Object.assign(window.__LB,{"20000": ["病机", "脉浮沉皆有力，示外感痰饮壅肺，气机壅滞，正邪交争。体丰气虚，痰饮素盛，薄受外感即喘，乃外寒引动伏饮，肺失宣降。脉浮主表邪，沉主里饮，有力为实，故主外感痰喘实证，治当解表化饮，小青龙加石膏汤主之。", ["浮", "沉", "实"]], "20001": ["治法", "脉象无力为气虚，虚而兼数则气阴两伤。喘状如前而脉无力，示正虚不能胜邪，故小青龙汤去麻黄之峻汗，加人参补气，石膏清热，杏仁降肺。脉虚兼数加知母，乃因数脉主热，虚数并见为气阴不足兼热，故佐知母滋阴清热。", ["虚", "数"]], "20002": ["治法", "脉虚而无力或兼数，主气阴两虚，虚热内扰。吸难呼易、苦上气，乃肾不纳气、肺失肃降。虚数之脉示正虚有热，故用滋阴清燥汤，滋阴润燥以复肺肾，使虚热退而喘自平。此脉不任发散，故避麻黄之属。", ["虚", "数"]], "20003": ["治法", "脉实而至数不数，示邪实而热未炽，故小青龙汤原方加生石膏清热。若脉数，则热象已显，数主热，故减麻黄之半以防助热，加石膏、知母以清泄里热。脉实为邪气盛，数则为热，此辨热之轻重以定麻黄用量。", ["实", "数"]], "20004": ["治法", "脉洪滑而浮，洪为热盛，滑主痰湿，浮示邪在表。舌苔白厚、胸中烦热，乃痰热壅肺兼表邪未解。洪滑而浮说明热痰郁于肺卫，故用寒解汤透表清里，服后汗出则表解热清，喘自愈。此脉非虚寒，故宜清透。", ["洪", "滑", "浮"]], "20005": ["治法", "脉象滑实，滑主痰湿，实主邪盛。舌苔白厚或微黄，示痰湿化热，壅阻肺胃。喘不甚剧而脉滑实，说明里热痰实为主，故用白虎汤清阳明气分热，少加薄荷叶以疏透。滑实之脉不虚，故可直清里热。", ["滑", "实"]], "20006": ["治法", "脉洪滑而实，洪为热盛，滑主痰，实为邪壅。喘而发热，舌苔白或兼黄，示痰热壅肺，阳明热盛。洪滑实之脉说明热痰内结，故用白虎汤清泄里热，加栝蒌仁化痰宽胸。此脉实热明显，非虚寒可拟。", ["洪", "滑", "实"]], "20007": ["治法", "脉象确有实热，至数兼数，数主热；重按无力，则示热盛而气阴已伤。喘而发热，脉数无力，为虚实夹杂之候。故用白虎加人参汤清热益气，再加川贝、苏子化痰降气。虚甚者以生山药代粳米，加强补脾益阴之力。", ["数", "虚"]], "20008": ["病机", "脉浮弱不堪重按，为胃气大虚、根本不能固摄之象。痰喘甚剧而脉反浮弱，是虚阳上浮、正气欲脱，故虽烦躁而脉不任按。用参、冬仍恐不胜药，正因脉虚不能胜药，后脉如水上浮麻，更见虚风内动、元气浮越之危。", ["浮", "弱", "虚"]], "20009": ["病机", "原文未出脉名，然述汗吐下伤胃气，胃气不能下行而反上逆，引动冲气上冲，肝气亦随之上逆，痰涎与气凝滞心下痞硬，噫气不除。此乃胃虚气逆、冲肝上冲、痰气交阻之病机，脉当见弦劲或虚浮，然原文未及。", []], "20010": ["病机", "脉浮而动数，浮主风，数主热，动主痛，数又主虚。此表未解而误下，动数变迟，膈内拒痛，客气动膈，短气躁烦，心中懊𢙐，阳气内陷，心下因硬，则为结胸。脉变迟者，实邪内结、气化不通之象，非热退也。", ["浮", "数", "动"]], "20011": ["病机", "脉浮热犹在表，数则为热，然阴分不虚者脉未必即数，今脉数故断为虚。误下后胸中大气虚，表热乘虚入里，与痰水凝结成结胸。脉变为迟者，非热变凉，乃脏腑有实在瘀积、阻塞气化流通，故脉恒现迟象，如大承气汤证亦脉迟。", ["浮", "数", "迟"]], "20012": ["治法", "甘遂性猛烈有毒，用治痰迷心窍之疯狂，须脉大实方敢轻投。脉大实为邪实壅盛、正气未衰之征，故可任峻下逐痰之品。若脉不实，则正虚不能胜药，反伤元气。此以脉大实为用药之凭据，非泛论病机。", ["大", "实"]], "20013": ["误治", "原文未出脉名，述后世畏大陷胸汤之峻，因提纲言数则为虚，恐虚不堪猛剂。然结胸脉数本为热实，数则为虚乃指阴分不虚者脉未必数，非谓结胸脉虚。此段辨误治之疑，明大陷胸丸可通变，非脉象主病之论。", []], "20014": ["主病", "脉浮滑者，浮主表阳未罢，滑主痰热内结。小结胸病正在心下，按之则痛，为表阳内陷与心下水饮互结为热痰，结聚未深，故脉浮滑而不沉实。此与大陷胸汤证之脉沉紧、心下硬满不可近者，轻重浅深自别。", ["浮", "滑"]], "20015": ["病机", "脉现滑象，知为热痰。心君之火炽盛，铄耗心下水饮，结为热痰，表阳又随风内陷，与痰互相胶漆，停滞心下为痞满，杜塞经络，按之作痛。若但有痰而不热，脉当现濡象，今滑故为热痰，用黄连、半夏、栝蒌清火涤痰。", ["滑"]], "20016": ["病机", "原文以“脉无滑热之象”排除痰饮化热之病机，说明此证但为痰饮痞结于心下，尚未郁而化热。脉不滑不数，故可治以荡胸汤，但需减轻药剂，因无热象则不宜过用寒凉攻下。", []], "20017": ["病机", "脉沉细欲无，沉主里，细主虚，欲无示阳气衰微。然此证四肢冰冷、痰声漉漉、呼吸窒碍，为寒实结胸，寒邪内闭，阳气不能外达，故脉沉细欲无，非纯虚也，乃寒实内结之象。", ["沉", "细"]], "20018": ["病机", "脉微细若无，不足四至，微为阳衰，细为阴盛，迟为寒。患者素患寒饮，严冬感寒，凉气上冲，昏仆息微，此寒实结胸，阴寒内盛，阳气式微，故脉微细若无而迟。", ["微", "细"]], "20019": ["病机", "脉关上浮，关候中焦，浮主阳热。心下痞按之濡，为无形邪热痞结心下，热郁气壅，故关上浮。此热痞之证，主以大黄黄连泻心汤泄热消痞。", ["浮"]], "20020": ["主病", "脉结代，心动悸，为气血亏虚，心失所养，脉道不充，故脉来中止。结代脉主心之气阴两虚，鼓动无力，脉行不畅，炙甘草汤益气滋阴、通阳复脉。", ["结", "代"]], "20021": ["病机", "原文详辨结脉“止无定数”与代脉“止有定数”。结脉偶阻于气血凝滞，病轻；代脉为脏腑之气内亏，不能外达，病重。心动悸为结代脉之所由来，总由气血不续、脉道不利所致。", ["结", "代"]], "20022": ["治法", "此段为炙甘草汤（复脉汤）煎服法，以清酒和水久煮，纳胶烊化，温服日三。酒性温热，久煮变地黄之凉为温，旨在温补肾脏、复脉通阳，体现治法之深意。", []], "20023": ["病机", "脉象结代而微弱无力，非独心血亏少，实因肾气不能上升与心气相济。原文强调“脉之跳动在心，而脉之所以跳动有力者，实赖肾气上升与心气相济”，故炙甘草汤重用生地黄温补肾气，以复脉之根本。", ["结", "代", "微", "弱"]], "20024": ["治法", "原文讨论炙甘草汤中人参用量，指出人参“助心脉跳动”，为方中要药，但用量恐有误，主张加倍。此处“脉跳动”非具体脉象，而是指心脉搏动之病机，涉及心气不足致脉动无力，故以人参补益心气。分析紧扣“助心脉跳动”及分量调整，说明该段属治法范畴，非直接论脉象主病。", []], "20025": ["病机", "脉象结代而兼阳明实热，单用炙甘草汤难效，因实热内结致脉道不利而现代象。案中脉洪而不实、现有代象，洪为热盛，不实为热未成实，代因热结气阻。治以白虎加人参汤清透实热，热退则脉已不代，证明代脉由实热壅遏所致，非纯虚之候。", ["洪", "代"]], "20026": ["病机", "脉象洪滑甚实，或七八动一止，或十余动一止，止在左部。洪滑甚实主阳明实热，结脉因肝气不舒、气机阻隔所致。原文明言“左脉之结乃肝气之不舒也”，说明结脉在此非虚，乃实热兼肝郁气滞，故治以白虎加人参汤加莱菔子开通气机，结脉得除。", ["洪", "滑", "结"]], "20027": ["病机", "脉洪实异常，至数不数，惟右部有止时，止无定数，乃结脉。洪实主外感实热，结因实热壅滞、气机不畅。下血日久却脉洪实，知非虚证，乃外感大实之热迫血妄行。投白虎加人参汤后脉洪实大减而结益甚，说明结脉随实热减轻而显露气分阻隔之本质。", ["洪", "实", "结"]], "20028": ["病机", "脉非结代而现雀啄之象，脉搏近六至，重按有力，十余动或二十余动后连二三啄。雀啄为气分阻隔、脉道不畅之象，非止脉。患者因账目被责，情志不遂，气息不顺，致脉气受阻而现雀啄。原文指出“气分有所阻隔”，说明雀啄脉在此主气机郁滞，与情志因素相关。", ["数", "雀啄"]], "20029": ["病机", "本段未识脉名，论述外感之热循三焦脂膜下降结于膀胱，热蒸胞室致血蓄不行，热由任脉上窜扰乱神明而如狂。病机为热结膀胱、血蓄下焦、神明被扰。若血蓄自下则热随血去可愈；若蓄极不下，需攻下，但表未解者应先解表。全段重在阐发蓄血发狂之病机与治法次第。", []], "20030": ["病机", "太阳病桂枝证误下，利遂不止，脉促者表未解也。促脉在此主表邪未解、热邪内陷，正气抗邪外出而脉行急促。喘而汗出为热迫肺肠。原文引《伤寒论》条文，说明促脉主表未解兼里热，故用葛根黄芩黄连汤解表清里。促脉非止脉，乃脉行急迫之象。", ["促"]], "20031": ["病机", "原文辨析促脉与结、代之不同，指出促脉多见于速脉之中，非止脉，乃脉动加速、脉管拥挤偶现龃龉之象，如奔驰中遇不平而改步武。促脉因外感之热内陷，促其跳动加速所致。故用芩、连化下陷之热，葛根透表，使表里俱清。此段明促脉主热陷、表里同病之病机。", ["促", "数"]], "20032": ["主病", "脉浮滑，浮为表热未解，滑为里热已盛，热邪充斥表里，故原文称“表有热里有寒”，实指伤寒热邪入里而表未尽。浮滑并见，说明热势弥漫，非单纯表证，故以白虎汤清泄里热、透达表邪，为阳明热盛兼表之脉证。", ["浮", "滑"]], "20033": ["病机", "原文以“浮而且滑”立论，滑为热入里，浮则热未尽入里，故谓“半在阳明之府，半在阳明之经”。浮滑并见，说明热邪未全入里，表里俱有热象，故曰“表有热里有寒”。文中辨“寒”非表寒，乃伤寒热邪已入里之意，脉滑亦主阳明热实、气血素充。", ["浮", "滑"]], "20034": ["主病", "脉滑而厥，滑主里有热，厥为热深厥深、阳郁不达四肢所致。原文明言“里有热也”，说明此厥非寒厥，乃阳明热盛、热邪郁遏阳气不能外达。脉滑为热实之征，故以白虎汤清里热，热清则厥自回，属真热假寒之候。", ["滑"]], "20035": ["病机", "原文谓“脉滑者阳明之热传入厥阴也”，滑主热实，热郁肝中，肝失疏泄，故“热深厥亦深”，四肢厥逆。脉滑而厥，说明热邪由阳明传入厥阴，郁遏阳气不达四末，非阳虚寒厥。治以白虎汤，热消则肝疏泄复常，厥逆自回。", ["滑"]], "20036": ["治法", "原文列举白虎汤三见：太阳篇“脉浮滑”、厥阴篇“脉滑而厥”，皆未言自汗。作者借此辨明不可因无自汗而不敢用白虎汤，强调“邪愈深入则愈险”，当由表入里、阳明渐实之际急投大剂白虎汤。浮滑示热连表，滑而厥示热郁厥阴，均当据脉施治，不可拘泥自汗一症。", ["浮", "滑"]], "20037": ["病机", "原文由“脉浮而滑”及“脉滑而厥”推知白虎汤正脉“当为洪滑无疑”。洪滑为阳明府热已实之正脉，放胆投白虎汤；若脉浮滑，则病犹连表，加薄荷、连翘、蝉蜕以透表；若脉滑而厥，则厥阴肝气不舒，加白茅根煎药。此段以脉象洪滑、浮滑、滑而厥分判热之深浅与兼夹。", ["洪", "滑", "浮"]], "20038": ["误治", "吴鞠通原文列白虎汤禁忌：脉浮弦而细者不可与，脉沉者不可与。浮弦而细，为阴虚阳浮或寒邪在表，非阳明实热；脉沉，为热未入府或阳虚，亦非白虎所宜。此段以脉象辨白虎汤之禁，说明脉不洪滑而见浮弦细或沉，误投白虎则伤阳损正，属误治之戒。", ["浮", "弦", "细", "沉"]], "20039": ["其他", "原文按语论石膏微寒之性，举治春温阳明府热已实、心下胀满异常，及少腹肿疼等案，说明石膏能推荡实热。所涉脉象“沉洪有力”，沉主里，洪主热盛，有力为实，示阳明府热结实之脉。此段以临证验案证石膏主治，非专论脉，故归其他，脉象沉洪有力为里热实之征。", ["沉", "洪"]], "20040": ["病机", "脉洪滑而浮，洪为热盛，滑主痰热内蕴，浮示热势趋表。此案温病误以温药发汗，热邪益炽，脉象反映阳明实热兼表热未解。洪滑为里热炽盛之征，浮为热邪有外透之势，故投白虎汤加连翘、蝉蜕透表清热，服后得凉汗而愈，说明脉象与实热病机相应。", ["洪", "滑", "浮"]], "20041": ["治法", "脉有数象者，数主热盛，伏气化热之病，热邪内炽故脉数。文中强调伏气化热当治以白虎汤，脉数者加人参以益气生津，因热盛易伤气阴。医者不识此治法，久不瘥，说明脉数反映热盛伤津之病机，治法当清热益气，白虎加人参汤主之。", ["数"]], "20042": ["病机", "脉弦长有力，重按甚实，弦主气机郁滞，长主邪实有余，有力为实热内结。此伏气化热，热邪阻塞三焦升降之气化，故大小便不利、腹满发热、热上逆而呕吐。脉象反映实热内结、气机壅滞之病机，非外感表证，故宜大剂白虎汤清解里热。", ["弦", "长", "有", "力"]], "20043": ["主病", "脉洪大者，洪为热盛，大为邪实，此服桂枝汤大汗出后，津液大伤，热邪转盛，故大烦渴不解。洪大脉主阳明热盛、津气两伤之病机，热盛则脉洪，津伤则渴，故以白虎加人参汤清热益气生津，脉象与烦渴症候相应。", ["洪", "大"]], "20044": ["病机", "脉洪大异常，洪大主热盛，异常强调热势鸱张。此因服桂枝汤汗出如水流漓，大伤津液，热邪愈炽，故大烦大渴、脉洪大异常。脉象反映热盛津伤之病机，热盛故脉洪大，津伤故烦渴，以白虎汤解热加人参复津液，脉证相应。", ["洪", "大"]], "20045": ["治法", "脉浮，浮主表，伤寒脉浮发热无汗，表不解者不可与白虎汤，因表邪未解，过早清里易引邪内陷。渴欲饮水无表证者，方可用白虎加人参汤。脉浮在此说明表证存在，与无汗、发热相应，提示治法当先解表，不可误用白虎汤清里。", ["浮"]], "20046": ["病机", "脉象但浮，浮主表，虽发热而热在表，故不可与白虎汤。白虎汤证脉当浮滑，滑主里有热，浮为热连于表。此节脉但浮，说明无里热之滑象，表邪未解，与无汗、表不解相应，故不可清里。文中辨析浮脉与滑脉之别，以明白虎汤使用禁忌。", ["浮", "滑"]], "20047": ["误治", "脉象有力而兼硬，有力为实，硬为热盛津伤、脉道失柔，非滑脉之流利。此伤寒热入阳明，脉硬即非滑，宜白虎加人参汤。误投大剂白虎汤后脉搏转数，数主热盛，谵语更甚，说明津伤热炽加重。脉硬转数反映热盛津亏之病机，故改投白虎加人参汤而愈。", ["有", "力", "硬", "数"]], "20048": ["病机", "脉虽有力而数逾六至，为阳明府实证热盛伤阴之象。脉数主热，有力为实，数逾六至则阴分已伤。前医加玄参、沙参滋阴不效，因热邪未清，阴液难复。张锡纯断为白虎加人参汤证，以人参益气生津，石膏清阳明实热，热退则脉数自减。此脉数非独阴分虚损，实由热盛耗阴，故清热与益气滋阴并施而愈。", ["数", "有力"]], "20049": ["治法", "原文未明言脉象，但述‘脉过六至者’用生怀山药代粳米，取其滋阴补肾、浓郁汁浆调胃；阳明热实兼下痢者，以生杭芍代知母，清肝热除里急后重；妇人产后寒温实热，亦以山药代粳米，加玄参代知母，因山药补产后肾虚，玄参主产乳余疾。此皆因证制宜、通变古方之法，紧扣脉过六至及兼症而设。", []], "20050": ["病机", "脉数逾六至，左部弦细而浮，不任重按，右部亦弦细而重诊似有力。数主热盛，弦细为阴伤风动，浮而不任重按乃真阴失守、元气将脱之兆。久热灼耗气血，肝风内动，故见目睛上窜、筋惕肉𥆧、周身颤动。此热盛阴亏、气血两虚、肝风内动之候，急宜白虎加人参汤辅以滋阴固气。", ["数", "弦", "细", "浮"]], "20051": ["预后", "前案服白虎加人参汤变方后，目睛不上窜，身体安稳，嗳声止，气息匀，精神较前明了，而仍不能言，大便未通，肌肤犹热。原文虽未直言脉象，然以‘脉数已减’推之，热势已挫，元气渐固。此方重加山萸肉收敛肝脏疏泄，防元气上脱，故诸症递减，预后转佳，惟余邪未净，仍须续治。", ["数"]], "20052": ["病机", "服两日热全退，脉热象已静且微弱，继则微弱益甚，右部关前之脉几至不见。热退而脉转微弱，乃邪去正虚，胸中大气下陷之象。大气不升，不能上达舌本，故仍不能言；无力推送，故大便不通。右关前几不见，尤显中气陷下。治当升补胸中大气，使之上达舌本，则言自复。", ["微", "弱"]], "20053": ["主病", "阳明病脉迟，虽汗出不恶寒，身重短气腹满而喘，有潮热，手足濈然汗出，大便已硬，此里实已成，可攻里，大承气汤主之。脉迟非寒，乃肠中阻塞、脉道不利所致；迟而有力，正是燥屎内结、腑气不通之征。若汗多微发热恶寒，热不潮，则表未解，不可与承气；腹大满不通，可与小承气微和胃气。", ["迟"]], "20054": ["病机", "阳明病脉迟为当下之明征。此迟非迟缓之象，乃肠中阻塞、脉道不利，蓄极而通，迟而突出；因阳明火盛，脉原有力，阻其脉力使之迟，正激其跳跃之势。故脉迟而有力者，可下之。若脉数，下后恒不解；脉不数，无虑下后不解。此辨脉迟之机理，明阳明腑实可下之征。", ["迟", "数"]], "20055": ["治法", "阳明病当下，脉迟者固可下，脉不迟而亦不数者亦可下；惟脉数及六至则不可下，强下之病必不解或加剧。因脉数六至为热盛阴伤，下之更伤津液。张锡纯创变通下法，以白虎加人参汤送服石膏末，名白虎承气汤，清热生津兼通腑实，使热退津复而便自通，较峻下为稳妥。", ["迟", "数"]], "20056": ["治法", "脉虽数而洪滑有力，数主热盛，洪滑为阳明燥热内结、正气未衰之象。热邪炽盛，故脉数；气血涌盛，故洪滑有力。此脉提示热实可下，但正气尚足，故用白虎汤时可不加党参，专以清热通下为治。", ["数", "洪", "滑"]], "20057": ["治法", "脉象数者，主热邪内盛，燥结于肠。数脉为热，热盛则大便燥结难下。文中以大剂白虎汤或白虎加人参汤通下，因热盛耗津，故需重用生石膏清热，佐以玄明粉软坚。此脉数示热实，治当清热通便。", ["数"]], "20058": ["病机", "原文以“脉迟”开端，言脉象虽热而至数不加数，非迟于平脉，乃阴分充足之脉。若脉不迟而数，则阴虚不胜燥热；脉纵不数而热实脉虚，亦不可妄投承气。此论脉迟与数、虚之辨，示阳明病脉象古今不同，治当随时制宜。", ["迟", "数", "虚"]], "20059": ["病机", "大承气汤证原宜脉迟，若脉不迟而洪实有力亦可用；惟脉转数者，若遽投承气，脉无力者下后虚脱，有力者降后不解。数脉主热盛阴伤，故必先治其数，再通大便。此段辨脉迟、洪实、数之异，明承气汤之宜忌。", ["迟", "洪", "实", "数"]], "20060": ["病机", "脉数逾六至，心中烦热，为外感热盛、燥结内停之象。脉象虽数而重按甚实，示热实内结而正气未虚。故先投白虎加人参汤清热，待壮热消、脉不数，再以芒硝蜂蜜通下。此脉数而实，主热实可下，然须先清其热。", ["数", "实"]], "20061": ["治法", "脉亦数逾六至且不任重按，为热盛而气阴不足之象。数脉主热，不任重按示虚。故用白虎加人参汤以生地、山药代知母、粳米，清热兼养阴。服后脉数见缓，示热退阴复，大便自通。此以脉数转缓为热退之征，主热盛阴伤之病机。", ["数", "缓"]], "20062": ["病机", "脉弦长有力，无论见于何部，皆主肝火炽盛。因大怒之余感冒伤寒，热传阳明，肝火与燥热相合，故脉弦长有力。此脉主肝火炽盛，不受承气之降，故于大承气汤中加生杭芍、生赭石以平肝降逆，使药能受而病愈。", ["弦", "长", "有", "力"]], "20063": ["病机", "脉弱而火则甚实，素伤烟色，气虚脉弱，然外感实热内结，故虽脉弱而火实。弱脉主气虚，然不可仅凭脉弱断为虚寒，当合症辨之。此脉弱而火实，主气虚热结之病机，故用调胃承气汤加参、赭石、天冬，攻补兼施而愈。", ["弱"]], "20064": ["病机", "左部沉弦有力，沉主里、弦主肝，有力为实，说明肝经气郁火盛。怒动肝火兼伤寒，热结大肠则便燥，肝火横逆则胁疼。用柴胡、生麦芽疏肝达郁，气机得通，故胁疼止而便通胀消。", ["沉", "弦"]], "20065": ["兼症", "妊妇伤寒八九日，脉象洪实，洪为热盛、实为邪结，故心中热而烦躁，脐上似有结粪、按之微疼。此内热与燥屎相结，先以白虎加人参汤清之，热减而肿疼反增，知非降下不可，然须避芒硝、慎赭石。", ["洪", "实"]], "20066": ["病机", "此段论黄疸病机，以油之寒热湿郁分阴阳黄：液虚血燥则热甚为阳黄，油湿血热交蒸则小便不利、身黄如橘，油寒膜湿郁血为热则寒湿为阴黄。虽未出脉，然辨黄之阴阳寒热，正为凭脉施治立据，示人于寒湿中求治法。", []], "20067": ["病机", "左部弦而无力，右部濡而无力。弦为肝脉，无力则肝胆阳不振；濡为湿脉，右部无力则脾胃虚寒。土虚现本色而发黄，胆气不宣、胆汁妄行溢于血分，故黄似黯淡而不甚黯淡。此寒湿发黄之病机，非湿热阳黄可比。", ["弦", "濡"]], "20068": ["病机", "左部弦硬，右部沉濡。弦硬为肝胆木郁化热，沉濡为脾胃湿郁生寒。久受雾露潮湿，湿郁脾胃则寒而食不化，湿郁肝胆则热而胆管肿胀闭塞，胆汁妄行溢血而身黄。寒热错杂，黄之根源在湿郁。", ["弦", "硬", "沉", "濡"]], "20069": ["主病", "脉浮发热，渴欲饮水，小便不利，为阳明热盛而太阳府气不化。浮脉主表，亦主太阳之府；热入阳明不得由太阳分消，上逆累肺故渴，水热互结故小便不利。猪苓汤仍从太阳之府分消其热，使水热下行。", ["浮"]], "20070": ["病机", "此释脉浮之由：病入阳明而连太阳之府，太阳经脉浮，府有实热亦脉浮。府热蕴结则小便不利，热不得由府分消，上逆累肺而渴欲饮水。故用猪苓汤仍从太阳之府分消其热，脉浮为府热外现之象。", ["浮"]], "20071": ["主病", "脉浮而迟，浮为表热，迟为里寒，表热里寒并见，故下利清谷。浮脉非纯表，迟脉主脏寒，此内真寒而外假热之候，四逆汤温里回阳，使里寒去而浮热自解，下利可止。", ["浮", "迟"]], "20072": ["主病", "脉弦细为少阳主脉。弦属肝胆气郁，细为正气略伤、邪入半表半里之象。原文以“脉弦细，头痛发热”断属少阳，正因少阳居表里之间，脉不浮不沉而见弦细。既属少阳，则不可发汗，误汗伤津助热，热归阳明则谵语、烦而悸，故以“胃和则愈，胃不和”点明转归。", ["弦", "细"]], "20073": ["病机", "原文承“脉虽弦细”而申明“重按必然甚实”，指出弦细为少阳本脉，重按实则为阳明里热未净，故断为少阳阳明合病。热有一半入府，非尽传少阳，故以胃和、胃不和为紧要。治用柴胡汤减半加石膏、知母，清少阳兼清胃热，正合“胃和则愈”之旨，并申汗吐下三禁。", ["弦", "细", "实"]], "20074": ["兼症", "案中“脉象弦细，重按有力”，弦细应少阳，重按有力说明热邪偏实。症见寒热往来、头疼发热、心烦喜呕，皆少阳提纲证。故用小柴胡汤加减，柴胡减半、加生石膏，既解少阳之邪，又清偏盛之热，体现弦细而有力者当兼顾里热，不可纯作虚论。", ["弦", "细"]], "20075": ["病机", "脉象沉弦，沉为病在里，弦为少阳木气不舒。症见寒热往来无定时、心中发热、呕吐痰涎连连不竭，原文断为“少阳病而连太阴”。少阳去路为太阴，太阴湿土与少阳相并，湿热化合而生黏涎，故脉沉弦。治以小柴胡加石膏、茯苓，清少阳之热兼利太阴之湿。", ["沉", "弦"]], "20076": ["病机", "脉沉弦有力，沉主里、弦主少阳，有力为邪实内陷。妇人经期感邪，月信断后热入血室，症见寒热往来、热重寒轻、夜则讝语，与“昼日明了，暮则讝语”相合。邪陷血室故脉沉弦有力，治以小柴胡减柴胡加黄芪、川芎升举下陷，加石膏清下陷之热。", ["沉", "弦", "实"]], "20077": ["主病", "脉象弦长有力，弦为少阳，长为邪盛气实，有力示热结偏重。症见寒热往来、胸中满闷烦躁甚剧、时作呕吐，原文断为“大柴胡汤证”。少阳枢机不利、里热壅盛，故脉弦长有力。治用大柴胡加减，去大黄、枳实，加石膏、竹茹，重在和解少阳兼清里热。", ["弦", "长", "实"]], "20078": ["病机", "原文仅言“脉有数象”，数为热盛之征。患者禀赋素弱，初夏感邪，前医误用发表，病近一旬未愈，诊为白虎汤证。数脉说明里热已盛，虽未见汗下、不渴，仍当清阳明之热。因体弱又劳心，故用白虎汤原方酌减石膏，示数脉主热、当以清热为要。", ["数"]], "20079": ["主病", "脉浮大为三阳合病之脉。浮属太阳，大属阳明，关上候少阳，原文“上关上”说明邪盛于三阳。但欲眠睡为热盛神昏，目合则汗为阳热迫津。浮大之脉不专一经，故断三阳合病，主以清热和解，不可单治一经，体现脉象合参以定病位之旨。", ["浮", "大"]], "20080": ["病机", "左右脉皆弦，右脉尤弦而有力、重按甚实，关前且浮。弦主少阳，右脉重按实主阳明，关前浮甚主太阳，故断为三阳合病。其无寒热往来者，因少阳与太阳、阳明相并，邪无出入之机。脉象反映三阳经气同病，邪盛于表里之间，故用石膏、玄参、连翘等清透并施而愈。", ["弦", "浮", "实"]], "20081": ["病机", "脉左右皆弦细而浮，数逾六至，重按即无。弦细浮数主少阳之邪未解而还太阳，数而重按无根为正气已虚、邪热浮越。结合肢体惕动、两目直视、潮热属少阳，精神昏愦、讝语属阳明，脉浮甚为自少阳还太阳，故谓三阳合病。脉数无根提示正虚邪陷，病势深重。", ["弦", "细", "浮", "数"]], "20082": ["预后", "前案脉数逾六至、重按无根，服滋阴填精之剂两日后，脉不足六至，精神亦见明了。脉由数疾无根转为和缓，是阴精渐复、虚热退舍之象，故为病退向愈之兆。虽大便未行，乃阴液得充、肠腑未燥，故去萸肉加连翘以清余热，服后得汗而病若失。此段以脉息改善判断预后。", []], "20083": ["病机", "原文辨太阴中风欲愈之脉：若阳大而阴滑，则邪盛内陷；今阳不大而微，阴涩而见长，知微涩非正气虚，乃邪不盛，长为正气足。微涩示邪衰，长脉示正复，故为欲愈。此以脉之微涩与长并见，判断邪退正复之病机，与阳大阴滑之邪盛内陷形成对照。", ["大", "滑", "微", "涩"]], "20084": ["病机", "脉大而濡，两尺重按颇实。大濡主太阴伏气化热、邪热弥漫而正气受困，两尺重按实示热邪深伏下焦。腹中胀满为太阴受病，脾主四肢，热邪上行故两手肿疼，烦躁亦热邪所致。此脉与《伤寒论》太阴中风阳微阴涩而长之欲愈脉相反，故不得径言欲愈，须细商治法。", ["大", "濡", "实"]], "20085": ["治法", "太阴病脉浮者，为病机外越，邪有外出之势，故可因势利导，用桂枝汤发汗。脉浮说明邪在表分、正气尚能抗邪外达，非太阴虚寒之本脉，故从太阳表解。此条以脉浮定治法，示太阴病见浮脉者可发汗，宜桂枝汤。", ["浮"]], "20086": ["治法", "脉浮为太阴病机外越，可因势导之，服桂枝汤发汗。若脉浮而有力，为有浮热之象，过用桂枝恐致失血，故减桂枝之半加连翘，以其凉而宣散，遇浮而有力之脉恒能出汗。若兼太阴腹满，加生莱菔子消胀助汗。此段以脉之浮与浮而有力辨治法加减。", ["浮"]], "20087": ["误治", "太阳病误下，脾土为降下所伤，肝木乘虚侮脾，致腹满时痛，乃肝脾相龃龉。桂枝汤平肝和脾，辅以芍药、甘草、姜、枣柔肝扶脾，去啜粥即为治太阴病之正药。腹满时痛而倍芍药者，以芍药善治腹痛，与甘草等分即为甘草芍药汤。此段论误下致变及救逆之法。", []], "20088": ["主病", "少阴病提纲以“脉微细”立论。微为阳气虚衰，细为阴血不足，心肾水火交济失常，气血不能充盈鼓动血脉，故脉道细窄而搏动无力。此脉主少阴心肾虚衰之病机，与“但欲寐”相应——阳气不振、精神倦怠，故但欲寐。脉证合参，揭示少阴虚寒本质。", ["微", "细"]], "20089": ["病机", "原文反复申明“脉皆微细”“微细无力”，从心肾水火根源立论：心肾相济则气化壮旺，相离则气化衰惫。少阴受邪，肾气被遏不能上升济心，故无论病凉病热脉皆微细无力。又因心肾不交、气化衰惫，精神倦懒而“但欲寐”，且肾气不能吸引心阳下潜，虽闭目而不能成寐。", ["微", "细"]], "20090": ["预后", "少阴病脉紧为阴寒内盛，至七八日自下利后“脉暴微”，紧象骤去，是阴寒随下利外泄、元阳来复之象；更见“手足反温”，说明阳气已回，故断为“欲解”。虽有心烦、下利，亦必自愈。脉由紧转微、由有力转和缓，反映寒去阳复，属向愈之预后。", ["紧", "微"]], "20091": ["病机", "原文谓“脉现紧象”，紧为寒，乃外寒入少阴与内水相并、阻遏元阳，阴盛阳衰逼阳不得宣布所致。至七八日命门火蓄极暴发，迫阴寒下利外出，“脉之紧者亦暴微”，是由弦紧有力转为和缓，非真衰微。紧去、手足反温为元阳已回之兆，心烦乃相火暴发之象，故治少阴寒病以护元阳为主。", ["紧", "微"]], "20092": ["病机", "此段未出具体脉名，从“阴证见阳脉者生，阴病见阳证亦为易愈”立论，强调治少阴伤寒以阳为主。又以“恶寒而蜷”之蜷字推究阴寒在内：阴寒则屈曲身体，是伸督脉之阳以抑阴自救；阳热则直腰张胸，是伸任脉之阴以济阳。借身体姿态辨阴寒病机，与脉之阳回与否互为印证。", []], "20093": ["治法", "少阴病吐利而“手足不逆冷，反发热者不死”，是阳气尚存、未至厥逆。然“脉不至”示阳气暴脱、脉道不通，故急“灸少阴七壮”以温通阳气、接续脉气。此段未出具体脉象，主旨在于脉不至时以灸法急救回阳，属少阴病阳衰脉绝的治法。", []], "20094": ["治法", "此段承上条脉不至而申述灸法。原文指出太谿穴在“跟骨上动脉中”，即取动脉搏动处定穴。太谿、复溜同为少阴生脉之源，先灸太谿，脉仍不应再灸复溜，且宜两腿同时灸，以温通少阴经气、促脉复生。所述“动脉”为定位标志，非论病之脉象，主旨属灸治取穴之法。", ["动"]], "20095": ["主病", "少阴病“始得之，反发热脉沉”，发热为太阳表邪未解，脉沉为少阴阳虚、寒邪在里，属太少两感之证。脉沉揭示阳气不足、不能鼓动脉气外达，故虽发热而脉不浮反沉。治以麻黄附子细辛汤，温经助阳、解表散寒，此脉沉正是辨少阴兼表的眼目。", ["沉"]], "20096": ["病机", "脉不浮而沉，因太阳寒邪直透少阴，少阴已为寒凉所伤，故脉沉；少阴之脉微细，微细近于沉，反映里寒虚象。外表虽有发热，乃恶寒中之发热，非壮热，故脉不浮。此脉主太阳少阴合病，治以麻黄附子细辛汤温里解表。", ["沉", "微", "细"]], "20097": ["治法", "凡宜发汗之病脉皆浮，此独脉沉，说明病机非单纯表证，而兼少阴里寒，故需细辛辅麻黄附子以发汗。脉沉为少阴受寒，阳气不能外达，用细辛辛温香窜，助麻黄透表，助附子温里，使寒从汗解。", ["浮", "沉"]], "20098": ["兼症", "脉微细若无，为少阴暴虚之象。患者因恣食西瓜、当窗酣睡受寒，梦中遗精，致少阴阳气骤虚，故周身寒凉抖战、腹中隐痛加剧。脉微细若无反映阳气衰微、阴寒内盛，故用麻黄附子细辛汤加熟地、山药、萸肉等温补少阴。", ["微", "细"]], "20099": ["病机", "少阴病提纲脉微细，若病发于心而心热生烦，脉必现浮洪之象；今心虽有热而脉仍微细，说明病源不在心而在肾，乃肾病累及于心。脉微细为少阴阳虚本质，浮洪为心火独亢之假象，此处以脉定病位，强调少阴病脉微细的辨证意义。", ["微", "细", "浮", "洪"]], "20100": ["其他", "本段未涉及脉象，专论元阳与气海。人身有膈上后天宗气之海与脐下先天元气之海，元阳以元气为体质，温暖全身，本于先天，为君火，命门相火辅佐。下焦气海形质为脂膜及胰子团结中空。此段为理论阐述，与脉象无关。", []], "20101": ["主病", "少阴病身体痛、手足寒、骨节痛，脉沉者，主附子汤证。脉沉为少阴阳虚，寒湿内盛，阳气不能温煦四肢，故手足寒；寒湿痹阻筋骨，故身体骨节痛。脉沉反映里虚寒，治以附子汤温经散寒、除湿止痛。", ["沉"]], "20102": ["主病", "脉微弱而沉，左三部几不见，为少阴寒痢之脉。患者受潮湿，下痢脓血渐变紫色如烂炙，杂脂膜，腹中切痛，饮食不化，上有浮热，下痢无度。脉微弱沉反映阳气衰微、寒湿内盛，故断为寒痢，肠中脂膜腐败。", ["微", "弱", "沉"]], "20103": ["病机", "脉微弱而沉，少阴之脉也。下痢如烂炙兼脂膜，较下脓血尤甚，为少阴阳虚寒盛、肠中脂膜腐败。病危至极，非桃花汤原方所能胜任，故变通以硫黄代干姜，山药、熟地、龙眼代石脂，仍本桃花汤温涩固下之义，兼滋阴固脱。", ["微", "弱", "沉"]], "20104": ["病机", "脉弦迟细弱，弦主痛，迟主寒，细弱主虚。患者下焦疼甚且凉甚，小便因凉而凝滞不通，此脉象反映下焦虚寒、气化不利之病机。方用温阳散寒之品而愈，证明脉症相符。", ["弦", "迟", "细", "弱"]], "20105": ["病机", "原文未识脉名，论述赤石脂治肠澼下脓血之理。其性温涩，能温养脾胃、流通气血之瘀滞；佐干姜祛寒开瘀，粳米和脾胃利小便。此证气血因寒而瘀，化为脓血，故脉当见沉迟涩之类，然原文未及。", []], "20106": ["预后", "少阴病下利脉微，为阳衰阴盛之象，与白通汤温阳散寒。若利不止、厥逆无脉、干呕烦，则阳衰更甚，加猪胆汁、人尿引阳入阴。服汤后脉暴出者，是残阳外脱，故死；脉微续者，阳气渐复，故生。", ["微"]], "20107": ["病机", "原文未识脉名，阐述白通加猪胆汁汤中人尿、猪胆汁之作用。人尿含脏腑生气，猪胆汁为少阳相火所寄生，能以后天助先天。当元阳衰微、命门相火将绝时，用此二味引阳入阴，从治之法，以救垂绝之阳。", []], "20108": ["预后", "脉暴出者，是将脱之脉象已现，阴阳离决，故为不治。然作者经验，重用山萸肉大剂煎服，能收敛元气、固脱救逆，使暴脱之证可愈。此段论脉暴出之预后及救脱治法，强调山萸肉救脱之功。", ["暴"]], "20109": ["其他", "此段仅为少阴病通脉四逆汤证之标题，未涉及具体脉象与病机分析，故脉象要素为空，主旨归为其他。", []], "20110": ["病机", "少阴病下利清谷、手足厥逆、脉微欲绝，为里寒外热、阴盛格阳之证。脉微欲绝反映阳气衰微，不能鼓动血脉；身反不恶寒、面赤色为虚阳外越。通脉四逆汤急温回阳，以通脉救逆。", ["微"]], "20111": ["治法", "此段为通脉四逆汤方药组成，未涉及脉象与病机分析，故脉象要素为空，主旨归为治法（方药）。", []], "20112": ["预后", "原文述服药后“其脉即渐而出者愈”，并强调非“暴出者之自无而忽有、既有而仍无”。脉渐出是阳气渐复、由弱转强之象，故主愈；暴出则属虚阳外越，如灯火回焰，主危。此段以脉之渐出与暴出辨预后，紧扣“利止脉不出”等语，示阳气来复之机。", []], "20113": ["病机", "原文言“寒盛脉闭”，故用通脉四逆汤倍干姜以“开凝寒以通脉”。面赤乃“阴寒在下，逼阳上浮”之戴阳证，加葱通上下之气，使阳归宅。脉闭由寒盛所致，非脉象本身，故脉象要素不取。此段主述寒盛阳浮、脉道闭阻之病机及治法。", []], "20114": ["病机", "奇恒痢脉“缓小迟涩”，原文谓“阳气偏盛，阴气受伤，是以脉小迟涩”，又谓与少阴病之“脉微细者同”。缓小迟涩示阳亢伤阴、脉道不利，故主急下泻阳养阴。此脉与咽干喉塞、心下痛、口中干燥相应，属少阴下利范围。", ["缓", "小", "迟", "涩"]], "20115": ["主病", "少阴病下利脉“微涩”，微为阳气衰微，涩为阴血不足兼气滞，故见呕而汗出、数更衣而反少（虚坐努责）。此脉主少阴下利之阴阳两虚、阳气下陷，当温其上而灸之，以升阳举陷。原文紧扣“脉微涩”“当温其上，灸之”。", ["微", "涩"]], "20116": ["病机", "“伤寒脉微而厥”，微为阳气衰微，厥为阴阳气不相顺接。原文辨脏厥与蛔厥：脏厥者肤冷、躁无暂安时，为纯阴无阳；蛔厥者静而时烦、吐蛔，为脏寒蛔扰。脉微主阳气虚衰，故见厥逆，与脏厥、蛔厥之寒证相应。", ["微"]], "20117": ["病机", "脉“微细”主阳衰阴盛，“重按又似弦长”为厥阴肝木亢盛之象。四肢凉、肤冷为阳郁不达，心中及下利发热为热郁于内，断为厥阴温病（厥阴伤寒）。此脉示寒热错杂、厥阴枢机不利，与吐泻并作、内热外寒之症相应。", ["微", "细", "弦", "长"]], "20118": ["主病", "“脉滑而厥”，滑主里有热，厥为热邪深伏、阳气不达四末，故原文断为“里有热”，主白虎汤证。此脉与厥逆并见，是热深厥深之象，非阳虚寒厥。紧扣“脉滑而厥者，里有热”，说明滑脉主热、厥由热郁。", ["滑"]], "20119": ["病机", "原文对比太阳篇白虎汤证“脉浮滑是表里皆有热”，此节“脉滑而厥，是里有热表有寒”，即热深厥深。浮滑示热盛于表里，滑而厥示热郁于里、阳不外达。故治以白虎汤清里热，或先以茅根通阳，使厥回身热。", ["浮", "滑"]], "20120": ["主病", "脉细欲绝，细为阴血虚少，脉道充盈不足，欲绝则血虚已甚、脉道几近空虚。血虚寒凝，四肢失于温养，故手足厥寒。此非阳气衰微之微脉，乃血虚寒厥之细脉，故以当归四逆汤养血通脉、温经散寒；内有久寒者加吴茱萸生姜，温中散寒之力更专。", ["细"]], "20121": ["病机", "沈氏辨析细与微之别：微者薄也，属阳气虚，卫外之气怯薄；细者小也，属阴血虚，荣行脉中而实其中者少，故脉体细小。细未必薄，薄未必小，二者阴阳各异。少阴病脉微欲绝用通脉四逆回阳，此脉细欲绝用当归四逆补血，正说明细主血虚、微主阳虚，不可混释。", ["细", "微"]], "20122": ["病机", "厥阴血寒郁于脏，本应有弦凝之征，弦主寒凝气郁；今反见脉细欲绝，可知少阴经气来源先虚，又受脏寒之感，虚寒转甚，故细而欲绝。治以当归四逆汤温肝通郁，桂枝、白芍疏浚经气之源，细辛、通草畅达经气之流，内有凝寒则加吴萸、生姜温经通气。", ["弦", "细"]], "20123": ["病机", "左脉弦而有力，弦属厥阴肝木，有力为实；右脉洪而有力，洪属阳明热盛。两脉合参，断为阳明、厥阴合并病。阳明府热故周身皆热、心中热渴，厥阴热利故下利脓血、里急后重；因阳明热盛于周身，四肢厥逆反不显现，故手足甚温，正合合并病之机。", ["弦", "洪"]], "20124": ["预后", "服药三次后诸病减三分之二，再诊其脉仍有实热未清，说明阳明厥阴之实热虽挫而未净，脉象仍提示邪热内实。故于原方加滑石五钱利小便，使热从下泄，正所以止其下利后重。此段以脉测余邪，示热病瘥后须察脉以定清解未尽之治。", []], "20125": ["主病", "脉象微浮而至数如常，浮主表、微浮示邪浅，至数如常则里无热。身体酸软懒动、稍畏风、舌色白，皆受风甚轻之征，因风邪轻微故受时不觉。脉浮而不数不洪，说明邪尚在表而未化热，宜轻清辛凉之剂发散，使轻邪从表而解。", ["浮"]], "20126": ["主病", "脉象浮数似有力，浮主表邪，数主热，似有力示邪正相争。受风较重，头疼、周身骨节疼、肌肤热、心中微热、舌苔白厚，皆风邪外袭、渐有化热之势。故于前方去葱白之温散，加天花粉清热、菊花治头疼，薄荷后入以存其轻清发散之力。", ["浮", "数"]], "20127": ["病机", "脉象浮而有洪象，浮为外感触动之表，洪为伏气化热之里，表里俱热故一时并见。舌苔白厚、中心似干，示伏热内蕴而津渐伤。此伏气虽连及阳明，然脉仍带浮，说明邪尚有从太阳汗解之机，故仍可因势利导，由表而解，不必径清阳明。", ["浮", "洪"]], "20128": ["治法", "原文未提脉象，论述重用石膏、花粉少用薄荷、连翘的方剂作用机理。此方为发表之剂，但通过调剂阴阳，使伏气化热之邪自汗而解，非强发其汗。关键在“重用凉药与之化合”如“水沃冶红之铁”，热气蓬勃四达，少佐解表药则汗出而解，且汗多无亡阴亡阳之虞。", []], "20129": ["主病", "脉浮而濡，至数如常，主湿温。浮为风邪在表，濡为湿气内蕴，故见身体酸懒沉重、头重懒抬、足重懒举、肌肤微有痕、小便不利、舌苔白腻带灰。此因久居潮湿、阴雨湿侵或饮食伤脾，湿郁中焦复感风邪，治宜外解表邪、内利湿浊。", ["浮", "濡"]], "20130": ["病机", "脉浮而长，主温病初得作喘。浮为风邪袭表，长为痰火内盛，故肌肤不恶寒而发热，心中微热。此乃肺中先有痰火，又为风邪所袭，表邪引动痰火，肺气上逆而喘。治宜麻杏甘石汤，清肺化痰、解表平喘。", ["浮", "长"]], "20131": ["病机", "温病旬日不解，舌苔仍白，脉仍浮，此邪入太阳之府。脉浮为邪在表，太阳之府为膀胱，邪入则气化不利，小便必发黄。此非单纯表证，乃表邪未解而内传膀胱，治宜发表清热药中加清膀胱之药，分解表里之邪。", ["浮"]], "20132": ["病机", "温病至七八日，六经已周，脉忽然浮起，至数不数，且有大意，此邪欲从表解之机。脉浮为邪气外达，不数为热不炽，大意谓脉象宽缓，示正气渐复，故宜辛凉之剂助其达表而汗解，因势利导。", ["浮"]], "20133": ["病机", "脉象浮数而细，关前尤甚，主温病多日，外感重还太阳欲作汗。浮为邪在表，数为热，细为阴分太亏。头目昏沉、讝语、四肢扰动，乃阴亏不能上济应阳，欲汗不汗。若因脉浮强发其汗，必凶危立见，宜大滋真阴，使数者渐缓、细者渐大，阴充则汗自出。", ["浮", "数", "细"]], "20134": ["治法", "服大滋真阴药三剂后当自汗，若汗不出，其脉不似从前之数细，说明阴分渐复、热势已减。此时可仍煎此药送服阿斯匹林一瓦以助汗出。原文以“脉不似从前之数细”为阴充热退之征，故可佐西药发汗。", ["数", "细"]], "20135": ["其他", "原文未提脉象，论述山萸肉酸敛之中大具条畅之性。其味至酸得木气最全，故能养肝熄风，治四肢骚扰不安之肝风动；酸敛可止元气不固之汗，条畅可助肝虚不疏泄者出汗。此方用萸肉意在养肝熄风，非妨于出汗，乃临证实验所得。", []], "20136": ["病机", "脉浮数有力，浮为外感束表，数为热，有力为实，说明伏气化热已入心包，又为外感所束，内蕴之热益甚。热扰心神则五心烦躁，热蒸清窍则头目昏沉，舌苔白厚生芒刺、口有辣味皆热盛津伤之象。此脉证相应，主伏气温病内外俱热之病机。", ["浮", "数", "实"]], "20137": ["病机", "脉洪滑或兼浮，洪为阳明热盛，滑为热实，浮为热势趋表。此寒温传经已深，阳明热实，故见周身壮热、心中热渴、舌苔白欲黄。洪滑主里热炽盛，兼浮说明热邪尚有外达之势，故用白虎汤加辛凉之品因势利导，使热从汗解。", ["洪", "滑", "浮"]], "20138": ["病机", "原文未明言脉象，而述承气证得汗之机理。胃府实热为承气冲开，病机自外越，故大便未下而汗出；降后得汗则脉净身凉，示热随汗解。若降后无汗，热必不尽，需竹叶石膏汤等清余热。此段论伤寒风温始终宜汗解，汗出为热邪外透之征，脉净身凉为邪去正安之候。", []], "20139": ["治法", "脉象虽有实热而仍在浮分，且头疼、舌苔犹白，说明热邪尚在表分，未全入里。浮脉主表，实热为伏气所化，表邪未解故仍当汗解，但宜辛凉发汗，佐以清热。此先有伏气又薄受外感之温病，脉浮实提示表里同病而以表为主，故用清解、凉解、寒解三方斟酌选用。", ["浮", "实"]], "20140": ["病机", "脉象洪实，洪为热盛，实为邪实，说明伏气暴发自内达外，表里壮热。舌苔白而欲黄，为热邪初入阳明之象。此证虽表里俱热，但不宜发汗，因热自内发，宜宣散清解，用白虎汤加连翘、茅根等，使内蕴之热从腠理透出，服药后自汗而解，非取汗也。", ["洪", "实"]], "20141": ["病机", "脉象多数而有力，数为热，有力为实，说明冬不藏精之人阴虚内热，为外感拘束而发为温病。热积脏腑故脉数有力，阴虚津伤故息微喘、舌苔白而津短，后或干黄、黑如斑点，频饮不解渴，入阴分潮热。此脉主阴虚伏热之温病，初起舌苔白时亦可汗解，但须辅以大滋真阴之药。", ["数", "实"]], "20142": ["预后", "原文述少阴温病服药后脉当见大，继则复和平。伏气化热窜入少阴，肾虚损故精神短少、昏昏似睡、舌干无苔、小便短赤，热郁于中而肌肤无甚热。服药后脉见大，为邪热外达之象；脉复和平，则邪退正安，示预后向愈。此段以脉象变化判断少阴温病之转归。", ["大", "和平"]], "20143": ["主病", "脉洪滑有力者，洪滑为阳明热盛，有力为实，主暑温表里大热，宜白虎汤；脉虽洪大而按之不实者，洪大为热盛，按之不实为气阴不足，宜白虎加人参汤。此证发于长夏烈日劳作，即《伤寒论》所谓暍病，脉象虚实不同，治法因人而异，皆可随手奏效。", ["洪", "滑", "实", "大"]], "20144": ["病机", "脉弦长有力而见于沉分，弦主肝胆气机郁滞，长主邪实有余，沉则病位在里。此非表证之浮脉，乃伏气化热内伏于里，热郁不能外达，故外畏冷而心中热，二便闭、呕吐，皆热深厥深、气机不通之象。", ["弦", "长", "沉"]], "20145": ["主病", "脉浮洪为温病初起邪在卫表、热势外扬之象；洪滑则热盛于里，燥热内蕴。原文谓‘内蕴之燥热与凉润之药化合’而汗出，说明此脉主温病表里俱热，故见恶寒、大热、渴嗜饮水，治以凉解、寒解而一汗愈。", ["浮", "洪", "滑"]], "20146": ["其他", "本段未出具体脉象，而论《伤寒论》以中风、伤寒、温病三项统于六经，并指出‘论脉之处有所区别’。其意不在某脉主某病，而在说明脉诊是分辨三证之关键，故列于其他，以见脉法在辨证中的提纲作用。", []], "20147": ["病机", "原文辨太阳脉浮统中风伤寒，脉缓为浮中之缓属中风，脉紧为浮中之紧属伤寒。大青龙汤证明言中风而脉浮紧，是中风病中现伤寒之脉，主寒邪凛冽束表；又脉浮缓、身不疼但重，则属温病。此段以浮紧、浮缓之异辨风寒温三证之病机。", ["浮", "紧", "缓"]], "20148": ["病机", "原文言伏气化热之温病，病在少阴则辨之甚易，因少阴寒热迥分两途。脉愈微细，说明伏气化热内灼，阴精亏耗，脉道不充，故见微细；此与少阴伤寒之寒证脉微细不同，彼为阳虚，此为热灼阴伤，当从伏气化热论治。", ["微", "细"]], "20149": ["病机", "本段未出具体脉象，而言伤寒温病皆有谵语神昏，不可概以阳明胃实论，当‘详辨其脉象之虚实，热度之高下，时日之浅深’。其主旨在于脉象虚实是辨谵语神昏属胃实或属他因的关键，故归病机，强调凭脉别虚实。", []], "20150": ["治法", "脉洪而有力、按之甚实，为阳明胃腑热盛之确据。胃热上蒸则神昏谵语，肠实便结则肾气不交于心而亢阳无制。原文据此脉投大剂白虎汤，便结甚者酌用承气，是凭洪实之脉定阳明胃实之治，故归治法。", ["洪", "实"]], "20151": ["误治", "脉象确有实热而兼弦兼数、重按不甚实，弦数示真阴亏损、邪热炽盛。原文先与白虎汤，服后脉搏力减而谵语益甚，是但清邪热未滋真阴之误；急改白虎加人参汤倍参而愈。此段以弦数之脉说明邪炽阴伤，单用白虎为误治。", ["弦", "数", "实"]], "20152": ["误治", "脉洪实有力为阳明热盛之象，然汗吐下后或误治伤正，脉虽洪实而转数，谵语更甚，示热未清而气阴已伤。洪实主热盛，数则示正虚邪扰，故用白虎汤时宜加人参以扶正，防苦寒伤气。", ["洪", "实", "数"]], "20153": ["病机", "脉跳动无力因肾虚邪伏少阴，肾气不能上济心脉，致心脉鼓动无力；燥热郁中不得外透，故闭目昏昏、间作谵语。此少阴伏气温病，脉虚数为正虚热郁之征，治宜白虎加人参汤清透郁热、扶助肾气。", ["虚", "数"]], "20154": ["兼症", "脉象洪实为阳明热盛，热退后脉近和平而神昏谵语不减，知热邪上蒸脑膜、累及神经。洪实减半示热势已挫，而神昏不除，故非纯阳明证，当兼治脑髓神经，用白虎加人参汤加羚羊角清透余热、通络醒神。", ["洪", "实"]], "20155": ["病机", "脉弦而浮、一息近六至、不任循按、两尺尤甚，为下焦阴分虚损、不能化汗之象。弦主阴亏木旺，浮数示虚阳外浮，尺甚则肾阴不足。阴不济阳则汗源匮乏，热扰神明故昏愦谵语，治当大滋真阴以化汗。", ["弦", "浮", "数"]], "20156": ["误治", "脉微弱而迟、不足四至，为过服开破降下之药损伤胸中大气，气虚下陷不能上达脑中则神昏，不能上潮舌本则舌干，不能宣布营卫则周身皆凉。脉微弱迟主气虚阳衰，非热闭，故当补益大气而非清热。", ["微", "弱", "迟"]], "20157": ["兼症", "脉象热而兼紧、数而有力，为温病兼疹毒内伏之征。紧主毒邪郁遏，数实主热盛，热毒内攻扰乱神明则谵语惊悸。疹毒未透故脉紧，透疹后脉象自和，治宜清热透疹、解毒醒神。", ["数", "紧", "实"]], "20158": ["病机", "脉象有力、关前摇摇而动，为温疫秽邪由口鼻传入、自肺传心之象。关前候心肺，摇摇而动主邪热扰心、神明失守，故无故自笑、精神恍惚、言语错乱。实主邪盛，动主心神不宁，治当护心透邪。", ["实", "动"]], "20159": ["误治", "此段述误用草果发汗致头面汗出如洗、喘息而脱，脉始见而身体虚弱，示正虚不耐峻汗。草果性烈，虽五分亦能伤正，虚人误汗则阳气外脱。脉象未详，然身体虚弱为辨证关键，提示虚人温病忌峻汗。", []], "20160": ["主病", "革脉如按鼓革，外硬中空，即弦脉之大而有力者。因其中空，故虽大而不洪、虽有力而不滑。此脉主阴阳离绝，上下不相维系，气血不交，故病将变革，有危在顷刻之势。张锡纯详录其形状与治法，强调革脉为病脉中之险脉，人多忽之。", ["革", "弦", "大", "滑"]], "20161": ["病机", "原文重申革脉形状如按鼓革，外虽硬而中空，即弦脉之大而有力者。因其与弦脉相近，故虽大而不洪（无起伏），虽有力而不滑（中空）。此脉主阴阳离绝，上下不相维系，脉至如此，病将变革，有危在顷刻之势。张锡纯以此揣摩革脉真象，并附治验以明其险。", ["革", "弦", "大", "滑"]], "20162": ["兼症", "温病脉大而且硬，微兼洪象，舌苔薄黑有斑点，便闭腹满按有硬处。脉大且硬为内伤与外感并重，洪象示温热炽盛。服白虎加人参汤后外感热退，洪象已无，而脉之大与硬未除，说明宿病腹中硬满仍在，脉象随证变化，提示温热渐清而宿疾未愈。", ["大", "硬", "洪"]], "20163": ["病机", "脉左部洪长有力，症见脑疼彻目、目疼彻脑、眩晕生翳。左脉候肝胆，洪长有力为肝胆之火挟气血上冲脑部，脑中血管受冲激而膨胀，故疼；目系连脑，故目疼生翳且眩晕。此脑充血证，脉证合参，当清火、平肝、引血下行。", ["洪", "长", "实"]], "20164": ["病机", "脉左部弦长，右部洪长，皆重按甚实。左弦长为懊憹所生之热，右洪长为积酒所生之热，二热相并，挟脏腑气血上冲脑部，故头疼如锥刺、左手足不能动。此脑充血之剧者，脉实示热盛邪实，弦长洪长并见，说明肝火与酒热交炽上冲。", ["弦", "长", "洪", "实"]], "20165": ["病机", "脉必弦硬而长，或寸盛尺虚，或大于常脉数倍，而毫无缓和之意。弦硬长为肝火亢盛、气血上冲之象，寸盛尺虚示气血上壅于上，大于常脉数倍而无缓和之意，说明邪热鸱张、脉失柔和，为脑充血之典型脉象，提示病机为肝胆之火挟气血上冲。", ["弦", "硬", "长", "数"]], "20166": ["治法", "原文未出具体脉名，仅言「参以脉象之呈露」即可断为脑充血之朕兆。所列证候偶有一二发现，再合脉象即可早断。张锡纯酌定建瓴汤一方，服后能使脑中之血如建瓴之水下行，脑充血之证自愈。此段主旨为治法，强调脉象在早期诊断中的参合作用。", []], "20167": ["预后", "脉象弦硬而大，症见头目眩晕、脑中作疼、心中烦躁、恒觉发热、两臂撑胀，知为脑充血之朕兆。服建瓴汤后脉象虽不若从前之大，而仍然弦硬，病遂反复；必待脉象和平如常，停药方不再反复。说明弦硬大之脉未除，则病根未拔，脉象平和为预后向愈之关键。", ["弦", "硬", "大"]], "20168": ["主病", "脉象弦硬而大，为肝阳上亢、气血上冲之象。弦主肝病，硬为脉失柔和，大则气血壅盛。此脉反映脑部充血，与头疼、口眼歪斜相应。文中言脉搏力达百六十毫米汞柱，断为脑充血证，治以建瓴汤。脉未复常则病根未除，故劝服至脉象平和。", ["弦", "大", "硬"]], "20169": ["治法", "脉象壮实者，气血壅盛，脑充血证情偏实，故可于建瓴汤中酌加大黄以破血降逆；脉象不甚壮实者，则宜桃仁、丹参等活血化瘀之品。此以脉之壮实与否辨体质强弱，定用药峻缓，体现凭脉施治、因人制宜之法。", ["壮实"]], "20170": ["兼症", "脉象洪实者，为阳明大热之征。脑充血证若夹杂外感之热，热势炽盛，脉见洪实，当先以白虎汤或白虎加人参汤清解外感之热，而后治脑充血。此段明辨中风兼脑充血与外感夹杂之脉症，洪实脉提示热盛，为兼症辨治之关键。", ["洪", "实"]], "20171": ["病机", "脉象微弱，或至数兼迟，为气血不足、胸中大气虚损之象。脑贫血者脑中血液不足，不能荣养脑筋，故脉微弱；迟为阳气不振。此脉与头重目眩、精神昏愦、面黄唇白、呼吸短气、心中怔忡相应，甚则猝然昏仆、肢体颓废。文中引《内经》「上气不足，脑为之不满」以明其病机。", ["微", "弱", "迟"]], "20172": ["病机", "此段未言脉象，专论脑髓空虚之病机。色欲过度则脑髓空，髓海不足则头重目眩，甚或猝然昏厥、知觉运动俱废。因脑髓为神经之本源，故其证较脑贫血尤为紧要。治宜峻补肾经，加鹿角胶通督脉，并清心寡欲，还精补脑。", []], "20173": ["病机", "此段未出脉象，推阐脑贫血之病机。引《内经》「上气不足，脑为之不满」，谓脑不满因血少，而血少因胸中大气虚损，不能助血上升。大气虚则斡旋无力，血脉流通不畅，故见耳鸣、头目倾眩，剧则肢体痿废。治当以补气之药为主，气旺则血自升。", []], "20174": ["主病", "脉象极微细无力，为气血大虚、胸中大气虚损之候。微细主气血不足，无力为虚象。此脉与肢体痿废或偏枯相应，因大气虚不能助血上升，脑失所养，经络失濡。干颓汤重用黄耆升补大气，佐当归生血，萸肉、枸杞补肝肾，乳香、没药开血痹，正为此设。", ["微", "细", "无", "力"]], "20175": ["治法", "此段未言脉象，专释干颓汤方义。重用黄耆升补胸中大气，助气上升达脑，血液随气上注；当归生血，与黄耆合为补血汤；萸肉补肝，枸杞补肾，元气壮旺则督脉流通；乳香、没药开血痹，使久瘀经络得通。全方以补气升气为主，兼顾生血通络，针对大气虚损、血不上荣之病机。", []], "20176": ["主病", "脉象极微细无力，为气血大虚、精髓亏耗之象。肢体痿废偏枯而久服补药不愈，说明不仅中焦脾胃气虚，更兼下焦肝肾精血枯竭，不能充养筋骨。微细无力之脉正反映正气衰极，故以补脑振痿汤峻补精血、温养脑髓为治。", ["微", "细"]], "20177": ["病机", "脉象沉微，右部尤不任循按，沉为气陷，微为阳虚，右部不应指说明胸中大气及中焦脾胃之气皆虚陷。前医误用开胸理气，更伤正气，致四肢痿废、言语不能发声。此脉主大气下陷、脾胃气败，故用升陷汤加术、归以升补举陷。", ["沉", "微"]], "20178": ["病机", "心为血脉循环之枢机，心房一动则脉一动。心机亢进则脉大而有力或更数，心脏麻痹则脉细而无力或更迟。脉不得其平，皆由心机亢进与心脏麻痹两端而来。此段以脉之大小数迟辨心之病机，将心疾分亢进、麻痹二大纲，脉象即其外候。", ["大", "数", "细", "迟"]], "20179": ["病机", "脉象洪而有力、脉搏加数，为阳明胃府热炽、上蒸心脏致心机亢进之候。洪为热盛，数为热急，有力为实。热在阳明，故用大剂白虎汤清胃；兼燥粪不通者，用承气汤涤肠，热由下泻则心机自平。此脉主实热亢进之病机。", ["洪", "数"]], "20180": ["病机", "下焦阴分虚损，不能维系上焦阳分，君火浮越妄动而致心机亢进。脉象上盛下虚、摇摇无根、至数加数，为上实下虚、阴不制阳之象。故见眩晕、头疼、目胀、耳鸣。治以加味左归饮壮水制火，使浮游之火归源，心机亢者自平。", ["数"]], "20181": ["病机", "心体之阳素旺，胃腑积有实热，复上升助之，致心机亢进。脉虽有力而脉搏不数，说明热在里而不在表，非外感急热之比。五心灼热为内热之征。治以咸寒之品，以寒胜热、以水胜火，使心阳得制而亢进自平。", []], "20182": ["病机", "思虑过多，神明之阳由心发露，致心机因热亢进，人多迷惑。思虑所生之热与痰涎互相胶漆，故脉现滑实之象，滑主痰，实主热结。脉滑而有力，正是痰热内结、心机亢进之明证。治用大承气汤加赭石、甘遂清热降痰，药虽猛烈而屡效。", ["滑", "实"]], "20183": ["预后", "肝木过升，肺金失肃降，金不制木，肝木横逆上干心脏，致心机亢进；兼冲气上冲，则脉象弦硬有力迥异寻常。弦硬为肝气横逆、冲气上冲之象，甚则脑部血管破裂而成大厥。初露朕兆时脑中作疼、眩晕、半身不利，治以清肺镇肝敛冲，连服数十剂脉渐变柔和，则预后可期。", ["弦", "硬"]], "20184": ["病机", "原文言怔忡之证，气血过于虚损，神明失其凭依，虽心机之动照常，而脉象多微细，或脉搏兼数，脉恒为涩象。微细为气血虚损之象，数因虚而神明不宁，涩则血少气滞，故主心之气虚血少、神明失养之怔忡，治宜补气养血、镇安神明。", ["微", "细", "数", "涩"]], "20185": ["预后", "原文述白虎汤证脉洪大有力，若失治则脉洪大有力之极，渐变为细小无力，此由心机亢进而转为心脏麻痹，已成坏证。洪大有力为阳明热实，热盛伤及心脏，脉由实转虚，故示预后凶险，宜急投大剂白虎加人参汤挽回。", ["洪", "大"]], "20186": ["病机", "原文谓心脏本体之阳薄弱，胃中寒饮溢于膈上，凌逼心阳，致心脏渐欲麻痹，脉象异常微细，脉搏异常迟缓。微细迟缓皆阳气衰微、寒饮内盛之象，心阳被遏，鼓动无力，故主心阳虚弱兼寒饮凌心之证，治以理饮汤温阳化饮。", ["微", "细", "迟", "缓"]], "20187": ["病机", "原文言霍乱证之六脉皆闭者，乃心脏为传染之毒菌充塞以至于麻痹。六脉皆闭为毒菌壅塞、心阳痹阻、血脉不通之象，故主心脏麻痹之危候，治宜兴奋心脏与扫除毒菌并用，如急救回生丹、卫生防疫宝丹。", []], "20188": ["兼症", "原文辨惊悸之脉，若数而兼滑者，系心血虚而兼热；其脉微弱无力者，系心气虚而莫支。数滑为血虚有热，微弱无力为心气虚弱，二者皆心体虚弱所致，故主惊悸之兼症，治当补虚泻热、镇靖魂魄或补气收敛神明。", ["数", "滑", "微", "弱"]], "20189": ["病机", "原文论肺病初起，外感风邪自皮毛袭入肺脏，阻塞气化，暗生内热，酿毒成肺病，其脉象恒浮而有力。浮为邪在表，有力为风热壅盛，故主外感风邪、肺热酿毒之肺病初起，症见咳嗽吐痰有水泡、周身疼、舌白苔、心中发热。", ["浮"]], "20190": ["病机", "原文述外感伏邪入胃，热熏肺脏成肺病，脉象滑实，多右胜于左；又治徐姓叟病肺，脉弦长有力，迥异寻常，重用石膏后脉始柔和。滑实弦长有力皆邪热壅盛、痰热内结之象，故主伏邪化热、痰热壅肺之肺病，脉数者阴分必虚，数可变为和缓。", ["滑", "实", "弦", "长"]], "20191": ["病机", "原文论内伤肺病，因脾胃伤损，土虚不能生金，肝木横恣侮克脾土，饮食不化精液，化痰涎黏滞肺叶，虚热刑肺，其脉弦而有力，或弦而兼数，重按不实。弦为肝木横恣，数为虚热，重按不实为土虚，故主肝木侮土、土虚金伤之肺病。", ["弦", "数"]], "20192": ["病机", "脉细数无力，为肾阴亏损、虚火刑金之象。肾阴亏则肺失濡养，虚火内生，故脉细数；气化暗耗，故无力。症见潮热、咳嗽、懒食、痰腥臭或喘促，皆阴虚肺燥、火灼金伤之候。若脉数不能渐缓，示虚热不退，病势缠绵。", ["细", "数", "虚"]], "20193": ["病机", "脉弦硬或弦而兼数，为阴血伤损、内热瘀滞之征。素患吐血衄血，阴血亏虚，或强止其血，瘀血留络，久而生热，灼肺成病。弦硬主瘀滞与内热，数主热盛。症见心中闷热、咳逆短气、吐痰腥臭，皆瘀热壅肺之候。", ["弦", "硬", "数"]], "20194": ["病机", "阴虚不纳气者，脉多细数，或上盛下虚，或硬弦而长。细数主阴虚内热，上盛下虚示肾不纳气、气浮于上，硬弦而长乃肝气冲逆之象。此段辨喘之因于肝肾者，脉象有别：阴虚者细数，冲气上逆者弦长，皆气机不降之候。", ["细", "数", "弦", "长"]], "20195": ["病机", "本段论肺劳作喘之由，肺叶紧缩、闟辟失常，津液减少、血脉凝滞。虽未明言脉象，然暑热时紧数稍缓，寒凉则喘作，暗示脉紧数之象。肺失宣降，故喘；津血凝滞，故肺叶紧缩。此内伤肺病之机，非外感可比。", []], "20196": ["病机", "脉滑主热饮，弦细主寒饮。痰饮积胃溢膈，浸肺作喘。热饮脉滑，多兼神经病；寒饮脉弦细，因上焦阳分虚，寒饮内停。弦细为阳虚饮聚之象，滑为痰热之征。治以温化，使饮从水道出，则喘自平。", ["滑", "弦", "细"]], "20197": ["病机", "外感之喘，脉浮紧为风寒束表，卫气郁闭，肺气不宣；脉洪滑为温病热盛，热壅于肺。浮紧主表寒，洪滑主里热。风寒束表则卫气不通，胸中大气膨胀排挤肺脏；温邪犯肺则热壅气逆。二者皆肺失宣降而喘。", ["浮", "紧", "洪", "滑"]], "20198": ["病机", "脉甚虚者，为外感风寒内侵，与水气凝滞，上迫肺气作喘，而正气已虚。小青龙汤证本为寒饮射肺，若脉甚虚，则示胸中大气不足，不能抗邪，故宜加野台参以扶正。虚脉主气弱，饮邪内停，正虚邪实之候。", ["虚"]], "20199": ["病机", "不纳气之喘脉多数，大气下陷之喘脉多迟而无力。数主阴虚气浮，迟而无力主胸中大气虚陷。二者脉迥不同：不纳气者肩息，大气下陷者不肩息而肩下垂。脉数是虚热上浮，迟弱是气虚下陷，辨此可免误治。", ["数", "迟", "虚"]], "20200": ["病机", "脉象微弱无力，主大气下陷，胸中气机不能撑持，故呼吸困难而呈喘状；脉搏略数，兼阴虚不纳气，虚热内扰。背发紧、身心微有灼热，亦为气陷兼阴虚之征。此喘同中有异，治宜升补大气兼滋敛阴虚，方中不用桔梗、升、柴，恐升散碍阴虚纳气。", ["微", "弱", "数"]], "20201": ["预后", "此证之脉若见滑象，说明痰浊内壅、气机尚能鼓动，服参赭培气汤可降逆化痰而愈。滑为痰饮之常脉，与参赭培气汤镇降痰浊相合，故断言必愈；服五六剂后加三七细末，防瘀滞，愈后自无再发之阨。", ["滑"]], "20202": ["病机", "脉至数如常而六部皆有郁象，非数非迟，乃胃气不降、气机郁滞之征。饮食停滞胃中不下，间有呕吐，大便非通利不行，皆胃气上逆不降所致。郁象示气机壅遏，非虚非实，故重用赭石降胃，佐山药、当归、鸡内金、厚朴、柴胡以和胃疏郁。", []], "20203": ["病机", "胃气不降初得多弦长有力：冲气上冲则脉长而有力，肝气上干则弦而有力，肝冲并见则弦长有力。此证六脉郁而重按无力，因上逆既久，习惯成自然，气郁而虚，故脉郁且虚。说明病机由实转虚，胃气久逆不能下行，非初起肝冲迫胃之实象。", ["弦", "长", "虚"]], "20204": ["病机", "脉象洪滑重按甚实，主热盛于内、胃气不降。洪为热盛，滑为痰壅，重按甚实为邪热结聚，胃气上逆迫血妄行，故吐衄。此因热而胃气不降，治宜平胃寒降汤清降胃热，热降则胃气自下行而血止。", ["洪", "滑", "实"]], "20205": ["病机", "脉象虚濡迟弱，主中阳不足、胃气虚寒。虚濡为气弱，迟弱为阳衰，胃中无火以腐熟，饮食停滞胃口不能下行，胃气因凉而不降，逆而吐衄。此因凉而胃气不降，治宜健胃温降汤温中降逆，阳复则胃气下行。", ["虚", "濡", "迟", "弱"]], "20206": ["病机", "左脉弦长有力，主肝胆之气火上冲。弦为肝脉，长为气火有余，左脉候肝，故肝胆气火循经上冲胃腑，胃气不降而吐衄，或肋下胀满作疼、频作呃逆。治宜泻肝降胃汤清泻肝胆，降胃止血。", ["弦", "长"]], "20207": ["病机", "右脉弦长有力，主冲气上冲。右脉候脾胃，弦长为冲气鼓动之象，冲气起于下焦上冲胃腑，胃气不降，饮食停滞不下，或频作呃逆，甚则吐衄。治宜镇冲降胃汤镇冲降逆，冲平则胃气自降。", ["弦", "长"]], "20208": ["病机", "脉浮数重按无力，浮数为阳热外浮，重按无力为阴分亏损、不能潜阳。失血过多，阴不敛阳则作热，阴不纳气则作喘，冲气上干为呃逆眩晕咳嗽，心血不荣为怔忡惊悸不寐。此脉象揭示阴亏阳浮、气逆不降之病机。", ["浮", "数", "虚"]], "20209": ["病机", "脉浮弦重按无力，浮为气浮于上，弦为肝木失和，重按无力为气脱于下。吐衄血脱气亦随脱，故言语不接续、动则作喘。此脉象说明血脱气浮、根本欲脱之病机，主吐衄后气随血脱之证。", ["浮", "弦", "虚"]], "20210": ["病机", "脉上盛下虚，即寸关浮盛而尺部虚弱，为血脱气浮、下元不固之象。血脱气亦随脱，气逆于上则喘促咳逆，虚阳上扰则心中烦热。此脉象揭示上焦气逆、下焦虚损之病机，主吐衄后气脱阳浮之证。", ["上盛下虚"]], "20211": ["病机", "脉弦长有力，弦为肝气偏亢，长为胃热壅盛，有力为实热内结。患者吐血，服柴胡后大吐不止，心中发热，知系胃气因热不降。此脉象说明胃热壅盛、肝气上逆之病机，主吐衄因热而气逆之实证。", ["弦", "长", "有", "力"]], "20212": ["病机", "脉微弱无力，为气血亏虚、中气下陷之象。妇女倒经吐衄，气短不足以息，少腹时有气下坠，皆因气陷不能升举，血随气逆。此脉象说明气虚下陷、统摄无权之病机，主吐衄因气陷者，虽少见却需细察。", ["微", "弱", "无", "力"]], "20213": ["病机", "六脉和平，重按似有不足，和平为脉无偏亢，重按不足为脾胃虚弱。吐血愈后稍食硬物或过饱即反复，知脾胃消化力弱，胃中出血处肌肉未复，被食物撑挤而再出血。此脉象说明脾胃虚弱、运化无力之病机。", ["和平"]], "20214": ["病机", "脉左右皆洪实，洪为热盛，实为邪结，左右皆然说明肝胆胃热俱盛。吐衄因寒温而致者，若脉洪实，宜加羚羊角泻肝胆之热，血始能止。此脉象揭示热盛迫血妄行之病机，主吐衄属热盛实证者。", ["洪", "实"]], "20215": ["病机", "脉微弱无力，为气血大虚之象。血脱须分脱于二便或吐衄：二便下脱者脉微弱可用独参汤；吐衄而脱者纵脉微弱亦不宜用，因阴血亏损、维系无力，孤阳有浮越之虞，复用人参则气易上奔，血随之上奔而复吐衄。此脉象说明血脱气浮之病机。", ["微", "弱", "无", "力"]], "20216": ["病机", "脉象滑动，按之不实，为胃气上逆、血随气升之象。滑主痰饮，动主惊悸，此因吐血后阴血亏虚，虚阳上浮，故脉虽滑动而按之不实。患者心若虚悬无著，正是血去心虚、神不守舍之候。鲜藕、茅根甘寒凉血，降胃安冲，使血止而脉静，故饮后心神若有所归。", ["滑", "动"]], "20217": ["治法", "脉滑实为痢初起湿热积滞壅盛之征。滑主湿浊，实主邪实，脓血稠鲜、后重肠疼，皆湿热蕴结肠道、气血壅滞所致。脉实故可下，用小承气汤加芍药、甘草，朴实开肺，大黄芍药清肝，寒热交平，涤肠荡滞，此因脉实而施下法之例。", ["滑", "实"]], "20218": ["病机", "脉按之不实，为痢久正伤、邪滞未净之象；迁延日久，脉或略数或微虚，数主热，虚主正亏，脂膜间杂，腹疼浸剧，乃久痢伤阴、脾肾两虚而余热未清。化滞汤治其初，燮理汤治其久，皆因脉不实而设，示人久痢不可峻下，当顾护正气。", ["数", "虚"]], "20219": ["病机", "脉确有实热，为痢兼外感、热陷阳明之候。实主邪壅，热主火盛，表里俱热，服凉药而热不退，乃外感之热随痢深陷，无路外达，故痢为热助而日甚。通变白虎加人参汤以人参助石膏，使深陷之热徐徐上升外散，佐芍药甘草理后重腹疼，此凭脉实热以定清透之法。", ["实", "数"]], "20220": ["预后", "此段未识脉名，然述外感实热与痢相并之险证，脉搏至百一十至、神识蒙昏、舌干苔剥，显系热邪内陷心营、阴液将涸之危候。东人不知清外感实热为要务，仅注射血清，故至不救。设早用通变白虎加人参汤清透，或可挽回，此示脉数热盛兼神昏者预后多凶。", []], "20221": ["病机", "脉洪而无力，为暑伤气分、热盛津伤之象。洪主热盛，无力主气阴两虚，肌肤烙手、昏不知人、循衣摸床，乃暑热熏蒸、心神失守。白痢而现此脉，知非寒湿，实因伤暑而致，故用生石膏清暑，台参益气，使热退神清而痢自愈。", ["洪", "虚"]], "20222": ["病机", "初病脉弦细而重诊有力，弦主痛、细主阴伤，为湿热痢伤阴之象；反复后脉弦细兼迟、不任循按，迟主寒，不任按主虚，知病机由热转寒，已成寒痢。同一痢证，脉象前后迥异，故用药凉热各别，示人临证须息息与病机相赴。", ["弦", "细", "迟"]], "20223": ["病机", "脉关前浮弦、重诊不实，两尺微弱无根，一息五至，为虚极将脱之兆。浮弦主虚阳上浮，微弱无根主肾气欲绝，上焦烦热、噤口不食、怔忡恍惚，乃上下不交、阴阳离决之危候。故急用萸肉、山药、熟地等峻补肝肾、收敛浮阳，以救其脱。", ["弦", "浮", "微", "弱"]], "20224": ["病机", "暑热时奔走劳碌，肝胆肠胃先有蕴热，陡然下痢带鲜血，脉洪大为热盛于内、气血沸涌之象，故主实热痢；若洪大而按之虚，则热盛而气阴已伤，正不胜邪，故宜白虎加人参汤，既清暑热又顾护气阴，送服鸦胆子仁以治痢。", ["洪", "大", "虚"]], "20225": ["病机", "痢久清阳下陷，胸中大气因痢下陷，故脉象迟弱，迟为阳气不振，弱为气陷无力；症见下坠腹疼、呼吸短气、寒热往来，皆大气下陷、清阳不升之候，故治以升陷汤升补大气，去知母之寒滑，加山药、白头翁固气化而止泻痢。", ["迟", "弱"]], "20226": ["病机", "痢下频频而肠中仍有燥结，尺部重按甚实，实为有形燥屎内结之征，故虽日下痢脓血稠黏、腹疼后重，仍须去其燥结而痢始愈；投小承气汤加生杭芍下燥粪后，后重腹疼顿愈，证明脉实主肠有结粪，非虚寒下痢可比。", ["实"]], "20227": ["病机", "此段论硫黄治寒痢之理，脉甚细弱示下焦阳虚、火不暖土，故痢证下焦凉者上焦恒有虚热；硫黄禀火之精气，质重直达下焦补相火暖下焦，性热而能通，故治寒痢最宜，与干姜、白术、五味同用则止泻，说明细弱之脉主下焦虚寒。", ["细", "弱"]], "20228": ["病机", "内伤结胸与外感结胸相并，脉左右皆弦、右部弦而有力，弦主饮邪结聚、气机郁滞，有力为实；脉不为洪而有力，说明热未外扬而结于胸膈，故心下痞闷杜塞、吐痰腥臭、肌肤发热、大便不行，属温病结胸之险证，非单纯肺胃病。", ["弦", "有力", "洪"]], "20229": ["治法", "霍乱分阴阳，阴证宜温、阳证宜凉，辨证不清而凉热误投必凶危立见；甚者脉闭、身冷如冰而心中发热、嗜饮凉水，断为阳证，热毒内伏、阳气郁闭，故脉闭身冷；急救回生丹性凉善发汗解毒，使内伏毒热透表外出，则身凉可温、脉闭可现。", []], "20230": ["病机", "大泻不止继以吐，脉尤紧而迟，紧主寒邪内束、迟主阳气不振，四末微麻、头疼身热无汗、口渴，为伏阴而兼外感之候；阴寒内伏、表邪外束，故脉紧迟而兼表证，治以急救回生丹温复得汗，令邪从表解，吐泻之势亦缓。", ["紧", "迟"]], "20231": ["预后", "霍乱吐泻已极、奄奄一息将脱，方书谓之脱疫，此时无论因凉因热皆当急救；吐泻之始肝木助邪侮土，吐泻之极肝气转先脱，故身凉、脉不见、心中分毫不觉热，为阴阳俱脱之危候，急用急救回阳汤阴阳俱补，敛肝气、固元气以挽回生机。", []], "20232": ["病机", "原文言霍乱大寒之证，必现恶寒、四肢拘急、厥冷、吐利汗出等症，且脉象沉细欲无者，方可酌用《伤寒论》中诸方急回其阳。脉沉细欲无，为阳气衰微、阴寒内盛之象，故主大寒之霍乱，阳回之后间有烦热，又宜凉润滋阴。", ["沉", "细"]], "20233": ["兼症", "原文述霍乱大热证，虽吐泻交作、脉微身凉，而心中热而且渴，须臾难忍，恣饮凉水可解。脉微身凉似阴寒，然心中热渴为热邪内郁，阳郁不达外，故脉微身凉，实非真寒，乃热证之假象，故放胆饮凉水而愈。", ["微"]], "20234": ["病机", "原文言食西瓜后吐泻转筋，心中发热，火气上腾，身不凉，脉不闭，自知纯系热证。脉不闭说明热邪未致闭厥，与身凉脉闭之阴证相反，故用白虎加人参汤及吞冰而愈，此因食凉物激动伏暑之热，发为热霍乱。", []], "20235": ["病机", "原文辨霍乱阴阳：阴证身凉有汗脉沉伏，阳证身热无汗脉沉紧。脉沉伏为阴寒内盛、阳气被遏；脉沉紧为寒邪束表、里有实邪，腹疼甚、呕不得出、胀不得泻，邪正相争，故脉沉紧。", ["沉", "伏", "紧"]], "20236": ["病机", "原文评阴证身凉脉沉伏，阳证亦间有之，然阴证恒恶寒、身欲厚复，阳证始终不恶寒。脉沉伏主阳气郁闭，阴证为阳衰，阳证为热郁，须结合恶寒与否、有汗无汗及腹疼拒按等症辨别阴阳。", ["沉", "伏"]], "20237": ["病机", "原文论肝病不仅害脾，凡惊痫、癫狂、眩晕、脑充血等脑气筋病皆与肝经相关。肝主筋，为肾行气，脑气筋发源于肾而分派督脉，故肝风火动则脑气筋病，治当镇肝清火，使风定火熄。", []], "20238": ["治法", "原文论硝石矾石散用法，随证择药送服：实热用茵陈栀子，食积用鸡内金山楂，便结用大黄麻仁，尿闭用滑石芍药，呕恶用赭石青黛。脉沉迟而弦主内寒肝郁，左脉沉而无力、右脉沉而无力主气血不足，脉浮有外感者当先解表。", ["沉", "迟", "弦", "浮"]], "20239": ["病机", "原文述黄疸证先受外感，酿成内伤而发，症见身无大热、心中满闷、恶心呕吐、食后不化、腹中觉凉。其脉左似有热、右多郁象，盖肝胆热而脾胃凉，因湿郁久则肝胆生热、脾胃生寒，木热土寒，故成黄疸。", []], "20240": ["病机", "原文引《伤寒论》「脉浮而缓，手足自温，是为系在太阴」及《金匮》「寸口脉浮而缓，浮则为风，缓则为痹」，说明浮为风邪外袭，缓为湿痹内阻，风与湿合，郁于太阴脾土，脾色外现而发黄。此脉象揭示黄疸病机为风湿痹阻、脾失运化、瘀热以行，故主发黄之证。", ["浮", "缓"]], "20241": ["病机", "原文述「左脉细弱者，知系肝阳不能条畅」「右脉濡弱者，知系脾胃不能健运」。左脉细弱反映肝阳不足、条达失职；右脉濡弱提示脾胃气虚、健运无权。此脉象说明内伤黄疸病机在肝脾两虚，故分别用黄芪、当归、桂枝尖条畅肝阳，白术、陈皮、薏米健运脾胃。", ["细", "弱", "濡"]], "20242": ["病机", "原文指出「风水、皮水脉浮，正水、石水脉沉」，又言水病剧者「脉之部位皆肿，必重按之成凹其脉方见，原难辨其浮沉」。浮脉主表、主风，水在肌表；沉脉主里、主水，水在里。更以有力无力辨凉热，说明水肿病机有表里寒热之分，故治法脉浮宜发汗、脉沉宜利小便。", ["浮", "沉"]], "20243": ["病机", "原文载水肿患者「脉六部细数，心中发热，小便不利，知其病久阴虚，不能化阳，致有此证」。细脉主阴血不足，数脉主热，六部俱细数说明久病阴虚生内热，阳无以化，气化不利，水湿内停。此脉象揭示阴虚水停之病机，故用鲜白茅根利小便兼清虚热。", ["细", "数"]], "20244": ["病机", "原文言「因凉成水臌者，其脉必细微迟弱，或心中觉凉，或大便泄泻」。微细迟弱皆阳气衰微之象，迟主寒，弱主虚，说明下焦阳虚、阴寒内盛，不能温化水饮，水湿泛滥而成水臌。此脉象主虚寒水停之病机，故用花椒目、硫黄等温性利小便之药。", ["微", "细", "迟", "弱"]], "20245": ["病机", "原文论气臌「多系脾有瘀滞所致」，引《内经》「诸湿肿满皆属脾也」，说明脾居中焦、主运化，瘀滞阻遏气化则腹中胀满，久积成臌。文中「脉证皆实」指邪实内结之候，故用鸡胵汤开脾瘀、助脾运，实者更以黑丑末峻下逐水。此段主述气臌脾瘀气滞之病机。", []], "20246": ["其他", "原文为强肾瑞莲丸方论，以建莲子、猪羊脊髓为丸，谓「常服大有强肾之效」。文中以物之脊中袋喻督脉，谓脊髓所藏之液能助肾脏作强，督脉上通于脑，故用鹿角胶、猪羊脊髓补肾。此段未及脉象，专论补肾强身之方药与理据，属其他类。", []], "20247": ["病机", "原文载患者「年过四旬，身形羸弱，脉象细微，时患泄泻，房事不能作强」。细微脉主气血阴阳俱虚，说明下焦虚寒、肾中元气亏乏，不能温煦固摄，故泄泻、阳痿。紫稍花温补下焦，服后脉有起色，证明此脉象主肾虚下焦寒之病机。", ["细", "微"]], "20248": ["病机", "本段为冲气上冲之总论，未出具体脉象，故脉象要素为空。原文指出冲气上冲多因肾虚不敛、肝气恣横，致胃气失于下行而转上逆，症见腹中膨闷、哕气、呃逆、胁胀、眩晕等。其病机核心为冲胃之气上逆，脉象虽未明言，但后文以弦硬而长为肝脉之象，提示本段旨在阐明病因病状病脉之总纲。", []], "20249": ["病机", "原文谓“其脉则弦硬而长，乃肝脉之现象也”，又言“脉象数而觉热者”。弦硬而长为肝气恣横、冲气上逆之征，因冲脉隶于阳明，冲气上冲则胃气亦逆，故脉见弦硬而长；数而觉热者，示气逆化火。此脉主冲气上冲兼肝胃气逆，症见腹中膨闷、哕气、呃逆、胁疼胀、头目眩晕等。", ["弦", "硬", "长", "数"]], "20250": ["主病", "本案脉象弦长有力，为冲气上冲、肝胃气逆之典型脉。弦长主肝气恣横，有力主气逆壅实；气冲痰涎作响，故腹中漉漉有声，胸胁满闷、饮食减少、哕逆、便干皆气逆不降所致。服降胃镇冲方后“脉即柔和”，反证弦长有力为气逆实证之脉，脉柔则气降病退。", ["弦", "长", "有", "力"]], "20251": ["兼症", "原文谓“脉情状大略与前案同”，即脉弦长有力，惟“尺脉稍弱”。尺弱示肾虚不摄，冲气失敛；弦长有力仍属肝胃气逆。无痰声漉漉，故去芒硝，加柏子仁、枸杞子兼顾下焦。此脉主冲气上冲兼肾虚，症见胸胁满闷、哕逆、腹中气冲等，尺弱为辨证加减之关键。", ["弦", "长", "弱"]], "20252": ["主病", "原文谓“其脉左右皆弦硬异常”。患者年高性躁，常忿怒，致冲气上冲，气自下上冲杜塞咽喉，有危在顷刻之势。弦硬异常为肝气恣横、冲气上逆之甚，左右皆然，示气逆遍及三焦。此脉主冲气上冲重证，与咽喉窒塞、气逆危急相应，故用降胃镇冲汤加减而效。", ["弦", "硬"]], "20253": ["病机", "原文分两证：一为气海元气虚损，脉“尺弱寸强，浮大无根”，尺弱示下焦虚，寸强浮大无根为元阳浮越，症见眩晕、面红耳热、怔忡、息贲；二为真阴虚损，脉“多弦数，或重按无力”，弦数为虚阳浮越，重按无力示阴虚不敛。两脉皆主元阳浮越、下焦虚损之病机。", ["弱", "强", "浮", "大"]], "20254": ["病机", "原文谓“其脉弦迟细弱，或两寸浮分似有力”。弦迟细弱示元阳大虚、沉寒锢冷内积，脉道拘急而鼓动无力；两寸浮分似有力为虚阳上窜之假象。此脉主下焦沉寒、元阳浮越，症见心中烦躁、上焦灼热而下焦凉甚、泄泻，即“引火归原”之典型脉证。", ["弦", "迟", "细", "弱"]], "20255": ["病机", "原文谓“其脉多弦长有力，右部尤甚”，并引李士材脉诀“直上直下”。弦长有力右部尤甚，为冲气上冲兼胃气上逆之象，右部主胃，直上直下示气逆壅盛。此脉主冲胃气逆、元阳浮越，症见胸中满闷烦热、呃逆、吐痰涎，剧则痰火与气杜塞咽喉，治当降胃镇冲。", ["弦", "长", "有", "力"]], "20256": ["病机", "脉寸关有力兼滑象、脉搏略数，为用心过度、心中生热，牵动少阳相火，上越外越之征。滑主热痰，数主热，有力为实，故见心中烦躁、疑惑忿怒、热起胁下散于周身，治以咸寒解热、制相火妄动。", ["数", "滑"]], "20257": ["病机", "脉多弦迟细弱，六部皆然，或浮大而软按之豁然，为心肺脾胃之阳甚虚，寒饮停于中焦、溢于膈上，逼迫阳气上越外越。弦主饮，迟细弱主阳虚，故见目眩耳聋、短气咳喘、心中发热而食后胀满加剧，治宜温燥健补脾胃以扫除寒饮。", ["弦", "迟", "细", "弱"]], "20258": ["病机", "脉象虽大，按之无力，又多寸盛尺虚，为下焦虚寒、孤阳上越之戴阳危候。大而无力主虚阳外浮，寸盛尺虚示上下异致，故见面赤气粗、烦躁不安，宜通脉四逆汤加葱、人参以回阳救逆。", ["大"]], "20259": ["病机", "脉沉细而数或浮大而数者，断不可用通脉四逆汤；本案关前洪滑、两尺无力，误顿饮凉药后关前脉大于从前一倍、数至七至，已成戴阳之证。洪滑数主上焦燥热，尺弱主下焦虚寒，元阳上浮，故见滑泻冷沫、鼻如烟熏、面如火炙。", ["沉", "细", "数", "洪"]], "20260": ["病机", "脉数七至，为上焦燥热未清、下焦滑泻致元阳上浮，益助上焦之热，故现种种热象。服参后脉象收敛、至数加数，是下焦得温补而元阳收回，上焦因参反激而燥热益增，故又急用大凉大润之药清上焦燥热而不侵下焦。", ["数"]], "20261": ["病机", "脉必虚，为肾虚之征。原文谓腰疼皆脊梁处作疼，实督脉主之，督脉下连命门为副肾脏，肾虚则督脉必虚，是以腰疼。故治当用补肾之剂而引以入督之品，如益督丸徐徐服之，服至月余自愈。", ["虚"]], "20262": ["病机", "脉左部沉弦、右部沉牢，沉主病在里，弦牢主痛、主瘀滞不通。结合疼剧时心中满闷，可知关节经络必有瘀而不通之处，即《内经》通则不痛、痛则不通之义。前服补肝肾强筋骨诸药无效，故拟利关节通络之剂兼补正以辅助。", ["沉", "弦", "牢"]], "20263": ["预后", "服药三剂后腰已不疼、心中不发闷，脉较前缓和，不专在沉分，说明瘀滞渐通、病势向愈。再诊六部调匀，腰疼除根，为预后良好之征。由此案可知，身形不羸弱而腰疼者多属关节经络不通，羸弱者或肝肾亏损。", ["缓", "和"]], "20264": ["病机", "脉象无力为气虚，至数稍迟亦主气弱。患者呼吸短气、饮食畏寒凉，显系胸中大气虚衰；行经时气血下注，大气随陷，故腰际下坠作疼。脉无力与迟并见，正合大气虚而欲陷之机，非单纯血瘀或寒凝可比。", ["虚", "迟"]], "20265": ["病机", "脉有涩象，涩主血行不畅、瘀血内阻。妇人行经腰疼兼腹疼，经血当行而不畅，瘀滞胞宫经络，故脉涩。涩为血瘀之确征，与气虚下陷之无力脉不同，故治以活血化瘀之品而愈。", ["涩"]], "20266": ["病机", "右部脉微弱无力，左部如常，而麻木偏在右。右脉主气，微弱为气虚；风袭经络，气血不能贯注，经络闭塞，肌肤失养而消瘦麻木，渐成偏枯。脉微弱无力正示气虚风袭、经络不通之病机，非实邪壅盛。", ["微", "弱"]], "20267": ["病机", "两寸甚微弱，两尺重按有根，寸脉候胸中大气。素日气虚、呼吸短气，劳力过度后大气下陷，不能斡旋全身，故四肢痿废、卧不能起。寸微弱而尺有根，说明下焦尚固，病在胸中大气陷而不升，故用升补大气之剂取效。", ["微", "弱"]], "20268": ["病机", "脉微细欲无且甚迟缓，微细为阳气衰微、气血不足，迟缓为寒。患者平素心中发凉、咳吐黏涎，胸中素有寒饮，又感冬寒，寒饮凝结杜塞，阳气不能外达，故昏倒不知人、呼吸大碍。脉微细迟缓正合寒饮内闭、阳气式微之机。", ["微", "细", "迟", "缓"]], "20269": ["病机", "六脉皆有涩象，涩主瘀血。室女素虚，误用补敛太过，月事闭塞，瘀血内停，经络闭塞，两腿痿废、抑搔不知疼痒。六脉皆涩，说明瘀血闭塞经络遍及全身，非一处之滞，故治以活络效灵丹加活血通经之品，月事通而腿渐知痛痒。", ["涩"]], "20270": ["病机", "脉洪大或弦长有力，为脏腑气血挟热上冲之象。脑部充血，血管破裂或渗血，黏滞司运动之神经，则对侧手足痿废。洪大弦长有力正示热盛气逆、血与气并走于上之大厥病机，与气虚微弱之痿废截然不同。", ["洪", "大", "弦", "长"]], "20271": ["治法", "脉象和平，说明脑充血已愈，热逆上冲之势已平，而肢体仍痿废者，乃余邪未净、经络气血未复。此时脉已和平，不可再投清降攻伐，宜徐服起痿汤缓图恢复，以养气血、通经络，使痿废之肢体渐次康复。", ["和平"]], "20272": ["病机", "脉左右皆弦硬而长，为肝阳上亢、气血上冲脑部之象。弦主肝，硬主亢盛，长主气火有余。脑充血致脑中疼热、烦躁，即此脉所主。服药后弦硬稍愈，脉近和平，手足渐能运动，说明病机向愈；后弦硬又增，是黄芪升补助热之误，脉随药变，可证脉象与病机相应。", ["弦", "硬", "长"]], "20273": ["病机", "脉象仍有稍变弦硬之时，说明脑部充血溢血虽愈，而溢出之血留滞脑中未化，经络闭塞，肝阳未靖，故脉仍弦硬。弦硬为气血上冲、络脉不和之征。服补气药后觉热，脉变弦硬，是参芪助热升阳，病机未全平复，须随脉加减凉药，息息与病机相赴。", ["弦", "硬"]], "20274": ["兼症", "脉左右皆浮而有力，浮主表，有力主实，结合舌上白苔，知兼外感之热。外感束表，气血抗邪于外，故脉浮有力；然四肢疼痛不休、卧床不能转侧，是外感引动经络痹阻。发汗后脉仍有力，说明外感虽减而里热未清，故改用清热通络之品。", ["浮", "有力"]], "20275": ["病机", "脉细弱无力与洪大有力对举，说明偏枯有虚实两途：细弱无力为胸中大气虚损下陷，不能斡旋脑髓神经；洪大有力为脑中血管充血过度，甚则破裂。一虚一实，病因判若天渊，误投则凶危立见，故临证当以脉辨虚实，不可轻用补阳还五汤。", ["细", "弱", "洪", "大"]], "20276": ["主病", "脉象洪实，右部尤甚，洪主热盛，实主邪壅，右部候气，右甚则气分热壅尤著。结合口眼歪斜、左半身不利、头疼眩晕、心中发热，知系脑部充血。洪实为气血上冲、阳热亢盛之脉，故用建瓴汤镇肝降逆而愈；若误用参芪升补，则助血上行，其弊相同。", ["洪", "实"]], "20277": ["病机", "脉弦而有力，主肝胆之热；洪而有力，主阳明胃腑热盛；脉有数象者，热盛于内；脉象稍浮者，热有外达之势。鼻渊病灶在頞，病本在胆与胃，胆热移脑则辛頞鼻渊。弦为胆脉，洪为胃脉，数主热，浮主上炎，故凭脉可辨热之来源而分经清之。", ["弦", "有力", "洪", "数"]], "20278": ["病机", "少阴病本脉微细，此则阴阳俱紧，为少阴之变脉。紧脉主寒主痛，本不当汗，反汗出者，是亡阳也。无根之阳上窜则咽痛。脉紧而反汗，说明阴寒内盛、虚阳外越，故用八味地黄汤收敛元阳归根以止汗，咽痛自愈。", ["紧", "微", "细"]], "20279": ["治法", "脉为少阴病之微细脉，微细主阴虚热浮，少阴之热上熏咽喉则咽痛。甘草汤润肺利咽、缓心火之上炎；桔梗汤升提肾中真阴，使阴阳接续，上焦浮阳不铄肺熏咽。后世忌桔梗，然审脉确为少阴微细，用之无妨，因苦桔梗能升能降，有开通之力。", ["微", "细"]], "20280": ["其他", "原文未出脉象，仅述少阴病咽中伤生疮、不能言语之证治。少阴之脉络肺上循喉咙，故少阴篇多兼咽喉病。苦酒汤以醋与半夏同用，可使咽疮速破；然醋调生半夏末外敷亦可消疮，不必皆攻破。此段重在阐发少阴咽疮之病机与治法，非论脉。", []], "20281": ["病机", "脉微细兼沉，为少阴伤寒之脉。患者蜷卧昏睡、谵语、舌干黑斑、咽痛溲赤，似属热证，而脉反微细者，因肾气为伏热所遏，不能上达与心相济，心之跳动无力，故无论或凉或热，少阴伤寒其脉皆微细。此脉微细正是肾虚热伏、心肾不交之病机反映。", ["微", "细", "沉"]], "20282": ["病机", "脉洪长有力，纯乎阳明胃腑蕴有实热。温疹兼喉证，疹似靥未靥，咽喉红肿微烂，心中热甚，溲短赤，便三日未行，皆阳明热盛之象。洪长有力为阳明实热之典型脉，故用大剂白虎汤加连翘、薄荷以清阳明、托疹外出，药后脉仍有力，继用茅根汤煎药而愈。", ["洪", "长", "有", "力"]], "20283": ["病机", "脉洪滑而长，重按有力，近九十至，为火毒炽盛、盘踞阳明之脉。虾蟆瘟颔下连颈壅肿硬热色红，牙关不开，咽喉肿疼，痰涎壅盛，气上冲呃逆，便数日未行，皆毒热炽盛、阳明腑实之候。洪滑长而有力，正合实热壅盛之病机，故治当大清阳明火毒。", ["洪", "滑", "长"]], "20284": ["治法", "此段为治法加减：脉象洪实者加生石膏一两，小便不利加滑石，大便不通加大黄。洪实之脉主阳明实热，故加石膏以清之；兼小便不利者加滑石以利湿；大便不通者加大黄以通腑。此以脉象洪实为用石膏之据，示人凭脉用药之法。", ["洪", "实"]], "20285": ["误治", "脉多浮而微数，或初得浮数有力，或洪而有力，此喉证初起之脉。医者不辨，误认缠喉风，重用发表辛温之剂，强发其汗，竟至不救。浮数有力似表实，然喉证多属燥热阴伤，妄汗则津液愈竭，热毒愈炽。此段以误治致死，警示喉证忌表，当以润燥滋阴清热为主。", ["浮", "微", "数"]], "20286": ["病机", "脉微细而迟，主寒痰结胸。患者咽喉肿疼，胸膈满闷杜塞，呼吸顿停，目翻身挺，胸膈常觉发凉，凉气上冲则息停。微细而迟为阳虚寒盛之脉，寒痰充溢上焦，迫心肺之阳上浮，故咽痛而胸膈杜塞。即脉审证，知系寒痰结胸，故用赭石、干姜、附子、厚朴、陈皮温降痰浊而愈。", ["微", "细", "迟"]], "20287": ["病机", "脉细弱而数，主脾肾两虚。患者喉证日久，黏涎甚多，须臾满口。肾虚则气化不摄，阴火上逆，痰水上泛；脾土虚损又不能制之，故咽肿而涎多。细弱为虚，数为阴火上逆之象。此脉细弱而数，正合脾肾两虚、阴火痰水上泛之病机，故用六味地黄汤加于术、苏子以补肾健脾、降气化痰。", ["细", "弱", "数"]], "20288": ["病机", "脉象浮洪，为表里壮热之征。浮主邪在肌表，洪主阳明气分热盛，热势蒸腾，故脉形浮大而洪。原文谓猩红热“证现白虎汤证时”，表里壮热而脉浮洪，兼大便实，说明阳明胃腑热实，邪热有外透之势，故用石膏清里、阿斯匹林透表，使疹全出而热退。", ["浮", "洪"]], "20289": ["病机", "脉象数而有力，数主热，有力为实，示温病热盛于里。肌肤热而干涩、心烦躁扰、大便三日未行，皆阳明热实、阴液受灼之象。热灼日久，恐痧疹毒伏未透，故用白虎加人参汤清泄里热，佐连翘、蝉蜕透邪，便通热退后脉还浮分，继以微汗透痧而愈。", ["数", "实"]], "20290": ["病机", "脉象细数有力，细为阴伤，数为热盛，有力为实，示疹毒未透、阳明府热已实而阴分已伤。肌肤甚热、心中热、气息微喘、干咳、咽疼起疙瘩、舌苔黄、大便数日未行，皆热毒壅结、阴液受耗之候。故须清热与表散并用，以茅根、石膏清里，阿斯匹林透表。", ["细", "数", "实"]], "20291": ["病机", "脉仅细数有力，非洪大有力，说明热毒虽实而阴分已伤，热势未至弥漫。细主阴亏，数主热，有力主实。原文据此认为石膏可少用，但因与茅根同煮，茅根渣减石膏之力，故仍用二两许；并指出若多用羚羊角亦可透疹，此三味并用可代羚羊角，紧扣脉细数有力之阴伤热实病机。", ["细", "数", "实"]], "20292": ["病机", "脉之跳动多无力、脉皆微细，为少阴阴阳两伤之象。微细主气血虚衰，肾气不能上潮于心，故多烦躁。原文论少阴寒热之变，谓寒气轻者伏于三焦脂膜，阻塞气化，暗生内热，后因肾脏虚损，伏热乘虚入肾，虚热实热相助为虐，互伤肾阴，致脉转微细无力，说明病机由实转虚、由热伤阴。", ["微", "细"]], "20293": ["病机", "鼠疫初起脉不但微细，恒至数兼迟，微细为少阴阴阳衰败，数迟并见示正气颓败、阴阳不相接续。精神颓败、闭目昏昏、厌人呼唤、舌干亮如镜、咳嗽咽痛甚至肺燥腐烂呕血水，皆少阴热证至重之候。原文谓鼠疫固少阴热证之至重者，脉微细数迟正合此燥热伤阴、肾气不能上达之病机。", ["微", "细", "数", "迟"]], "20294": ["病机", "脉沉细而迟，沉主里，细主阴伤，迟主阳衰，示少阴阴阳不相接续；心虽发热而肌肤热度无异常，闭目昏昏似睡、呼之眼微开，即《伤寒论》少阴篇“但欲寐”之景象。舌上无苔干亮如镜、喉干微疼、干咳，皆因燥生热、肾气不能上达所致。原文又言脉变洪大，示热势外露，为鼠疫无疑。", ["沉", "细", "迟", "洪"]], "20295": ["预后", "原文未识脉名，仅言“身热，脉起，舌上微润，精神亦明了”，述药后脉象渐起、身热渐退、舌润神清之转归，惟大便未通、内蕴之热未尽清，故再服原方一剂而便通热消。此段重在预后判断，说明脉起、舌润、神清为正气渐复、邪热渐退之佳兆，非专论某脉主病。", []], "20296": ["病机", "脉沉细且咽喉干疼较前尤甚，说明病机为肾阴亏虚、虚火上炎。沉细脉主阴血不足，阴不制阳则虚火灼咽，故干疼加剧。前证相同而脉症更甚，提示阴亏更深，故仍用前方并加鲜茅根、鸡子黄以滋肾润肺、清降虚火。", ["沉", "细"]], "20297": ["病机", "原文言脉象沉细，又谓微细者可变为洪大，洪大者渐臻和平。沉细微主肾阴亏虚、脉道不充；洪大乃阴虚阳浮之象。用茅根汤煎药、加鸡子黄，旨在滋肾润肺、升发沉细之脉，使洪大渐平，体现阴阳互根、调整脉象之病机。", ["沉", "细", "微", "洪"]], "20298": ["预后", "脉象间有不微细迟缓而近于洪数者，为鼠疫最轻者，服方速愈；燥热愈甚则脉愈迟弱，身转不热，说明迟弱脉主燥热内伏、阳气不达。服药后脉起身热，为病机向愈之兆，故本段重在凭脉判断预后转归。", ["微", "细", "迟", "数"]], "20299": ["病机", "原文未直接描述脉象，但论及少阴寒温证剧者，因阴阳之气久不接续，血脉流通闭塞，闭塞而成腐败，酿毒传染。此即从病机层面说明少阴病脉道闭塞、阴阳不相顺接，进而化腐成毒，故传染性强，需严为防范。", []], "20300": ["兼症", "原文虽以脉象细微同于少阴病脉可知为题，但主体叙述鼠疫症状：头痛眩晕、恶寒战栗、发热、淋巴肿胀、嗜眠谵语、泄泻、尿蛋白等。脉细微提示少阴本虚，与但欲寐、伤肾等症相应，故本段重在兼症与脉象的对应关系。", ["微", "细"]], "20301": ["病机", "脉象沉迟细弱，由肾气不上达于心，阴阳之气不相接续，心脏跳动无力所致。沉迟细弱主阳气衰微、心肾不交，故见心脏麻痹之危候。急投坎离互根汤以退热升达肾气，使心肾相交，则脉可复，危可转安。", ["沉", "迟", "细", "弱"]], "20302": ["病机", "原文未直接描述脉象，但言疫毒先犯心脏，使心力衰弱，脉搏如丝为疫毒侵犯心脏之确据。脉搏如丝即脉微细欲绝之象，主心气衰微、疫毒内陷。其后发热、头痛、昏睡谵语、腺肿等症，皆疫毒炽盛、内陷心包之病机表现。", []], "20303": ["治法", "原文未直接描述脉象，但言若脉道阻滞、形容惨淡、神气模糊、恶核痛甚者，宜用解毒活血汤。脉道阻滞提示毒瘀互结、气血不畅，故治以解毒活血、开窍辟秽，并强调初起不可即下、忌早用大苦大寒，属治法范畴。", []], "20304": ["主病", "脉象洪数，为热邪炽盛之征。洪脉主热盛，数脉主热疾，热甚则口燥无津、唇焦大渴，热毒上攻则项肿如虾蟆瘟。此脉此症，热毒充斥内外，故用清瘟败毒饮、普济消毒饮清热解毒。", ["洪", "数"]], "20305": ["病机", "此段论鼠疫病机，阴凝成燥，燥甚化毒。他证以脉洪数为热进，微弱为热退；此证则以微弱为热进，洪数为热退。因鼠疫为阴燥化毒，脉洪数反是热退之象，与少阴证可变鼠疫之病情脉状吻合。", ["洪", "数", "微", "弱"]], "20306": ["兼症", "鼠疫初起，证候多变，有恶寒或不恶寒，先核后热或先热后核，热核同见或见核不见热等。兼见疗疮、癍、疹、衄、嗽、咯、吐，甚则烦躁、昏谵、癫狂、痞满、腹痛、便结旁流、舌焦起刺、鼻黑如煤、目瞑耳聋、骨痿足肿、舌唇裂裂、脉厥体厥等恶证，皆热毒迫血成瘀所致。", []], "20307": ["病机", "脉数苔黄，为热毒内盛之象。患者先触死鼠，毒气传入血管，复感春阳之气，致胃热呕逆、肺伤喷血，热深内窜肺络，影响心主，故昏迷谵语。此证涉危笃，急宜清胃、泻肺、攻毒、解热重剂急进。", ["数"]], "20308": ["病机", "脉涩而无力，两尺尤弱，涩主血瘀，弱主气虚，尺弱主肾虚。产后恶露未净，积为硬块，渐大且痛，月信渐少，饮食减少，身体软弱，乃瘀血内结兼气血亏虚之证，故脉涩弱无力。", ["涩", "弱"]], "20309": ["治法", "此段论治法，无论血瘀冷积，日服真鹿角胶，日久可徐消。鹿角胶入冲任通血脉，入督脉助元阳，故能消化瘀血冷积。未涉及脉象，故脉象要素为空。", []], "20310": ["误治", "脉洪数，为热盛之象。何姓叟手足拘挛，误服桂附人参熟地等补阳之品，致面赤、脉洪数、小便闭、身重不能转侧，手不能上至鬓，足蜷曲不能移动。此误补助热，热壅经络，故重用生石膏清解，服至三月始收全功。", ["洪", "数"]], "20311": ["病机", "脉象沉弦而细，沉主里，弦主饮主痛，细主虚。蛊胀无汗，乃阳气郁闭，水气内停。用麻黄附子甘草汤行太阳之阳，泻厥阴之阴，得汗至膝上，脐以上肿消，腹仍大，小便不利，改五苓散加桂参，小便大通，腹胀遂消。", ["沉", "弦", "细"]], "20312": ["主病", "脉沉迟而弦紧，沉主里，迟主寒，弦紧为寒凝收引之象。腹中寒凉作疼，乃阴寒内盛，气血凝滞不通，故脉见沉迟弦紧。重用乌附子温阳散寒，连服近二十斤始愈，说明寒邪深痼，非大剂温通不能解。此脉象明确指向里寒实证，与腹痛、畏寒等症相应。", ["沉", "迟", "弦", "紧"]], "20313": ["主病", "脉象沉紧，沉主里，紧主寒主痛。少腹有块，痛时膨胀如拳，手足痹软，遍身冷汗，不省人事，舌苔白厚湿滑，面色暗晦，皆阴寒内盛、阳气欲脱之危候。紧脉在此示寒邪深结，非表寒可比。通脉四逆汤重用附子，温阳破阴，药后瞑眩反应而病愈，脉证相符。", ["沉", "紧"]], "20314": ["病机", "脉象洪实，右脉尤甚，洪为热盛，实为邪壅。两腿肿疼发热，服热药加剧，服凉药平平，断为相火炽盛，湿热相并下注。洪实之脉主阳热实证，右脉尤甚提示热邪偏于气分或下焦。小便不利，湿热无从宣泄，故投清热利湿之剂，重用生石膏而获效。", ["洪", "实"]], "20315": ["病机", "脉搏近六至为数，右部甚实，数为热盛，实为邪结。患者受锅炉炙热，阴血暗耗，又感外邪，表里壮热，大便两三日一行，阳明府热甚炽兼阴分虚损。数而实之脉，主里热炽盛，右部实尤显阳明实热。故用白虎加人参汤，重用石膏，佐以滋阴，热退而愈。", ["数", "实"]], "20316": ["病机", "六脉皆闭，重按亦分毫不见，乃顽痰壅塞经络，气血不通之故。原文明言“顽痰能闭脉”，脉闭非虚，实为邪闭。癫狂失心，痰火蒙蔽心窍，脉道不通，故取大承气汤加赭石、甘遂，峻下痰热，服后大便行，杂以成块之痰，脉即复出，证实脉闭由痰实所致。", []], "20317": ["病机", "脉多见沉紧，紧者毒也，紧在沉部，其毒在内。疔毒发于脏腑，非仅在于经络，故脉沉紧。重者发于鸠尾穴，名为半日疔，未发之前可见心中怔忡、鸠尾隐痛、似有漫肿，脉象沉紧即宜预防，投大剂解毒清血之品，大便实者用大黄下之，使疔暗消。此脉示毒邪深伏在内。", ["沉", "紧"]], "20318": ["病机", "脉象沉紧，紧为有毒，非伤寒之紧脉为寒也；紧而且沉，其毒在里可知。沉洪者热在里，可下其热；沉紧者毒在里，当亦可下其毒。口角生疔，疼痛异常，大便三日未行，投清热解毒药不效，脉沉紧，故用大黄降下其毒。此段以脉沉紧辨疔毒在里，与沉洪热在里可下同理。", ["沉", "紧", "洪"]], "20319": ["病机", "脉象洪而微数，右部又实而有力，洪数为热盛，右实为阳明府实。素有肺痨，咳喘呕血，舌苔白厚欲黄，心中甚热，大便二三日一行，断为温病之热盘据阳明，逼迫胃气上逆，并肺气上逆。洪数实脉主阳明里热炽盛，故治宜清源，清其温病之热，则咳喘呕血自愈。", ["洪", "数", "实"]], "20320": ["病机", "脉左右皆洪实，一息五至，为伏气化热之温病。洪实主阳明热盛，正气未衰，热邪内炽，故表里俱热、胁腹疼痛；痢虽愈而温益重，正合‘温为正病，痢为兼病’之论。脉证相参，热邪充斥内外，非虚寒可比。", ["洪", "实", "数"]], "20321": ["病机", "脉象洪实，舌苔白厚，大便两日未行，小便色黄，为外感实热已入阳明之府。洪实乃阳明燥热内结、正气尚充之象，故主府实热盛，与‘表里俱觉发热’相应，当以清下为治。", ["洪", "实"]], "20322": ["兼症", "此段未明言脉名，但述‘脉象之热较前又盛’，结合头面肿甚、舌苔中心已黄、大便三日未行，可知热势鸱张，邪已化燥成实，上攻头面而肿，内结阳明而便闭。脉热盛为邪进之征，非虚象，故仍当清泄。", []], "20323": ["病机", "脉象虽有热而重按无力，为下元素虚、旧有鸦片嗜好之体，热邪虽盛而正气已馁。重按无力主虚，故不敢投大凉之剂，恐伤中气。此脉示虚实夹杂，热浮于上而根不固，与头面肿、烦躁不能食相应。", []], "20324": ["病机", "脉浮而滑，右寸关尤甚，浮主风邪在表，滑主痰涎壅盛，右寸关候肺脾，故知风与痰互相胶漆，滞塞肺窍，发为喘症。动则作喘、呼吸迫促，皆痰风壅肺、肺失宣降之象，非肺痨虚损可比。", ["浮", "滑"]], "20325": ["病机", "脉浮而无力，数近六至，浮为风邪袭肺，数而无力为阴虚内热。病久喘剧，肺风未去而肝肾阴虚不能纳气，故喘浸剧。脉数阴虚，散风则益耗其阴，故用麻黄佐山药，既祛风又顾阴，后脉象虚数渐减，示阴渐复。", ["浮", "数", "虚"]], "20326": ["病机", "脉数五至余，弦而有力，左右皆然，弦硬中见有力，非洪滑之有力，为阴虚火实之脉。热至阳明，胃与大肠皆实，故便闭、苔起芒刺；然年过七旬，数近六至，阴分已亏，不堪承气推荡，故变通治法，兼顾其虚。", ["数", "弦", "实"]], "20327": ["预后", "服药后脉象已平，舌上芒刺已无，舌苔退强半，胁疼大愈，略思饮食，为邪热渐退、肝木得平之佳兆。脉平示病势向愈，虽大便未通，继以润下而诸病皆愈，此脉象转平为预后良好之征。", ["平"]], "20328": ["治法", "本段未出脉名，论白虎加人参汤因胁下疼而权用生山药代粳米、赭石代人参之配伍。虽无脉象，然从'大肠甚实''镇呕逆'可知其证为阳明热实兼呕逆，故以赭石重坠通燥结、降逆气，与石膏并用迫寒凉下行。脉象虽缺，病机为热实内结、胃气上逆，治法重在清通降逆。", []], "20329": ["病机", "左脉弦硬而长，为肝气郁而化火、气火并迫之象。月事五月不行，肝失疏泻，气不能下行而专于上行，兼心肝内热，迫血上输，脑部充血过度，故目胀头疼、心中发热。弦硬而长正是肝经气火亢盛、血随气逆之脉，主瘀血内结、气火上冲之病机。", ["弦", "长", "数"]], "20330": ["病机", "脉迟而无力，为阳气虚衰、寒从中生之象。痢三年不愈，赤白兼泻，平素宜热不宜凉，知其病偏于凉，脾肾阳虚不能温运，故脉迟无力。迟而无力主虚寒，与久痢滑泻、下焦不固相应，故用山药、龙眼肉温补，硫黄补火助阳，木贼升散以举下陷之阳。", ["迟", "虚"]], "20331": ["病机", "脉非洪大而重按有力，说明热邪已内结阳明之腑，非在表之洪大。温而兼疟，羸弱呕吐，大便数日未行，阳明热实兼少阳不和，故重按有力为里实之征。非洪大者，因久病羸弱、正气已伤，热虽实而脉不浮洪，主阳明腑实兼少阳之病机。", ["洪", "实"]], "20332": ["病机", "脉确有实热而至数过数，为热邪炽盛、阴分亏损之象。温病旬日，周身灼热、烦躁不安，热灼阴伤故脉数；实热内结故脉实。数而实主阳明热盛、阴液受灼，与精神恍惚、烦躁、便闭相应，故先清里用石膏山药，后以阿斯匹林解表透痧。", ["数", "实"]], "20333": ["病机", "本段论温病表里毗连、伏气因感而发之机理，举'脉数烦躁'为里热已盛之征。脉数主热，烦躁为热扰心神，说明伏气内发、热势已张，此时不可拘泥先表后里，当权衡量解表清里之先后。脉数烦躁在此标示里热偏重，为表里同病之病机关键。", ["数"]], "20334": ["病机", "脉搏至数如常而芤而无力、重按甚涩，为失血之后阴血亏虚、脉道不充之象。便血甚剧虽经止血，然血去过多，周身酸软无力、饮食减半，芤主血虚，涩主血少行滞，重按无力为气血两伤。主失血后阴血亏虚、气血不复之病机，与便时不顺利相应。", ["芤", "涩", "虚"]], "20335": ["病机", "脉左右皆洪长，重诊欠实，至数略数，两呼吸九至，为阳明热盛而阴分已伤之象。表里壮热、苔黄中黑、谵语、便黏臭灼热，皆热结阳明；洪长为热盛，欠实为热虽盛而正气已耗，数而近疾为热灼阴亏。主阳明实热兼阴伤之病机，与精神昏愦、小便短涩相应。", ["洪", "长", "数", "虚"]], "20336": ["病机", "脉象洪长，为阳明热盛之征，热邪鼓动气血故洪，邪盛于经故长；然重按不实，因身形素弱，虽挟外感实热而正气不足，故脉虽洪长却非沉实有力。此脉主温病热在阳明与少阳合病，热在阳明则脉洪长，兼入少阳则小便短少、水归大便而滑泻，脉不实亦提示正虚。", ["洪", "长", "实"]], "20337": ["治法", "原文以「脉不实故加人参」为据，说明虽用白虎汤清阳明之热，但脉象不实提示正气已虚，故加人参扶正；又因滑泻以生山药代粳米，因少阳府热致小便不利而滑泻，加白芍清少阳之热以利小便。此段从脉不实出发，阐明方药加减之理，属治法范畴。", ["实"]], "20338": ["预后", "服完药后翌晨精神顿爽，大热已退，滑泻亦见愈，脉象已近平和，说明邪热渐退而正气来复，脉由病脉转为和平，为向愈之兆；后因泻仍不止，再以滋阴清燥汤加玄参，一剂泻止，脉静身凉而全愈。此段以脉象近平和判断病势好转，属预后。", ["和平"]], "20339": ["病机", "脉近七至为数，洪大无伦、右部尤甚，右部候肺胃，洪大无伦为阳明胃府热盛之象；误服麻、桂、干姜、细辛大热之剂，火上添油，故心如火焚、舌苔黄厚、大便三日未行。此脉主阳明实热炽盛，热邪充斥内外，故脉数而洪大无伦，右部尤甚，与胃府热实相应。", ["数", "洪", "大"]], "20340": ["病机", "原文未识出脉名，但诊断明言「阳明胃府之热已实，又误服大热之剂，何异火上添油」，说明前段脉近七至、洪大无伦右部尤甚，正是胃府热实之征；服离中丹后「再诊其脉，较前和平」，热势稍解。此段以脉象变化印证阳明实热病机及误治后热减之势，属病机分析。", []], "20341": ["预后", "原文未识出脉名，仅言「翌日则脉静身凉，大便亦通下矣」。脉静指脉象由病脉转为平和安静，身凉示热退，大便通下示腑气已通，三者并见为邪去正安之象。此段以脉静身凉判断病愈，属预后。", []], "20342": ["病机", "脉洪滑有力，关前尤甚，关前候心肺，洪为热盛，滑为痰凝，有力为实，故知其心火炽盛、热痰凝郁上焦；火盛痰郁，气机不畅，故胸中满闷、呃逆连连不止。此脉主心火炽盛兼热痰凝郁上焦之实证，与胸满呃逆症候相应，故用朴硝咸寒治热、白矾消痰。", ["洪", "滑"]], "20343": ["病机", "原文反复言「脉微弱者」「脉象微弱」「脉之微弱者服桂枝则脉大」，指出脉微弱为气分不足、无阳之征，故不可发汗，宜桂枝二越婢一汤解肌；若脉有力则直投越婢汤。服桂枝后脉由微弱转大，说明桂枝助气分以托邪外出。此段以脉之微弱与有力辨气分虚实，属病机。", ["微", "弱", "大"]], "20344": ["治法", "原文以“脉象迟弱无力恶寒者”与“脉象有力恶热者”对举，明示迟弱无力为风邪伤于外廓而正气不足、阳气偏衰之象，故恶寒；有力恶热则属邪实热盛。迟弱无力主虚寒，治当重用黄芪补气、加乌头温经散寒；有力恶热则减麻黄加薄荷、花粉以清热。此段脉象实为辨证选药之依据，非专论病机。", ["迟", "弱"]], "20345": ["病机", "原文未识脉名，仅言“脉搏近七至”，属数脉范畴。劳热喘嗽、心中热且干、喘嗽连连，脉近七至为阴虚劳热、虚火内扰之象。前医方中皆用橘红，其性温燥，耗阴助热，故病益加剧。张氏投以山药、玄参、沙参、枸杞、熟地等滋阴清热之品，一剂即不觉干，证明脉数由阴虚火旺所致，非实热也。", []], "20346": ["病机", "脉浮洪而长，浮主表、洪主热盛、长主气分热炽，合为阳明经府皆热之象。风温证发热头疼咳嗽，前医误用橘红温燥，掩蔽解表清里之功，致头疼益剧。张氏去橘红加生石膏一两，清阳明气分大热，一剂而愈。此脉象说明邪已入阳明，热势鸱张，非单纯表证，故以清里为主。", ["浮", "洪", "长"]], "20347": ["病机", "脉浮而微数，右部寸关皆有力，浮主风邪在肺，数主热，右寸关有力为肺胃热盛之征。肺脏受风，医者误投毛橘红温燥之品，致热伤血络而大口吐血，咳嗽益甚。张氏以麻杏甘石汤清肺泄热，加旱三七止血，血止后加丹参化瘀，防留瘀成劳。此脉象示风热壅肺、热伤血络之病机。", ["浮", "数"]], "20348": ["误治", "原文脉细促，细主阴血不足，促主阳盛而阴不能相续，为虚弱之象。鳖甲、龟板醋炙后开破之力峻猛，肝虚弱者单用鳖甲末即觉怔忡异常，是开破太过、扰动心神之误。此段以脉细促示肝虚阴弱之体，不可妄用开破之品，否则相助为虐，反致虚虚之祸，故归为误治之戒。", ["细", "促"]], "20349": ["预后", "左脉弦硬有真气不敛之象，右脉近洪而不任重按，弦硬为肝阴亏虚、真气外泄，洪而不任重按为邪热盛而正气已虚，故断为“邪实证虚”。病者拒服补正祛邪之剂，他医误用三甲复脉汤加重大黄，致汗出不止、阴阳将离。此脉象预示正虚邪盛、预后凶险，误治则危殆。", ["弦", "硬", "洪"]], "20350": ["病机", "脉洪长甚实，左右皆然，洪主热盛、长主热炽气分、实主邪实，合为阳明实热之象。目疾久不愈，眼睑红肿、胬肉遮睛、耳聋鼻塞，兼心中发热、舌苔中心已黄，显系冬伏寒邪感春阳化热，热上攻目与耳鼻。张氏用大剂白虎汤清阳明热，加白芍、龙胆草清少阳，脉象实为伏气化热、热邪充斥阳明之明证。", ["洪", "长", "实"]], "20351": ["病机", "原文未识脉名，仅言“脉不闭”，与“身不凉”对举，说明暑热内蕴、气机未闭。暑热伏于膜原，秋感凉气激薄而暴发，腹疼作泻、暴注下迫，甚则转筋，然身不凉、脉不闭、心中热甚欲饮凉，此仍属暑热为病，与霍乱之脉闭身凉不同。脉不闭正是暑热内盛、阳气未衰之征，故重用石膏清暑泄热。", []], "20352": ["病机", "脉象数而有力，数主热，有力为实，说明温病热邪炽盛，正气尚能抗邪。肌肤热而干涩、烦躁不安、大便数日一行，皆热盛伤阴、腑气不通之象。脉证合参，病机为热盛阴亏，兼有腑实，故治以清热生津、通便之剂。", ["数", "实"]], "20353": ["病机", "脉象数而无力，重诊即无，数主热，无力为虚，说明热邪留恋而正气大虚，尤其下焦滑泻日久，阴液耗伤，元气欲脱。精神昏愦为虚热上扰神明，上焦躁渴、下焦滑泻乃虚实夹杂之候。脉证合参，病机为气阴两伤，虚热内扰。", ["数", "虚"]], "20354": ["病机", "脉数五至，似有力而非洪实，数主热，非洪实说明热不盛而正气已伤。舌苔干黑、言语不真、怔忡烦躁，皆真阴内亏、外感实热铄耗阴液之象。脉证合参，病机为真阴亏虚，外感实热相铄，故治以清热滋阴并重。", ["数", "虚"]], "20355": ["病机", "脉象滑实，关前尤甚，滑主痰，实主邪盛，关前候心肺，说明痰火充盛，上并于心。痰火扰心，神不守舍，故发时狂笑；痰火上迫脑筋，失其所司，故肢体抽掣、昏不知人。脉证合参，病机为痰火充盛，上扰心神，迫激脑筋。", ["滑", "实"]], "20356": ["病机", "脉象有力，摇摇而动，有力主邪实，摇摇而动为热盛风动之象，似将发痉。周身壮热、渴嗜饮水、疹出三日似靥非靥，皆热毒炽盛、内陷厥阴之兆。脉证合参，病机为热毒炽盛，引动肝风，故急以白虎汤加羚羊角清热熄风，防其发痉。", ["有", "力", "动"]], "20357": ["病机", "脉象洪实，洪主热盛，实主邪实，说明热毒炽盛，内扰心神。心中烦躁异常、夜间尤甚、彻夜不眠，皆热毒内炽、心神不宁之象；肤痒流黄水、皮肤脱落，为热毒外发肌肤。脉证合参，病机为热毒炽盛，内外充斥，故治以清热解毒、祛风止痒。", ["洪", "实"]], "20358": ["其他", "本段未识别出脉名，内容论述坎离砂以醋沃之发热之理，认为铁屑煆红时养气留于铁中，醋中养气亦归铁中，用时沃醋则养气感通发动而生热，以熨寒痹疼处，可驱逐凝寒、流通血脉。全段未涉及脉象与病机，故脉象要素为空。", []], "20359": ["病机", "脉象紧数，紧主寒主痛，数主热，说明毒邪内侵，正邪交争，气血壅滞。发热、恶心、瞑眩，皆毒邪内扰、胃气上逆之象。脉证合参，病机为毒邪内蕴，气血壅滞，故治以黄连、甘草、金银花、天花粉清热解毒。", ["紧", "数"]], "20360": ["病机", "此段论阴阳互根，谓阳无阴则飞越，阴无阳则凝滞，阳盛于阴则热，阴盛于阳则冷。虽未出脉名，然所论阴阳偏盛为病、相维则生、相离则死，实为脉诊阴阳总纲：脉之浮沉迟数虚实，皆可归此阴阳偏盛之理。故列病机，示脉象判别当以阴阳互根为要，非专主一脉一病。", []], "20361": ["其他", "此段评喉证诸书，辨白喉忌表之得失，非专论脉。文中仅言「脉虚者」当审其正虚，不可妄表。脉虚为正气不足之象，喉证见表而脉虚，则表散宜慎，辛凉犹可，温热升提则耗正。故以脉虚点出喉证辨治中顾护正气之要，非以脉定病。", ["虚"]], "20362": ["病机", "原文言气自脐上冲至胸腔，集于左乳下跳动不休，乃冲脉之气上冲犯胃，循虚里大络贯膈络肺，出于左乳下与动脉相并，致「动脉因之大动」。动脉主惊主痛，此则冲气上逆、胃络受扰而脉动不安，故当降冲敛冲镇冲补冲以治其源，非寻常动脉主病可比。", ["动"]], "20363": ["病机", "原文辨「伤寒脉浮滑」，谓滑则热入里，滑而兼浮是热未尽入里，半在阳明之府、半在阳明之经，故表有热里有寒。又驳痰字之误，言「脉滑亦为有痰之证」，然寒温脉滑原主阳明之热已实。浮为在表，滑为里热，浮滑并见正示热邪半表半里、阳明经府同病之机。", ["浮", "滑"]], "20364": ["误治", "原文质疑「脉浮数者可下之」，谓脉浮宜汗、脉数忌下，浮数并见而竟下之，必致病不愈而脉更加数。又言下后脉数不解、消谷善饥、久不大便，再以抵当汤下之，终至下脱。此段借浮数之脉论误下之害：浮为邪在表，数为热盛，妄下则伤正助热，脉数愈甚，示脉证相参不可孟浪攻下。", ["浮", "数"]], "20365": ["预后", "原文述误治案：本脉濡缓，清散太过则里寒外热、元阳不固，其脉反「细数微浮而濡」。若疑数为有热，然数与细浮濡并见，实为元阳摇摇欲脱之候，犹火垂垂欲灭。濡缓为湿为虚，细数为阴伤阳浮，微浮为虚阳外越，诸脉并见示真寒假热、元气将脱之危候。", ["濡", "缓", "细", "数"]], "20366": ["病机", "此段论忧愁思虑伤心，引《脉要精微论》「脑为精明之府」及心为君主之官，谓神明属阳主热，思虑耗心血，心伤则输血于脑、于肝不足，故苦惊喜忘、夜不能寐、多怒。全段未出脉名，然以心血耗伤、神明失养立论，为虚损病机之根，脉当见细弱虚数之属。", []], "20367": ["治法", "原文言少年素有痃癖，少腹胀疼，屡服开气行气之品或效而复发，「脉象无力」。脉无力示正气已虚，痃癖积久，徒行气则耗正而病根不除，故断不宜再用开气行气之药。此以脉无力定治法，示攻积当顾正气，非专主一病，列治法。", []], "20368": ["病机", "脉沉而无力，沉主里、无力为虚，非实邪内结。少腹寒积、肠结便闭，前医屡下而疼胀如故，服温药亦不觉热，反见短气，正是胸中大气下陷、无力推动温煦之征。故以升陷汤升举大气，一剂疼胀全消，气息亦顺，证明此脉所主为气虚下陷而非寒积实滞。", ["沉", "虚"]], "20369": ["病机", "脉左右皆沉而无力，再诊愈形沉弱，沉为气陷于里，弱为正气不足。前医误作气血凝滞，投破气活血之品，疼益甚且短气，说明破其气则大气愈陷。此段明言大气下陷迫挤少腹作疼，升举其气则疼自愈，故脉沉弱所主为气虚下陷、非瘀滞实证。", ["沉", "弱"]], "20370": ["其他", "本段未言脉象，专述下焦虚寒与痃癖积聚治法。鹿角胶温而且补，又善通血脉，故连服后少腹素积之硬块尽消，兼获意外之效。原文以温补通脉解释积消之理，并举阳和汤消硬疽、喻氏痞块治验相参，属治法与验案讨论，非凭脉断病，故脉象要素从缺。", []], "20371": ["治法", "本段为外敷方药组成与炮制说明，未及脉象。方中以白术健脾开痹为主，佐乳香、没药、血竭、当归活血通络，细辛、白芷、冰片、薄荷冰辛香走窜，络石藤煎汤送服以通络。全段主旨在于立健脾开痹、活血通络之治法，故归治法类，脉象要素无从摘取。", []], "20372": ["病机", "本段未载脉象，据两膝踝趾骨焮热肿痛、连臀亦肿兼目痛，断为心肝郁热、风湿热相并，壅塞血脉流通故作肿疼。原文以关节经络间邪热闭阻释肿痛之由，并述中西药驾驭之法，主旨仍在阐发病因病机，故归病机类，脉象要素从缺。", []], "20373": ["病机", "本段未言脉象，专论血海虚寒之病机。血海即冲脉，居脐两旁，赖任脉担任、带脉约束、维跷拥护、督脉督摄。其中气化虚损兼寒凉，宣通之力微，遂凝滞作疼，诸脉亦连带作疼。故治当温补气化而宣通之，疼自止。全段以冲脉气化立论，属病机分析。", []], "20374": ["妇人", "本段言脉淆乱，指产后血脉错乱无序，非具体脉象要素。产后血脉淆乱兼有瘀血，故当归活血止血、使气血各有所归，为产后良药；川芎香窜善升清阳，治清阳下陷之寒热。全段围绕产后用药立论，属妇人门，脉象要素因纯描述而缺。", []], "20375": ["误治", "左脉沉细欲无，右脉沉紧皆有数象。沉细欲无为清阳下陷、正气虚馁；沉紧而数，是瘀血受寒、重加干姜热药所伤，热郁于内。前服生化汤借川芎升举暂愈，旬余复作，误加干姜致寒热益甚、渴饮不解、身热如炙而畏冷，正合脉象所示虚陷兼热伤之误治。", ["沉", "细", "紧", "数"]], "20376": ["病机", "脉象滑动，服六味地黄丸后得之，非虚证，乃热痰郁于中焦。痰热内蕴，胃气上逆，冲气上冲，遂成上盛下虚。滑主痰，动主热，痰热相搏故脉滑动。上盛下虚则时时有荡漾之病，法当利痰清火降胃敛冲。", ["滑", "动"]], "20377": ["其他", "此段借脉象洪紧论针灸经络之奥妙，非专主病机。洪紧之脉见于疔毒，示热毒壅盛、气血壅滞。然原文主旨在于说明十二经超于迹象之外，脉象仅作引证，故归其他。", ["洪", "紧"]], "20378": ["病机", "脉左右皆弦硬，间现结脉，至数如常。弦硬为肝阳偏亢、阴血不足，结脉为气分有亏、脉道不利。症见胸中烦热、怔忡、大便干燥，皆阳盛阴亏、热迫心胃所致。", ["弦", "硬", "结"]], "20379": ["病机", "脉细参，纯系阳分偏盛阴分不足之象。脉有结象，高年虽不忌，究系气分不足。细主阴亏，结主气滞，故当大滋真阴以潜阳，少加补气之品以调脉，不可苦寒泻阳。", ["细", "结"]], "20380": ["治法", "此段为方解，未直接描述脉象。重用凉润滋真阴，少用野台参调脉，倍用生赭石引之下行，兼降胃气通大便。针对前段阳盛阴亏、脉结之证，体现滋潜兼调气机的治法。", []], "20381": ["治法", "用甘草缓脉象之弦硬，调和诸凉药之性。弦硬为肝阳亢盛、阴血不足之脉，甘草甘缓以柔肝，使脉道得舒。此方解说明药物针对脉象弦硬而设，属治法范畴。", ["弦", "硬"]], "20382": ["预后", "服药后烦热大减，脉已不结，且较前柔和。结脉消失、脉转柔和，示气分渐复、阳亢得潜，为向愈之兆。故调整方药，连服诸病皆愈，属预后良好之征。", ["结"]], "20383": ["病机", "左脉浮而弦硬，右脉浮而芤，皆不任重按，一息六至。浮弦硬为肝阳上亢、阴血亏虚，浮芤为阴血不足、阳气外浮。症见昏睡、发热、怔忡、便闭溺少，乃阴虚阳亢、热扰心神之候。", ["浮", "弦", "硬", "芤"]], "20384": ["病机", "脉左弦右芤，浮数无根，为气血亏极、阴阳不相维系之象。弦为肝血不足，芤主失血，浮数无根乃阳气外浮，故见阳气上浮而面热、外越而身热，属虚劳中极危险之证。", ["弦", "芤", "浮", "数"]], "20385": ["病机", "虚劳之证脉络多瘀，即《金匮》所谓血痹虚劳。用鸡内金化其血痹，与台参并用运化补力，使补而不滞，针对虚劳兼瘀之病机。", []], "20386": ["主病", "脉左右皆弦长，右部重按有力，一息五至，为热盛阴伤、肝胃火旺之象。弦长主肝气有余，数主热，右部有力为阳明热实，故见咳嗽夜重、身热、便燥溲赤等症。", ["弦", "长", "数"]], "20387": ["预后", "脉象由弦数转为缓和，知伏气之热已消，所余惟阴虚之热。缓和为胃气渐复、邪退之征，故热退咳减、饮食加多，预后向愈。", ["缓", "和"]], "20388": ["病机", "脉象弦数，右部尤弦而兼硬，为热久涸阴、血液亏损，兼阳明余热留滞。弦主阴伤，数主热，硬为热结，故见心中发热、咳嗽吐痰、身体瘦弱。", ["弦", "数", "硬"]], "20389": ["病机", "脉弦数者，热久涸阴血液亏损；右部弦硬，为外感余热留滞阳明之腑。热久伤肺则咳嗽吐痰，治当先清阳明余热，再滋真阴。", ["弦", "数", "硬"]], "20390": ["预后", "脉象较前和平，知外邪之热已清，阴分渐复。和平为邪退正复之象，故身心之热大减、咳痰愈半，宜专滋其阴以消余热。", ["和", "平"]], "20391": ["治法", "外感实热忌但用甘寒滞泥，致余热锢闭、热久耗阴成虚劳。若虚劳未甚而脉象仍有力者，治以白虎加人参汤变通，退实热兼退虚热。", []], "20392": ["预后", "左右脉皆细弱，重按无根，数逾七至，为真阴亏虚、气化不敛之象。细弱无根示阴精耗竭，数逾七至乃虚阳外越、气不归元。虽见日晡潮热、夜咳不能安枕、羸瘦气促等虚劳重症，然食量犹佳、大便干燥，知胃气未败，犹可挽回，故断为可治。", ["细", "弱", "数"]], "20393": ["病机", "脉仍七至强，灼热退而数不减，恍悟此数不仅因阴虚，实兼气虚。气虚则力弱难任重，犹力小强任重者体发颤，故脉数而无力。前服峻补真阴虽减灼咳，脉数未复，知单补阴不够，须辅以补气之品，使气能敛阳，数脉乃平。", ["数"]], "20394": ["治法", "此段述方药加减，未及脉象。虚劳之甚者脉络间恒多瘀滞，故加鸡内金化经络瘀滞，又恐台参作闷而佐以运化。虽无脉文，然承前脉数无根、真阴亏虚兼气虚之机，治以峻补真阴、补气敛化，兼通络瘀，使补而不滞。", []], "20395": ["预后", "脉已缓至六至，灼热咳嗽愈十之七八，足征补气有效。前脉七至强为阴虚兼气虚，今数减而缓，知气渐复、阳能敛藏。脉缓至六至虽未全平，然较前七至强已大减，故断多服数剂病自除根，示预后向愈。", ["缓", "数"]], "20396": ["预后", "灼热咳嗽全愈，脉已复常，遂停汤剂。此段未载具体脉象，然承前脉数逾七至、细弱无根，经峻补真阴、辅以补气后脉复常，示气阴来复、阳能归元，故病愈停药。脉复常为虚劳向愈之征。", []], "20397": ["病机", "脉左右皆弦细，关前微浮，两尺重按无根。弦细为肺气郁滞、痰涎阻络，关前浮示病位在上在肺；两尺无根则肾气不固、根本已虚。喘嗽遇冷加剧，乃肺胞紧缩、气化不通，加之遗传性病因，故病深难骤愈。", ["弦", "细", "浮"]], "20398": ["病机", "此段论诊断，未出脉象。承前两尺脉无根，知不但肺中气化不通、细管为痰涎滞塞，且肝肾亦有病，病因又属遗传性，非一蹴可愈。故治当培养肺中气化、疏瀹细管，并分步调补肝肾，非独治肺所能尽。", []], "20399": ["病机", "复诊脉关前不浮，至数少减，而两尺似无根。关前不浮示肺中气化渐通、痰滞稍疏，故咳喘愈三分之二、能卧睡；至数少减亦为气渐敛之征。然两尺仍无根，知肾不纳气、根本未固，故再治以纳气归肾之方。", ["浮"]], "20400": ["病机", "脉仍逾五至即数脉，行动时气息微喘，乃下焦阴分未充，不能维系阳分，致阳气上奔。数脉主虚热，此非实火，而是阴不敛阳，故当峻补真阴以摄阳。", ["数"]], "20401": ["预后", "脉至数已复常，行走动作皆不作喘，说明阴分渐充，阳有所维，气不上奔，病趋痊愈。故停汤药，以山药、梨汁善后，属预后佳象。", []], "20402": ["主病", "左脉弦细而硬，为肝血虚、津液短；右脉濡而兼沉，为湿痰留饮、中焦气化不足。外寒引动痰饮，咳喘夜不能卧，脉症相合，主气血两亏兼停饮之喘嗽。", ["弦", "细", "硬", "濡"]], "20403": ["病机", "左脉弦细为气虚，弦细兼硬为肝血虚津液短；右脉濡为湿痰留饮，濡而兼沉为中焦气化不足。痰饮上溢迫肺，故喘而且嗽，病机属气血两亏、痰饮内停。", ["弦", "细", "硬", "濡"]], "20404": ["预后", "药后喘愈咳减，右脉已不沉而稍有力，示中焦气化渐复、痰饮渐化；左脉仍近弦硬，乃肝血虚津液未充之余象。脉症均减，故再以健胃养肺滋生血脉之品调治。", ["弦", "硬"]], "20405": ["预后", "咳嗽全愈，脉亦调和如常，说明邪去正复，气血冲和，病告痊愈。脉象由病脉转为和平，为预后良好之征。", ["和平"]], "20406": ["主病", "左脉弦硬为肝肾阴液不足，右脉濡滑为肺胃痰涎充溢，两尺重按无根为下焦气化虚损、不能固摄。冬令喘嗽连连，遇暖渐愈，脉症合参，主虚损夹痰之喘嗽。", ["弦", "硬", "濡", "滑"]], "20407": ["病机", "左脉弦硬主肝肾阴液不足，右脉濡滑主肺胃痰涎充溢，两尺不任重按主下焦气化虚损不能固摄。风邪锢闭肺中，气管滞塞，痰涎壅滞，故喘嗽遇冷加重，病机为虚损夹痰、肺气郁闭。", ["弦", "硬", "濡", "滑"]], "20408": ["病机", "左脉弦硬、右脉濡、两尺虚，示病去正未复。弦硬为肝木未和，濡为脾湿未化，尺虚为肾气未充。喘嗽虽愈而劳动微喘，正是本虚未复之征，故宜培养根本。", ["弦", "濡", "虚"]], "20409": ["治法", "两尺脉虚，主下焦肾气不固。喘逆之证，气欲上脱，故用人参、赭石并用，导肺气归肾，兼培补下焦气化。尺虚为肾不纳气之根，非重用赭石引之下行不可。", ["虚"]], "20410": ["预后", "脉左右调和无病，两尺重按不虚，示正气已复，病根已除。劳动亦不作喘，为肺肾气化壮旺之验。故减赭石之降，多服以善后，巩固根本。", []], "20411": ["病机", "左脉弦而无力，右脉滑而无力，数逾五至，主肝郁化火、痰热壅肺而气阴两伤。弦为肝急，滑为痰盛，数为热炽，无力为正气已衰。故见不寐、咳喘痰壅、便燥、困顿。", ["弦", "滑", "数"]], "20412": ["病机", "至数复常而六部重按欠实、左脉仍有弦意，示痰火已退而真阴未充、肝木未柔。弦意未除，为病根尚存；重按欠实，为下焦空虚。故须峻补真阴以除病根，上病取诸下。", ["弦"]], "20413": ["病机", "脉五至强、左弦无力、右浮取有力而尺重按豁然，主肝火犯肺、迫血妄行而肾阴亏虚。弦数无力为肝急火炎，浮取有力为肺热，尺部豁然为下元不固。故咳血、喘不得卧、便燥溲赤。", ["数", "弦", "浮", "虚"]], "20414": ["预后", "脉已有根，不若从前之浮弦，示血止咳愈、气阴渐复。浮弦为肝肺浮火之象，今脉有根则火降气敛，故诸症向愈。仍须加减调服，以清余热而固本。", ["浮", "弦"]], "20415": ["预后", "脉已复常而尺部重按仍欠实，示诸病虽愈而肾阴未充。尺部欠实为下焦根本未固，故加熟地黄滋补肾阴，再服数剂以善其后，防病复萌。", []], "20416": ["病机", "左脉弦长、右脉洪长且重按颇实，说明热邪久留肺胃，屡服凉药而热不除，化燥伤津。弦长为肝热有余，洪长为肺胃热盛，重按实为邪热内结。热灼肺络则咳嗽痰血，热耗肠津则便燥溲赤，脉象与症候相应。", ["弦", "长", "洪", "实"]], "20417": ["预后", "复诊时脓血已不复吐，咳嗽少愈，二便见愈，但心中仍觉发热，脉象仍然有力。说明肺胃燥热虽减而未清，脉有力为热邪未净之征，故需再投清肺泻热之剂，以防余热复炽。", []], "20418": ["预后", "诸病皆愈，惟心中间有发热，脉象较常脉似仍有力，说明燥热余邪未尽。服山药茶汤送离中丹两月后脉始复常，热亦不复作，证明脉有力为燥热未清之象，热清则脉和，属善后调理之预后判断。", []], "20419": ["病机", "左脉近和平，右部寸关俱滑实，说明病位在肺胃。滑实为痰热内蕴之象，热久留肺胃，金畏火刑则咳嗽痰血，胃热铄膜则呕血，热输肠中则便燥。左脉和平示肝血未伤，右脉滑实主肺胃实热。", ["滑", "实"]], "20420": ["病机", "证脉合参，知外感之热久留肺胃，金畏火刑而肺伤咳嗽，胃腑久热铄致胃膜腐烂连及血管而呕血，热下输肠中且胃气上逆失传送之职故便燥。脉象滑实为肺胃实热之征，治当清肺胃热为主，养肺降胃为辅。", []], "20421": ["病机", "脉左右皆沉濡，右部寸关尤甚，沉濡主气虚阳弱。胸中气息下坠、努力呼难上达，为胸中大气下陷之征；大气下陷失统摄，则小便不禁、下焦凉甚、肢体无力。右寸关沉濡尤甚，正合肺脾大气虚陷之病机。", ["沉", "濡"]], "20422": ["病机", "脉沉濡而迟，为胸中大气下陷之剧。大气虚陷则心血循环无力，故脉沉濡而迟；肺气呼吸将停，故努力呼气难上达。大气失位无权，全身失斡旋则肢体酸软，三焦失统摄则小便不禁，下焦凉甚为外寒随陷。", ["沉", "濡", "迟"]], "20423": ["病机", "左脉弦而兼硬，右部寸关皆沉而无力。左弦硬为肝血虚而肝火旺，右寸关沉无力为胸中大气虚陷。呼吸短气、动作气短不续，为大气下陷之征；心中发热、懒食、肢体酸懒，为肝火犯胃、大气不运之候。", ["弦", "硬", "沉"]], "20424": ["病机", "左脉弦而兼硬，为肝胆郁热之明征；右寸关沉而无力，为胸中大气下陷之明征。因忍饥劳力过度，大气下陷，肝胆郁热，故脉象如此。", ["弦", "硬", "沉"]], "20425": ["病机", "脉关前沉细欲无，关后亦沉，一息不足四至，为胸中大气下陷之候。大气陷则气不上达，故呼吸费力、畏寒、食不消化，脉沉细而迟。", ["沉", "细", "迟"]], "20426": ["预后", "脉象大有起色，为药后大气渐复之佳兆。气息已顺、发冷除、饮食能化，皆脉象好转之应，故去党参、减干姜桂枝，加山药以善后。", []], "20427": ["病机", "此段论心肺之阳本虚，赖胸中大气保护；大气陷则失其保护，虚寒之象顿呈。故治以升补大气为主，培养心肺之阳为辅，病药相投。", []], "20428": ["病机", "脉浮分无力，沉分稍实，至数略迟，为胸中大气下陷兼伏气化热之象。大气陷故浮取无力，伏热故沉分稍实，大气陷而脉道迟滞故至数略迟。", ["浮", "沉", "实", "迟"]], "20429": ["病机", "脉浮分无力，为大气下陷；沉分犹实，为伏气化热；脉转稍迟，因大气下陷之脉原多迟。胃热化食，故日食四次犹饥，宜升补大气兼清伏热。", ["浮", "沉", "实", "迟"]], "20430": ["病机", "脉之迟数关乎热力，然大气下陷虽兼伏热而脉仍迟。因宗气贯心脉而行呼吸，大气陷则心机跳动受病，故脉迟，非独热力微弱所致。", ["迟", "数"]], "20431": ["病机", "脉关前沉而无力，右部尤甚，至数稍迟，为胸中大气下陷之征。大气陷则呼吸难上达，劳动益甚，气分不舒，疝气坠疼亦因气陷而加重。", ["沉", "迟"]], "20432": ["病机", "原文未提脉象，但言“诊断即此证脉参之”，结合呼吸短气、疝气下坠，辨为胸中大气下陷。大气陷则肺脏闟辟失斡旋，故呼吸短气；三焦气化失统摄，故疝气下坠。脉虽未明言，然证脉相参，当见虚而无力之象，主升补大气。", []], "20433": ["预后", "原文仅言“脉象亦大有起色”，未及具体脉形。服药三剂后短气大愈、疝气上升、下坠不疼，脉象随之好转，说明药已对证而功候未到。此段以脉象起色为凭，判断病势向愈，仍须续服加减原方。", []], "20434": ["病机", "脉大致近和平，惟两尺稍浮、按之不实。尺部候下焦，浮而不实，说明下焦气不固摄，虚阳挟热上冲。原文“气起自下焦挟热上冲”至中焦闷热、心中烦乱、上出为呃，正是尺浮不实、下焦不藏、冲气上逆之脉证相应。", ["浮"]], "20435": ["主病", "脉左右皆弦，右脉弦而且长，重诊颇实，至数照常。弦为肝脉，弦长为冲脉之象，见于右部按之颇实，又为胃气上逆之脉。肝胃冲三经气化有升无降，故食停胃中、气上冲阻、大便旬日始下，多日不下则呕吐。此脉主肝胃冲气逆、便秘呕吐之病。", ["弦", "长", "实"]], "20436": ["病机", "原文明言弦为肝脉，弦而且长则冲脉也；弦长见于右部、按之颇实，又为胃气上逆之脉。肝胃冲三经气化皆有升无降，故下焦便秘而上焦呕吐。此段以脉弦长实解释病机，主张泻肝、降胃、镇冲，使大便顺、呕吐止。", ["弦", "长", "实"]], "20437": ["兼症", "左部沉细，右部弦硬而长、大于左部数倍。左脉沉细主肝气郁结；右脉弦硬而长主冲气上冲、胃气不降。冲胃之气相并上逆，故胃脘满闷、胸中烦热、胁下胀疼、呃逆呕吐；胃气不降，故大便燥结。脉证合参，兼症分明。", ["沉", "细", "弦", "硬"]], "20438": ["病机", "左脉沉细为肝气郁结，右脉弦长为冲气上冲。冲脉上隶阳明，冲气上冲不已易致阳明胃气不降。呕吐呃逆、胃脘满闷、胸间烦热，皆冲胃之气相并冲逆之征；胁下胀疼为肝郁之征；大便燥结因胃气不降。此脉主肝郁冲逆、胃气不降之病机。", ["沉", "细", "弦", "长"]], "20439": ["预后", "连服二十余剂后，肝气已升，胃气已降，左右脉均已平安，诸病皆愈。脉象由前之沉细弦长转为平安，说明肝胃冲逆之气已平，病势向愈。惟肢体乏力、饮食不甚消化，乃病后脾胃未复，拟再补气健胃。此段以脉平为预后佳兆。", ["平"]], "20440": ["病机", "脉左部弦硬，右部弦硬而长，一息近五至，为肝火挟胃气上冲之象。弦主肝旺，硬主火盛，长主气逆，数主热。食后停滞艰于下行，气火上冲致口苦舌胀、目眩耳鸣、呃逆恶心、胸膈烦闷，大便难、小便不利，皆肝胃气逆、火盛灼津之候。", ["弦", "硬", "长", "数"]], "20441": ["预后", "原文未列具体脉象，仅言“颇见柔和”，为邪退正复之兆。前案脉弦硬而长，今转柔和，知肝火渐平、胃气渐降，故大便通、小便利、上焦诸病轻减。此脉象改善与症候好转相应，预后佳。", []], "20442": ["病机", "左脉弦长重按无力，右脉大而芤，一息五至。弦长为肝火浮动，重按无力为病久气化虚；大而芤为失血过多。吐血久不愈，心中热上冲，微喘，便溏日行数次，皆肝胃气逆、气化虚不摄之病机。", ["弦", "长", "大", "芤"]], "20443": ["病机", "左脉弦、右脉大，为肝火浮动挟胃气上冲，故吐血时觉热上逆；弦而无力为病久气化虚；大而兼芤为失血过多。喘与便频亦气化虚不摄。此脉象揭示胃气不降、肝火上冲、气血两虚之病机，治当清肝降胃、培养气血、固摄气化。", ["弦", "大", "芤"]], "20444": ["预后", "原文仅言“脉象亦较前和平”，未列具体脉象。前案脉弦大芤，今转和平，知肝火降、胃气和、气血渐复，故血止喘平、便次减少。惟心中仍热，余热未清，续服滋阴之剂而愈，预后良好。", []], "20445": ["病机", "左脉浮而动，右脉浮而濡，两尺无根，数逾五至。浮动为肝阳上亢、气火升腾，故吐血时心中热上冲、颧红面热、心中摇摇似将上脱；浮濡为气阴两虚；两尺无根、数逾五至为肾气不固、虚阳外越，属危重之候。", ["浮", "动", "濡", "数"]], "20446": ["预后", "原文仅言“脉跳动仍旧”，未列具体脉象。吐血后昏愦，脉仍跳动，知生机未绝，故能苏醒。服降逆止血药后血止，继以健脾养胃善后，身形渐复，预后转佳。", []], "20447": ["病机", "脉关前浮弦，两尺重按不实，数逾五至。关前浮弦为肝火挟痰上逆，故咳嗽加剧、痰中带血、大口吐血、心中发热、胁下作疼；两尺不实为肾虚不摄；数主热。此肝火犯肺、肾虚不纳之病机，致气逆血溢。", ["浮", "弦", "数"]], "20448": ["病机", "原文以「脉上盛下虚」概括肺金伤损、肝木横恣、胃气不降、肾气不摄之病机。上盛者肺胃之气上逆，故咳血吐血、胁下作疼；下虚者肾气不摄，故气息微喘。脉之上盛下虚正与肺伤、肝横、胃逆、肾不摄四端相应，故治宜平肝降胃润肺补肾。", ["浮", "沉"]], "20449": ["病机", "左部弦硬、右部弦长而重按不实，一息近五至。弦硬为阴分亏损、肝胆有热之象，弦长为冲气上冲、胃气上逆之征；重按不实则血亏而气亦亏。故见吐血反复、咳嗽痰血、胁下刺疼、口千灼热、便燥，皆阴亏血少、肝胃气逆所致。", ["弦", "硬", "长", "数"]], "20450": ["病机", "原文明言左脉弦硬为阴分亏损而肝胆有热，右部弦长为冲气上冲并致胃气上逆；重按不实为血亏而气亦亏。冲胃之气上逆致胃壁血管破裂而吐血咳血，口无津液、身灼热、便燥无非血少阴亏之象，故治以清肝降胃滋阴化瘀。", ["弦", "硬", "长"]], "20451": ["预后", "吐血、咳血、胁疼、灼热诸症皆愈或大减，惟口中仍干、脉仍有弦象。弦象未除，说明真阴犹亏、肝木未柔，病虽向愈而根本未复，故断为真阴犹亏，拟再进滋补真阴之剂以竟全功，属据脉判断预后转归。", ["弦"]], "20452": ["预后", "原文未载具体脉名，仅言「脉亦复常」。诸症全愈而脉复常，是阴血渐充、脏腑气机恢复和平之征，故去三七之化瘀，以熟地黄易生地黄，转用滋补以善其后。此段以脉复常作为病愈之凭据，属预后判断。", []], "20453": ["病机", "左部弦长、右部长而兼硬，一息五至。病发时胃中气化不通、满闷发热、便滞，旋即吐血咳痰，正是肝火挟冲胃之气上逆、血随气逆之候。弦长为肝火炽盛，长而兼硬为冲胃上逆，数则为热，合示肝火冲胃、血随气逆之病机。", ["弦", "长", "硬", "数"]], "20454": ["病机", "原文自释：左脉弦长因肝火炽盛，右脉长而兼硬因肝火挟冲胃之气上冲，脉既弦硬又兼数则因失血久而真阴亏损。弦硬即阴亏之象，数主热。故病机为肝火挟冲胃之气上逆、血随气升，兼失血日久阴分亏虚，治以泻肝降胃佐大滋真阴。", ["弦", "长", "硬", "数"]], "20455": ["预后", "原文未载具体脉名，只言再诊其脉「左右皆有和柔之象」。前此弦硬之脉转为和柔，是肝火已平、阴分渐复、冲胃之气不再上逆之征，故心中闷热全无、血止嗽愈、大便顺利。脉象和柔为病退向愈之凭，属预后判断。", ["和"]], "20456": ["病机", "脉弦而芤，数逾五至，左寸摇摇有动意。弦为肝气横逆，芤为失血过多，数主热，动主惊悸。此因误服柴胡升散，致肝气暴逆，血随气上，大吐不止，血脱于下则脉芤，气逆于上则脉弦数，左寸动应心，故怔忡殊甚。", ["弦", "芤", "数", "动"]], "20457": ["预后", "再诊脉芤动皆无，至数仍略数。芤为失血之脉，动为惊悸之征，今二者皆去，知血已止而怔忡亦愈，惟余略数，是阴血未全复，尚有微热。此脉象转佳，故以熟地易生地，滋阴以善后。", ["芤", "动", "数"]], "20458": ["病机", "脉浮而不实有似芤脉，而不若芤脉之硬，两尺沉分尤虚，至数微数。浮而不实为气浮于外，似芤非芤知失血未甚，两尺尤虚乃下焦亏虚，数主阴虚内热。此下血日久，阴亏气浮，肠中溃烂，故腹疼即便，心中发热。", ["浮", "芤", "虚", "数"]], "20459": ["病机", "脉近芤者，失血过多也；两尺尤虚者，下血久而阴亏，更兼下焦气化不固摄也。芤主血虚，尺虚主下焦不固，故临便腹疼为肠中溃烂，心中发热为阴虚上浮。治宜化腐生肌、滋阴固气。", ["芤", "虚"]], "20460": ["治法", "脉两尺过弱，下血日久，下焦气化不固，阴损及阳。鸦胆子善治下血但性寒凉，恐单用伤阳，故少加硫黄辅之，以温下焦、消肠中毒菌。此脉弱为用硫黄之据，非主病之脉。", ["弱"]], "20461": ["预后", "脉不若从前之浮，至数如常。前脉浮而不实，为阴亏气浮；今下血已愈，心中不热，脉亦不浮，知阴血渐复，气不外浮。惟大便溏泻，是肠虚未固，故宜健胃固肠以善后。", ["浮"]], "20462": ["病机", "脉迟而芤，两尺尤不堪重按。迟为阳虚，芤为失血，尺弱为下元虚寒。下血二年，阴损及阳，故夜间下血、腹疼、不寐，服温补下元药稍轻。此下焦虚寒，气不摄血之候。", ["迟", "芤"]], "20463": ["病机", "脉搏六至，左部弦而微硬，右部濡而无力。数为有热，弦硬为肝气横逆，濡弱为脾虚气弱。下血年余，脾虚肝旺，故饮食减少、身体羸弱、面目黄白，便时腹疼而血下多。", ["数", "弦", "硬", "濡"]], "20464": ["病机", "左部弦长主肝经血热妄行，故血随便下且量多；右部洪滑主胃中热盛，故心中发热懒食。弦长与洪滑并见，说明肝胃热盛、血不循经，虽下血多而不觉疼坠，是热迫而非气虚下陷。", ["弦", "长", "洪", "滑"]], "20465": ["预后", "复诊时弦长与洪滑之象皆减退，说明肝胃热势已衰，血得归经，故血止而少腹觉微凉。脉象由实转和，是邪退正复之兆，故可改用半清半补以善后，预后良好。", ["弦", "长", "洪", "滑"]], "20466": ["病机", "脉象近和平而稍弱不能条畅，说明气血虽未大虚，但肝经瘀血阻滞，气机不畅，故脉虽弱而不条达。右胁下物阻呼吸、言半句而止、忿怒益甚，皆肝瘀气滞、升降不利之征，脉弱正示病久正伤。", ["弱"]], "20467": ["治法", "脉虽稍弱犹能支持，说明正气尚可耐受攻伐，故可但用化瘀血之药徐徐化其瘀结。因努力太过致肝经瘀血阻络，气息升降不利，脉弱示病久正伤，治当化瘀而不伤正，瘀化则气息自调。", ["弱"]], "20468": ["病机", "此段论呼吸与肝经瘀血之关系，非直接论脉。原文谓心肺肝一系相连，下连冲任，吸入之气由血脉管下达，呼出之气由回血管上达，皆从肝经过，故血瘀肝经即妨升降气息，阐明肝瘀碍呼吸之理。", []], "20469": ["病机", "脉左右皆弦硬，关前有力，两尺重按不实，说明肝火过升、冲胃之气上逆，而上盛下虚、阴分不足。弦硬为肝火亢盛之象，火升引血上冲，故头疼眩晕夜剧；胃气不降则食滞便干；络脉壅滞则言语肢体不利。", ["弦", "硬", "实"]], "20470": ["病机", "弦为肝脉，弦硬有力见于左右，说明肝火过升，引动冲胃之气并上升，血随气逆，脑中充血过甚故作疼；上盛下虚则阴分不足，夜剧眩晕；肝火炽则心热；冲胃不降则食滞便干；络脉壅滞则言语肢体蹇涩。", ["弦", "硬", "实"]], "20471": ["预后", "复诊脉象之弦硬已减，两尺重诊有根，说明肝火冲逆之势渐平，下虚渐复，故头疼愈半、夜能安睡、诸病见愈。脉由弦硬转缓、尺部有根，是邪退正复之佳兆，故可守原方加减再服。", ["弦", "硬"]], "20472": ["病机", "诸病皆愈而脉象犹微有弦硬之意，说明肝阳未全潜降、阴分尚亏，弦为肝脉、硬为亢阳失柔之象。操劳过度则阳气复浮，头仍作疼、心中间觉热，正是阴虚阳浮、肝火上扰的余焰，故拟滋阴清热以善其后。", ["弦", "硬"]], "20473": ["预后", "脉象已和平如常，是弦硬尽去、阴阳复归冲和之象，故头不复疼、可彻夜安睡，病已向愈。既停汤药，改用生山药煮茶送服赭石细末，取山药滋真阴、赭石降胃镇肝，缓缓调养以善其后，属病愈后防复之图。", ["和平"]], "20474": ["主病", "左右皆弦硬而长、重诊甚实，弦长为肝胆气火有余、硬实为胃气不降而冲气上逆。气火升腾故头疼剧至呻吟、心中发热烦躁、间作眩晕；胃气不降失传送之职，故大便燥结非通下不行。此属气血并走于上之厥证。", ["弦", "硬", "长", "实"]], "20475": ["病机", "左脉弦硬而长主肝胆之火上升，右脉弦硬而长主胃气不降兼冲气上冲，左右皆弦硬又见阴分亏损。脏腑气化有升无降，血随气升充塞脑部排挤血管故作疼，即《内经》血之与气并走于上之厥证；便结、烦躁、眩晕皆由胃不降、肝胃火升、脑充血碍神经所致。", ["弦", "硬", "长"]], "20476": ["病机", "脉较前和平而仍有弦硬之意，是标热渐清而本阴未复，弦硬为肝阳未柔、真阴亏虚之征。故头疼止而失眠时仍作，发热烦躁眩晕皆无、大便自行，说明胃气已降、火势已平，惟余根未除，宜注意滋真阴以除病根。", ["弦", "硬"]], "20477": ["预后", "又服二十余剂后脉象和平如常，弦硬之意尽消，是阴分渐复、肝阳潜降、胃气顺降之征，故病遂全愈。此段以脉转冲和印证诸症悉除，属病愈之预后判断，说明前法滋阴降气切中病机。", ["和平"]], "20478": ["主病", "脉弦细有力而长、左右皆然，弦长为肝火亢盛、气机升逆，细为阴分不足，有力则邪实。肝火扰神故头疼甚剧、夜不能眠、动肝火即眩晕；胃气不降、饮食停滞、大便六七日不行，皆由肝胃气逆、阴亏火旺所致，故久治无效。", ["弦", "细", "长", "有力"]], "20479": ["病机", "服药四剂诸病皆轻、脉象稍见柔和，是弦硬之势渐减、肝阳渐潜、胃气渐降之兆，惟大便六日未行，说明腑气仍未通降。故于方中加重赭石、略为加减，专取镇降之力以通大便，使腑气通而病可全愈。", ["柔和"]], "20480": ["病机", "脉象仍有弦硬之意，说明真阴犹未充足。弦硬为肝气偏亢、阴血不足之象，阴不涵阳则脉失柔和。虽诸证皆愈十之八九，月信仍不甚多，亦阴血未充之征，故知其真阴未复，需再加滋阴生血之品。", ["弦", "硬"]], "20481": ["预后", "脉象大见和平，是邪热已退、气机渐复之佳兆。心中分毫不觉热，大便日行一次，均示里热已清、腑气通畅。脉由病脉转为和平，说明药证相符，病势向愈，故去玄参、沙参，减赭石、山药以善后。", ["和平"]], "20482": ["主病", "左部弦而甚硬，右部弦硬且长，为肝胃气逆、冲气上冲之象。弦硬主气火亢盛，长脉主气逆有余。症见头疼眩晕、心中发热、大便燥结，甚则猝然痿弱无力，皆气化有升无降、血随气升充塞脑部所致。", ["弦", "硬", "长"]], "20483": ["病机", "左脉弦硬为肝气挟火上升，右脉弦硬且长为胃气上逆兼冲气上冲。脏腑气化有升无降，血随气升充塞脑部，故头疼眩晕，甚则溢血著于运动神经而肢体痿弱。心中发热、饮食停滞、大便燥结，亦皆气化过升之故。", ["弦", "硬", "长"]], "20484": ["预后", "脉象大见缓和，是肝胃气逆渐平、冲气下降之征。诸病大见愈，惟步履仍须用杖、心中间有发热，示气血尚未全复、余热未尽。脉由弦硬转缓和，说明气化渐趋和平，故仍佐通活血脉之品以竟全功。", ["缓和"]], "20485": ["主病", "脉左右皆弦硬而长，重按有力，为肝气挟火、胃冲之气上逆之极。弦硬主气火亢盛，长而有力主气逆有余。症见闭目昏昏、呼之不应、喉间痰涎杜塞，知不仅痰厥，实素有脑充血病，血随气升充塞脑部所致。", ["弦", "硬", "长"]], "20486": ["治法", "本段未识脉名，主述治痰厥之手术：点天突穴令吐痰涎，豁然顿醒。醒后心中发热、头目胀疼，知痰厥虽解，脑部充血未除，故继用建瓴汤方，因病脉之所宜而略为加减，以平肝降胃、导血下行。", []], "20487": ["病机", "脉象较前和缓，是气火渐平之象；然似有上盛下虚，示阴血未充、下元不足。心中不热、头疼目胀皆愈，惟头重足轻、脚底如踏棉絮，正是上盛下虚、清阳不升之征，故添滋补之品以固下元。", ["和缓"]], "20488": ["病机", "脉左右皆弦硬，右部尤甚，弦为肝气偏亢，硬为血脉壅塞失柔。肝阳上冲，血随气升，充溢脑络，故见头疼眩晕、猝然昏倒、半身麻木、言语謇涩。脉证相参，知脑充血病根未除，虽服药年余而脉仍弦硬，正是血壅气逆之征。", ["弦", "硬"]], "20489": ["病机", "初得时脉象弦硬尤剧，弦硬乃充血之极、血管壅胀之候。血壅至极则溢于脑络，著于司运动之神经，故半身痿废。今溢血虽愈而弦硬未除，说明脑充血病根尚在，仍当治其充血，佐通活经络，不可因痿废而专补。", ["弦", "硬"]], "20490": ["预后", "脉之弦硬已愈十之七八，是肝阳渐平、血壅渐减之佳兆。故脑中不作疼，心中微热，左半身肌肉松活，麻木减轻，言语謇涩稍愈，大便通顺。脉象改善与症候好转相应，说明脑充血渐消，预后转佳，可再专治手足痿废。", ["弦", "硬"]], "20491": ["治法", "本段未言脉象，专释方义。鹿角胶为左半身引经，补益脑髓以养神经；三七化关节经络积久之瘀滞；制马钱子𥆧动神经使灵活。三药合用，针对脑充血后络瘀髓亏、神经失用而致半身痿废、言语謇涩之病机。", []], "20492": ["误治", "本段未言脉象，专论脑充血用药禁忌。黄耆补而兼升，气升则血随之上涌，使脑中充血益甚，可致血管溢血或破裂，故最忌。待充血愈而肢体痿废不愈者，乃经络瘀塞、血脉不通，此时通瘀不妨辅以黄耆，仍加赭石、牛膝监制其升，花粉调剂其温。", []], "20493": ["病机", "六脉细微无力，为气血两亏、胃气虚弱之象。饮食不顺，嚼糜方能下咽，偶觉龃龉即呕吐痰涎，是胃膜瘀阻、食管窄隘；便结如羊矢，因进食甚少、胃气无力输送。脉细微无力正合气血亏虚，故攻瘀之中须辅培养气血。", ["微", "细", "虚"]], "20494": ["病机", "脉象甚弱，因进食甚少、气血两亏所致。瘀血阻于上脘，食管窄隘而成噎膈，即西人所称胃癌。便结如羊矢，亦由饮食少、胃气弱不输送下行。脉弱与症候相参，知瘀血虽为病根而正气已虚，故宜化瘀引血下行，兼培气血。", ["弱"]], "20495": ["病机", "脉弦长按之不实，左右皆然，弦为肝气偏旺，长为气机郁逆，不实为胃气已虚。食后停滞不下，恶心，气自下上冲而吐食，是肝气犯胃、胃失和降。屡服暖胃降气药反复不愈，身体羸弱，脉弦长不实，正示本虚标实、肝胃不和之机。", ["弦", "长"]], "20496": ["病机", "原脉弦长，服药后脉不若从前之弦长，知下元气化不固，不任赭石镇降。弦长示肝胃气逆，去赭石加赤石脂固涩下焦，脉象改善，说明病机由气逆转为下元不固。", ["弦", "长"]], "20497": ["病机", "脉左右皆弦细，右脉兼牢意。弦细主气郁血少，牢主气化凝郁、饮食停滞。症见呃逆、便秘、羸弱，乃中焦气化凝郁，久病入络，气血不畅。", ["弦", "细", "牢"]], "20498": ["病机", "复诊右脉仍有牢意，胃疼未脱然。牢脉主瘀血凝滞，气化不利。虽诸病减轻，但瘀血未去，故胃疼仍在，需加消瘀血之品。", ["牢"]], "20499": ["预后", "服药四剂后胃中安然不疼，诸病皆愈，脉象已如常人。脉复常示气血调和，病邪已去，预后良好，故可再服数剂善后。", []], "20500": ["病机", "脉象沉弦，左右皆然，至数稍迟。沉弦主下焦寒凝气滞，迟主寒。少腹下坠、得温则减，乃寒滞肝脉，气血不通，故虽服热药上焦烦躁，下寒未解。", ["沉", "弦", "迟"]], "20501": ["预后", "脉左右皆微弱，至数照常，按之犹有根柢。微弱主气血虚衰，但根柢尚存，胃气未绝，故知犹可救。食结肠中、呕吐便秘，乃虚中夹实，正气虽弱尚能支。", ["微", "弱"]], "20502": ["病机", "脉搏五至（数），左右脉象皆弱，独右关重按似有力。弱主正气不足，数主热，右关有力主胃腑实热。表里俱热、呕吐便秘，乃阳明腑实，热结于内，正气已伤。", ["弱", "数"]], "20503": ["治法", "此段论治法，据脉证断为阳明胃腑蕴外感实热，肠结不通，胃气上逆致呕。治当镇降止呕、咸润开结，辅以补益，使呕止结开而正气无伤。", []], "20504": ["预后", "原文述服药后呕止结开、大便通下燥粪、表里热减，而“诊其脉仍有余热未净”，未指具体脉象，仅据脉判断热邪未尽。脉象虽未明言，但结合前症，脉当数或滑，示余热未清，故续予滋阴清热以善后。", []], "20505": ["病机", "脉搏五至为数，左部弦长、关脉弦而兼硬，右脉稍和平。弦长主肝胆气逆，硬为热灼筋急，数则热盛。肝胆之热上冲脑部，故头疼定时发作，午後加重、夜不能寐，心中觉热、饮食懒进，皆热扰之象。", ["弦", "长", "硬", "数"]], "20506": ["病机", "原文未出具体脉名，但据前段脉象论之，显系肝胆之热上冲脑部作疼。以弦长兼硬之脉，主肝火偏亢、肝阴不足、肝阳上逆，故治以清肝火、养肝阴、镇肝逆，兼升清降浊理脑部。", []], "20507": ["预后", "服药一剂病愈十之七八，“脉象亦较前和平”，说明邪热渐退、脉气趋于调和。前脉弦长兼硬，今转和平，为肝胆之火得清、肝阴渐复之兆，故减龙胆草苦寒之品，续服两剂全愈。", ["和平"]], "20508": ["病机", "脉左右皆有力，右关重按洪实。洪实有力主实热内蕴，右关候脾胃，热蕴阳明则二便不通、心中发热；肝开窍于目，肝热上攻则目干涩胀疼、视物昏花。屡服不愈者，实热未清也。", ["洪", "实", "有力"]], "20509": ["病机", "左部如常，右部弦长按之有力。右关候脾胃，弦长有力主肝木乘土、胃火循经上炎。牙疼剧甚、碍食难寐，迁延二十余日，诸药不效，正因脉见右部弦长有力，示胃火肝逆未平，非泛治牙疼可解。", ["弦", "长", "有力"]], "20510": ["病机", "左部微细、按之即无，右脉近和平而搏动力弱。左脉微细主肝血亏虚、络脉失养，故胁疼游走、久治不效，疼剧时精神昏愦；右脉弱示脾胃气衰。平肝舒肝柔肝不效者，因虚不在实，乃肝络空虚作痛。", ["微", "细", "弱"]], "20511": ["预后", "再诊胁疼已愈强半，脉象左部重按有根、右部较前有力。前脉左部微细按之即无，今重按有根，示肝血渐复、络脉得养；右部有力，脾胃气亦渐振。惟食量未增，故加健胃消食之品以善后。", ["有根", "有力"]], "20512": ["预后", "原文谓“脉象左右皆调和无病”，说明经治后气血已得安和，胁痛止、食增，脉复常度，病势向愈；惟腿膝筋骨软弱，乃病久肝肾亏虚、筋骨失养之余象，非脉象所主，故脉但示和平，预后良好。", []], "20513": ["病机", "左脉沉弦微硬，沉主里、弦主肝、硬为气郁化火伤阴之象，示肝经血虚火盛而气郁结；右脉弦而无力，乃木旺克土、脾胃受戕，健运失职，故饮食不化、痛连胃中。脉症相参，病本在肝，标在脾胃。", ["沉", "弦", "硬"]], "20514": ["病机", "左脉弦硬而沉，为肝血虚、肝火盛而气郁结之征；右脉弦而无力，乃土为木伤、脾胃失其健运。申酉属金，木遇金时气化益遏，故疼作有时。遵“厥阴不治，求之阳明”，健补脾胃以运中焦，佐理肝则痛愈。", ["弦", "硬", "沉"]], "20515": ["预后", "复诊脉见和缓，缓为胃气渐复、肝木得舒之象，与胃痛止、胁痛大减、疼时须臾自愈相应，示中焦气化渐通、病势向愈，故仍守原方加减续进。", ["缓"]], "20516": ["预后", "原文谓“肝脉亦和平如常矣”，脉复和平，知肝气已舒、气血调和，故胁痛霍然全愈；遂停汤药，以山药、鸡内金缓调脾胃以善后，防其复发。", []], "20517": ["病机", "左右两部皆弦硬，弦主肝郁、硬为气火亢盛之象，肝气横逆则两胁掀疼，左胁尤甚；肝火内扰则心中发热，木旺克土、胃气上逆则恶心欲呕。脉症合参，病机为肝郁化火、气逆犯胃。", ["弦", "硬"]], "20518": ["病机", "左部沉弦，右部沉牢，沉主里、弦主肝、牢主坚积，示肝肾经络气血瘀滞不通；故疼剧时不能动转，动气劳力则剧，心中发闷。前服补肝肾强筋骨数百剂不效，正以瘀阻未通，脉象非虚细可凭。", ["沉", "弦", "牢"]], "20519": ["病机", "原文辨“肝肾果系虚弱，其脉必细数”，今左沉弦、右沉牢，非细数虚象，乃腰际关节经络瘀而不通之实候。沉弦主肝郁，沉牢主坚积，故痛则不通，治当利关节、通经络，不可妄补。", ["沉", "弦", "牢"]], "20520": ["预后", "原文述服药后“脉象虽有起色，仍未复常”，继服数剂后“脉已复常”，病遂除根。脉象由未复常渐至复常，反映药后气血渐和、病邪渐退之机转，故以脉象变化判断预后转归，非以脉主病。", []], "20521": ["病机", "原文指出“脉气分甚虚、脉知其下焦虚寒”，又强调腰疼“由于气血瘀者颇多”，不可拘于肝肾虚。脉气虚提示气分不足，下焦虚寒则温运无力，气血易滞而作痛，故脉虚在此主气虚寒凝、瘀阻腰络之病机。", ["虚"]], "20522": ["病机", "脉“左右皆弦细无力，两尺尤甚，至数稍迟”。弦细无力主气血不足、筋脉失养；两尺尤甚提示下焦肾气亏虚；至数稍迟为阳虚寒凝之象。合而观之，此脉主下焦虚寒、气血不能温养腰腿之病机。", ["弦", "细", "迟"]], "20523": ["病机", "原文谓“下焦相火虚衰，是以易为寒侵”，又“细审其脉，实更兼气虚不能充体，即不能达于四肢以运化药力”。虽未明言脉象，但据脉断为相火虚衰兼气虚，故药力难达，主下焦火衰、气虚寒侵之病机。", []], "20524": ["预后", "复诊“脉象较前似稍有力”，腿疼稍轻而仍不能任地。脉由无力渐转有力，示药后气机稍振、病有起色，然仍不能任地，说明下焦虚寒未复。此以脉象变化判断药后反应及病势进退，属预后观察。", []], "20525": ["预后", "原文“脉象已调和无病”，腿疼大减，可扶杖行步。脉调和无病为气血冲和、病邪已退之征，故可停汤药，改服丸药缓图。此以脉象复常判断病愈向愈，属预后转归，非主病之脉。", ["和平"]], "20526": ["病机", "两腕肿甚，按之移时水气四开始见脉。左部弦而兼硬，主肝胆郁热、木失柔顺；右部滑而颇实，主胃中湿热壅盛。一息近五至为热象。合之，此脉主肝胃郁热、水气内停之病机，与周身肿、便干溲赤相应。", ["弦", "硬", "滑", "实"]], "20527": ["病机", "原文引《金匮》“风水脉浮”，因肿甚难辨浮沉，然有汗受风，断为风水。左脉弦硬为肝胆郁热，右脉滑而实为风束胃中浸生热。故脉浮主风水，弦硬滑实主肝胃郁热，合为风水兼肝胃热之病机。", ["浮", "弦", "硬", "滑"]], "20528": ["预后", "原文“脉象已近和平”是描述复诊时脉象趋于平和，非具体脉象要素。此表明服药后周身透汗、热退、小便通利、肿胀大减，病邪已衰，正气渐复，故脉近和平，属病退向愈之象，预后良好，可再以滋阴利水善后。", []], "20529": ["病机", "左脉弦细，弦主肝郁，细主阴血不足，肝疏泄失职则小便不利；右脉弦而微硬，弦硬为胃有蕴热，热灼阴津；脉数六至为阴虚内热之征。诸脉合参，示阴分虚损、肝肾伏热、胃热下溜，致水液代谢失常，发为水肿、潮热、小便赤涩。", ["弦", "细", "硬", "数"]], "20530": ["病机", "原文明言“左脉弦细，则肝之疏泄力减”，“右脉弦硬，胃之蕴热下溜”。弦细为肝阴不足、疏泄无力；弦硬为胃热内蕴。此脉象揭示阴分虚损、肾脏虚热生炎、肝失疏泄、胃热下溜，三焦水道不利，积成水肿，故治以大滋真阴为主。", ["弦", "细", "硬"]], "20531": ["病机", "原文“脉仍数逾五至”，数脉主热，此热由阴分未充、虚热内生所致。虽小便已利、肿消半、日晡热除，但心中仍发热、脉数未减，说明真阴尚未充足，虚热未清，故仍宜注重补真阴，少佐利水。", ["数"]], "20532": ["预后", "原文“脉已复常”是描述肿消后脉象恢复正常，非具体脉象要素。此表明药后肿尽消、脉复常，病已向愈，故停汤药，以山药粥、梨汁善后，属预后良好之象。", []], "20533": ["病机", "原文“脉象无火而微浮”，微浮主表、主风，无火象说明非实热。结合腹胀漫肿、喘息迫促、痰涎杜塞、苔淡白、小便赤涩，此脉示风水相搏、肺失宣降、水气泛溢，故拟遵《金匮》治风水之法，从表散水。", ["浮"]], "20534": ["误治", "原文“诊其脉仍无火象”，未识具体脉名。前服风水方后汗出喘愈，但添心中热渴、不思饮食，脉仍无火象，说明痰饮湿胜、热象不显，故当“舍脉从证”，以清热重剂治其热渴，属凭脉辨证后调整治法。", []], "20535": ["病机", "左脉弦长有力且甚硬，弦长硬为肝经热盛、气火有余；右脉有力而微浮，为胃热兼表或热势上浮。结合身目黄如橘、小便黄赤、心中热渴，此脉示肝胆湿热蕴结、胃热炽盛，发为阳黄，故脉见弦长硬而有力。", ["弦", "长", "硬", "浮"]], "20536": ["病机", "原文未直接描述脉象，但指出“肝胆之脉太盛”，说明肝胆热盛是黄疸病机关键。肝蕴热，外感束之，热益甚，胆管肿胀，胆汁不能输于小肠而溢于血中，随血运周身故身黄，随水饮渗入膀胱故小便黄，胆汁不入小肠故大便色白。脉盛反映肝胆实热，主黄疸证。", []], "20537": ["兼症", "右脉犹浮，说明表证未罢。此证舌苔犹白，右脉浮，为外感表邪未尽，故于初次服药后加服阿斯匹林以得微汗解表。浮脉主表，与舌苔白、未罢之表证相应，提示在治疗黄疸同时需兼顾解表。", ["浮"]], "20538": ["预后", "脉象较前和缓，说明病情好转。服药后周身得汗，渴热减轻，能进饮食，大便变黑，小便黄色稍淡，身黄见退，脉由前之弦盛转为和缓，反映邪热渐退，肝胆气机趋于调和，故为向愈之兆。", ["缓"]], "20539": ["预后", "脉象已和平如常，说明病邪已退，气血调和。周身黄减三分之二，小便黄日见清减，脉复常态，为疾病向愈、正气来复之象，故停药，以饮食调养善后，两旬全愈。", ["和平"]], "20540": ["主病", "脉象沉细，左部更沉细欲无，说明阳气衰微，气血不足。周身黄色甚暗似兼灰色，饮食减少，肢体酸懒无力，大便完谷不化，皆脾肾阳虚、寒湿内盛之象。沉细主里虚，左部尤甚提示肝肾阳气亏虚，此属阴黄重证。", ["沉", "细"]], "20541": ["预后", "原文仅言“脉象亦大有起色”，未具体描述脉形。服药后饮食增加，消化佳良，体力稍振，身黄退半，脉象大有起色，说明正气渐复，病势向愈，故仍服丸药并加减汤药以巩固疗效。", []], "20542": ["预后", "原文未直接描述脉象，但言“脉象已复其常”，说明脉已恢复正常。周身黄退十分之七，身形渐强壮，脉复常态，为病愈佳兆，故减丸药，汤药中加山药以善后。", []], "20543": ["病机", "脉象左部弦而有力，右部滑而有力。弦主肝胆，滑主痰湿或实热。左弦右滑有力，说明肝胆热盛，痰湿内蕴。症见周身面目俱黄，饮食懒进，呕吐，心中发热，小便黄甚，大便白而干涩，皆肝胆湿热、胆汁不循常道之象，脉证相符。", ["弦", "滑"]], "20544": ["主病", "脉左右皆弦细，左部弦而兼硬，一息九十二至为数。弦细并见，示气血两亏而肝木失养；左弦硬为肝肾阴亏、筋脉失柔之象。下痢两月，赤白鲜血转为血水脂膜、腐败腥臭，日二十余次，羸弱口干怔忡，皆久痢伤阴耗血、肠膜溃败之候，脉与症合，主痢久肠溃、气血两伤。", ["弦", "细", "硬", "数"]], "20545": ["病机", "原文自释“脉象弦细者，气血两亏也”“左脉细而硬者，肝肾之阴亏甚也”。弦为肝脉，细为血少，硬则阴亏失濡、脉道不柔。痢久肠中脂膜腐败溃烂，纯下血水脂膜，下血过多则口干怔忡，正合气血两亏、肝肾阴亏之机，故主虚中夹毒、宜培养气血佐解毒化瘀。", ["弦", "细", "硬"]], "20546": ["预后", "复诊脉象犹弦而左部不若从前之硬，是阴亏渐复、脉道稍柔之征。前诊左脉细硬为肝肾阴亏甚，今硬减而弦存，说明药已中病，故“病大见愈”，怔忡除、便次减、间见好粪。然弦脉未去、血粪相杂，示余邪未清，或有毒菌伏藏，故仍须加减消解，属预后转佳而未尽之候。", ["弦"]], "20547": ["主病", "泄泻旬日继变泻为痢，日十余次赤白参半，下坠腹疼，身益羸弱，脉象亦弱而左略胜于右。弱脉主气血不足，久痢伤中、脾胃虚弱故脉弱；左候肝胆，左力略胜右，提示虚中挟有肝热。脉弱与羸弱、久痢不愈相应，主气血两虚而兼肝胆郁热之痢。", ["弱"]], "20548": ["病机", "原文明言“左右脉皆弱者，气血两虚也”，左略胜右为“肝胆虚而挟热”。弱脉应指无力，是气血不足、脉道不充之象；虚而挟热，热非实热，故不可过用凉药，虚又不受峻补，须补品兼能泻热，使肝胆虚热解而痢自愈。此段由脉弱推演虚中挟热之病机与治法分寸。", ["弱"]], "20549": ["病机", "左部弦而有力，右部浮而濡、重按不实。左弦有力为肝胆气盛化热，右浮濡不实为脾胃气虚、湿滞中焦。腹疼后重、下痢赤白、日七八次，饮食减少、肢体酸软，正合肝热犯脾、脾虚湿滞、冷热相搏之痢。脉象左右分候，揭示肝胆实热与脾胃虚弱并存之病机。", ["弦", "浮", "濡"]], "20550": ["病机", "本段未出具体脉名，以“证脉合参”立论。由上证之左弦有力、右浮濡不实合参，断为肝胆因劳心生热、脾胃因生冷有伤，冷热相搏遂致成痢。其病机要点在肝热与脾虚并存、寒热错杂，故治法当清肝胆之热而兼顾脾胃之虚，脉证互参以定虚实寒热之偏。", []], "20551": ["预后", "再诊脉左部已和平如常，而右部仍如从前之浮濡不实。左候肝胆，左脉和平示肝热已清、腹疼后重皆除、下痢转白；右候脾胃，右脉未复示脾虚湿滞尚存。故知病势向愈而脾胃未健，再投温补脾胃之剂当愈，属预后良好、以脉定后续治法之段。", ["和平"]], "20552": ["病机", "左脉弦而硬，右脉弦而浮，搏五至。弦为肝木之象，硬则木失柔和、肝火内炽；浮弦见于右部，示木邪犯胃、胃气不降。故下痢鲜血、后重甚剧、腹疼即须入厕，皆肝火迫肠、木横克土之征；不能进食、恶心、心中发热，正是胃腑被木火扰攘、和降失职之候。", ["弦", "硬", "浮", "数"]], "20553": ["兼症", "左部较前和平，是肝火已减、血痢止而次数大减；右部仍有浮弦之象，说明木邪犯胃之势未全退，胃腑尚被扰动，故仍不能饮食、心中发热，惟恶心已除。浮弦在右，主木郁土中、胃气未和，故须再清胃腑方能进食，此脉症相应之处。", ["弦", "浮"]], "20554": ["病机", "六部皆弱而两尺尤甚，弱为气血虚衰、脾肾不足之象。尺弱尤甚，是下焦命火式微、肾关不固；脾虚不能运化，故泻十四五次、泻后疼益甚。过午发热、夜半渐愈，乃阳虚气陷、虚阳浮扰之候，脉弱正合脾肾两虚、滑泻不止之病机。", ["弱"]], "20555": ["预后", "原文未载具体脉名，仅言脉象较前有力。前段六部皆弱、两尺尤甚，今服药三剂泻愈强半而脉转有力，是脾肾虚衰渐复、正气来复之佳兆。脉由弱转有力，说明药证相合、阳气渐振，故可原方加减再服，属预后向愈之判断。", []], "20556": ["病机", "左部弦硬，右部微浮重按无力。弦硬为肝木失柔、疏泄太过之象；右浮而重按无力，是气血虚弱、肾失蛰藏。肝疏泄过甚则肾不能藏，故小便完时精髓随出；风袭尿道则刺痒。身体衰弱、精神短少，正合右脉无力之虚象，脉症相参，病在肝风疏泄、肾气不固。", ["弦", "硬", "浮"]], "20557": ["病机", "左脉弦硬为肝脉挟风之象，风性劲急故脉失柔和；右脉浮而无力，因病久气血虚弱、脉不任按。原文谓风气通于肝、肝行肾之气，风袭入肝则疏泄太过，肾失蛰藏而精随尿出；尿道刺痒尤显风袭。弦硬主肝风，浮而无力主气血虚，二者合示风扰而正虚之病机。", ["弦", "硬", "浮"]], "20558": ["病机", "脉弦细沉微，不足四至。弦主痛、主寒凝，细为阳虚血少，沉微则阳气衰微、阴寒内盛。下焦疼甚且凉甚，正是寒凝气滞、阳不温通之征；小便因受寒而凝滞不出，脉沉微不足四至恰合阳虚寒凝、气化不行之病机，故当以温热之药通之。", ["弦", "细", "沉", "微"]], "20559": ["预后", "原文未载具体脉名，仅言脉已复常。前段脉弦细沉微、不足四至，为阳虚寒凝之象；服药三剂后小便通下、腹疼觉凉全愈而脉复常，是寒凝已散、阳气来复、气化复行之明证。脉复常即预后向愈之据，故停汤药而以硫黄温补善后。", []], "20560": ["主病", "脉左部浮弦，右脉尤弦而兼硬，一息五至。浮弦为肝血虚损、肝火上升之象，阴虚不能潜阳故不寐；右脉弦硬乃胃中酸汁短少、胃气上逆，酸少不化食，气逆不降，故食停胃脘、大便燥结。数脉主热，合参诸症，病机为肝胃同病、阴虚火旺。", ["浮", "弦", "硬", "数"]], "20561": ["病机", "左脉浮弦主肝血虚损兼肝火上升，阴虚不能潜阳故不寐；右脉弦而兼硬主胃中酸汁短少、胃气上逆，酸少不化食，气逆不传送，故食停胃脘、大便燥结。脉象直接揭示肝胃同病、虚实夹杂之病机，治宜清肝火、生肝血、降胃气、滋胃汁。", ["浮", "弦", "硬"]], "20562": ["预后", "服药两剂后脉象不若从前之弦硬，说明肝火渐清、胃气渐降，弦硬减轻为病退之兆。夜寐转安、心热已除、食量稍增，皆与脉象缓和相应；大便仍滞，是胃腑气化尚未全复。脉症合参，示病情向愈，故原方略为加减再服。", ["弦", "硬"]], "20563": ["预后", "诸症悉愈而脉象仍有弦硬之意，说明肝胃余热未清、气机尚未全和。弦硬为肝火未净、胃气未柔之象，虽症状已除，脉未和平，故将龙眼肉加至八钱，多服数剂以善其后，防其复发。此段以脉测证，示病虽愈而脉未复，仍需调养。", ["弦", "硬"]], "20564": ["主病", "左部弦硬为肝火亢盛、阴血亏虚，故心热、不寐、怔忡；右部近滑重诊不实，滑主痰热，不实为胃气虚弱，痰热内扰故惊悸、短气、懒食；一息近六至为数，主热盛阴伤，故便燥。脉象示肝火挟痰热上扰、胃虚不降之病机。", ["弦", "硬", "滑", "数"]], "20565": ["预后", "左部稍见柔和，是肝火渐平、阴血渐复之象；右部仍有滑象，为胃中痰热未净；至数稍缓，数脉得缓则热减。惊悸愈、气息顺、便结愈，皆与脉象好转相应。脉症合参，示病势向愈，故原方略为加减再服。", ["弦", "滑", "缓"]], "20566": ["病机", "脉左右皆弦硬异常，弦为肝风，硬为血随气升、脑充血之象。肝风内动则发痫风，血菀于上则脑热、疼、眩晕。脉象揭示痫风与脑充血同源，皆由肝阳化风、气血上逆所致，故断为痫风兼脑充血。", ["弦", "硬"]], "20567": ["预后", "连服二十剂后脉象和平如常，脑热疼眩晕皆除，说明肝阳已平、气血调和，脑充血之病机已解。脉仍有力时是余热未净，继服则脉转和平，为病愈之征。脉象和平如常，故可再治痫风。", ["和平"]], "20568": ["兼症", "原文未识脉名，仅言“诊其脉亦有热象”，提示热邪内蕴。证候见闭目昏昏、身躯后挺、两手紧握，为热盛动风、筋脉拘急之象；舌肿不能吮乳、便溏、皮肤发热，乃热郁气机、脾胃不运。脉热象与壮热、抽搐并见，主热极生风、内扰心神之病机。", []], "20569": ["病机", "脉紧而头向后仰，为督脉因寒紧缩、筋脉拘急之象；脉象细数无力，细为血虚，数为热，无力为虚，合之则阴血亏虚、虚热内扰。潮热颧红、昏睡露睛、抽掣吐泻，皆阴亏血少、肝风内动、脾胃虚弱之候。脉细数无力正合虚风内动、寒热错杂之病机。", ["紧", "细", "数", "虚"]], "20570": ["病机", "原文言“脉因寒紧缩”，紧脉主寒主痛。疟久伤脾，又服消导开破，中焦气化愈伤，寒痰留饮上溢，迫心肺之阳上浮，故面红身热而病本实凉。手足抽掣、头向后仰，为血虚肝风内动、督脉因寒紧缩。脉紧正应寒痰内阻、阳气不达之病机。", ["紧"]], "20571": ["预后", "原文未识脉名，仅言“脉象亦较前有力”，为药后正气渐复之兆。前证潮热泄泻，今皆愈而脉转有力，说明脾胃阳气来复、邪气渐退。脉由无力转有力，反映中焦气化恢复，故去白术、减干姜而收全功，属预后向愈之象。", []], "20572": ["病机", "脉微细欲无，微为阳衰，细为阴血不足，合之则气血大亏、阳气欲脱。吐泻交作、肌肤灼热而脉反微细，乃脾胃虚寒、不能腐熟水谷，寒饮内积、格阳于外之真寒假热证。昏睡露睛、神气虚弱，皆阳气衰微、神失所养之候。", ["微", "细"]], "20573": ["病机", "脉转微细，为脾胃虚寒、气血亏损之征。所食不化精微而多成寒饮，积胃溢膈，排挤心肺之阳外出，故周身灼热而脉反微细，此里有真寒外作假热。昏睡露睛因眼胞属脾胃、虚寒紧缩；肢体抽掣因气血不能上达濡润脑髓神经。脉微细正主虚寒内盛、气血不荣之病机。", ["微", "细"]], "20574": ["病机", "左部弦细，弦为肝木偏旺，细为血少；右部虚濡，虚为脾胃气弱，濡为湿滞。至数兼迟，迟则为寒。食后吐、便完谷、腿软委地，皆脾胃虚寒、肝木乘土、气血不荣筋脉之候。脉弦细虚濡而迟，正合慢脾风将成、真寒假热之病机。", ["弦", "细", "虚", "濡"]], "20575": ["病机", "脉转弦细虚濡，至数且迟，弦细为肝血不足、木失柔养，虚濡为脾胃气弱、湿浊内停，迟则为寒。吐泻、偶痿废不能行步，皆慢脾风朕兆；周身灼热而脉反虚濡迟，显系内有真寒外有假热。脉象正说明脾胃虚寒、肝风内动、气血亏虚之病机。", ["弦", "细", "虚", "濡"]], "20576": ["主病", "六脉滑实，两寸尤甚，一息五至，滑主痰盛，实主邪壅，数则为热。寸部候心肺，滑实偏聚于上，说明痰热壅盛于上焦心脑，扰乱神明，故见言语错乱、精神昏瞀、忿怒狂歌、烦躁不寐、以手挠胸。身形似强壮而脉实，为实证非虚象，痰火内闭为其病机核心。", ["滑", "实", "数"]], "20577": ["病机", "原文指出关前脉滑实太过，关前候心肺，滑实为热痰壅盛之象。痰火循心脑相通之路而上壅，杜塞神明往来之道，致神明隔碍、失其常性，遂成癫狂失心。故治当开通重坠，引痰火下行，使血管流通、神明复常，此段重在以脉释癫狂之病机。", ["滑", "实"]], "20578": ["预后", "服药三次、通下痰涎后精神稍明了，而脉仍见滑实之象，身体未见衰弱。脉象未变说明顽痰热邪尚未尽除，邪实仍在而正气未伤，故可再投重剂攻下。此段以脉仍滑实判断病邪未净、攻邪尚可续进，属凭脉测预后与转归。", ["滑", "实"]], "20579": ["预后", "连下顽痰之后精神大见明了，脉象亦不复滑实，说明痰热壅塞之势已解，邪去而神明渐复。脉由滑实转为不复滑实，是邪退正安之征，故改用平和之剂调治。此段以脉象改善作为病情向愈、可停峻攻的依据，属预后判断。", ["滑", "实"]], "20580": ["主病", "左脉弦而硬，右脉弦而长，两尺重按不实，一息五至。弦主肝病与气逆，硬为肝血虚而火炽，长为冲气上逆之象。气火挟痰上冲，滞塞喉间、冲激脑部，故心中满闷发热、不思饮食、气上冲、精神昏瞀、言语支离。两尺不实示下焦不固，冲气易上，本段以脉象统括诸症之主病。", ["弦", "硬", "长"]], "20581": ["病机", "原文自释左脉弦硬为肝血虚而火炽盛，右脉弦长为冲气挟胃气上冲，即方书所谓直上直下、冲脉昭昭之状；两尺不实为下焦气化不固、有虚脱之象，故冲气易挟胃气上冲。气火痰涎上冲滞塞喉间、冲激脑部，致神经错乱、言语失常。此段纯以脉释病机，主张降胃敛冲镇肝兼凉润滋阴。", ["弦", "硬", "长"]], "20582": ["预后", "连服四剂后满闷发热大愈、能进饮食，气上冲已不复上干神经致错乱，左右脉皆较前平和，惟尺部仍然欠实。脉转平和说明肝火冲气上逆之势已减，病向愈；尺仍欠实提示下焦虚脱之根未除，故拟兼培补下元以除病根。此段凭脉判断疗效与余邪，属预后。", ["弦", "长"]], "20583": ["预后", "原文仅言连服六剂后诸病皆愈、脉亦复常，未识别出具体脉名，故脉象要素为空。脉复常与诸病皆愈相应，说明气火痰涎上冲之病机已解，下焦渐固，神明言语复其常态。此段以脉恢复正常作为疾病痊愈的最终判断，属预后收尾之文。", []], "20584": ["病机", "原文谓“其脉上盛下虚”，上盛为痰浊壅于胃脘，下虚为肾气不纳，故见胃口满闷有痰。此脉象说明痰饮内停、肾虚不摄之病机，与《金匮》“短气有微饮”相应，故用肾气丸加赭石，以地黄补肾、赭石降逆，使痰饮从下焦分消，药后胸次豁然，正合上盛下虚之治。", ["浮", "沉"]], "20585": ["病机", "原文谓“脉象似有力而不实，一息五至”，似有力为邪热内结阳明之假象，不实为气血已亏之本质，数脉主热。此脉说明阳明腑实而正气难支，故见舌苔黄黑而干、谵语不休、两目直视、筋惕不安，大便四日未行，皆热盛津伤、肝风内动之候，属病实脉虚之危象。", ["数", "虚"]], "20586": ["病机", "原文断为“病实脉虚之证”，脉虚示气血亏损难抗外邪。舌苔黑干为阳明热实津不上潮，两目直视为肝火上冲，两手筋惕为肝热血耗内风将动，谵语不省为邪热昏神。此脉说明正虚邪实、热盛伤阴之病机，故拟白虎加人参汤辅滋补真阴，清热与扶正并行。", ["虚"]], "20587": ["预后", "原文谓“至数较前稍缓，其浮分不若从前有力，而重按却比从前有根底”，缓为胃气渐复，浮分减力而重按有根为邪退正复之象。此脉说明药后热势渐衰、真阴渐复，故大便得下、舌苔较愈、目能瞬、筋惕已愈强半，皆佳兆，预后向愈，仍须清余热复真阴。", ["浮", "缓"]], "20588": ["其他", "此段仅为“伤寒脉闭”之标题，未载具体脉象描述与症候，故脉象要素为空。其主旨标示伤寒病中脉闭一证，属篇目分类，不涉病机分析，亦无预后、治法等内容可据，仅作条目提示，故归入其他类。", []], "20589": ["其他", "此段仅述天津张姓患者年三十八，季冬得伤寒证“且无脉”，未出具体脉象写法，故脉象要素为空。其文为病案起首，交代时令、年龄与无脉之症，尚未展开病机，主旨属病案叙述，故归其他类，待后文诊断段方论脉闭之理。", []], "20590": ["主病", "原文谓“六脉皆无”，即脉闭之象，伴内外俱觉寒凉、头疼、气息微喘、身体寒战。六脉皆无说明风寒深入、经络阻塞、阳气不能外达，故脉道不通而身寒战、喘促。此脉主伤寒脉闭之病，与寒邪束表、正气被遏之候相应，为后文麻黄汤加补气之治提供依据。", []], "20591": ["病机", "原文未出具体脉象，然承前“六脉皆无”而论，断为“风寒深入阻塞经络，是以脉闭”。其身体素弱又重感，正气不足则寒邪深陷，经络阻遏故脉道不通。此段说明脉闭之病机在正虚邪陷、寒凝经络，故治以麻黄汤重加补气，补正逐邪，使脉复邪出。", []], "20592": ["预后", "原文述服药后周身得汗，其脉即出，诸病皆愈。此段未直接描述具体脉象，但指出汗出后脉象由隐伏转为显现，是邪随汗解、正气来复之征。脉能出而病愈，说明先前脉不出为邪郁阳遏，今得汗则表解阳通，故预后良好。", []], "20593": ["病机", "原文指出少阴伤寒脉原微细，微细之至可至于无。此案脉微细，但见头疼、微喘、寒战等太阳症，而无蜷卧、但欲寐之少阴症，故从太阳治。脉微细在此反映正虚邪郁，非少阴本证，故用麻黄汤加生黄耆扶正逐邪。", ["微", "细"]], "20594": ["其他", "此段仅为标题“伤寒脉闭”，未涉及具体脉象描述或病机分析，故脉象要素为空。主旨为标示病证名称，属其他类。", []], "20595": ["其他", "此段为病案起首，仅述患者年龄与所得病证“伤寒脉闭”，未载脉象细节及病机分析，故脉象要素为空，归类为其他。", []], "20596": ["主病", "原文载证候头疼、身冷、恶寒、无汗、心中发热，六脉皆闭。脉闭指脉象沉伏不出，为风寒外束、阳气郁遏之象。外寒闭表则无汗恶寒身冷，阳郁化热则心中发热，脉闭正是邪郁卫阳、脉道不利之主病表现。", []], "20597": ["病机", "原文诊断脉闭身寒，因身形羸弱、汗出感寒，风寒深入而脉道闭阻；又肋下素有郁气，肝胆火郁，外感激动郁火故心中觉热。脉闭在此反映正虚寒闭、郁火内伏之病机，故治法发表为主，兼清热理郁补正。", []], "20598": ["预后", "原文述服药后汗出遍体，翌日复诊其脉已出，五至无力，已不恶寒，心中仍觉发热。脉已出而五至无力，说明邪已外解，但正气尚虚，余热未清。脉数无力为汗后正伤、余热未净之象，故去麻黄，加玄参、山药养正清热以善后。", ["数", "虚"]], "20599": ["病机", "原文载寒战腹疼益甚，脉六部皆微细欲无，断为直中少阴之伤寒。微细欲无乃阳气衰微、阴寒内盛，脉道鼓动无力所致。少阴中寒，正虚邪陷，故见寒战腹疼，脉微细欲无正是少阴阳衰寒盛之病机反映。", ["微", "细"]], "20600": ["病机", "原文述麻黄附子细辛汤证由太阳传少阴，故脉沉；寒战脉沉细，因恣食寒凉直中少阴，内外寒凉夹攻，太阳无反应之力。脉沉主里，细主虚寒，说明少阴里虚寒盛，阳气不能外达，故外寒战而内腹疼，与发热脉沉之太阳少阴两感病机相应。", ["沉", "细"]], "20601": ["主病", "脉极洪实、左右皆然，为阳明腑实之证。洪实主热盛邪实，热与燥屎内结，故大便数日一行甚干燥、舌苔白厚中心微黄。通常阳明腑实脉偏右手，此左右皆洪实，因心肝积有内热，挟阳明之热上攻，故脑中胀疼、烦躁不安。", ["洪", "实"]], "20602": ["病机", "脉数逾六至主热盛，左部细而浮、不任重按，为阴亏热扰、正气已虚；右部弦细、重诊似有力，示热邪内陷、肝风内动。症见目睛上窜、身体颤动、神昏不语、舌缩而干、大便旬日未行，皆热灼真阴、风火相煽之象，脉症合参属热陷厥阴、阴亏风动之危候。", ["数", "细", "浮", "弦"]], "20603": ["预后", "复诊脉数已减，不若从前之浮弦，右部重诊仍似有力，说明热势渐退、浮弦之象已缓，但右部重按仍有力，示阳明腑实未净、里热犹存。症见目睛不上窜、身体安稳、嗳声止、气息匀，为风火渐平之兆，然大便未通、肌肤犹热，故脉仍数而右部有力，预后向愈而余邪未清。", ["数", "浮", "弦"]], "20604": ["病机", "脉六部皆微弱无力，为气血大虚之象。前证热退而仍不能言，非热闭可知，乃胸中大气虚陷，不能上达舌本，故脉微弱无力。大便未通而间有努力欲便之象，属气虚无力推运，非实结。此脉主正气亏虚、大气下陷，与神清不能言、便难相应。", ["微", "弱"]], "20605": ["病机", "脉象似有力而不实，左部尤不任重按，一分钟百零二至，摇摇有动象。数主热，动主惊惕不安，似有力而不实、不任重按为正气已虚、邪热内扰。初受外感误汗伤阴，热陷于里，故表里大热、呕吐、泄泻、小便不利，脉动摇不宁，示正虚邪热相搏、肝风欲动之机。", ["数", "动"]], "20606": ["治法", "本段为方解，论滋阴清燥汤治上有燥热下焦滑泻之证。原文未直接描述脉象，仅言「脉数动摇者之要药也」，指芍药、甘草等药能复真阴、缓肝急，以治脉数动摇之证。其病机为燥热伤阴、肝木郁而动，故以山药、滑石滋阴清火，芍药甘草复真阴，半夏、竹茹止呕，生麦芽、茅根利小便兼达肝郁。", []], "20607": ["预后", "复诊脉象不复摇摇，仍似有力，至数未减，说明肝风动摇之势已平，但热势未全退，故脉仍数而似有力。呕吐泄泻皆愈、小便已利，为里气和畅之兆；表里之热稍退，气息仍不顺、舌苔仍黄，示余热未清。脉数未减而大便不实，故不敢重剂清下，预后需续以清解。", ["数"]], "20608": ["病机", "脉左右皆弦硬而长、数近七至，非洪滑之象。数近七至固为阴虚有热，然正气虚损不能拒邪亦现数；弦硬而长为气血两亏、邪热炽盛之征，故见目直视、舌黑、热甚息不接续，断为气分虚郁兼血虚阴亏、阳明热炽。", ["弦", "硬", "长", "数"]], "20609": ["预后", "服药后热退强半、精神清、气息顺，脉象较前缓和，是邪热渐衰、正气渐复之兆；惟大便未通，余热犹存，故仍守方加石膏、莱菔子以清通，待便通热全退乃停服，示脉缓为向愈之机而非病愈之凭。", ["缓"]], "20610": ["病机", "左脉浮弦似有力而按之不实，右脉弦长有力、重按甚硬，一息逾五至。浮弦为外感，弦长硬为阴亏火盛、冲气上逆；按之不实示正气已伤。故壮热呕吐、水入即吐、泻多尿闭腿疼，皆火盛阴亏、冲胃上逆、下焦不摄之候。", ["浮", "弦", "长", "硬"]], "20611": ["病机", "脉不为洪滑有力而为弦硬有力，右脉弦硬且长，是火盛阴亏之象。阴素亏血不荣筋故腿抽疼；阳明壮热灼阴故脉弦硬；右脉弦硬且长主冲气上冲，胃气不降故呕吐；阴虚肾亏不能漉水，水归大肠故小便不利而滑泻。", ["弦", "硬", "长"]], "20612": ["病机", "呕吐未止、二便渐调而表里仍壮热，脉象仍弦长有力，说明阳明邪热未清、阴亏火盛之势未减。弦长为热盛阴伤、肝胃气逆之脉，故放胆用重剂清阳明之热，热清则冲胃之气自降，呕吐当止，示脉象为辨证用药之据。", ["弦", "长"]], "20613": ["病机", "此段释方，指出脉象弦硬，弦为肝脉，此证弦硬乃肝经火盛、阴亏失柔之征。故以白虎汤加减清热滋阴，用芍药甘草复真阴、通小便，生山药代人参补益气血，皆针对弦硬所主之肝火阴亏、水饮偏渗大肠之机。", ["弦", "硬"]], "20614": ["预后", "三诊表里之热退强半、腿疼全愈，脉象亦较前缓和，是邪热渐退、阴分渐复之佳兆；惟呕吐未全愈、恶心懒食，乃胃气尚逆、余热未清，故先用赭石降胃镇逆，待胃脘开通后再清余热，脉缓示病势向安。", ["缓"]], "20615": ["预后", "原文未识脉名，仅言脉一息犹五至。热全消、便通、病脱然全愈，而脉仍五至，知邪去而真阴未尽复，故以山药粥调补、佐鸡内金助运，待脉复平和。此段以脉至数测阴复与否，属病后调摄之预后判断。", []], "20616": ["病机", "脉六部皆微弱而沉，左部兼细，为阳气虚衰、阴血不足之象。微弱主气弱，沉主里，细主阴伤。症见咽喉微疼、口唇干裂、舌干缩、心中热干、周身酸软无力，乃气阴两虚、虚热内扰；大便四日未行、小便短少赤涩，为津亏液涸、气化不利。脉症合参，病机属气阴两虚、虚热内郁。", ["微", "弱", "沉", "细"]], "20617": ["病机", "脉转微细，为伏气温病内陷少阴之征。微细主阴阳俱虚，少阴心肾受损。原文谓冬伤于寒又兼冬不藏精，寒伏三焦化热，乘虚窜入少阴。脉微细正是少阴精气亏虚、邪热内陷之象，与温病初起脉浮数者不同，提示病位深、正气弱。", ["微", "细"]], "20618": ["预后", "复诊脉象较前有力，似近洪滑，为邪热外达、正气渐复之佳兆。洪滑主阳热有余，然诸病皆见轻减、精神已振，说明此洪滑非病进，而是肾气上潮、心肾相交之象。惟心中余热、大便未通，故仍宜凉润清之，少佐补气。", ["洪", "滑"]], "20619": ["病机", "脉象沉细，沉主里、细主虚，为肾气亏虚不能上潮于心之征。心肾不交，水火失济，故见沉细之脉。原文明言此证之脉象沉细，是肾气不能上潮于心，而心肾不交也，直接点明脉象所主病机为心肾不交。", ["沉", "细"]], "20620": ["预后", "服药后脉近洪滑，是肾气已能上潮于心而心肾相交之象。洪滑本主阳热，然此证诸病皆见轻减，故非寻常温病脉洪大为增剧之比。脉象由沉细转洪滑，反映心肾相交、气化复常，属向愈之预后。", ["洪", "滑"]], "20621": ["病机", "脉左部沉弦，右部沉牢。沉主里，弦主气郁，牢主坚积。症见心下痞闷、胸膈痞塞、烦热，为气机郁滞、痰热内结之象。左部沉弦示肝气郁结，右部沉牢示痰积内阻，脉症合参，病机属气郁痰结、痞塞胸膈。", ["沉", "弦", "牢"]], "20622": ["病机", "原文未识出具体脉名，但言审证察脉，其病属结胸无疑。结胸成因，或寒温下早，或表里同病专事开破，致外感乘虚而入。脉象虽未明言，然结胸之脉多沉紧或沉实，反映邪结于里、气机壅塞。此段重在阐明结胸病机及误治之由。", []], "20623": ["病机", "脉左部弦长，弦主气郁、主饮，长主气机有余。症见胸中满闷异常、似有物填塞、气息不能上达，发热嗜饮水，小便不利，大便溏泻，为肝气郁滞、水饮内停、气化不利之象。左部弦长正示肝郁饮停，气机壅塞于胸膈。", ["弦", "长"]], "20624": ["病机", "原文未明言脉象，但据“证脉合参”推断，此证因下早而成结胸，又小便不利致溏泻，病机为上实下虚，外感之热兼阴虚之热。上实指结胸，下虚指溏泻，外感与内伤之热并存，故治宜上开其结、下止其泻，兼清内外之热。", []], "20625": ["预后", "复诊脉象较前平和仍微数，说明上焦之结已愈强半，灼热减、不渴，是热势渐退之象；但大便仍溏、服药后下一次，示下虚未复，微数之脉提示余热未尽，故再即原方略加减，以清余热、顾护脾胃。", ["数"]], "20626": ["主病", "脉左右皆浮弦有力，浮主表，弦主少阳，有力主阳明实热。表里俱发热、胸膈满闷似结胸、呼吸不利、夜不能寐，乃风邪痰饮凝结胸膈，太阳表邪未解，兼阳明少阳之热，故脉浮弦有力，舌苔白厚、便闭亦为实象。", ["浮", "弦"]], "20627": ["病机", "脉浮为病在太阳，按之有力为连及阳明，浮有力兼弦为更连及少阳。胸膈满闷呼吸不利，因怒气溢于胸中，挟风邪痰饮凝结于太阳部位。故脉浮弦有力反映太阳表邪、阳明里热、少阳不和之病机。", ["浮", "弦"]], "20628": ["预后", "服药后遍身得汗，胸次豁然，温热全消，夜能安睡，脉已和平如常，说明表里之邪已解，阴阳调和，故脉复平和。惟大便未通，乃余邪未尽，用旃那叶通下即愈，示病向愈之预后。", ["和平"]], "20629": ["主病", "脉弦长有力，右部微有洪象，一息五至。弦长主肝胃气逆，洪为阳明热盛，数主热。周身壮热、心中热、大便数日未行，阳明腑热已实；呕吐不食，冲气上冲，胃气不降，故脉弦长有力而洪数，主胃热冲逆之病。", ["弦", "长", "洪", "数"]], "20630": ["病机", "原文未出脉象，但据“证脉相参”知阳明腑热已实，又挟冲气上冲。腑热实故不能进食、大便不行；冲气上冲故呕吐、药亦多呕。病机为胃热腑实、冲气上逆，故治以清胃为主，降冲为辅，使冲气降则胃气降，呕止能食。", []], "20631": ["预后", "服药后呕吐止、大便通、热退强半，三诊脉静身凉，示邪热已退、脉复安宁，病已愈。但仍不能饮食、憎其臭味，乃胃气不开，非邪未尽，故以莱菔汤开胃气而饮食复常，说明脉静身凉为病愈之候，胃气未复可待饮食调养。", ["静"]], "20632": ["病机", "脉浮而微滑，浮主表，滑主痰热，右关重按甚实，关候脾胃，实主里热内结。原文谓“感风成温”而“伏气化热内动”，故脉浮滑为外感风温引动伏热，热壅咽喉则咽热咳嗽音哑，周身拘束酸软为表邪未解。", ["浮", "滑", "实"]], "20633": ["病机", "脉洪大而实，左右皆然，洪大为阳明热盛之象，实主邪热内结。原文谓“伏气化热，又兼有新感之热”，热势鸱张，故服凉药后表里反大热，咳嗽音哑益甚，非药不对证，乃热重药轻，须重用石膏清之。", ["洪", "大", "实"]], "20634": ["预后", "脉已平和如常，为热邪已退、正气渐复之象，故原文谓“原无须服药”。惟大便三日未行，喉间微疼，乃余热未清、津液未复，故以滋阴润便之方善后，待大便通后喉疼自愈，示脉平而症未全消，仍须调理。", ["和平"]], "20635": ["病机", "脉微弱不起，而表里俱热、烦躁异常、舌苔薄黄、小便赤涩短少，此脉症不符，非虚寒，乃伏气化热遏抑肾气，水火不交，热郁于内而脉反无力。原文谓“屡服表疹清热之药”而热不退，正因脉虚证实，不可纯用寒凉。", ["微", "弱"]], "20636": ["病机", "原文未识脉名，然述“脉仍然无力”，结合舌苔黄、小便短赤、阳明腑热已实而脉无力，断为伏气化热窜入少阴，遏抑肾气，水火不交，故烦躁异常。此温病与少阴伤寒热证脉同，治以白虎加人参汤变通，兼托疹毒。", []], "20637": ["治法", "原文标“脉虚之热”，指证属实热而脉虚无力。方解白虎加人参汤变通，以花粉代知母清热兼解毒，山药代粳米和胃兼滋肾，加人参治“证实脉虚之热”，鲜茅根治温病下陷之热，示脉虚者清热之中须扶正。", ["虚"]], "20638": ["误治", "原文未识脉名，但述“脉象仍然无力”，服白虎加人参汤后热退复作，大便日两次，知寒凉过服伤中，不可再服。此脉无力而热不退，非纯热证，乃正虚邪恋，故前法无效，后悟得治此证之的方，示脉虚者不可一味寒凉。", []], "20639": ["病机", "脉洪滑甚实，洪为热盛，滑为痰热，实为邪结。原文谓伏气化热在三焦，毒菌传染先受上焦，毒热相并弥漫全身，故脉洪滑实。前用白虎加人参汤无效，竟以鲜白茅根凉散收功，示热毒弥漫非石膏独清，须凉散透达。", ["洪", "滑", "实"]], "20640": ["病机", "左部弦硬为劳力伤肝肾之阴，阴不制阳而化热；右部洪实而浮，为阳明腑热已实兼表邪未罢。数逾五至示热盛。合目谵语、舌苔白厚、便三日未行，皆腑热上扰神明、热灼津伤之象，脉证相合，主里热实证兼表。", ["弦", "硬", "洪", "实"]], "20641": ["病机", "原文明言左脉弦硬者，劳力过度肝肾之阴分有伤；右部洪实者，阳明之腑热已实；洪实兼浮者，证犹连表。弦硬为阴伤不柔，洪实为腑热内结，浮为表邪未尽。故治以白虎加人参汤滋阴退热，佐透表之药引热外出，脉象直接指示病机层次。", ["弦", "硬", "洪", "实"]], "20642": ["治法", "此段以脉释方：右脉洪实，故重用石膏清阳明腑热；左脉弦硬，故加人参、玄参、山药于退热中滋阴复真阴；脉象兼浮，知表证未罢，佐阿斯匹林或薄荷、连翘透表出汗。所谓因其病机而利导，是据脉定药、以脉象分部指导治法配伍的典型。", ["洪", "实", "弦", "硬"]], "20643": ["病机", "左右皆弦而有力，为肝火炽盛兼外感之热入阳明；重按不实，乃前服开降之品过多伤正所致；搏近五至示热。腹疼甚剧因弦主疼、弦而有力致气化不和；烦躁因下久阴虚、肾气不能上济心火。脉弦有力主肝火与阳明热，按之不实提示正伤。", ["弦", "有力", "数"]], "20644": ["病机", "原文指出脉象弦而有力，因肝火甚盛兼外感之热已入阳明；按之不实，因从前服开降之药过多。弦主疼，弦且有力则腹中气化不和而疼甚剧；下久阴虚、肾气不能上达与心相济，故烦躁。脉弦有力为肝火与温热之征，按之不实为药伤正气之据。", ["弦", "有力"]], "20645": ["预后", "复诊温热已愈强半，下痢腹疼皆愈，脉象亦见和缓。前段脉弦而有力，今转为和缓，示肝火已平、温热渐清、正气来复，故为病退之佳兆。仍拟凉润滋阴以清余热，说明脉由弦急转和缓可作温热病向愈的客观凭据。", ["缓", "和"]], "20646": ["病机", "脉洪滑而长，两寸尤盛，为阳明热盛、痰热内壅之象。洪主热盛，滑主痰，长主阳热有余，寸盛示热壅上焦。闭目昏昏、呼之不应，乃热扰神明；周身灼热无汗、便三日未行，为腑热内结、表气不通。脉证合参，主阳明实热蒙蔽清窍。", ["洪", "滑", "长"]], "20647": ["预后", "四岁小儿正脉当七至，今数十至且无力，为热盛而正气大虚、阴液耗竭之候。形瘦已极、灼热、恶心呕吐、小便不利、大便稀水日十余次、哭泣无声，皆脾胃衰败、气阴两伤之象；指纹淡红透气关，示病位深入而正气不支。脉数无力主正虚邪恋，预后堪忧。", ["数", "无力"]], "20648": ["病机", "脉数逾五至为热盛，浮弦无力示热伤气阴、虚风内动。周身骨节疼、身热、渴、便干尿赤、干嗽、酸软、动则眩晕，皆温病日久，热灼阴伤，筋脉失养，虚风上扰之象。脉浮弦无力，正合阴虚阳浮、筋脉拘急之机。", ["数", "浮", "弦", "虚"]], "20649": ["预后", "药后得汗，骨节疼止，热退半，小便通，脉已不浮弦而稍有力，示表邪渐解，里热减轻，正气来复。脉由浮弦转为稍有力，为邪退正复之佳兆，故可原方加减续服，以清余邪。", ["浮", "弦"]], "20650": ["误治", "温病初起误用辛温发汗，又误下伤正，致邪热内陷，灼伤阴津。脉弦而有力、搏近六至，为热盛邪实；按之不实、左部不任重按，示阴伤正虚。神昏谵语、喘、灼热、唇裂、舌干黑、渴饮不解，皆热陷心营、阴液耗损之危候。", ["弦", "数", "虚"]], "20651": ["预后", "药后温热大减，神清，脉仍似有力，示余热未尽，正气渐复。便未通、心犹热，为热结未下；续服至便通，则邪有出路，病获全愈。脉象虽未详，然从“仍似有力”可知热势未净，故以清热通便收功。", []], "20652": ["兼症", "腹中搅疼、号呼辗转、身热、心热、手足扰动、舌紫干、根黄苔、便两日未行，脉难细诊而总近热象，显系热毒内壅、肝火下迫、腑气不通之实热证。热扰心神则卧不安，热灼津伤则舌紫干，热结肠道则便不行。", []], "20653": ["病机", "脉左右皆似大而有力，重按不实，数近六至，示外感实热炽盛而正气大虚。屡下脓血，阴血耗伤，热毒未清，故精神昏愦、呼之不应。大而重按不实，为热盛伤阴、正不胜邪之象，故拟白虎加人参汤清热益气。", ["大", "数", "虚"]], "20654": ["预后", "药后神清，下脓血止，脉大见和平，示邪热渐退，正气来复。然心中微热、怔忡不安，为余热未清、心气阴两伤，故以凉润育阴清余热，兼保合气化以安怔忡。脉象和平为病退之兆。", []], "20655": ["其他", "此段为治验说明，非直接论脉。腹疼辗转号呼不能诊脉，因肝火下迫兼外感毒疠，热毒壅盛，气血逆乱。用芍药泻肝热、甘草缓肝急，更以防疫宝丹驱邪，连翘、离中丹清温热，示温痢并重之证，脉难细诊而病势危速。", []], "20656": ["病机", "左脉弦硬为肝火炽盛、下迫肠中，故下痢赤多白少、后重腹疼；右脉洪实为阳明热盛，故周身壮热、心热而渴、舌苔白厚中心微黄。一息五至示热势尚盛。弦硬与洪实并见，说明风温之热已入阳明，肝火乘机下迫，热与痢并作，属邪实之候。", ["弦", "硬", "洪", "实"]], "20657": ["病机", "原文明言右脉洪实为风温之热已入阳明之腑，左脉弦硬为炽盛之肝火下迫肠中作痢。阳明脉实而渴，故用白虎加人参汤；肝热甚盛兼下痢，故以生山药代粳米固下焦气化，辅凉肝调气之品。此段以脉象定病位在阳明与肝，热与痢并治。", ["洪", "实", "弦", "硬"]], "20658": ["预后", "复诊时温热已退强半，痢疾已愈十之七八，腹已不疼，脉象亦较前和平。脉由弦硬洪实转为和平，说明邪热渐退、肝火已平、肠胃气机渐复，故为向愈之兆。原文以脉象较前和平与症状减轻互证，示原方加减再服可收全功。", ["和平"]], "20659": ["预后", "诸病皆愈，惟脉象似仍有余热，胃中似不开通懒于饮食。脉虽近平而尚有余热未清，胃气未复，故以鲜梨、鲜藕、莱菔煮汁送服益元散清余热、开胃气。至三次则喜进饮食，脉亦和平如常，说明余热尽去、胃气恢复，脉象平和为病愈之征。", ["和平"]], "20660": ["病机", "左脉弦而兼硬为肝血虚而胆火盛，故灼热、心热渴、呻吟不止；右脉似有力而重按不实，示下痢日久气化已伤，外感之热又入阳明；数近六至为热灼日久、真阴亏损。证脉合参为邪实正虚之候，故病益加剧，须通变白虎加人参汤与通变白头翁汤并治。", ["弦", "硬", "数"]], "20661": ["病机", "原文自释左脉弦而兼硬为肝血虚而胆火盛，右脉似有力而重按不实为下痢久气化已伤、外感之热侵入阳明之腑，数六至为外感之热灼耗已久、真阴大有亏损。故断为邪实正虚之候，以通变白虎加人参汤及通变白头翁汤二方相并治之，脉象直接决定扶正祛邪并施之法。", ["弦", "硬", "数"]], "20662": ["预后", "服两日表里之热皆退，痢变为泻仍稍带痢，腹疼后重较前轻减，脉象已近平和。脉由弦硬数急转为近平和，说明邪热已退、正气渐复，故宜大剂温补止泄泻，少辅治痢之品。此段以脉象转和作为由攻转补的依据，属预后判断。", ["和平"]], "20663": ["病机", "泄泻逾两旬，左脉微弱为久泻伤及肝血、正气亏虚，故周身酸软无力、时或怔忡；右部重按颇实、搏近六至，为肠胃仍有积热，故心中发热懒食、小便赤涩发热。左弱右实并见，示正虚与邪热夹杂，久泻而热未清，属虚实错杂之候。", ["微", "弱", "实", "数"]], "20664": ["病机", "脉弱而不舒，反映正气不足，尤其脾胃虚弱，运化无力。上焦燥热与下焦滑泻并见，脉弱提示中气亏虚，不能斡旋上下，故燥热与滑泻同存，治疗棘手。弱脉主虚，与滑泻日久、阴液耗伤相应，故需滋阴清燥，兼顾上下。", ["弱"]], "20665": ["主病", "脉象洪长有力，左右皆然，为阳明实热内盛之典型脉象。洪主热盛，长主气分热炽，有力为邪实。症见壮热、嗜饮凉水、便干溲赤、苔黄，皆阳明府热结实之候，故脉洪长有力主阳明实热证。", ["洪", "长"]], "20666": ["病机", "脉之洪长有力是伏气化热、暑热内伏，为外感所激而发，表里壮热，阳明府热已实之明征。洪长有力反映热邪充斥气分，正盛邪实，故主阳明实热病机，治宜大剂白虎汤清泄里热。", ["洪", "长"]], "20667": ["病机", "复诊脉象洪长有力仍旧，表里之热分毫未减，大便未通，说明药轻病重，阳明实热未得挫减。洪长有力持续存在，表明热邪仍盛，府实未下，故非药不对证，乃病重药轻，需加重石膏以清阳明大热。", ["洪", "长"]], "20668": ["病机", "下燥粪数枚后，表里之热仍然不退，脉象亦仍有力，说明阳明府实虽得部分下行，但热邪未清，脉有力示邪实仍在。此脉有力与壮热不退相应，提示需继续清泄实热，故以石膏研细送服增强清热之力。", ["有"]], "20669": ["误治", "脉弦硬异常，虽有力而无洪滑之象，说明热盛伤阴，脉失柔和，非单纯阳明实热之洪滑。误用白虎汤后热势大增，因脉无洪滑，提示气阴已伤，急予人参补气生津，脉渐和缓，热退而愈，示弦硬为气阴不足之象。", ["弦", "硬", "数"]], "20670": ["主病", "脉左部弦而长，右部弦硬有力，症见项疼不能转侧、周身灼热、心中热、思凉物、便干溲少。弦长主风热或肝经热盛，弦硬有力为实热内蕴，结合项疼，为风温袭于风池、风府，热邪充斥，故脉弦长硬主风温实热证。", ["弦", "长", "硬"]], "20671": ["病机", "高年脉本弦细，因气虚无起伏，血少细而不濡。今脉弦硬而长有力，显有温热之象，说明风温袭表，热邪内盛。弦硬长有力为实热之征，与项疼、灼热相应，故当清实热兼补正解表。", ["弦", "细", "硬", "长"]], "20672": ["病机", "左右脉皆弦，右部尤弦而有力，弦主肝郁气滞、木盛克土。误补党参致气郁化火，右胁陡疼、彻夜不卧、心中发热、舌苔白厚、大便四日未行，皆肝胃郁热、腑气不通之象。脉弦有力为实，非虚也，故补之反剧。", ["弦"]], "20673": ["病机", "脉弦主疼、主血液短少。右胁非常疼痛，为肝络瘀滞；劳心暗生内热，伤损血液，故脉弦。右脉弦而有力，为外感之热已入阳明之府。证脉相符，治以白虎汤清阳明，辅开郁滋阴以柔肝。", ["弦"]], "20674": ["病机", "脉象变为浮弦，浮为病势还表，弦为余邪郁于少阳。热退强半、胁疼已愈三分之二，但胸膈郁闷、大便未通，乃余热未清、气机未畅。脉浮有还表之象，故宜宽胸清热润燥中少加透表，引邪从汗解。", ["浮", "弦"]], "20675": ["病机", "脉浮滑，重按有力，浮主表热，滑主痰涎壅盛。面红身热、喘息迫促、痰声漉漉、目似不瞬，为痰热壅肺、肺气上逆之危候。指有紫纹上透气关，舌苔白而润，大便两日未行，小便微黄，皆痰热内闭、肺失肃降之征。", ["浮", "滑"]], "20676": ["预后", "脉象见滑，虽主有痰，亦足征阴分充足，身体胖壮，故犹可治。滑脉为痰涎内盛，然重按不虚，胃气尚存，阴分未竭，故预后尚可。治宜小青龙加石膏汤，再加杏仁、川贝以利肺气，化痰清热。", ["滑"]], "20677": ["治法", "面红身热、脉象有力，为痰热壅肺之实证。小青龙加石膏汤中重用生石膏十倍于麻桂，以监制麻、桂、姜、辛之热，使麻黄可留而不去。此方解说明石膏用量之依据，针对脉有力之热象，非泛论也。", []], "20678": ["病机", "复诊喘愈强半，痰犹壅盛，肌肤犹灼热，大便犹未通下，脉象仍有力。脉有力示痰热未清，肺气仍壅，腑气未通。虽喘减而余邪未尽，故再治以清热利痰之品，继清肺胃痰热。", []], "20679": ["病机", "左脉沉弦，右脉洪实，数近六至。沉弦为肝郁化火，洪实为阳明热盛。患者禀性褊急、多忧思、易动肝火，晨起微热，午后表里大热，精神昏昏，舌肿无苔，大便素燥，皆肝火犯胃、阳明腑实之候。", ["沉", "弦", "洪", "实"]], "20680": ["病机", "左脉沉弦，沉主里、弦主肝，知肝气郁滞不能条达，故呻吟不止以舒其气；右脉洪实，洪为热盛、实为邪实，知伏气化热窜入阳明，或外感温病剧变。脉象反映肝郁与阳明热盛并见，故治以白虎汤清阳明热，佐调气舒肝。", ["沉", "弦", "洪", "实"]], "20681": ["病机", "药后热退，左脉仍有弦象而不沉，知肝郁已减而未全舒；右脉已无洪象而仍似有力，至数之数亦减，知阳明热势已挫而余热未清。心中仍觉热、腹中知饥而懒食，皆余热未净、胃气未和之象，故再宜凉润滋阴清其余热。", ["弦", "数"]], "20682": ["预后", "药后大便通下、热全消、能进饮食，脉象亦和平，此邪去正复之佳兆；然至数仍有数象，知余热未尽、阴分未充，故脉虽和而数未除。预后良好，仍须玄参、潞参煎服数剂以善其后，清余热而养阴液。", ["数"]], "20683": ["主病", "左脉弦硬，弦主肝、硬主火，知肝胆之火炽盛；右脉弦长有力，弦长为冲气挟胃气上冲，有力为外感之热已入阳明。一息五至为数，主热盛。脉象反映肝火、冲胃气逆与阳明热盛并见，故见烦热汗出、呕吐不受饮食、吐药吐水、便闭等症。", ["弦", "硬", "长", "数"]], "20684": ["病机", "左脉弦硬，为肝胆之火炽盛；右脉弦长，为冲气挟胃气上冲；弦长兼有力，为外感之热已入阳明之府。因被盗怒动肝气，肝火上冲，激动冲气挟胃气上冲，外感之热复炽于胃相助为虐，故烦热汗出、不受饮食而吐药吐水，治当清热镇逆。", ["弦", "硬", "长", "实"]], "20685": ["治法", "本段论石膏用法，谓石膏重坠寒凉，白虎汤以甘草缓之、粳米和之，使留恋胃中；忌与重坠、开破药并用。今肝气胆火相并上冲，更激动冲气挟胃气上冲，外感之热助之上冲，致脏腑气化有升无降，饮食与药皆不能存留，故特用赭石辅石膏以旋转气化。", []], "20686": ["主病", "左脉弦长，弦主肝、长主气逆，知肝气冲胃上逆；右脉洪长，洪为热盛、长为热邪炽张，重按皆实，知阳明热结里实。脉象反映肝胃气逆与阳明实热并见，故见表里壮热、呕吐甚剧、不能服药、少进饮食亦吐、舌苔白厚中心微黄、大便三日未行。", ["弦", "长", "洪", "实"]], "20687": ["预后", "复诊呕吐止、可进饮食、大便通下一次，诊其脉犹有余热，心中仍觉热而较前大轻减，知邪势已衰而余热未清。脉象虽未明言，然从症候推断，热退而未净，故拟改用汤剂以清其未尽之热，属病退向愈之预后。", []], "20688": ["预后", "原文述服药后“热又减退若干，脉象已近和平”，脉象已近和平指脉象趋于和缓，无偏亢之象，说明邪热渐退，正气来复，病势向愈。故属预后良好之征，非主病之脉。", []], "20689": ["病机", "脉摇摇而动，数逾五至，重按不实，为热盛伤阴、虚风内动之象。壮热、衄血、便血、呕吐、怔忡，皆热灼营阴、胃气上逆所致。脉动数而虚，主热盛阴伤，虚风萌动，故恐白虎加人参汤服后作呕。", ["动", "数", "虚"]], "20690": ["病机", "热退七八，衄血便血皆愈，脉象力减而至数仍数，说明大热已退，但阴液未复，余热未清，故脉数而力减。此脉数主阴虚内热，非实热壅盛，与上证相应。", ["数", "虚"]], "20691": ["病机", "原文明言“大热已退而脉仍数者，以其有阴虚之热也”，脉数在此主阴虚发热，非外感实热。故用玄参、潞参滋阴退热，连翘透疹解毒，脉数提示阴亏未复，余热内扰。", ["数"]], "20692": ["病机", "原文指出“大热退后，脉象犹数”，并释为阴虚之热。脉数在此主阴液亏虚、虚热内生，故重用玄参滋真阴、清余热，佐潞参、连翘，使虚热易退，余热外透。", ["数"]], "20693": ["病机", "疹密灼热，昏谵息促，唇裂紫黑，脉数而有力，为热毒炽盛、内陷营血之象。脉数有力主实热壅盛，毒热攻心，故见谵语；热灼津伤，故唇裂；热迫大肠，故便溏。", ["数", "实"]], "20694": ["病机", "热大减，诸病皆愈，惟不能稳睡，心中骚扰，脉象仍似有力，说明余热未清，扰及心神，脉实主邪热内蕴，非纯虚象。故减滑石、石膏，送安宫牛黄丸清余热、安心神。", ["实"]], "20695": ["病机", "脉左右皆洪滑有力，一分钟九十八至，为阳明热盛、痰热壅结之象。洪滑有力主实热痰浊，热毒上攻咽喉则红肿疼闷，外透肌肤则疹密猩红，热扰心神则自觉热甚。", ["洪", "滑", "实", "数"]], "20696": ["预后", "脉象之洪滑亦稍减，说明表里之热稍退，为邪热减轻之象；然疹出加多、喉肿增剧、呼吸滞碍，是热毒未尽而壅于咽喉，故虽脉减而病势仍危，需刺血泄毒。", ["洪", "滑"]], "20697": ["病机", "脉左右皆弦长，右部重诊有力，乃外感热入阳明，冲气挟胃气肝火上冲之象；弦主肝旺，长主气逆，故见壮热喘逆、咽喉红肿、呼吸窒碍，便闭溺赤亦热盛之征。", ["弦", "长"]], "20698": ["病机", "左右脉皆弦长，因冲气挟胃气肝火上冲；右脉力胜于左，为外感之热已入阳明之府。弦长主肝胃气逆火升，故喘逆、咽喉肿疼偏左，正当肝火上升之路。", ["弦", "长"]], "20699": ["预后", "脉象较前平和，右部仍然有力，示表里之热已减而阳明胃热未清；胸膈郁闷、气上冲、咳嗽、便未通，乃余热未净、气机未畅，故仍需开郁降气清热。", ["和平"]], "20700": ["病机", "脉浮滑而长，右关尤重按有力，浮为表邪未尽，滑长为阳明热盛；热壅咽喉则疼痛碍食，热扰心胸则上冲，便干苔白亦里热之征，属外感兼内伤之候。", ["浮", "滑", "长"]], "20701": ["病机", "脉象犹浮，舌苔犹白，得病甫二日，表证未罢；右关重按有力，时觉热上冲咽喉，是内伤外感相并。浮脉主表，右关有力主胃腑热盛，故宜重剂清胃少佐解表。", ["浮"]], "20702": ["病机", "脉浮而无力，右寸浮尤甚，两尺按之即无，数至一百二十至，乃阴竭阳浮、肝风内动之危候；目盲、循衣摸床、谵语，皆肾阴将竭、神明失守之象，脉数无力为虚阳外越。", ["浮", "数", "无力"]], "20703": ["病机", "脉浮为病还在太阳，右寸浮尤甚为将汗之兆；两尺脉甚弱，是阳升而阴不应，故不能作汗。肾阴将竭，肝风已动，当滋真阴以济阳，听其自汗，不可强发。", ["浮", "弱"]], "20704": ["预后", "原文述服药后“形状较前安静，再诊其脉颇有起色”，脉象由病态渐趋和缓，说明药已中病，正气渐复，故预后良好，终得“透汗”而愈。此段以脉象好转判断病势向愈，属预后范畴。", []], "20705": ["病机", "脉一息五至强为数，左部弦而有力主肝木乘脾，右部大而有力却不任重按，是胃热壅盛而正气已伤。结合心下胀满、喘不能卧、心中干甚、小便赤少，显系肝胃热结、气机上逆、阴液受灼之病机。", ["弦", "大", "数"]], "20706": ["病机", "左脉弦细无根，是肝阴亏虚、虚风内动；右关稍实，为胃热未清；一息六至为数，主热。热药误汗后热益甚、渴、消瘦、便干，皆阴伤热留之象。脉弦细无根与关实并见，示正虚邪恋、阴亏而热郁之病机。", ["弦", "细", "实", "数"]], "20707": ["预后", "复诊“右关脉已平和”，说明胃热已退，外感之热已解；惟过午微热，乃阴分未复。脉象由病态转为平和，提示邪去正渐复，但余热未清，故当再滋补阴分。此段以脉象改善判断病势向愈。", []], "20708": ["病机", "左部弦长主肝火亢盛，右部洪长主阳明热炽，一息五至为热象。表里壮热、吐血、便闭、苔白厚欲黄，皆肝胃热盛、迫血妄行之病机。脉弦长与洪长并见，示热盛于阳明而兼肝火，血热妄行。", ["弦", "长", "洪", "数"]], "20709": ["病机", "原文谓“脉象火热虽盛，而正犹不虚”，虽未列具体脉形，但以脉象判断火热盛而正气未衰。结合家务劳心、心肝蕴热，复感外热入阳明，两热相并逼血妄行而吐血。脉象示邪盛正不虚，故知犹可治。", []], "20710": ["预后", "原文述“血止热退，脉亦平和”，脉由病态转为平和，说明邪热已清、气血渐和，故吐血止、热退。惟大便未通，再服余药后便通全愈。此段以脉象平和判断病愈，属预后。", []], "20711": ["病机", "左脉弦硬而长为肝火炽盛、冲气上冲；右脉洪滑而长为温热入阳明胃腑，亦兼冲气上逆。表里壮热、嗜饮凉水、痰涎上泛、呃逆哕气、两胁作胀，皆肝胃热盛、冲气上逆、痰热内壅之病机。脉弦硬洪滑皆重按有力，示邪实热盛。", ["弦", "硬", "长", "洪"]], "20712": ["预后", "原文言药后热退气平、痰涎减十之七八，脉象亦近平和，是邪热渐退、正气来复之征。脉由病时之数或洪滑转为近平和，说明病机向愈，故可于原方减石膏、龙骨、牡蛎再服，待大便通下而全愈。此段脉象非主病，乃判断预后与转方的依据。", ["和平"]], "20713": ["病机", "脉左右皆弦而无力，数逾五至，弦为疟邪郁于少阳之象，无力且数则示气血阴阳俱虚，而阴分虚尤甚。原文谓“阴分阳分俱虚，而阴分之虚尤甚”，故虽疟发寒热，不可专事攻邪，当培养气血而以治疟之药辅之，此脉为虚实夹杂之病机。", ["弦", "数", "无力"]], "20714": ["病机", "服治疟药后疟止而身犹觉热，脉象犹数，原文断为“阴分犹虚”。数脉在此非实热，乃阴虚不能恋阳、虚热内生之象，故以玄参、山药滋阴，姜枣和中，服至身不发热时停服。此段以脉数说明疟后阴亏未复之病机。", ["数"]], "20715": ["病机", "脉洪滑而实，右部尤甚，洪滑主痰热内盛，实主邪结，右部甚则病在脾胃。原文见心中杜塞满闷、热上攻、大便四日未行，皆痰热壅阻、腑气不通之候。疟发寒热不甚剧，正因邪热内结而非纯在表，故脉不弦而洪滑实，主里实痰热之病机。", ["洪", "滑", "实"]], "20716": ["病机", "左部弦硬，右部洪实。弦硬为肝胆热盛、木火偏亢，洪实为阳明热结。原文热甚剧、心中发热、思食凉物、便燥溲赤，皆肝胆之火与胃肠之热并盛之征。疟间日发而寒轻热重，正合弦硬洪实之脉，主肝胆热盛兼阳明腑实之病机。", ["弦", "硬", "洪", "实"]], "20717": ["病机", "脉左右皆有弦象，左关独弦而有力。弦为疟邪郁于少阳、肝胆气机不和之象，左关候肝胆，独弦有力说明病根在肝胆而邪热偏盛。原文痢赤白参半、下坠腹疼、疟间日发寒轻热重，皆肝胆之热下迫肠中、外感之邪留连之候，主肝胆热盛之病机。", ["弦"]], "20718": ["病机", "原文自释：左右皆弦为病疟之常脉，左关独弦而有力则病根在肝胆。肝胆受外感热邪，气机郁滞故脉现弦象，邪热盛故弦而有力；热下迫肠中则下痢。故拟清肝胆之热、散外感之邪，使疟痢同愈。此段以脉弦有力说明肝胆热邪为病本之病机。", ["弦"]], "20719": ["病机", "原文仅言“脉象无力，却无闭塞之象”，未识具体脉名。无力示正气不足，无闭塞之象则非实邪壅阻。症见发热而渴、恶心怔忡、饮水即吐、腹疼下泻、腿筋转，皆中虚气逆、津液受伤之候。脉无力正说明虚象为主，不可作实热攻下，主中虚气逆之病机。", []], "20720": ["病机", "原文言“脉象无火而其实际转大热”，指出霍乱毒邪内蕴实热，但心脏受毒麻痹，启闭无力，故脉不显热象。此脉象无火并非真寒，而是毒邪麻痹心脏所致，主内蕴实热之霍乱，与心中热渴、二便觉热相应，治当寒凉清热兼解毒。", []], "20721": ["病机", "复诊“脉较前有力，显呈有火之象”，说明心脏麻痹已解，启闭机关灵活，脉象随之变更。此脉象变化反映毒邪渐退而余火未清，兼吐泻伤阴生热作渴，故主余热未清、阴伤之病机，治宜清热兼滋真阴。", []], "20722": ["主病", "脉沉细欲无、不足四至，伴吐泻频繁、手足凉至肘膝而心中发热，为霍乱毒菌内侵、心脏受麻痹、血脉流通无力之象。沉细示阳气不能外达，欲无示心搏将停，故主霍乱危候，与吐泻、肢冷、心热相应。", ["沉", "细"]], "20723": ["病机", "脉沉细且迟，因霍乱毒菌随暑热传入脏腑，心脏受毒麻痹，跳动之机关将停，血脉流通无力，不能达于四肢。沉细迟主心阳不振、毒邪内闭，故见手足皆凉、吐泻交作、心中发热，治宜解毒清热。", ["沉", "细", "迟"]], "20724": ["预后", "六脉全无、奄奄一息、昏昏似睡、肢体甚凉，而心中犹觉发热难受，为霍乱毒菌窜入心脏、行血机关将停、血脉不达周身之危候。脉闭身凉而内蕴热，示阴阳将离，预后凶险，但仍可据心热以热论救治。", []], "20725": ["病机", "身凉脉闭而心中自觉发热，仍当以热论。脉闭因霍乱毒菌窜入心脏，致行血机关将停，血脉不达周身，故内虽蕴热而外显身凉脉闭。此脉象闭伏非真寒，乃毒邪内闭、心阳将竭之病机，治当消菌清热并助心房跳动。", []], "20726": ["预后", "药后心热与难受愈强半，而脉犹不出、身仍发凉，因年过花甲、吐泻两日未进饮食，血衰惫极，不能鼓脉外出以温暖周身。脉不出示气血衰极、心阳难复，虽症减而脉未复，预后仍需调补，不可遽断向愈。", []], "20727": ["预后", "药后脉出周身亦热，示心阳渐复、血脉通达，为向愈之兆；惟心中余火未清，知阴分犹亏不能潜阳。脉出而热显，说明毒邪已退、阴阳渐和，但阴亏余热未靖，故继以玄参、沙参、山药滋阴潜阳而全愈。", []], "20728": ["死脉", "脉象模糊如水上浮麻，莫辨至数，是元气暴脱、脉气涣散之象。气脱则血行无力，脉道不充，故脉形模糊难辨，至数不清，与气息若无、呼之不应相应，属暴脱危候，一息尚存尚可挽回。", []], "20729": ["病机", "脉若水上浮麻，为元气上脱之征，气浮于上则脉浮散无根；下脱则脉沉细欲无，因气陷于下，脉道不充。此以脉之浮沉辨脱之上下面，外脱则周身汗出不止，萸肉敛汗治之。", ["浮", "沉", "细"]], "20730": ["主病", "脉左右皆洪滑而实，一息五至强，为阳明府实、热盛于里之象。洪滑实主热邪壅盛，气血涌沸；数主热。与面红气粗、舌苔白厚中心黄、大便干燥、小便短赤相应，虽怀妊亦当急清其热。", ["洪", "滑", "实", "数"]], "20731": ["病机", "原文未出脉名，承上洪滑实脉而言。据此脉症，不但阳明胃府热甚实，肝胆之热亦盛，因左部脉亦现洪滑实，知未病前曾怒动肝火，热迫血妄行，故急以白虎加人参汤清热保胎。", []], "20732": ["预后", "药后大便通下一次，热退十之七八，脉象已非洪实，仍然有力，说明阳明实热已减，脉由洪实转为有力，是邪退而正气未衰之象，故仍心中发热，拟再用凉润滋阴之品清余热。", ["洪", "实"]], "20733": ["病机", "阳明府实之证，右关脉洪滑而实为宜，因胃府之脉候于右关。今左部亦现洪滑实，知未病之先肝中已有郁热，继为外感之热所激，勃然发动，故左右皆现此象，热盛于阳明兼肝胆。", ["洪", "滑", "实"]], "20734": ["妇人", "受妊吐甚，勺水不存，困顿已极，脉虽甚虚弱，仍现滑象，至数未改，为妊娠恶阻、胃气受损而胎气尚存之征。左关微浮稍似有力，是肝木犯胃、气逆作吐之象，虚中夹实。", ["虚", "弱", "滑", "浮"]], "20735": ["预后", "药后呕吐即止，精神稍振，脉左关之浮已去，六部皆近和平，说明肝木犯胃之气逆已平，胃气渐复，故脉由左关浮转为和平。惟仍有恶心、懒于饮食，是胃气未全复，再以开胃理肝滋阴清热调之。", ["浮"]], "20736": ["病机", "左右寸脉洪实异常，两尺按之不实，数至八至，为热盛于上、下元不固之象。洪实主热盛气壅，故喘息迫促、昼夜不能卧、烦躁；尺脉不实示下焦虚，热不下达，故便干溲赤。舌苔白厚欲黄，为热渐入里。", ["洪", "实", "数"]], "20737": ["预后", "脉上盛下虚，七至即为绝脉，今八至，为元气将脱、热邪上冲之危候。屡用麻黄发汗，致元气欲脱，外感之热入阳明，与内热相并上冲，故脉上盛下虚而喘逆迫促。数至八至，真阴耗竭，预后不良。", ["数"]], "20738": ["病机", "脉较前更数，一息九至，不若从前滑实，尺脉按之即无，为肝肾阴分大亏、不能维系阳分而气化欲涣散之象。阴亏于下，阳浮于上，故喘稍剧、烦躁、怔忡不能支持。胎滑下死胎，亦由阴亏失荫。", ["数"]], "20739": ["预后", "脉减三至为六至，尺脉按之有根，为病已回生之佳兆。心中犹觉发热，非外感之热，乃真阴未复之热。脉数减而尺有根，示阴渐复、阳有所附，故当纯用大滋真阴之品以复其阴。", []], "20740": ["其他", "此段论胎死腹中之由，非脉象主病。因吸入之气分毫不能下达，胎失母气所荫，不能资生，故下降为死胎，非因服药而堕。强调胎借母呼吸以养，气不下达则胎失所养。", []], "20741": ["病机", "左脉弦长，右脉洪滑，皆重诊有力，一息五至，为肝胆火炽、温热入阳明之象。弦长主肝胆火盛，洪滑主阳明热壅，故壮热无汗、思饮冰水、舌苔干黄、腹疼下坠、下痢赤白兼鲜血。", ["弦", "长", "洪", "滑"]], "20742": ["病机", "左脉弦长有力，为肝胆之火炽盛之明征。弦为肝脉，长主气火有余，有力为实热内蕴。肝胆火盛，下迫大肠，故下痢赤白、兼下鲜血、腹疼下坠。此脉直接揭示火盛下迫之病机。", ["弦", "长"]], "20743": ["病机", "右部洪滑有力，知温热已入阳明之府，故舌苔干黄、心热思饮冰水。脉象虽热而不至甚数，且流利无滞，示热未伤阴、胎气可保。左弦长主肝火下迫，故痢下赤白鲜血。治以白虎加人参汤清阳明，重用芍药清肝。", ["洪", "滑", "数"]], "20744": ["预后", "脉象仍然有力而较前则和缓，说明邪热虽退强半，但余邪未净，正气渐复。脉有力为邪实未全去，和缓为胃气渐和之象，故表里之热退、痢愈十之七八、腹疼坠减轻，舌苔由黄变白有津液，皆示病势向愈，预后良好。", ["实", "缓"]], "20745": ["病机", "左部弦细，右部沉虚，为产后下血不止、气血两亏之象。弦细主血虚肝郁，沉虚主气陷不足。下血日久，血脱气陷，故精神衰惫、身体羸弱、心中怔忡、呼吸短气；腰际疼甚，乃血去肾虚、冲任不固所致。", ["弦", "细", "沉", "虚"]], "20746": ["病机", "原文未出具体脉名，仅言「脉证细参」。结合前段左弦细、右沉虚，断为血下陷气亦下陷。前医但治血不知治气，故无效。当培补气血，佐收敛固涩，使气能摄血，血不下陷，则诸症可愈。", []], "20747": ["预后", "原文未出具体脉名，仅言「脉象亦有起色」。服药后下血与短气皆愈强半，诸病见愈，脉有起色，示气血渐复、气陷渐升。然起坐片时筋骨酸软，乃下焦肝肾未充、筋骨失养，故仍宜培补气血、固摄下焦兼壮筋骨。", []], "20748": ["病机", "左部沉弦，右部沉涩，一息四至强。沉弦主肝郁气逆，沉涩主血瘀气滞。气血上涌则昏然身挺、四肢抽掣；腹中作疼揉之少瘥，乃气滞血瘀、肝木乘脾。脉沉弦涩数，示郁热内扰、气血壅滞之病机。", ["沉", "弦", "涩", "数"]], "20749": ["病机", "左部沉弦，右部沉涩，一息近五至。沉弦主肝郁气结，沉涩主瘀血内停，数近五至示郁久化热。产后恶露少、月信未行，少腹胀满疼硬，乃瘀血结于下焦、气机不畅。脉证合参，为瘀血癥瘕初结之病机。", ["沉", "弦", "涩", "数"]], "20750": ["预后", "原文未出具体脉名，仅言「脉亦较前舒畅」。服药六剂后腹已不疼，硬处未消但按之觉软，食量复旧，脉较前舒畅，示气机渐通、瘀结渐散，病势向愈。然硬处未消，仍需加减续服，以竟全功。", []], "20751": ["病机", "脉左右皆弦细无力，一息近六至。弦细无力主气血两虚、肝郁脾弱，数近六至为虚热内扰。癥瘕大如复盂、按之甚硬，乃瘀结日久；饮食减少、寒热往来、咳嗽吐痰、身体羸弱，皆气血亏耗、正虚邪结之候，故脉细数无力。", ["弦", "细", "数"]], "20752": ["预后", "原文述复诊时寒热已愈、饮食加多、咳嗽吐痰大轻减，症瘕虽未消但已不疼，且“其脉亦较前颇有起色”，说明前药切中病机，虚劳渐复，脉象好转为向愈之兆，故预后良好，可续以半补虚劳半消症瘕之方缓图。", []], "20753": ["预后", "三诊时咳嗽吐痰皆愈，身形渐强壮，“脉象又较前有力，至数复常”，表明虚劳已愈，正气渐复，脉象由弱转有力、至数复常为向愈之征，故曰“虚劳已愈，无庸再治”，唯余症瘕未消，可专药消之。", ["有力"]], "20754": ["主病", "脉象洪实，右部尤甚，且满面火色、微喘、烦躁作渴、舌苔白而微黄、大便未行，显系阳明府热已实，热盛于内，故脉洪实；右部尤甚者，热壅气分也。此脉主阳明实热证，与壮热、烦渴、喘满、便闭相应。", ["洪", "实"]], "20755": ["病机", "脉洪实兼数，为阳明府热已实之象；然产后阴虚生内热，略为外感拘束而即成温病，故洪实之中兼数，又寓阴虚之机。其烦躁而渴、微喘、舌苔白而微黄，皆热入阳明、阴亏不纳之候，故脉主府热实而兼阴虚。", ["洪", "实", "数"]], "20756": ["预后", "复诊服药一剂后热退强半，渴喘皆愈，“脉象已近和平”，说明邪热已衰，正气渐复，脉由洪实转平和，为病退向愈之象；惟大便未通，余热未清，故宜大滋真阴以退余热，少佐补气以助真阴复。", ["和平"]], "20757": ["病机", "流产后气血上涌，不能进食，动则作喘、眩晕、怔忡，脉象微弱，两尺无根，此下焦暴虚，肾气不能固摄冲气，冲气上逆，胃气不降，故脉微弱无根，主肾虚冲逆、胃气不纳之病机。", ["微", "弱"]], "20758": ["病机", "原文未直接描述脉象，但诊断指出流产后下焦暴虚，肾气不能固摄冲气，冲气上逆，胃气不降，故胀满不能食。此病机关键在“下焦暴虚”与“冲气上冲”，脉当现微弱无根之象，治宜峻补重镇，忌开破。", []], "20759": ["病机", "脉觉寒时似近闭塞，热时又似洪大而重按不实，一息五至强，此温疹毒热内攻，热盛于里则脉洪大，然重按不实，且寒热往来，乃正虚邪实、毒热内陷之象，故脉主热毒壅盛而正气已伤之病机。", ["洪", "大"]], "20760": ["预后", "原文言“脉已近和平，惟至数仍数”，是邪热大势已退、脉象趋于调和，但数象未除，说明外感虽愈十之八九，而真阴尚未恢复。数脉在此非实热，乃阴亏未复、虚热内扰之征，故断为“真阴犹未复”，预后当以滋补真阴、培养血脉为法，使血脉调和则月信通顺。", ["数", "和平"]], "20761": ["预后", "原文言“再诊其脉已和平四至矣”，是经三诊连服四剂后，饮食增加、精神振作、诸病皆无，脉由病象转为和平四至，即脉率匀调、不浮不沉、不迟不数，示邪退正复、气血渐和。惟腹中时疼，为月信欲通未通、瘀滞未尽，故知凉药宜减，少加活血化瘀之品，属病势向愈之预后判断。", ["和平"]], "20762": ["病机", "左部弦而微硬、右亦近弦，重诊无力而一息逾五至，弦为肝木偏旺、硬示木失柔和，数而无力则阴分已亏。木旺克土故饮食减半、消化不良；阴虚内热故心中觉热思凉、便干数日一行；申时潮热、黎明微汗、夜咳略甚，皆阴虚阳浮、肝肺不和之候，脉象与症相符。", ["弦", "硬", "数"]], "20763": ["病机", "左脉弦而兼硬，为心血虚损不能润肝滋肾，肝失濡养则脉弦硬；右脉弦而无力，示肺津胃汁皆亏、肺胃气分不足。合饮食减少、生血不足致经闭，午前凉为气分不足，晚间热、心中热为血虚阴亏生内热，便燥因脾胃失传送、血虚不润，咳嗽多痰由热伤肺、胃中消化不良生痰涎。", ["弦", "硬", "无力"]], "20764": ["病机", "脉濡弱而搏近五至，濡弱示气血不足、脉道不充，五至为稍数，主虚而有热。呼吸短气、呼气需努力，是宗气不足、肺失宣降；过午潮热不甚剧，属气虚发热或阴虚内热之轻证。合观脉症，病机为气阴两虚、虚热内扰，非实邪所致。", ["濡", "弱", "数"]], "20765": ["其他", "本段为《玉泉玉屑丹砂空青绿青曾青白青扁青石胆云母朴硝硝石芒硝滑石石钟乳紫石英矾石（马齿矾、绛矾、黄矾、青矾）白石英五石脂太一余粮紫禹余粮石中黄子禹余粮黄禹余粮金屑银屑水银（汞粉附）雄黄雌黄殷孽孔公孽石脑石硫黄熏黄阳起石凝水石石膏磁石玄石理石长石肤青石黛铁落生铁铁钢铁铁精铁浆食盐光明盐绿盐蜜陀僧桃花石珊瑚石花乳床青琅玕礜石特生礜石握雪礜石方解石苍石土殷孽代赭卤碱大盐戎盐青盐赤盐白垩铅丹锡粉锡铜镜鼻铜弩牙金牙石灰冬灰炭锻灶灰伏龙肝东壁土半天", []], "20766": ["其他", "本段为凉州、甘州、肃州、伊州、瓜州、西州、沙州各地所产药物清单，如大黄、白附子、鹿茸、椒根、肉苁蓉、百脉根、伏翼、葵子、甘草、蒲桃、石膏等，未涉及脉象描述，亦无病机、主病或症候内容，故无法作脉学病机分析，仅属本草产地记录。", []], "20767": ["其他", "本段为方药组成，非脉象论述，未识别出脉名，故脉象要素为空。原文列白磁屑、伏龙肝、柏叶、青羊脂、艾叶、五石脂、赤箭、天名精、蒲黄、生地黄、黄芩、茜根、败船茹、水苏、白胶、马屎、槲脉等药，多属止血、清热、温摄之品，推测用于出血诸证，但段中无脉象与病机文字，不能据药反推脉象，故不作主病、病机判断。", []], "20768": ["其他", "此段仅存篇题「利血脉第六十一」，无脉象描述，亦无病机论述。篇题提示所论与通利血脉相关，但原文未及具体脉形、主病或症候，故不能据以推断病机。脉象要素无从摘取，主旨归为其他，待补全原文后再作分析。", []], "20769": ["其他", "此段为药物主治条文，述玉泉味甘平无毒，主五脏百病、柔筋强骨、安魂魄、长肌肉、益气、利血脉，疗妇人带下十二病等。全段无脉象记载，所论为药性功效而非脉诊病机，故脉象要素为空，主旨不属主病、病机诸类，暂归其他。", []], "20770": ["其他", "此段述丹砂味甘微寒无毒，主身体五脏百病，养精神、安魂魄、益气明目、通血脉，止烦满消渴，杀精魅邪恶鬼，除中恶腹痛毒气等。通篇为药物功用，未涉脉象与脉诊判断，故不能归纳脉象要素，主旨亦非脉学病机，归入其他。", []], "20771": ["其他", "此段述空青味甘酸寒，主青盲耳聋、明目、利九窍、通血脉、养精神、益肝气，疗目赤痛、去肤翳、利水道、下乳汁、通关节、破坚积。全段为药性主治，无脉象描述，故脉象要素为空；所论非脉诊病机，主旨归其他。", []], "20772": ["其他", "此段述朴硝味苦辛大寒，主五脏积热、胃胀闭，涤去蓄结饮食，推陈致新，除邪气，疗五脏十二经脉中百二十疾、暴伤寒、腹中大热等。原文虽言「五脏十二经脉」，但指药治范围，非脉象，故脉象要素为空，主旨归其他。", []], "20773": ["其他", "此段述硝石味辛苦大寒，主五脏积聚、久热胃闭，除邪气、破留血、腹中痰实结搏，通经脉、利大小便及月水、破五淋、推陈致新。全段为药物主治，未载脉象，故脉象要素为空；所论属药性功效，非脉诊病机，主旨归其他。", []], "20774": ["其他", "此段述方石味辛苦寒无毒，主身热、胃中结气、四肢寒厥，利小便、通血脉、明目去翳眇、下三虫、杀蛊毒、止消渴、下气除胁肋肺间邪气。通篇为药性主治，无脉象记载，故脉象要素为空，主旨不属脉学病机，归其他。", []], "20775": ["其他", "此段述黄石味苦辛大寒无毒，主胸中留热结气、黄疸，通血脉，去蛊毒。原文简短，仅言药性与主治，未及脉象，故脉象要素为空；所论为药物功用而非脉诊病机，主旨归其他。", []], "20776": ["其他", "此段为药物主治条文，未及脉象。文中“除五脏血脉中热，血痹血瘀”点明药性入血分，所主鬼疰、蛊毒、腹中毒邪气及女子赤沃漏下、产难胞衣不出，皆属瘀热与邪毒互结之候，故以“养血气”“除血脉中热”为治，非凭脉断病，列于其他。", []], "20777": ["治法", "本段言外治法，先“刺腋下脉出血”以泻局部郁热，再以醋和药封之攻腋臭；又熬药投酒治“贼风反折”，烧赤铜纳酒治贼风。刺脉出血属泻法，针对络脉壅滞，全段重在治法操作与验效，未涉脉象主病，故归治法。", []], "20778": ["其他", "此段为药性主治，未言脉。文中“主心腹结气，伤中伤饱，胃络脉绝，羸瘦短气”提示中焦气结、胃络失养之虚损候，故能“消谷调中”“强阴益精”“令人肥健有子”。所举身重目黄、心下支满、虚劳客热，皆脾胃不足、津亏之症，属药治范围而非脉诊。", []], "20779": ["其他", "全段述药之主病，无脉象。“主折跌，绝筋伤中，逐血痹，填骨髓，长肌肉”说明其功在续筋补髓、行血通痹；“破恶血，溺血，利大小肠”则示活血利窍之力。所治五劳七伤、女子伤中胞漏下血，皆精血亏虚兼瘀滞之候，属本草主治，非脉法。", []], "20780": ["其他", "此段为菊花主治，未及脉。“主风头头眩肿痛，目欲脱，泪出”示风热上攻头目；“皮肤死肌，恶风，湿痹”示风湿痹阻肌表；“除胸中烦热，安肠胃，利五脉，调四肢”则示清降通调之效。全段以药性证治为主，无脉象可辨，故列其他。", []], "20781": ["其他", "甘草条，无脉象。文中“主五脏六腑寒热邪气，坚筋骨，长肌肉，倍力”示补益之功；“温中下气，烦满短气，伤脏咳嗽”示和中降气止咳；“通经脉，利血气，解百药毒”示调和通利。所治皆虚损、邪气、药毒之候，属本草主治，非凭脉立论。", []], "20782": ["其他", "人参条，未言脉。“主补五脏，安精神，定魂魄，止惊悸，除邪气”示补虚安神、扶正祛邪；“疗肠胃中冷，心腹鼓痛，胸胁逆满，霍乱吐逆”示温中调气；“通血脉，破坚积”示补中兼通。所主惊悸、虚冷、坚积皆气血不足兼气滞之候，属药治范围。", []], "20783": ["其他", "芍药条，无脉象。“主邪气腹痛，除血痹，破坚积，寒热疝瘕”示其能行血散结、缓中止痛；“散恶血，逐贼血，去水气，利膀胱大小肠”示活血利水；“消痈肿，时行寒热”示和营泄热。所治皆血痹、坚积、水气之候，属本草主治，非脉诊内容。", []], "20784": ["其他", "此段为药物主治条文，未涉及脉象。原文述其味辛甘平无毒，主去恶虫、除脾胃寒热、通利九窍血脉关节，疗脾疸常欲眠、心烦哕出音声、耳聋痈肿结不消及金疮恶疮等。所主病机为脾胃寒热壅滞、九窍血脉关节不通，故以通利为治，非脉诊内容。", []], "20785": ["其他", "此段仅存药名「百脉根」，无脉象描述，亦无病机症候可析。原文极简，未言性味主治，无法据以推断所主病机。按体例归入其他类，脉象要素为空，不作臆测。", []], "20786": ["其他", "此段为药物主治条文，未言脉象。原文述其味咸甘温微温冷利有小毒，主结气胁下满、惊悸、除水、去脏间寒热、消胸上痰结唾如胶漆、心胁痰水、膀胱留饮、风气湿痹等。所主病机为水饮痰结停聚胸胁膀胱、寒热错杂，故以除水消痰通血脉为治。", []], "20787": ["其他", "此段为药物主治条文，未涉及脉象。原文述其味辛温无毒，主上气咳逆、结气喉痹、吐吸心痛、胁风胁痛，能温筋通脉、止烦出汗、利关节、补中益气。所主病机为寒邪结气上逆、筋脉不通，故以辛温通脉散结为治，非脉诊内容。", []], "20788": ["其他", "此段为药物主治条文，未言脉象。原文述其味甘辛大热有小毒，主温中、利肝肺气、心腹寒热冷疾、霍乱转筋、头痛腰痛、出汗止烦止唾、咳逆鼻齆，能堕胎、坚骨节、通血脉、宣导百药。所主病机为寒凝气滞、血脉不通，故以辛热温通为治。", []], "20789": ["其他", "此段为药物主治条文，未涉及脉象。原文述其味甘寒无毒，主伤中五劳六极、羸瘦、崩中脉绝，补虚益气，去肺中水气，治唾血热渴、水肿腹满胪胀，利水道。所主病机为虚损兼水气内停、热伤血络，故以补虚益气利水为治，非脉诊内容。", []], "20790": ["其他", "此段为药物主治条文，未言脉象。原文述其味辛温有大毒，主伤寒温疟寒热，破症瘕结聚、坚积、留饮痰癖、大腹水胀，荡涤五脏六腑、开通闭塞、利水谷道，疗女子月闭烂胎。所主病机为痰饮症瘕结聚、闭塞不通，故以峻猛攻逐开通为治。", []], "20791": ["其他", "此段为药物主治条文，未涉及脉象。原文述其味辛温大热有毒，主邪气咳逆、温中、逐骨节皮肤死肌、寒湿痹痛、下气，除六腑寒冷、心腹留饮宿食、肠澼下痢，散风邪瘕结水肿，开腠理通血脉。所主病机为寒湿风邪痹阻、阳气不通，故以辛热温通为治。", []], "20792": ["其他", "此段为药物主治，非论脉。文中“取脉灸用之”之“脉”指植物叶脉或茎脉，非脉象。全段述其味甘苦、平、无毒，主痔止血、疗血痢、止渴，属本草药性主治，与脉诊病机无关，故脉象要素为空，不涉脉理。", []], "20793": ["其他", "此段为药物性味功用，非脉诊原文。“利血脉、益经气”指药能通利血脉、补益经气，属药理作用，非指脉象。全段言味甘温、无毒，主男女伤中、阴气不足，以酒服之，为药物主治范畴，不涉及脉象要素与脉机分析。", []], "20794": ["其他", "此段为药物主治，非论脉。“脉绝”指血脉虚绝之病证，非脉象描述；药主伤中、脉绝、阴不起，强志益气，长肌肉，肥健生子，并治小儿惊痫。全段属本草药性功用，虽涉“脉绝”病名，但非脉象要素，故脉象为空。", []], "20795": ["其他", "此段为药物性味主治，非脉诊。“绝脉”指血脉断绝之病证，非脉象。药味甘温，主丈夫女子伤中绝脉、筋急痛、咳逆，以酒和服。全段属本草主治范畴，言药能治血脉虚绝之病，不涉及具体脉象要素，故脉象为空。", []], "20796": ["其他", "此段为药物性味及禁忌，非论脉。“闭血脉”指药性苦能闭塞血脉，属药理作用，非脉象。全段言味苦，主闭血脉、弱筋骨、虚人肌，不可久食，病人金疮者尤甚，属本草药性与禁忌，不涉脉象要素与脉机。", []], "20797": ["其他", "此段为药物主治，非脉诊。“通利血脉”指药能通利血脉，属药理功用，非脉象。全段述味苦微寒有毒，主逐瘀血、破血积、坚痞症瘕寒热，通利血脉及九窍，治女子月水不通、积聚、贼血在胸腹五脏及喉痹结塞，属本草主治范畴。", []], "20798": ["其他", "此段为药物性味主治，非论脉。“通利血脉”指药能通利血脉，属药理作用，非脉象。全段言味咸寒有毒，主血瘀、症坚寒热，破积聚、喉咽痹、内寒无子，通利血脉，属本草药性主治，不涉及脉象要素与脉机分析。", []], "20799": ["其他", "此段为药物主治，非脉诊。“保血脉”指药能保养血脉，属药理功用，非脉象。全段言味甘平无毒，主女子赤沃，止血养精，保血脉，益气，令人肥健嗜食，一名水英，属本草药性主治范畴，不涉脉象要素与脉机。", []], "20800": ["其他", "此段为药物性味功用记载，非脉学原文，未涉及脉象。文中\"复血脉\"\"乳妇产后余疾\"提示该药有通利血脉、调补产后之功，然全段无脉象描述，不能据以推断病机，故脉象要素为空，主旨归入其他。", []], "20801": ["其他", "此段仅载药物性味及\"主气脉溢\"，属本草主治条文，非脉诊论述。\"气脉溢\"指气机壅盛、血脉满溢之证，但原文未出脉象，无法据脉析机，故脉象要素为空，主旨列为其他。", []], "20802": ["其他", "此段为药物性味主治，言\"充肌肤，益气，令人暴肥\"，又诫\"不可久服，血脉满盛\"，提示久服致血脉壅盛之弊，然全段无脉象记载，不能作脉机分析，脉象要素为空，主旨归其他。", []], "20803": ["其他", "此段为面膏制作工艺，述浸药、煎炼、绞滤、涂面之法，\"去脉\"指剔除羊胰筋膜，非脉诊之脉。全段与脉学无关，无脉象可录，脉象要素为空，主旨列为其他。", []], "20804": ["妇人", "此段论妇人带下五贲，列热病下血、寒热下血、漏血、伤妊脉下血、产后经利五类，总括为\"外实内虚\"。文虽未出具体脉象，然\"举重伤妊脉\"点明妊脉受损之机，属妇人病范畴，故主旨归妇人，脉象要素为空。", []], "20805": ["病机", "太阳病本应脉浮，今发热而脉沉细，是邪郁于表而正气不足、筋脉失养之象。沉为在里，细为血少，表证见里虚之脉，津血不能濡养筋脉，故发为痓，症见项背强急。此以脉沉细揭示痓病正虚邪滞之病机。", ["沉", "细"]], "20806": ["兼症", "此段述痓病见症：身热足寒、颈项强、恶寒、时头热面赤、目脉赤、独头动摇。\"目脉赤\"指目络血脉红赤，非脉诊之脉。全段以症候描述为主，未出脉象，故脉象要素为空，主旨归兼症，示痓病邪郁于上、阳气壅遏之候。", []], "20807": ["病机", "太阳病关节疼烦而脉沉缓，沉主里、主湿着，缓主湿性濡滞。湿邪痹阻关节，气血运行不畅，故疼烦；脉不浮而沉缓，说明湿邪已着于肌肉关节之间，非单纯表证。此脉揭示湿病偏里、湿滞关节之病机。", ["沉", "缓"]], "20808": ["病机", "喘而头痛鼻窒烦，脉大却能饮食、腹中和，说明病不在里而专在头中寒湿。脉大为邪气壅于上、清窍不利之象，非里实之洪大；寒湿蒙蔽鼻窍故窒，湿郁化热则烦。纳药鼻中取嚏通窍即愈，正合邪在头面局部之病机。", ["大"]], "20809": ["病机", "夏月伤冷水，水行皮肤，故身热疼重；脉微弱非阳虚，乃水湿遏阻、阳气不能外鼓之象。水气在表，营卫不畅，脉道不充，故见微弱。此中暍夹水湿，与单纯暑热伤气之脉虚不同，主水湿浸淫肌表之病机。", ["微", "弱"]], "20810": ["病机", "太阳中暍而见弦细芤迟，弦细为暑伤气阴、筋脉失养，芤迟为津血不足、脉道不充且行迟。故发热恶寒、身重疼痛，小便后手足逆冷，劳则热，齿燥，皆气阴两伤之候。原文诫发汗、温针、数下，正因本虚不可再伤，示误治之害。", ["弦", "细", "芤", "迟"]], "20811": ["病机", "仅言太阳病其脉浮，浮为邪在表、卫气趋外抗邪之象，是太阳表证之提纲脉。脉浮与太阳病相应，说明病位在肌表，未入里。此段以脉浮点明表证属性，为辨太阳病脉证之总纲，非专主某一兼症。", ["浮"]], "20812": ["病机", "发热汗出恶风而脉缓，缓为营卫不和、肌腠疏松之象，风邪中于卫表，营阴外泄，故汗出恶风。脉缓非虚弱，乃风性疏泄、脉道弛缓。此即太阳中风之典型脉证，主风邪袭表、营卫失调之病机。", ["缓"]], "20813": ["误治", "太阳病三日，已发汗吐下温针而病不解，此为坏病，非单纯表证，故桂枝汤不可复与。原文未出具体脉名，只言观其脉证、知犯何逆、随证治之，强调误治后证情复杂，须凭脉辨证求因，不可拘执一方。", []], "20814": ["误治", "桂枝汤本为解肌和营，适用于脉缓汗出之中风。今脉浮紧、发热无汗，为寒邪束表、营卫闭郁之伤寒表实，非桂枝汤所宜。浮紧示邪在表而腠理致密，与浮缓相对，故原文诫不可与，防其助热留邪，属辨脉防误之论。", ["浮", "紧"]], "20815": ["病机", "太阳外证未解而脉浮弱，浮为邪仍在表，弱为营卫不足、汗源不充。此非表实之浮紧，乃表虚中风之类，故当以汗解而宜桂枝汤，取其解肌调和营卫，微汗而不伤正。脉浮弱正示正虚邪恋、宜缓汗之病机。", ["浮", "弱"]], "20816": ["病机", "原文两言「其脉浮」，并明训「浮为在外」。太阳病先发汗不解，又误下，脉仍浮，说明邪未内陷，病位仍在表。浮脉主表、主外，故不当再下，当「解其外则愈」。此段以脉浮定病位在表，属病机与治法相应之论，非主里虚或里实。", ["浮"]], "20817": ["病机", "原文未出脉名，以「病常自汗出」立论，谓「荣气和，卫气不和」。荣行脉中、卫行脉外，卫外不固则常自汗。复发其汗，使卫气和则愈。此段从营卫不和释自汗病机，脉象无载，故脉素取空，主旨归病机。", []], "20818": ["病机", "伤寒发汗已解，半日许复烦，脉见「浮数」。浮为邪在表，数为热、为邪未净，故知表邪复聚而烦。脉浮数说明病仍在外，可复发其汗，宜桂枝汤。此以脉浮数定表热未解之病机，非里热入府之数。", ["浮", "数"]], "20819": ["病机", "原文云「其脉阴阳俱停」，非具体脉名，指尺寸脉一时隐伏停止，乃邪正相争、阳气郁遏之象，故必先振栗，汗出而解。「但阳微者，先汗之而解」，说明脉停非死候，而是欲作汗解之机。脉素取空，主旨辨病机与转归。", []], "20820": ["病机", "太阳病误下后「其脉促胸满」，促为阳气受挫、邪陷胸中、气机不利之象，胸满即其症。故用桂枝去芍药汤，去芍药之酸敛，使阳气宣通；若微寒者，更加附子温阳。此段以脉促胸满示误下后胸阳不振、邪滞之病机。", ["促"]], "20821": ["预后", "太阳病八九日如疟，脉「微缓者，为欲愈」，微缓示邪气渐衰、胃气渐和；「脉微而恶寒者，此为阴阳俱虚」，则不可吐下发汗。同见微脉，一缓一恶寒，转归迥异。此段以脉微缓与微而恶寒辨欲愈与阴阳俱虚，主旨在预后。", ["微", "缓"]], "20822": ["病机", "服桂枝汤后大汗出，脉见「洪大」。洪大为阳气浮盛、热势外扬之象，然形如疟、一日再发，说明表邪未尽而汗出过多，营卫失调。故仍与桂枝汤，并宜桂枝二麻黄一汤微汗调之。此以脉洪大辨汗后阳盛邪恋之病机。", ["洪", "大"]], "20823": ["病机", "太阳病发热恶寒、热多寒少，而「脉微弱，则无阳也」。微弱示阳气虚衰，无力鼓动，故不可发汗，恐更伤阳。主以桂枝二越婢一汤，小发其汗兼清郁热。此段以脉微弱定无阳之病机，与热多寒少之症相参，示禁汗之戒。", ["微", "弱"]], "20824": ["主病", "脉阴阳俱紧，指寸尺皆见紧象。紧主寒，寒邪外束太阳，卫阳被遏，故必恶寒；寒凝经脉则体痛；寒犯胃腑、胃气上逆则呕逆。或已发热或未发热，正邪交争之象。紧脉与恶寒体痛呕逆并见，正是伤寒表实寒邪束表之病机，故断为伤寒。", ["紧"]], "20825": ["病机", "伤寒一日邪在太阳，脉弱示正气不足、邪未深入；至四日邪传太阴，脉大示邪气转盛、病位入里。以脉之弱、大随日数变化，说明邪由太阳传入太阴的传变过程，脉象由弱转大反映病机由表入里、邪势渐盛，属以脉测传经之论。", ["弱", "大"]], "20826": ["病机", "脉若静者，脉象未变，示邪留太阳而不传；若颇欲呕、躁烦，脉转数急，数主热、急主邪势急迫，说明邪气内传、正邪交争加剧。以脉静与脉数急对举，判断伤寒是否传变，脉数急为邪已传里之征，故曰乃为传。", ["数", "急"]], "20827": ["兼症", "病十日已去而脉浮细，浮示邪仍在表、细示正气渐虚，嗜卧为邪退正复之象，故谓外解。若胸满胁痛，则邪涉少阳，与小柴胡汤；浮者仍偏表实，主以麻黄汤。本条以浮细辨外解与兼症，脉浮细为表邪未尽而正已不足之候。", ["浮", "细"]], "20828": ["主病", "脉浮紧为太阳伤寒表实证，浮主表、紧主寒，寒束肌表则无汗发热身疼痛。八九日不解而表证仍在，当发其汗。服药后发烦目瞑、增剧必衄，乃阳气重、郁热不得外泄而迫血妄行，衄后邪随血解。脉浮紧紧扣表实寒凝、阳气郁遏之病机。", ["浮", "紧"]], "20829": ["治法", "脉浮主邪在表，热数示表有郁热、正邪交争而脉行急数。浮而数并见，说明邪仍羁表而热势已显，病机为表实兼郁热，故可发其汗，宜麻黄汤开表泄热。本条以脉浮数定可汗之治法，脉象为表实郁热、宜汗解之依据。", ["浮", "数"]], "20830": ["误治", "脉浮紧为伤寒表实，当发其汗而反不发，寒邪郁闭、阳气不得外达，郁热内迫血分，因而致衄。此以脉浮紧说明表实未解、当汗失汗，致邪热迫血妄行之病机，衄虽出而表证仍在，故仍宜麻黄汤解表，属失汗致衄之误治。", ["浮", "紧"]], "20831": ["病机", "脉浮而紧，浮为风、紧为寒，风伤卫、寒伤荣，荣卫俱病则骨节烦疼。本条以浮紧分释风寒伤卫伤荣之病机，说明表实寒凝、营卫俱受邪而致骨节疼痛，故可发其汗，宜麻黄汤。脉浮紧为风寒束表、营卫俱病之征。", ["浮", "紧"]], "20832": ["病机", "太阳桂枝证本应解表，医反下之，致里气受损而下利不止。脉促为阳气被遏、抗邪外出之象，说明表邪未解而里热已生。喘而汗出是热迫于肺、津液外泄，故用葛根黄芩黄连汤解表清里。促脉在此非主死候，而是表里同病、邪热内迫之征。", ["促"]], "20833": ["误治", "脉浮紧主风寒束表、卫闭营郁，故发热恶寒、身疼不汗出而烦，宜大青龙汤发汗。若脉微弱、汗出恶风，则属表虚阳弱，不可峻汗；误服大青龙则阳气更伤，出现厥逆、筋惕肉𥆧，此为逆治。原文以浮紧与微弱对举，明辨表实可汗与表虚禁汗之别。", ["浮", "紧", "微", "弱"]], "20834": ["病机", "脉浮缓而身不疼但重、乍有轻时，说明表邪仍在而兼有水气郁滞，非少阴里虚之身重。浮主表，缓主湿滞，水气泛溢故身重，邪正交争故乍有轻时。无少阴证则排除阳虚里寒，故可与大青龙汤发越水气、外解表邪。", ["浮", "缓"]], "20835": ["误治", "脉迟浮弱，浮为表邪未尽，迟弱为里气已虚。恶风寒、手足温示表证尚存，医再三下之则脾胃更伤，故不能食、胁下满痛、面目及身黄、小便难，为湿郁发黄之候。颈项强为表未解，本渴饮水而呕、食谷者哕，皆中虚气逆，柴胡汤亦不中与，属误下变证。", ["迟", "浮", "弱"]], "20836": ["病机", "阳脉涩、阴脉弦，阳涩为气血不足，阴弦为木气偏盛、克伐中土，故法当腹中急痛。先与小建中汤温中缓急，不瘥再与小柴胡汤和解枢机。前段身体热恶风、颈项强、胁下满、手足温而渴，为少阳兼表之证，小柴胡汤主之。涩弦并见，示虚与郁并存。", ["涩", "弦"]], "20837": ["病机", "脉细为阳微，沉紧为病在里，然头汗出、微恶寒、手足冷、心下满、大便坚，为阳微结之候，半在表半在里。纯阴结当无外证，今有头汗出，知非少阴，故虽沉紧不得为少阴病。阳微结者，阳气郁结不能外达，可与柴胡汤和解，得屎而解。", ["细", "沉", "紧"]], "20838": ["治法", "伤寒发热汗出不解，心中痞坚、呕吐下利，为少阳阳明合病，大柴胡汤主之。病人表里无证而发热七八日，虽脉浮数，亦示邪热偏盛、里实已成，故可下之，宜大柴胡汤。浮数在此非单纯表脉，而是热盛于里、外显浮数，故从里实论治。", ["浮", "数"]], "20839": ["预后", "太阳病未解而脉阴阳俱停，为邪正相争、脉气一时隐伏之象，非死脉。正气蓄积而奋起抗邪，故必先振栗，继而汗出而解。若阳脉微者，先汗出而解；阴脉微者，先下之而解，宜承气汤。此段以脉停言战汗作解之机，示预后转归与因势利导之法。", []], "20840": ["误治", "原文辨误下后脉证：本当自利脉微厥，今反脉调和，知非虚寒而是内实，故宜承气汤。脉调和在此非平脉，乃相对微厥而言，示邪未因误下而虚，仍属阳明腑实，主谵语、大便坚等症。", ["微", "和"]], "20841": ["病机", "寸口浮关上沉为结胸，阳脉浮关上细沉紧为脏结。浮主阳热在上，沉紧主寒结在里，细为阴伤。脏结无阳证、反静、舌胎滑，示纯阴无阳，故不可攻；结胸因下早热入，故脉浮沉并见。", ["浮", "沉", "细", "紧"]], "20842": ["预后", "结胸证脉浮大，浮为表邪未罢，大为热盛而虚，示邪尚在表、里未成实，故不可下。下之则表邪内陷，正气骤脱，故曰下之即死。此以脉浮大禁下，明结胸可下之脉当沉紧。", ["浮", "大"]], "20843": ["病机", "浮为风，数为热，动为痛，数又为虚。太阳表未解而误下，动数变迟，胃中空虚，客气动膈，阳气内陷，心下因坚成结胸。脉浮动数示表热与痛，误下后脉迟示邪陷正虚，故见短气躁烦、心中懊𢙐。", ["浮", "动", "数"]], "20844": ["主病", "结胸热实脉沉紧，沉主里，紧主痛主实，示热邪与水饮结于胸胁，故心下痛、按之如石坚。无大热而头微汗出，为水结在胸胁、热郁于里，故均主大陷胸汤。", ["沉", "紧"]], "20845": ["主病", "小结胸正在心下，按之即痛，脉浮滑。浮示热浅未深结，滑主痰热内壅，故病位局限、程度较轻，不似大结胸之沉紧石坚。浮滑为痰热互结之象，主小陷胸汤证。", ["浮", "滑"]], "20846": ["误治", "太阳病二三日，不能卧但欲起，心下必结，脉微弱示本寒阳虚。反下之，利止者阳伤而邪陷成结胸；利未止者，四五日复重下，挟热而利。脉微弱为本寒之征，误下则变结胸或挟热利。", ["微", "弱"]], "20847": ["误治", "太阳少阳并病，当刺禁汗。发汗则谵语，谵语而脉弦，弦为少阳木旺之象，示汗伤津液、少阳邪热内扰神明。五日谵语不止，当刺期门以泻肝热。脉弦在此主少阳热郁、谵语之机。", ["弦"]], "20848": ["病机", "脉浮紧本为表寒实证，误用下法，紧反入里，说明表邪内陷、气机壅滞于中焦，故成痞。按之自濡，提示无形气痞而非有形实结，紧脉入里反映寒邪与正气相搏、气结不散，主痞证而无实邪内结。", ["浮", "紧"]], "20849": ["治法", "心下痞按之自濡，为无形邪热壅聚中焦。关上脉浮，关候中焦，浮为阳热之象，说明热邪痞结于胃脘，非有形实滞。故以大黄黄连泻心汤清泄中焦邪热，脉浮在此提示病位在上焦气分、热痞之机。", ["浮"]], "20850": ["预后", "伤寒吐下发汗，津气两伤，故脉甚微，为阳气虚衰之象。心下痞坚、胁下痛、气上冲、眩冒、经脉动惕，皆因虚阳上逆、筋脉失养。脉微提示正气已虚，久则筋脉失濡而成痿，属误治伤正、虚风内动之预后不良。", ["微"]], "20851": ["病机", "病如桂枝证而头项不强痛，脉微浮，说明邪不在表而在胸中。胸中痞坚、气上冲喉咽不得息，为胸有寒痰实邪阻滞、气机不得宣降。微浮示病位偏上、邪有外出之势，故因势利导，用瓜蒂散吐之。", ["微", "浮"]], "20852": ["误治", "伤寒脉浮，本应汗解，医反以火迫劫取汗，致亡阳。浮脉在此为表邪未解之象，火劫发汗太过，阳气外亡，心神失守，故惊狂、卧起不安。脉浮提示邪仍在表而正已伤，治以救逆汤温阳镇惊、安神定志。", ["浮"]], "20853": ["病机", "太阳病六七日表证仍在，脉微而沉，说明邪热内陷下焦血分，非结胸之脉。热在下焦、少腹坚满而小便自利，为瘀热在里、血蓄下焦。脉微沉反映热瘀互结、气血不畅，故发狂，宜抵当汤下瘀泄热。", ["微", "沉"]], "20854": ["病机", "太阳病身黄，脉沉结，沉为在里，结为气血瘀滞不畅。少腹坚而小便不利者，属湿热发黄无血；若小便自利、其人如狂，则瘀血内结下焦，血证确凿。脉沉结正反映瘀热结于下焦、血行不畅之病机，故用抵当汤。", ["沉", "结"]], "20855": ["妇人", "妇人中风发热恶寒，经水适来，七八日后热除而脉迟身凉，为热邪乘经期血室空虚内陷。脉迟非寒，乃热入血室、血行瘀滞之象。胸胁下满如结胸、谵语，皆瘀热上扰神明，故刺期门以泄血室之热，随虚实取之。", ["迟"]], "20856": ["误治", "原文强调“伤寒脉浮，发热无汗，其表不解，不可与白虎汤”，脉浮主表邪未解，虽有发热无汗，若误用白虎汤清里，则表邪内陷。必待“渴欲饮水无表证”方可用之，说明脉浮在此提示表证存在，是禁用白虎汤的关键依据，与口燥渴烦、背微恶寒等里热症并见时，须辨表里先后。", ["浮"]], "20857": ["主病", "脉浮滑为表有热、里有寒之象。浮主表热，滑主里实，然原文谓“里有寒”，可知滑非实热之滑，乃寒饮内动、气血壅滞之滑。此脉与白虎汤证相应，说明热在表而寒在里，表里同病，故用白虎汤清表热、温里寒，脉象反映寒热错杂之机。", ["浮", "滑"]], "20858": ["病机", "伤寒八九日，风湿相搏，身体疼烦，不能自转侧，下已脉浮而紧。浮为风湿在表，紧为寒邪束表、气血不畅。下后脉仍浮紧，说明表邪未解，风湿仍搏于肌表，故用桂枝附子汤温经散寒、祛风除湿。脉浮紧与身体疼烦、不呕不渴相应，主风湿在表之病机。", ["浮", "紧"]], "20859": ["主病", "脉结代指脉来缓而时一止，止有定数或不定数，主气血虚衰、心脉失养。原文“伤寒脉结代，心动悸”，结代脉与心动悸并见，说明心之气血阴阳俱虚，鼓动无力，脉道不充，故用炙甘草汤益气滋阴、通阳复脉。此脉直接主心脉虚损之病机。", ["结", "代"]], "20860": ["病机", "伤寒三日，邪入阳明，阳明多气多血，邪热亢盛，鼓动气血，故脉大。大脉主阳明热盛，与阳明病身热、汗自出、不恶寒反恶热等症相应。原文仅言“阳明脉大”，点明脉大为阳明里热亢盛之标志，是判断邪入阳明、热势鸱张的重要脉象。", ["大"]], "20861": ["病机", "脉浮而缓，浮为太阴之表，缓为脾土之湿。手足温者，系在太阴，太阴湿郁，当发黄；若小便自利，湿有出路，则不能发黄。至七八日而坚，为湿从燥化，转属阳明。脉浮缓反映太阴湿困、表里同病之机，与手足温、发黄、小便不利等症相应，说明湿郁太阴之病机。", ["浮", "缓"]], "20862": ["误治", "阳明中风，口苦咽干，腹满微喘，发热恶寒，脉浮若紧。浮紧为表邪未解之象，虽有阳明里症，但表证仍在，不可下之。下之则表邪内陷，腹满更甚，小便难。原文以脉浮紧提示表邪未解，是禁用下法的依据，说明脉象在此主表里同病、先表后里之治则。", ["浮", "紧"]], "20863": ["病机", "阳明病脉迟，迟主脾胃虚寒、运化无力。食难用饱，饱即微烦头眩，小便难，此欲作谷疸。虽下之，腹满如故，所以然者，脉迟故也。脉迟说明中焦虚寒，湿浊内停，非实热可下，下之更伤脾胃。脉迟与食难用饱、头眩、小便难相应，主谷疸将作之病机。", ["迟"]], "20864": ["病机", "脉浮为热邪在表，紧为邪实，浮紧相合主阳明热盛兼表邪。原文言“其热必潮，发作有时”，潮热定时而作，是阳明里热已成；但浮者，热未全入里，迫津外泄，故“必盗汗出”。此脉说明热郁阳明、表里相争之病机，与潮热、盗汗相应。", ["浮", "紧"]], "20865": ["病机", "阳明病脉迟，非寒证，乃热邪壅滞、气血运行不畅所致。原文“虽汗出，不恶寒，其体必重，短气，腹满而喘，有潮热”，皆里热结实之象。脉迟而见手足濈然汗出，为“已坚”之征，热实内结，故可攻里，承气汤主之。此脉说明热结阳明、腑气不通之病机。", ["迟"]], "20866": ["预后", "脉滑疾为热实内盛，故谵语潮热，承气汤主之。若下后“脉反微涩”，微为气虚，涩为血少，是里虚之候，不可再攻。原文“此为里虚，为难治”，说明脉由滑疾转微涩，反映邪去正伤、虚实转化之病机，预后不良。", ["滑", "疾", "微", "涩"]], "20867": ["误治", "脉沉主病在里，喘满为里实气逆。原文“沉为在里，而反发其汗”，误汗伤津，致“津液越出，大便为难”，形成“表虚里实”。久则津亏热盛，扰乱神明而讝语。此脉说明里实误汗、津伤化燥之病机，属误治变证。", ["沉"]], "20868": ["治法", "脉实为阳明里热结实，故“当下之”，宜承气汤；脉浮虚为表虚邪留，故“当发其汗”，宜桂枝汤。原文以脉实、脉浮虚对举，说明同一烦热如疟之症，脉象不同则病机异，治法亦殊，体现凭脉辨表里虚实以定汗下之法。", ["实", "浮", "虚"]], "20869": ["病机", "脉浮弱为正气不足、邪气未实。原文“无太阳柴胡证，而烦心下坚”，虽似可下，但脉浮弱示里未成实，故先以小承气汤少与微和之。至六七日不大便而小便少，头坚后溏，未定成坚，不可峻攻。此脉说明正虚邪滞、燥结未实之病机，攻下须慎。", ["浮", "弱"]], "20870": ["主病", "阳明少阳合病下利，脉不负者为顺，言脉与证相符。滑而数者，滑主宿食，数主热，说明宿食内停、郁而化热，热结旁流而利。原文“有宿食，宜承气汤”，脉滑数正是宿食化热之征，主病为宿食积滞、热结阳明。", ["滑", "数"]], "20871": ["误治", "脉浮紧为邪热郁于阳明之表，原文“咽干口苦，腹满而喘，发热汗出，不恶寒，反偏恶热”，热盛于里。若误发汗则躁、愦愦谵语；加温针则怵惕烦躁；下之则胃中空虚，客气动膈，心中懊𢙐。此脉说明热郁阳明、误治致变之病机。", ["浮", "紧"]], "20872": ["主病", "脉浮为热邪在表，然渴欲饮水、小便不利并见，是表热未解而水蓄下焦、气化不行。浮脉在此提示热势偏外偏上，水热互结则小便不利；渴欲饮水为水停津不上承。猪苓汤育阴利水清热，正对水热互结之病机，非单纯表证。", ["浮"]], "20873": ["病机", "脉浮发热为热在表，口干鼻燥是热循经上灼，能食示胃气尚强、热未入腑。热盛于经，不得外泄，迫血妄行，故即衄。浮脉在此说明热势偏表偏上，衄乃郁热自寻出路，与口干鼻燥、能食相呼应，非虚寒失血之候。", ["浮"]], "20874": ["主病", "脉浮为表热未罢，迟为里阳不足、阴寒内盛，故称表热里寒。下利清谷是脾肾阳虚、腐熟无权之明证。浮迟并见，说明表邪虽在而里寒已急，若单解表则里阳更伤，故以四逆汤温里回阳，里和则表自解，此脉示病机重心在里寒。", ["浮", "迟"]], "20875": ["预后", "脉弦浮大，弦主少阳、浮主表、大示邪盛，合短气腹满、胁下心痛、鼻干嗜卧、一身悉黄、潮热哕逆，为阳明中风而三阳合病、湿热郁蒸。刺之小瘥而外不解，脉续浮则邪仍欲从表出，故与小柴胡汤；但浮无余证则与麻黄汤。不溺腹满加哕，是气化绝、胃气败，故曰不治，脉示邪盛正衰之危。", ["弦", "浮", "大"]], "20876": ["主病", "阳明病而脉迟，迟非里实之候，反见汗出多、微恶寒，是表阳不足、卫外不固，表邪未解。脉迟在此说明里无燥实内结，不可攻下，当从表解，故宜桂枝汤调和营卫。迟脉与汗多恶寒相应，提示病机偏于表虚，非阳明腑实之迟。", ["迟"]], "20877": ["主病", "阳明病脉浮，浮为邪在表、未入于里；无汗则表气闭郁，肺气不宣，故其人必喘。脉浮与无汗、喘并见，说明病机为风寒束表、肺失宣降，而非阳明里热。发汗则表解气畅，喘自愈，宜麻黄汤开表宣肺，此浮脉主表实无汗之证。", ["浮"]], "20878": ["病机", "无表里证而发热七八日，脉浮数似表，然无表证可凭，是热郁于里、血气壅滞。下已而脉数不解，合热消谷喜饥、不大便，为瘀血内结之征，故抵当汤主之。若数不解而下不止，则热迫肠络，必挟热便脓血。浮数在此示热势鸱张，非表邪未尽，脉与瘀血、便脓血相应。", ["浮", "数"]], "20879": ["病机", "脉阳微而汗出少者，是阳气虽微尚能固摄，津液未伤，故为自如；汗出多则阳微不能摄津，津液外亡，为太过。太过者阳绝于内，津亏肠燥，大便因坚。微脉在此说明阳气虚衰、卫外不固，汗多亡津是病机关键，与大便坚相应，示过汗伤正之变。", ["微"]], "20880": ["病机", "浮为阳热有余，芤为阴血不足，浮芤相搏则胃气生热而阳热独绝于内，阴不配阳。趺阳浮涩，浮示胃气强，涩示脾阴约束、小便数而津伤，故大便坚，成脾约之证，麻子仁丸润燥通便。此段以脉释胃热津亏、脾约便坚之病机。", ["浮", "芤", "涩"]], "20881": ["病机", "伤寒脉弦细，弦属少阳木气，细为血少，头痛发热为邪郁少阳经气。少阳禁汗，发汗则津伤胃燥而谵语，转属阳明。胃和则愈，不和则烦而悸，示少阳误汗伤津、邪传胃腑之变。脉弦细正是少阳本脉，主半表半里、不可发汗之机。", ["弦", "细"]], "20882": ["病机", "太阳不解转入少阳，胁下坚满、干呕不食、往来寒热，为邪结少阳枢机。脉沉紧示邪入里而气机紧束，未吐下则正气未伤，可与小柴胡汤和解。若误施吐下发汗温针，谵语而柴胡证罢，则为坏病，当审犯何逆而法治之。脉沉紧主少阳邪结、枢机不利。", ["沉", "紧"]], "20883": ["兼症", "三阳脉浮大，上关上，为阳热盛于上焦。但欲寐、目合则汗，示阳热内扰、卫气不固而寐中汗出。浮大为三阳热盛之象，关上候中焦，热壅于上，故见嗜寐合目汗出之兼症。此段以脉浮大上关上，说明阳热偏盛、营卫失和之候。", ["浮", "大"]], "20884": ["预后", "伤寒三日，邪在少阳，其脉本弦。今脉小而不弦大，示邪气已衰、正气渐复，故为欲已之兆。脉小为邪退之象，非虚损之小，乃少阳病向愈之征。此段以脉小判断少阳病势将解，属预后顺证，说明脉象由弦转小反映邪去正安。", ["小"]], "20885": ["治法", "太阴病腹满吐、食不下、时腹自痛、胸下坚结，本属里虚寒。若脉浮，示邪偏于表、正气尚能外达，故可发其汗，因势利导从表解。下之益甚，示里虚禁下。脉浮在此为可汗之凭据，说明太阴兼表、邪有外解之机，治当先解表而不可妄下。", ["浮"]], "20886": ["病机", "伤寒脉浮而缓，手足温，为邪系太阴。太阴湿土，脉缓主湿，浮示邪在表。湿郁当发黄，若小便自利则湿有出路而不发黄。至七八日暴利十余行自止，因脾家实、腐秽当去，故自止。脉浮缓说明太阴湿滞、脾运来复之病机，非虚寒下利。", ["浮", "缓"]], "20887": ["误治", "人无阳证而脉弱，示胃气虚弱、阳气不足。脉弱则其人续自便利，中气易动。设当用大黄、芍药攻下，须减其量，因胃气弱不耐攻伐，易致泄利。此段以脉弱说明胃气虚弱之体，提示用药当减峻药，属防误治、顾护胃气之论。", ["弱"]], "20888": ["病机", "少阴病以“脉微细”为提纲，微为阳气虚衰，细为阴血不足，脉道不充。阳虚不能鼓动，故但欲寐，反映心肾阳衰、神失所养之病机，主少阴本证之虚寒。", ["微", "细"]], "20889": ["病机", "“脉阴阳俱紧”而反汗出，紧为寒，阴阳俱紧示寒邪深入少阴，虚阳外越故汗出，属少阴寒化、虚阳上浮，法当咽痛而复吐利，为下焦虚寒、不能制溲之病机。", ["紧"]], "20890": ["治法", "“脉细沉数”细为阴血少，沉为病在里，数为虚热内扰，总属少阴里虚有热。病在里不可发汗，误汗则伤阴耗阳，故本条以脉示禁，主少阴里虚之治法禁忌。", ["细", "沉", "数"]], "20891": ["误治", "“脉微不可发其汗，无阳故也”，微为阳气衰微，汗之则更伤阳；尺中弱涩，弱为阳虚，涩为阴血少，下之则伤阴。本条以脉微、尺弱涩示禁汗禁下，属少阴虚寒误治之戒。", ["微", "弱", "涩"]], "20892": ["预后", "少阴病脉紧为寒盛，至七八日下利而“脉暴微”，紧去而手足反温，是寒邪退、阳气复之象，故为欲解，虽烦下利必自愈。脉紧反去示阴寒渐消，主少阴病向愈之预后。", ["紧", "微"]], "20893": ["预后", "少阴中风，“脉阳微阴浮”阳微为表邪已衰，阴浮为里阳来复，阴阳趋于调和，故为欲愈。此脉象反映少阴中风邪退正复之病机，主疾病向愈之预后。", ["微", "浮"]], "20894": ["治法", "少阴病吐利而手足不逆、反发热，是阳气尚存，故曰不死；“脉不足”示正气虚衰，灸少阴七壮以温阳复脉。本条以脉不足为据，主少阴虚寒证用灸法温经回阳之治法。", []], "20895": ["死脉", "少阴病四逆恶寒而蜷，阳气已衰；“其脉不至”为脉气断绝，阳亡不能鼓动血脉，更加不烦而躁，是阴盛格阳、神气散乱之危候，故主死。脉不至反映少阴阳气竭绝之死脉。", []], "20896": ["预后", "少阴病脉微细沉，阳气衰微、阴寒内盛之象；但欲卧、汗出不烦为阳微欲脱，自欲吐为阴寒上逆。至五六日自利更伤中阳，复烦躁不得卧寐乃残阳外越、阴阳离决之兆，故断为死候，脉证合参示预后凶险。", ["微", "细", "沉"]], "20897": ["治法", "少阴病始得之反发热，是少阴阳虚兼表寒外束；脉不浮而反沉，说明阳气不足、寒邪直入少阴。脉沉为里虚寒之征，与发热并见提示表里同病，故用麻黄细辛附子汤温经解表，脉沉是辨少阴兼表的关键依据。", ["沉"]], "20898": ["治法", "少阴病身体痛、手足寒、骨节痛，为阳虚寒湿内侵、气血凝滞不通；脉沉主里主寒，说明病在少阴之里而非表证。脉沉与手足寒相应，证实阳气虚衰、寒湿留着，故以附子汤温阳散寒除湿，脉沉为辨证眼目。", ["沉"]], "20899": ["误治", "少阴病下利脉微，本属阳衰阴盛，服白通汤后利不止、厥逆无脉、干烦，是阴寒格拒、药不得入之变。脉微乃至无脉，示阳气欲绝而虚阳上扰，故用白通加猪胆汁汤以咸苦反佐、引阳入阴，脉微为阳气衰微之明证。", ["微"]], "20900": ["预后", "此段言服白通加猪胆汁汤后脉象变化：脉暴出者，是阴液枯竭、残阳一时外露，属回光返照之死候；脉微续者，是阳气渐复、徐徐而生，故主生。原文以脉之暴出与微续判生死，体现少阴阳复以渐为顺、以暴为逆的预后规律。", []], "20901": ["治法", "少阴病下利清谷、里寒外热、手足厥逆、脉微欲绝，为阴寒内盛、虚阳格拒于外之真寒假热证。脉微欲绝是阳气衰微欲脱之征，与面赤、身反恶寒相应，故用通脉四逆汤破阴回阳、通达内外，脉微欲绝为辨证核心。", ["微"]], "20902": ["治法", "此段为通脉四逆汤方后加减法：服汤后其脉即出者愈，说明阳气来复、脉道通利则病向愈；面赤加葱白通阳，腹痛加芍药和络，呕加生姜，咽痛加桔梗，利止脉不出加人参益气复脉。诸加减皆围绕脉不出所反映的阳衰气弱而设。", []], "20903": ["治法", "少阴病其脉沉者，沉主里主寒，示少阴阳虚、阴寒内盛，病位在里而不在表。脉沉与少阴病本证相应，故当温之，宜四逆汤回阳救逆。此以脉沉定病性为寒、病位在里，是少阴病温法运用的脉象依据。", ["沉"]], "20904": ["病机", "脉弦迟，弦主饮主痛，迟主寒。少阴病见饮食入则吐、心中温温欲吐、手足寒，为胸中实邪阻滞，阳气不布。弦迟并见，说明寒饮实邪结于胸膈，故不可下，当因势利导吐之；若膈上寒饮干呕，则属虚寒，又不可吐，当温之。同一脉象须结合症候辨虚实。", ["弦", "迟"]], "20905": ["病机", "脉微涩，微为阳气衰微，涩为阴血不足、脉道不利。少阴病下利日久，阳微阴涩，中气下陷，故见呕、汗出、数更衣而反少，此滑脱不禁之象。脉微涩提示下焦阳虚、阴寒内盛，当温其上而灸之，以升举阳气。", ["微", "涩"]], "20906": ["预后", "厥阴中风，脉微浮为欲愈。微浮者，是阴病转阳、邪气外达之象，说明阳气来复，邪有外出之势，故为欲愈；若不浮，则阳气未复，邪仍内陷，为未愈。此以脉之浮沉判断厥阴病之转归。", ["微", "浮"]], "20907": ["预后", "伤寒厥利，反能食，恐为除中；食黍饼不发热，知胃气尚在，必愈。后三日脉之数，其热不罢，为热气有余。脉数主热，热盛不退，腐蒸气血，必发痈脓。此以脉数判断阳复太过、热毒壅聚之病机。", ["数"]], "20908": ["误治", "伤寒脉迟，迟为寒，六七日反与黄芩汤彻其热，是误以寒药攻寒。脉迟为寒，复除其热，则腹中冷，当不能食；今反能食，此为除中，胃气败绝，必死。此段以脉迟为寒，说明误治致中阳衰败之死候。", ["迟"]], "20909": ["病机", "伤寒脉微而厥，微为阳虚，厥为阳衰不达四末。至七八日肤冷，躁无安时，此为脏寒。蛔上入膈，故烦，须臾复止，得食而呕又烦，蛔闻食臭出，其人常自吐蛔，蛔厥者乌梅丸主之。脉微揭示脏寒为本，蛔扰为标。", ["微"]], "20910": ["死脉", "伤寒六七日，其脉数，手足厥，烦躁，阴厥不还者死。脉数主热，热盛于内而手足厥冷，是热深厥深、阴阳不相顺接之象。烦躁不宁，阴厥不回，说明阳气外越、阴寒内盛，阴阳离决，故主死。", ["数"]], "20911": ["误治", "伤寒五六日，不结胸，腹濡，脉虚复厥者，不可下之，下之亡血，死。脉虚为气血不足，复厥为阳虚不达，腹濡无实邪，此属虚寒。若误下，则竭阴伤血，故死。伤寒发热而厥，七日下利者，为难治，亦示正虚邪陷之危。", ["虚"]], "20912": ["治法", "脉促而手足厥逆，为阴寒内盛、阳气被遏，脉气急促不匀，非热盛之促，乃阳欲伸而寒拒之象。灸法温通阳气，使寒散阳复，促脉可平。此段以脉促定阳虚寒厥之机，灸之助阳，与四逆辈同意，属治法范畴。", ["促"]], "20913": ["主病", "脉滑而厥，滑主里热，厥为热深厥深、阳郁不达四末所致，非真寒。原文明言「其表有热」，实指里有热而外现厥冷，热邪内伏，故以白虎汤清泄里热，热除则厥回。滑脉在此为热盛之据，与寒厥脉微细迥别。", ["滑"]], "20914": ["主病", "手足厥寒而脉细欲绝，细为血虚，绝为阳衰，乃血虚寒凝、经脉不通之象。寒邪客于经脉，气血运行不畅，四肢失温，故厥寒脉细。当归四逆汤温经散寒、养血通脉，正对此血虚寒厥之机，与阳虚四逆汤证有别。", ["细"]], "20915": ["病机", "脉乍紧者，紧主寒主痛，乍紧为邪结胸中、气机忽阻之象。邪结胸中，心下满而烦，饥不能食，为痰食壅塞胸膈，气不上通。脉乍紧反映邪结有形、气机时通时阻，故用瓜蒂散因势吐之，邪去则脉平。", ["紧"]], "20916": ["预后", "大下后脉沉迟，沉为里，迟为寒，手足厥逆、下部脉不至，为阳衰阴盛、气血不能达于四末。咽喉不利、唾脓血、泻利不止，乃上热下寒、虚实错杂，故为难治。脉沉迟示阳气内衰，与唾脓血之上热并见，麻黄升麻汤寒热并调，属难治之候。", ["沉", "迟"]], "20917": ["预后", "下利有微热而渴，脉弱者，弱为胃气尚存、邪气已衰之象。下利伤津故渴，微热为余邪未尽，脉弱而非数急，说明正气渐复、邪不内陷，故可自愈。此以脉弱判断胃气未败、病势向愈，属预后之论。", ["弱"]], "20918": ["预后", "下利脉数，若微发热汗出，数为阳复、邪从表解之象，故自愈；设脉复紧，紧主寒主邪结，为寒邪未解、病势缠绵，故为未解。同一人脉由数转紧，反映邪正交争、寒邪复聚，脉象变化直接提示病解与否，属预后判断。", ["数", "紧"]], "20919": ["死脉", "下利手足厥而无脉，为阳气衰绝、脉道不通之危候。灸之而手足不温，阳不能复；反微喘者，阳气上脱、肾不纳气，故死。少阴负趺阳为顺，指趺阳脉胜于少阴，胃气尚存则生机未绝。此段以无脉、灸不温、微喘判死生，属死脉预后之论。", []], "20920": ["病机", "下利本属里证，脉应沉迟，今反浮数，是邪热内迫、阳气外浮之象；尺中自涩，涩主血行滞涩，热伤下焦血络，故知必清脓血。浮数为热，涩为血瘀，热与血结于肠道，腐化为脓血而下，此脉象揭示热利伤络、血腐成脓之病机。", ["浮", "数", "涩"]], "20921": ["预后", "下利脉沉弦，沉主里、弦主急，气机郁滞于下，故下重里急；脉大者邪气盛，故为未止；脉微弱数者，微弱为邪衰正复，数为阳气来复，故为欲自止。虽发热，因脉象由大转微弱数，示邪退正复，故断不死，此以脉象进退判断下利预后。", ["沉", "弦", "大", "微弱"]], "20922": ["病机", "下利脉沉而迟，沉主里、迟主寒，为里寒下利清谷之脉；面少赤、身微热乃阴寒内盛、虚阳上浮之戴阳证，下虚故也。郁冒汗出而解者，阳气蓄积奋起驱邪，汗出则阳气得通。脉沉迟与戴阳并见，揭示下焦虚寒、虚阳浮越之病机。", ["沉", "迟"]], "20923": ["预后", "下利脉反数而渴，数为热、渴为津伤，热盛伤津故渴。脉数而渴为阳气来复、邪热外达之象，故今自愈；若不瘥，则热邪深入下焦，灼伤血络，必清脓血。此以脉数口渴判断下利向愈或转为热利便脓血之预后转归。", ["数"]], "20924": ["预后", "下利后脉绝、手足厥，为阳气衰绝、不能达于四末之危候。晬时脉还、手足温者，阳气渐复，故生；脉不还者，阳不复返，故死。此段纯以脉之还与不还、手足温与不温判断阳气存亡，脉绝为死候，脉还为生机，揭示下利后阳脱之预后。", []], "20925": ["死脉", "伤寒下利日十余行，正气当虚，脉应微弱；今脉反实，实为邪气亢盛、正虚邪实之象。下利频作而脉实，是胃气已败、邪气独盛，正不胜邪，故主死。此以脉症相反判断危候，脉实非正气强，乃邪气实而胃气绝之死脉。", ["实"]], "20926": ["治法", "下利清谷为里寒盛、脾肾阳虚，不能腐熟水谷；里寒外热、汗出而厥，乃阴寒内盛、虚阳外越之格阳证。脉象虽未明言，然证属少阴寒化、阴阳格拒，故以通脉四逆汤破阴回阳、通达内外，此段主旨在于出方治法，非论脉。", []], "20927": ["兼症", "呕而脉弱，弱为正气不足、胃气虚弱；小便复利，为津液下夺；身有微热而见厥，是阳虚不能温煦四末，虚阳外浮。脉弱与厥并见，示阳气衰微、阴阳不相顺接，故为难治，主以四逆汤回阳救逆。此段以脉弱统摄呕、利、厥、热诸兼症。", ["弱"]], "20928": ["病机", "少阴病脉细沉数，细为阴血不足，沉主病在里，数为虚热内扰，三者合见示少阴里虚、阴阳俱损而虚热内生。原文明言「病在里」，里虚之证误汗则更伤阴液阳气，故「忌发其汗」，此脉所主为少阴里虚、禁汗之机。", ["细", "沉", "数"]], "20929": ["病机", "脉浮而紧为太阳伤寒表实，法当身疼以汗解；然「尺中脉迟」提示营血不足、血气微少，尺候营阴，迟为血少行缓。表证虽在而里营已虚，若径发其汗必更耗营血，故忌汗。此段以尺脉迟辨营虚禁汗之机。", ["浮", "紧", "迟"]], "20930": ["病机", "少阴病脉微，微为阳气衰微之象，原文直指「无阳故也」，即少阴阳气虚弱，鼓动无力故脉微。阳虚之体若发其汗，则阳气随汗外泄而愈虚，甚则亡阳，故「忌发其汗」。此脉所主为少阴阳虚、禁汗之病机。", ["微"]], "20931": ["病机", "太阳病发热恶寒而寒多热少，脉见微弱，微弱为阳气虚衰、鼓动无力之象，原文断为「无阳也」，即表证之下里阳已虚。阳虚者再发其汗，必致阳气更伤，故「忌复发其汗」。此脉主阳虚禁汗之机。", ["微", "弱"]], "20932": ["病机", "脉浮主病位在表，气血趋外抗邪，故原文谓「病在外」，邪在肌表当因势利导，宜发其汗以驱邪外出。此为凭脉定表里、以浮脉确立汗法之机，属治法范畴，示浮脉主表可汗。", ["浮"]], "20933": ["病机", "太阳病脉浮而数，浮为邪在表，数为邪盛正奋、阳气浮越之象，表邪郁于肌腠故脉浮数。邪在表而未入里，宜发其汗使邪从表解。此段以浮数脉定太阳表证可汗之机，属治法范畴。", ["浮", "数"]], "20934": ["病机", "阳明病脉浮虚，浮示病势偏表，虚为正气不足、脉道不充。阳明虽多里实，然此脉浮虚说明表邪未尽而里未成实，故宜发其汗从表解。此段凭浮虚脉辨阳明病兼表、可汗之机，属治法范畴。", ["浮", "虚"]], "20935": ["病机", "阳明病脉迟，迟主邪郁而气血运行不畅，然原文并见「汗出多而微恶寒」，汗多恶寒示表邪仍在、表为未解，脉迟非里寒而是表未罢之象，故宜发其汗以解表。此段以脉迟合症辨表未解可汗之机。", ["迟"]], "20936": ["治法", "太阴病本属里虚寒，脉当沉迟，今见脉浮，说明邪气有向外、向上之势，正气尚能趋表抗邪，病机为邪在表或里虚不甚而兼表。脉浮主表、主外，故宜因势利导发其汗，使邪从表解。此条以脉浮定治法，非言太阴虚寒之主脉，紧扣「脉浮」「宜发其汗」可知。", ["浮"]], "20937": ["主病", "太阳中风而见脉浮紧，浮为邪在表，紧为寒邪束表、营卫郁闭之象；卫闭则发热恶寒、身体疼痛、不汗出，阳郁化热则烦躁。脉浮紧与无汗烦躁相应，说明外寒闭表、内有郁热，故主大青龙汤证。紧扣「脉浮紧」「不汗出而烦躁」以明寒闭热郁之机。", ["浮", "紧"]], "20938": ["误治", "本太阳病恶寒发热，今自汗出、反不恶寒而发热，关上脉细而数。细为阴伤液亏，数为热，关候中焦，说明吐下太过损伤胃中津液，虚热内生，邪已离表入里。脉细数与自汗、不恶寒发热相应，故断为「吐之过也」，属误治伤津化热之候。", ["细", "数"]], "20939": ["病机", "少阴病饮食入则吐、心中温温欲吐、手足寒，脉弦运（当作弦迟），弦主饮、主痛，迟主寒，说明膈上有寒饮内停，阳气不足，饮邪上逆。脉弦与干呕、欲吐、手足寒相应，病机为寒饮阻膈、阳不布达，故忌吐，当以温药化饮。紧扣「脉弦运」「膈上有寒饮」立论。", ["弦"]], "20940": ["病机", "病如桂枝证而头项不强痛，寸口脉浮，胸中痞坚、上撞咽喉不得息。寸口脉浮说明病位偏上，胸中阳气被寒饮所阻，气机上逆，故痞坚撞咽。脉浮与胸中痞坚、不得息相应，揭示「此为有寒」、邪实在上，故宜因势吐之，使寒邪从上而出。", ["浮"]], "20941": ["病机", "胸中郁郁而痛、不能食、欲按、涎唾下利日十余行，而脉反迟、寸口微滑。迟为寒、为阳郁不布，滑主痰涎实邪；胸上诸实阻遏阳气，故脉反迟而非数。寸口微滑与涎唾、胸痛相应，说明实邪在上焦，故宜吐之，邪去则下利自止。紧扣「脉反迟」「寸口微滑」。", ["迟", "滑"]], "20942": ["病机", "手足逆冷而脉乍紧，紧主寒、主实，乍紧说明寒实之邪结聚胸中，阳气被阻不能外达四末，故手足逆冷；心下满而烦、饥不能食，皆邪结胸中之征。脉乍紧与胸中满烦相应，病位在上，故宜吐之，使结邪从上越。紧扣「脉乍紧」「邪结在胸中」。", ["紧"]], "20943": ["误治", "咽中闭塞本属邪实于上，忌用下法；下之则气机逆乱，上轻下重、水浆不下。诸外实亦忌下，误下则虚其里，阳气外浮发微热，甚则亡脉而厥。原文未出具体脉名，以「亡脉则厥」言误下伤阳、脉气欲绝之变，说明下法伤正、阳气衰败之病机。", []], "20944": ["误治", "脉数为热盛之象，热邪内炽，若误用下法，则热邪乘虚内陷，扰动心神而烦；下伤脾胃，升降失司，故利不止。原文以“脉数者忌下”立论，正因数脉主热，热证当清不当下，下之则引邪入里，变生烦、利不止之坏证，示人凭脉辨禁下之机。", ["数"]], "20945": ["误治", "脉浮大为病在表、邪势方张之象，法当汗解。医反下之，是诛伐无过，引表邪内陷，逆其病势，故称“大逆”。原文以浮大之脉明表证未罢，下之则伤正陷邪，变证蜂起，紧扣“医反下之，此为大逆”以戒误下。", ["浮", "大"]], "20946": ["预后", "结胸证本为邪结于里，然其脉浮大，说明表邪未尽、病势尚浅，未可遽下。若误下之，则里气更伤，邪结愈深，正气溃败，故“下之即死”。原文以浮大之脉断其禁下，突出误下致死的预后判断，示人结胸见浮大脉当先解表。", ["浮", "大"]], "20947": ["病机", "脉弦主饮、主痛，迟主寒，弦迟并见，为胸中寒饮内实、阳气被遏之象。饮阻胸膈，胃气上逆，故食入即吐、温温欲死而不能吐；阳不达于四末，故手足寒。原文断为“胸中实”，实为寒饮实邪，忌下者，下之则伤阳助饮，病必不除。", ["弦", "迟"]], "20948": ["误治", "脉虚为气血不足，复见厥者，阳虚不能温煦四末。腹濡而不结胸，说明里无实邪可下。虚脉厥逆而误下，则气血更伤，血失所养而亡血，故“下之亡血则死”。原文以脉虚复厥明其正虚禁下，突出误下致亡血之危。", ["虚"]], "20949": ["治法", "下利而三部脉皆浮，浮为邪在表、气机趋外；按其心下坚，说明里有实邪结聚。脉浮而心下坚，为表里同病、实邪内结之候，故宜下之以去其结。原文以浮脉与心下坚并见，辨为可下之实，示人凭脉参症以定下法。", ["浮"]], "20950": ["病机", "脉迟主寒、主滞，滑主实、主食积。迟而滑并见，为宿食内停、实邪壅滞之象，非虚寒之迟。实邪结于肠胃，故下利未欲止。原文断为“实也”，明其脉迟而滑主宿食内实，宜下之以去积滞，示人迟脉亦有实可下者。", ["迟", "滑"]], "20951": ["病机", "阳明与少阳合病而下利，脉数而滑，数为热、滑为实，主宿食内停、热实壅滞。原文以“脉不负者为顺”言其脉症相应，数滑之脉则明有宿食实邪，故宜下之。示人合病下利见数滑脉，当辨宿食内实而用下法。", ["数", "滑"]], "20952": ["主病", "寸口脉浮大，浮为阳浮于上，大为邪实，然按之反涩，是实中有滞；尺中亦微而涩，说明下焦气血不畅、宿食内停。宿食阻滞中焦，气机不利，故脉虽浮大而按之涩滞。原文以“按之反涩”“尺中亦微而涩”辨宿食，脉证合参，故知有宿食，宜下之。", ["浮", "大", "涩", "微"]], "20953": ["病机", "脉双弦而迟，弦主饮主痛，迟主寒；心下坚而脉大紧，大示邪实，紧主寒结。原文谓“阳中有阴”，即阳证中夹阴寒实邪，寒饮凝结心下，故脉双弦迟而心下坚，大紧为实邪内结。寒实内结，非温下不可，故宜下之，此脉象揭示寒实内结之病机。", ["弦", "迟", "大", "紧"]], "20954": ["主病", "病者烦热汗出即解，复如疟日晡所发，属阳明腑实。脉实者，邪热与燥屎内结，正气未虚，脉应之而实。实脉主邪气盛，阳明里实已成，故当下之，以泻热通腑。原文以“脉实”为可下之凭据，说明脉实反映阳明燥实内结之病机。", ["实"]], "20955": ["病机", "病发热头痛，脉当浮，今反沉，是阳证见阴脉，提示正气不足、邪陷于里。若不瘥而身体更疼痛，为里虚寒盛、营血凝滞。脉沉主里主虚寒，故当救其里，宜温药四逆汤。原文以“脉反沉”揭示表证而里阳已虚之病机，不可再汗，当温里回阳。", ["沉"]], "20956": ["病机", "下利而脉迟紧，迟主寒，紧主痛。下利见迟紧，为寒邪内盛、凝滞作痛，故原文谓“为痛未欲止”。寒性收引，气血凝滞，故脉迟紧而腹痛未止。此脉象说明里寒未解、疼痛持续之病机，治宜温之，散寒止痛。", ["迟", "紧"]], "20957": ["误治", "下利脉浮大，浮大本为有余之象，然下利见之，原文断为“此为虚”，乃因强下损伤正气，虚阳外浮所致。脉浮大而中空，是正虚邪陷、脾胃受损之征。强下伤中，故宜温之；若与水，水寒伤胃，必致哕逆。此段以脉浮大辨误下致虚之病机。", ["浮", "大"]], "20958": ["病机", "少阴病下利，脉微涩。微为阳气衰微，涩为阴血不足、气血滞涩。少阴下利而脉微涩，说明阳衰阴竭、气血两伤。呕者，为阴寒上逆、胃气不和。原文宜温之，以温阳散寒。脉微涩揭示少阴里虚寒盛、气血不足之病机，故不可攻下，当温补。", ["微", "涩"]], "20959": ["病机", "少阴病饮食入则吐，心中温温欲吐复不能吐，手足寒，脉弦迟。弦主饮主痛，迟主寒，弦迟并见，为寒饮内停、阳气不振。膈上有寒饮，干呕，是寒饮上逆。手足寒、脉弦迟，说明少阴阳虚、寒饮内结之病机，故宜温之，以温阳化饮。", ["弦", "迟"]], "20960": ["治法", "少阴病脉沉，沉为在里，主阳气衰微、阴寒内盛，脉气不能外达故沉。原文'脉沉者，宜急温之'，正因沉脉示少阴阳虚已深，须急温回阳，迟则寒凝阳脱。此沉非水饮结实之沉，乃虚寒在里之沉，与但欲寐、手足厥冷、下利等症相应。", ["沉"]], "20961": ["误治", "伤寒脉浮，邪在表，当以汗解。医反以火迫劫取汗，火气内逼，汗出过多则亡阳。阳亡而心神浮越，故'必惊狂，卧起不安'。浮脉本主表邪，此处火劫后阳浮于外，与惊狂不安相应，示误治伤阳、神不守舍之病机。", ["浮"]], "20962": ["病机", "伤寒脉不弦紧而弱，弱为阴血不足、津液亏虚，非表实寒凝之弦紧。津亏故'弱者必渴'；若再被火攻，火邪内迫，津伤更甚，热扰神明则'必谵语'。弱脉在此示正虚津少，与口渴、谵语相应，明火逆伤津之机。", ["弱"]], "20963": ["误治", "微数之脉，微为阳虚，数为热，然此热多属虚热。微数并见，示阴阳俱不足而虚阳浮动。原文'慎不可灸'，因灸火助热，火邪内攻则为烦逆。微数脉与烦逆相应，说明虚热之体误灸，火邪为患，非实热可灸之证。", ["微", "数"]], "20964": ["误治", "脉浮为邪在表，当以汗解。反灸之则表邪无从外出，火气与邪相合而盛，壅遏阳气，不能温养下体，故'病从腰以下必重而痹'。浮脉本主表，此处因火逆致邪郁，与腰以下重痹相应，明火逆伤阳、邪无出路之病机。", ["浮"]], "20965": ["误治", "脉浮热甚，为表实热盛之证，当以汗解。反灸之，是以实作虚治，火气内动，灼伤津液，上攻咽喉则'咽燥必唾血'。浮脉主表热，与咽燥唾血相应，示实热误灸、火邪伤络之病机，故原文断为'实以虚治'。", ["浮"]], "20966": ["治法", "少阴病吐利，手足逆冷，脉不足，示少阴阳气衰微、中焦虚寒，脉气无力鼓动。原文'灸其少阴七壮'，以灸法温少阴之阳，回厥止利。脉不足与吐利、手足逆相应，明虚寒在里、阳微欲脱之机，故取灸法温经复阳。", []], "20967": ["病机", "少阴病下利，脉微涩，微为阳虚，涩为津血不足。阳虚不能温运，故呕；津血亏少，故虽数更衣而反少。原文'宜温其上，灸之'，示病机为阳微津伤、下焦不固。微涩脉与呕、汗、更衣反少相应，明少阴阳虚津亏之候。", ["微", "涩"]], "20968": ["预后", "下利、手足厥、无脉，为阳气衰绝、脉道不通之危候。灸法本以回阳，若灸后手足不温反见微喘，是阳气不能回复，反有上越之势，故主死。原文以“灸不温反微喘者，死”点明阳亡气逆之预后。", []], "20969": ["预后", "伤寒六七日，脉微为阳气虚衰，手足厥为阳不达四末，烦躁为虚阳上扰。灸厥阴以回阳，若厥逆不还，则阳气已绝，故主死。原文“脉微”“厥不还者，死”紧扣阳衰欲脱之机。", ["微"]], "20970": ["治法", "脉促为阳气被遏、脉道急促之象，手足厥为阳郁不达。此非纯虚，乃阳郁可回之候，故宜灸之以通阳。原文“脉促，手足厥者，宜灸之”示阳郁厥逆可用灸法。", ["促"]], "20971": ["误治", "原文列举“熇熇之热”“渌渌之汗”“浑浑之脉”及“病与脉相逆”皆不可刺，强调脉症相逆时刺法易致误。浑浑之脉为脉象混乱不清，与病相逆则气血逆乱，故禁刺。此段主在告诫误刺之害。", []], "20972": ["病机", "伤寒腹满谵语，寸口脉浮而紧，浮为阳热外浮，紧为邪实内结。原文断为“肝乘脾，名曰纵”，肝木乘脾土，邪热内扰则谵语腹满。脉浮紧示邪实于外而乘于内，故宜刺期门以泻肝实。", ["浮", "紧"]], "20973": ["治法", "伤寒喉痹，刺手少阴穴，取“腕当小指后动脉”处，即神门穴附近动脉应手处。动脉为脉气搏动明显之处，用以定位。针入三分补之，示喉痹属少阴经气不利，以补法通经利咽。", ["动"]], "20974": ["病机", "下利脉浮大，原文断为“虚”，因强下之故，虚阳外浮。设脉浮革，革为虚大中空，主虚寒，因尔肠鸣，当温之。若与水则哕，示虚寒水气上逆。脉浮大、浮革皆虚象，故主温法。", ["浮", "大", "革"]], "20975": ["病机", "未持脉时，病人手叉自冒心，试令咳而不即咳，知两耳无所闻。原文归因于“重发其汗，虚故也”，过汗伤阳耗液，心阳虚则叉手冒心，肾精亏则耳聋。此段以症测机，示过汗致虚之病机。", []], "20976": ["病机", "原文点明“数为热，当消谷引食”，但反吐者，因医发汗致“阳气微，膈气虚”，此数乃“客热”，非真阳旺，故“不能消谷，胃中虚冷”。脉数与症状相悖，揭示数脉可主虚寒客热，胃中虚冷则失和降而吐，属误汗伤阳之病机。", ["数"]], "20977": ["预后", "发汗后重发汗致亡阳谵语，若“脉反和者，不死”，说明脉气和缓、阴阳未竭，预后尚可；若服桂枝汤后汗出、大烦渴不解而“脉洪大”，则邪从热化，阳明热盛津伤，故与白虎汤清之。本段以脉判预后并辨转归。", ["洪", "大"]], "20978": ["治法", "发汗后身体疼痛，脉不浮而“沉迟”，说明表邪已去而营气不足、筋脉失养，沉主里、迟主虚寒，非表证未解。故不用麻黄再汗，而以桂枝加芍药生姜人参汤益营气、通阳痹，属汗后虚痛之治法。", ["沉", "迟"]], "20979": ["兼症", "发汗后“脉浮而数，复烦”，浮为邪仍在表，数为热郁不宜，汗后津伤而水热互结，故烦。此非单纯表证，亦非纯里热，属汗后水气不化、表里兼夹之烦，故以五苓散化气利水，脉症合参以定兼症。", ["浮", "数"]], "20980": ["误治", "伤寒脉浮、自汗、小便数、微恶寒、脚挛急，本属阴阳两虚兼表，反与桂枝攻表，致“厥，咽干，烦躁吐逆”，是误汗伤阳、阴液亦损。先以甘草干姜汤复阳，再以芍药甘草汤伸脚，示脉浮不可径汗，须辨虚而误治之变。", ["浮"]], "20981": ["病机", "吐下发汗后“心下逆满，气上撞胸，起即头眩，其脉沉紧”，沉主里、紧主寒饮，说明误治伤脾，水饮内停，逆而上冲。发汗即动经、身为振摇，是阳虚饮动之象，故以茯苓桂枝白术甘草汤温阳化饮，脉沉紧为水气内动之据。", ["沉", "紧"]], "20982": ["病机", "下后发汗，必振寒，“其脉微细”，原文自释“内外俱虚故也”。微为阳虚，细为阴血不足，汗下两伤，表里气血俱虚，故见振寒。脉微细正是内外俱虚之征，非邪实可攻，提示虚证禁再汗下。", ["微", "细"]], "20983": ["病机", "下后复发汗，昼日烦躁不眠、夜而安静，无表证、不呕不渴，“其脉沉微，身无大热”，沉主里、微主阳虚，是汗下伤阳、虚阳外扰而里寒独存。昼烦夜静为阳虚阴盛之象，故属附子干姜汤温复其阳，脉沉微为辨证关键。", ["沉", "微"]], "20984": ["病机", "脉浮数为表邪未解，本当汗出而愈；误下后里气受损，尺中脉微示下焦里虚，故见身体重、心悸。此时不可再发汗，须待表里之气自和、津液充盈，方能自汗而解。脉微是关键，说明误下已伤里阳，病机由表实转为表里俱虚。", ["浮", "数", "微"]], "20985": ["预后", "伤寒吐下后潮热、谵语、循衣妄掇、微喘直视，为邪热内结、阴液耗伤之危候。脉弦者，阴气未绝、胃气尚存，故生；脉涩者，营血枯竭、脉道不利，故死。以弦涩对举判预后，紧扣原文“脉弦者生，涩者死”，示阴液存亡为转归关键。", ["弦", "涩"]], "20986": ["病机", "脉微涩为阳气衰微、津血不足之象。本霍乱吐利后转属伤寒，邪入阴经当利；素呕下利者，中阳已败，故不治。若欲大便而反失气不利，是转属阳明、燥屎内坚，经气行尽十二日可愈。脉微涩点明正气已虚，与阳明结实形成虚实对照。", ["微", "涩"]], "20987": ["治法", "下利后脉微而复利，恶寒，为阳气衰微、阴寒内盛，利止则津血亦亡，故主四逆加人参汤回阳救逆、益气生津。原文以“脉微”标出阳衰本质，又言“利止必亡血”，说明利止非愈，而是阴血耗竭之兆，故用四逆加人参汤温阳固脱。", ["微"]], "20988": ["病机", "吐利汗出、发热恶寒、四肢拘急、手足厥，为阳衰阴盛、内外俱寒之候。脉微欲绝，示阳气衰微欲脱，故主四逆汤回阳救逆。原文“里寒外热”点明阴寒内盛、虚阳外浮之病机，脉微欲绝正是阳气将绝之征，与吐利汗出、下利清谷相应。", ["微"]], "20989": ["治法", "吐已下断而汗出厥逆、四肢不解，脉微欲绝，为吐利后阳亡液竭、脉道将绝之危候。通脉四逆加猪胆汤于回阳救逆中佐苦寒反佐，防虚阳格拒。脉微欲绝紧扣阳气衰微、阴液枯竭之病机，与汗出而厥、四肢不解相应，示病情较四逆汤证更重。", ["微"]], "20990": ["治法", "本条为通脉四逆汤加猪胆汁之服法说明，言服后“其脉即出”，说明方证针对脉微欲绝之阳衰证，药后阳气来复则脉出。无猪胆以羊胆代之，示反佐之品可权变。原文未直接描述脉象，故脉象要素为空，主旨属治法与服药后脉复之观察。", []], "20991": ["病机", "吐利发汗后脉平，示邪去正复、脉象趋于和平；而小烦者，乃新虚之体不胜谷气，脾胃尚弱、运化不及所致。脉平说明大邪已解，病机转为脾胃新虚、谷气不消，故见微烦，非复感外邪，亦非危候，属病后调摄之机。", ["平"]], "20992": ["治法", "伤寒瘥后更发热，示余邪未尽。脉浮为邪仍在表，故以汗解，因势利导从表而出；脉沉实（或作紧）为邪结于里、腑气不通，故以下解之。一浮一沉，辨表里之异，定汗下之法，紧扣原文“脉浮者，以汗解之，脉沉实者，以下解之”，非泛论脉象。", ["浮", "沉实"]], "20993": ["病机", "此段分两层：大病后喜唾久久不了，是胸上有寒、津液不摄，故当温之，宜理中丸；又“脉已解”而日暮微烦，乃病新瘥脾胃气尚弱，强与谷而不能消谷，食积生烦。前者责寒，后者责虚与食，皆紧扣“脾胃气尚弱，不能消谷”，故损谷即愈。", []], "20994": ["小儿", "此段述胎儿逐月成形及生后六十日至三百六十日动作发育之期，如“三月有血脉”“百五十日任脉成”“三百六十日膝膑成，能行”。若不能依期，则“必有不平之处”，示发育迟速可察脏腑筋骨之盈亏，属小儿生长候察之法，非论脉。", []], "20995": ["小儿", "原文言新生儿“不可令衣过厚热”，过厚则郁热伤皮肤肌肉，致“血脉发杂疮及黄”。此为小儿调护之戒，指出衣着过暖可致血脉郁热、外发疮疡与黄疸，紧扣“伤皮肤肌肉，血脉发杂疮及黄”，属小儿护养病机，非脉诊。", []], "20996": ["小儿", "小儿身热、汗出而脉乱，原文断为“蒸之候也”，即变蒸之象。变蒸时气血骤变，脉气随之扰乱不宁，故脉乱非凶候，与身热汗出并见，为蒸热外达之征。紧扣“身热、脉乱、汗出”三症合参，方识其为蒸，不可误作他病。", ["乱"]], "20997": ["小儿", "原文谓小儿“微惊者，以长血脉”，示轻微惊惕可助血脉生长，属生理之常；“但不欲大惊”，大惊则伤神，故“大惊乃灸惊脉”。此段辨惊之微甚，微惊可长血脉，大惊须灸惊脉以安之，紧扣原文惊与血脉、灸法之关系。", []], "20998": ["小儿", "小儿有癖积，脉大则食积化热、痰食上扰，必发食痫，故“下之便愈”。原文又察掌中与三指脉，脉在掌中尚可早治，至指则病增，示癖积传变由浅入深。脉大主积热壅盛，早下则脉不复起，紧扣“脉大必发痫”“此脉终不起也”。", ["大"]], "20999": ["病机", "小儿腹中有疾则身寒热，寒热相争则血脉动，血脉动则心不定，心不定则易惊，惊则痫发速。原文以“血脉动”为枢，串联腹疾、寒热、心惊、发痫，示痫由积疾化热、扰动血脉心神而作，紧扣“血脉动则心不定，心不定则易惊”。", ["动"]], "21000": ["主病", "原文以“血脉盛实”为小儿出腹核心病机，脉盛实即血气壅盛、邪热内实之象。盛实之脉应寒热温壮、四肢惊掣、发热大吐、乳食不消、壮热及变蒸不解，甚则中客忤鬼气、惊痫。龙胆汤苦寒泻实，正对血脉盛实之壅热，故列小儿第一方。", ["盛", "实"]], "21001": ["病机", "小儿中客忤见“脉弦急”，弦主气机郁逆，急主邪扰挛急。原文吐下青黄汁、腹中痛、反倒偃侧似痫而目不上插，正是客忤之气扰乱中焦、肝风内动之候。弦急示邪正交争急迫，失时不治则久难治，故当早治。", ["弦", "急"]], "21002": ["治法", "“第一大脉”指舌下两侧粗大之络脉，非脉诊之脉。以刀锋决之出血，是刺络泻血之法，避舌下中央脉以防血出不止杀人。此段言治法操作与禁忌，大脉在此为可刺之络，示血壅当泻，非主病之脉象。", ["大"]], "21003": ["其他", "此段无脉象，主论施泻后当导引补虚，否则“血脉髓脑日损”。列举吐逆、汗出当风、饱食大呼、疾走举重、思虑太深等耗损之由，皆伤血脉、损年寿。强调补泻相济、和理养生，属养生禁忌与补泻之理，非脉诊病机。", []], "21004": ["其他", "此段无脉象，列五逆六不祥及饮食起居禁忌。其中“大饱血脉闭”“大劳行房露卧发癫病”涉及血脉壅闭与劳伤，但全段主旨为日常避忌、求福远祸，属养生杂忌，非以脉象论病机，故归其他。", []], "21005": ["其他", "此段无脉象，论交会择日：大月十七、小月十六为毁败日，犯之“伤血脉”；二、三、五、九、二十日为生日，交会令人无疾。以日期吉凶言伤血脉与无疾，属房中择日禁忌，非脉象主病，故归其他。", []], "21006": ["其他", "此段无脉象，详述地黄选种、耕地、作畦、锄壅、掘取、洗净、蒸晒、绞汁再蒸等炮制工序。全段为药材种植与修治技术，不涉脉诊病机，故归其他。", []], "21007": ["其他", "此段无脉象，论牛乳性平，能“补血脉，益心，长肌肉”，令人康强润泽、志气不衰，劝人子常供亲食。以牛乳补血脉益心为说，属食疗补养，非脉象主病，故归其他。", []], "21008": ["治法", "本段为石英类方药的煎服法，未言脉象。文中强调'须令药力遍身，百脉中行'，说明服药后当行走以助药力流通百脉，属治法范畴。'若大冷者，春秋各四十九日'提示此方针对沉寒痼冷之体，需久服取效，非凭脉断病，故脉象要素为空。", []], "21009": ["其他", "本段为灵飞散方组成与服法，未涉脉象。文中'三日力倍，五日血脉充盛'描述药后血脉充盈之效，'七十日头发尽落，故齿皆去'为服药反应，属方药杂录，非脉诊病机，故归其他，脉象要素为空。", []], "21010": ["其他", "本段详述云母炮制及药性主治，未言脉象。'主治死肌，中风寒热，如在船车上，除邪气，安五脏'为药物功效记载，'五劳七伤，虚损少气'言其补益所主，全段属本草炮制内容，无脉象可辨，故脉象要素为空。", []], "21011": ["其他", "本段述服水七日节次及身体反应，未及脉象。'十七日中髓脑众脉皮肤汗类一切悉愈'言服水后众脉通利、诸病除愈，属服食养生记录，非据脉断证，故归其他，脉象要素为空。", []], "21012": ["病机", "本段论人夭殁由不自爱惜、竭情尽意，致'血气将亡，经络便壅，皮里空疏'，正气日衰而邪气日盛。原文仅标'脉则动'，动脉主阴阳相搏、气血失和，正合血气将亡而经络壅滞之机。五劳既用，心肾先损，腑脏俱病，脉动正是正虚邪盛、气血躁动之象。", ["动"]], "21013": ["病机", "本段论寒食散发动之脉候。'热多则弦快，有癖则洪实，急痛则断绝'，洪实主癖积内结，沉数主热郁难发，浮大则药力易发。脉无常度，或似死脉而非死候，关键在'动从节度'。脉沉数者难发当数下之，说明脉象反映药毒内蕴、热结深浅之病机。", ["洪", "实", "沉", "数"]], "21014": ["主病", "本段言肺痈见'脑中满而振寒，脉数，咽干不渴，时时出浊唾腥臭，久久吐脓如粳米粥'。脉数主热，热毒壅肺、腐肉成脓，故咳唾腥臭浊脓；振寒为痈脓将成、邪正相争之象。脉数与咽干不渴并见，说明热在肺而不在胃，主肺痈已成之病。", ["数"]], "21015": ["主病", "本段言'手足厥寒，脉为之细绝，其人有寒'。脉细绝主阳气衰微、血脉不充，寒邪内盛则气血凝滞，不能达于四末，故手足厥寒。细绝之脉与有寒之症相应，属寒厥重证，故用当归茱萸四逆汤温经回阳，脉象直接主阳虚寒盛之病机。", ["细"]], "21016": ["主病", "脉微欲绝为阳气衰微、阴寒内盛之象。下痢清谷、手足厥逆、身反恶寒，皆脾肾阳衰、不能温煦所致；内寒逼阳外浮，故面赤、内寒外热。脉微欲绝正是心肾阳微、鼓动无力之征，主通脉四逆汤证。", ["微"]], "21017": ["治法", "此段述通脉四逆汤服后“脉即出也”，以脉出为阳气来复之验。面赤加葱白通阳，腹痛加芍药和营，呕加生姜，咽痛加桔梗，痢止脉不出加人参益气复脉，皆随证加减以救阳复脉，属治法范畴。", []], "21018": ["其他", "“复脉汤”为方名，未出脉象。此段仅列方名，无脉症可析，然方名“复脉”提示其主治脉结代、脉不出等脉气不复之证，属其他类。", []], "21019": ["预后", "脉结为气血虚衰、脉道不利之象。虚劳不足、汗出而闷、心悸，皆气血亏虚、心失所养所致；行动如常而脉结，说明虚损尚能勉强维持，然不出百日或二十一日死，示脉结在此为危候，主预后不良。", ["结"]], "21020": ["治法", "此段述复脉汤服法，以“脉复为度”，若脉未复则隔日再服，力弱者三日一剂，乃至五剂十剂。杨素失脉，七日服五剂而复，说明治疗以脉复为效验，属治法范畴，强调守方续服以复脉气。", []], "21021": ["主病", "此段主八十三种风著人头面，面肿痒、眉发陨落、手脚拘急、梦与鬼神交通、心烦恐怖、百脉自惊、羸瘦，皆风邪入中、血脉受病之候。未出脉象，然“百脉自惊”提示脉气受扰，主风邪为病。", []], "21022": ["主病", "此段主积年八风五注，举身亸曳、不得转侧、口噤失音、四肢脊筋皆急、肉痹血脉曲挛掣痱、肿痛流走无常处，皆风邪深入血脉筋骨、气血痹阻所致。未出脉象，主风邪痼疾、血脉挛急之病。", []], "21023": ["主病", "此段主除风气通血脉、益精气，治筋急膝不得屈伸、恶风寒冷、通身流肿生疮、背痛不能立、面目萎黄等，皆风气痹阻、血脉不通、精气亏虚之候。未出脉象，主风邪血脉痹阻及虚损之病。", []], "21024": ["治法", "本段为秦艽等十五味药的主治罗列，未涉脉象。诸药如秦艽主风不仁、防风去风疼除湿痹、附子主风湿坚肌骨、乌头逐风上气除邪，皆围绕风邪湿痹、留饮、脏虚而设，体现以祛风除湿、温阳益气为法，非凭脉辨证之文，故脉象要素为空。", []], "21025": ["主病", "原文述“三十年恶风湿痹，发秃落，瘾疹生疮，气脉不通，抓搔不觉痛痒”，指出久病风湿痹阻、气脉不通之候。抓搔不觉痛痒，是气血不能荣养肌肤、脉络痹塞之征，与恶风湿痹日久、营卫不通的病机相应，全段未出脉名，故脉象要素为空。", []], "21026": ["兼症", "本段详列丸药服法及随症加减：吐多痢少取枳实，吐少痢多加干姜，吐痢干呕用半夏，体痛煮枣，转筋以韭汁洗腹肾，体冷微汗腹中寒用附子。末言“吐痢悉止，脉不出体犹冷者，可服诸汤补之”，脉不出示阳气未复，故以温补收功，全段未出具体脉名。", []], "21027": ["主病", "原文论胃疟“令人且病寒，善饥而不能食，支满腹大”，善饥不能食、腹大支满，是胃热内蕴、脾运受困之象，故刺足阳明太阴横脉出血以泻其实。此段言胃疟主病与刺法，未及脉象，脉象要素为空。", []], "21028": ["病机", "原文谓“主内实热盛发黄，黄如金色，脉浮大滑实紧数者”，浮大滑实紧数并见，为邪热内实、湿热熏蒸之象。热盛于内故脉实而数，湿毒壅滞故紧，气血沸涌故浮大而滑，黄如金色正由酒客胃中热、湿毒内蕴所致，脉症相合，主内实热盛发黄。", ["浮", "大", "滑", "实"]], "21029": ["病机", "原文论酒疸“其脉浮者，先吐之；沉弦者，先下之”，浮为病在上焦宜吐，沉弦为病在下宜下。又言酒疸下之久久为黑疸，目青面黑、大便正黑，“其脉浮弱”，浮弱示正气已伤、邪陷血分，虽黑而微黄，故知由酒疸误下转变而来，脉象反映病位与正气盛衰。", ["浮", "沉", "弦", "弱"]], "21030": ["治法", "本段专列灸黄二十穴，如脾俞、手少阴、胃管、耳门、巨阙、上管等，随年壮或百壮施灸，并兼用针刺上腭、舌下、颊里诸处。全段为黄疸外治取穴之法，未言脉象，故脉象要素为空，主旨属治法。", []], "21031": ["预后", "原文分吐血为内衄、肺疽、伤胃三种，伤胃者因饮食大饱、胃中冷不能消化，强呕致胃口伤裂，血鲜赤、腹中绞痛、自汗出，“其脉紧而数者，为难治也”。紧为痛为寒，数为热为急，紧数并见示邪正交争、胃络损伤而热迫，故判难治；若吐后奄奄然不闷则自愈，烦躁闷乱者误与黄土汤等反增闷乱。", ["紧", "数"]], "21032": ["其他", "本段为伏龙肝等药组方，未识别脉名，亦无论脉之语。方中伏龙肝、干地黄、阿胶、黄芩、干姜、牛膝、槲脉、甘草相配，寒温并用，补涩兼施，当属止血补虚、调中摄血之剂。原文无脉象描述，故不能据脉论病机，仅列方药组成，属其他类。", []], "21033": ["病机", "原文明言「血室空虚，客阳通之，令脉紧数」，紧主寒积、数主热蒸，久积痰冷而胸胁痞满、不受食饮、浑浑欲吐，是寒痰内积；血室空虚则客阳乘之，重热水蒸，故汗漏如珠、四肢烦痛、唇口干燥、渴升水浆。脉紧数并见，正示寒积于中而虚阳外扰之病机。", ["紧", "数"]], "21034": ["主病", "本段未识别脉名，主述伤中里急、两胁挛痛、久咳、四肢寒热、小便赤黄、血痹不仁、梦寤失精、唇口干燥、短气等症。原文「长风百脉开张」言风邪乘虚入于百脉，致血痹不仁、失精短气，属虚损兼风之候，非以脉象立论，故列主病。", []], "21035": ["其他", "本段仅言「养神补益，长肌肉，能食，安利五脏，通血脉调气」，为补益调养之方，未识别脉名，亦无脉象描述。其主旨不在论脉辨证，而在述方药功用，故归其他类，不能据脉推病机。", []], "21036": ["主病", "本段述露蜂房、乱发、蛇皮烧灰酒服，主诸恶疽、附骨痈、历节肿出、疔肿恶脉诸毒，又治下乳石热毒壅闷、狐刺疮、赤白痢、尿失禁。原文「恶脉」指恶疮毒脉，非诊脉之脉；全段无论脉之语，主旨为方药主治诸毒恶疮，故列主病。", []], "21037": ["主病", "本段极简，言梅根疗风痹、出土者杀人，梅实利筋脉去痹。原文「筋脉」指筋与脉，非脉象诊断；未识别脉名，无浮沉迟数等脉象要素。主旨为梅根、梅实主治风痹之病，故归主病，不能据以论脉机。", []], "21038": ["其他", "本段详述乌头与粟米粉同罨制曲、候汁衣紫色、刮截看「白黄脉断即熟」等炮制工序。文中「脉断」指乌头内部纹理断处，非诊脉之脉；未识别脉名，无脉象可言。主旨为药物炮制火候判断，故归其他类。", []], "21039": ["主病", "本段述十三味药捣丸，治绕脐相逐上下不定、按之挑手、心中愠愠如有虫、病走皮中，及蜂蛇所中、中恶、飞尸、梦寤惊恐、卒中鬼魅狂言妄语等。原文「一丸涂其脉」指涂于脉络之处，非脉象诊断；未识别脉名，主旨为丸药主治诸恶毒邪病，故列主病。", []], "21040": ["主病", "原文以“陷脉散”主治二三十年瘿瘤、骨瘤、石瘤等，久则“骨消肉尽”“惊惕寐卧不安”“体中掣缩”，脉散正合瘤病日久、气血耗散、正气不敛之机。散脉主气散不收，故见瘤溃漏、形体消削、神惊不安，属久病正虚、邪结不散之候。", ["散"]], "21041": ["治法", "本段详述服药后虫从小便出，按虫色黄赤白青黑分述，属攻虫外出的治法与效验观察。原文未及脉象，故脉象要素为空。其重点在“空腹服”“清酒和药”“小便似淋即更服药”，说明以药力逐虫下行，非凭脉辨证，故归治法。", []], "21042": ["其他", "本段论“患在五脏骨髓者，非汤药不愈；患在皮肤肉脉中者，针刺可瘥”，比较汤药与针灸的适用层次及养性延年之效，强调“汤药益人精神”“针灸虽得目下解急，于人神浊”。原文无脉象描述，主旨为治法取舍与养生观点，故归其他。", []], "21043": ["误治", "原文用炒药蹋袋取汗法，末言“三部脉微弱者勿用之”。三部脉微弱，示气血不足、正气虚馁，发汗更伤营卫，故禁此法。此段以脉微弱为禁忌指征，说明误汗可致虚脱闷乱，属误治警示，脉微弱正为禁汗之据。", ["微", "弱"]], "21044": ["治法", "本段述白石英等药蒸捣、水飞、猪脂炼和、和酒服法，属制药与服食方法。原文未提脉象，故脉象要素为空。其“赤脉尽则休”指猪脂浸水去赤脉，非诊脉之脉，主旨为治法操作，故归治法。", []], "21045": ["治法", "本段述石英、石脂等五味煎服法，强调“日日依前秤取”“满四十日止”“忌酒肉”，并令“药力遍身，百脉中行”。原文无脉象，主旨为服药方法及药力运行百脉，属治法范畴，故归治法。", []], "21046": ["病机", "原文言“食少、药气行于肌肤、五脏失守、百脉摇动、与正气竞”，脉摇动即动脉之象，主阴阳相搏、正气与药气交争。因食少则脏失所养，百脉动摇不安，故见头掉不自支任。以热酒和脉、冷食定脏，使关机调柔，说明动摇由正邪相竞、脏气失守所致。", ["动"]], "21047": ["病机", "本段论“心痛如刺”由“应食而不食、应洗而不洗、寒热相击、气结不通，聚在心中”所致，原文未及脉象，故脉象要素为空。其病机为寒热相击、气结血滞，故痛如刺；以热酒行气血、冷水淹布外敷，使“起沉滞于血脉之中”，属病机分析。", []], "21048": ["病机", "原文述遍体肿痛、不能转徙，归因于“久停久息、久不饮酒，药气沉在皮肤之内，血脉不通”。此段无脉象，主旨是血脉不通致肿痛，属病机论述；以热酒、冷水洗、强行活动通调血脉为治，故列病机。", []], "21049": ["病机", "原文谓“肌肉坚如木石，不可屈伸”，由“食热卧温作癖，久而不下，五脏隔闭，血脉不通”所致。无脉象可录，核心在宿癖内结、五脏气隔、血脉不通而成坚肿，故归病机，下法冷食冷饮以除积通闭。", []], "21050": ["病机", "此段论营卫气血生成流行，“血和则孙脉先满，乃注于络脉；络脉皆盈，乃注于经脉”，强调“经脉流行不止，与天同度”。无具体脉象，主旨为血气平与不平及痈疽所生之由，属病机讨论，故列病机。", []], "21051": ["预后", "原文述夭疽“发于颈”“大而赤黑”，不急治则“热气下入渊腋，前伤任脉，内熏肝肺，则十余日而死”。无脉象，重点在疽毒内陷、伤任脉熏肝肺的死亡期限，属预后判断，故列预后。", []], "21052": ["病机", "原文辨痈疽：“荣气稽留于经脉之中，则血泣而不行”，卫气归之壅遏不通故热，热胜肉腐为脓；疽则“热气纯盛，下陷肌肤筋髓骨肉，内连五脏，血气竭尽”。无脉象，全段阐痈疽成脓与内陷之机理，故归病机。", []], "21053": ["治法", "原文讲痈坏后去恶肉、敷生肉膏散及摩四边，并嘱“绝房室，慎风冷，勿自劳动，须筋脉平复乃可任意”。脉象写作“脉平复”，指筋脉恢复平和，非病脉；主旨为痈后调护治法，故列治法，脉取“平”。", ["平"]], "21054": ["预后", "原文述脉疽发环项，始痛身热、不欲动、不能食，“此有所大畏，恐怖而不精上气”，发引耳不可肿；并断“二十日可刺，不刺八十日死”。无脉象，重点在疽发部位、症候与刺治时限及死期，属预后，故列预后。", []], "21055": ["预后", "原文述陈干疽发两臂，三四日痛不可动，五十日身热而赤，六十日可刺；“如刺脉无血，三四日死”。无脉象，主旨为疽之病程与刺后无血之死期判断，属预后，故列预后。", []], "21056": ["预后", "原文未出脉名，仅言“手心主脉有肿”，以经脉所过与痈肿部位相配推断预后。手心主（心包）脉循胸出胁下腋，其肿见于股胫，属经气壅遏、毒邪旁窜，故断“六日死”；若发脓血，则毒有出路，延至“六十日而死”。全段以脉部与痈位相应定死期，属预后判断。", []], "21057": ["预后", "本条未识脉名，以“胁少阳脉有肿”立论。少阳之脉循胁，今胁部脉见肿，而痈发在颈，是经气壅滞、毒邪上攻，经脏不相顺接，故“八日死”；若脓血外发，毒势得泄，则“十日死”。原文以脉部与痈位错互言死期，属预后推断。", []], "21058": ["预后", "原文未出脉名，言“腰太阳脉有肿交脉来于阳明”，是太阳与阳明经气交并壅遏，毒聚于颈而成痈。经气交阻、毒无出路，故“十日而死”；若发脓血，毒泄而正亦伤，故“七日死”。全段以脉部交会与痈位定死期，属预后判断。", []], "21059": ["预后", "本条未识脉名，谓“尻太阳脉有肿”，而痈在足心，属太阳经气下壅、毒邪旁窜足少阴之分。经气阻绝、毒无外泄，故“八日死”；若发脓血，毒有出路而正气渐耗，故“八十日死”。原文以脉部与痈位相应言死期，属预后。", []], "21060": ["预后", "原文未出脉名，言“头阳明脉有肿”，痈反在尻，是阳明经气壅遏、毒邪下注。经气不通、毒聚无路，故“六日死”；若发脓血，毒泄而正伤，故“六十日死”。全段以脉部与痈位错互定死期，属预后判断，未涉具体脉象。", []], "21061": ["预后", "本条未识脉名，谓“股太阳脉有肿”，痈在足太阳，是太阳经气壅滞、毒聚于足。经气阻遏、毒无出路，故“七十日死”；若发脓血，毒泄而正亦损，故“百日死”。原文以脉部与痈位相应言死期，属预后推断。", []], "21062": ["预后", "原文未出脉名，言“肩太阳太阴脉有肿”，痈在胫，是太阳、太阴经气交阻，毒邪下注。二经壅遏、毒无外泄，故“八日死”；若发脓血，毒有出路而正渐耗，故“四百日死”。全段以脉部与痈位定死期，属预后判断。", []], "21063": ["预后", "本条未识脉名，谓“足少阳脉有肿”，痈在胁，是少阳经气壅遏、毒聚于胁。经气阻绝、毒无出路，故“八日死”；若发脓血，毒泄而正伤，故“六百日死”。原文以脉部与痈位相应言死期，属预后推断，未及具体脉象。", []], "21064": ["预后", "原文述手阳明脉有肿痈在腋渊，未及脉象，而断言“一岁死，发脓血二岁死”，是据痈发部位与传变推测死期。腋渊为手阳明所过，痈毒聚此，易内陷伤及脏腑，故预后凶险。此条重在判断疾病转归，非论脉诊，故脉象要素为空。", []], "21065": ["治法", "原文虽列“脉来细而沉、脉来大渐小者”，但全段主旨在于痈疽治法，如“五香连翘汤主之”“先刺去热”“针去血”“大针入五分”等。脉细沉主毒邪内伏，脉大渐小示正气渐衰，故治疗强调早期刺血、内服外敷，并据脓成与否施针，体现辨脉以施治。", ["细", "沉", "大", "小"]], "21066": ["主病", "原文“主寒热瘰疬，在颈脉如杏李方”，指颈部瘰疬之病，症见寒热，局部肿核如杏李大。此条未直接描述脉象，而“脉”字在此指病变部位（颈部脉络），非脉诊之脉。病机为痰毒结聚颈项，与寒热并见，属外科瘰疬主病。", []], "21067": ["其他", "此段仅为篇题“卷第二十五·色脉”，无具体脉象与病机论述，故脉象要素为空。其内容提示该卷讨论色诊与脉诊，但本条本身不构成独立病机分析，仅作篇章标识，归为其他类。", []], "21068": ["平脉", "原文强调“上医察色，次医听声，下医脉候”，虽善脉候而不知察色，终未尽妙。此段论色脉合参之要，非专言某脉主病，而重在医者诊法层次。脉候居下，非贬脉诊，乃示色诊先于脉诊，以决生死、定狐疑，属诊法总则。", []], "21069": ["预后", "原文论病人本色白，欲如璧玉之泽、有光润者佳，不欲白如垩；若面白黑则“无复生理”。此以面色光泽判断胃气荣华之存亡，白如垩为血气尽、荣华已去，故预后不良。虽未言脉，但色脉相应，面白黑无泽示脏气竭绝，故属死候。", []], "21070": ["病机", "原文述察色知病：白色起于两眉间薄泽者病在皮肤，唇色青黄赤黑者病在肉，荣气需然者病在血脉，目色青黄赤白黑者病在筋，耳焦枯受尘垢者病在骨。此以五色显现部位推断邪客深浅，由皮肉血脉筋骨层层深入，示病位病机，非论脉象。", []], "21071": ["治法", "原文论皮部、肉柱、气血之输、筋结、骨属的取治部位，强调“候病间甚”：间者浅之少之，甚者深之多之，随变而调之，故曰上工。此段主针刺深浅多少须据病之轻重，并分上工、中工、下工及十全之数，属治法范畴，未涉具体脉象。", []], "21072": ["病机", "本段论脏腑虚实与荣卫气血运行，提出“脏实则腑虚，腑实则脏虚”，以呼吸出入分阴阳脏腑荣卫，并述一昼夜万三千五百息、脉行五十周。虽未出具体脉名，但以“脉行五十周于其身”说明脉气随荣卫周流全身，是平人气血运行常度，为后文凭脉辨脏腑虚实、以针泻调之立论基础。", []], "21073": ["病机", "本段列“六虚”，以“脉虚则惊”点明脉虚与惊的关系。脉为血之府，心虚则脉道不充而虚，神失所养故惊。原文以皮虚热、肉虚重、骨虚痛、肠虚泄溏、髓虚惰并列，说明六虚各随所主组织而见不同症候，脉虚主心气不足、神志不宁之惊。", ["虚"]], "21074": ["其他", "本段仅为“诊脉大意第二”篇题，无具体脉象与病机论述，属脉学著作的篇目名称，标示该篇总论诊脉大要。因原文未涉及脉象要素与病症，故脉象要素为空，主旨归入其他，不作病机推断。", []], "21075": ["平脉", "本段论独取寸口之理，因寸口为五脏六腑气血终始，荣卫五十度复会手太阴。又分尺寸部位：“寸口关上为阳，阳脉常浮而速，尺中为阴，阴脉常沉而迟”，说明阳部脉常浮数、阴部脉常沉迟，是平人尺寸阴阳之常脉，非病脉，故归平脉。", ["浮", "数", "沉", "迟"]], "21076": ["预后", "本段论诊脉须“称其形性”，以人大小长短、性气缓急与脉相应为吉。原文举“人大而脉细，人细而脉大，人乐而脉实，人苦而脉虚，性急而脉缓，性缓而脉躁”等为逆，逆则难治；反则为顺，易治。脉与形性相乘即逆，故主预后不良，属凭脉判断难治易治之论。", ["细", "大", "实", "虚"]], "21077": ["妇人", "本段专论妇人、小儿常脉。妇人“脉常欲濡，弱于丈夫”，因妇人以血为本，脉道柔和濡弱为常；小儿四五岁“脉自疾快，呼吸八至”，因小儿气血未充、生机旺盛，脉数疾为常。二者皆属生理常脉，非病象，故主旨归妇人，兼及小儿平脉特点。", ["濡", "疾"]], "21078": ["平脉", "本段述春、夏常脉。春脉“细弦而长”，应春气生发、肝木条达，故脉弦长；夏脉“洪浮而长，来疾而去迟”，应夏气盛长、心火充旺，故脉洪浮而长。此皆四时平脉，随季节阴阳升降而变，原文以脉象形态言时令之常，非主病之脉。", ["细", "弦", "长", "洪"]], "21079": ["平脉", "本段述秋、冬、季夏常脉。秋脉“微浮而散”，应秋气收敛、肺金清肃，故浮散；冬脉“沉滑而实”，应冬气闭藏、肾水沉实，故沉滑而实；季夏脉“洪而迟”，应长夏湿土、脾气温厚，故洪而迟。三者皆四时平脉，与季节气化相应，非病脉。", ["微", "浮", "散", "沉"]], "21080": ["平脉", "本段以浮沉分脏腑：心肺居上故脉浮，浮大应心、浮短应肺；肝肾居下故脉沉，牢长应肝、按之濡举指来实应肾，迟缓而长应脾。以脉位浅深、形态长短软硬辨五脏常脉，属平脉分部之论，非主病之脉。", ["浮", "大", "短", "沉"]], "21081": ["病机", "原文强调“胃为水谷腑，主禀四方，皆以胃气为本”，荣卫由水谷化生，行于脉内外，阴阳相贯。虽未出具体脉名，但主旨在于胃气为脉之根本，脉有无胃气关乎荣卫化源，为后文以胃气察脉病之理论依据。", []], "21082": ["预后", "“病脉不病”指人病而脉尚和，为内虚，病轻可治；“脉病人不病”指脉已显病象而人无自觉，名曰行尸，死不治。以脉与症之相应与否判预后，强调脉象先于症状暴露脏气败绝，属死脉预后之论。", []], "21083": ["平脉", "原文以不缓不急、不涩不滑、不长不短等对立脉象皆不偏胜为平和之脉，无病；又言尺欲小大、关欲小实、老人脉欲微，为阳羸于阴之平。全段辨平脉之无偏胜及因人而异的常脉尺度，非主病。", ["缓", "急", "涩", "滑"]], "21084": ["病机", "“按之实强，其脉有似沉伏，名曰牢”，牢脉沉取实强而似沉伏，非真沉伏之虚软。牢为阳脉，主阴寒内实、坚积之病机，脉形坚牢有力，说明邪实内结、气血凝滞，与癥瘕积聚、心腹疼痛等症相应。", ["沉", "伏", "牢"]], "21085": ["病机", "“脉见于关上，无头尾，大如豆，厥厥摇，名曰动”，动脉形圆如豆、摇动不定，见于关部。动为阳脉，主阴阳相搏、气血冲动，多因惊恐、疼痛或阳气浮动而致，与心悸、惊悸、痛证等症相应。", ["动"]], "21086": ["其他", "“上件八条，皆阳脉也”，为总结性条文，指前所列八种脉象同属阳脉范畴，未具体描述脉形与病机。此段仅作归类收束，故不列脉象要素，主旨属脉象分类之其他。", []], "21087": ["病机", "“脉来动而中止，按之小数中能还者，举指则动，名曰结”，结脉动而时止、止后能还，小数中复动。结为阴脉，主阴盛气结、气血痰郁阻滞脉道，然“不死”示其病未至脏气败绝，与气郁、痰凝、寒积等症相应。", ["动", "数", "结"]], "21088": ["死脉", "脉动而止，不能自还，因而复动，名曰代。代脉为脏气衰微，不能接续之象，属阴脉，故主死。原文直言“代者死”，强调其预后凶险，非一般病机可挽回。", ["动", "代"]], "21089": ["其他", "此段总结上件一十四条皆阴脉，未列具体脉象，旨在归类阴脉性质。阴脉多主里、主寒、主虚，与阳脉相对，提示病位在阴分，病性偏衰。", []], "21090": ["病机", "寸口微而尺中弦，或但寸口微而弦，此为相薄。寸微主上焦阳气不足，尺弦主下焦阴寒内盛，阴阳相迫，故称相薄。反映上下阴阳失调，寒热错杂之病机。", ["微", "弦"]], "21091": ["病机", "脉出为阳，入为阴，来往之间为脾，大阴。此以脉之出入往来分阴阳脏腑，出属阳分，入属阴分，往来从容为脾土之象。强调脉势动态与脏腑阴阳的对应关系。", []], "21092": ["病机", "浮滑长皆为阳脉，沉涩短皆为阴脉。浮主表、滑主痰食、长主气盛，故属阳；沉主里、涩主血少、短主气衰，故属阴。此以脉象要素统分阴阳属性，为辨脉大纲。", ["浮", "滑", "长", "沉"]], "21093": ["病机", "以脉之阴阳组合分一阴一阳至一阳三阴。沉滑为阴中阳，沉滑长阴多阳少，浮滑长阳多阴少；浮涩为阳中阴，长沉涩阳多阴少，沉涩短阴多阳少。反映阴阳多少与脉象兼夹。", ["沉", "滑", "长", "浮"]], "21094": ["病机", "脉有伏匿，谓阴阳更相乘伏。阴部见阳脉为阳乘阴，阳中伏阴则时沉涩短；阳部见阴脉为阴乘阳，阴中伏阳则时浮滑长。重阴者癫，重阳者狂，说明阴阳偏盛可致神志病。", ["沉", "涩", "短", "浮"]], "21095": ["预后", "关前阳动脉当九分而浮，过为太过，减为不及，上鱼为溢，外关内格，阴乘之脉；关后阴动脉当一寸而沉，过为太过，减为不及，入尺为覆，内关外格，阳乘之脉。真脏脉见，不病自死；寸不至关阳绝，尺不至关阴绝，皆死不治。", ["浮", "沉"]], "21096": ["病机", "原文以五行生克论脉之相乘，分纵、横、逆、顺。水乘火、金乘木为纵，火乘水、木乘金为横，水乘金、火乘木为逆，金乘水、木乘火为顺。此非具体脉象，而是以五行乘克阐释脉象所反映的脏腑病机传变规律，说明脉诊可辨病势顺逆。", []], "21097": ["预后", "原文言诊三部脉“大小迟疾浮沉正等”，即脉象匀平无偏，虽寒热未解，但阴阳已平，故知病将愈。此以脉之均衡判断阴阳调和，属预后推断，强调脉象和平为向愈之征。", ["大", "小", "迟", "疾"]], "21098": ["预后", "表病发热身痛脉当浮大，反见沉迟；里病腹中急痛脉当沉细，反见浮大。原文谓“故知当愈”，然又言“其人不即愈者，必当死，以其病与脉相反也”。此论脉症相反之预后，脉反其候示阴阳错乱，轻则向愈，重则危殆。", ["浮", "大", "沉", "迟"]], "21099": ["病机", "原文以脉之长、短、数、大、代、细等论气血病机：长则气治，短则气病，数则烦心，大则病进，代则气衰，细则气少。又按脉位与脉形分病之上下内外，如“短而急者病在上”“弦而沉者病在内”。此段总论脉象主病机与病位。", ["长", "短", "数", "大"]], "21100": ["病机", "原文以腑阳脏阴分主热寒，阳微自汗，阴浮自下；阳数口疮，阴数恶寒；阳数出血，阴涩下血。此以阴阳脉象之微、浮、数、涩辨析病机，说明阳脉多主热、阴脉多主寒，数脉主热迫血溢，涩脉主血行滞涩而下血。", ["数", "涩"]], "21101": ["平脉", "原文述脉有三部，随呼吸出入、津液流通而随时动作，春弦秋浮冬沉夏洪，肾沉心洪肺浮肝弦，此为经常之平脉。又言“风则浮虚，寒则牢坚，沉潜水畜”，说明四时脏腑常脉及外邪水气所致脉象变化，属平脉与病脉之总论。", ["弦", "浮", "沉", "洪"]], "21102": ["预后", "原文强调疗病当察形气色泽、脉之盛衰及病之新故。形气相得、色泽以浮、脉顺四时者易治；形气相失、色夭不泽、脉实坚甚、脉逆四时者难疗。此以脉实坚甚与脉逆四时并见，判断邪盛正衰、预后不良。", ["实", "坚"]], "21103": ["预后", "原文以形与脉相失论预后：形盛脉细、少气不足以息者危，形瘦脉大、胸中气多者死；形气相得者生，三五不调者病。此说明脉之细、大与形体盛衰相悖，反映正气虚衰或邪气壅盛，故主危候。", ["细", "大"]], "21104": ["其他", "原文仅标目「诊四时脉第三」，未出具体脉象文字，故无从论其脉为何主何病。四时脉诊法当以春弦、夏洪、秋毛、冬石为常，反此则为病脉；此段为篇题，提示后文将依时令论脉之常变与病机，非直接言某脉主某病。", []], "21105": ["病机", "春肝木王，其脉弦细而长为平脉，弦应肝木，细长应春生之象。反得微浮短涩，是肺金乘肝，金克木为贼邪大逆，故十死不治；浮大而洪为心乘肝，子乘母为实邪，不治自愈；沉濡而滑为肾乘肝，母归子为虚邪，虽病自愈；大而缓为脾乘肝，土畏木为微邪，虽病不死。此以五行生克判病之轻重逆顺。", ["弦", "细", "长"]], "21106": ["病机", "夏心火王，其脉浮大而洪为平脉，浮大洪应心火炎上之象。反得沉濡而滑，是肾水乘心，水克火为贼邪大逆，十死不治；大而缓为脾乘心，子乘母为实邪，不治自愈；弦细而长为肝乘心，母归子为虚邪，虽病当愈；微浮短涩为肺乘心，金畏火为微邪，虽病不死。此以五行生克判病之轻重逆顺。", ["浮", "大", "洪"]], "21107": ["病机", "季夏六月脾土王，脉大穰穰而缓为平脉，大缓应脾土敦厚之象。反得弦细而长，是肝木乘脾，木克土为贼邪大逆，十死不治；微浮短涩为肺乘脾，子乘母为实邪，不治自愈；浮大而洪为心乘脾，母归子为虚邪，虽病自愈；沉濡而滑为肾乘脾，水畏土为微邪，虽病不死。此以五行生克判病之轻重逆顺。", ["大", "缓"]], "21108": ["病机", "原文「凡脾脉王则不见，衰时即见」，谓脾土居中，王时脉象和缓不显，故不见其病脉；及脾气衰，则病脉始见。此非具体脉象描述，而言脾脉常隐、衰乃显之理，提示诊脾当于脉象和缓中察其衰败之兆，属脉象显隐与病机盛衰关系之论。", []], "21109": ["病机", "秋肺金王，其脉微浮短涩为平脉，微浮应秋气之收，短涩应肺金之敛。反得浮大而洪，是心火乘肺，火克金为贼邪大逆，十死不治；沉濡而滑为肾乘肺，子乘母为实邪，不治自愈；大而缓为脾乘肺，母归子为虚邪，虽病自愈；弦细而长为肝乘肺，木畏金为微邪，虽病不死。此以五行生克判病之轻重逆顺。", ["微", "浮", "短", "涩"]], "21110": ["病机", "冬肾水王，其脉沉濡而滑为平脉，沉应冬藏，濡滑应肾水润下之象。反得大而缓，是脾土乘肾，土克水为贼邪大逆，十死不治；弦细而长为肝乘肾，子乘母为实邪，不治自愈；微浮短涩为肺乘肾，母归子为虚邪，虽病自愈；浮大而洪为心乘肾，火畏水为微邪，虽病不死。此以五行生克判病之轻重逆顺。", ["沉", "濡", "滑"]], "21111": ["其他", "原文仅标目「诊寸口脉第四」，未出具体脉象文字，故无从论其脉为何主何病。寸口为脉之大会，诊寸口可察脏腑气血盛衰；此段为篇题，提示后文将专论寸口脉之诊法及所主病机，非直接言某脉主某病。", []], "21112": ["病机", "寸口脉壮大而尺中无有，为阳气偏盛于上、阴分不足于下，阳干阴病。阳盛于上则腰背痛，阴伤于下则阴中伤、足胫寒，脉象壮大与尺无形成上下阴阳偏倾之机。", ["大"]], "21113": ["病机", "脉弱为卫气微，迟为荣中寒。荣血受寒则发热，卫气微弱则心中饥而虚满不能食，弱迟并见反映荣卫俱虚、寒热错杂之病机。", ["弱", "迟"]], "21114": ["病机", "脉弱为阳气不足，缓为胃气有余。阳气不足则运化无力，胃气有余则噫而吞酸、食卒不下，气填膈上，弱缓并见示阳气虚而胃气壅滞之机。", ["弱", "缓"]], "21115": ["病机", "脉微为无气，弱为血不足。气血俱虚则呼吸无力，不能呼不能吸，呼吸不足则胁满短气，微弱并见主气血两虚、呼吸不利之病机。", ["微", "弱"]], "21116": ["病机", "脉微为卫气不得，涩为荣气不逮。荣卫不能相将则三焦无所仰，身体痹不仁；荣气不足则疼而烦满、口难言；卫气虚则恶寒数欠，微涩示荣卫俱虚、三焦失养之机。", ["微", "涩"]], "21117": ["病机", "脉微为卫气衰，涩为荣气不足。卫衰色黄，荣不足色青，荣卫俱微则根叶枯槁，见寒栗、咳逆、唾腥、吐涎沫，微涩主荣卫俱虚、根叶枯槁之病机。", ["微", "涩"]], "21118": ["病机", "脉微而缓，微则卫气疏而肤空，缓则胃气足而谷消水化，荣盛肤疏则三焦绝经名曰血崩。脉微而数，微为风、数为热，风则汗出，热则振寒栗，示卫疏荣盛、风热相搏之机。", ["微", "缓", "数"]], "21119": ["病机", "寸口脉微而迟，尺脉沉为血、滑为实，血实内结入络胸臆，致肺痿色薄、不能喘息，心坚脱色、口不能言，肝举筋厥、四逆不识人，微迟沉滑示血实内结、脏腑气机逆乱之机。", ["微", "迟", "沉", "滑"]], "21120": ["病机", "原文以微、濡、弱三脉互训：微为寒，濡为恶寒，弱为发热，濡又主厥逆。微濡相薄则阳气郁而化烦，其气在心。说明寸口脉微而濡者，总由阳气虚衰、寒湿内盛，卫外不固故恶寒，阳浮于外故发热，阳不达四末故厥逆，虚阳扰心故烦，病机重心在心阳不足。", ["微", "濡", "弱"]], "21121": ["病机", "寸口脉微主阳虚，尺中紧主阴寒内盛。阳微则卫表不固而多汗，汗出更伤阳气；尺紧说明阴寒独存于下。原文断为“虚损多汗”，并谓“知阴常在，绝不见阳”，即阴寒偏盛、阳气衰绝之候，属虚损病机，预后堪忧。", ["微", "紧"]], "21122": ["其他", "此段仅为篇题“诊关上脉第五”，标示论述关部脉象的章节，未载具体脉形与主病文字，故脉象要素为空。其内容属脉诊分部框架，提示后文将围绕关脉候中焦病证展开，本条本身不构成独立的病机判断。", []], "21123": ["主病", "关上脉弦大而长，弦主气机郁滞、痛证，大主邪盛，长主积气有余。关部候中焦，弦长之脉见于关上，说明积气结聚于中焦，故原文断“有痛在脐左右上下”，《脉经》更明言“积在脐左右上下”，皆以脉形定积聚疼痛之部位。", ["弦", "大", "长"]], "21124": ["其他", "此段仅为篇题“诊尺中脉第六”，标示论述尺部脉象的章节，未出具体脉形与主病之文，故脉象要素为空。尺部候下焦、肾与二阴，此篇题提示后文将论尺脉所主病证，本条自身不含可分析的脉象与病机内容。", []], "21125": ["病机", "尺脉候下焦，滑主湿浊痰热，浮大主阳热外浮。原文称“阴中之阳病”，即阴分部位出现阳热之象。湿热蕴结下焦，气化不利，故少腹痛满、不能尿；热注前阴则尿时阴中痛，热移大肠则大便亦热，皆由尺脉滑浮大所主之湿热下注。", ["滑", "浮", "大"]], "21126": ["主病", "尺寸俱浮而直下，原文以此为督脉之候。督脉行于背脊，浮脉主阳、主表，直下形容脉势挺直。督脉为病则腰脊强痛、不得俯仰；阳浮气逆上犯，大人发为癫病，小儿则为风痫，皆由督脉经气失常所致。", ["浮"]], "21127": ["主病", "尺寸俱牢、直上直下，原文以此为通冲脉之候。牢脉主沉寒痼冷、坚积内结，冲脉起于胞中而上行胸腹。寒邪结于冲脉，阳气不通，故胸中有寒疝之病，脉形坚牢挺直正反映寒凝气结之实象。", ["牢"]], "21128": ["其他", "此段仅标目「诊杂病脉第七」，未出具体脉象文字，故脉象要素为空。原文属篇章题名，提示下文将论杂病脉诊之法，非具体病机判断，亦不主某病。列「其他」以存其目，不与后文脉证相混。", []], "21129": ["预后", "原文言「热病，大汗后脉不安静者，此段死」。热病大汗后，邪应随汗解，脉当安静；今脉不安静，说明汗出而邪未退，正气已伤而脉仍躁动，正虚邪恋，故断为死候。此段重在凭脉判预后，非论具体脉形。", []], "21130": ["病机", "原文「热病，脉盛大而快，不得汗，此热发也」。盛大而快即洪数之象，主热盛鼓动气血；热盛而不得汗，说明表气闭郁、热无从外泄，故曰「热发」。此脉此证相应，示热邪亢盛、汗不得出之病机。", ["洪", "数"]], "21131": ["预后", "原文「寒热瘛疭，脉绝代者，死」。瘛疭为筋脉拘急抽搐，寒热交作已示邪正纷争；脉绝代则气血衰败、脉气不能接续，脏气将绝，故主死。此段以代脉判断危候，说明脉气断续与抽搐并见，为正败邪盛之兆。", ["代"]], "21132": ["预后", "原文「热病未得汗，脉盛大者，生；细小者，死」。热病未得汗，邪仍在表，脉盛大说明正气尚能抗邪，故生；脉细小则正虚无力驱邪，故死。此段以脉之大小判热病未汗之预后，盛大与细小对举，突出正盛正衰之别。", ["洪"]], "21133": ["预后", "原文「热病多汗，脉虚小者，生；紧实者，死」。热病多汗已伤津气，脉虚小正合汗后正虚之象，故生；脉紧实则邪热仍盛而正已耗，脉与汗后虚象相违，故死。此段以虚小与紧实对举，判热病多汗之吉凶。", ["虚", "细", "紧", "实"]], "21134": ["预后", "原文「热病得汗，脉常喘而热不退者，死」。得汗后热当退、脉当静，今脉喘而热不退，说明汗虽出而邪热未解，脉气仍急促不宁，正不胜邪，故断为死候。此段以汗后脉喘、热不退并见判预后，未出具体脉名。", []], "21135": ["预后", "原文「汗出而衄，其脉小滑者，生；大躁者，死」。汗出而衄，阴血已伤；脉小滑则邪热不甚、胃气尚存，故生；脉大躁则邪热亢盛、阴血耗散，故死。又云微细为难治，亦示正虚难复。此段以脉之小滑与大躁对举判吉凶。", ["小", "滑", "大", "躁"]], "21136": ["预后", "伤寒脉浮而洪大，为邪在表、正气尚盛，故易治；谵言妄语身热而脉洪大，是阳证脉与证相应，故生。若脉转沉细而微，兼手足四逆，则阳气衰败、阴寒内盛，脉证相反，故主死。原文以浮洪大与沉细微对举，判表里寒热之顺逆。", ["浮", "洪", "大", "沉"]], "21137": ["预后", "咳而尿血、羸瘦，已见阴血耗伤、虚火灼络之象；此时脉反大，是脉与羸瘦之体不相称，属脉大为劳、正气外浮而根不固，故主死。原文以“羸瘦”与“脉大”对举，示形脉相反、虚证见实脉之危候。", ["大"]], "21138": ["预后", "咳而羸瘦，肺气已损、形肉消脱；脉坚大者，坚为邪实内结、大为病势亢盛，正气虚而脉反坚大，是脉证相反、胃气已败，故主死。原文以“羸瘦”与“坚大”相形，明虚体见实脉之逆。", ["坚", "大"]], "21139": ["预后", "上气注液，气逆而津液不摄；脉虚、慢、伏匿，是正气虽弱而脉尚柔缓沉潜，与虚证相应，故生。若脉牢弦，则牢为坚积、弦为劲急，邪气内结而正气受迫，虚证见牢弦实脉，脉证相反，故死。原文以虚伏与牢弦对举判吉凶。", ["虚", "伏"]], "21140": ["预后", "寒疰上气，寒邪上逆而气机壅塞；脉虚濡者，虚为正气不足、濡为脉来柔缓，尚与虚寒之证相应，故生。若牢急而疾，牢主坚积、急疾主邪势暴张，正气虚而脉反劲疾，脉证相反，故死。原文以虚濡与牢急疾对举。", ["虚", "濡", "牢", "急"]], "21141": ["预后", "上气喘息，肺气上逆；脉滑而手足温，滑为气血尚充、温为阳气未败，脉证相应，故生。若脉涩而四肢寒，涩主血少气滞、寒主阳衰不达四末，正虚邪滞而阳气将竭，故死。原文以滑温与涩寒对举，判阳气存亡。", ["滑", "涩"]], "21142": ["预后", "上气而面浮肿、肩息，是气逆水泛、肺失肃降，病势已重；脉浮大者，浮为气浮于上、大为邪盛无制，正虚而脉反浮大无根，是脉证相反、气将上脱，故主死。原文以“面浮肿肩息”与“浮大”相参，示危候。", ["浮", "大"]], "21143": ["预后", "上气喘息，脉滑者，滑为气血尚充、脉来流利，与喘息之证尚能相应，故生；若脉大而快，大为邪盛、快即数急，是正气虚而脉反亢急，脉证相反，故死。原文以滑与“大而快”对举，判顺逆。", ["滑", "大"]], "21144": ["预后", "唾血而脉沉弱，沉为在里，弱为气血不足，与失血后阴血亏虚、正气渐衰之象相应。脉证相符，故主生。原文并举“紧强者死，滑者生”，紧强为邪热炽盛、脉失柔和，滑则气血尚充，反衬沉弱虽虚而胃气未绝，故可生。", ["沉", "弱"]], "21145": ["预后", "吐血而脉牢实，牢为坚积内着、实为邪气壅盛，失血之后脉反牢实，说明瘀热固结、正气不能胜邪，脉与吐血脉证相逆，故主死。原文直断“脉牢实者，死”，强调出血后忌见坚劲有余之脉。", ["牢", "实"]], "21146": ["预后", "吐血、鼻衄后脉沉细，沉为在里，细为阴血虽伤而脉道尚柔，与失血后虚象相应，故生；若浮大而牢，浮大示阳气外越，牢为坚积，失血而见浮大坚牢，是邪热亢盛、阴不敛阳，脉证相逆，故死。", ["沉", "细", "浮", "大"]], "21147": ["预后", "中恶腹大，脉紧实细者，紧实为邪气内结，细则尚存收敛之象，邪虽盛而脉未散越，故生；浮大则邪气外张、正气不守，故死。金疮出血不断而脉大且止，大为气浮，止为脉气断续，出血不止而脉见歇止，故七日死。", ["紧", "实", "细", "大"]], "21148": ["预后", "金疮出血太多，脉虚细者，虚细为血去而脉道空虚，与失血之候相符，故生；大数者，大为邪热鼓动，数为热盛迫血，出血多而脉反大数，是阴血亏而阳热亢，脉证相逆，故死。", ["虚", "细", "大", "数"]], "21149": ["预后", "金疮去血四五升，脉弱微缓而迟，弱微为气血虚衰，缓迟为脉气从容不迫，与大量失血后虚象相应，故生；急疾则脉失柔和、邪热内迫，失血而见急疾，是正气欲脱而邪势未衰，故死。", ["弱", "微", "缓", "迟"]], "21150": ["预后", "被笞榜而内有结血，脉实大者，实大为瘀血内结、邪气尚盛，脉与结血之实证相应，故生；虚小则脉气无力，瘀血内着而正气已衰，不能运化结血，脉证相逆，故死。", ["实", "大"]], "21151": ["预后", "从高堕下及金疮内有瘀血、腹胀，脉牢大者，牢为坚积内着，大为邪实有余，与瘀血内结、腹胀之实证相应，故生；沉细则脉气沉伏细弱，瘀血内结而正气不能鼓动，脉证相逆，故死。", ["牢", "大", "沉", "细"]], "21152": ["预后", "心腹痛而脉沉细，沉主里、细主虚，说明痛由里虚寒凝、气血不足所致，脉证相合，正气尚能内守，故主生。若反见浮大而长，是脉气外越、邪盛正衰，里虚而脉不应，故主死。原文以沉细与浮大对举，判其顺逆。", ["沉", "细"]], "21153": ["预后", "腹胀而脉浮，浮为阳脉，说明胀由气机壅滞于外、病势尚浅，脉与证相应，故主生。若脉虚小，是正气衰微而邪气内陷，腹胀本属气机不利，虚小则中气败绝，故主死。原文以浮与虚小对举，辨其正邪进退。", ["浮"]], "21154": ["预后", "下痢而脉微细，微为阳气衰、细为阴血少，说明痢久伤及气血，脉证相符，正气虽虚尚能自守，故主生。若见浮大，是虚阳外浮、邪热未去而正气已败，脉不应病，故主死。原文以微细与浮大对举，判其吉凶。", ["微", "细"]], "21155": ["预后", "下痢而脉代绝，代为止而有常数、绝为脉气不相接续，说明痢久脏气衰微、脉道不利。然原文独言不死，是因其虽见代绝，尚未至真脏脉现、胃气全无，故可图治。此段以代绝辨其可治，与浮大无根之死脉有别。", ["代", "绝"]], "21156": ["预后", "肠澼便脓血而脉沉细虚迟，沉细主里虚、虚迟主寒，说明痢由脾肾虚寒、气血不足所致，脉证相合，故主生。若脉疾大而有热，是邪热炽盛、正气受灼，脉证相反，故主死。原文以沉细虚迟与疾大对举，辨其寒热虚实。", ["沉", "细", "虚", "迟"]], "21157": ["预后", "肠澼下白沫而脉沉，沉主里、主阴，白沫属寒湿内滞，脉证相应，说明病在里而未外越，故主生。若脉浮，是阳气外浮、里虚不能固摄，脉不应病，故主死。原文以沉与浮对举，判其病势之顺逆。", ["沉"]], "21158": ["预后", "肠澼下赤白而脉细微而迟，细微主气血虚衰、迟主寒，说明痢由虚寒内伤、气血不足所致。更兼身体温暖，是阳气尚存、未至厥逆，故曰可治。原文以脉细微迟合身体温暖，辨其阳气未败、尚可图治。", ["细", "微", "迟"]], "21159": ["预后", "肠澼而脉滑，滑主气血尚充、邪未深陷，脉证相合，故主生。若脉浮，是正气外越、里虚不固，故主死；若悬绝，是脉气断绝无根，胃气已败，亦主死。原文以滑与浮、悬绝对举，判其吉凶。", ["滑", "浮"]], "21160": ["预后", "泄痢伤津耗气，脉缓为胃气尚存，时小结乃邪去而正未大伤，故主生；若脉浮大而数，则阴伤而阳浮于外，虚热鼓动，正合《内经》'大则病进'之义，泄痢见此，示正气溃散、邪热鸱张，故主死。原文以缓、结与浮大数对举，判生机在胃气未绝、死机在阳浮无根。", ["缓", "结", "浮", "数"]], "21161": ["预后", "洞泄或去脓血、食不化，脾胃大伤，气血俱耗。脉微小者，脉证相合，正气虽虚而尚未散越，故生；实急者，乃邪气壅盛、胃气已败而脉反坚劲，所谓'脉实以坚，谓之益甚'，正虚邪实，故死。原文以微小与实急对勘，明泄痢之脉贵在柔小、忌在坚急。", ["微", "小", "实", "急"]], "21162": ["预后", "泄痢日久，阴血耗伤，脉细微而涩，是脉证相应、正气虽弱犹未散乱，故生；紧大而滑，则寒邪内盛、痰食搏结，脉反有余，与泄痢之虚证相悖，示邪气未衰而正气已竭，故死。原文以细微涩与紧大滑对举，判脉证相合则生、脉证相反则死。", ["细", "微", "涩", "紧"]], "21163": ["预后", "泄痢而寸关脉不见，尺中时一见，是上中二焦气血衰微、脉道不充，唯肾气独存一脉可察。原文谓'此肾气见'，然肾气虽在而脾胃已败，化源将绝，故断为难治。此以脉之部位有无判脏腑之存亡，非单纯脉象描述，故脉象要素从略。", []], "21164": ["预后", "下痢脉绝、手足寒，是阳气衰微、脉道不通之危候。若晬时脉还、手足转温，则阳气来复、生机尚存，故生；脉不还、手足不温，则阳绝不复，故死。原文以脉还与不还、手足温与不温对举，判阳气存亡，非以具体脉形立论，故脉象要素从略。", []], "21165": ["预后", "霍乱吐下，津液暴脱，脉大为邪气尚盛而正气未竭，脉证相合，故可治；若脉微细，则阳气阴液俱衰，脉道不充，正不胜邪，故难治。原文以脉大与微细对举，明霍乱之脉贵在有力有神，忌在微弱欲绝，判其可治难治。", ["大", "微", "细"]], "21166": ["预后", "霍乱吐下，阳气阴液两伤，脉微迟为阳气衰微、鼓动无力之象；更见气息劣弱、口不欲言，是宗气亦败、神机将息。原文以脉微迟合气息劣、不欲言，断为不治，示吐下之后脉证俱衰、阳气难复者，预后凶险。", ["微", "迟"]], "21167": ["预后", "手足厥逆，脉当沉细而涩，是阳虚寒盛、血脉凝滞之正脉；反得坚大而滑，则脉与证相反，坚大为邪气壅盛、滑为痰热内搏，阳气外越而脉反有余，故死。原文以'当'与'反'对举，明厥逆之脉宜沉细涩、忌坚大滑，判脉证相逆者死。", ["沉", "细", "涩", "坚"]], "21168": ["预后", "水病脉洪大者生，因洪大为阳脉，水湿得阳气鼓动，尚能气化外达，正未大虚；微细者死，因微细为阴阳俱衰、阳气不能运化水湿，水气内闭而脉道不充，故主危候。原文以脉之洪大与微细对举，判水病之生死。", ["洪", "大", "微", "细"]], "21169": ["预后", "消渴脉数大者生，数大示燥热尚盛而正气未竭，脉证相应；细小浮短者死，因细小为阴血枯涸、浮短为阳气浮越无根，消渴日久阴竭阳浮，故主死。原文以数大与细小浮短对举，辨消渴之顺逆。", ["数", "大", "细", "小"]], "21170": ["预后", "卒中风四肢不收、唇口僻、语言不正，脉浮迟者生，浮迟示邪在表而正气尚能抗邪；癫病卒忤脉坚弦实大者生，坚弦实大示邪实而正未虚，尚可攻伐；虚伏濡小者死，因虚伏濡小为正气衰微、邪气内陷，故主危。", ["浮", "迟", "坚", "弦"]], "21171": ["预后", "癫狂恍惚脉实牢者生，实牢为邪实内结、正气尚充，脉证相符，可任攻逐；沉细者死，因沉细为阳气衰微、气血不足，邪实而正虚，无力抗邪，故主死。原文以实牢与沉细对举，判癫狂之顺逆。", ["实", "牢", "沉", "细"]], "21172": ["预后", "中风口噤不能言、四肢不收，脉浮迟者生，浮迟示邪在表而正气尚存、病势较缓；实大数急者死，因实大数急为邪热炽盛、正气溃败，脉证相失，故主危候。原文以浮迟与实大数急对举，辨中风之生死。", ["浮", "迟", "实", "大"]], "21173": ["预后", "风痹不仁、痿厥，脉虚数者生，虚数为气血不足而虚热内扰，与痿厥之虚证相应；牢急者死，因牢急为邪气坚结、脉道劲急，虚证而见实脉，脉证相反，故主死。原文以虚数与牢急对举，判风痹痿厥之顺逆。", ["虚", "数", "牢", "急"]], "21174": ["预后", "目䀮䀮者，视物昏蒙不明也。脉大缓者死，因大缓为胃气败绝、脉失约束而纵缓，精气不能上注于目，故目䀮䀮而脉见大缓，主危候。原文以脉大缓断目病之死，示脉证相失之凶。", ["大", "缓"]], "21175": ["预后", "闭目不欲见人，脉得肝脉者生，肝脉弦而和缓，示肝气未绝、脏气相应；反得肺脉者死，肺脉浮涩而短，肝病而见肺脉，为金来克木、脏气相反，故主死。原文以肝脉与肺脉对举，判闭目之生死。", []], "21176": ["预后", "耳聋多由肾气不足或风热上壅。脉大者，正气尚能抗邪，气血未衰，故主生；若脉沉迟而细，沉主里、迟主寒、细主虚，示肾阳亏虚、精气不能上充耳窍，正虚邪陷，故为难治。原文以脉之大小沉细辨耳聋之吉凶，正是从脉测正气盛衰。", ["大", "沉", "迟", "细"]], "21177": ["预后", "坚积泄痢，积块坚结而兼下利，正气已伤。脉微细者，微为阳衰、细为阴血不足，脉证相应，邪虽盛而正未至溃散，故生；若见浮脉，浮为气浮于外、阳气外越，里虚不能内守，正脱于外，故主死。原文以微细与浮对举，判积痢之顺逆。", ["微", "细", "浮"]], "21178": ["预后", "头痛多属阳邪上扰或气血壅滞。脉短涩者，短为气损、涩为血少，气血虚涩不能上荣，脉证相失，故主死；浮滑者，浮为阳、滑为痰实，阳邪上攻而正气尚充，脉证相应，故生。原文以短涩与浮滑对举，辨头痛之吉凶顺逆。", ["短", "涩", "浮", "滑"]], "21179": ["预后", "中毒药后，毒邪内攻。阳脉洪大而数者，洪大为阳盛、数为热，正气尚能奋起逐毒，毒从阳化而外达，故生；若脉微细，微为阳微、细为阴弱，正气衰败不能抗毒，毒陷正溃，故死。原文以洪大数对微细，判中毒之预后，注文「速」作「迟」亦示脉证相参。", ["洪", "大", "数", "微"]], "21180": ["预后", "暴病骤起，邪气虽急而正气未伤。脉微细者，微细为气血内守、正未外越，脉证相安，故生；若脉大急洪直，大为邪盛、急为气促、洪直为阳亢无制，正不胜邪、气机奔迫，故死。原文以微细与大急洪直对举，辨暴病之顺逆。", ["微", "细", "大", "急"]], "21181": ["死脉", "「大人得小人脉」，指成人反见小儿般细弱短小之脉。成人气血本应充盛，脉当长大和缓；今脉形细小如小儿，示气血衰少、根本已亏，形脉相反，故主死。原文以脉之大小与年龄形质相失为断，属形脉不应之死候。", []], "21182": ["死脉", "「脉但出不能入」，指脉气只外出于寸而不能再内还于尺，来去不相应。脉之出入，赖阴阳升降、气血环流；但出不能入，示阳气外浮不能内守、阴阳不相接续，根本将绝，故主死。原文以脉之出入失常判死候。", []], "21183": ["死脉", "原文以「群鸟之聚」「悬石之落」「出筋之上，藏筋之下」形容将死之脉：来去无常、坚劲无根、散乱不整，如鸟聚忽散、石落无回。此示胃气已绝、真脏脉见，气血不能相续，荣卫失守，故不可候而知，属真脏死脉之象。", ["坚", "散", "乱"]], "21184": ["死脉", "虾游脉冉冉而起、寻复退没、不知所在，来去无根；鱼翔脉似鱼不行而但掉尾动身，动疏住久。二者皆脉无胃气、根本已绝之象，故主死。虾游为阳气欲脱而忽聚忽散，鱼翔为阴血枯竭而脉道涩滞，皆困病危候，与原文'困病脉'相应。", []], "21185": ["死脉", "屋漏脉既绝而止、时复一起、不相连属，是胃气已绝、脉道断续；雀啄脉来甚数而急疾、绝止久已复顿来，是阴竭阳越、虚风内动。原文'脉病人不病'而见屋漏、雀啄，说明形未病而脉已败，脏气竭绝，故主死。", ["数", "疾"]], "21186": ["死脉", "弹石脉辟辟急，来如弹石之坚劲，是肾气绝而真脏脉见；解索脉动数而随散乱无次绪，去如解索之纷乱，是阴阳离散、脉无统纪。来坚去散，根本已败，故原文断为'死'，与真脏脉见、胃气全无之候相应。", ["数", "散", "急"]], "21187": ["死脉", "脉来涌涌不去，谓脉气涌盛上溢而久留不退，来势汹涌无从容和缓之胃气。此乃邪气亢盛、正气不能约束，或脏气逆乱、脉无根蒂之象。原文径言'死'，说明脉失柔和、来去不宁，属真脏败脉，与危重病候相应。", []], "21188": ["死脉", "脉如转豆，谓脉来短促坚硬、旋转如豆之滚动，无上下从容之态。此象为胃气竭绝、真脏脉见，脉道拘急而失柔和。原文断为'死'，说明脉无胃神根，脏气已败，与危重病候相应，非寻常病脉可比。", []], "21189": ["死脉", "脉如偃刀，谓脉来坚劲如刀锋之仰，浮取坚硬、按之无根，是胃气全无、真脏脉见之象。此脉刚劲少和，说明脏气竭绝、脉失柔缓，故原文断为'死'，与危重病候相应，属真脏败脉。", []], "21190": ["死脉", "脉怒来忽去、暂止复来，谓脉来急怒而忽去，暂止又复来，来去无常、无从容和缓之胃气。此乃正气涣散、脉无根蒂，或邪气暴逆、脏气不守之象。原文断为'死'，说明脉失胃神根，与危重病候相应。", []], "21191": ["死脉", "脉中移者，谓脉动之中忽有移易、部位不定，来去无常而失其常度。此象为胃气已绝、脉无根蒂，脏气离散不能主持脉道。原文径言'死'，说明脉失和缓从容之胃气，属真脏败脉，与危重病候相应。", []], "21192": ["死脉", "原文直言「脉久绝者，死」。「久绝」指脉气断绝已久而不复，非一时之伏匿，说明气血生化之源已竭，心脉无所禀受，故脉道不能复续。脉绝既久，则脏腑经络失养，生机已尽，故断为死候。此条以脉之有无久暂判生死，与一般主病脉象不同，重在预后。", []], "21193": ["死脉", "「脉有表无里」指轻取似有、重按即无，浮取得象而沉取不应。此示阳气浮越于外，阴血内竭于里，脉之根本已失。表有里无，是阴阳不相维系、根气脱散之象，故主死。原文以表里之有无判脉之根柢，强调重按无根者预后凶险。", []], "21194": ["妇人", "原文「妇人尺脉按之不绝者，胎也」。尺脉候肾与胞宫，按之不绝谓重按仍连续有力、不绝如缕，示肾气充盛、胞宫气血充盈以养胎。妊娠之脉多滑而尺部不绝，此条专从尺脉按之不绝断胎，说明胎孕赖肾气维系，脉不绝即有根，故主有娠。", []], "21195": ["预后", "产后寸口「焱疾不调」为阳气浮越、脉失和缓，故死；「沉微附骨不绝」示脉有根底、胃气尚存，故生。新产后渴而热病，脉细而四肢冷，细为阴血不足，冷为阳气不达四末，热病伤阴而阳不外温，阴阳离决，故断为死候。原文以脉之有无根、肢之温冷判产后吉凶。", ["细", "疾", "沉", "微"]], "21196": ["妇人", "「三部脉沉浮正等不断绝者，有娠也」。三部脉浮沉取之均等而连续不绝，示气血和平、阴阳相抱，无偏浮偏沉之弊。妊娠之脉贵在冲任气血调和，脉来有根而不绝，故以沉浮正等不断绝为有娠之征，与尺脉不绝条互参，皆从脉之有根和调断胎。", ["沉", "浮"]], "21197": ["妇人", "妊娠脉滑疾而按之不散，为气血充盛养胎之象，故胎已三月；但疾不滑则血少，故推五月。七八月脉实大牢强弦紧，示母气壮实、胎有所养，故生；沉细则气血衰少，故死。欲产脉细而滑，细为血聚胞宫、滑为气血流利，是临产离经之渐。原文以脉之滑疾、实大、沉细辨胎孕与产候吉凶。", ["滑", "疾", "实", "细"]], "21198": ["妇人", "「妇人欲产，其脉离经者，曰生也」。离经指脉象忽然变异、异于平常，非经脉断绝之义，是临产时气血骤聚胞宫、脉道随之而变的表现。脉能离经而变，说明气血尚充、胎气灵动，故主顺产。此条以脉之变异判产候，与死脉之「绝」不同，重在生机尚存。", []], "21199": ["预后", "新产脉小缓滑者生，小为血去而脉不洪，缓为胃气和调，滑为气血流利，示产后虽亡血而胃气未败、脉有柔和之象，故生。实大弦急则脉失柔和、肝木偏亢、气血壅逆，产后正虚而脉反刚劲，故死。原文以脉之缓滑与弦急对举，判新产之吉凶。", ["小", "缓", "滑", "实"]], "21200": ["预后", "产后脉沉虚小者生，因沉虚小示气血虽耗而脉气尚柔，胃气未绝，故预后佳；实牢坚者死，实牢坚为邪气壅盛、脉失柔和，产后见之乃胃气败绝、瘀血内结之兆，故主死。原文以脉之虚实判生死，紧扣“已产”后气血状态。", ["沉", "虚", "小", "实"]], "21201": ["预后", "月经不通脉绝小实者生，绝小实示脉虽细而根气尚存，实为瘀血内阻而正气未竭；浮虚者死，浮虚为气血外浮无根、冲任枯竭之象，故预后不良。原文以“绝小实”与“浮虚”对举，判经闭之生死。", ["绝", "小", "实", "浮"]], "21202": ["病机", "寸关调如故而尺脉绝不至，尺候下焦，尺绝不至示冲任胞宫气血阻绝，故月经不利；少腹引腰绞痛、气积聚上叉胸胁，乃下焦寒凝气滞、瘀血内结，气逆上冲所致。原文以尺脉绝点明病位在下焦，症候与脉相应。", []], "21203": ["预后", "漏下赤白脉急疾者死，急疾为热迫血妄行、阴血暴脱而脉失柔和，故主危候；迟滑者生，迟滑示脉有胃气、热势未炽，气血尚能自持。原文以脉之急疾与迟滑对举，判漏下之生死顺逆。", ["急", "疾", "迟", "滑"]], "21204": ["病机", "妇人脉迟而寸俱微弱，迟为阳气不足，微弱为气血俱虚，寸候上焦心肺，寸弱则气血生化无源，冲任空虚，胞宫失养，故绝子不产。原文以“迟”与“寸俱微弱”点明虚寒病机，主不孕。", ["迟", "微", "弱"]], "21205": ["病机", "小儿脉沉者乳不消，沉主里、主水谷内停，小儿脾胃娇弱，乳食过量则停滞中焦，脉气内沉，故见乳不消。原文以“沉”直指乳食积滞之里证，脉症相应。", ["沉"]], "21206": ["死脉", "按脉五十至而不止者五脏皆受气足为吉；四十动一止则一脏无气，三十动一止二脏无气，二十动一止三脏无气，十动一止四脏无气，死期随止数递减。原文以代止之疏密测脏气存亡，止数愈频则脏气愈衰，故主死。", []], "21207": ["死脉", "脉一动一止、或三动一止、或十动一止，投数无常，此死脉也。动而止无常数，示脏气衰败、脉气不能接续，胃气将绝，故虽命未尽亦不过苟延日月。原文以“投数无常”点明代止杂乱无根，主死。", ["动", "结", "代"]], "21208": ["平脉", "原文以呼吸定息计至，一呼再至、一吸再至，合定息共五至，且“不大不小”，故为平脉。若一呼三至、一吸三至，至数增多，超出常度，故“始为得病”，提示阳热偏盛或正气受扰，脉行急迫，属病脉之始，非死候。", ["平"]], "21209": ["主病", "原文以脉形前后对比言病：“前大后小”则上盛，故为头痛目眩；“前小后大”则上虚下实，胸中气机不利，故为胸满短气。脉之前后大小反映气血上下分布偏倾，寸尺盛衰不同，故主头部与胸膈症候。", ["大", "小"]], "21210": ["预后", "原文以“一呼再至曰平”为常，三至、四至、五至、六至依次为离经、夺精、死、命绝，属至脉从下上；一呼一至至四呼一至为损脉从上下。损脉“血脉虚少，不能荣于五脏”，渐损皮毛、血脉、肌肉、筋、骨，故见皮聚毛落、消瘦、筋缓、骨痿，示病情由浅入深，预后凶险。", ["虚", "数", "疾"]], "21211": ["病机", "原文以“一息再至为平”定常，一息三至名离经。“离，失也；经，常也”，谓脉失其常度，至数偏多。原文直言“其人荣卫已亏，将欲病也”，说明脉数非纯实热，乃荣卫不足、脉行失守之先兆，属病机将成未成阶段。", ["平", "数"]], "21212": ["预后", "原文以息计至递减言危候：一息一至，虽能行而“当著床”，因“血脉已病，诸气皆不足”；二息一至为危，三息一至为困，四息一至为行尸将死，五息一至为定死。至数愈少，示气血虚衰愈甚，脏气将竭，故预后由危困至死。", ["迟", "虚"]], "21213": ["其他", "本段为医史叙事，记甄权针治成君绰颈肿喉闭、水粒不下，针右手次指之端而气息即通，未言脉象。原文重点在展示甄权针术效验及其校定《明堂》之事，属医家事迹与针灸治法记录，非脉诊病机条文，故脉象要素为空。", []], "21214": ["其他", "原文为腧穴定位文字，言“上关在客主人下耳前动脉下空下廉”，以“动脉”为取穴标志，非论脉象主病。所述“合口有穴，张口则闭”亦属穴位开合特征，与脉诊病机无关，故归其他，脉象仅取“动”字。", ["动"]], "21215": ["其他", "原文为“大迎”穴定位，言在“曲颔前一寸二分骨陷中动脉”，以动脉搏动处作为取穴依据，非诊脉论病之文。全段旨在明穴位所在，未涉病机症候，故归其他，脉象要素仅取“动”字。", ["动"]], "21216": ["其他", "此段为颅息穴定位，言其在耳后青脉之间，属针灸腧穴内容。原文以\"青脉\"标志穴位所在，非论脉象主病，故无脉象要素可析，亦不涉病机。归为其他，示其非脉学正文。", []], "21217": ["其他", "此段述瘛脉穴位于耳本鸡足青脉处，并明言\"不灸\"，属腧穴定位与灸禁。原文\"青脉\"指浅表血络，非诊脉之象，故不取脉素。主旨为穴位记述，非论病机，归其他。", []], "21218": ["其他", "此段为和窌穴定位，言在耳前兑发下动脉处。\"动脉\"指可触及搏动之脉，用以标定穴位，非以脉论病。虽取\"动\"为脉素，然全段主旨仍是腧穴定位，不涉主病病机，故归其他。", ["动"]], "21219": ["其他", "此段述人迎穴在颈大筋脉动应手处，夹结喉旁以候五脏气，并言\"不灸\"。人迎虽为诊脉要处，然原文重在定位与灸禁，\"动应手\"仅描述搏动可触，非论脉象主病，故归其他。", ["动"]], "21220": ["其他", "此段为带脉穴定位，言在季肋下一寸八分。全段仅述腧穴部位，未及脉象描述，亦无论病机主病之文，故脉素为空，归其他，示其属针灸经穴内容。", []], "21221": ["其他", "此段述五枢穴在带脉下三寸，并附异说在水道下一寸半。原文纯为腧穴定位与异同校注，无脉象、无病机、无主病之论，故脉素空，归其他。", []], "21222": ["其他", "此段为云门穴定位，言在巨骨下气户两旁各二寸陷中，\"动脉应手\"，举臂取之。\"动脉应手\"用以标定穴位，非论脉诊病机，全段主旨为腧穴定位，故取\"动\"而归其他。", ["动"]], "21223": ["其他", "此段述中府穴在云门下一寸、乳上三肋间，\"动脉应手陷中\"。原文以动脉搏动处定穴，属腧穴定位内容，非以脉象论病机主病，故取\"动\"为脉素，归其他。", ["动"]], "21224": ["其他", "此段纯述不容穴的定位：在幽门旁一寸五分，去任脉二寸，直肋端相去四寸。原文未出现任何脉象描述，亦未论及脉与病机的关系，故无从据脉析病机。其内容属腧穴部位考订，与脉学所主病机无涉，只可视为针灸取穴的定位资料。", []], "21225": ["其他", "此段述冲门穴定位，在府舍下横骨两端约中动脉处。原文以「动脉」为取穴标志，指该处可触及搏动之脉，非以脉论病。动脉在此仅作体表定位依据，说明冲门位于股动脉搏动处，与脉象主病无关，属腧穴定位内容。", ["动"]], "21226": ["其他", "此段述鱼际穴位置，在手大指本节后内侧散脉内。原文「散脉」指该处脉络分布散漫可见，是体表浅络的形态描述，用作取穴标志，并非脉诊中主病之散脉。故此处散脉不主气血耗散等病机，仅为腧穴定位服务。", ["散"]], "21227": ["其他", "此段述尺泽穴在肘中约上动脉处。原文以「动脉」标定穴位，指肘窝中可扪及搏动之处，属体表动脉定位，非论脉象所主之病。动脉在此只作取穴依据，说明尺泽位于肘部动脉搏动处，与病机分析无关。", ["动"]], "21228": ["其他", "此段述侠白穴在天府下、去肘五寸动脉处。原文「动脉」为体表可触搏动之标志，用以确定穴位所在，并非脉诊病机之论。故本条动脉不主任何病机，仅说明侠白位于臂部动脉搏动处，属腧穴定位内容。", ["动"]], "21229": ["其他", "此段述天府穴在腋下三寸、臂臑内廉动脉处，并注明「不灸」。原文动脉仍为取穴定位标志，指臂内廉可扪及搏动处；「不灸」是针灸禁忌，非据脉断病。全段未以脉象论病机，属腧穴定位与施治禁忌的记载。", ["动"]], "21230": ["其他", "此段述五里穴在肘上行马里大脉中，并注「不刺」。原文「大脉」指该处脉络粗大可见，作取穴标志，非脉诊主病之大脉。故此处大脉不主邪盛等病机，仅说明五里位于肘上粗大脉管处；「不刺」为刺禁，属腧穴定位与禁忌内容。", ["大"]], "21231": ["其他", "此段述阴郄穴在掌后脉中、去腕半寸。原文「脉中」指掌后脉管所在之处，用以定位，未给出具体脉象写法，亦未论脉所主病。故本条无从据脉析病机，属腧穴定位记载，与脉诊病机无直接关系。", []], "21232": ["其他", "此段为极泉穴定位，言其位于腋下筋间动脉处，入胸。文中\"动脉\"仅指可触及搏动之脉管，用于定穴，非论脉象主病。动脉在此为解剖标志，说明该处脉气显露可扪，与病机无关，故不归主病或病机，属针灸腧穴定位之其他类。", ["动"]], "21233": ["其他", "此段为劳宫穴定位，言其在掌中央动脉处。\"动脉\"指掌中可扪及搏动之脉，用以确定穴位，非诊脉论病。掌中央动脉显露，说明该处脉管浅行可触，属解剖定位，不反映病机，故归其他类，不主病。", ["动"]], "21234": ["其他", "此段为三阳络穴定位，言其在臂上大交脉、支沟上一寸，并注\"不刺\"。\"大交脉\"指该处脉管交会显露，用以定穴，非论脉象。原文未识别脉名，仅述穴位与禁刺，属针灸定位及禁忌，不涉病机，故归其他类。", []], "21235": ["其他", "此段为箕门穴定位，言其在鱼腹上越筋间，动应手于阴市内，一云在阴股内起脉间。\"动应手\"指该处脉动应指可扪，\"起脉\"指脉管起始显露，皆为定穴标志，非论脉象主病，故归其他类，不反映病机。", ["动"]], "21236": ["其他", "此段为气冲穴定位，言其在阴股内动脉处，并注此穴已见上腹第三行中。\"动脉\"指股内可扪及搏动之脉管，用以确定穴位，属解剖标志，非诊脉论病。原文未言脉象主何病机，故归其他类。", ["动"]], "21237": ["其他", "此段为五里穴定位，引《甲乙针经》言其在阴廉下、去气冲三寸，阴股中动脉处。\"动脉\"指股中可触及搏动之脉管，用于定穴，非论脉象主病。原文仅述穴位位置，不涉病机，故归其他类。", ["动"]], "21238": ["其他", "此段为阴廉穴定位，言其在羊矢下去气冲二寸动脉处。\"动脉\"指该处脉管搏动可扪，为定穴标志，非诊脉论病。原文未言此动脉主何病机症候，属针灸腧穴定位，故归其他类。", ["动"]], "21239": ["其他", "此段为太谿穴定位，言其在足内踝后、跟骨上动脉陷中。\"动脉\"指该处脉动应指，陷中为穴处凹陷，用以定穴，非论脉象主病。太谿虽为肾脉所过，但原文仅述定位，未言主病，故归其他类。", ["动"]], "21240": ["其他", "此段为申脉穴定位描述，言其在足外踝下陷中、可容爪甲，属针灸腧穴内容，未涉及脉象指感或病机判断。原文无脉名、无主病之语，故不能据以推演病机，脉象要素亦无从提取，仅作穴位部位记载。", []], "21241": ["其他", "此段述委中穴位于腘窝横纹中动脉搏动处，'约文动脉'指腘中横纹间可触及搏动之脉。动脉在此为定位标志，非辨病之脉象，原文未言其所主病机，故只属腧穴定位，不能据'动脉'二字推断病候。", ["动"]], "21242": ["其他", "此段讲五脏六腑三阴三阳十二经脉的井荥俞原经合流注次序及募俞所在，以肺手太阴为例列少商、鱼际、大泉、列缺、经渠、尺泽诸穴。全段论经络腧穴配属，未及脉象指感与病机，故脉象要素为空，主旨归其他。", []], "21243": ["治法", "此段言产后脉绝不还，取合谷针入三分急补之，又主胎上抢心。'脉绝不还'指产后脉气断绝不复，属气血暴脱之危候，故用补法急刺合谷以回脉气；胎上抢心亦由气逆上冲所致。原文重在针治取穴与手法，故归治法。", []], "21244": ["妇人", "此段论妇人下血、漏下赤白，灸营池穴三十壮，穴在内踝前后两边池上脉处，一名阴阳。'池上脉'为取穴标志，非辨病脉象。漏下赤白属妇人经带之疾，多由冲任不固、湿浊下注，原文以灸法温固，主旨归妇人。", []], "21245": ["妇人", "此段言妇人漏下赤白、四肢酸削，灸漏阴三十壮，穴在内踝下五分微动脉上。'微动脉'为穴位处细微搏动之定位语，非主病之脉；漏下赤白兼四肢酸削，示冲任虚损、气血耗伤而筋脉失养，故取灸法温补，主旨属妇人。", ["微", "动"]], "21246": ["其他", "此段述齿疼灸外踝上高骨前交脉处七壮，'交脉'指两脉交会之处，为取穴定位，非脉象描述。原文只言齿疼之灸法取穴，未论脉象指感与病机，故脉象要素为空，主旨归其他。", []], "21247": ["其他", "此段述客主人（上关）穴在听会上一寸动脉宛宛中，针入一分，主耳聋鸣如蝉。'动脉宛宛中'为穴位处搏动陷窝之定位语，非辨病脉象；耳聋鸣如蝉属少阳经气不利、清窍失聪，原文以针取穴论治，未及脉象主病，故归其他。", ["动"]], "21248": ["治法", "本条言耳门穴位于上关下一寸动脉宛宛中，以\"动脉\"定穴，非论脉象主病。动脉在此指局部搏动处，为取穴标志。主耳聋、耳中如蝉鸣，乃耳窍经气闭阻之候，灸针该处可通耳窍经气，故列治法。慎生冷醋滑酒面等，属灸后调护，非脉诊病机。", ["动"]], "21249": ["治法", "本条以下关穴在耳门下一寸宛宛中\"动脉际\"定位，动脉为取穴依据而非诊脉。主牙车脱关、不得嚼食，属下颌关节经筋不利之症，针灸下关以通利关节经气。文中\"动脉际\"只言穴位所在搏动处，未涉脉象主病，故归治法，忌热食酒面为调护语。", ["动"]], "21250": ["病机", "本条以内外沉浮分病位：内属五脏、外属皮肤、沉属骨髓、浮属血脉，是借浮沉言邪之浅深层次，非具体脉象。腠理浅则汤药可及，五脏深则酒醪所至，血脉则针灸所中，骨髓最深则扁鹊亦云不能如何。说明风病传变由浅入深、治各有宜，主病位层次之病机。", []], "21251": ["治法", "本条为脾风占候之灸法，症见言声不出或手上下，属脾风内动、经气逆乱。取手十指头、人中、大椎及耳门前脉去耳门上下行一寸处、大指节上下六穴各七壮。文中\"脉\"指耳前络脉部位，为施灸处，非脉象主病，故归治法，示灸穴以通经熄风。", []], "21252": ["治法", "本条论卒中风口㖞外治：以苇筒纳耳孔、面塞四畔、燃艾灸七壮，并灸手交脉三壮，左病灸右、右病灸左。口㖞属风邪中络、经气偏阻，故取交叉灸法以通调左右经气。\"手交脉\"为施灸部位，非脉象，全条主旨在治法，未涉脉诊病机。", []], "21253": ["预后", "尸厥如死而\"脉动如故\"，是关键：形似死而脉仍搏动，说明生机未绝、气血未散，故可针百会补之、灸熨两胁以回阳通窍。脉动如故在此判断预后可治，与真死脉绝者相别。原文以脉动存否辨生死，紧扣\"如死\"而脉动，属预后判断。", ["动"]], "21254": ["治法", "本条言下关二穴在耳前\"动脉下空下廉陷中\"，以动脉为定位标志，灸各七壮。动脉指耳前搏动处，非诊脉所得脉象，亦未言所主之病，仅述取穴与灸法，故归治法。文中无病机、主病之论，不可据\"动脉\"推演病候。", ["动"]], "21255": ["治法", "本条言颞颥在眉眼尾中间，上下有来去络脉，是针灸治疸气温病之处，夹人中火针治马黄疸通身并黄、语音已不转者。\"来去络脉\"指局部可见络脉，为施针依据，非脉象。疸而通身黄、语声不转，属湿热郁蒸、窍机不利，故取络脉火针以泄邪，归治法。", []], "21256": ["治法", "原文“治诸疟而脉不见者”，脉不见指疟邪深伏、气血壅遏，脉气不能外达，非无脉可察。故取刺十指间（井穴）出血，以泄血分郁热、通阳达邪，“血去心已”示血出则邪随血解、心神得安；又察身赤如小豆者尽取之，是辨疟发之疹点以尽泄邪毒，属因脉不见而转用刺血通阳之法。", []], "21257": ["治法", "原文“肝劳，邪气眼赤”，肝开窍于目，劳伤肝气则邪热上攻目系而赤。灸当容百壮，取“眼后耳前三阴三阳之会处”，以手按“有上下横脉”为穴征，正是凭横脉之显现定灸位，使三阴三阳经气交会得通，邪热从阳经而散，属以脉定穴、灸治肝劳目赤之法。", []], "21258": ["病机", "“左手关上阳绝者，无胆脉也”，关候肝胆，阳绝即少阳胆脉不至，胆气不足。胆主决断，虚则“恐畏如见鬼，多惊少力”；胆液不荣则口中无味。此以脉绝定位胆腑虚衰，症候与脉相应，故刺足厥阴及三毛中，从肝之表里以振奋少阳胆气，属脉绝主病机之论。", []], "21259": ["治法", "原文“脉不出，针不容两穴”，脉不出指脉气沉伏不显，多因中焦气机壅滞、脉道不利。不容穴在幽门两旁各一寸五分，属足阳明胃经，主调中焦、通腑气。针之使胃气畅达，气行则脉自出，是凭脉不出而定取阳明之穴，属以针通脉、调中焦气机之法。", []], "21260": ["病机", "“左手关前寸口阳绝者，无小肠脉也”，寸口候小肠，阳绝即小肠经气不至。小肠虚寒则“脐痹，少腹中有疝瘕”，寒凝气滞，冷气上抢心。此以寸口阳绝定位小肠虚衰，症候由经气不通、寒凝少腹而来，故刺手心主（掌后横纹中入一分），从心与小肠表里以温通其气，属脉绝主病机。", []], "21261": ["病机", "“左手关前寸口阳实者，小肠实也”，寸口脉实而动，主小肠实热。实脉为邪气盛，动脉为热搏气血，故见“心下急，热痹，小肠内热，小便赤黄”，皆实热内蕴、循经上扰下注之症。原文以“动脉”定刺手太阳之位，是凭脉之实动辨小肠实热，脉症相合，属脉实主病机之论。", ["实", "动"]], "21262": ["治法", "原文“又，灸督脉三十壮，在直鼻人中上，入发际三报之”，此承前文而补灸法。取督脉自人中直上入发际之穴，督脉总督诸阳，灸之可振奋阳气、通调经脉。“三报之”指分三次施灸，使阳气渐复而不骤。全段未言脉象，专述灸督脉之部位与壮数，属针灸治法之记录。", []], "21263": ["治法", "“狂走惊痫”为阳热扰神、痰火蒙心之候。灸河口五十壮，穴在“手腕后陷中动脉”，即手阳明经动脉应手处，凭动脉之搏动定穴。阳明多气多血，灸之可泄阳热、通神明，使狂惊痫证得平。原文以动脉为穴征，属因脉定位、灸治阳热神病之法，非以脉断病机。", ["动"]], "21264": ["治法", "本条言狂邪惊痫取承命穴灸治，定位在“内踝后上行三寸动脉上”。动脉搏动处为经气汇聚之所，狂邪惊痫乃神志逆乱、痰火扰心之候，灸动脉处可通调经气、潜镇浮越之神明，故以动脉为施灸标志，属灸法取穴定位，非以脉断病。", ["动"]], "21265": ["治法", "惊狂走者，神志躁动不宁，属阳热扰神、气逆于上。灸“内踝上三寸，近后动脉上”，取动脉搏动处为穴，意在通经泄热、安神定志。动脉在此为定位标志，说明灸法可借脉动之处调畅气血，使惊狂得平，非据脉象推断病机。", ["动"]], "21266": ["其他", "“尺中动脉名鬼受”为古代脉位与穴名之标识。尺中动脉即尺部搏动处，古人以“鬼受”名之，属针灸取穴或脉诊部位的称谓记录。此条未言病候，动脉仅作部位指认，说明尺部脉动可触之处为施治着眼点，非以动脉主某病。", ["动"]], "21267": ["预后", "干呕不止、食入即吐，胃气上逆已甚；若更见四厥而“脉沉绝不至”，则阳气衰败、脉道不通，属危候。灸间使三十壮以通阳复脉，原文谓“灸之便通，此法起死人”，正说明沉绝之脉主阳亡气闭，灸后脉通即生机可复，故本条重在凭脉判断预后险恶。", ["沉", "绝"]], "21268": ["治法", "气短不语，属肺气壅塞或宗气不足、声道不利。原文列大椎、肺俞、肝俞、尺泽及“小指第四指间交脉上”、手十指头等灸法，交脉处为经气交会之所，灸之可宣肺利气、开音通窍。本条纯为灸穴记录，未以脉象言病机，故脉象要素为空。", []], "21269": ["治法", "五淋不得尿，为湿热蕴结下焦、膀胱气化不利。灸悬泉（中封别名），“在内踝前一寸，斜行小脉间是”，以小脉为取穴标志。小脉指细小的络脉搏动处，说明施灸须循细小脉道定位，以通利下焦、助膀胱气化，非以小脉主淋病之机。", ["小"]], "21270": ["治法", "本条仅载“灸两耳后发际直脉七壮”，直脉指耳后发际处纵行之脉，为施灸定位标志。原文未出病候，亦未以脉论病，属灸法取穴记录。耳后直脉近少阳经分野，灸之可疏泄少阳、通调头部经气，然本条主旨仍在治法取穴，脉象要素无可取。", []], "21271": ["治法", "“灸两手鱼际各二七壮，断痈脉也”，痈脉指痈肿毒邪循脉流注之势。鱼际为肺经荥穴，灸之可清泄肺热、消散痈毒，使痈脉断绝不再蔓延。本条以“断痈脉”说明灸法能截断痈毒传变之路，属治法范畴，未以具体脉象论病机，故脉象要素为空。", []], "21272": ["病机", "原文述风邪由孙脉入络脉、入大经、注腑归脏，未直接言脉象，故脉象要素为空。其病机为外风乘腠理开而内传，由浅入深，最终归心，故谓“风病多归于心”。后文灸刺诸穴之禁忌，示误治可致心惊、气上、绝孕，属病机与误治相兼之论。", []], "21273": ["误治", "“微数之脉”示正气已虚而兼有热象，微为气阴不足，数为热扰，虚热内蕴；新汗后津气外泄，腠理疏松，阴阳未复。此时若用灸法，易助热伤津、耗气动血，故列为禁忌。原文以脉象与汗后状态并提，说明灸法须避虚热及津伤之体，属误治警示。", ["微", "数"]], "21274": ["其他", "本段列举头维、脑户、风府等禁灸或慎灸穴位，末注“女人忌灸”石门，属针灸禁忌之列，未言脉象。其旨不在脉诊，而在提示特定腧穴不可妄灸，以免伤及经络气血。石门为妇人禁灸，与绝孕相关，体现古人对穴位禁忌的重视，归为其他。", []], "21275": ["其他", "本段仅列玉枕、维角、睛明、舌根、结喉等穴名，未涉脉象与病机，当为针灸穴位禁忌或部位举要之残文。原文无脉象描述，亦无主病、预后之论，故脉象要素为空，类别归其他，不宜强解为脉学内容。", []], "21276": ["治法", "原文强调“凡欲针灸，必先诊脉”，以脉诊为先决条件，兼看行年、本命、人神、吉辰及忌穴，再定壮数。其核心是针灸施治前的诊脉与择时择穴法则，属治法范畴。虽未列具体脉象，但明确脉诊在针灸决策中的统领地位，体现脉学与针灸实践的结合。", []], "21277": ["其他", "此段为医书序论，从清浊肇判、四时寒暑说到人禀五常、形质既著则疴瘵生，继而述调针切脉、汤药针灸禁咒符印导引五法。全段未言具体脉象，旨在阐明医学源流与治法多样，脉诊仅为其中一端，故脉象要素为空，类别归其他。", []], "21278": ["其他", "本段为禁咒疫鬼之辞，以东西南北四方鬼名配心口、肝肠、皮、百脉，又借六甲六乙等干支咒语驱疫。文中“倚于百脉”虽涉脉字，但非脉象诊法，而是咒术中的病位表述。全段无脉象要素，主旨属禁咒疗法，归其他。", []], "21279": ["治法", "本段为禁咒疗疮之法，述先左营目、闭气禁之，以“清血无流，浊血无往”“脉脉相当”等语描述疮口气血调和之态，非诊脉之象。其旨在于以咒术配合调气止血、促疮向愈，属治法中的禁咒一类。脉象要素为空，不作脉学病机解。", []], "21280": ["其他", "本段为咒禁祝由之辞，非脉诊内容。文中“注心根”“注百脉”“注脊腰”“注心脾”“注十指”言四方注气侵入人体不同部位，属古代禁咒疗法对病邪传注的想象描述，与脉象要素无关，故脉象取空。其主旨不在辨脉主病，而在咒注驱邪，故归其他。", []], "21281": ["其他", "本段亦为禁咒之辞，“配阴脉十三，阳脉十五，二十八脉随手上下”虽涉脉数，然系咒语套语，非论脉象主病。“一脉一通，知汝有苦”及“骸骨消散，流离道旁”等语，皆咒禁中设想邪祟为害之状，非实际脉诊候病机，故脉象取空，归其他。", []], "21282": ["其他", "本段述医道源流，自燧人、伏羲、神农、黄帝至和缓、扁鹊、仓公、仲景、华佗，赞其“探赜索隐，穷幽洞微”，而叹晋宋以后“治十不能愈五六”。全段未及具体脉象与病机，虽标题有“脉诊候，采药合和”字样，原文实为医史总论，故脉象取空，归其他。", []], "21283": ["其他", "本段论为大医之条件，须谙《素问》《甲乙》《针经》及三部九候、五脏六腑、表里孔穴，兼通阴阳禄命、相法卜筮，并涉猎群书。文中“三部九候”虽属诊法范畴，但全段旨在强调医者学养，非辨析脉象所主病机，故脉象取空，归其他。", []], "21284": ["病机", "本段指出“病有内同而外异，亦有内异而外同”，五脏六腑盈虚、血脉荣卫通塞非耳目所能察，必先诊候。而“寸口关尺有浮沉弦紧之乱”，说明脉象浮沉弦紧错杂，反映表里寒热虚实相混之病机；若“盈而益之，虚而损之”则重加其疾，故须用心精微以审脉辨机。", ["浮", "沉", "弦", "紧"]], "21285": ["病机", "本段言人禀天地中和之气而生，头圆足方、五脏法五星、六腑法六律，以应天地阴阳。继而指出“服食五谷不能将节，冷热咸苦更相抵触，共为攻击，变成疾病”，说明饮食失节、冷热偏胜是致病之由；又强调“问而知之，别病深浅”，脉诊须合问诊，全段未出具体脉象，故脉象取空。", []], "21286": ["预后", "本段论理病先察其源、候其病机。以“五脏未虚，六腑未竭，血脉未乱，精神未散”为可治之据，服药必活；若“病已成”则仅得半愈，“病势已过”则命将难全。文中“未虚”“未乱”正是从反面提示虚与乱为病进之象，脉未乱则生机尚存，脉乱则预后不良，故归预后。", ["虚", "乱"]], "21287": ["平脉", "本段论诊候常以平旦，此时“阴气未动，阳气未散，饮食未进，经脉未盛，络脉调均，气血未乱”，故能“精取其脉，知其逆顺”。所述经脉未盛、络脉调均、气血未乱，正是平旦诊脉所见平和之象，为诊脉之常法基准；又分上医听声、中医察色、下医诊脉，强调医未病之病，故归平脉。", []], "21288": ["其他", "此段专论三部九候诊法，非论某病之脉。文中反复言\"两额动脉\"\"两颊动脉\"\"耳前动脉\"，以动脉搏动之处分属头角、口齿、耳目之气，又配手太阴肺、手阳明胸中、手少阴心、足厥阴肝、足少阴肾、足太阴脾，合为九候。其意在明诊脉部位与脏腑气机相应，为辨病机之基础，故不主一病。", ["动"]], "21289": ["预后", "\"形盛脉细，少气不足以息者死\"，形有余而脉细气弱，是形脉相反、气衰不能充脉；\"形瘦脉大，胸中多气者死\"，形不足而脉大，是脉盛于形、气逆于胸。故以形气相得为生，三五不调为病，三部九候相失为死。段末又言火风水土不调致蒸热、强直、浮肿、肢废，正说明脉道失和则病深。", ["细", "大"]], "21290": ["治法", "此段论汤、散、丸三方之用，未及脉象。\"当先以汤荡涤五脏六腑，开通诸脉\"，以汤净万物；风冷湿痹、表里移走者用散逐邪；积聚坚癖者用丸消磨。又戒不须汗而强汗则津液枯竭，须汗不与则毛孔闭塞闷绝，不当下而强下则洞泄不禁，皆示治法当顺病势，不可妄攻妄补。", []], "21291": ["其他", "此段答问，论古今药力与疗病难易之异，未涉脉象。言古者药在土中经久、气味真实，人少欲而禀气中和，故病轻易疗；今时药力轻虚、人多巧诈，感病厚重难医。又责今医但知诊脉处方，不委采药时节、出处土地、新陈虚实，故治十不得五六，强调识药与诊脉并重。", []], "21292": ["治法", "此段论用毒药及服药先后之法，无脉象可录。\"先起如黍粟，病去即止，不去倍之\"，示毒药当渐增以取去为度，不可过剂。又按病位定服药时序：胸膈以上先食后药，心腹以下先药后食，四肢血脉宜空腹旦服，骨髓宜饱满夜服，皆因药力随谷气与部位而行。", []], "21293": ["治法", "此段专论服汤之法，未言脉。分三服而\"一服最须多，次一服渐少，后一服最须少\"，因病人后气力渐微，故汤递减；服补汤则三升半、昼三夜一、中间间食，使\"汤气溉灌百脉\"。又戒服汤不得太缓太急，须左右仰覆卧、室中行百步，令汤势遍行腹中，属服药调护之法。", []], "21294": ["妇人", "此段论妇人别立方之由，未及具体脉象。言妇人\"众阴所集，常与湿居\"，十四以上阴气浮溢，内伤五脏、外损姿颜，月水去留交互、瘀血停凝、中道断绝，恶血内漏致气脉损竭，故比男子十倍难疗。惟四时节气、虚实冷热之病与丈夫同，怀胎挟病则避毒药，示妇人病机重在血与湿。", []], "21295": ["妇人", "此段论妊娠早期胎元变化，无脉象。言阴阳调和、二气相感而有娠，三阴所会多生女；妊娠二月名始膏，精气成于胞里；三月名始胎，\"血脉不流，象形而变，未有定仪，见物而化\"，男女未分，故未满三月可以方术转之。其要在明胎孕初成、血脉未充之机，属妇人胎产之说。", []], "21296": ["妇人", "本条辨妊娠脉。\"脉平而虚\"为乳子之常，非胎脉；\"阴搏阳别\"谓血气和调、阳施阴化，故有子。手少阴脉动甚者，心主血脉，血旺成胎；尺中肾脉按之不绝，胞门子户脉盛，亦为妊娠。三部脉沉浮正等、按之无绝，是阴阳匀平、气血充盛之象，故法妊娠。诸脉皆从气血和调立论，非病脉。", ["虚", "动", "沉", "浮"]], "21297": ["妇人", "本条以左右尺寸脉之浮沉大小辨男女。左疾为男、右疾为女，左手沉实为男、右手浮大为女，尺脉左偏大为男、右偏大为女，皆以左属阳、右属阴，实大属阳、沉细属阴为说。\"来而断绝\"则月水不利，非胎脉。诸法以脉之阴阳偏胜推测男女，属古人经验之谈，其要在辨气血阴阳之偏。", ["沉", "浮", "大", "细"]], "21298": ["妇人", "本条论将产之脉。\"怀妊离经，其脉浮\"，离经指脉离常度，浮为气浮于外、胎气欲动之象；若兼\"腹痛引腰脊\"，则胞宫将开、产期将至。又谓离经者不病，说明此浮非外感之浮，乃妊娠临产气血变动之常脉，故主将产而非病脉。", ["浮"]], "21299": ["妇人", "本条论恶阻。妇人虚羸、血气不足、肾气弱，又当风饮冷，心下有痰水，故病阻。\"脉理顺时平和\"是虽见恶食、愦闷、呕吐，而脉未病，故知欲有娠。经血闭而水渍于脏，脏气不宣，气逆呕吐；血脉不通、经络痞涩则四肢沉重，挟风则头目眩。脉平正是辨妊娠与病阻之关键。", ["平"]], "21300": ["妇人", "本条论妊娠一月养胎。足厥阴肝脉养胎，肝主筋及血，一月之时血行痞涩，故不可针灸其经，当寝必安静、无令恐畏。原文未出脉名，其意在血行痞涩、肝血养胎，故以慎护为要，非以脉断病。", []], "21301": ["妇人", "本条论妊娠二月养胎。足少阳胆脉养胎，胆主精，二月之时儿精成于胞里，故不可针灸其经，当慎护惊动。原文未出脉名，其旨在于二月精成、胆经养胎，慎护以防惊动伤胎，属养胎禁忌而非脉诊。", []], "21302": ["妇人", "本条论妊娠三月养胎。手心主心包脉养胎，内属于心，故不可针灸其经，并无悲哀思虑惊动。原文未出脉名，其要在三月心包养胎，情志波动易扰心神胎气，故以静心慎护为训，非脉象主病之论。", []], "21303": ["妇人", "本条论妊娠三月定形后之变证。有寒则大便青，有热则小便难、不赤则黄；猝惊恐忧愁嗔怒或顿仆，动于经脉，则腹满绕脐苦痛或腰背痛，甚则猝有所下。原文未出脉名，所论为情志跌仆扰动经脉、胎气不安之病机，故宜服雄鸡汤以安胎。", []], "21304": ["妇人", "原文述妊娠四月“始受水精，以成血脉”，以食稻粳鱼雁“盛血气以通耳目而行经络”，全段未及脉象，主旨为妊娠按月养胎的饮食调摄。其病机在于四月血脉初成，血气需充盛以通耳目、行经络，故以饮食补养血气，使血脉充盈、经络通利，属养胎防病之法，非凭脉断病。", []], "21305": ["妇人", "原文言妊娠四月“手少阳脉养”，手少阳内输三焦，四月“儿六腑顺成”，故戒针灸其经，并主张“静形体，和心志，节饮食”。全段无脉象描述，主旨为按月分经养胎：三焦主六腑，四月六腑成形，故养手少阳经，避针灸伤经，以静形和志节食保胎，属妊娠调护之说。", []], "21306": ["妇人", "原文述妊娠五月“足太阴脉养”，足太阴内输于脾，五月“儿四肢皆成”，故不可针灸其经，并戒大饥大饱、食干燥、自炙热、太劳倦。全段未言脉，主旨为按月养胎：脾主四肢，五月四肢成形，故养足太阴脾经，以饮食适中、避免劳倦护脾安胎，属妊娠调摄。", []], "21307": ["妇人", "原文言妊娠六月“足阳明脉养”，足阳明内属于胃，“主其口目”，六月“儿口目皆成”，故不可针灸其经，主张“调五味，食甘美，无大饱”。全段无脉象，主旨为按月分经养胎：胃主口目，六月口目成形，故养足阳明胃经，以调五味、节饮食护胃安胎，属妊娠调护。", []], "21308": ["妇人", "原文述妊娠七月“手太阴脉养”，手太阴内属于肺，“主皮毛”，七月“儿皮毛已成”，故不可针灸其经，戒大言号哭、薄衣洗浴、寒饮。全段未及脉象，主旨为按月养胎：肺主皮毛，七月皮毛成形，故养手太阴肺经，避外寒、护肺气以安胎，属妊娠调摄之说。", []], "21309": ["妇人", "原文述妊娠七月忽受惊恐摇动，腹痛猝有所下，手足厥冷，“脉若伤寒”，烦热腹满短气，颈项腰背强，治以葱白汤。脉若伤寒者，惊恐动胎、气血逆乱，外寒乘虚而入，故脉现寒象；腹痛下血、厥冷为胎动不安之征，烦热腹满短气、项背强为寒郁气逆，主惊恐伤胎兼感寒之证。", []], "21310": ["妇人", "原文言妊娠八月“手阳明脉养”，手阳明内属于大肠，“主九窍”，八月“儿九窍皆成”，故不可针灸其经，戒食燥物、辄失食、忍大起。全段无脉象，主旨为按月分经养胎：大肠主九窍，八月九窍成形，故养手阳明大肠经，以饮食润燥、起居有节护胎，属妊娠调护。", []], "21311": ["妇人", "原文述妊娠九月“足少阴脉养”，足少阴内属于肾，“肾主续缕”，九月“儿脉续缕皆成”，故不可针灸其经，戒处湿冷、著炙衣。全段未言脉，主旨为按月养胎：肾主续缕，九月儿脉续缕成形，故养足少阴肾经，避湿冷、慎衣着以护肾安胎，属妊娠调摄之说。", []], "21312": ["治法", "此段为治水气之方，白茅根、瞿麦、茯苓、鲤鱼齿利水消肿，桃胶活血，人参、地脉补虚。原文未出脉名，仅列药味，故脉象要素为空。方中利水与补虚并用，提示水湿内停兼正气不足之病机，属治法类条文，非脉诊论述。", []], "21313": ["病机", "原文言「百脉沉重」，脉沉而重，主热毒风虚内陷、水湿下注。冬感温风，至春夏化热，热毒与风虚相搏，故头痛、下赤白、不思饮食、头眩心悸、酸𢠹恍惚。脉沉重说明邪郁于里、气血不畅，外有热毒而内兼虚损，属病机分析。", ["沉", "重"]], "21314": ["治法", "此段为治风虚不足、通血脉、补寒冷之方，石斛泽兰丸。原文未出脉象，仅述主治与方名，故脉象要素为空。风虚不足则血脉不通，寒冷内盛，治以补虚通脉温散，属治法类条文，非脉诊内容。", []], "21315": ["病机", "此段论带下五贲之病，列举热病下血、寒热下血、房事血漏、举重伤任脉下血、产后脏开经利五种，总归「外实内虚」。原文未出脉名，脉象要素为空。五贲皆以下血为主，外见实象而内本虚损，属病机论述，说明下血诸证之虚实错杂。", []], "21316": ["治法", "此段为治妇人下血之方，牡丹皮、干地黄、禹余粮、艾叶、龙骨、柏叶、伏龙肝、阿胶、芍药等，凉血止血、固涩补虚并用。原文未出脉名，脉象要素为空。方药提示下血日久、虚实夹杂之病机，属治法类条文，非脉诊论述。", []], "21317": ["妇人", "此段言女人漏下赤白，灸营池四穴三十壮，穴在内踝前后两边池中脉上。原文未出脉名，脉象要素为空。所述为妇人漏下赤白之灸法取穴，属妇人病治疗条文，说明漏下赤白可取内踝脉上穴位施灸，非脉象主病之论。", []], "21318": ["妇人", "此段言女人漏下赤白、四肢酸削，灸漏阴三十壮，穴在内踝下五分微动脚脉上。原文未出脉名，脉象要素为空。漏下赤白兼四肢酸削，提示下血伤正、气血不足，取内踝脉上穴灸之，属妇人病治法条文，非脉诊主病。", []], "21319": ["妇人", "此段言灸内踝下白肉际青脉上，随年壮，承上文治妇人漏下赤白。原文未出脉名，脉象要素为空。取青脉施灸，提示瘀滞或虚寒之病机，属妇人病灸法条文，说明漏下赤白可循脉取穴，非脉象主病之论。", []], "21320": ["小儿", "原文以生后日数定瞳子、任脉、尻骨、掌骨、膑骨、膝骨之成，属小儿发育常期。若不能依期，则'必有不平之处'，指脏腑筋骨发育失序，非脉象所主。此段无脉名，主旨为小儿生长定法及发育迟速之辨，故归小儿类，病机在先天禀赋与养育失宜致骨脉不成。", []], "21321": ["小儿", "原文述小儿变蒸周期，谓'变蒸者，是荣其血脉，改其五脏'，故一变则情态有异。'变者上气，蒸者体热'为变蒸之候，乃血气充荣、五脏更改之生理过程，非病脉。脉象写法虽标'脉乱'，实为蒸时气血涌动之象，非主病之脉，故脉素取空，归小儿变蒸常候。", []], "21322": ["小儿", "此段详列变蒸日数及证候，明言'蒸者甚热而脉乱，汗出是也'。脉乱由蒸时热盛、血气沸腾所致，属变蒸之常，非病机之脉。原文又诫'当其变之日，慎不可妄治之，则加其疾'，强调变蒸不可妄治。故脉素不取，主旨为小儿变蒸证候与治禁，归小儿类。", []], "21323": ["小儿", "原文论初生儿衣着调护，谓'不可令衣过厚，令儿伤皮肤，害血脉'，又谓暖衣则'筋骨缓弱'，宜数见风日使'血凝气刚，肌肉牢密'。此段无脉象，主旨为小儿护养失宜致血脉筋骨受损之病机，以阴地草木为喻，说明厚衣温暖反令肌肤脆软不堪风寒，归小儿养育调护。", []], "21324": ["小儿", "原文述初生儿血脉不敛之候：'血沮败不成肌肉'则面目鼻口悉黄而啼、闭目撮口、口中干燥、四肢不能伸缩，断为'血脉不敛也，喜不育'。此非脉象所主，乃以症候辨血脉未凝之病机，主张急决悬雍血泡并予龙胆汤。主旨为初生儿血脉不敛之危候与救治，归小儿类。", []], "21325": ["病机", "原文以脉浮沉判痫之阴阳：'脉浮者为阳痫，病在六腑，外在肌肤'，故易治；'脉沉者为阴痫，病在五脏，内在骨髓'，故极难治。浮主邪在表、病位浅，沉主邪入里、病位深，此以脉之浮沉定病位浅深与预后善恶。又以身软时醒为痫、强直反张不时醒为痉，皆由脏气不平、风邪所中。", ["浮", "沉"]], "21326": ["小儿", "原文引《神农本草经》言小儿惊痫百二十种，'证候微异于常，便是痫候'。其病机为初出腹血脉不敛、五脏未成，稍将养失宜即病；变蒸后余证可宽，惟'中风最暴卒'。此段无脉象，以证候异常见痫候，主张四肢惊掣、气息小异及变蒸日满不解者与龙胆汤，归小儿惊痫。", []], "21327": ["小儿", "原文论养儿'微惊以长其血脉，但不欲大惊'，大惊则灸惊脉，然五六十日灸反使惊甚，百日后灸乃善。又指出儿有热不欲哺乳、卧不安、数惊，为'痫之初也'，服紫丸下其盛气可令不病痫。此段无脉象，主旨为小儿惊痫先兆之辨与灸法、下法之宜忌，病机在惊热盛气内扰血脉。", []], "21328": ["主病", "原文言“凡小儿有癖，其脉大必发痫”，脉大主邪气盛实，癖积内结，食滞不化，郁而化热生风，故发食痫。脉大反映积滞壅盛，病机为食积化风，主病为食痫，症见发痫，治当早下，下之便愈。", ["大"]], "21329": ["病机", "原文“腹中有疾生，则身寒热，寒热则血脉动”，脉动为气血失和、心不定之象。寒热交争致血脉动，动则心不定，易惊而痫发。脉动主病机为寒热扰动、心神不宁，与惊痫相应。", ["动"]], "21330": ["主病", "原文“脉青大者，寒；脉青细为平也”，青大脉主寒邪内盛，青细为小儿平脉。鱼际脉黑为痫候，赤为热，青大为寒，说明脉色合参以辨寒热痫候，脉大主寒实，细为平和。", ["大", "细"]], "21331": ["主病", "原文“耳后完骨上有青络盛，卧不静，是痫候”，未直接言脉，但青络盛为痫候之外候，反映络脉瘀滞、风动之机。卧不静为神不安，青脉刺之令血出，以泻其邪，主病为痫。", []], "21332": ["预后", "原文列举痫之初候与剧候，强调“见其候，便抓其阳脉所应灸”，并言剧者“非复汤抓所能救，便当时灸之”。虽未明言脉象，但以证候判断预后，初候可治，剧候难疗，主旨在预后判断。", []], "21333": ["治法", "原文“血脉盛实，寒热温壮，四肢惊掣”，脉盛实主邪热壅盛，气血充实，小儿初生胎热内蕴，或客忤鬼气，致惊痫诸症。脉盛实为实证，治以龙胆汤清泻实热，主病机为实热惊风。", ["盛", "实"]], "21334": ["主病", "原文“少小中风，脉浮发热自汗出，项强，鼻鸣，干呕”，脉浮主表证，风邪袭表，营卫不和，故发热自汗出；风邪上扰，项强鼻鸣；干呕为风邪犯胃。脉浮主病机为风邪中表，主病为小儿中风。", ["浮"]], "21335": ["其他", "原文“少小有风痫疾，至长不除，或遇天阴节变便发动”，未言脉象，述风痫反复发作，百脉挛缩，行步不正，言语不便，属痫疾日久，风痰瘀阻络脉，主病机为风痫久羁，络脉不利。", []], "21336": ["小儿", "原文言有噤者“舌下脉急，牙车筋急”，此“脉急”指舌下络脉拘急，非寸口脉象。其病机为河洛关中土地多寒，寒邪客于舌本牙车，筋脉收引而急，故见噤口不开。文旨在于说明南北地气不同，小儿灸颊防噤当因地域而异，不可拘泥古方，否则反害小儿。", ["急"]], "21337": ["误治", "本段未出脉名，主旨在告诫小儿惊啼、眠中四肢掣动、变蒸未解者，慎不可针灸抓之。因小儿脏腑娇嫩，妄加针灸则“动其百脉”，扰动气血，反因惊而成痫。惟阴痫噤痉属寒闭筋急者，方可针灸抓之。此论误治之害，强调辨证施治，不可一概而论。", []], "21338": ["治法", "本段论肾痫灸法，取“肘中动脉”为穴，动脉指肘部搏动处，非脉象主病之动脉。肾痫面黑、直视不摇如尸状，乃肾经气逆、痰浊蒙窍所致。灸心下、肘中动脉及足太阳少阴，意在温通肾经阳气、化痰开窍，属针灸治法，非以脉候病机。", ["动"]], "21339": ["治法", "本段详述小儿目反上视、眸子动的灸法取穴，其中“客主人穴在眉后际动脉是”“耳门当耳开口则骨解开动张陷”，动脉、动均指穴位搏动处或骨节开合动态，非脉象。目反上视、眸子动属肝风内动、痰热上扰之候，灸囟中、客主人、耳门等穴以熄风开窍，为外治取穴之法。", ["动"]], "21340": ["病机", "原文言小儿“血脉嫩弱”，指小儿气血未充、血脉娇嫩之体质特点。秋夏阳气在外，血脉嫩弱，晨夕暴冷易折其阳，阳结则壮热，胃冷则下痢。故夏末秋初小儿多壮热下痢，非尽中客。此以嫩弱之体说明外寒易伤、阳结胃冷之病机，治当先杀毒后下之，慎不可先下。", ["弱"]], "21341": ["主病", "中客忤之病，吐下青黄白色、水谷解离、腹痛、面色变易，其候似痫但眼不上插，脉急数者，乃邪客肠胃、正邪交争、热郁于里之象。急主邪盛拘急，数主热，故脉急数。据此脉症可断为中客忤，宜龙胆汤下之，加人参当归以顾护气血，为辨证主病之要。", ["急", "数"]], "21342": ["其他", "本段未出脉名，“肿脉核如麻豆大”指口中悬雍左右青黑肿起之脉络核块，非寸口脉象。此为中客之邪郁结于口咽，络脉瘀滞而成核。治以针速刺溃去之，或爪摘决之，拭去血，属外治决血之法，旨在去其瘀滞以解客邪。", []], "21343": ["主病", "少小中客，吐下青黄赤白汁、腹中痛、反倒偃侧、喘似痫状但目不上插，脉弦急者，弦主痛主肝，急主邪盛拘急，乃邪客中焦、肝气拘急、正邪交争之象。脉症合参可断为中客，若失时不治则难治，故当及早疗之，为辨证主病并示预后之论。", ["弦", "急"]], "21344": ["病机", "小儿夏月壮热、洞下黄溏、气力惙然，脉极洪数，乃暑热炽盛、热迫大肠之象。洪为热盛气浮，数为热急，极洪数示热势鸱张，故见壮热烧手、下利黄溏而气力衰疲。方中加大黄通腑泄热，正合此热壅之机。", ["洪", "数"]], "21345": ["病机", "暴冷折四肢、热不得泄则壮热，冷气入胃变下痢，脉洪大或急数，为寒束于外、热郁于内，热势奔迫之象。洪大主热盛，急数主热急，故见壮热、小腹胀痛、下痢赤白滞起数去。服之热歇下瘥，即解其郁热。", ["洪", "大", "数", "急"]], "21346": ["病机", "足太阳阳明、手少阳脉动发目病，此以脉动言经气之搏动。原文述五脏六腑精气上注于目，邪中于项因身虚入深，随眼系入脑，引目系急而目眩转。脉动示经气逆乱，与目系急、目眩旋转相应，非言脉形之动。", ["动"]], "21347": ["主病", "本条未出脉名，专述肝热不止冲眼之证：眼眦赤、赤脉息肉痛闭不开、热势彭彭不歇、目睛黄。病机为肝经热邪上冲目窍，热壅血滞则赤脉息肉，热灼则痛闭，热郁则睛黄，与脉象无直接关联。", []], "21348": ["主病", "本条未识脉名，述目热眦赤、赤脉侵睛、息肉急痛、闭不开、如芥在眼碜痛。病机为热邪客于目眦，血热生脉，瘀滞成息肉，故急痛碜涩。全段主症候与病位，未及脉诊，属目病热证之论。", []], "21349": ["治法", "本条未识脉名，述肝劳邪气眼赤之灸法，取当容穴百壮，穴在三阳三阴交会处，按之有上下横脉可验。所谓横脉指局部络脉，非诊脉之脉。主旨为灸治肝劳目赤，属外治之法，故归治法。", []], "21350": ["误治", "本条刺舌下两边大脉出血以治舌病，戒勿刺著舌下中央脉，出血不止则杀人。大脉指舌下粗大之络脉，非寸口脉象。刺大脉出血为治法，然误中中央脉致血出数升，故以烧铁篦熨疮绝血救之，主旨警示误刺之害。", ["大"]], "21351": ["治法", "本条未识脉名，述风齿疼痛灸外踝上高骨前交脉三壮。交脉指穴位所在处脉络交会，非脉象诊断。病机为风邪客于齿龈，取外踝前交脉穴灸之以祛风止痛，属灸法外治，故归治法。", []], "21352": ["其他", "本段为膏方制作工艺，先以水浸猪鹅犬熊脂令血脉尽，再以清酒渍药、铜铛炭火煎膏，绵滤瓷贮，以敷面。全段无脉象描述，亦不涉病机，仅述制药与用法，故脉象要素为空，主旨归入其他。", []], "21353": ["死脉", "原文言脚气缓急，气上入腹、胸胁逆满、肩息，已属危候；更见脉促短而数，兼呕吐不止，则正气衰败、邪气上逆，促短为气竭，数为热迫，胃气上逆故呕，故断为皆死，属死脉之候。", ["促", "短", "数"]], "21354": ["预后", "本段论脚气诊候，强调三部之脉须不违四时者为吉，逆四时者勿治；又据形质黑瘦、肥大肉厚赤白判易治难愈，谓肉软则受疾至深。全段以脉合四时与体质推断预后，未出具体脉名，故脉象要素为空。", []], "21355": ["治法", "原文以脉三品分风毒证治：脉浮大而缓宜续命汤，浮大紧转快宜竹沥汤，脉微而弱因虚而得宜风引汤；浮大而紧快为最恶脉，沉细而快同属恶脉，浮大病在外、沉细病在内。据脉择方，故归治法，脉象取浮大缓紧。", ["浮", "大", "缓", "紧"]], "21356": ["病机", "原文附方后云脉沉细快，风在内者作此汤。沉主病在里，细为气血不足，快即数急，示风邪内入、郁而化热，与前方浮大而紧病在外相对，故以沉细辨风之内外，主风在内之病机。", ["沉", "细"]], "21357": ["治法", "本段仅言治虚损、通顺血脉、极补下气方，属立方施治之语，未载脉象，故脉象要素为空。其治以补虚顺脉下气为法，针对虚损而气血不畅、气逆不降之证，主旨为治法。", []], "21358": ["主病", "原文列风痹、湿痹、周痹、筋痹、脉痹、肌痹、皮痹、骨痹、胞痹各有证候，形如风状，须以脉别之；脉微涩，其证身体不仁。微为阳气虚，涩为血少滞，气血虚滞不荣肌肤，故身体不仁，脉微涩主痹证。", ["微", "涩"]], "21359": ["病机", "原文谓贼风邪气伤阳，客皮肤传入孙脉，孙脉满入络脉，络脉满输大经成病，归六腑为热；其脉坚大为实，实者外坚充满、按之则痛。坚大示邪盛壅实，故主实证病机，与充满拒按之症相应。", ["坚", "大"]], "21360": ["病机", "本段论风邪由肌肤渐入脏腑经络，随所客之处而变生诸症：客肌肤则虚痒成风疹瘙疮，入深与寒热相搏则内枯，客半身入深真气去则偏枯，客关机则挛，入脏则喑哑喉痹舌缓，逐脉流入脏则猝喑缓纵噤痉致死。原文以“风邪入深”“真气去”“风逐脉流入脏”层层说明风邪传变之病机，非论脉象。", []], "21361": ["治法", "本段言目𥆧动、口唇动偏㖞皆因“风入脉”所致，属风邪中于脉络、筋脉失约之候。原文随即给出“急服小续命汤”、以八风散摩神明白膏、丹参膏并“依经针灸”的治法，重在祛风通络、内外合治，故主旨为治法而非脉诊病机。", []], "21362": ["病机", "本段论痹由风寒湿三气并客分肉之间，“迫切而为沫，得寒则聚”致肉裂而痛，痛则神归化热而痛解，痛解则厥而他痹复发，说明痹在分肉、真气不能周之病机。风多则肿为行痹走无常处，寒多则痛痹，湿多则著痹，冷汗濡随血脉上下者为周痹，左右相应者为偏痹。", []], "21363": ["病机", "本段论太阳中风重感寒湿变痉，症见口噤脊强、摇头马鸣、腰反折、汗出如雨。原文指出“新产妇人及金疮血脉虚竭”易得之，脉虚竭正示血脉空虚、筋脉失养而拘急；又言“针耳前动脉”，动脉为风邪搏击之处。虚竭与动脉并见，说明正虚邪中、风动成痉之病机。", ["虚", "动"]], "21364": ["其他", "本段为方药功效叙述，言除风气、通血脉、益精华、定六腑、聪耳明目、悦泽颜色乃至头白更黑、齿落更生，服药百日致神明、房中强壮，并主病在腰膝。全段未涉及脉象与病机分析，属方剂主治与服效记载，故归其他。", []], "21365": ["治法", "本段述猝中恶风、心闷烦毒欲死及久风猝风诸症，如筋急不能行、眼戴睛上插、不能语、不识人、眼反口噤、半身不遂、口噤不言、角弓反张等，皆风邪猝中、筋脉拘急之候。原文以灸法为主，取足大趾横纹、内外踝、目眦后、神庭、曲差等穴，属急灸祛风之治法。", ["动"]], "21366": ["治法", "本段为脾风占候之灸法，症见声不出或上下手，原文依次灸手十指头、人中、大椎、两耳门前脉及两大指节上下各七壮。所述以灸治取穴为主，未言脉象，亦未展开病机推演，主旨在于风邪中脾之灸疗措施，故归治法。", []], "21367": ["病机", "本段从经络立论：脾脉络胃挟咽、连舌本、散舌下，心之别脉系舌本，今心脾二脏受风邪，风阻经络则舌本不利，故“舌强不得语”。原文以经络循行解释舌强不语之由，说明病位在心脾、病性属风邪中络，为病机分析而非脉诊。", []], "21368": ["病机", "原文以“脉动如故”辨尸厥，谓“阳脉下坠，阴脉上争，气闭故也”。脉动如故说明非真死，乃风寒客中、气机闭阻，阴阳升降失常，故见喑不能言、喉痹失音，甚则尸厥。脉动未绝正是气闭而非气绝之征，故可针百会、熨两胁以通阳开闭。", ["动"]], "21369": ["主病", "本段未出脉名，专论“风入脉”所致眼𥆧动、口唇偏㖞、喉痹舌缓，甚则“风入脏，使人喑哑卒死”。其病机为风邪中于经脉，筋脉失养而拘急㖞僻；入脏则脏气闭绝，故卒死。所列灸法、涂药皆从外治风、通经活络立法。", []], "21370": ["治法", "此段仅载灸法，未言脉象。灸“手交脉”三壮、左灸右右灸左，属以灸通阳调脉之法。交脉为手部脉气交会之处，左右互灸意在交通阴阳、畅达经脉，反映古人对脉气阻滞者取灸以温通的治疗思路，故归治法。", []], "21371": ["主病", "本段未识脉名，述“风注入肢体百脉”而身肿、角弓反张、手足酸疼、身体尽痛、耳聋惊悸、短气、二便异常等。病机为风邪深入百脉，气血壅滞、筋脉拘急，兼及五脏虚损，故称“五劳七伤，万病皆治”，属风注百脉、虚实夹杂之候。", []], "21372": ["病机", "原文“脉自微涩，涩在寸口，关上紧”，微涩示营血不足、阳气痹阻，紧为微风外袭。尊荣人骨弱肌肤盛，疲劳汗出被风，血行痹涩而成血痹，形如风状。故宜“针引阳气，令脉和紧去则愈”，脉和紧去即阳通痹解之验。", ["微", "涩", "紧"]], "21373": ["主病", "“脉浮身重汗出恶风”为风湿在表之典型脉症。浮主风邪在表，身重为湿着肌腠，汗出恶风示表虚不固。风湿相搏于表，卫阳不固，故脉浮而见身重汗出恶风，主风湿表虚之证，治当祛风除湿、固表。", ["浮"]], "21374": ["病机", "本段述伤寒一日在皮、二日在肤、三日在肌、四日在胸、五日在腹、六日入胃的传变次第，强调“入胃乃可下”，若热毒在外先下则“热乘虚入胃，即烂胃”。虽段末脉名未全，然以病程浅深定汗吐下之法，主旨为伤寒传变病机与误下之害。", []], "21375": ["误治", "王叔和论阳盛阴虚汗之则死、阳虚阴盛下之则死，引“脉微不可吐”“脉有沉浮转能变化”“脉实大者”以辨虚实。脉微者正气虚不可吐，脉实大者邪盛可攻，沉浮转化示表里进退。若不明此而妄发妄攻，则桂枝下咽阳盛则毙、承气入胃阴盛以亡，故主误治之戒。", ["微", "沉", "浮", "实"]], "21376": ["治法", "原文言“诸病发热恶寒脉浮洪者，便宜发汗”，浮主病在表，洪为热盛气浮，故发热恶寒而脉浮洪，属表热当汗之证。然紧接“其人适失血及大下利，则不可大汗”，示津血亏虚者虽见表脉，亦禁峻汗，否则更伤阴血。全段以脉定汗法宜忌，非专论病机。", ["浮", "洪"]], "21377": ["病机", "风温之病“脉阴阳俱浮”，浮为风热在表，寸尺俱浮示邪热弥漫三焦。汗出体重、息喘、不仁欲眠，皆风热伤卫、壅肺困脾之象。原文列下之小便难、发汗讝语、烧针耳聋、吐下遗矢便利，明误治变证，脉浮为风温在表之机，非单纯表寒。", ["浮"]], "21378": ["治法", "“夫脉浮者，病在外，可发汗，宜桂枝汤”，浮脉主表，邪在肌腠，故当因势利导，以桂枝汤解肌发汗。此以脉浮定病位在外，为可汗之征，与桂枝汤调和营卫法相应，属凭脉立法之例。", ["浮"]], "21379": ["治法", "“脉浮大而数者，亦可发汗，宜桂枝汤”，浮主表，大示热盛，数主热躁，三脉并见为表热较著。虽热象明显，原文仍以桂枝汤发汗解肌，示表证未解时，脉浮大数仍可汗之，非一见数脉即禁汗，当结合表证有无。", ["浮", "大", "数"]], "21380": ["病机", "原文未出脉名，以“常自汗出”论营卫不和。营气和而外不解，是营无病而卫气不和，卫外不固故汗出。营行脉中、卫行脉外，复发其汗以调卫，卫和则愈。此段从汗出机理言营卫失谐，非凭脉断病，故脉象要素为空。", []], "21381": ["误治", "太阳病先汗不解而复下之，“其脉浮者不愈”，浮为邪在外，反下之则引邪入里，故不愈。今脉仍浮，知邪尚在表，当须解表则愈。原文以脉浮为凭，指出下之为误，表证仍在者仍宜桂枝汤解外，属误治后凭脉救逆。", ["浮"]], "21382": ["误治", "桂枝本为解肌，若“脉浮紧，发热无汗”，浮紧为寒邪束表、营阴郁滞之象，无汗则非桂枝汤所宜。原文告诫“勿与之”，恐以解肌之剂误治伤寒表实，反致邪闭。此以脉浮紧辨表实，防桂枝汤误用于无汗之证。", ["浮", "紧"]], "21383": ["病机", "中风“脉阳浮而阴弱”，阳浮者卫气浮盛于外，故热自发；阴弱者营阴不足于内，故汗自出。涩涩恶风、淅淅恶寒、翕翕发热、鼻鸣干呕，皆卫强营弱、风邪袭表之候。脉之浮弱正合营卫不和之机，为桂枝汤证之脉象提纲。", ["浮", "弱"]], "21384": ["主病", "脉浮紧为风寒束表之象。浮主邪在肌表，紧主寒邪收引、营卫凝滞。原文“发热恶寒，身体疼痛，汗不出烦躁”，正合寒邪闭表、卫阳被遏、营阴郁滞之机；无汗则表实，烦躁乃阳郁化热之轻征。故脉浮紧在此主中风伤寒表实证，与恶寒无汗身痛相应。", ["浮", "紧"]], "21385": ["主病", "脉浮大数，浮为邪在阳分，大为热盛气壅，数为热毒炽盛。原文“身重腰背痛，烦闷不安，狂言……面赤斑斑如锦文，咽喉痛，唾脓血”，显系阳毒热毒燔灼营血、上攻咽喉、外发肌肤。脉浮大数正应热毒鸱张、邪未全入里之候，故主阳毒重证。", ["浮", "大", "数"]], "21386": ["主病", "脉沉细紧数，沉细为阴寒内盛、阳气衰微，紧数乃寒凝气滞、毒气攻冲之象。原文“腹中绞痛，咽喉不利，毒气攻心，心下坚强，短气……四肢厥冷”，皆阴毒内结、寒凝血脉、阳气不达之候。脉沉细紧数正合阴毒寒盛阳衰之机，故主阴毒危候。", ["沉", "细", "紧", "数"]], "21387": ["主病", "脉浮为邪在太阳肌表。原文“发热往来，汗出恶风，头项强，鼻鸣干呕”，乃风邪袭表、营卫不和、肺胃气逆之象。汗出恶风示表虚，与浮脉相应，故主太阳中风证，宜桂枝汤解肌调和营卫。脉浮在此点明病位在表、邪未入里。", ["浮"]], "21388": ["误治", "此段论正阳旦汤加减禁忌。原文“若脉浮紧发热者，不可与之”，浮紧为风寒表实、寒邪闭表之脉，而正阳旦汤温补建中，施于表实无汗者恐闭门留寇、助邪碍表。故脉浮紧在此标示表实证，与“虚劳里急”之虚证相对，属禁与温补之列，提示辨证须别虚实。", ["浮", "紧"]], "21389": ["治法", "原文以脉定治法：“脉浮者，宜重服发汗；脉沉实者，宜以𫘝豉丸下之。”浮主邪仍在表，故当发汗解表；沉实主邪已入里、实热内结，故当攻下。同一病三四日不解，凭脉浮沉实以判表里、定汗下，体现脉象指导治法选择，属据脉施治之例。", ["浮", "沉", "实"]], "21390": ["主病", "原文未识别出具体脉名，仅言“脉盛”。脉盛泛指脉来充盛有力，示邪气亢盛、正气未衰。结合“伤寒时气温疫头痛壮热始得一二日”，乃温热疫毒初袭、邪正交争于表之候。脉盛在此提示邪势方张、病属实证，与壮热头痛相应，为早期可汗解之据。", []], "21391": ["病机", "原文“脉势仍数者，阳气犹在经络未入脏腑”，以数脉主热、主阳盛。服前药不瘥而脉势仍数，说明邪热未除、阳气仍郁于经络而未内陷脏腑。数脉在此标示热势未衰、病位尚浅，故治疗仍当清透经络之热，不可遽投攻里，体现凭脉判断邪热浅深之机。", ["数"]], "21392": ["病机", "寸口脉浮而头不痛项不强，知非太阳表邪，乃久痰宿于胸中，气机壅塞，胸阳不布，故胸中硬满、气上冲咽喉不得息。浮脉在此反映病位偏上、正气有驱邪向上之势，痰浊壅盛宜因势利导而吐之，吐后气机通畅则诸症自解。", ["浮"]], "21393": ["病机", "胸上诸寒郁遏，阳气不布故脉迟；寸脉微滑为痰涎内聚之象。寒痰结于胸中，胸阳被阻则郁郁而痛、不能食，涎出、下利日十余行皆痰寒下迫所致。脉迟非虚寒，乃邪阻气机；微滑示有形之痰，故宜吐去胸中寒痰，痰去则利自止。", ["迟", "滑"]], "21394": ["病机", "脉乍结者，邪气阻遏胸中，阳气不能外达四末，故手足逆冷；客气在胸中，气机不利则心下满而烦、饥不能食。结脉乍现，反映邪结而正气尚能抗争，病位在上焦胸中，非虚寒之结，故因势吐之，邪去则脉结与逆冷自除。", ["结"]], "21395": ["病机", "寸脉微浮，头不痛项不强，非表证可知；胸中痞坚、气上冲咽喉不得息，是胸有寒痰壅塞，气逆于上。微浮示病位在上、正气有向上驱邪之势，寒痰阻胸则痞坚，气不得下则冲咽。脉证合参，病在胸中，宜吐以去寒痰，使气机通降。", ["浮", "微"]], "21396": ["其他", "此段仅为篇题及方灸数目标注，未载具体脉象与证候，故脉象要素为空。其内容属篇章体例说明，提示下文脉证方治之数目，不涉病机分析，亦不能据以推断主病，仅作目录性文字看待。", []], "21397": ["病机", "伤寒已解半日许而复心烦热，脉浮数，说明表邪未尽、余热复聚于表，正气仍有驱邪外达之势。浮主病位在表，数主热，故可更发汗以解余邪，宜桂枝汤。文中又诫发汗后饮水必喘，因汗后津伤、饮水停聚上逆，示人慎护。", ["浮", "数"]], "21398": ["病机", "服桂枝汤大汗后脉洪大，是汗出过多、津气外泄，阳气浮盛于外所致，非里热炽盛之洪大。故仍与桂枝汤调和营卫。若形如疟、一日再发、汗出便解，则属表邪微留、营卫不和，宜桂枝二麻黄一汤微汗透邪，此脉洪大当从汗后气浮理解。", ["洪", "大"]], "21399": ["病机", "太阳病反下之，利遂不止而脉促，促为阳气被遏、急促而上，示表邪未解、正气仍欲抗邪外出。表未解则喘而汗出，下利不止为误下伤中、邪热下迫。脉促在此标志表证仍在，不可再下，当先解表，表解则喘汗下利可平。", ["促"]], "21400": ["病机", "脉沉紧主水饮内停。伤寒汗吐下后，心下逆满、气上冲胸、头眩，乃水饮上逆之证。沉为水气在里，紧为寒饮内结，故脉沉紧。若误发汗，则动经伤阳，身为振摇，此阳虚水泛之候。", ["沉", "紧"]], "21401": ["主病", "脉沉紧主结胸热实。伤寒六七日，热邪内陷，与水饮互结，心下痛按之坚，脉沉紧。沉为热入里，紧为邪结实，故宜大陷胸汤峻下热结。", ["沉", "紧"]], "21402": ["误治", "脉浮主表，发热无汗为表实。表不解者不可与白虎汤，恐寒凉伤中，引邪内陷。此条警示白虎汤禁例，脉浮为辨证关键。", ["浮"]], "21403": ["治法", "此段论除热解毒当用苦酸之品，如苦参、青葙、艾、栀子等，热盛非苦酸不解。反对多用辛甘贵价之药，主张就地取材，及时治疗。未涉脉象，故脉象要素为空。", []], "21404": ["预后", "脉沉迟主阳虚阴盛。大下后手足厥逆、下部脉不至，为阳气衰微；咽喉不利、唾脓血、泄利不止，乃上热下寒、阴阳格拒之危候，故为难治。", ["沉", "迟"]], "21405": ["其他", "此段论病新瘥后饮食起居调护，强调静卧节食、勿劳心劳力，尤禁房事。华佗视脉言阳气不足，女劳则死，示瘥后正虚未复，犯禁可致劳复危候。未出具体脉象，故脉象要素为空。", []], "21406": ["主病", "脉实主食积内停。大饱不消、劳复而脉实，为宿食化热、腑气壅实之象，故治当消导攻下，脉实为辨证眼目。", ["实"]], "21407": ["妇人", "妇人温病瘥后未复，血脉未和而交接受病，名阴易。脉缓弱主血气虚，骨髓竭，故气力转少、著床不能动摇。此段专论妇人瘥后交接受邪之危候，脉缓弱示正虚。", ["缓", "弱"]], "21408": ["病机", "百合病身形如和而脉微数，微为气虚，数为有热，乃伤寒虚劳大病后阴液耗伤、虚热内扰之象。原文谓\"百脉一宗悉致病\"，故见意欲食复不能食、如寒无寒如热无热、默默欲卧不得眠、口苦小便赤涩等神志恍惚之候，脉微数正合阴虚内热、百脉失和之病机。", ["微", "数"]], "21409": ["病机", "其人脉数而无热微烦、默默欲卧汗出，数为热，然外无大热，是热郁血分。初得三四日目赤如鸠眼，七八日四眦黄黑，为热毒蕴结于血、蓄积成脓之征。能食者胃气尚强，脓已成也。脉数在此示血分郁热、热毒酿脓之病机，与目赤眦黄黑相应。", ["数"]], "21410": ["误治", "脉数者不可灸，因火为邪，血散脉中。数脉本主热，误灸则火气虽微内攻有力，因虚逐实使血走脉中，焦骨伤筋血难复，甚则井输益肿、肉腐为痈脓而成火疽。原文\"血散脉中\"\"伤脏则剧\"点明误治之害，故应在泻心以泻火解毒，兼治下痢呕吐肠鸣。", ["数", "散"]], "21411": ["病机", "黄汗身体浮肿发热、汗出不渴、汗沾衣色正黄如柏汁，状如风水而其脉自沉。沉脉主里主水，此因汗出入水中浴，水从汗孔入，水湿内郁营分，湿热交蒸溢于肌表，故汗黄如柏汁而脉沉。脉沉正示水湿内郁、非表证之浮，与浮肿汗黄之候相应。", ["沉"]], "21412": ["治法", "治诸病黄疸宜利其小便，此常法也；然假令脉浮，则病势偏表，当以汗解。浮脉主表，示湿热之邪郁于肌表而未全入里，故因势利导从汗而解，与利小便之常法相对而言。原文以脉浮为凭定汗解之法，体现凭脉施治、表里分消之旨。", ["浮"]], "21413": ["预后", "黄发已久变桃皮色、心下有坚、呕逆不食、小便极赤少、四肢逆冷，脉深沉极微细迟，为阳气衰微、湿毒深陷之危候，故不宜服此方，下之必变啘。若脉小浮出形小见、不甚沉微，则阳气渐复，便可治；脉浮见者黄当明、心下自宽，示病势向外向愈。脉之沉微细迟与浮小，判预后吉凶。", ["沉", "微", "细", "迟"]], "21414": ["病机", "内实热盛发黄如金色，脉浮大滑实紧数，浮为热蒸于外，大滑实紧数为邪热壅盛、内实之象。原文谓发黄多是酒客劳热、食少胃中热或温毒内热，湿热毒邪交蒸而成黄。脉浮大滑实紧数正合内实热盛之病机，与黄如金色之候相应，故治当清泻内实。", ["浮", "大", "滑", "实"]], "21415": ["其他", "本段为急黄热气骨蒸、两目赤脉之方治，原文未识别出脉名，故脉象要素从缺。急黄属热毒炽盛、深入骨髓之重证，热气骨蒸示内热蒸腾，两目赤脉为热毒上攻目络之征。全段主旨在于出方施治，属治法方药范畴，脉象信息不足，不作病机推断。", []], "21416": ["病机", "寸口脉浮缓，浮为风邪外袭，缓为湿痹，风与湿合，瘀热不行，脾色外现而发黄；趺阳紧数，数为热则消谷，紧为寒则食满，寒热相搏，谷气不消，浊气下流，小便不通，热流膀胱，身尽黄，名曰谷疸。尺浮伤肾、趺阳紧伤脾，点明脾肾受困、风寒相搏之病机。", ["浮", "缓", "紧", "数"]], "21417": ["预后", "酒疸误下，久久转为黑疸，目青面黑、大便正黑、皮肤不仁，为瘀血内停之候。其脉浮弱，浮为虚阳上浮，弱为气血不足，说明误下后正气已伤而邪未尽，虽见黑色而微黄，故知非纯黑疸，仍属酒疸下后变证，脉症合参可辨预后。", ["浮", "弱"]], "21418": ["治法", "本段言上腭穴入口内上缝赤白脉处，针三锃，治马黄黄疸及四时等病。原文以赤白络脉为刺灸依据，未及脉象，故脉象要素为空。其主旨在于指出黄疸可循上腭络脉施针，属外治取穴之法，非以脉断病，故归治法。", []], "21419": ["治法", "本段述颞颥穴在眉眼尾中间，上下有来去络脉，针灸之可治四时寒暑所苦之疸气、温病；又挟人中穴火针治马黄黄疸疫通身并黄、语音不转者。原文以络脉为针灸依据，未载具体脉象，主旨为黄疸疫病的外治取穴，故归治法。", []], "21420": ["主病", "疟脉自弦，弦为少阳之象，为疟病主脉。弦数多热，弦迟多寒，弦小紧可下，弦迟可温；紧数可发汗针灸，浮大可吐之瘥，弦数者风发，以饮食消息止之。原文以弦脉为纲，兼数、紧、浮大等辨寒热表里，说明疟邪伏于少阳、寒热往来之病机，并据脉定治法。", ["弦", "数", "紧", "浮"]], "21421": ["病机", "瘅疟因阴气孤绝、阳气独发而脉微，微为阳气衰微、阴气内竭之象。其候少气烦满、手足热欲呕、但热不寒，邪气内藏于心，外舍分肉之间，消烁脱肉。脉微与但热不寒并见，说明阳热独盛而阴液已亏，正气不能鼓脉，故脉象微弱，主瘅疟之病机。", ["微"]], "21422": ["主病", "温疟其脉平无寒时，病六七日但见热，骨节疼烦时呕，朝发暮解、暮发朝解。脉平说明邪不在表里之极，正气未大伤，故脉象如常而无寒候；但热不寒、定时发作，为温疟邪留半表半里、阳热偏盛之征，原文以脉平与但热对举，点明温疟之特征。", ["平"]], "21423": ["治法", "本段论五脏疟及胃疟分经刺法，肝疟刺足厥阴见血，心疟刺手少阴，脾疟刺足太阴，肺疟刺手太阴阳明，肾疟刺足少阴太阳，胃疟刺足太阴阳明横脉出血；又详灸疟取穴、灸壮及艾炷大小。原文以横脉、动脉为刺灸依据，未以脉断病机，主旨为疟病针灸治法。", ["动"]], "21424": ["其他", "本段为《肝脏脉论》篇题，未出具体脉象文字，故脉象要素为空。篇题标示全篇主旨在于论肝脏之脉，即肝脉的常变、主病与预后，属脉学专论之纲目，非直接陈述某一病机或主病，故归入其他。", []], "21425": ["平脉", "原文以“将息得理，则百脉安和”立论，说明调养得宜则脉道安和，为无病之平脉；反之“役用非宜”则生五劳七伤六极。此段总述五脏六腑血脉根源与九窍相应，强调脉安和即脏腑调和之征，为全书立论之平脉总纲，非专主一病。", ["和平"]], "21426": ["平脉", "原文谓肝“其脉弦”，又言春时“其气来濡而弱，宽而虚，故脉为弦”。弦为肝之常体，濡弱宽虚为春生柔和胃气之象，故弦而兼濡弱方为肝之平脉。并诫“濡即不可发汗，弱则不可下”，示濡弱之脉气血不足，汗下须慎，属平脉兼及治禁。", ["弦", "濡", "弱"]], "21427": ["病机", "原文以“春脉如弦”为平，其气“濡弱，轻虚而滑，端直以长”；“实而弦”为太过病在外，令人眩冒癫疾；“不实而微”为不及病在内，令人胸痛引背、两胁胠满。又“盈实而滑如循长竿”曰肝病，“急而益劲如新张弓弦”曰肝死，层层示弦脉失胃气之病机轻重。", ["弦", "濡", "弱", "滑"]], "21428": ["死脉", "原文“真肝脉至内外急，如循刀刃责责然，如按琴瑟弦”，脉来劲急毫无柔和胃气，是肝之真脏脉见，故主死，兼色青白不泽、毛折。又提出“弦多胃少曰肝病，但弦无胃曰死”，以胃气多少判平、病、死，说明弦脉失胃气则脏气败绝。", ["急", "弦"]], "21429": ["预后", "原文论足厥阴肝气绝，“脉弗营则筋缩急”，筋缩引卵与舌，见唇青舌卷、卵缩，为筋先死之候，并推断“庚笃辛死，金胜木也”。此段以脉不营行说明肝绝筋失濡养之病机，属危重预后判断，未出具体脉名，故脉象要素为空。", []], "21430": ["病机", "原文以“脉弦细而长曰平”为肝之常，继而以五行乘克论四时反脉：沉濡而滑为肾乘肝之虚邪易治，浮大而洪为心乘肝之实邪自愈，微涩而短为肺乘肝之贼邪十死不治，大而缓为脾乘肝之微邪即瘥。说明弦细长中兼见他脏脉，即示邪之深浅与预后。", ["弦", "细", "长", "沉"]], "21431": ["主病", "原文“左手关上阴绝者，无肝脉也”，指左关肝脉绝而不见，主癃、遗溺、难言、胁下邪气、善吐等症，并出刺足少阳之治法。此段以肝脉绝于关部说明肝经气血阻绝、疏泄失职之病机，属主病兼治法，原文未出具体脉象字，故脉象要素为空。", []], "21432": ["预后", "原文以“濯濯如倚竿，如琴瑟弦”状肝脉之弦，再至为平，三至为离经病，四至脱精，五至死，六至命尽。脉来弦劲而数，至数递增，说明肝气亢逆、阴精耗竭，由平转病、由病转危，故主预后凶险，非一般主病之脉。", ["弦", "数"]], "21433": ["主病", "本段以肝脉急、缓、大、小、滑、涩分主诸病：急甚为恶言，微急为肥气在胁下如复杯；缓甚呕、微缓水瘕痹；大甚内痈呕衄，微大肝痹缩咳引少腹；小甚多饮、微小消瘅；滑甚颓疝、微滑遗溺；涩甚淡饮、微涩瘛疭筋挛。脉象变化反映肝病寒热虚实不同病机。", ["急", "缓", "大", "小"]], "21434": ["病机", "“搏坚而长”为肝脉太过，主坠堕瘀血在胁下，令人喘逆；“濡而散”为肝脉不及，色泽者主溢饮，因渴暴多饮，水溢肌肤肠胃之外。坚长为实、濡散为虚，一实一虚对举，说明肝病有瘀血与水饮不同病机。", ["坚", "长", "濡", "散"]], "21435": ["病机", "“长而左右弹”形容肝脉弦长劲急，主积气在心下支胠，名曰肝痹。原文明言“得之寒湿，与疝同法”，寒湿凝滞肝经，气血结聚，故见腰痛、足清、头痛。脉长而弹指，正是寒湿积气搏结之象。", ["长", "紧"]], "21436": ["主病", "肝脉“沉之而急，浮之亦然”，说明肝经气血郁滞，内外皆急。主胁痛支满引少腹、小便难、目眩头痛、腰背痛、足寒时癃，女子月事不来或时亡时有。原文指出“得之少时有所堕坠”，瘀血内阻肝经，故脉沉急而诸症丛生。", ["沉", "急"]], "21437": ["治法", "肝病色青、手足拘急、胁下苦满、时眩冒，其脉“弦长”，原文判为“此为可治”。弦长为肝脉本象，病未离经，故可治；继而列防风竹沥汤、秦艽散内服，并按时令刺大敦、行间、曲泉、太冲、中郄，补泻兼施，又灸期门、背第九椎，属治法范畴。", ["弦", "长"]], "21438": ["治法", "本段言邪在肝，两胁中痛、寒中、恶血在内、胻善瘈、节时肿，取行间引胁下，补三里温胃中，取血脉散恶血，取耳间青脉去瘈。虽“脉以散恶血”提示刺血脉以散瘀，但全段主旨在于针灸取穴治法，非单纯脉象主病。", []], "21439": ["病机", "肝主胸中，喘、怒骂，其脉“沉”，胸中窒塞欲人推按，有热鼻窒；肝伤则脱肉、卧口欲张、时时手足青、目瞑、瞳仁痛。脉沉说明肝气郁滞于里，胸阳不展，故见喘骂窒塞；肝伤日久，气血不荣，故脱肉、手足青、目瞑，属肝脏伤所致。", ["沉"]], "21440": ["主病", "肝积脉弦而细，弦为肝之本脉，细乃积块内结、气血不充之象。原文以“两胁下痛，邪气走心下，足胫寒，胁痛引少腹”明肝经气滞、积块内阻，男子积疝、女子瘕淋皆肝经所过为病；身无膏泽、转筋、爪甲枯黑，为肝血不荣筋爪。春瘥秋剧、色青，应肝木旺衰之候，故脉弦细主肝积。", ["弦", "细"]], "21441": ["预后", "肝病当见弦长而急，为肝气实、木气本然之脉；今反短涩，短涩属肺金之象，色又反白，是金来克木，故称“大逆，十死不治”。原文以胸满胁胀、善恚怒叫呼为肝实，身体有热复恶寒、四肢不举为气机逆乱，脉色与证相违，故列死候。", ["弦", "长", "急", "涩"]], "21442": ["病机", "此段不诊脉而察音色，以角音属肝、肝声呼、其志怒，论厥逆少阳则营卫不通、阴阳交杂，阴外阳内相击则寒而虚，虚则猝然喑哑，为厉风入肝。面目青黑、四肢缓弱、遗矢便利，皆肝虚风动之候；“呼而哭，哭而反吟”为金克木，故以音色判吉凶。", []], "21443": ["平脉", "春属木应肝，色青主足少阳脉，言春取络脉分肉，因肝气始生、其气急、风疾而经脉常深、气少不能深入，故取浅层络脉分肉。其脉根本在窍阴之间，应在窗笼之前，即耳前上下动脉以手按之动者，属春时肝气初生之常脉部位，非病脉。", []], "21444": ["其他", "此段专述足少阳胆经循行路径，自目锐眦上头角、下耳后、入缺盆，贯膈络肝属胆、循胁里，下抵绝骨外踝，出小趾次趾之端，合足厥阴为表里。全段为经脉部位之文，未及脉象与病机，故列其他，示胆经与肝经表里相合之通路。", []], "21445": ["病机", "足少阳别络光明主肝生病，实则胆热而厥，阳脉反逆大于寸口一倍，见胸中热、心胁头颔痛、缺盆腋下肿；虚则胆寒而痿躄，阴脉反小于寸口，见胸中寒、少气口苦、身体无膏泽、诸节皆痛。以阳脉大、阴脉小分胆实胆虚，阴阳俱静俱动如引绳俱顿者为病。", ["大", "小"]], "21446": ["主病", "述足厥阴肝经循行及是动、所生病：腰痛不可俯仰、丈夫𤻊疝、妇人少腹肿、嗌干面尘脱色，主肝所生病见胸满呕逆、洞泄狐疝、遗溺闭癃。盛者寸口大一倍于人迎，虚者寸口反小于人迎，以寸口人迎大小辨肝经虚实，脉大为实、脉小为虚。", ["大", "小"]], "21447": ["其他", "此段仅为篇目体例之文，标“脉四条，方十一首，灸法一首”，说明该篇收载脉论四条、方剂十一首、灸法一首，未出具体脉象与病机，故脉象要素为空，列其他类，属文献编次信息而非诊法内容。", []], "21448": ["主病", "原文“左手关上脉阴实者，足厥阴经也”，关部候肝，阴实即肝经邪气壅盛。实脉主邪实，肝气郁而化热，故见“心下坚满，常两胁痛，息忿忿如怒状”，皆肝实热、气机壅滞之候，病位在足厥阴肝经。", ["实"]], "21449": ["主病", "“左手关上脉阴阳俱实”，关部浮沉皆实，示足厥阴与少阳两经俱实。肝胆同病，木旺克土，胃气不降，故“胃胀呕逆，食不消”；实脉主邪盛，此属肝胆俱实、疏泄失职、横逆犯胃之候。", ["实"]], "21450": ["主病", "“左手关上脉阴虚者，足厥阴经也”，关部按之虚软，为肝经阴血不足。肝虚寒则疏泄无力，故“胁下坚、寒热，腹满、不欲饮食，腹胀悒悒不乐”；妇人经血乏源，故“月经不利，腰腹痛”，皆肝虚寒之候。", ["虚"]], "21451": ["主病", "“左手关上脉阴阳俱虚”，关部浮沉皆虚，示厥阴、少阳两经气血俱亏。肝胆虚则神魂失养，故“恍惚，尸厥不知人，妄见，少气不能言，时时自惊”；虚脉主不足，此属肝胆俱虚、神气不守之候。", ["虚"]], "21452": ["病机", "本段论筋极主肝，以“阴气外出则虚”“阳气内发则实”分筋虚、筋实。虚则“善悲，色青苍白见于目下”，实则“善怒，嗌干……胁下痛不能转侧”，皆从肝主筋、肝合筋立论，属病机阐发，非单论脉。", []], "21453": ["兼症", "“胻脉疼急”指小腿经脉拘急疼痛，属筋虚极之兼症。原文述筋不能转、十指爪痛、数转筋，甚则“舌卷唇青，引卵缩”，皆因交接过度或病后伤气、内筋绝所致，脉急为筋脉失养拘挛之象。", ["急"]], "21454": ["其他", "此段仅为“胆腑脉论第一”篇题，无脉象描述与病机论述，故脉象要素为空。其主旨为胆腑脉法篇目之标目，不涉具体主病、病机内容，归入其他。", []], "21455": ["病机", "本段论胆腑形态功能，谓胆“中清之腑”“号将军”，与肝合气，属奇恒之腑“藏而不泻”，与胃、大肠等传化之腑“泻而不藏”相对。全段无脉象描述，旨在阐发胆腑藏精汁、主决断之生理，属病机基础论述。", []], "21456": ["病机", "原文以「左手关上阳绝」「阳实」分述胆病虚实。阳绝即无胆脉，胆气不足则决断失职，故善畏如见鬼、多惊少力，胆经循膝，故膝疼口苦；阳实为胆实，气机壅滞则腹中不安、身躯习习。此段以关上脉之绝实辨胆之虚实病机，非具体脉象描述。", []], "21457": ["病机", "原文言胆病善太息、口苦呕宿汁、心澹澹恐如人将捕，又言「邪在胆，逆在胃」，胆液泄则口苦，胃气逆则呕苦汁，故称呕胆。此段从胆胃气逆论病机，并及「脉之陷下者灸之」，以脉陷下示经气不足，非具体脉象主病。", []], "21458": ["病机", "原文述足少阳经脉是动、所生病，口苦善太息、心胁痛不能反侧、面微尘、身无膏泽、足外反热为阳厥，主骨所生病。末以「人迎大一倍于寸口」为盛、「人迎反小于寸口」为虚，从人迎寸口对比辨少阳经虚实，属经脉病机而非具体脉象。", []], "21459": ["其他", "此段仅为篇目体例文字，标举「脉二首方九首灸法二首」，提示该篇含脉论、方剂与灸法条目，未载具体脉象与病机内容，故无可分析之脉证，归为其他。", []], "21460": ["主病", "原文以「左手关上脉阳实」候足少阳胆经，阳实即胆经邪气壅盛。胆实热则气机不畅，故腹中气满、饮食不下；胆火上炎则咽干头痛；少阳不和则洒洒恶寒、胁痛。脉实主邪盛，与胆实热诸症相应，名曰胆实热。", ["实"]], "21461": ["主病", "原文以「左手关上脉阳虚」候足少阳胆经，阳虚即胆经阳气不足。胆虚寒则清阳不升，故眩厥、目黄、䀮䀮失精；筋脉失养则足趾不能摇、躄不能起、僵仆。脉虚主正气不足，与胆虚寒诸症相应，名曰胆虚寒。", ["虚"]], "21462": ["病机", "原文论五劳七伤八风十二痹伤中六极，分气极、肺极、脉极、筋极、骨极、肉极，各述多寒痹腹痛、心下坚有积聚、颜色苦青恍惚失气、拘挛骨节疼痛、肢节厥逆浮肿如水病状等。末言「此皆六极七伤所致，非独房室之为也」，明虚损成极之病机，非脉象主病。", []], "21463": ["预后", "原文论吐血三因，伤胃者因饮食大饱、胃中冷不能消化，强呕致胃口伤裂，血鲜正赤、腹绞痛自汗。脉紧而数，紧主胃中冷积、气逆上冲，数主热迫血行，寒热错杂、正虚邪盛，故「为难治也」，属以脉判断吐血预后。", ["紧", "数"]], "21464": ["病机", "脉大来迟，大则形气有余，迟则主寒主积。原文以“腹不满自言满”辨其非实热，乃气机壅滞、虚寒内结之象，故曰“为无热”。脉大非热盛，迟非邪实，故治疗“但依方不须有所增加”，不可妄加大黄、黄芩苦寒之品，紧扣脉症合参以断有无热邪。", ["大", "迟"]], "21465": ["治法", "此段详述服药法度，非专论脉。文中“脉急者”一语提示里急、药力攻冲之象，故强调以粥和缓药性、平旦空心服、以知为度。脉急示邪正相争、药势峻烈，故“勿更加之”“非理加增，必大吐利”，戒过剂伤正，体现以脉急为度、中病即止的用药思想。", ["急"]], "21466": ["其他", "本段仅为“心脏脉论第一”篇题，未出具体脉象文字，故脉象要素为空。其主旨在于标立心脏脉论篇目，统摄下文心脉诸条，属篇章分类之目，非论具体病机，故归入其他，不作脉理发挥。", []], "21467": ["病机", "此论心主神、为帝王之官，夏旺属火。脉洪、洪大而长、浮有表无里，皆心火用事之象：洪大为火盛，长为气旺，浮则心气外浮而里不足。原文“心气虚则悲不已”点明火虚神怯之机，故脉象虽见洪大，须辨虚实，火盛则洪，火虚则浮散无根。", ["洪", "大", "长", "浮"]], "21468": ["病机", "夏脉如钩，其气来盛去衰为平。来盛去亦盛为太过，病在外，令人身热肤痛浸淫；来不盛去反盛为不及，病在内，令人烦心、咳唾、气泄。原文以“来盛去衰”定钩脉之常，以来去盛衰辨太过不及，说明心火亢盛则外热，心气不足则内烦上咳下泄。", []], "21469": ["预后", "心脉平者累累如连珠、如循琅玕，柔和流利；病脉则“喘喘连属，其中微曲”，喘促不宁、曲而不舒，示心气失调、胃气渐少；死脉“前曲后居如操带钩”，曲居无胃，坚劲失和。原文以连珠、微曲、带钩三层递进，辨平、病、死之预后。", ["喘", "曲"]], "21470": ["死脉", "真心脉至坚而搏，如循薏苡子累累然，坚劲弹指、全无胃气柔和之象，故为真脏脉见。原文兼察“色赤黑不泽，毛折乃死”，色不泽、毛折示精气败绝。又以钩多胃少为心病、但钩无胃为死，说明脉须以胃气为本，坚搏无胃即死候。", ["坚", "搏"]], "21471": ["病机", "此段论情志伤神之病机，未出具体脉象。心藏脉、脉舍神，怵惕思虑则伤神，神伤则恐惧自失、破䐃脱肉、毛悴色夭，死于冬。原文以神伤致形损、色夭，说明心脉失养、神气耗散之机，属七情内伤、由神及形之病变。", []], "21472": ["病机", "原文言“手少阴气绝，则脉不通”，脉不通则血不流，血不流则发色不泽，面黑如漆柴，此血先死之候。心主血脉，气绝则脉道不通，血行停滞，故面色黑如漆柴。壬笃癸死，水胜火也，乃心火受水克之危候。", []], "21473": ["预后", "夏心火旺，其脉浮大而散曰平，此平脉之象。若心死脏，浮之实如豆麻击手，按之益躁疾者死。又论四时相乘之脉：弦细而长为肝乘心，大而缓为脾乘心，沉濡而滑为肾乘心，微涩而短为肺乘心，以五行生克判预后吉凶。", ["浮", "大", "散"]], "21474": ["主病", "左手关前寸口阴绝者，无心脉也，症见心下热痛、掌中热、善呕、口中伤烂，刺手少阳治阳。阴实者心实也，心下有水气，忧恚发之，刺手心主治阴。此以寸口脉之绝实辨心之虚实，绝则心脉虚，实则水气忧恚为病。", []], "21475": ["平脉", "心脉来累累如贯珠滑利，此平脉之象。再至曰平，三至曰离经病，四至脱精，五至死，六至命尽。以至数多少判平病生死，滑利如贯珠为心脉之常，至数增多则病进，甚则危殆。", ["滑"]], "21476": ["兼症", "心脉急甚为瘛疭，微急为心痛引背、食不下；缓甚为狂笑，微缓为伏梁；大甚为喉介，微大为心痹引背；小甚为善哕，微小为消瘅；滑甚为善渴，微滑为心疝；涩甚为喑，微涩为血溢维厥耳鸣癫疾。此以脉之急缓大小滑涩分主心之诸症。", ["急", "缓", "大", "小"]], "21477": ["主病", "心脉搏坚而长，当病舌卷不能言，此心脉太过，邪热壅盛，舌本不利。其濡而散者，当病消渴自已，濡散为心脉不足，气阴两伤，然病可自愈。坚长为实，濡散为虚，虚实异治。", ["坚", "长", "濡", "散"]], "21478": ["病机", "赤脉之至也喘而坚，诊曰有积气在中，时害于食，名心痹。得之外疾思虑而心虚，故邪从之。喘而坚为心脉太过，积气内结，心气不畅，故食害。思虑伤心，心虚则邪乘，此心痹之病机。", ["坚"]], "21479": ["主病", "心脉沉之小而紧，浮之不喘，苦心下聚气而痛，食不下，喜咽唾，时手足热烦满，时忘不乐，喜太息，得之忧思。沉小紧为心脉郁结，气聚心下，故痛而食不下；忧思气结，故善忘不乐、喜太息。", ["沉", "小", "紧"]], "21480": ["主病", "脉实大而数，为心经实热之象。实大主邪气盛，数主热，心热炽盛故见心痛短气、手掌烦热、面赤身热，甚则啼笑骂詈、悲思愁虑。此脉与症相符，邪实而正未大虚，故曰“可治”，宜刺心包经穴及灸巨阙、背第五椎以泻热安神。", ["实", "大", "数"]], "21481": ["病机", "心中寒者，寒邪客于心胸，阳气被遏，故病心如啖蒜齑状，剧则心痛彻背、背痛彻心。脉浮为邪在上焦、病位偏表，正气有驱邪外出之势，故“自吐乃愈”，吐则寒邪随越，气机得通。此脉浮非表证，乃病位在上、邪欲外解之机。", ["浮"]], "21482": ["病机", "心伤由劳倦所致，心气受损，虚阳上浮则头面赤，下焦失固则下重，心脉不畅故心中痛彻背，自烦发热，脐跳手为心气虚而肾水欲上乘。脉弦为心脉之变，弦主痛、主虚劳，此心脏伤而脉失柔和，故曰“心脏伤所致也”。", ["弦"]], "21483": ["病机", "脉短而微，为血气少、心气虚之征。短主气不足，微主阳虚，心气虚则畏怯、合目欲眠、梦远行而精神离散，魂魄妄行。阴气衰则癫，阳气衰则狂，五脏空虚则魂魄飞扬。此脉短微正应其脏不足，故魂魄不安，涕泣自出。", ["短", "微"]], "21484": ["主病", "心脉急，名曰心疝。急脉主拘急疼痛，心为牡脏，小肠为之使，心脉急则小肠气滞，故小腹当有形。此以脉急测知心疝，病位在心与小肠，气机挛急，故小腹出现有形包块，为疝气之征。", ["急"]], "21485": ["预后", "心病烦闷、少气大热、呕咳吐逆、狂语、汗出如珠、身体厥冷，脉当浮，今反沉濡而滑，色当赤而反黑，此为水克火之逆。沉濡滑为水气之脉，黑为水色，水气太过而克心火，木逆乘之，故曰“十死不治”，示预后极恶。", ["浮", "沉", "濡", "滑"]], "21486": ["其他", "此段论心之形态与色脉相应，赤如鸡冠者吉，火形之人耐春夏不耐秋冬。𩩲骭长短倾正与心相应，心小则邪弗能伤而易伤以忧，心大则虚而寒，心高则实而热，心下则脏外易伤于寒。纯以形色推论心之禀赋与发病倾向，未及具体脉象。", []], "21487": ["治法", "夏火心脉色赤，主手太阳。夏者火始治，心气始长，脉瘦气弱，阳气留溢，热熏分腠内至于经，故取盛经分腠绝肤而病去，邪居浅也。脉瘦气弱应夏初心气未盛之象，治当浅刺阳脉以泄分腠之热，使邪从表解。", ["瘦", "弱"]], "21488": ["病机", "原文述手太阳小肠经之脉根于少泽、应于命门，强调脉气有根有应。脉本在外踝之后而应在命门之上三寸，说明经脉之气自手小指端发出，贯脊上达心膈，与心相联系。此段非论脉形，而在明经脉根结与脏腑相应之理，故脉象要素为空，主旨归病机。", []], "21489": ["病机", "原文详述手太阳小肠经脉循行，起于小指之端，循手外侧上腕出踝，绕肩胛入缺盆络心属小肠，其支至目锐眦入耳中。此段以经脉走向说明小肠与心为表里、与手少阴同会于手太阴，脉气贯通上肢头面。非辨脉形，故脉象要素为空，主旨属经脉病机。", []], "21490": ["病机", "原文以手太阳别络支正主心生病，实则以阳脉大反逆于寸口再倍，主小肠热、节弛、嗌痛颔肿耳聋目黄；虚则阴脉反小于寸口过于一倍，主短气、百节病、筋急颈痛。脉大示阳热实邪逆盛，脉小示经气虚衰，大小对比正分虚实两端，故归病机。", ["大", "小"]], "21491": ["病机", "原文述手心主包络脉循行及是动病，见手心热、肘臂挛急、胸胁支满、心中澹澹大动、面赤目黄、善笑不休。以寸口与人迎比较定虚实：盛则寸口大一倍于人迎，虚则寸口反小于人迎。脉大示心包热盛，脉小示经气虚，盛泻虚补，故主旨为病机。", ["大", "小"]], "21492": ["病机", "原文述手少阴心脉循行及是动所生病，见咽干心痛、渴而欲饮、目黄胁满痛、臑臂内后廉痛、掌中热痛。以寸口与人迎对比辨虚实：盛则寸口大再倍于人迎，虚则寸口反小于人迎。脉大主心经实热，脉小主心经虚衰，盛泻虚补，故归病机。", ["大", "小"]], "21493": ["病机", "原文设问手少阴独无输，答以心为五脏六腑之大主、精神所舍，其脏坚固邪不能容，容之则神去身死，故诸邪在心皆在心包络。指出外经腑病而脏不病，独取掌后锐骨之端。此段论心不受邪、病在包络之机理，非脉形描述，脉象要素为空，主旨属病机。", []], "21494": ["病机", "原文论夏三月心小肠赤脉㩌病，源从少阴太阳之气相搏而停，营卫不通则皮肉痛起，淫邪之气因时而作。腑虚则阴邪所伤，身战脉掉捉所不禁；脏实则为阳毒所侵，肉热口开舌破咽塞声嘶。此段以时令脏腑虚实论疫病机，未出具体脉形，故脉象要素为空。", []], "21495": ["其他", "原文仅为篇题残文，标目「脉四条方十一首灸法一首」，提示该篇含脉论四条、方十一首、灸法一首，属目录性文字，未载具体脉象与病机。既无脉形可辨，亦无证候可析，故脉象要素为空，主旨归其他。", []], "21496": ["病机", "原文以「左手寸口人迎以前脉阴实」定位手少阴心经，阴实即心经邪气壅盛。实脉主邪实有余，心实热则气机壅滞，故见大便不利、腹满；热郁四肢则重，热蒸于外则身热。脉实与心实热诸症相应，属邪热内实之病机。", ["实"]], "21497": ["病机", "原文「脉阴虚者，手少阴经也」，阴虚即心经气血不足。虚脉主正气亏虚，心气虚则神不守舍，故悸恐不乐、恍惚；心脉失养、寒凝气机则心腹痛难以言、心如寒。脉虚与心虚寒诸症相应，属心气阳不足之病机。", ["虚"]], "21498": ["病机", "原文「脉阴阳俱虚」指手少阴心与巨阳小肠经气俱虚。虚脉主脏腑气衰，心阳不足则寒少气、四肢厥；小肠虚寒不能泌别则洞泄、肠澼。脉阴阳俱虚与心小肠俱虚之洞泄、厥冷相应，属表里阳气俱衰之病机。", ["虚"]], "21499": ["其他", "本段仅存篇题「脉极第四」，无脉象描述与症候文字，无法据以分析具体病机。脉极当指脉气耗极之候，然原文未出脉形、未列主病，故脉象要素为空，仅能判定为篇目性文字，不作病机推断。", []], "21500": ["病机", "原文「其脉空虚」为脉痹内舍于心之候，虚示心血不足，故饮食不为肌肤、脱血色白不泽。又分「脉气实则热」「脉气虚则寒」：实热则好怒、口赤、言语不快；虚寒则咳、心痛、咽肿喉痹。以虚实两途明心风之候，脉之虚实即心之寒热病机。", ["虚", "实"]], "21501": ["治法", "本段为「治脉热极」之方治，原文述血色脱、色白干燥不泽、饮食不为肌肤，皆热极伤血脉、耗营血之候。文中所出为「消热止极强胃气方」，属针对脉热极的治法，未直接描述脉形，故脉象要素为空，主旨归于治法。", []], "21502": ["其他", "本段仅存篇题「脉虚实第五」，无脉象描述及症候正文，不能据以分析具体病机。篇题提示所论为脉之虚实，然原文未出脉形与主病，故脉象要素为空，仅作篇目性文字处理，不臆测病机。", []], "21503": ["病机", "原文「脉虚者好惊跳不定，脉实者洪满」，虚主心气不足而神动，实洪主心火有余而脉道满溢。又言「脉虚实之应主于心小肠」，以热应脏、寒应腑分属。脉之虚实洪满与心小肠寒热病机相应，明脏腑虚实各有所主。", ["虚", "实", "洪"]], "21504": ["病机", "脉虚而惊跳不定、乍来乍去，是正气不足、小肠腑寒，心气浮越不能自持之象。虚脉主气血亏乏，鼓动无力，故脉来去无常；惊跳不定说明寒邪扰及心神，心与小肠相表里，腑寒则心气不宁。治以补虚调中，正合虚寒之机，非实邪所致。", ["虚"]], "21505": ["主病", "脉实洪满，实为邪气盛，洪为火热燔灼、气血涌盛，满则脉体充盈。心属火，热邪内盛则脉道充盈而洪实，故主心热病。此脉与心热相应，热盛于内、气血壅盛，治当清泄心火，与后文调心泄热之法一脉相承。", ["实", "洪"]], "21506": ["病机", "心脉厥大，厥者逆也，大则邪气壅盛。心脉当微而反厥大，是心经热邪逆盛，波及相表里之小肠，故寸口见小肠热象，症见齿龋嗌痛。齿属阳明、咽嗌近心，热循经上攻则痛。治以调心泄热，使心火降而小肠之热自解。", ["大"]], "21507": ["治法", "原文未出具体脉名，仅言脉不出则针不容穴，属以脉定治之法。脉不出提示气血痹阻、经气不通，故取幽门两旁之不容以通调，又灸巨阙治心闷痛、上气牵引小肠。此为脉症合参、针灸并施，非单纯论脉，故归治法。", []], "21508": ["病机", "阳微阴弦，即寸口阳脉微、尺中阴脉弦。阳微为上焦阳虚，阴弦为阴寒内盛，寒邪乘虚上逆，痹阻胸阳，故胸痹而痛。原文责其极虚，又言阳虚在上焦，正说明本虚标实：虚为病之本，阴弦为寒凝之标，故胸痹心痛由此而生。", ["弦", "微"]], "21509": ["兼症", "寸脉沉而迟，沉主里、迟主寒，是上焦阳气不振、寒饮内停；关上小紧数，紧为寒凝、数为阳郁，寒饮阻遏胸阳，气机不利。故见胸痹喘息咳唾、胸背痛短气。脉症合参，本段以脉象带出胸痹兼症，属兼症论述。", ["沉", "迟", "紧", "数"]], "21510": ["病机", "脉极虚寒，虚为气血不足，寒为阳气衰微，精血不能上荣，故须发落堕。发为血之余，阳气虚寒则血不生、发不润。治令发润泽，当温补气血、扶阳散寒，使精血上奉。此段以脉虚寒点明须发脱落之病机根本在阳气精血亏虚。", ["虚", "寒"]], "21511": ["其他", "本段仅为篇题小肠腑脉论第一，未出具体脉象与症候，属篇章标目，无脉可析、无病机可论。按体例归入其他，不作脉象与病机推断，以免附会原文所无。", []], "21512": ["主病", "原文指出小肠病可见小腹痛、腰脊控睪而痛、耳前热等症，若脉滑则为其候。滑脉主实热，此处提示小肠有热或邪实内蕴，气血壅滞，故见腹痛牵引腰脊及耳前热等症。脉滑与小肠病候相应，说明病机为邪热内结、气血不畅。", ["滑"]], "21513": ["病机", "左手关前寸口阳绝者，无小肠脉也，即小肠经脉气断绝。苦脐痹、小腹中有疝瘕、月即冷上抢心，皆因小肠阳气虚衰，寒凝气滞，故见脐腹痹痛、疝瘕及冷气上逆抢心。此段论小肠脉绝之病机，属阳虚寒盛、经脉失养。", []], "21514": ["病机", "原文以皮之厚薄缓急及脉之厚薄缓小、纡屈来推断小肠之厚薄长短结。脉厚则小肠厚，脉薄则小肠薄，脉缓则小肠大而长，脉冲小则小肠小而短，诸阳经脉多纡屈则小肠结。此以脉象测脏腑形态，说明脉与小肠相应，脉象变化反映小肠结构及功能状态。", ["厚", "薄", "缓", "小"]], "21515": ["病机", "手太阳之脉是动则咽肿痛、颔肿不可以顾、肩似拔、臑似折，是主液所生病者，耳聋目黄、颊颔肿、项肩臑肘臂外后廉痛。此段述手太阳小肠经经脉病候，病机为经脉气血阻滞，经气不利，故循经部位肿痛，并影响液所生病。", []], "21516": ["其他", "此段仅为篇目提示，列脉二首、方三首、灸法二首，无具体脉象与病机论述，故脉象要素为空，主旨归为其他。", []], "21517": ["主病", "左手寸口人迎以前脉阳实者，手太阳经也，病苦身热、来去汗不出、心中烦满、身重、口中生疮，名曰小肠实热。阳实脉主邪热壅盛，小肠实热内结，故见身热无汗、心烦满、口疮等症。脉实与实热病机相应。", ["实"]], "21518": ["主病", "左手寸口人迎以前脉阳虚者，手太阳经也，病苦颅际偏头痛、耳颊痛，名曰小肠虚寒。阳虚脉主阳气不足，小肠虚寒，清阳不升，寒凝经脉，故见偏头痛、耳颊痛。脉虚与虚寒病机相应。", ["虚"]], "21519": ["病机", "此段论舌为心主、小肠之候，五味偏嗜则舌脉凝、舌皮槁、舌筋急、舌肉肥、舌根痛等，并指出脏热则舌生疮引唇揭赤，腑寒则舌本缩、口噤唇青，治宜寒补热泻。虽未明言脉象，但舌脉凝等描述反映五味伤及脏腑气血之病机。", []], "21520": ["病机", "原文论癫疾由母孕时大惊，气上不下，精气并居所致。病在诸阳脉则寒热发狂，刺之虚脉，指泻其邪使脉虚。脉虚反映邪去正安之机，非主虚证。癫疾初发先不乐、头重直视，为阳郁神乱之候，与脉虚相应者，示邪有外泄之势。", ["虚"]], "21521": ["主病", "筋癫疾者身拳挛急，脉大。脉大主邪盛气逆，筋脉拘急，气血壅滞于筋。大脉为阳邪亢盛之象，与身拳挛急相应。若呕多涎沫、气下泄，则脾胃气败，故不疗。脉大在此示邪实正未大虚，然见呕涎气泄则预后不良。", ["大"]], "21522": ["主病", "脉癫疾者暴仆，四肢之脉皆胀而从满脉尽，刺之出血。此段未出具体脉名，然四肢脉胀满，为气血壅逆于经脉之象。暴仆乃气逆上冲、神明失守所致。脉胀满与暴仆相应，示邪闭经脉，刺血以泻其壅。若呕多涎沫、气下泄，则脏气衰败，故不疗。", []], "21523": ["预后", "癫疾脉搏大滑，久自已，大滑为阳邪渐衰、气血尚和之象，故可自愈。脉沉小急实，则邪深入阴，正气被遏，故死不疗。小牢急亦不可治，牢急示邪坚正败。脉虚可疗，虚为邪去正复之机；实则死，实为邪盛正绝。此以脉之虚实大小判癫疾吉凶。", ["大", "滑", "沉", "小"]], "21524": ["病机", "此段论厥之寒热，阳气衰于下则寒厥，阴气衰于下则热厥。热厥起于足下，阳盛则足下热；寒厥起于五趾至膝，阴盛则内寒。厥或腹满、暴不知人，由阴气盛于上则下虚，下虚则腹满，气逆则阳气乱。巨阳之厥则肿首头重、足不能行、发为眴仆。全段未出脉名，主述厥病病机。", []], "21525": ["其他", "此段分癫病为五：阳癫、阴癫、风癫、湿癫、马癫。风癫由热汗出当风、房室过度、醉饮饱满行事，令心气逼迫短气脉悸得之。脉悸为心气被迫、心神不宁之候，非脉象本身。湿癫由热沐发湿结脑得之。全段未出具体脉名，主述五癫成因与证候。", []], "21526": ["治法", "此段述大人癫、小儿惊痫之灸法，取背第二椎及下穷骨、脊骨上、阴茎上宛宛中、足大趾聚毛中、囊下缝、乳头、督脉、天窗百会、耳上发际等穴。全段为灸治癫疾惊痫之具体取穴法，未涉及脉象，故脉象要素为空。", []], "21527": ["治法", "此段引扁鹊论百邪所病针有十三穴，从鬼宫起，次鬼信、鬼垒、鬼心等，述各穴部位与针刺深浅。若邪蛊之精便自言说，男左女右起针，数处不言则遍穴针之。全段为针治邪病之具体穴位与手法，未出脉象，故脉象要素为空。", []], "21528": ["治法", "本段为灸法治疗狂痫癫疾诸症，取穴多依据动脉搏动处，如河口穴在腕后陷中动脉是。动脉主惊、主痛，狂痫乃神志逆乱、痰火扰心所致，灸百会、天窗等穴以通阳开窍、涤痰宁神，故动脉在此提示病位在心神，与狂言恍惚、掣疭等症相应。", ["动"]], "21529": ["其他", "本段仅标目「脾脏脉论第一」，未出具体脉象与病机文字，故脉象要素为空。从篇题可知其主旨为论述脾脏平脉、病脉及死脉，属脉学专论之纲目，无具体脉症可析，故归入其他类。", []], "21530": ["病机", "本段论脾藏意、主肌肉、裹血温五脏，脉缓为脾之平脉，缓而和柔则脾气健运；若脉伏而沉，则脾阳不振、湿浊内困，与「脾气虚则四肢不用」相应。脉缓主常，伏沉主病，提示脾病多因气虚湿滞，故以脉象统论脾之生理病理。", ["缓", "伏", "沉"]], "21531": ["预后", "本段以脉象判脾之平、病、死。脉来和柔相离如鸡践地曰平，胃气存也；实而盈数如鸡举足曰脾病，邪气实也；坚锐如鸡之喙、如屋之漏、如水之流曰脾死，真脏脉见、胃气竭也；弱而乍疏乍散亦为死候。脉之坚锐与弱散，皆示脾气败绝，故主死。", ["实", "数", "坚", "弱"]], "21532": ["主病", "本段以右手关上脉之阴绝、阴实辨脾病。阴绝者无脾脉，主少气下利、腹满身重、四肢不欲动、善呕，乃脾气虚衰、运化失职；阴实者脾实，主肠中伏伏如坚状、大便难，乃脾实气滞、腑气不通。虽未明写脉象，然以「绝」「实」示脉之虚实，故归主病。", []], "21533": ["平脉", "本段论脾之平脉为「长长而弱，来疏去穊」，长而弱乃脾土柔和之象，再至曰平，三至曰离经病，四至脱精，五至死，六至命尽。以至数分平、病、死，强调脾脉以胃气为本，长弱和缓为常，至数失常则病深，故归平脉类以明常度。", ["长", "弱"]], "21534": ["病机", "本段以脾脉之急、缓、大、小、滑、涩分主诸病。急甚为瘛疭，微急为膈中满、食入还出，乃脾寒肝乘、筋脉拘急；缓甚为痿厥，微缓为风痿、四肢不用，乃脾虚湿盛；大甚为击仆，微大为脾疝脓血，乃邪实；滑甚为㿉癃，微滑为虫毒蛔，乃湿热内蕴。诸脉各主其病机。", ["急", "缓", "大", "滑"]], "21535": ["病机", "本段论脾脉搏坚而长，其色黄，病少气，乃邪实脉坚、脾气壅滞；软而散色不泽者，当病足胻肿若水状，乃脾虚不运、水湿下注；黄脉之至大而虚，有积气在腹中，厥气名曰厥疝，得之汗出当风，乃脾虚气逆、风邪内侵。脉坚长为实，大而虚为虚实夹杂。", ["坚", "长", "大", "虚"]], "21536": ["病机", "脉沉取濡软、浮取虚软，反映脾虚湿困、运化失职。脾虚故腹胀烦满、不嗜食、食而不化；湿浊内蕴化热则胃中有热、大便难；脾主四肢，湿阻络脉故四肢苦痹时不仁；房劳伤脾及冲任，则月使不来或频并。", ["沉", "濡", "浮", "虚"]], "21537": ["预后", "脾病见脉微缓而长，微缓为脾虚有湿之常，长为胃气尚存、病未深入，故曰「此为可治」。饮食不消、腹胀满、体重节痛、大便不利皆脾运不健之症，脉不弦急而反微缓长，说明中气未败，宜平胃、泻脾等丸及针灸补泻。", ["微", "缓", "长"]], "21538": ["病机", "趺阳脉浮为胃气强，涩为小便数，浮涩相搏则津液偏渗膀胱，肠道失润，大便坚而小便利，此即「脾约」。脾约者，胃热约束脾之转输，故不渴而便坚，与善哕、四肢急、体重不能衣之脾胀症候相应。", ["浮", "涩"]], "21539": ["病机", "寸口脉弦滑，弦主痛、滑主实，痛则筋脉拘急，实则气机壅踊，痛踊相搏故胸胁抢急。趺阳脉浮涩，浮为胃气微，涩为脾气衰，微衰相搏则呼吸不得，此为「脾家失度」，说明脾胃气衰、升降失常。", ["弦", "滑", "浮", "涩"]], "21540": ["病机", "寸口脉双紧，紧主寒主痛，双紧为寒邪内入，其气不出，无表证而病在里，寒凝气滞故心下痞坚。此段以脉紧说明寒邪内结、里气不通之病机，与「无表有里」相应。", ["紧"]], "21541": ["误治", "趺阳脉微为无胃气，涩为伤脾。寒在于膈而反下之，寒积不消，胃微脾伤，谷气不行，食已自噫，寒在胸膈，上虚下实，谷气不通，为闭塞之病。此段说明误下伤脾、寒凝气闭之病机。", ["微", "涩"]], "21542": ["平脉", "寸口脉缓而迟，缓为阳，卫气长；迟为阴，荣气促（一云不足）。荣卫俱和，刚柔相得，三焦相承，其气必强。此段以缓迟相合说明荣卫调和、三焦通畅之平脉，非病脉。", ["缓", "迟"]], "21543": ["病机", "趺阳脉滑为胃气实，紧为脾气伤。得食而不消者，脾不治也；能食腹不满为胃气有余；腹满不能食、心下如饥为胃气不行、心气虚；得食而满者为脾家不治。此段以滑紧说明胃实脾伤、运化失职之病机。", ["滑", "紧"]], "21544": ["病机", "原文未出脉名，只言“病脉已解”而“反暮微烦”。暮时阳气入阴，脾胃气尚弱，强与谷则不能消谷，谷气停聚生微热，故烦。脉已解说明外邪已去，病机在脾胃虚弱、食复，损谷则愈，属病后调护失宜之病机。", []], "21545": ["主病", "脾积脉浮大而长，浮大主中焦气壅，长主积气成形。原文“心下累累如桃李起”“腹满呕泄肠鸣”“四肢重足胫肿”，皆脾失运化、水湿内停、肌肉受损之候，色黄亦脾病外征，故脉主脾积。", ["浮", "大", "长"]], "21546": ["预后", "脾病本脉当浮大而缓，缓为脾土和缓之象。今反弦急，弦急属木，木克土为逆；色当黄而反青，青亦木色，故“十死不治”。脉症皆见克贼之象，说明脾土受木乘、胃气败绝，主预后凶险。", ["浮", "大", "缓", "弦"]], "21547": ["其他", "此段述足太阴脾脉之根、行、络，起于足大趾端隐白，循内踝前廉、入腹属脾络胃、挟咽连舌本。原文为经脉循行与腧穴部位，非论脉象主病，故脉象要素为空，主旨归其他，说明脾脉所系之经络系统。", []], "21548": ["病机", "公孙别络入络肠胃，实则胃热，阳脉反大于寸口三倍，主腹中切痛、舌强筋转等阳实之候；虚则胃寒，阴脉反小于寸口一倍，主鼓胀泄水、不能卧而烦。脉时缀缀动为络脉扭折之征，发动甚者死不治，说明虚实两端皆由脾胃络脉失调。", ["大", "小", "动"]], "21549": ["其他", "此段仅为篇目体例文字，标明“论一首方二十三首脉四首灸法一首”，未出具体脉象与病机论述，故脉象要素为空，主旨归其他，不能据以分析病机。", []], "21550": ["主病", "右手关上候脾胃，脉阴实者，阴经实热。原文“足寒胫热、腹胀满、烦扰不得卧”，足寒为阳郁不达四末，胫热腹胀烦扰为脾实热壅于中焦，故名曰脾实热，脉实主邪气盛实。", ["实"]], "21551": ["主病", "右手关上阴阳俱实，足太阴与阳明经俱实。原文“脾胀腹坚、抢胁下痛、胃气不转、大便难、时反泄利、喘鸣多惊、身热汗不出、喉痹精少”，皆脾胃实热壅滞、气机不转、上冲肺肝之候，故脉阴阳俱实主脾胃俱实。", ["实"]], "21552": ["主病", "原文述脾脉厥逆而见大，腹中热切痛，舌强腹胀身重食不下，此脉大乃邪热内盛、脾气壅滞之象。脾脉本应和缓，今厥逆而大，说明热邪内结，气机逆乱，故见腹中热痛、舌强等症，主脾实热证。", ["大"]], "21553": ["病机", "右手关上脉阴虚，即脾经虚寒。原文列泄注、腹满气逆、霍乱呕吐黄疸、心烦不得卧、肠鸣，皆脾虚冷、运化失司、气逆于上所致。脉虚为阳气不足，故主脾虚冷之病机。", ["虚"]], "21554": ["病机", "右手关上脉阴阳俱虚，示足太阴与阳明经气皆虚。脾胃俱虚，纳运无力，故胃中如空状、少气不足以息；阳虚不能温煦，则四逆寒、泄注不已。脉虚直接反映脾胃气虚之病机。", ["虚"]], "21555": ["主病", "脉数而滑为宿食内实，故可下；寸脉紧主头痛风寒或宿食不化；脉紧如转索为宿食；寸口浮大按之涩、尺中微涩，皆宿食阻滞、胃气不降之征。诸脉象共同说明宿食内停、邪实于中之病机。", ["数", "滑", "紧", "浮"]], "21556": ["病机", "原文论脾风、厉风、恶风，虽未出脉名，但以阴阳动静、肉之虚实为纲。里虚外实则体重怠堕、不嗜饮食；阳动伤热则热实，见鼠走、唇口坏、汗大泄。此段重在阐发风邪伤肉、虚实转化的病机。", []], "21557": ["预后", "肉绝五日死，因太阴气绝则脉不营肌肉，肌肉濡而人中满、唇反，唇反则气尽肉先死。原文以“脉不营”言肉失所养，非具体脉象，而述肉绝之预后，故归预后。", []], "21558": ["病机", "趺阳脉浮为胃气强，涩为小便数，浮涩相搏则津液偏渗，大便坚而小便利不渴，此为脾约。脉浮涩反映胃热约束脾阴、津液输布失常之病机。", ["浮", "涩"]], "21559": ["其他", "此段仅为篇题“论一首脉证二十四条”，无具体脉象与病机论述，故脉象要素为空，主旨归为其他，不作病机分析。", []], "21560": ["病机", "下痢见脉滑而数，滑主宿食内积，数主热，是食积化热、壅滞肠腑之象。宿食不去则下痢难止，故原文断为「有宿食，当下之」，示其病机为实积而非虚寒，与一般虚寒下痢脉微弱者迥异。", ["滑", "数"]], "21561": ["病机", "脉迟而滑，迟为寒为滞，滑为实为积，合见则属寒实内结、积滞未去。原文断为「实也」，虽下痢而「利为末止」，是邪未尽，故「急下之」，示脉迟非虚寒，乃实邪阻滞、气血不畅所致。", ["迟", "滑"]], "21562": ["病机", "下痢本多虚，今脉反滑，滑主实积，是内有宿滞当去。原文谓「当有所去下乃愈」，说明脉滑为邪实可下之征，与虚寒下痢脉不应滑相对，提示病机在积滞内停、非攻不去。", ["滑"]], "21563": ["病机", "此段辨下痢复发与下后变证。脉迟为寒，故「但当温之」；脉沉紧为寒实内结，下之亦然；脉浮大弦则邪有外达之势，「下之当已」。原文以「下不尽」释复发，示病机在余邪未净，须凭脉辨寒实与可下之机。", ["迟", "沉紧", "浮大弦"]], "21564": ["病机", "下痢脉浮大，非实热，乃「以强下之故」，误下伤正致虚阳外浮。设脉浮革，革为虚寒之象，因而肠鸣，是中阳不足、寒气内动，故「当温之」。原文以浮大、浮革并见，明虚寒之病机而非可下之实。", ["浮大", "浮革"]], "21565": ["病机", "脉迟紧，迟为寒，紧为痛，是寒邪凝滞、气血不通之象，故原文谓「为痛，未欲止，当温之」。若得冷则寒更甚，气机壅塞而「满」，肠垢下泄，示病机属寒凝腹痛而非热痢。", ["迟", "紧"]], "21566": ["病机", "下痢脉反浮数，浮为热外浮，数为热盛，尺中自涩则阴血受伤、热灼血络，故「其人必清脓血」。原文以「反」字点出脉与下痢之常不符，示热邪内迫、血腐成脓之病机。", ["浮", "数", "涩"]], "21567": ["病机", "脉数而渴，数为热，渴为热灼津伤，若正能胜邪则「今自愈」；设不瘥，则热郁血分，「必清脓血，有热故也」。原文以脉数渴与脓血相应，明病机为热邪内盛、伤及血络。", ["数"]], "21568": ["预后", "下痢脉沉弦，沉为里、弦为气滞不畅，故下重里急后重；脉大则邪气盛、正气未衰而痢未止；脉微弱数为邪退正复、胃气渐和之象，故欲自止。虽发热，因脉微弱数而非实大急数，知非邪盛，故必不死。此段以脉之沉弦、大、微弱数辨下痢之轻重进退与生死预后。", ["沉", "弦", "大", "微弱数"]], "21569": ["病机", "下痢脉沉而迟，沉主里、迟主寒，为里寒下利清谷之脉。面少赤、身微热乃阴寒内盛、虚阳上浮之戴阳，故曰面戴阳下虚。阳气郁冒，必郁冒汗出而解，然病人必微厥，因下元虚寒、阳不外达。此段以沉迟脉合面赤微热辨下虚戴阳之病机。", ["沉", "迟"]], "21570": ["预后", "下痢有微热而渴，似属热象，然脉弱为邪气已衰、正气渐复之征，脉证相参知邪不盛，故今自愈。微热而渴乃痢后津伤、余邪未尽之轻候，脉弱则胃气未败，正能胜邪，故预后良好。此段以脉弱辨下痢向愈之机。", ["弱"]], "21571": ["预后", "下痢脉数、有微热汗出，数为阳复、邪从汗解之象，故今自愈。设脉紧则紧主寒主痛，为寒邪内盛、正气受困，痢未解也。此段以脉数、脉紧对举，辨下痢之解与未解，数则阳通邪退，紧则寒凝未散。", ["数", "紧"]], "21572": ["预后", "下痢脉弦，弦为少阳木气之脉，发热身汗乃邪从表解、阳气外达之象，脉弦而身汗出，知邪有外出之路，故自愈。此段以脉弦合发热身汗，辨下痢之邪从汗解而向愈。", ["弦"]], "21573": ["预后", "下痢脉大浮弦，大浮为邪在表、正气尚能抗邪外出，弦为气机调畅之象，脉浮大而弦知邪有外解之势，故下当已。此段以脉大浮弦辨下痢将愈之候，邪从表解而下利自止。", ["大", "浮", "弦"]], "21574": ["预后", "下痢后脉绝、手足厥冷，为阳气暴脱、脉道不通之危候。若晬时脉还、手足转温，则阳气来复、生机尚存故生；脉不还、手足不温则阳绝不复故死。此段以脉绝与脉还、手足温与不温辨下痢后阳气存亡之生死决断。", []], "21575": ["预后", "下痢手足厥冷无脉，为阳气衰绝、脉道不利。灸之不温、脉不还，反微喘者，乃阳气上脱、肺气欲绝，故死。少阴负趺阳者为顺，谓少阴肾脉弱于趺阳胃脉，胃气尚存则顺。此段以灸后脉温与喘辨阳气存亡及胃气之顺逆。", []], "21576": ["主病", "脉沉细小数，沉主里，细主虚，小主不足，数主热。夏月暴冷伤中，泄痢耗液，引饮热汤，水气内停，通身浮肿，成冷下结。脉沉细小数示里虚有热，正虚邪恋，水湿不化，故主冷下结之病。", ["沉", "细", "小", "数"]], "21577": ["主病", "脉微细，微主阳气衰微，细主阴血不足。小儿夏月暴寒入胃，暴下如水，四肢被寒所折则壮热，经日不除，通身虚满腹痛。脉微细示寒伤中阳，气血两虚，正不胜邪，故主此寒泄虚满之证。", ["微", "细"]], "21578": ["其他", "本段仅标「胃腑脉论第一」为篇题，未出具体脉象与病机论述，故脉象要素为空。篇题提示以下诸段专论胃腑脉候，属脉学分类纲领，非主病、病机或预后之具体条文，故归入其他。", []], "21579": ["平脉", "原文述胃腑容量及水谷更虚更满之常，谓「气得上下，五脏安定，血脉和利，精神乃居」，脉和利即平人之常脉。此段以胃满肠虚、肠满胃虚的生理为基础，说明血脉和利乃水谷精气充养之象，故属平脉。", ["和"]], "21580": ["病机", "原文「右手关上阳绝者，无胃脉也」，阳绝指胃脉断绝，关部无冲和之象。胃中冷，故吞酸头痛。无胃脉示胃气衰败，中阳不振，寒饮内停，病机为胃气虚寒、阳气隔绝，故刺足太阴以治阴。", []], "21581": ["病机", "右手关上阳实，胃实也，肠中伏伏不思食，得食不能消。脉浮而芤，浮则为阳，芤则为阴，浮芤相搏，胃气生热，其阳则绝。浮主阳盛，芤主阴伤，阳热搏阴，胃气生热而阴液耗竭，故主胃实热结之病机。", ["浮", "芤"]], "21582": ["主病", "趺阳脉浮大，浮主胃气外浮，大主虚而无力。原文谓「此胃家微虚烦」，圊必日再行，动作头痛重热气朝者属胃。脉浮大示胃虚气浮，虚热上扰，故主胃家微虚烦之病，症见便次增多、头痛、热气朝作。", ["浮", "大"]], "21583": ["主病", "胃脉搏坚而长，坚主邪实，长主气盛，其色赤，当病折髀，示胃热壅盛、气血瘀阻。其软而散者，软散主胃气虚弱，当病食痹。同篇并述髀痛、胀满、少腹腰脊痛等传变，皆由胃病及肾、膀胱、心脾，故主胃病实虚两候。", ["坚", "长", "软", "散"]], "21584": ["主病", "原文未出脉名，论胃疟证候：旦病、善饥不能食、食而支满腹大。病机为疟邪客于胃，胃气壅滞，受纳虽亢而运化不行，故善饥却不能食，食入则气滞支满而腹大。刺足阳明太阴横脉出血，正是泻胃脾壅滞之邪，从证治反推其病机在胃实气滞。", []], "21585": ["病机", "原文以「胃脉实则胀，虚则泄」立论，实脉主邪气壅盛于胃，胃气不通故胀满；虚脉主胃气不足，仓廪不固故泄泻。后文又以肉䐃坚大、么小、不称身等论胃厚薄缓急结，皆从形肉测胃气强弱，说明胃脉虚实与胃体胃气盛衰相应，实胀虚泄为其主病。", ["实", "虚"]], "21586": ["其他", "此段纯述足阳明胃经循行路径，自鼻交頞、入上齿、环唇、下膈属胃络脾，直至下足跗入中趾间，未及脉象与病候。其主旨在于明胃经所过之处，为后文胃病证候及针灸取穴提供经络依据，故不属主病、病机诸类，仅作经络循行记述。", []], "21587": ["其他", "此段仅为篇目小注「脉二首方三首灸法一首」，标明该篇所收脉论、方剂与灸法数目，无具体脉象与病机内容，亦无证候可析。属文献编次体例之记，不能归入主病、病机、平脉等类，故列其他。", []], "21588": ["主病", "右手关上脉阳实，关候中焦，阳实即胃经邪热壅盛。原文列头痛、汗不出如温疟、唇口干、善哕、乳痈、缺盆腋下肿痛，皆阳明热盛、经气壅遏之象：热郁则汗不出，热灼则唇口干，胃热上逆则哕，热壅经络则乳痈、缺盆腋下肿痛，故名曰胃实热。", ["实"]], "21589": ["主病", "右手关上脉阳虚，关主中焦，阳虚即胃经虚寒。原文见胫寒不得卧、恶风寒洒洒、目急、腹痛虚鸣、时寒时热、唇口干、面目浮肿，皆胃阳不足、寒从中生、卫外不固之候：寒凝则胫寒腹痛，阳虚则恶寒洒洒，水气不化则面目浮肿，故名曰胃虚冷。", ["虚"]], "21590": ["其他", "此段亦为篇目小注「脉二首方十三首灸法三首」，仅记该篇脉论、方剂、灸法之数，无脉象描述，无病机证候可论。属古籍编次体例之标记，与具体脉诊内容无关，故归入其他，不作主病或病机分析。", []], "21591": ["病机", "趺阳候胃气。浮而涩者，浮为胃气虚浮，涩为脾伤不磨，脾伤则宿谷不化，朝食暮吐、暮食朝吐，名为胃反。紧而涩者，紧主寒凝、涩主津伤，寒结而脾阴耗，胃气上逆不通，故其病难治。二脉皆从趺阳论胃反之虚实轻重。", ["浮", "涩", "紧"]], "21592": ["其他", "本段仅为篇首标题，标明“论一首脉一首方二十四首”，未载具体脉象与病机内容，故无法分析所主病机。原文无脉象描述，亦无症候对应，属篇章结构信息，不涉脉学实质。", []], "21593": ["病机", "原文以“阳紧阴数”论吐家，紧主寒、数主热，寒热相搏于中焦则食已即吐；“脉紧而芤”紧为寒、芤为虚，寒虚相搏致“阴结而迟”，胃气不通故噎。“趺阳脉微而涩”微为下利、涩为吐逆，谷不得入，明胃气虚寒、升降失司。诸脉皆围绕呕吐噎膈之寒热虚实错杂病机。", ["紧", "数", "芤", "迟"]], "21594": ["治法", "原文“干呕不止，粥食汤药皆吐”，胃气上逆已极，若更见“四厥，脉沉绝不至”，乃阳气衰微、脉道不通之危候。灸手间使三十壮以通阳复脉，灸之便通，说明脉沉绝非真死脉，乃寒厥气闭所致，灸法温通阳气则脉可复。此段以脉沉绝提示阳衰气闭，属灸治取效之例。", ["沉", "绝"]], "21595": ["病机", "趺阳脉微弦，微为虚、弦为寒，虚寒气从下上逆，法当腹满；若不满则寒凝下焦，见“下部闭塞，大便难，两胠下疼痛”。此脉说明中阳不足、寒从下犯，气机升降失常。原文“当以温药服之”正对虚寒病机，腹满转痛趋小腹为欲自下利，亦寒凝气转之象。", ["微", "弦"]], "21596": ["主病", "腹满发热数十日而“脉浮而数，饮食如故”，浮为病在表、数为热，然饮食如故知胃气未伤，非里实之候。此脉主表热与腹满并见，热未入腑，故可治以解表清里。原文以此脉症示腹满发热之属表热者，与里实腹满脉沉实者相鉴别。", ["浮", "数"]], "21597": ["其他", "本段为篇首标题，仅标“论一首脉一条方二十首灸法一首附寒疝骨蒸”，未载具体脉象与病机文字，故无从分析所主病机。属篇章结构信息，不涉脉学实质内容。", []], "21598": ["病机", "原文“寒脉沉弦，脉双弦者寒也”，弦脉“状如张弓弦，按之不移”主寒饮内结；“弦数者当下其寒”示寒郁化热之机；“双弦而迟者心下坚”为寒凝心下；“大而紧者阳中有阴可下之”主寒实内结。寸口脉弦则胁下拘急而痛，微紧涩并见为虚寒血少，误汗复下更伤阳气。诸脉围绕中寒里虚、寒实内结之病机。", ["沉", "弦", "数", "紧"]], "21599": ["病机", "胁下偏痛发热而“其脉紧弦”，紧主寒、弦主痛，紧弦相合为寒实内结、气机不通之象。胁下偏痛属寒凝胁络，发热乃寒郁阳浮，非实热。原文断为“此寒也”，治“当以温药下之”，以温下寒实，正合紧弦主寒实之病机。", ["紧", "弦"]], "21600": ["病机", "寸口脉弦而紧，弦主卫气不行而恶寒，紧主不欲饮食，弦紧相搏则寒疝成；趺阳脉浮而迟，浮为风虚，迟为寒疝。瘦人绕脐痛因风冷谷气不行，误下则气冲或心下痞，脉象揭示寒邪内结、卫阳不畅之病机。", ["弦", "紧", "浮", "迟"]], "21601": ["主病", "脉沉弦者主寒疝绕脐苦痛，发则自汗出、手足厥寒。沉为里寒，弦为痛为急，寒凝厥阴，阳气不达四末，故脉沉弦而见厥逆疼痛，方用乌头煎温散沉寒。", ["沉", "弦"]], "21602": ["治法", "原文未及具体脉象，但强调“患大热皆须候脉”，大热须准病用药，甚则倍用十倍以制之。服石致热不已者，惟朴硝煎可定，体现凭脉辨热、以寒制热之治法，非专论某脉主病。", []], "21603": ["其他", "此段仅为“肺脏脉论第一”篇题，无脉象描述与病机论述，故脉象要素为空，主旨归为其他，不涉具体主病或病机分析。", []], "21604": ["病机", "肺脉浮，秋时微浮，卫气迟、营气数，数在上迟在下，故名曰毛。阳当陷不陷、阴当升不升，为风寒所中，阳中邪则卷、阴中邪则紧，寒栗相搏名疟。脉之迟疾反映营卫失调、阴阳升降失常之病机。", ["浮", "微", "迟", "数"]], "21605": ["病机", "秋脉如浮，肺金收成之象，其气轻虚而浮、来急去散。若来毛而中央坚、两旁虚为太过，病在外，令人气逆背痛；来毛而微为不及，病在中，令人喘咳少气上气见血。脉象太过不及反映肺气虚实之病机。", ["浮", "毛", "坚", "微"]], "21606": ["平脉", "肺脉来厌厌聂聂如落榆荚，轻浮和缓，为肺之平脉；秋以胃气为本。若不上不下如循鸡羽，失其轻虚流利之态，则为肺病。此段以脉象形态辨平脉与病脉，强调胃气与轻浮和缓之象。", ["浮"]], "21607": ["死脉", "肺脉来如物之浮、如风吹毛，浮散无根，毫无胃气柔和之象，是肺金真气败绝之死脉。肺平脉本轻虚而浮，此则浮荡无依，故主死，与“如落榆荚”之平脉形成对照。", ["浮"]], "21608": ["死脉", "真肺脉“大而虚，如以毛羽中人”，大而无力、浮散无根，是肺气败散、胃气已绝之象，故肤色白赤不泽、毛折乃死。原文以“毛多胃少曰肺病，但毛无胃曰死”定其死生，又以毛而有弦、弦甚分春病今病，皆从胃气有无与兼脉生克立论。", ["大", "虚", "毛", "弦"]], "21609": ["预后", "肺死脏“浮之虚，按之弱如葱叶下无根”，浮取虚软、沉按弱而中空无根，是肺之真脏气竭，故主死。平脉则“微涩而短”，为秋金收敛之常。原文以脾乘肺、肾乘肺、心乘肺、肝乘肺四者辨邪之虚实逆顺，火克金为贼邪十死不治，木凌金为微邪即瘥。", ["浮", "虚", "弱", "涩"]], "21610": ["主病", "右手关前寸口“阴绝者，无肺脉也”，寸口肺脉绝而不至，肺主气、司呼吸，肺气不行故苦短气、咳逆、喉中塞噫逆。原文以脉绝定位病在肺，复以“刺手阳明，治阳”为治，是据肺与大肠相表里、取阳明以通肺气之意。", []], "21611": ["平脉", "肺脉来“泛泛轻如微风吹鸟背上毛”，形容其浮软轻虚、如毛羽飘拂，为肺金轻清之常。原文以至数分生死：再至曰平，三至曰离经病，四至脱精，五至死，六至命尽，是据脉之至数多少测胃气存亡与病之浅深。", ["毛"]], "21612": ["主病", "本段以肺脉兼见急、缓、大、小、滑、涩六象分主诸病：急甚为癫疾、微急为肺寒，缓甚多汗、微缓痿漏风，大甚胫肿、微大肺痹，小甚飧泄、微小消瘅，滑甚息贲上气、微滑上下出血，涩甚呕血、微涩鼠瘘。皆从肺主气、主皮毛、通调水道的功能失常推衍。", ["急", "缓", "大", "小"]], "21613": ["主病", "肺脉“搏坚而长”为气逆火盛、迫血上行，故当病唾血；“濡而散”为肺气浮散不敛、卫外不固，故当病漏汗，且言“今不复散发”，指汗出不止、阳气难复。原文以坚长与濡散对举，一实一虚，皆从肺脉之象推断血与汗之病变。", ["坚", "长", "濡", "散"]], "21614": ["病机", "白脉之至“喘而浮”，浮为肺气上逆、喘为息促不宁，故“上虚下实”，气积胸中而惊。若“喘而虚”则肺气不足，名曰肺痹，兼寒热，原文指其“得之醉而使内”，即醉后房劳伤肺。此段以浮、虚二象辨肺之虚实积气。", ["浮", "虚"]], "21615": ["其他", "此段为黄帝问句，问十二经脉中何以独手太阴之脉动而不休，原文仅设问而未及脉象描述，故脉象要素为空。其主旨在于探讨寸口肺脉独动之由，属经脉理论设问，非直接言某脉主某病，故归入其他。", []], "21616": ["平脉", "此段论足阳明胃脉为五脏六腑之海，精气上注于肺，肺气从太阴而行，以呼吸定脉动。原文言'人一呼脉再动，一吸脉亦再动，呼吸不已，脉动不止'，是以呼吸往来候脉之常动，非病脉也。脉动随息不止，说明胃气充沛、肺气宣行有常，故列平脉，示人以呼吸测脉动之准则。", ["动"]], "21617": ["病机", "原文'肺脉，沉之而数，浮之而喘'，沉取数而浮取喘促，示肺气壅热于内而宣降失职。苦淅淅寒热、腹满肠中热、小便赤，为热郁肺肠；肩背痛、腰以上汗出，乃风热上扰、腠理不固。末言'得之房内汗出当风'，点明汗出腠疏、风邪乘袭，故脉沉数浮喘并见，主肺热兼风之病机。", ["沉", "数", "浮"]], "21618": ["预后", "肺病色白、身但寒无热、时时咳，为肺气虚寒之候。原文断'其脉微迟为可治'，微主气虚，迟主脏寒，脉与色症相应，虚寒未至危笃，故曰可治。后列五味子大补肺汤、泻肺散及四时刺法灸法，皆示调补肺气之治。脉微迟与肺寒咳逆相合，是预后顺证之凭。", ["微", "迟"]], "21619": ["病机", "形寒寒饮两寒相感，中外皆伤，气逆上行而肺气伤。劳倦则咳唾血，原文谓'其脉细紧浮数皆吐血'，细紧主寒束血滞，浮数主热迫血溢，寒热错杂、肺伤气壅，故血随气逆而出。末言'躁扰嗔怒得之'，明情志化火、气壅肺伤，为此脉吐血之由。", ["细", "紧", "浮", "数"]], "21620": ["主病", "肺胀者虚而满、喘咳、目如脱状，乃肺气胀满、宣降失司，气壅于上。原文'其脉浮大'，浮主病在肺卫之上，大主邪气壅盛而脉道宽纵，正合肺胀虚满喘咳之象。脉浮大与喘满目突相应，示气逆于上、肺胀之病机，故主肺胀。", ["浮", "大"]], "21621": ["病机", "趺阳脉浮缓，少阳脉微紧。原文自释'微为血虚，紧为微寒'，浮缓主卫气浮缓、营血不足，微紧主血虚而寒客。血虚寒凝，结于皮腠，故发鼠乳。脉浮缓微紧与血虚微寒之机相合，示病由营血亏虚、寒邪凝滞所致，非单纯外感。", ["浮", "缓", "微", "紧"]], "21622": ["主病", "诊得肺积脉浮，手按之辟易，是积在肺而脉气浮越于外。胁下时时痛、逆背相引痛、少气善忘、目瞑结痈、皮肤寒，皆肺积气结、气血不畅之症。秋愈夏剧，秋金得令而夏火克金。皮中时痛如虱缘、甚如针刺、时痒色白，均属肺积外应皮毛，脉浮主积之在肺。", ["浮"]], "21623": ["预后", "肺病身热、咳嗽短气、唾出脓血，脉当短涩，短涩主肺伤气滞、血络受损，脉症相应。今反浮大，色当白而反赤，原文断为'火之克金，为大逆，十死不治'。浮大主火热外张，赤为火色，金受火克，脏气败绝，故属死脉危候，示脉症相反之凶。", ["短", "涩", "浮", "大"]], "21624": ["病机", "原文述秋金肺脉，言“应在腋下动脉”，指手太阴脉气所应之处。秋令金始治，肺将收杀，阴气初胜而湿气及体，阴气未盛未能深入，故取输以泻阴邪、取合以虚阳邪。其脉本在寸口，根于太仓，说明肺脉应秋收之令，动脉为经气所动之处，主肺金当令、阴气渐胜之病机。", ["动"]], "21625": ["其他", "本段述手太阴肺经循行路径，从“其脉起于中焦，下络大肠，还循胃口，上膈属肺”至“出大指之端”，并言其支者从腕后出次指端，合手阳明为表里。原文未及具体脉象，仅明经脉所过与表里相合关系，故脉象要素为空，主旨属经脉循行论述。", []], "21626": ["病机", "原文以“阳脉反逆大于寸口脉三倍”为阳病实候，主大肠热、肺病咳喘胸满、肩背痛风汗出；“阴脉反小于寸口一倍”为阴病虚候，主大肠寒、欠咳遗数、肩背寒痛少气。脉之大小逆顺反映太阴别络虚实，阳脉大主实热，阴脉小主虚寒，故脉象要素取“大”。", ["大"]], "21627": ["其他", "本段仅存“脉四首方二十首灸法三首”之篇目统计，无具体脉象描述与病机论述，故脉象要素为空。其内容属文献编次信息，不涉主病、病机或症候，仅可归为其他类。", []], "21628": ["主病", "原文言“右手寸口气口以前脉阴实者，手太阴经也”，阴实即寸口阴分脉实，主肺实热。症见肺胀汗出若露、上气喘逆、咽中塞如欲呕状。脉实为邪气壅盛之征，肺经实热则气逆胀满，故脉阴实主肺实热病。", ["实"]], "21629": ["主病", "原文谓“右手寸口气口以前脉阴阳俱实者，手太阴与阳明经俱实也”，阴阳俱实指寸口阴分阳分脉皆实，主肺与大肠俱实。症见头痛目眩惊狂、喉痹痛、手臂卷、唇吻不收。脉实主邪盛，肺与大肠表里俱实，热壅经络，故见诸症。", ["实"]], "21630": ["主病", "原文曰“右手寸口气口以前脉阴虚者，手太阴经也”，阴虚即寸口阴分脉虚，主肺虚冷。症见少气不足以息、咽干不津液。脉虚为正气不足之象，肺气虚冷则呼吸无力、津液不布，故脉阴虚主肺虚冷病。", ["虚"]], "21631": ["主病", "原文言“右手寸口气口以前脉阴阳俱虚者，手太阴与阳明经俱虚也”，阴阳俱虚指寸口阴分阳分脉皆虚，主肺与大肠俱虚。症见耳鸣嘈嘈、时妄见光明、情中不乐或如恐怖。脉虚主气血不足，肺大肠表里俱虚，清窍失养、神气不宁，故见诸症。", ["虚"]], "21632": ["病机", "原文论肺气极与皮痹内舍于肺，寒湿客于六腑，症见气上冲胸、咳逆短气、暮甚昼瘥，或喘唾血。虽未出脉名，然以阴阳表里衰旺为纲，示肺病虚实之机：阴伤则寒而虚，阳伤则热而实，治当以阳调阴、以阴调阳，早期治皮毛肌肤筋脉以防传变。", []], "21633": ["主病", "上气咳逆、喉中水鸡声、喘息不通，为寒饮迫肺、气逆上壅之候。脉浮主邪在表、病位偏上，饮邪乘肺则咳逆喘息；水鸡声乃痰饮搏结喉间之征。脉浮与上气并见，说明病机为外邪引动内饮、肺气不得宣降。", ["浮"]], "21634": ["其他", "此段为方药组成，大枣、甘皮、干姜、地黄四味，未言脉象与病机。从药测证，甘皮去脉、干姜温中、地黄滋阴、大枣补中，大致示中焦虚寒兼阴血不足之调治，然原文无脉症可据，不能强解为某脉所主。", []], "21635": ["治法", "短气不得语，属肺气壅塞、宗气不布之候。原文列灸天井、大椎、肺俞、肝俞、尺泽及指间交脉等法，取宣肺降气、通阳宽胸之意。虽未出脉，然从灸治诸穴可知病机重在肺气痹阻、气机升降失司，故以灸法温通为治。", []], "21636": ["病机", "寸口脉数而咳、浊唾涎沫，为热在上焦、津液重亡之肺痿。原文又言阳脉早索阴脉不涩、脉平弱，说明肺痿日久津伤气耗，脉由数转弱，阴脉不涩则津亏而非实邪。上虚不能制下则遗溺小便数，总属肺热叶焦、津液枯涸之机。", ["数", "涩", "弱"]], "21637": ["主病", "肺胀咳而上气、咽燥而喘，脉浮者，为心下有水、饮邪迫肺之候。脉浮主水气在表在上，饮停心下则肺气胀满、宣降失职，故咳喘并见。浮脉与肺胀相合，说明病机为水饮内停、上逆犯肺，属外寒内饮之肺胀。", ["浮"]], "21638": ["病机", "咳唾脓血而脉数实者属肺痈，虚者属肺痿；脉反滑数亦为肺痈。原文又言寸口脉微而数，微为风、数为热，风伤皮毛、热伤血脉，蓄结痈脓。数实主热毒壅盛，滑数主痰热成脓，微数则示风热初袭、营卫不和，总归热壅血瘀之肺痈病机。", ["数", "实", "滑", "微"]], "21639": ["主病", "咳而胸中满、振寒、咽干不渴、浊唾腥臭、久吐脓如米粥，脉数，为肺痈已成之候。脉数主热，热毒壅肺、血腐成脓，故吐腥臭脓痰；咽干不渴说明热在血分而不在气分。数脉与脓痰并见，示热壅血瘀、蓄结痈脓之病机。", ["数"]], "21640": ["主病", "卒中风寒冷温气入腹，虚胀急满抢心胸久痛、气息不通而汗不出，脉弦紧。弦主痛、主气机郁滞，紧主寒主痛，寒邪内侵、阳气被遏，故脉见弦紧而表气闭塞汗不出，正合寒凝气滞、胀满疼痛之候。", ["弦", "紧"]], "21641": ["主病", "风冷入腹忽绞痛、紧急如吹、二便闭、小腹气结如斗大胀满，脉弦紧或沉迟。弦紧为寒凝气结、痛势急迫之象，沉迟则示寒邪深入于里、阳气不运，故见绞痛胀满、大小便闭，属里寒实结之候。", ["弦", "紧", "沉", "迟"]], "21642": ["其他", "此段仅为「大肠腑脉论第一」篇题，未出具体脉象与病机文字，故脉象要素为空。其主旨在于标举大肠腑脉专论之目，属篇章归类，不能据以推断病机，故列其他。", []], "21643": ["其他", "此段论大肠腑之解剖形态、容量、长度与所主时令，谓其「主十二时，定血脉，和利精神」，并以鼻柱候大肠，全为脏腑生理之叙述，未及脉象与病机，故脉象要素为空，列其他。", []], "21644": ["病机", "右手关前寸口阳绝者，无大肠脉也，见少气、心下有水气，至立秋节即咳，刺手太阴鱼际间。寸口阳脉断绝示大肠经气不足，肺与大肠相合，气化不行则水气停心下、少气而咳，属经脉气虚、水气上逆之病机。", []], "21645": ["病机", "此段述手阳明大肠经脉循行及是动、所生病，如齿痛颊肿、目黄口干鼽衄喉痹、肩前臑痛、大指次指痛不用；气盛则脉所过者热肿，虚则寒栗不复，并以人迎与寸口大小相较辨虚实，属经脉病机之论，未出具体脉象。", []], "21646": ["其他", "此段仅为「脉二条方二首灸法七首」之篇目统计文字，未载具体脉象与病机内容，故脉象要素为空。其性质属编纂体例之标注，不能据以分析病机，故列其他。", []], "21647": ["主病", "右手寸口气口以前脉阳实者，为手阳明经病，症见肠满善喘咳、面赤身热、喉咽中如核状，名曰大肠实热。阳实之脉主邪热壅盛于阳明，热结肠道则肠满，热上蒸肺则喘咳面赤，咽中如核亦热壅之象，故主大肠实热。", ["实"]], "21648": ["病机", "原文言右手寸口气口以前脉阳虚，属手阳明大肠经。脉虚为阳气不足，大肠失温，故病苦胸中喘、肠鸣、虚渴、唇干目急、善惊泄白，总由大肠虚冷、传导失职、津不上承所致，脉虚正是阳虚内寒之征。", ["虚"]], "21649": ["病机", "支咳者心下坚满、咳则支痛，其脉反迟。迟主寒、主饮停，寒饮结于心下，气机不利，故咳则支痛而脉不数反迟，说明此咳非热邪迫肺，乃寒饮内结、阳气不伸之病机。", ["迟"]], "21650": ["病机", "久咳而时发热，脉在九菽，一作卒弦。弦主饮、主寒，胸中寒实内结，阳气被遏则时发热，非虚证可比。原文断为胸中寒实所致，当吐之，脉弦实正是寒实内结、病位偏上之据。", ["弦"]], "21651": ["治法", "咳家其脉弦，弦主饮、主寒，说明咳由水饮内停、肺气上逆而作。原文随即论欲行吐药当相人强弱而无热乃可吐，是据脉弦辨为饮邪在上，进而审体质虚实、有无热象以定吐法可否，脉弦在此为施治提供依据。", ["弦"]], "21652": ["预后", "咳家脉弦为有水，可下之；脉沉者不可发汗，沉主饮邪在里；久咳数岁脉弱者可治，弱为正气尚存；实大数者死，虚者必善冒，因支饮在胸。原文以弦、沉、弱、虚、实大数诸脉判断饮邪深浅与正气存亡，故归预后。", ["弦", "沉", "弱", "虚"]], "21653": ["预后", "吐血喘咳上气脉数有热不得卧者死，寒家咳而上气脉数者死，谓形损；脉大而散为气实血虚、有表无里；上气面胕肿肩息脉浮大不治。数、大、散、浮诸脉示邪盛正衰、气血耗散，故原文屡言死、不治，主预后不良。", ["数", "大", "散", "浮"]], "21654": ["病机", "小青龙汤下后多唾口燥，寸脉沉、尺脉微，手足厥逆，气从小腹上冲胸咽，面翕热如醉，小便难时复冒。寸沉尺微示下焦阳虚、冲气上逆，服汤后饮减而冲气未平，故以桂苓五味甘草汤治其气冲，脉象正是阳虚冲逆之机。", ["沉", "微"]], "21655": ["病机", "咳而上气肺胀，其脉浮，心下有水气，胁下痛引缺盆，若有实者必躁，常倚伏。浮脉主水气在表在上，饮邪迫肺则肺胀咳喘，水停心下则胁痛引缺盆，故以小青龙加石膏汤主之，脉浮点明水气偏表之病机。", ["浮"]], "21656": ["病机", "原文言肺胀咳而上气、烦躁而喘而脉浮，浮为邪在表、水气上逆之象。心下有水，水寒射肺则咳喘烦躁；脉浮说明病位偏上偏表，水饮未深结于里，故以发汗宣肺、化饮降逆为治，与麻黄等先煮去沫的用法相应。", ["浮"]], "21657": ["主病", "咳逆上气胸满、喉中不利如水鸡声，是寒饮郁肺、痰气搏结喉间之候。脉浮表明饮邪偏于上焦、病势向外向上，未全入里，故以宣肺散寒、化痰利咽为主，与射干麻黄汤类方相应。", ["浮"]], "21658": ["主病", "上气而脉沉，沉主里、主水，说明气逆不降源于里虚寒或水饮内停，病位不在表而在里。与上证脉浮相对，提示治当温里化饮、降气平逆，不可徒事发表，故原文特标脉沉以别治法。", ["沉"]], "21659": ["病机", "原文以脉双弦主寒、偏弦主饮，又言肺饮不弦但喘短气、支饮脉平，留饮脉微或沉滑、脉沉者有留饮。弦为饮邪凝聚、气机拘急；微为阳虚；沉滑为水饮内结。诸脉随饮停部位浅深而异，说明水饮为病脉无定象，当结合喘满、短气、胁痛等症辨其留饮所在。", ["弦", "微", "沉", "滑"]], "21660": ["病机", "膈间支饮，喘满、心下痞坚、面色黧黑，脉沉紧。沉主里、主水，紧主寒主痛，为水饮寒邪深结于里、阳气被遏之象。得之数十日吐下不愈，说明饮邪坚结非一般攻逐可去，故以木防己汤类通阳化饮、软坚散结。", ["沉", "紧"]], "21661": ["病机", "酒客久饮过度致咳吐血，脉虚者必胸满，胸中有支饮。虚脉说明久饮伤脾、中气亏虚，气虚不能运化水饮，饮停胸膈则胸满。此以脉虚点明正虚为本、饮停为标，故治当兼顾补虚化饮，不可纯用攻逐。", ["虚"]], "21662": ["病机", "病者脉伏，欲自利而利后反快，虽利心下续坚满，此为留饮欲去。伏脉主饮邪深伏、阳气被遏不能外达。利后反快是饮邪有外出之势，然续坚满说明饮根未除，故因势利导，以甘遂半夏汤类攻逐留饮。", ["伏"]], "21663": ["病机", "胸膈心腹痰水冷气、嘈烦水鸣多唾、口出清水、胁肋急胀，皆胃气弱受冷所致。脉来沉弦细迟：沉主里、弦主饮主痛、细主虚、迟主寒，四脉合见，正说明中阳不足、寒饮内停、胃气虚弱之病机，故治当温胃化饮。", ["沉", "弦", "细", "迟"]], "21664": ["其他", "原文仅标目「肾脏脉论第一」，未出具体脉象文字，故无从据脉析机。然篇题明示专论肾脉，当与后文沉、石诸脉相参，以肾主水、主藏精、主骨为纲。此段无脉可辨，病机分析暂缺，仅存篇目以备考。", []], "21665": ["病机", "原文「其脉沉」「沉为阴在里」，以沉主里主阴，应冬令阳气下陷、阴气上升之藏象。沉脉在里，故「不可发汗」，汗则伤阳动蛰；又「阴气在表，阳气在里」，误下则伤脾，脾土弱则「水气妄行」，变生喘、口烂、结胸、清溲痢诸症，皆由沉阴之脉示里虚不可妄攻。", ["沉"]], "21666": ["病机", "冬脉「沉以搏」为平，沉而搏即石中有胃。若「来如弹石」则石多胃少，为太过，病在外，故「解㑊脊脉痛而少气不欲言」；「去如数」为不及，病在中，故「心悬如病饥，䏚中清，脊中痛，少腹满，小便变赤黄」。一太过一不及，皆失沉搏之和，示肾气偏胜偏衰之机。", ["沉", "数"]], "21667": ["预后", "原文以「喘喘累累如勾，按之而坚」为平，勾石相兼、胃气犹存；「如引葛，按之益坚」则石多无勾，胃气渐失，故曰肾病；至「发如夺索，辟辟如弹石」，纯石无胃，真脏脉见，故曰肾死。三段递进，示肾脉由平→病→死，全在胃气存亡与石中是否有勾。", ["坚", "石"]], "21668": ["死脉", "「真肾脉至搏而绝，如以指弹石辟辟然」，纯石无胃，故主死，兼「色黄黑不泽毛折」为精败之外候。原文又申「石多胃少曰肾病，但石无胃曰死」，并以「肝不弦肾不石」释无胃气，明真脏脉即失胃气之和，石而無勾则死，石而有勾尚可病。", ["石"]], "21669": ["预后", "原文未出脉名，以「足少阴气绝」立论，谓少阴冬脉「伏行而濡滑骨髓」，气绝则骨不濡、肉不着骨，故「齿长而垢，发无泽」，为骨先死之候。此段从经脉气绝推骨枯发落，属肾绝危候，末言「戊笃已死，土胜水也」，以五行相胜定死期。", []], "21670": ["病机", "冬肾水旺，其脉「沉濡而滑」为平，沉应冬、濡滑为胃气与肾水相合。反得「微涩而短」是肺乘肾，母归子为虚邪，病易治；「弦细而长」肝乘肾，子乘母为实邪，自愈；「大而缓」脾乘肾，土克水为贼邪大逆，十死不治；「浮大而洪」心乘肾，火凌水为微邪，即瘥。以五行生克判轻重。", ["沉", "濡", "滑", "涩"]], "21671": ["主病", "原文以「左手关后尺中阴绝」为无肾脉，症见「足下热，两髀里急，精气竭少」，由劳倦耗精所致，刺足太阳治阳；「阴实」为肾实，症见「恍惚健忘，目视䀮䀮，耳聋怅怅善鸣」，刺足少阴治阴。此段虽未出脉名，以尺部阴阳绝实分肾之虚实，绝则精竭，实则邪壅。", []], "21672": ["病机", "原文以“阴绝”“阴实”论肾脉，非具体脉象描述。阴绝即肾脉不至，故“无肾脉”，主足逆冷上抢胸痛、梦魇等肾阳衰微、阴寒上逆之症；阴实为肾实，主骨疼腰脊痛、内寒热，乃寒邪或实邪客于少阴。二者从脉之有无虚实辨肾之病机，属脉诊分部主病之论。", []], "21673": ["预后", "肾脉沉细而紧，沉主里、细主虚、紧主寒，为少阴本脉。原文以至数分平、病、死：再至为平，三至曰离经病，四至脱精，五至死，六至命尽。脉沉细而紧而数至，示肾气渐衰、精脱之兆，故从至数判断预后吉凶，属死生之辨。", ["沉", "细", "紧"]], "21674": ["主病", "肾脉急甚为骨痿癫疾，微急为奔豚沉厥；大甚为阴痿，微大为石水；小甚为洞泄，微小为消瘅；滑甚为癃𤻊，涩甚为大痈。又“搏坚而长”主折腰，“软而散”主少血，“上坚而大”为肾痹。诸脉随急、大、小、滑、涩之变各主不同肾病，示肾脉失和则病候多端。", ["急", "坚", "长", "大"]], "21675": ["病机", "肾脉沉取大坚、浮取大紧，沉主里、坚紧主寒实。原文谓苦手足骨肿厥而阴不兴、腰脊痛少腹肿、心下有水气，得之浴水中身未干而合房及劳倦发之。此寒湿乘虚入肾，水气内停，阳气不达，故脉沉大坚紧而见肿厥、水气诸症。", ["沉", "大", "坚", "紧"]], "21676": ["预后", "肾病色黑气弱，吸吸少气、耳聋腰痛失精、饮食减少、膝以下清，为肾气虚衰。其脉沉滑而迟少，沉主里、滑为虚滑、迟少为阳气不足，脉症相应，故曰“为可治”。原文列内补散、建中汤、肾气丸等补泻灸刺，示脉证相符尚可调治。", ["沉", "滑", "迟"]], "21677": ["主病", "诊得肾积，脉沉而急。沉主里、急主痛，肾积结于少腹，故苦脊与腰相引痛、少腹里急；饥则见饱则减，示积块随气机而现；口干咽肿、目䀮䀮、骨中寒、髓厥善忘，皆肾积精亏、寒凝之候。脉沉急为肾积主脉。", ["沉", "急"]], "21678": ["预后", "肾积奔豚，脉当沉细而滑，沉细为肾虚，滑主积气；今反浮大，色当黑而反黄，为土克水之大逆，十死不治。原文以脉症色相合辨顺逆：脉沉细滑、色黑为顺，浮大、色黄为逆，示肾积见脾土克伐之象则预后凶险。", ["沉", "细", "滑", "浮"]], "21679": ["其他", "原文论冬水肾脉色黑，主足少阴脉，名曰太冲，述五十七穴及冬取井荥之理。冬者水始治，肾方闭，阳气衰少，阴气坚盛，太阳气伏沉，故取井以下阴气、取荥以通阳气。此段未出具体脉象，主在阐明肾脉应冬之生理与刺治原则。", []], "21680": ["其他", "此段专述足少阴肾脉的循行路径，从足小趾斜趋足心、出然骨、循内踝后，上贯脊属肾络膀胱，直行者上贯肝膈入肺、循喉咙挟舌本，支者从肺络心注胸中，并合足太阳为表里。全段为经脉循行描述，未涉及脉象指下形态与主病，故脉象要素为空，主旨归入其他，非主病或病机之论。", []], "21681": ["病机", "足少阴别络大钟主肾生病，实则膀胱热而闭癃，阳脉反逆大于寸口再倍，故见口热舌干、咽肿上气、心痛黄瘅等阳热之候；虚则膀胱寒而腰痛，阴脉反小于寸口，故见饥不欲食、面黑咳血、喘鸣善恐等虚寒之候。脉之大小逆于寸口，正示肾与膀胱虚实偏倾、阴阳不相顺接之病机。", ["大", "小"]], "21682": ["其他", "此段仅为篇目小注，标明本篇含脉八首、方四首、灸法一首，属文献编次之语，未载具体脉象形态与主病内容。原文无指下脉形可辨，故脉象要素为空，主旨归入其他，不能据以推断病机或症候，谨依原文存录，不作空泛引申。", []], "21683": ["主病", "左手尺中神门以后脉阴实，属足少阴肾经，实者邪热内盛。原文列舌燥咽肿、心烦咽干、喘咳汗出、小腹胀满、腰背强急、骨热、小便赤黄、好怒好忘、足下热疼、耳聋，皆肾实热循经上炎、下迫所致；《脉经》补膀胱胀闭、腰脊引痛，正合尺脉阴实主肾实热之病机。", ["实"]], "21684": ["主病", "右手尺中神门以后脉阴实，亦属足少阴肾经。实脉主邪实，肾经实热则见痹、身热心痛、脊胁相引痛、足逆热烦。身热与足逆热并见，是热郁于肾经而不得外达；脊胁相引痛，乃少阴之脉贯脊循胁之应。原文以脉阴实定肾实热，症候与脉象相合，故归主病。", ["实"]], "21685": ["主病", "左手尺中神门以后脉阴阳俱实，为足少阴与足太阳两经俱实。原文见脊强反抑、戴眼、气上抢心、脊痛不能自反侧，皆太阳经气壅实、少阴肾气逆上之象。阴阳俱实示表里两经邪气皆盛，故病名肾与膀胱俱实，脉实与脊强戴眼等症相应，属主病之论。", ["实"]], "21686": ["主病", "右手尺中神门以后脉阴阳俱实，亦为足少阴与足太阳俱实。原文见癫疾、头重与目相引、痛厥欲走、反眼、大风多汗，是太阳经实热上冲头目、少阴肾实扰及神明所致。阴阳俱实说明表里两经邪实俱盛，故以肾与膀胱俱实名之，脉症相印，归主病。", ["实"]], "21687": ["主病", "右手尺中神门以后脉阴虚，属足少阴肾经。虚脉主正气不足，肾虚寒则见心中闷、下重、足肿不可以按地。下重足肿为肾阳虚衰、水寒之气下注；不可按地则虚痛拒按之象。原文以脉阴虚定肾虚寒，脉虚与症候相应，故归主病，示少阴经气虚寒之病机。", ["虚"]], "21688": ["病机", "原文言“脉阴虚者”指右手尺中神门以后脉虚，属足少阴经虚寒；“脉代绝时不至”为代脉，主脏气衰微。肾阳虚衰，不能温煦下肢，故足胫小弱、足寒、上重下轻、行不可按地；阳虚寒凝，小腹胀满，上抢胸痛引胁下。此脉此症共示肾虚寒之病机。", ["虚", "代"]], "21689": ["病机", "原文“脉阴阳俱虚者”指右手尺中神门以后脉浮取沉取皆虚，为足少阴与太阳经俱虚。肾阳虚不能固摄则小便利；心肾阳虚，故心痛背寒；下焦虚寒，气化不利，则时时小腹满。脉虚与诸症相应，主肾膀胱俱虚之病机。", ["虚"]], "21690": ["病机", "原文“脉阴阳俱虚者”示足少阴与太阳经俱虚。肾阳虚衰，火不暖土，故时时苦洞泄、寒中泄；阳虚气陷，下重不自收篡反出；心肾阳虚，故心痛。脉虚与洞泄、下重、心痛并见，主肾膀胱俱虚、阳虚不固之病机。", ["虚"]], "21691": ["治法", "原文未出脉名，而言“治虚劳，阴阳失度，伤筋损脉”，以嘘吸短气、漏溢泻下、小便赤黄、阴下湿痒、腰脊如折、颜色堕落为症。此属虚劳阴阳两伤，筋脉受损，下元不固，故立补虚调阴阳之方，为治法条文。", []], "21692": ["病机", "原文论“精极”主五脏六腑病候，谓五脏六腑衰则形体皆极，眼视无明、齿焦发落、耳聋行步不正。又析阳邪害五脏、阴邪损六腑，阳实从阴引阳，阴虚从阳引阴，邪入五脏则咳、多涕唾、面肿气逆。全段阐精极之阴阳虚实病机，未出具体脉象。", []], "21693": ["治法", "原文为灸法条文，灸阳陵泉、阴陵泉、三阴交治梦泄精，末注“内踝上大脉，并四趾是”以定穴。大脉在此指内踝上明显可见之脉，非主病之脉。梦泄精属肾虚不固，灸三阴交等穴以固精，故归治法。", ["大"]], "21694": ["病机", "原文论“骨极”主肾，肾应骨。冬感邪为骨痹，内舍于肾，症见耳鸣色黑、牙齿苦痛、手足㾓疼、不能久立、屈伸不利。又分气阴则虚寒面肿垢黑，气阳则实热膀胱不通。全段辨骨极阴阳虚实病机，未出脉象。", []], "21695": ["病机", "原文言“肾脉逆小于寸口”，指肾脉（尺部）异常而小于寸口，为肾气不足、膀胱虚寒之象。阳虚寒凝，故腰痛；虚寒水气上逆，则胸中动。脉逆小与膀胱虚寒、腰痛胸中动相应，主肾与膀胱虚寒之病机。", ["逆", "小"]], "21696": ["治法", "本段论腰痛治法，以针决膝腰勾画中青赤络脉出血，并灸背脊竹度处。原文未出脉名，所述'青赤路脉'指络脉色赤，为瘀热壅滞之象，故刺络出血以泻其实。腰痛不得俯仰属经络气血不通，灸法随年壮以温通督脉。全段主旨为外治之法，非脉诊病机。", []], "21697": ["病机", "本段总论五劳六极七伤之成因，原文列志劳、思劳、忧劳、心劳、疲劳及气极、血极、筋极、骨极、髓极、精极，又言七伤各脏受损之症。其病机核心为'远思强虑''忧恚悲哀''喜乐过度''忿怒不解'等情志所伤，兼寒暄失节，致脏腑表里虚损。全段未及脉象，重在阐发虚损病机与病因。", []], "21698": ["其他", "本段为方药服法及效验记载，述六味药渍煮分服，'药入四肢百脉，似醉状是效'，并及无生姜以干姜酒渍代之。原文未出脉象，'百脉'乃泛称四肢血脉，非诊脉之脉。全段主旨属方药用法与服药反应，不涉病机脉理，故归其他。", []], "21699": ["病机", "本段明言'六绝之为病，皆起于大劳脉虚，外受风邪，内受寒热'。脉虚为正虚之象，大劳耗伤气血，故脉道空虚；虚而受风，寒热内侵，遂致手足疼痛、膝以下冷、腹中雷鸣、泄痢或闭、面目肿等症。五脏伤各有善惊、腹满喜噫、少精、少血、积聚等表现，皆由脉虚正衰、邪乘虚入所致，脉虚为全段病机之枢。", ["虚"]], "21700": ["病机", "本段述大风之病，得之饮酒中风、露卧湿地，寒从下入。原文谓'子精虚，脉寒，阴下湿茎消'，脉寒即脉象寒冷，主阳气衰微、寒湿内盛。寒邪下受，腰以下冷、不足无气，精虚阳弱，故见四肢不收、肩痛胫急、时寒时热、足腨如刀刺、恍惚时悲。脉寒正合寒湿伤阳、精虚失煦之病机。", ["寒"]], "21701": ["其他", "本段为丸药服法及效验记述，言服七日后四肢润泽、唇口赤、手足暖、音声清朗为验，十日长肌肉，药通中入脑鼻必酸疼。末引《古今录验》治丈夫五劳七伤诸症，阳气衰绝、阴气不行。原文未出脉象，'补十二经脉'乃泛论药效，非脉诊。全段属方药服验，故归其他。", []], "21702": ["病机", "本段述补虚益气方主治，原文谓'治五脏虚劳损伤阴痹，阴下湿痒或生疮，茎中痛，小便余沥，四肢嘘吸，阳气绝，阳脉伤'。其病机为五脏虚劳、阳气衰绝、阳脉受损，阴寒湿邪下注故阴下湿痒生疮，阳气不充故四肢嘘吸、小便余沥。'阳脉伤'指阳气伤损之脉，非具体脉象，全段重在虚劳阳衰病机。", []], "21703": ["其他", "本段仅为篇题'膀胱腑脉论第一'，无正文脉象与病机论述，无法据以分析脉理。既标'脉论'，当属脏腑经脉总论之篇目，然内容未展开，故脉象要素为空，主旨归入其他，不作病机推断。", []], "21704": ["其他", "此段仅存篇题「论一首脉四首」，未载具体脉象与病机文字，无法据以分析脉理。原文既无脉名描述，亦无症候对应，故脉象要素为空，主旨归入其他，不作无据推断。", []], "21705": ["病机", "原文言「左手关后尺中阳绝者，无膀胱脉也」，关后尺中候肾与膀胱，阳绝即该部阳气衰绝，故见逆冷、妇人月使不调或闭、男子失精尿有余沥。所取「足内踝下动脉」即太溪处动脉，为足少阴肾经所过，刺之以治阴，说明病机在肾阳不足、膀胱气化失司。", ["动"]], "21706": ["病机", "原文称「右手关后尺中阳绝者，无子户脉也」，右尺候命门与子户，阳绝则下焦虚寒，故见足逆寒、阴中寒、带下、绝产无子。此段未明写脉形，只言阳绝，实指该部脉气断绝无阳，病机属肾阳虚衰、胞宫失温，故列病机而不列具体脉象要素。", []], "21707": ["主病", "原文论膀胱病，见小腹偏肿而痛、按之欲小便而不得、肩上热，此为膀胱气化不利、湿热或气滞所致。文中两言「若脉陷」，陷即脉沉陷不起，说明邪在里、经气内陷，故取委中穴以通太阳经气。脉陷与足小趾外侧、胫踝后发热并见，提示病位在膀胱经。", ["沉"]], "21708": ["病机", "此段述足太阳经脉循行及所生病，末言「盛者则人迎大再倍于寸口」，以人迎大于寸口二倍判为太阳经气盛实。所举冲头痛、目似脱、项似拔、脊痛腰似折、腘如结、腨如裂等，皆太阳经气壅滞、筋脉不利之象，故以人迎大为据，说明经气盛实之病机。", ["大"]], "21709": ["其他", "此段仅存「脉四首方六首」之篇题，无具体脉象描述与症候文字，不能据以判定脉象要素或病机。原文既未言脉形，也未言主病，故脉象要素为空，主旨归入其他，避免凭空附会。", []], "21710": ["主病", "原文言「左手尺中神门以后脉阳实者，足太阳经也」，左尺神门后候膀胱，脉阳实即该部脉象实而有力，主膀胱实热。故见逆满、腰中痛、不可俯仰，腰为膀胱经所过，实热壅滞经气则痛而俯仰不利，与「膀胱实热」之诊断相应。", ["实"]], "21711": ["主病", "原文称「右手尺中神门以后脉阳实者，足太阳经也」，右尺神门后脉阳实有力，主膀胱实热。症见胞转不得小便、头眩痛烦满、脊背强，皆实热内结、膀胱气化受阻、太阳经气不利之象，故名曰膀胱实热，脉实与症相符。", ["实"]], "21712": ["病机", "原文言“左手尺中神门以后脉阳虚者，足太阳经也”，尺中候肾，神门以后属足太阳膀胱经分野。脉阳虚即阳气不足，膀胱经气失于温煦，故见脚中筋急、腹中痛引腰背、转筋恶风偏枯、外踝后痛等症，总由膀胱虚冷、经气不利所致，非外邪实滞。", ["虚"]], "21713": ["病机", "原文“右手尺中神门以后脉阳虚者，足太阳经也”，右尺候命门相火，脉阳虚则膀胱经阳气衰少。阳气不能温养肌肉则肌肉振动，筋脉失煦则脚中筋急，清阳不升则耳聋忽忽不闻，卫外不固则恶风飕飕作声，皆膀胱虚冷之候。", ["虚"]], "21714": ["其他", "此段仅为“三焦脉论第四”篇题，未载具体脉象与病机文字，故脉象要素为空。篇题标示下文将论三焦脉候，本身不主病、不涉症候，仅作篇章归类，不能据以推断病机。", []], "21715": ["病机", "此段论三焦“有名无形”，主五脏六腑往还神道，和利精气、决通水道、息气肠胃之间；又言营出中焦、卫出上焦，三焦与膀胱合而不同，同号孤腑。全段阐发三焦生理功能与形质，未及具体脉象，故脉象要素为空，主旨属病机理论。", []], "21716": ["主病", "原文述三焦病候：腹胀气满、少腹尤坚、不得小便、窘急，水溢则为水、留则为胀；候在足太阳之外大络，太阳少阳之间亦见于脉，取委阳。此以症候与经络定位言三焦病，未出具体脉名，故脉象要素为空，主旨为三焦病之主病与治法取穴。", []], "21717": ["主病", "原文“小腹肿痛不得小便，邪在三焦”，视太阳大络之结脉，与厥阴小络结而血者，肿上及胃脘，取三里。结脉示邪气结聚、络脉瘀阻，故小腹肿痛、小便不通；结而血者，瘀血内停。脉结在此主邪结三焦、络瘀之病机。", ["结"]], "21718": ["病机", "此段详述手少阳三焦经脉循行及是动、所生病：耳聋𪸩𪸩焞焞、咽肿喉痹、汗出目锐眦痛、颊肿、耳后肩臑肘臂外痛、小指次指不用。末言盛则泻、虚则补、热则疾、寒则留、陷下则灸，并以人迎寸口比较辨虚实。全段论经脉病机与治法，未出具体脉象。", []], "21719": ["治法", "原文“通脉泻热治上焦”，针对饮食下胃、胃气未定而汗出、面背身中皆热之“漏气”证，立通脉泻热之法。此段以治法为主，未载具体脉象，故脉象要素为空；其病机为胃气未定、热郁上焦、腠理开泄而汗出。", []], "21720": ["病机", "本段论中焦营气化生及脾胃病机，未及脉象。原文言中焦“主化水谷之味，秘糟粕，蒸津液，化为精微”，营气“独行于经隧”。实则生热而闭塞不通，虚则生寒而腹痛洞泄，主脾胃之病。血与气异名同类，脱血无汗、夺汗无血，示神气精气互根。全段以营气化生与脾胃虚实为病机核心。", []], "21721": ["治法", "霍乱吐下后“内热汗不出，不转筋脉急数者”，脉急数主热盛于里，急为热灼筋脉之象，数则热势急迫。因吐下伤津，热郁不得外达，故汗不出而脉急数。治以犀角合葛根饮，清解内热、生津舒筋。此段以脉急数辨内热之机，属霍乱变证之治法。", ["急", "数"]], "21722": ["病机", "霍乱吐利后“其脉微涩”，微为阳气衰微，涩为津血耗伤、脉道不利。本是霍乱吐利伤津耗气，今见伤寒表证，脉微涩示正虚邪陷，至阴经转入阴必利。原文强调“本呕下利者，不可治也”，脉微涩反映脾胃虚寒、津气两伤之病机，故吐多转筋、脐上筑为肾气动。", ["微", "涩"]], "21723": ["主病", "“多寒，手足厥冷，脉细欲绝”，细为脉道收缩、阴血不足，欲绝则阳气衰微不能鼓动。寒邪内盛，阳气不达四末，故手足厥冷；脉细欲绝正是寒盛阳衰、气血内竭之象。此脉主寒厥之病，治当温阳散寒、通脉回逆。", ["细"]], "21724": ["病机", "吐下汗出、小便复利、下利清谷，里寒外热而“脉微欲绝”，微为阳气虚衰，欲绝则阳亡在即。阴寒内盛，虚阳外浮，故发热恶寒、四肢拘急、手足厥冷。脉微欲绝紧扣里寒外热之病机，示阳气衰微欲脱，治当回阳救逆。", ["微"]], "21725": ["治法", "本段仅列“通脉四逆汤”方名，未出脉象及症候。联系前后文，通脉四逆汤为少阴病阴盛格阳、脉微欲绝而设，功在破阴回阳、通达内外。此段属治法方药，无脉象可析，故脉象要素为空。", []], "21726": ["病机", "吐利已断而汗出厥逆、四肢拘急不解，“脉微欲绝”，微为阳气衰微，欲绝则阳亡之势未回。吐利虽止，但津血耗伤、阳气外脱，故汗出而厥、拘急不解。脉微欲绝示阴寒内盛、阳气欲竭之病机，治当通脉四逆回阳救逆。", ["微"]], "21727": ["治法", "本段述通脉四逆汤服法与加减，“脉出即愈”以脉象判断阳气来复，非论病脉。方后加减针对面色赤、腹中痛、呕逆、咽痛、利止脉不出等症，皆随证化裁。全段属治法范畴，无具体脉象描述，故脉象要素为空。", []], "21728": ["治法", "原文未识脉名，仅言“脉不通”，指毒冷霍乱吐利致阳气闭绝、血脉不通之危候。转筋、肉冷、汗出、手足指肿、喘息垂死、语音不出，皆阴寒内盛、阳气欲脱之象。脉不通示寒凝气闭、血行不畅，故以汤药随吐续服并灸法温通阳气，取瘥乃止，属急救回阳通脉之法。", []], "21729": ["病机", "先服石药人因霍乱吐下，热药虽止吐利而变虚，心烦、手足热、口干燥欲水、呕逆迷闷，脉急数者，示石药余热未清、毒热内扰，兼吐下伤津而虚热浮动。及时行热病后毒未尽，复因霍乱吐下仍发热、心胸欲裂，亦属热毒壅遏。脉急数正应热盛毒留之机，故以解之方清解余毒。", ["急", "数"]], "21730": ["主病", "中热霍乱暴利，心烦脉数，欲得冷水，脉数主热。暴利伤津而热邪内盛，故心烦、渴欲冷水。此段以脉数点明中热霍乱之病性属热，热扰心神则烦，热盛耗津则欲冷饮。脉数与心烦、暴利、欲冷水相应，示热邪内迫、津液骤伤之病机，故治以清热之方。", ["数"]], "21731": ["病机", "论霍乱灸法，若吐下不禁，两手阴阳脉俱疾数者，灸心蔽骨下三寸及脐下三寸。疾数之脉示吐下不禁、正气暴脱而邪热仍盛，脉行急迫，阴阳之气有离决之势。原文以“吐下不禁”与“俱疾数”并见，说明津液骤亡、虚阳躁动之病机，故用重灸温固阳气、急救垂危。", ["疾", "数"]], "21732": ["主病", "原文未识脉名，仅言“脉如连珠”，形容脉来滑数流利、连续不断，如珠走盘。面黄、手足黄、咽中干燥、短气，示热邪内蕴、津液耗伤，湿热或虚热上蒸则面黄，津不上承则咽干，气耗则短气。脉如连珠应滑数之象，主热盛津伤、气机不畅，故以除热止渴利、补养为治。", []], "21733": ["病机", "原文未识脉名，仅言“阴脉绝”，指尺部阴脉沉伏不至，阴液亏竭、肾阴衰绝之象。消渴日久，阴津耗竭，胃气上逆而反吐食，故见阴脉绝与胃反吐食并见。阴脉绝说明肾阴枯涸、虚火上逆，胃失和降，属消渴重证之病机，故以滋阴降逆、和胃止吐为治。", []], "21734": ["病机", "虚热之人多服石散，石热伤阴耗气，又当风取冷患脚气，喜发动兼渴消肾，脉细弱。细弱之脉主气血两虚、阴阳俱损，正合虚热日久、石散耗伤、脚气频发之候。脉细弱说明正气已虚、阴血不足，虚热内扰则渴，肾气不固则消，故以补虚清热、兼顾脚气为治。", ["细", "弱"]], "21735": ["病机", "女人房劳伤肾，肾中有热，小便难不利，小腹满痛，脉沉细者。沉细之脉主里虚，沉为病在里，细为阴血不足。房劳耗伤肾阴，虚热内结下焦，气化不利则小便难、小腹满痛。脉沉细正应肾虚热结、阴血亏耗之病机，故加猪肾以补肾利水，兼清肾中虚热。", ["沉", "细"]], "21736": ["治法", "此段为治淋方药组成，榆皮、车前子、冬瓜子、鲤鱼齿、桃胶、通草、地脉、瞿麦诸药合用，通草、瞿麦、车前子利水通淋，榆皮滑窍，冬瓜子排脓，鲤鱼齿、桃胶散结。全方着眼于水道不通、湿热蕴结之五淋，属治法范畴，原文未及脉象，故脉素从缺。", []], "21737": ["治法", "此段言五淋不得小便之灸法，取悬泉（中封别名）及大敦。原文以“小脉上是”定悬泉穴位，小脉在此为定位标志而非主病之脉，然小脉应指细弱，与淋证日久、水道不利、正气不足之病机相合。灸法温通下焦，助气化以利小便，故归治法。", ["小"]], "21738": ["病机", "此段论水病难治之由，指出“百脉之中，气水俱实”，治者欲泻之，而羊头蹄极补反助水邪，葶苈久服令人大虚，故水病非久虚不得绝其根本。原文以“气水俱实”概括水病脉道壅实之机，又辨蛊胀腹满不肿与水胀四肢面目俱肿之别，强调误治杀人，主旨在水病病机与禁忌。", []], "21739": ["病机", "此段辨水与肤胀、鼓胀、肠覃、石瘕之别。水病“颈脉动”为水气上逆、脉道不利之征；肤胀寒气客于皮肤，脉自浮；水病脉亦浮，示水溢肌肤；肠覃、石瘕则脉沉迟，示寒凝胞宫肠外、气血结滞。原文以脉之动、浮、沉迟对举，说明水气在表在里、寒凝气滞之不同病机。", ["动", "浮", "沉", "迟"]], "21740": ["病机", "此段论禀形摄养失度，四时暴气卒然伤人，入于四体，顿折皮肤，流注经脉，使“腠理壅隔，营卫结滞，阴阳之气不得宣泄”，遂变痈疽疔毒恶疮诸肿。原文以营卫结滞、气不得泄为痈肿病机核心，强调早识疔肿，未涉脉象，故脉素从缺，主旨归病机。", []], "21741": ["预后", "此段言痈肿著于口中颊边舌上，赤黑如珠，碜痛应心，乃秋冬寒毒久结皮中，日久“流入诸脉数道”，如箭入身。脉数道指邪毒流窜诸脉，数脉示毒热炽盛；若眼中见火、神昏口干心烦，则毒攻心神，预后凶险，死不旋踵。原文以脉数道言邪毒扩散之势，归预后。", ["数"]], "21742": ["其他", "此段为篇目凡例，标明“脉七首论一首方八十七首禁法二首灸法三首”，属书籍编次体例之记录，非论脉理病机。原文未出具体脉象，亦无病候论述，故脉素从缺，主旨归其他，不作病机推演。", []], "21743": ["主病", "此段以“脉数身无热即有内痈”立论。数脉主热，身无表热而脉反数，说明热邪不在肌表而蕴结于内，腐肉成痈，故曰内痈。原文以脉数与身无热对举，突出热郁于里、气血壅聚成痈之病机，属主病范畴，数脉为内痈之重要凭据。", ["数"]], "21744": ["病机", "浮数脉主表热，热盛本当发热，今反洗洗恶寒，乃热毒内壅、营卫不通，故恶寒而非表寒。若有痛处，为热毒聚于局部，气血壅滞，将结为痈。脉浮数应发热而反恶寒，说明热郁于内，不得外达，痛处即痈肿所在。", ["浮", "数"]], "21745": ["病机", "脉浮而数，浮为在表，数为热，身体无热而形默默，是热郁于内，不显于外。胃中微燥，热灼津液；不知痛处，热毒深伏未定。热壅营卫，久必结为痈肿。此脉数而身无热，正说明热伏于里，将发痈脓。", ["浮", "数"]], "21746": ["病机", "脉微而迟，阳虚不能温煦，故必发热，此为虚阳外浮；脉弱而数，弱为气衰，数为热，气衰热郁，故振寒。营卫不和，热毒内蕴，当发痈肿。微迟弱数并见，示正气不足而热毒结聚，痈肿将成。", ["微", "迟", "弱", "数"]], "21747": ["病机", "滑为实，数为热，滑主营，数主卫，营卫相逢，热毒壅结，即结为痈。热之所过，血肉腐败，即为痈脓。身有痛处，时时苦有疮，是热毒外发之征。脉滑数示实热内盛，营卫壅滞，痈脓已成。", ["滑", "数"]], "21748": ["病机", "寸口脉微而涩，微为气衰，涩为血少，法当亡血或汗出。设不汗出，则当身有疮，被刀器所伤，亡血之故。脉微涩主气血两虚，亡血伤津，故见疮疡失血之候。", ["微", "涩"]], "21749": ["病机", "趺阳脉滑而数，滑为实，数为热，热实下注，法当下重少阴。少阴脉滑而数，热毒下迫前阴，妇人阴中生疮。滑数脉主湿热下注，壅结阴部，故见下重、生疮之症。", ["滑", "数"]], "21750": ["治法", "本段论痈破后调治，强调「俟筋脉平复，乃可任意」，以脉平复为向愈标准。新肉易伤，伤则里溃，溃则重发，故当断房室、忌风冷、勿劳烦。又辨风毒似痈者勿针，服升麻汤外摩膏；破后败坏不瘥，用猪蹄汤洗，恶肉净后敷生肉膏，令好肉速生。", []], "21751": ["病机", "经云血气俱涩不行，壅结为痈疽。又阳气溱集，寒化为热，热盛肉腐为脓。由体有热，被寒冷搏之，而脉凝结不行，热气壅结成痈疽。脉涩结示寒热搏结、气血壅滞，故成痈疽。治分冷未成热时用冷药贴敷，热已成则消热令不成脓。", ["涩", "结"]], "21752": ["治法", "此段为外敷内服方药煎服法，未及脉象。原文述\"取快利\"，意在通利恶肉恶脉、恶核风结肿气痛，属外疡内消之治法，与脉诊无涉，故脉象要素为空。", []], "21753": ["病机", "原文言发背痈肿\"因大风或结气在内，经脉闭塞\"，至夏月出攻于背，久则\"积聚作脓血为疮内漏\"。指出风邪与结气内闭经脉、蓄久化热成脓之病机，全段未载脉象，故脉象要素为空。", []], "21754": ["病机", "论瘭疽\"毒散，逐脉入脏杀人\"，其毒\"根深至肌\"，能烂坏筋骨，著于十指。原文以\"逐脉\"言毒邪循脉内攻之径，强调热毒深陷、入脏则危，治法专\"去其热取瘥\"，未出脉象，故脉象要素为空。", []], "21755": ["病机", "代指\"先肿焮热痛，色不黯，缘爪甲边结脓\"，属热毒结聚；恶肉病则由\"春冬时受恶风入肌脉中\"变成。原文以\"入肌脉中\"明风毒客于肌脉之病机，热盛者服漏芦汤，未言脉象，故脉象要素为空。", []], "21756": ["病机", "赤脉病\"身上忽有赤脉络起陇耸如死蚯蚓之状，视之如有水在脉中\"，原文断为\"春冬受恶风入络脉中，其血肉瘀所作\"，即风邪入络、血瘀脉中而成。全段未载脉象，故脉象要素为空。", []], "21757": ["病机", "㾫病\"赤脉起如编绳，急痛壮热\"，原文谓\"久劳热气盛为湿凉所折，气结筋中成此病\"，即热为湿凉所遏、气结筋脉。久则溃脓筋挛，或作趺病，主以漏芦汤泻热，未出脉象，故脉象要素为空。", []], "21758": ["预后", "论九漏根在于脏、末出于颈腋，\"浮于脉中而未著于肌肉\"者易去。决死生则\"反其目，视其中，有赤脉从上下贯瞳子\"，以一脉、二脉、三脉计岁断死，\"赤脉不下贯瞳子者可治\"。此以目赤脉贯瞳判预后，非言脉象，故脉象要素为空。", []], "21759": ["病机", "项边腋下先作瘰疬者\"欲作漏\"，漏核\"累累然作疬子，有核在两颈及腋下，不痛不热\"，属寒热毒气堤留于脉、结核成漏之病机，未破者火针针著核中。原文未载脉象，故脉象要素为空。", []], "21760": ["病机", "原文未出脉名，仅言「濯濯脉转」，指颈部漏疮处脉动濯濯、转动不宁，属转脉漏之征。其病始发颈项，症见惊惕、身振寒热，原文归因「惊卧失枕」，根在小肠（或作心），说明惊扰气乱、络脉失和而发漏，脉转即络脉动摇之象，非平脉之常。", []], "21761": ["治法", "本段全为灸法取穴，未及脉象。所列寒热、颈颌肿、腋下肿、马刀瘘、喉痹、四肢不举等，皆瘰疬漏疮兼症，取肩井、天池、后谿、阳辅、申脉、临泣、丘墟、太冲、大迎等穴分经施治，示辨经取穴之法，非以脉断病，故脉象要素为空。", []], "21762": ["治法", "原文专述瘰疬外灸之法，以独头蒜贴疬上艾灸，取热勿破，七壮易蒜；又灸胯里患处、五里、人迎、耳后发际直脉及腋后纹上。全段未言脉，主旨在外治灸法消散肉结，属瘰疬痈疖之治法，故不列脉象。", []], "21763": ["主病", "肠痈小腹重强、按痛、汗出恶寒、身皮甲错、腹皮急，脉数者热盛肉腐，小有脓；脉迟紧者热未蒸腐、血瘀未成脓。数主热、迟紧主寒凝血脉，故以脉之数与迟紧辨脓成未成，甚则腹胀水声、脓从脐出，皆痈溃之候。", ["数", "迟", "紧"]], "21764": ["病机", "寸口脉滑而数，滑为实为荣，数为热为卫，荣卫相干、血为浊败，故小腹痞坚、小便涩、汗出恶寒而脓已成。设脉迟紧，则热未化腐、血瘀不行，为瘀血未成脓，血下则愈。以滑数辨脓成、迟紧辨瘀血，正是肠痈脓血之病机分界。", ["滑", "数", "迟", "紧"]], "21765": ["主病", "肠痈小腹痞坚、色白坚大如掌热、自汗出，脉迟坚者热未蒸腐、脓未成，可下之当有血；脉数则热盛腐肉，脓已成而不复，亦可下。迟坚与数对举，示以脉之迟数坚软断脓成未成，为肠痈可下之凭据，非泛论脉也。", ["迟", "坚", "数"]], "21766": ["妇人", "本段论产后乳汁蓄积不去，恶汁内引热温壮、结坚牵掣痛、大渴引饮、乳急痛手不得近，成妒乳而非痈。原文未出脉，主旨在妇人产后乳疾之辨与灸鱼际、内服连翘汤、外涂小豆等法，并及乳头浅疮妒乳之治，故脉象要素为空。", []], "21767": ["主病", "本段列五痔——牡痔、牝痔、脉痔、肠痔、血痔，各述肛边鼠乳溃脓、肿痛生疮、疮痒痛、核痛寒热、便血清血等症，并出蛇蜕皮、鳖甲、猬皮、悬蹄甲、蜂房分主之药。全段未言脉，以症候辨痔之类型而施治，故脉象要素为空。", []], "21768": ["病机", "原文言\"卒死无脉，无他形候，阴阳俱竭故也\"，指出无脉非单一脏病，而是阴阳气血俱竭、脉道无以为继。无他形候说明非外邪闭阻，而是正气骤脱，脉气不能鼓动。此属危候，脉绝即阴阳离决之象，故治当急救回阳复脉，而非寻常辨证。", []], "21769": ["病机", "原文述饮酒房劳虚受热，积日不食，又四月热中饮酒不已，\"酒入百脉，心气虚，令人错谬失常\"。酒性湿热，入百脉则扰动血脉，房劳伤精、不食伤中，心气因虚而神失所养，故见错谬失常。此段以病机言酒热乘虚入脉、心气虚馁致神志失常，非论脉形。", []], "21770": ["病机", "原文论\"咸走血\"，咸入胃后其气注于诸脉，脉为血之所走，咸与血相得则\"血凝\"，凝则胃中汁泣而胃干，咽路焦故舌干喜渴。此以咸味过食伤血、血凝津泣解释口渴病机，强调血脉为中焦之道，咸入走血而致凝泣，非脉象本身。", []], "21771": ["其他", "原文列\"五脏所合法\"：肝合筋荣爪、心合脉荣色、脾合肉荣唇、肺合皮荣毛、肾合骨荣发。此段言五脏与形体组织相合及荣华外候，其\"心合脉\"仅说明脉为心所主之体，非论脉象主病，故归其他，不取脉象要素。", []], "21772": ["病机", "原文列五脏食忌：多食酸则皮槁毛夭，多食苦则筋缩爪枯，多食甘则骨痛发落，多食辛则肉胝唇寒，\"多食咸则脉凝泣而色变\"。此以五味偏胜伤其所合之脏与体，咸走血而致脉凝泣、色变，说明过食咸使血脉凝涩、荣色异常的病机，非直接论脉形。", []], "21773": ["其他", "原文述梅实味酸平涩无毒，能下气除热烦满、安心、去青黑痣恶疾，止下利好唾口干，\"利筋脉\"，多食坏人齿。此属本草食疗条目，言梅实功用及过食之害，\"利筋脉\"为药效描述，非脉象主病，故不取脉象要素。", []], "21774": ["病机", "原文言林檎味酸苦平涩无毒，止渴好唾，\"不可多食，令人百脉弱\"。脉弱为气血不足、脉道失充之象，多食林檎酸涩收敛，损及气血，使百脉失养而弱。此段以\"百脉弱\"说明过食酸涩致脉气虚弱、血行无力之病机，与倦怠乏力相应。", ["弱"]], "21775": ["其他", "原文述白麻子味甘平无毒，宜肝、补中益气、肥健不老，治中风汗出、逐水利小便、破积血风毒肿，\"复血脉\"，产后乳余疾。此为本草条目，言白麻子补益及活血利水之功，\"复血脉\"指恢复血脉功能，非脉象主病，故不取脉象要素。", []], "21776": ["其他", "本段为沙牛髓及牛肝、胆、肉之食疗药性，非论脉。原文称髓\"通十二经脉，理三焦约\"，是言药力通行经脉、调畅三焦，非脉象主病。其\"益气力，止泄利，去消渴\"皆从补中温骨髓取效；\"不可常食，发宿病\"则示食养有节，与脉诊病机无涉。", []], "21777": ["其他", "本段载野马阴茎与肉之性用，未涉脉象。阴茎味酸咸温，主\"阴痿缩少精\"，是从温补下元立论；肉主\"筋脉不能自收，周痹肌不仁\"，乃言其治筋脉弛纵、痹而不仁之症，非据脉以断病。\"病死者不任用\"属用药禁忌，与脉学无直接关联。", []], "21778": ["其他", "本段罗列豚卵、豚肉、猪蹄、脑、心、肾、肝、肺、肚、肠等诸品主治，属食疗药性，未及脉象。豚卵主\"寒热奔豚，五癃邪气挛缩\"，心主\"虚悸气逆，妇人产后中风\"，皆从脏腑症候言药效；\"豚肉有小毒，不可久食\"则示食用宜忌，非脉诊病机。", []], "21779": ["其他", "本段述鹿头肉、茎筋、蹄肉、骨、髓、肾、肉、角之主治，未言脉象。髓主\"伤中脉绝，筋急痛\"，此处\"脉绝\"指血脉虚竭之症，非脉象；肉生者敷\"中风口僻不正\"，角主\"强骨髓，补绝伤\"，皆属药性主治。末言白鹿肉发恶疮，为食用禁忌。", []], "21780": ["病机", "本段虽无脉名，然\"精气薄恶，血脉不充\"直指病机根本：王侯卿士纵酒房劳，耗竭精血，故血脉空虚；又\"生产不时，字育太早\"\"童孺擅气\"\"疾病构精\"，使胎元怯弱，\"胎伤孩病而脆\"。层层相生，病病相孕，终致\"少百岁之人\"。其旨在于纵欲耗精则血脉不充、禀赋脆弱，与脉学之虚损脉理相通。", []], "21781": ["其他", "本段论养性之道，主\"小劳\"而忌\"大疲\"，以流水户枢为喻，明运动不腐之理。所列\"久视伤血，久卧伤气，久立伤骨，久坐伤肉，久行伤筋\"，言过用则伤形；\"十二少\"为摄生都契，\"多思则神殆\"示七情耗神。全段属养生调摄，未涉脉象主病，故归其他。", []], "21782": ["其他", "本段主干为节饮食、慎起居之养生法，论\"先饥而食，先渴而饮\"\"食欲数而少\"及五味偏伤、食毕漱口等，均非脉诊。题注脉象\"屋漏\"，屋漏脉乃胃气衰败、脉来良久一至之死脉象，与本段饮食调养之文不相属，疑为后人标注错置，故仅存脉名而不据以论病机。", ["屋漏"]], "21783": ["其他", "本段详述地黄选种、深耕、作畦、耘壅、掘取、蒸晒及绞汁再蒸之法，属药材种植炮制，与脉诊无关。文中\"有筋脉\"指地黄根中筋络未蒸透，非人身脉象；\"赤色虚软者\"言择种标准。全段无病机脉理可析，故列其他。", []], "21784": ["其他", "本段为服食方药后的效验描述，非脉诊内容。文中'血脉充盛'指药后气血充盈的外在征象，非指具体脉象；'面色悦泽''耳目聪明'等皆属服药后身体机能改善之候，与脉象主病无关，故不取脉象要素，亦不归入主病、病机等脉学范畴。", []], "21785": ["其他", "本段论房中养生与年岁的关系，强调四十以上气力衰退、众病蜂起，主张节欲养生，未满四十不可服房中补药，否则'精髓枯竭'。全段无脉象描述，'气力衰退'为全身状态而非脉候，故脉象要素为空，主旨属养生议论，归入其他。", []], "21786": ["其他", "本段仅为卷目题名'卷二十八脉法'，无具体脉象描述与病机论述，属篇章标目，不能据以分析脉象主病，故脉象要素为空，category归入其他，不作病机推断。", []], "21787": ["平脉", "本段为篇题'平脉大法第一'，标示该篇专论平脉之大法。'大法'指诊脉之总则，非指脉形洪大之'大'脉；然题中'脉大法'字样含'大'字，姑取为脉象要素。全段无具体脉症描述，主旨属平脉诊法总纲，故归平脉。", ["大"]], "21788": ["其他", "本段论医者当专心精研脉道，'寤寐俯仰，不与常人同域'，强调脉学为医之大业，未涉具体脉象与病机。文中无浮沉迟数等脉形描述，故脉象要素为空；主旨为劝学立论，非主病、病机、平脉等，归入其他。", []], "21789": ["平脉", "本段引经论诊脉之法，主张平旦诊脉，此时'阴气未动，阳气未散，饮食未进，经脉未盛，络脉调匀，气血未乱'，故可诊有过之脉。文中'经脉未盛''络脉调匀'为诊脉时机之生理状态描述，非具体脉象，故脉象要素为空；主旨为平旦诊脉之常法，归平脉。", []], "21790": ["平脉", "本段论平脉诊法，先诊寸口，'初重指切骨'后渐举指'与皮毛相得'，于轻重之间随人强弱肥瘦消息进退，'称其浮沉诸类应于四时五行'。文中明言浮沉，指举按所得脉位浅深，须与四时五脏相应，属平脉诊察之常法，故取浮、沉，归平脉。", ["浮", "沉"]], "21791": ["平脉", "本段论人禀气有躁静，'气脉流动'随性情而异，提出一呼脉再至、一吸脉再至、呼吸定息复一至，合为五至，'此为平和中适者也'，并以昼夜四时长短为喻。文中'气脉流动'为描述性语，非具体脉形，故脉象要素为空；主旨辨平脉至数之常，归平脉。", []], "21792": ["平脉", "原文强调诊脉当先调息，以呼吸定息计脉数，五至为平人。脉数在此指脉搏至数，通过盈缩判断病源。五至为常，过与不及皆可寻状论病，体现以息数测平脉、辨病源的思想。", ["数"]], "21793": ["其他", "此段专论三部脉之部位与尺寸分关之法，从肘腕横纹至鱼际后纹分寸关尺，说明寸口骨高、阴得尺内一寸、阳得寸内九分。全段为脉位制度说明，未涉具体脉象主病，故脉象要素为空。", []], "21794": ["病机", "原文以寸口为脉之大会、手太阴之动脉，分寸关尺主上中下三焦，象三才天地人。十二经皆有动脉而独取寸口，因寸口决五脏六腑死生吉凶。动脉在此指手太阴脉动之处，说明寸口为荣卫循行大会，可候全身病机。", ["动"]], "21795": ["其他", "此段仅为篇题“诊五脏脉轻重法第二”，无具体脉象描述与病机论述，故脉象要素为空。其主旨在于标示将论五脏脉之轻重指法，属篇章结构，不涉主病兼症。", []], "21796": ["病机", "原文以菽数轻重分五脏脉：心肺俱浮，浮大散者心，浮短涩者肺；肾肝俱沉，牢长者肝，濡大举指来实者肾；脾脉在中州。此以指下轻重与脉形别五脏之气，说明脉象与脏气相应之病机。", ["浮", "大", "散", "短"]], "21797": ["病机", "此段为脉象定义总汇，逐一描述浮沉涩滑洪细微弦紧迟数缓弱动伏芤软虚实促结代散革等脉之指下形态，如浮举有余按不足、沉举不足按有余、弦如张弓弦、紧如切绳。旨在立脉名、明脉形，为辨病机之基础。", ["浮", "沉", "涩", "滑"]], "21798": ["其他", "此段仅为篇题“五脏脉所属第四”，无具体脉象与病机内容，故脉象要素为空。其作用在于标示将论五脏与脉之所属关系，属篇章分类标题，不涉主病兼症。", []], "21799": ["其他", "此段仅存“脉法赞云”四字，为引文起首，无脉象描述与病机论述，故脉象要素为空。其内容不足以判断主旨，仅属文献残句，不涉具体脉诊分析。", []], "21800": ["病机", "本段论寸口分部与脏腑对应，左主心肝、右主脾肺，肾命门在尺，关前一分为人迎气口，神门在关后。强调“人无二脉，病死不愈”，说明脉气根本不可断绝；又“诸经损减，各随其部”示脉象变化可反映相应脏腑损伤。春弦秋浮冬沉夏洪为平脉应时，非病脉，故脉象要素不取具体脉名。", []], "21801": ["病机", "本段以脉数在腑、脉迟在脏分表里寒热；脉长而弦病在肝，脉小血少病在心，脉下坚上虚病在脾胃，脉滑微浮病在肺，脉大而坚病在肾。又脉滑多血少气、脉涩少血多气，脉大血气俱多、脉小血气俱少，脉沉细滑疾者热、脉迟紧为寒，皆以脉象测气血盛衰与病位。", ["数", "迟", "长", "弦"]], "21802": ["其他", "本段仅为“平寸口脉主对法”标题，无具体脉象与病机论述，故脉象要素为空，主旨归为其他。原文未展开脉症对应内容，不能凭空分析病机。", []], "21803": ["主病", "本段以寸口脉滑而迟、不沉不浮、不长不短为无病；中手短者头痛，中手长者足胫痛，促上击者肩背痛。脉沉而坚病在中，浮而盛病在外；沉而弱主寒热疝瘕小腹痛；沉而紧苦心下有寒时痛有积邪；沉而滑为胸中有水气、面目肿、风水。皆以脉之浮沉迟滑坚弱定病位与病性。", ["滑", "迟", "沉", "坚"]], "21804": ["其他", "本段仅为“平关脉主对法”标题，无具体脉象与病机内容，故脉象要素为空，主旨归为其他。原文未提供可分析的脉症条文，不能臆测病机。", []], "21805": ["主病", "本段论关上脉主病：浮而大风在胃中，张口肩息、食欲呕；微浮积热在胃中、呕吐蛔虫；滑而大小不均必吐逆，病方欲来；紧而滑者蛔动；弦而长有痛如刀刺在脐左右；涩而坚大而实按之不减为中焦实、伏结在脾肺气塞、实热在胃中。皆以关脉候中焦脾胃病。", ["浮", "大", "滑", "紧"]], "21806": ["其他", "本段仅为“平尺脉主对法”标题，无具体脉象与病机论述，故脉象要素为空，主旨归为其他。原文未展开尺脉主病内容，不能凭空分析。", []], "21807": ["主病", "本段论尺脉主病：尺浮为客阳在下焦；尺弱为下焦冷、无阳气、上热冲头面；尺弱寸强胃络脉伤；尺偏滑疾面赤如醉、外热；尺细微溏泄冷利；尺虚小足胫寒痿痹脚疼；尺涩下血不利多汗；尺沉而滑寸白虫；尺细而急筋挛痹不能行；尺大热在脬中小便赤痛。皆以尺部候下焦及肾与膀胱病。", ["浮", "弱", "滑", "细"]], "21808": ["主病", "原文以“脉来细软附骨者，为积也”定积脉之形，细软附骨说明积块深伏、气血被阻；又言“脉弦紧而细微者，症也”，弦紧主寒、主痛、主积，细微示正气渐伤。故本段脉象主寒痹、症瘕、积聚，与腹中急痛、腰背相引、寒疝等症相应，总由寒凝气血、积久成形所致。", ["细", "软", "弦", "紧"]], "21809": ["主病", "原文以“寸弦紧”“关弦紧”“尺弦紧”分候积之部位，又谓“弦紧，亦为积，为寒痹，为疝痛”，说明弦紧为寒积内结、气机收引之象。至“脉弦而伏者，腹中有症不可转也，必死不治”，弦伏示积结深痼、阳气不通；细沉而直主痈肿伏梁，亦属积类。全段脉象主积、寒痹、疝痛，兼及痈肿伏梁。", ["弦", "紧", "伏", "细"]], "21810": ["病机", "原文以浮、沉、长、短、滑、涩分阴阳，谓“浮、滑、长者，阳也；沉、涩、短者，阴也”，并以“脉来沉而滑”为一阴一阳、“沉滑而长”为一阴二阳、“浮滑而长，时一沉”为一阴三阳，说明脉象阴阳相兼之机。此段非主一病，而在阐明脉之阴阳组合以测病机属性，故归病机。", ["浮", "沉", "滑", "涩"]], "21811": ["病机", "原文以“浮之损小，沉之实大”为阴盛阳虚，“沉之损小，浮之实大”为阳盛阴虚，又列浮、大、数、动、长、滑为阳，沉、涩、弦、弱、短、微为阴，说明脉之浮沉大小可辨阴阳虚实。更言“阳数即吐，阴微即下。阳弦则头痛，阴弦则腹痛”，以脉之阴阳属性推症，故本段主旨为病机。", ["浮", "沉", "数", "弦"]], "21812": ["病机", "原文以“脉来濡者，虚；牢者，实也”辨脉之虚实，濡脉软弱示精气夺，牢脉坚着示邪气盛，正合“邪气盛则实，精气夺则虚”之旨。又举“脉盛皮热，腹胀，前后不通”为五实，“脉细皮寒，气少，泄痢”为五虚，以脉之盛细配症之虚实，说明虚实辨证之病机。", ["濡", "牢", "细"]], "21813": ["病机", "本段未出具体脉名，以“无肝脉”“无心脉”“无肺脉”“无肾脉”“无脾脉”论四时得病之由，谓春得病无肝脉、夏得病无心脉等，说明时令与脏气相应，若某脏之脉不应时令，则示该脏气衰或邪犯，故主病机。原文以脉之有无应时推断病之所由，非专主一病。", []], "21814": ["预后", "原文以“五脏已夺，神明不守，声嘶者死”“阴阳俱绝，掣衣掇空，妄言者死”等判断危候，又察目色黄赤青黑以决死生，如“青如草滋，死”“赤如衃血，死”“白如枯骨，死”“黑如炱者，死”，皆示脏气败绝、色泽枯夭之预后。虽未出脉名，然通段主旨为预后判断。", []], "21815": ["预后", "原文列肝绝、胆绝、筋绝、心绝、肠绝、脾绝、胃绝等，各以面青伏眠、眉倾、爪甲青呼骂、肩息回视、发直如干麻、口冷足肿泄利不觉、脊痛腰重等症候推断死期，说明脏气竭绝、形神败露之危候。全段虽未明出脉象，然以绝候定预后，故归预后。", []], "21816": ["其他", "本段仅为篇题「诊四时相反脉第十二」，未载具体脉象与病机内容，故无从分析其脉所主病机。原文标题提示讨论四时相反之脉，属脉学理论范畴，但无脉象描述及症候对应，不能臆断。", []], "21817": ["预后", "原文论四时王相顺脉及「肾反脾」「脾反肝」「肾反肝」「肾反心」等相反脉，以脉至先后逆时序判断死期，如「七十日死」「三十日死」「三岁死」。虽未列具体脉形，但以「反」为核心，说明脉气与四时五行相逆则脏气败绝，故主预后凶险。", []], "21818": ["预后", "原文以「形气相得，色泽以浮，脉从四时」为易治，反之以「形气相失，色夭不泽，脉实坚甚，脉逆四时」为难治。脉实坚甚而无柔和胃气，且与四时相逆，说明邪气盛而脏气衰，形神与脉不相协调，故属难治之候。", ["实", "坚"]], "21819": ["预后", "原文列「春夏沉涩，秋冬浮大」及「病热脉静」「泄痢脉大」「脱血脉实」「病在中脉坚实」「病在外脉不实」等，皆名逆四时，难疗。又强调「四时脉皆以胃气为本」，胃气即「脉来弱而滑」，无胃气则难瘥。说明脉失胃气、与证相反者主预后不良。", ["沉", "涩", "浮", "大"]], "21820": ["其他", "本段仅为篇题「诊脉动止投数疏数死期年月第十三」，未载具体脉象与病机内容，故无从分析其脉所主病机。标题提示讨论脉动止疏数及死期年月，属脉学理论范畴，但无脉象描述及症候对应，不能臆断。", []], "21821": ["预后", "原文以脉「一动一止」至「五十动一止」推断死期，动止越频死期越近，如「脉一动一止，二日死」「脉五十动一止」则死期较远。脉动而中止为脏气衰败、胃气不能连续之象，止数疏密反映脏气绝续程度，故主预后凶险，属死脉范畴。", ["动", "止"]], "21822": ["其他", "本段仅为篇题「扁鹊诊诸反逆死脉要诀第十四」，未载具体脉象与病机内容，故无从分析其脉所主病机。标题提示讨论反逆死脉，属脉学理论范畴，但无脉象描述及症候对应，不能臆断。", []], "21823": ["死脉", "原文列「屋漏」「雀啄」「弹石」「解索」「虾游」「鱼翔」等怪脉，如「脉来数而疾绝止，复顿来」为雀啄，「辟辟急」为弹石，「动数而随散乱」为解索，皆无胃气柔和之象。又言「脉病人不病」而见此类脉者死，说明脏气败绝、真元离散，故主死候。", ["数", "疾", "弦", "急"]], "21824": ["预后", "原文以脉之浮大沉小判伤寒温病吉凶：伤寒热盛脉浮大者生，沉小者死，因热盛邪实，脉浮大则邪有外达之机；已得汗则脉沉小者生，浮大者死，因汗后津伤，脉宜静敛。温病脉大疾者生，细小难得者死，示正能抗邪则生，正不胜邪则死。厥逆汗出脉坚强急者生，虚缓者死，强调脉证相应为顺，反之则凶。", ["浮", "大", "沉", "小"]], "21825": ["其他", "本段仅为篇题「诊三部脉虚实决死生第十六」，未载具体脉象与病机内容，故脉象要素为空。篇题提示该篇主旨在于通过诊察寸关尺三部脉之虚实以决断死生预后，属脉诊总纲性标题，无具体脉证分析可引。", []], "21826": ["预后", "原文强调「三部脉大都欲等」，脉与形性相应为顺。虚脉主长病得之死，虚而涩、虚而滑、虚而缓皆主长病亦死，虚而弦急则主癫病亦死，示正气虚衰而见诸兼脉均属危候。实而长长病得之死，实而滑长病得之生、卒病得之死，说明实脉须结合新久病判吉凶，邪实正伤则预后不良。", ["虚", "实", "滑", "涩"]], "21827": ["其他", "本段论述病源本于脏腑、脏腑之脉出手足循环腹背，往来出没难以测量，强调针灸取穴须依图按经，非图莫可。文中未涉及具体脉象主病，仅言「脏腑之脉」之循行与取穴之要，故脉象要素为空，主旨属针灸经穴论述而非脉诊病机分析。", []], "21828": ["其他", "本段为头部及面部腧穴定位描述，如上星「入发际一寸陷容豆」、囟会「在上星后一寸陷者中」、百会「在前顶后一寸半顶心中」等，均属针灸取穴内容。文中虽出现「动脉」字样，但系指穴位处可触及搏动之动脉，非脉诊脉象，故脉象要素为空。", []], "21829": ["其他", "本段为胸部腧穴定位，云门「在巨骨下挟气户两旁各二寸陷中动脉，应手举臂取之」，中府「乳上三肋间动脉，应手陷中」，周荣、胸乡、天溪、食窦依次相去一寸六分。文中「动脉」指穴位处搏动之脉，用于定穴，非诊脉之脉象，故脉象要素为空。", []], "21830": ["其他", "本段为腹部腧穴定位，不容「在幽门旁各一寸五分，去任脉二寸」，承满、梁门、关门、太一、滑肉门依次相去一寸，天枢「去肓俞一寸半，直脐旁二寸」，外陵、大巨、水道、归来、气冲依次排列。全段无脉象描述，属针灸经穴内容，故脉象要素为空。", []], "21831": ["其他", "本段为手太阴肺经腧穴定位，少商「在手大指端内侧，去爪甲角如韭叶」，鱼际「在手大指本节后内侧散脉中」，大泉即太渊「在手掌后陷者中」，经渠「在寸口陷者中，不可灸」，尺泽「在肘中约上动脉」。文中「散脉」「动脉」均指穴位处脉之分布与搏动，用以定穴，非脉诊病机之脉象。", ["散"]], "21832": ["其他", "本段为手厥阴心包经腧穴定位，非论脉。文中'掌中央动脉''掌后两骨间'等仅为取穴标志，动脉指劳宫处可触及搏动，非脉象诊断。所主病机无从谈起，属针灸经穴内容，与脉诊病机无关。", ["动"]], "21833": ["其他", "本段为手少阴心经腧穴定位。'掌后动脉中''腋下筋间动脉入骨'等'动脉'均指体表可扪及的搏动处，作取穴依据，非脉象要素。全段无病机论述，属经穴定位文献，不能据以推断主病。", ["动"]], "21834": ["其他", "本段为耳后及枕部腧穴定位，'耳后青脉间''鸡足青脉'指体表可见的浅表血脉，作取穴标志，非脉象描述。文中'不灸'为刺灸禁忌，与脉诊病机无关，属经穴内容。", []], "21835": ["其他", "本段为手少阳三焦经腧穴定位，'大交脉''两骨间陷者中'等为解剖标志，'不刺'为刺灸禁忌。全段未涉及脉象与病机，属经穴定位文献，不能据以分析所主病机。", []], "21836": ["其他", "本段为足太阳膀胱经腧穴定位，'阳跷所生''足太阴郄也'等述经脉归属，'不刺'为禁忌。文中无脉象描述，亦无病机论述，属经穴定位内容，与脉诊病机无关。", []], "21837": ["其他", "本段为头面颈项部腧穴定位。'耳前兑发下动脉''动应手陷中'指可扪及的搏动处，'颈大脉'指人迎处粗大血脉，均为取穴标志而非脉象诊断。全段属经穴定位，不涉病机。", ["动", "大"]], "21838": ["其他", "本段为胁肋腋部腧穴定位，述章门、京门、带脉、大包等穴位置，'宛宛中'指凹陷处。文中无脉象描述，无病机论述，属经穴定位文献，不能据以推断所主病证。", []], "21839": ["其他", "本段为手阳明大肠经腧穴定位。'肘上行向里大脉中，不刺'指肘部粗大血脉处禁刺，'大脉'为解剖标志而非脉象。全段属经穴定位内容，无病机分析，与脉诊所主病机无关。", ["大"]], "21840": ["其他", "本段为足厥阴肝经腧穴定位，非论脉诊。文中“动应手”“动脉”指行间、阴廉处可触及搏动，属穴位定位标志，非病理性脉象。肝经起于大敦，经行间、太冲、中封等，动脉所在提示经气所过之处，与脉象主病无关，故不归主病或病机。", ["动"]], "21841": ["其他", "本段为足少阴肾经腧穴定位，非脉诊论述。“动脉陷中”指太谿穴处可扪及搏动，为定位依据；然谷、复溜等穴亦列其间。太谿为肾经原穴，动脉应手说明经气汇聚，但原文意在记穴，不涉病机，故不主病。", ["动"]], "21842": ["其他", "本段述手太阴肺经五输穴：少商为井、鱼际为荥、大泉为输、列缺为源、经渠为经、尺泽为合。纯为经络腧穴归类，未及脉象形态与主病，故脉象要素为空，主旨属其他，不可强解为病机。", []], "21843": ["其他", "本段述心包络脉五输穴：中冲为井、劳宫为荥、大陵为输、内关为源、间使为经、曲泽为合。原文标明“心包络脉”，属经络循行归类，无脉象描述，亦无病机推断，故列其他。", []], "21844": ["其他", "本段述手少阴心经五输穴：少冲为井、少府为荥、神门为输、通里为源、灵道为经、少海为合。与上段心包络脉并列，属经络腧穴整理，未言脉形主病，故脉象空、主旨其他。", []], "21845": ["其他", "本段述手阳明大肠经五输穴：商阳为井、二间为荥、三间为输、合谷为源、阳谿为经、曲池为合。纯为经脉腧穴归类，无脉象形态及主病内容，故不列脉象，主旨归其他。", []], "21846": ["其他", "本段述手少阳三焦经五输穴：关冲为井、液门为荥、中渚为输、阳池为源、支沟为经、天井为合。属经络腧穴记述，未涉及脉诊病机，故脉象要素为空，主旨列其他。", []], "21847": ["其他", "本段述手太阳小肠经五输穴：少泽为井、前谷为荥、后溪为输、腕骨为源、阳谷为经、小海为合。与前述各经五输穴体例一致，纯为腧穴归类，无脉象主病论述，故脉象空、主旨其他。", []], "21848": ["其他", "本段述足阳明胃经五输穴与源穴的流注次序，由厉兑井、内庭荥、陷谷输、冲阳源、解谿经至三里合，属经络腧穴理论，非论脉象。原文未及脉形脉势，故无脉象要素可录，主旨在于明胃经经气流注之路径，与病机、主病无直接关联。", []], "21849": ["其他", "本段述足少阳胆经五输穴与源穴流注：窍阴井、侠谿荥、临泣输、丘墟源、阳辅经、阳陵泉合，属经络腧穴内容。原文未描述脉象形态，故脉象要素为空，主旨为明胆经经气运行之序，非论病机主病。", []], "21850": ["其他", "本段述足太阳膀胱经五输穴与源穴：至阴井、通谷荥、束骨输、京骨源、昆仑经、委中合，为经络腧穴流注之说。原文无脉象描述，脉象要素从缺，主旨在于明膀胱经经气出入之路径，与脉诊病机无涉。", []], "21851": ["其他", "本段述足太阴脾经五输穴与源穴：隐白井、大都荥、太白输、公孙源、商丘经、阴陵泉合，属经络腧穴理论。原文未言脉形，故脉象要素为空，主旨为明脾经经气流注次序，非论脉象主病。", []], "21852": ["其他", "本段述足厥阴肝经五输穴与源穴：大敦井、行间荥、太冲输、中封源、中郄经、曲泉合，为经络腧穴流注内容。原文无脉象描述，脉象要素缺如，主旨在于明肝经经气运行路径，与病机主病无直接关系。", []], "21853": ["其他", "本段述足少阴肾经五输穴与源穴：涌泉井、然谷荥、太谿输、水泉源、复溜经、阴谷合，属经络腧穴理论。原文未及脉象形态，故脉象要素为空，主旨为明肾经经气流注之序，非论脉诊病机。", []], "21854": ["误治", "本段论针刺禁忌与误刺后果，如大寒、月生、月满、新内、大怒、大劳、大醉、大饱、大饥、大渴皆不可刺，乘车步行来者须休息乃刺；又述刺中心为噫、中肺为咳、中肝为语、中脾为吞、中肾为嚏、中胆呕吐等，皆言误刺伤脏之变。原文虽标大脉字样，实非论脉，乃刺法禁宜，故脉象要素不录。", []], "21855": ["其他", "本段列举诸穴禁灸之例，如下关、耳门耳中有干适低或脓乃适低无灸，人迎、阳关、丝竹空、承泣、脊中、乳中、瘛脉、石门、白环俞、天府、经渠、伏兔、地五会、鸠尾等禁不可灸，气冲灸之不得息，渊腋灸之生脓蚀。原文未述脉象，脉象要素为空，主旨属针灸禁忌，非脉诊病机。", []], "21856": ["平脉", "原文列五脏脉象：沉濡属肾，洪盛属心，弦长属肝，浮短属肺，缓大属脾。以脉之形态配五脏之性，沉濡为水之象，洪盛为火之象，弦长为木之象，浮短为金之象，缓大为土之象。此为以脉候脏之平脉法，非主一病，乃示五脏各得其常脉之象，与四时五行相应。", ["沉", "濡", "洪", "弦"]], "21857": ["其他", "原文列五脏脉气所出之井穴：涌泉属肾，中冲属心包络（心经出少冲），大敦属肝，少商属肺，隐白属脾。此段言五脏经气出于四肢末端之井穴，为经脉起止出入之处，非论脉象形态，故无脉象要素可录，主旨在于明五脏脉气外达之门户。", []], "21858": ["其他", "原文列六腑脉气所出之井穴：至阴属膀胱，少泽属小肠，窍阴属胆，商阳属大肠，厉兑属胃，关冲属三焦。此承上段五脏脉出而言六腑经气所出之处，说明六腑经脉之气亦从四肢末端井穴出入，属经络循行内容，未涉脉象形态，故脉象要素为空。", []], "21859": ["病机", "原文列五养：骨养于精，血养于脉，筋养于血，皮毛养于气，肉养于形。此以五体与精气血相配，说明形体各有所养之源。骨赖精充，脉赖血盈，筋赖血濡，皮毛赖气煦，肉赖气充。五养失宜则相应之体病，属病机层面之整体观，非直接描述脉象。", []], "21860": ["治法", "原文论针刺之法，强调先明孔穴、补虚泻实、送坚付濡、以急随缓，使荣卫常行。又言针者不离乎心，消息气血，针入一分知天地之气，二分知呼吸出入，三分知四时五行五脏六腑顺逆之气，并戒针皮毛勿伤肌肉、针肌肉勿伤筋脉等。全段为针刺操作与层次深浅之治法准则，未及脉象。", []], "21861": ["病机", "原文以五行配五脏：东方甲乙木主肝胆筋膜魂，南方丙丁火主心小肠血脉神，西方庚辛金主肺大肠皮毛魄，北方壬癸水主肾膀胱骨髓精志，中央戊己土主脾胃肌肉意智。继言针伤筋膜令人愕视失魂，伤血脉令人烦乱失神，伤皮毛令人上气失魄，说明针刺误伤五体则伤所藏之神，属病机与误治之理。", []], "21862": ["治法", "原文论用针补泻之法，以呼吸应江汉、补泻校升斗，经纬有法则，阴阳不相干，并配震兑坎离方位以明补泻方向。末言刺急者深纳而久留之，刺缓者浅纳而疾发。脉急者多属寒凝收引，故深纳久留以温通；脉缓者多属气机舒缓，故浅纳疾发以调之，体现因脉施针之治法。", ["急", "缓"]], "21863": ["治法", "原文论孔穴为脏腑荣卫血脉流通表里往来之所，临时救难必在审详，须因人老少长短肥瘦精思商量，不可一概。又述尺寸取穴之法及灸法分寸。段首标脉大者、脉浮热甚，提示脉大浮数属热盛之候，施灸取穴当审详折中，体现据脉辨治、因人施术之治法原则。", ["大", "浮", "数"]], "21864": ["主病", "本段为腧穴主治汇集，未出脉象。文中“风头痛”“头重痛”“风眩偏头痛”等，皆属风邪上扰清窍、经气不利之病机；取穴多属阳经及头部局部，以疏风通络止痛。脉象虽未明言，然风头痛多见浮脉，头重痛多兼湿，此段主旨在于列穴以治头面风疾。", []], "21865": ["主病", "本段列目疾诸穴，未言脉。文中“目䀮䀮不明，恶风寒”“目泣出”“目翳”等，属肝肾精血不足、风邪外袭、目窍失养之病机。取穴多取足太阳、足少阳及眼周局部，以通经明目。此段主旨为目病之针灸主治，非论脉。", []], "21866": ["主病", "本段为鼻病取穴，未出脉象。文中“鼻鼽清涕出”“鼻窒喘息不利”“鼽衄”“鼻中息肉”等，属肺气不利、风寒袭鼻、或热伤血络之病机。取穴多取手太阴、阳明及鼻周局部，以宣肺通窍。此段主旨为鼻疾针灸主治，脉象未及。", []], "21867": ["主病", "本段列舌病诸穴，未言脉。文中“舌下肿难言”“舌缓喑不能言”“舌卷口干”“舌本出血”等，属心脾积热、风痰阻络、或阴液不足之病机。取穴多取心经、脾经及舌本邻近穴位，以清心开窍、通络利舌。此段主旨为舌疾针灸主治。", []], "21868": ["主病", "本段为喉痹取穴，未出脉象。文中“喉痹，颈项肿不可俯仰”“咽肿不得消，饮食不下”“喉痹不能言”等，属风热壅肺、痰火结喉、气血瘀滞之病机。取穴多取肺经、大肠经及任脉局部，以清热利咽、消肿开闭。末言“胁中暴逆”先取冲脉后取三里云门，示喉痹急症之刺法。", []], "21869": ["病机", "本段主奔豚诸穴，末言“然谷主胸中寒，脉代，时不至寸口，小腹胀，上抢心”。脉代而时不至寸口，为胸中寒凝、阳气不布、脉气不能接续之象；奔豚气上抢心、小腹胀，正是寒水之气上逆、心阳被遏之病机。代脉在此主脏气衰微、寒邪内阻，与奔豚上气之症相应。", ["代"]], "21870": ["主病", "本段列臂肘腋病诸穴，未言脉。文中“臂重痛，肘挛”“肘节痹，臂酸重”“臂痿不仁”“臂不举”等，属风寒湿痹阻经络、气血运行不畅之病机。取穴多取手三阳经及局部，以通经活络、祛邪止痛。此段主旨为臂肘疾患之针灸主治，脉象未及。", []], "21871": ["主病", "本段为腰脊痛取穴，未出脉象。文中“腰脊急强”“腰痛如折”“腰痛不可以顾”“腰脊疝痛”等，属肾虚腰府失养、寒湿痹阻、或瘀血阻滞之病机。取穴多取足太阳、督脉及腰骶局部，以温通经络、强腰止痛。末言“腰脚重痛，于此刺出血”，示瘀滞重痛可刺络放血。", []], "21872": ["主病", "本段为腧穴主治汇编，列举昆仑、阴陵泉、京骨、承山等穴所主足痹、脚挛、足缓不收、足痿失履、胫寒不能久立等症。原文未出脉名，仅以“足痿失履不收”“脚筋急痛兢兢”述症，说明病机在足三阳三阴经气痹阻、筋脉失养，故取相应经穴分治，属针灸主病之文，非脉诊段落。", []], "21873": ["主病", "本段列偏历、神庭、攒竹等穴主癫疾呕逆、痫发瘛疭、狂走不得卧、寒热痉互引、口噤喉鸣沫等。原文标题虽云“脉主癫疾腠气”，正文实为腧穴主治，未出具体脉象。其病机为痰火风邪上扰神明、经气逆乱，故见癫狂痫瘛、呕沫痉厥，取穴多属督脉与手足阳经，以通阳泄邪、熄风安神。", []], "21874": ["病机", "原文两言“脉动如故”，指尸厥暴死、形无所知而脉仍搏动如常。此非死脉，乃五络俱竭、邪客手足少阴太阴及足阳明之络，气机骤闭而脉未绝，故“其状若尸”而“脉动如故”。脉动如故正说明生机未息，故刺足大趾、足心、手大指及手心主，并以筒吹耳、燔发醇酒救之，属病机判断。", ["动"]], "21875": ["治法", "原文“先取然谷，后取太谿大指间动脉，皆先补之”，动脉指足背太冲脉动处。热病烦心而足寒清、多汗，为热郁于上、阳气不达于下，故取肾经然谷、太谿及大指间动脉先补，以引阳下行、滋水制火。此段以动脉为施治部位，主旨在治法，非以脉候病机。", ["动"]], "21876": ["妇人", "本段专论妇人小腹坚痛、月水不通、漏下血闭、疝瘕阴挺、经水来下阴中肿痒、血闭无子等，取带脉、血海、阴谷、曲泉刺灸。原文未出脉象，所述“按之如以汤沃两股中”“漉青汁如葵羹”皆言症候，病机属冲任瘀阻、寒湿下注、气血不通，故以妇人病为主旨。", []], "21877": ["小儿", "本段列本神、前顶、囟会、天柱主小儿惊痫，临泣主惊痫反视，然谷主脐风口不得开，瘈脉长强主惊痫瘛疭、多吐泄注、惊恐失精。原文标题“脉长强主小儿惊痫瘛疭”中“脉”字连属穴名，非脉象。病机为小儿神气未充、风痰惊热内扰，故取督脉及阳经穴以熄风镇惊，属小儿主治。", []], "21878": ["其他", "本段为程子敬通传略，述其“指脉说病则目无全人”，接诊虽极贱贫必端问详审、反复精思，疑难者多至盈时，惟恐少误。原文未出具体脉象，主旨不在脉诊病机，而在称扬医者指脉说病、精思慎诊之德，并及《外台秘要》流布之事，故归其他。", []], "21879": ["其他", "本段论医与方并重，叹世降方愈凌杂、各据一家互相是非，验方秘不示人，镌行者依样葫芦、改头换面以博名高。原文未出脉象，亦不涉具体病机，旨在说明付梓《外台秘要》之由，追溯神农本草、轩辕素问灵枢及越人禁方源流，属医籍序论，归其他。", []], "21880": ["其他", "本段为医论，强调伤寒须逐日浅深施治，批评不早治、治不对病、困乃告医等误治，并提及“诊脉声色对病真方”，但未出具体脉象。主旨在于临病须审察地土方宜与脉证，非论某脉主某病，故脉象要素为空，归入其他。", []], "21881": ["病机", "原文“其脉朝夕𫘝者为实癖也，朝平夕𫘝者”，𫘝即数急之意。脉朝夕数急，说明邪实内结、癖积不散，气机壅滞而化热，故主实癖。朝平夕𫘝则示邪气随时而动，病机属实，与发汗不解、转下之证相应。", ["𫘝"]], "21882": ["病机", "原文以“脉不紧数”辨非里实。紧主寒实，数主热实，脉不紧数则里无实邪结聚，故不可下；又“不恶寒，身不疼痛”非伤寒表证，故不可汗。脉不紧数正是虚烦内无实邪之凭据，主虚烦热，与竹叶汤、橘皮汤证相应。", ["紧", "数"]], "21883": ["主病", "原文“诸病发热恶寒脉浮洪者，便宜发汗”，浮主邪在表，洪主热盛，浮洪并见说明风寒外束、阳气奋起抗邪而热势已张，故主表实发热恶寒之证，治宜发汗。若适逢失血或下利，则数少与桂枝汤使漐漐汗出，示脉浮洪为可汗之机。", ["浮", "洪"]], "21884": ["预后", "原文列热病九死候，其中“热病七八日，脉微小，病者便血，口中干，一日半而死”，脉微小为正气衰微、阴血耗竭之象，故主死；又“脉不躁不数，后三日中有汗，三日不汗，四日死”，脉不躁不数示邪热未甚，尚可望汗解，若不得汗则正不胜邪，预后凶险。", ["微", "小", "数", "躁"]], "21885": ["治法", "原文“脉微不可吐虚细不可下”，微为阳气虚，虚细为阴血不足，故禁吐下，以免虚其胃气；又“脉有沉浮转能变化”示脉随病机而变，当随时形势救解；后文“脉实大者”虽未全引，实大主邪实可下。全段以脉定汗吐下之禁与宜，主在治法。", ["微", "虚", "细", "实"]], "21886": ["病机", "本段引《素问》热病之论，述巨阳、阳明、少阳、太阴、少阴、厥阴六经受邪的传变次序与症候，如“头项痛腰脊强”“身热目疼而鼻干不得卧”等，说明伤寒热病由表入里、循经传脏的病机，未出具体脉象，故脉象要素为空，归入病机。", []], "21887": ["治法", "原文“治之各通其脏。脉病日衰已矣，其未满三日者可汗而已，其满三日可泄而已”，提出按病日浅深分汗泄之法，并据脉病日衰判断转归。虽言“脉病”，但未出具体脉象，主旨为热病治法，故脉象要素为空，归入治法。", []], "21888": ["预后", "两感于寒为表里两经同病，原文未出脉名，仅言\"其脉应与其病形何如\"。一日巨阳少阴俱病见头痛口干烦满而渴，二日阳明太阴俱病见腹满身热谵语，三日少阳厥阴俱病见耳聋囊缩厥逆，三阴三阳俱受邪，气血营卫不通，故断\"六日而死\"，示两感危候。", []], "21889": ["预后", "原文以\"脉之长也\"释阳明，谓阳明为十二经脉之长，气血最盛。五脏已伤、六腑不通、营卫不行之后，赖阳明气血尚盛故不知人而延至三日，待其气尽乃死。脉长应阳明气血充盛之象，此处借以说明胃气存亡决定死期，非主病之脉。", ["长"]], "21890": ["病机", "本条未出脉名，述伤寒一日太阳受病。太阳为三阳之首，其经络于腰脊、主头项，故得病一日即头项背膊腰脊痛。病机为寒邪首犯太阳之表，经气不利，故以头项腰脊强痛为症，属表证初起、邪在太阳经脉。", []], "21891": ["治法", "本条未出脉名，述伤寒二日阳明受病。阳明胃经主肌肉，脉络鼻入目，故内热鼻干不得眠。原文指出诸阳在表、表始受病在皮肤之间，故可摩膏火灸发汗而愈，示邪尚在表、当从汗解，属早期表证治法。", []], "21892": ["病机", "本条未出脉名，述伤寒三日少阳受病。少阳胆经循胁上颈耳，故胸胁痛而耳聋。原文强调三阳经络始相传病、未入于脏，故皆可汗而解，说明邪仍在三阳经表，未传脏腑，症以胸胁痛耳聋为少阳经气不利之征。", []], "21893": ["病机", "本条未出脉名，述伤寒四日太阴受病。太阴脾经为三阴之首，三日前阳受病讫而传于阴，其脉络脾主喉嗌，故腹满而嗌干。病在胸膈，故可吐而愈，示邪由阳传阴、病位偏上在胸膈，症以腹满嗌干为太阴受病之候。", []], "21894": ["病机", "本条未出脉名，述伤寒五日少阴受病。少阴肾经贯肾络肺系舌，故口燥舌干、渴而引饮。病在腹，故可下而愈，说明邪已深入少阴、津液受灼，症以口燥舌干引饮为少阴里热伤津之征，病位在腹当从下解。", []], "21895": ["病机", "本条未出脉名，述伤寒六日厥阴受病。厥阴肝经循阴器络肝，故烦满而囊缩。原文谓此则阴阳俱受病、毒气在胸，故可下而愈，示邪传厥阴、阴阳俱病，症以烦满囊缩为肝经受邪、筋脉拘急之候。", []], "21896": ["病机", "脉浮虚而涩，浮为风湿在表，虚为阳气不足，涩为湿滞血行不畅。伤寒八九日，风湿相搏，身体疼痛而烦，不能自转侧，不呕不渴，示邪未入里。误下后脉转浮虚而涩，说明表阳已伤而风湿仍恋，故属桂枝附子汤证；若大便硬、小便自利，则湿从燥化，转属附子白术汤。", ["浮", "虚", "涩"]], "21897": ["主病", "脉洪为热盛之象，伤寒初觉头痛肉热而脉洪，起一二日，邪在肌表，热势方张。洪脉主阳热亢盛，与头痛、肉热相应，说明表热已著但尚未入里成实，故用葱豉汤辛凉解表，取一叶兼疗之意，以挫其初起之热。", ["洪"]], "21898": ["病机", "脉滑数，滑主热盛痰实，数主热急，与昏愦、身体壮热、沉重拘挛相应，示三焦热炽而表未解。热毒内攻则昏愦，表邪未解则体犹沉重拘挛。单用解毒则挛急不瘥，单用汗药则毒因加剧，故以石膏汤三黄救内、增味解外，表里同治。", ["滑", "数"]], "21899": ["病机", "寸脉沉迟，沉为在里，迟为阳微，手足厥逆、下部脉不至，示阳气衰微不能达于四末。咽喉痛不利、唾脓血，为热毒上攻；泄利不止，为中焦虚寒。此上热下寒、正虚邪陷之候，故以麻黄升麻汤发越郁阳、清上温下。", ["沉", "迟"]], "21900": ["主病", "原文未识出具体脉名，仅言脉盛。脉盛与头痛壮热相应，示伤寒时气温疫初得一二日，邪在表而正气尚盛，热势鸱张。脉盛为邪正交争、阳热外浮之象，故取一叶兼疗之方，以解表清热，截断病势。", []], "21901": ["病机", "脉沉结，沉为在里，结为血行瘀滞。太阳病身黄、少腹坚、小便不利，似为湿热发黄，然小便自利而其人如狂，则非水湿而是瘀血。沉结脉与少腹坚、如狂相应，示瘀热互结下焦，血证谛也，故宜抵当汤下之，破血逐瘀。", ["沉", "结"]], "21902": ["病机", "阳明病脉迟，迟非寒而主里实，因燥屎内结、腑气壅滞，脉道不利故迟。虽汗出不恶寒，体必重、短气腹满而喘、有潮热，示外欲解而里可攻。手足濈然汗出为大便已坚，宜承气汤；若汗多微发热恶寒，则外未解，宜桂枝汤，不可妄攻。", ["迟"]], "21903": ["误治", "脉沉喘满，沉为在里，喘满为里实气壅。伤寒四五日，邪已入里，反发汗，津液越出，大便为难，表虚里实，久则谵语。此误汗伤津、邪热内结之变，沉脉示病位在里，喘满示腑气不通，谵语为里实上扰神明，皆由误治所致。", ["沉"]], "21904": ["主病", "伤寒六七日，邪热内陷与痰水互结而成结胸，脉沉紧。沉主里，紧主痛主实，为水热结聚于胸膈之征。原文\"心下痛，按之如石坚\"，正是邪实内结、气血不通之象，故脉沉紧与硬满拒按相应，主大陷胸汤证。", ["沉", "紧"]], "21905": ["误治", "脉浮为邪在表，发热无汗表不解，当先解表，不可与白虎汤，恐寒凉冰伏、引邪入里。原文以\"脉浮\"与\"无表证\"对举：表不解者禁白虎，渴欲饮水而无表证者方可用之。此段借脉浮说明表证未罢，属白虎汤禁忌之辨。", ["浮"]], "21906": ["病机", "少阴病寒多表无热，脉沉细而不喜渴。沉主里、细主虚，为阳气不足、寒湿内盛之象；\"默默不欲见光\"\"腹痛\"皆阴寒内凝、神气不振所致。原文怪四顺汤之热而不甚用，正因脉证偏寒，须辨有无热候以定温清，脉沉细为辨证关键。", ["沉", "细"]], "21907": ["主病", "原文仅言\"脉盛\"，未识具体脉名，故脉象要素从缺。脉盛示邪气方张、正气未衰，与伤寒温病初起\"头痛壮热\"相应，属表热实证。始得一二日邪在肌表，脉盛为热势鸱张之征，故以解表清热为治，此段主旨在于述其主病与治法。", []], "21908": ["主病", "阳毒为热毒炽盛之候，脉浮大数。浮为热蒸于外，大为邪盛，数为热急，与\"面赤斑斑如锦文\"\"咽痛唾脓血\"\"狂言或走\"相应，皆热毒燔灼、气血两燔之象。原文以五日可疗、七日不可疗示其传变之速，脉浮大数正是阳毒热实之凭。", ["浮", "大", "数"]], "21909": ["主病", "阴毒为寒毒内结之候，脉沉细紧数。沉细主里虚寒，紧主痛主寒凝，数在此非热，乃寒邪逼迫、阳气挣扎之象。与\"腹中绞痛\"\"唇青面黑\"\"四肢厥冷\"\"心下坚强\"相应，皆阴寒内盛、毒气攻心所致。原文引仲景语，明其为阴毒之候，预后险恶。", ["沉", "细", "紧", "数"]], "21910": ["病机", "夏月暴寒折于盛热，热结四肢则壮热头痛，寒伤于胃则下痢。脉微且数：微为正气不足，数为热邪内郁，与壮热且闷、下痢赤白相应，属寒热错杂、正虚邪实之候。原文谓\"宜下之\"，正因脉数示里有热结，微示其虚，故用调中汤两解之。", ["微", "数"]], "21911": ["兼症", "服桂枝汤大汗出后脉洪大，为汗后津伤、阳气浮盛之象，与\"形如疟，一日再发\"相应，属表邪未尽、营卫不和之兼症。原文仍与桂枝汤如前法，若寒热如疟则用桂枝二麻黄一汤，说明脉洪大在此非阳明热盛，乃汗后阳浮，须结合症候辨析。", ["洪", "大"]], "21912": ["误治", "脉浮紧为太阳伤寒表实证，风寒束表，卫阳被遏，营阴郁滞。阳明中风见脉浮紧，是表邪未解，里有热象。若误下，则表邪内陷，气机壅滞，故腹满、小便难。原文以“若下之则腹满小便难”警示下法之误，脉浮紧在此提示表证仍在，不可攻下。", ["浮", "紧"]], "21913": ["预后", "太阳中风见四肢烦疼，脉阳微阴涩而长者，为欲愈。阳微示表邪已衰，阴涩示里气未和，而脉长则胃气渐复，正胜邪却。长脉为气血充盈、胃气强盛之象，故知病将愈。原文以“阳微阴涩而长者为欲愈”判断转归，强调脉长是向愈关键。", ["微", "涩", "长"]], "21914": ["预后", "少阴中风，脉阳微阴浮者为欲愈。阳微指寸脉微，示表邪已微；阴浮指尺脉浮，示里邪外达，少阴之邪从里出表。少阴病本脉微细，今阴脉浮，为阳气来复、邪有外出之势，故为欲愈。原文以“阳微阴浮”为向愈之征，突出少阴病由阴转阳的机转。", ["微", "浮"]], "21915": ["预后", "厥阴中风，脉微浮者为欲愈，不浮为未愈。厥阴病本脉沉微，今见微浮，示阳气渐复，邪气有外达之势，故为欲愈。若脉不浮，则阳气未复，邪仍内陷，故为未愈。原文以脉之浮与不浮判断厥阴病转归，强调微浮为阳气来复、邪从表解之佳兆。", ["微", "浮"]], "21916": ["治法", "此段为服药方法与加减法，非专论脉。文中“脉反和者不死”指脉象平和则预后佳；“脉浮数”见于火发汗后，火气太过，汗出不解，烦躁不得寐，脉浮数示表热未解而里热已生。全段以治法为主，强调服法、汗出调护及火逆变证之处理，脉象仅作辨证参考。", []], "21917": ["主病", "脉浮发热，汗出恶风，项颈强，鼻鸣干呕，为太阳中风表虚证。脉浮主邪在表，发热汗出恶风示卫强营弱，项颈强为太阳经气不利，鼻鸣干呕为肺胃气逆。原文以“脉浮”统领诸症，阳旦汤主之，调和营卫，解肌祛风，脉浮在此明确病位在表。", ["浮"]], "21918": ["误治", "脉浮紧发热者不可与也，指正阳旦汤（桂枝汤类）禁用于表实无汗之证。浮紧为风寒束表、营阴郁滞之象，发热无汗，当以麻黄汤发汗。若误与桂枝汤，则表邪不解，反致迁延。原文以“脉浮紧发热者不可与也”强调桂枝汤禁例，脉浮紧是鉴别表实与表虚的关键。", ["浮", "紧"]], "21919": ["主病", "太阳中风脉浮紧，发热恶寒，身疼痛，汗不出而烦躁，为风寒表实兼里热之证。脉浮紧主风寒束表，卫阳被遏；汗不出示表闭，烦躁为阳郁化热、热扰心神。大青龙汤外解表寒、内清里热。原文以“脉浮紧”点明表实，与烦躁并见，揭示寒闭热郁之病机。", ["浮", "紧"]], "21920": ["治法", "本段述麻黄类方服法及禁忌，未出脉象。文中“汗出多者，温粉粉之”“复服汗多亡阳遂虚”强调过汗伤阳之弊，与“中风见伤寒脉者可服之”呼应，提示脉证合参方可投方。所主病机为汗法太过致阳气虚损，见恶风、烦躁不得眠，属误治变证。", []], "21921": ["病机", "寸口浮、关上沉，为热毒结聚心胸、气机壅塞之象，故按之痛而成结胸。“脉大不可下”示热实内结，下之则死；“脉浮而大，下之为逆”言表邪未解误下致逆。若关上细小沉紧而饮食如故、小便利，则属脏结，为阴寒凝结、阳气衰微，舌白苔滑者难疗。", ["浮", "沉", "大", "细"]], "21922": ["病机", "寸脉浮、关脉沉，为热邪结聚胸膈、气机不通，故按之痛名结胸。寸口浮、关上小细而沉紧，为阴寒内结、脏气不通，饮食如故、时时下利，名脏结。舌上白苔滑者，寒湿凝聚难化，故为难治；无阳证、不往来寒热、其人反静，示病在阴分，不可攻下。", ["浮", "沉", "细", "紧"]], "21923": ["预后", "结胸证脉浮大，为表邪未解、热势浮盛于外，里结未实，故不可下。若误下则表邪内陷，结胸愈甚，正气溃败，故曰“下之则死”。此以脉浮大辨表邪尚存，示下法之禁，属预后判断，强调结胸脉沉紧方可攻下。", ["浮", "大"]], "21924": ["病机", "脉浮动数，浮为风、数为热、动为痛、数为虚，示表邪未解而里已化热。医反下之，动数变迟，为阳气内陷、客热动膈，故膈内拒痛、短气烦躁、心中懊憹，心下因坚而成结胸。脉由动数转迟，反映邪陷热结、气机壅遏之病机转化。", ["浮", "动", "数", "迟"]], "21925": ["主病", "伤寒六七日，脉沉紧，沉主里、紧主痛，为热实内结、气血壅滞之象。心下痛、按之石坚，正是水热互结于胸膈，结聚成形，故主结胸热实之证，以大陷胸汤峻下逐水破结。脉沉紧与石坚拒按相应，示邪结深重。", ["沉", "紧"]], "21926": ["病机", "脉微弱，为阳气不足、本有久寒之象。太阳病二三日不能卧但欲起，心下必结，乃寒饮内停、气机不畅。医反下之，若利止者，寒邪乘虚结于胸膈，必作结胸；未止者，复下之则协热下利。脉微弱示里虚寒盛，下之更伤阳气，变证由生。", ["微", "弱"]], "21927": ["病机", "太阳病下之，脉促，为阳气被遏、抗邪外出之象。若不结胸，则邪有外解之势，故为欲解；若心下满硬痛，则热邪内陷、水热互结而成结胸，主以大陷胸汤。但满而不痛者，为气机痞塞之痞证，宜半夏泻心汤。脉促与结胸、痞证之辨，示下后变证之不同转归。", ["促"]], "21928": ["主病", "小结胸病位正在心下、按之则痛，脉浮滑。浮为热邪偏于上焦气分，滑为痰热互结、实邪壅聚之象；痰热结于心下，故按之痛而脉见浮滑。此脉此症相合，正说明邪热与痰浊相结、病位较浅，故以小陷胸汤清热化痰开结。", ["浮", "滑"]], "21929": ["病机", "伤寒过经不愈，脉反沉迟而非浮紧，说明阳气衰微、阴寒内盛。沉主里、迟主寒，手足厥逆正是阳不外达之征；原文谓「下部脉不至，阴阳隔绝」，邪客足少阴，毒气上熏致咽喉不利或生疮。沉迟在此标示少阴阴寒内闭、阴阳不相顺接之病机。", ["沉", "迟"]], "21930": ["误治", "衄家本已亡血，不可攻表。若误汗，则见「脉急而紧」、直视不能眴、不得眠，急紧示阴血亏耗而筋脉失养、邪热内扰；又述「脉浮紧发热、身无汗、自衄者愈」，浮紧为表寒束闭、阳郁求伸，郁热从衄而解。两脉并举，正说明亡血禁汗、误汗伤阴之戒。", ["急", "紧", "浮"]], "21931": ["病机", "「脉大来迟，腹不满，自言满者为无热」，大而迟非实热之象，乃虚寒中焦、气机壅滞所致。腹虽不满而患者自言胀满，是脾虚气滞、非有形实邪，故断为无热而不用黄芩。脉大来迟在此提示虚寒胀满、不可妄投苦寒之病机。", ["大", "迟"]], "21932": ["预后", "少阴病脉微细而沉、但欲卧，是阳气衰微、阴寒内盛之危候；若汗出、自利后烦躁不得卧寐则死，示阴阳离决。又「脉平而少烦」乃病新瘥脾胃气弱、不胜谷气之微烦，脉平说明邪已退而正未复。微细沉主少阴危证，脉平少烦主新虚，二者对举以辨预后吉凶。", ["微", "细", "沉", "平"]], "21933": ["主病", "脉浮发热、渴欲饮水、小便不利，浮为热邪在表或气化不利、水热互结；渴而小便不利，说明水停下焦、津不上承，热与水结。猪苓汤育阴清热利水，正对此水热互结、阴伤之病机。脉浮在此提示热邪未全入里，与小便不利合参以定病位。", ["浮"]], "21934": ["其他", "此段为栝蒌根药材选用之文，「内黄脉少者三两」指拣选栝蒌根内里色黄、筋脉稀少者入药，非论病之脉象。故脉象要素为空，主旨属药材修治与选用，不涉病机主病，列于其他。", []], "21935": ["其他", "此段为张文仲秦皮汤方的主治记载，述伤寒病热、毒气入眼，生赤脉赤膜白肤白翳及赤痛畏光等症，未识别出脉名，原文亦未言脉。故脉象要素为空，主旨属方药主治眼疾，不涉脉诊病机，列于其他。", []], "21936": ["预后", "下利脉弱为邪退正复，故自愈；脉沉弦主里急后重，气机壅滞；脉大则邪盛未止；脉微数示阳复欲愈。浮数尺涩为热伤血络，必圊脓血。浮大见于阳明下利，乃虚证误下所致。诸脉并见，皆辨下利之进退吉凶。", ["弱", "沉", "弦", "大"]], "21937": ["预后", "伤寒下利日十余行，脉反实为邪气盛而正气衰，故主死。脉浮大乃虚证强下之故，非实热。脉浮革主虚寒肠鸣，当温之，与水则哕。此段以脉辨下利之虚实死生，强调误下致虚之变。", ["实", "浮", "大", "革"]], "21938": ["病机", "太阳桂枝证误下，利遂不止，脉促为表邪未解，阳气被遏而急促。喘而汗出乃热迫大肠、肺气上逆。脉促在此示表未解而里已热，故用葛根黄连汤解表清里。", ["促"]], "21939": ["其他", "此段为方药煎服法及加减，未涉脉象。原文提及白通汤主少阴下利厥逆无脉，乃阳衰阴盛之危候，脉不可见。所述渴微呕心下停水，属水气内停，与脉无直接关联。", []], "21940": ["主病", "伤寒下利脉微，足厥冷，为阳气衰微，阴寒内盛，不能温煦四末。脉微主阳微欲绝，与厥冷并见，属少阴寒化之证，故用通草汤通阳散寒。", ["微"]], "21941": ["病机", "阴阳易病由新瘥交接，毒邪传易。经脉缓弱、血气空虚、骨髓枯竭，乃精血耗伤，经脉失养。缓弱非平和之脉，而是虚损之象，故见身体重、小腹里急、热上冲胸等症。", ["缓", "弱"]], "21942": ["其他", "此段述伤寒新瘥余邪未清，阳气不足，若行房室则阴阳易病，多死。未直接言脉，但华敷视脉知“尚虚未复”，提示脉当见虚象。所举吐舌数寸、吐涎、小腹急痛等，皆精竭阳脱之危候。", []], "21943": ["病机", "伤寒新瘥，津液未复，血气尚虚，若劳动过早则复病。脉沉紧为劳复后热入经络，里实可下。食复则脾胃虚弱，难消之物结热，下之伤胃，不下亦危。脉沉紧示里实，故宜下之。", ["沉", "紧"]], "21944": ["主病", "食不消劳复而见脉实，说明宿食内停、劳复之后邪气仍盛，正气未虚，脉道充盈有力。实脉主邪实内结，与食积不化、劳复发热相应，故用鼠屎栀子豉汤清宣导滞，从脉实可断其可攻可清。", ["实"]], "21945": ["病机", "百合病由伤寒虚劳大病后不平复而成，身形如和而脉微数，微为气虚阴亏，数为虚热内扰，故见欲食不能食、欲卧不得卧、如寒无寒如热无热等恍惚之状。脉微数正是阴虚内热、百脉失和之象，与尿辄头痛、小便赤黄相应。", ["微", "数"]], "21946": ["预后", "本条承百合病而言，身体仍和而脉微数，说明阴虚内热未解。原文以尿时头痛与否、淅淅然如寒、但头眩等分判六十日、四十日、二十日愈期，脉微数作为百合病本脉贯穿其中，反映虚热内扰、病在百脉，预后随症候轻重而异。", ["微", "数"]], "21947": ["兼症", "脉数无热而微烦、嘿嘿但欲卧、汗出，是热郁营分而外无大热；至眼赤如鸠眼、四眦黄黑，为热毒内蕴、血肉腐化为脓之征。脉数主热，无热说明热不在表而在里，能食者脓已成，脉数与目赤、脓成症候相呼应，示痈脓内结。", ["数"]], "21948": ["误治", "原文先言病形不可灸，火邪散走血脉，伤脏则剧，致井输穴肿、黄汁自出、肉腐为痈脓，此为火疽。又特别指出微数之脉慎不可灸，因火为邪则烦逆，追虚逐实，血散脉中，火气虽微内攻有力，焦骨伤筋。微数本阴虚内热，误灸则助火伤阴，血散难复。", ["微", "数", "散"]], "21949": ["病机", "时气二日阳明受病，阳明主肌肉，其脉络鼻入目，故内热鼻干不得眠。原文未出脉名，从诸阳为表、表始受病皮肤之间立论，说明邪在阳明肌表，可摩膏火灸发汗而愈，重点在邪未入里、因势外解的病机。", []], "21950": ["病机", "时气三日少阳受病，少阳脉循胁上颈耳，故胸胁热而耳聋。原文未言脉，强调三阳经络始相传、病未入脏，故可汗之而愈。其病机为邪客少阳经络，尚未内陷，治当因势汗解，与胸胁热、耳聋症候相应。", []], "21951": ["病机", "时气四日太阴受病，太阴为三阴之首，诸阳受病讫即传于阴。其脉主咽嗌，故腹满而嗌干，病在胸膈，故可吐而愈。原文未出脉名，从经络传变立论，说明邪入太阴、病位偏上在胸膈，因势吐之，与腹满嗌干相应。", []], "21952": ["病机", "原文未出脉名，以「少阴脉贯肾络肺，系于舌本」言经脉走向，说明邪入少阴，循经上熏则口热舌干、渴而引饮；病位在腹，故可下而愈。此段以经络受病推病机，非凭脉断证，故脉象要素为空。", []], "21953": ["病机", "原文未出脉名，以「厥阴脉循阴器、络于肝」说明邪入厥阴，循经为病则烦满而囊缩；三阴三阳俱受病，毒气入于肠胃，故可下而愈。全段以经络受病与毒气内结言病机，未及脉象，故脉象要素为空。", []], "21954": ["主病", "「脉浮紧，无汗而发热，其身疼痛」为寒邪束表、卫阳闭郁之象，浮主表，紧主寒主痛；表证续在故当发汗。服药已微除而发烦目瞑、剧者必衄，是阳气重、郁热伤络，衄乃解，说明此脉主太阳伤寒表实证。", ["浮", "紧"]], "21955": ["预后", "天行七日以上，热势弥固而见「脉沉细」，是邪热内结、正气已衰，脉不与壮热便秘、痞满狂言相应。沉细为阳病见阴脉，正虚邪实、无力托邪，故云「众状之中，一无可救」，此脉主病势危笃之预后。", ["沉", "细"]], "21956": ["病机", "原文列阳伤寒表里相应诸热状，至「皮肤热则脉洪数，身体热」，洪数为阳热亢盛、邪在肌表之象，与心热口干苦、肝热眼赤、肺热鼻干渴等相应。脉洪数说明阳伤寒为寒所伤后阳气怫郁化热，反此则为阴伤寒。", ["洪", "数"]], "21957": ["预后", "热病体气合热、骨肉疼痛，脉「合洪数」为脉证相应；今体气反凉、「脉反沉细」，是热极而将息酷冷，热结在心、无因通泄，阳证见阴脉，故云十不救二三。洪数与沉细对举，说明脉证相反、热结危候，当作成败计。", ["洪", "数", "沉", "细"]], "21958": ["主病", "「脉浮大，鼻中燥」并言必去血鼻衄，浮为阳热上浮，大为热盛，鼻中燥是热灼肺窍、迫血妄行，故主鼻衄。此段以脉浮大合鼻燥症断其必衄，脉象与症候相参，说明阳热上盛、络伤血溢之病机。", ["浮", "大"]], "21959": ["治法", "原文未出脉名，言「灸两臂中脉取止」，并取臂脉法以鼻嗅臂、点鼻尖所著处为穴，属灸法止衄之治。全段讲取穴施灸，未及脉象与病机，故脉象要素为空，主旨归治法。", []], "21960": ["主病", "脉洪数者，洪为热盛，数为热急，此热毒内盛攻于脏腑，余气流于肌肉，结成豌豆疮之候。原文言“热毒内盛”“状如火疮”，脉洪数正应热毒炽盛之病机，故主表虚里实、热毒发疮之病，与疮色紫黑毒重等症相应。", ["洪", "数"]], "21961": ["病机", "脉缓弱，缓为气血弛纵，弱为气血衰少。原文言“经脉缓弱，血气虚，骨髓竭”，此阴阳易病新瘥交接，毒气易人，耗伤气血骨髓，故脉见缓弱，主血气虚竭之病机，与身体热冲胸、小腹里急、气力转少等症相应。", ["缓", "弱"]], "21962": ["其他", "本段未识脉名，专论热病新瘥及大病后饮食禁忌。原文强调“胃气尚虚弱，不能消化”，若食坚实难消之物必更结热，下之则胃中虚冷大利难禁，不下必死。此述误食致危之由，非脉象所主，故脉象要素为空。", []], "21963": ["预后", "本段论温病脉候，原文列“脉躁疾”“脉盛而滑”“脉疾头痛”“脉直疾”“脉疾喜吐”“脉来细”“脉不疾”“脉大疾者生”“脉细小难得者”等，以脉之躁疾盛滑辨温热毒邪炽盛，脉细小难得则正虚邪陷，故主预后吉凶之判。", ["躁", "疾", "盛", "滑"]], "21964": ["其他", "本段未识脉名，与上段《病源》文大同，述热病新瘥后食禁。原文言“胃气尚虚弱，不能消化”，强食则结热，下之则胃虚冷，皆难救。此属病后调护禁忌，非脉诊所主，故脉象要素为空，主旨归其他。", []], "21965": ["预后", "本段未识脉名，论黄病证候及死候。原文言“寸口近掌无脉，口鼻气冷，并不可疗之，必死”，以无脉、气冷判胃气已绝、阳气衰败，故主预后不良。黄病由寒湿在表、瘀热与宿谷相搏，郁蒸发黄，脉象非本段重点。", []], "21966": ["治法", "本段未识脉名，为《千金》疗急黄方。原文言“热气骨蒸，两目赤脉”，以地黄汁汤治急黄热蒸。此属治法方药，非脉象主病，故脉象要素为空，主旨归治法。", []], "21967": ["病机", "本段未识脉名，论黄疸病机。原文言“酒食过度，脏腑不和，水谷相并，积于脾胃，复为风湿所搏，瘀结不散，热气郁蒸”，故身体面目爪甲小便尽黄。此述湿热郁蒸发黄之病机，兼及疸之渴与不渴辨难疗可疗，脉象非所重。", []], "21968": ["病机", "黄汗见身体洪肿、发热汗出而渴，状似风水，然其脉不浮而自沉。沉为水湿内郁、阳气不宣之象，汗出浴水，水入汗孔，湿遏肌表，脾胃郁热与外来水湿相合，故脉沉而身肿黄汗。脉沉正说明水湿在表而阳气被遏，非单纯表虚风水可比。", ["沉"]], "21969": ["病机", "本条述黄汗身体肿、发热汗出而渴，汗沾衣色黄如柏汁，脉自沉。沉脉主水湿内郁，汗出入水，水从外入汗孔，湿阻阳气，故脉不浮而沉。脉沉与身肿黄汗相应，说明水湿郁遏营卫，宜黄耆芍药桂心酒汤以通阳化湿。", ["沉"]], "21970": ["兼症", "虚劳饮酒多谷少，胃热因醉当风入水发黄，脉浮弱知酒疸。浮为热越于外，弱为胃气不足，故心中懊痛、小便黄、面赤斑。又言腹满欲吐鼻躁脉浮者先吐之，沉弦者先下之，浮主邪在上，沉弦主邪实于里，脉象不同则治法异。", ["浮", "弱", "沉", "弦"]], "21971": ["病机", "谷疸食毕头眩、心忪怫郁发黄，由失饥大食、胃气冲熏所致。阳明病脉迟，迟主胃中有寒、运化迟滞，故食难用饱，饱则烦眩，小便难。虽下之腹必满，以其脉迟，说明中焦虚寒、谷气不运，非实热可下，脉迟为辨证关键。", ["迟"]], "21972": ["病机", "本段论疟病发作有时，邪客风府，循膂而下，卫气昼夜会于风府，邪随卫气出入而病作。因邪气日下一节，故发作日晏；间日发者，邪内搏五脏、横连募原，道远气深行迟，不能与卫气俱行，故蓄积乃作。全段无脉象描述，主述疟发时间与邪伏深浅之机。", []], "21973": ["病机", "瘅疟阴气孤绝、阳气独发，脉微为阳气虚浮而少气烦满、手足热欲呕。疟脉自弦，弦为少阳邪郁之象；弦数多热，弦迟多寒，弦小紧可下，弦紧可汗针，浮大可吐。脉弦数者风疾，以饮食消息。诸脉随邪之寒热虚实而异，示疟以弦为纲。", ["微", "弦", "数", "紧"]], "21974": ["治法", "疟脉自弦，弦数多热，弦迟多寒，弦小紧可下，弦迟温药，数而紧可发汗针灸，浮大不可针灸。本条以脉定治：弦为疟之主脉，数紧主邪实可汗，浮大主正虚忌针。又述足太阳疟腰痛头重、先寒后热，刺郄中出血，示脉证合参以择治法。", ["弦", "数", "紧", "浮"]], "21975": ["其他", "本条论胃疟证候，令人善饥而不能食，食即支满腹大，刺足阳明太阴横脉出血。原文未载脉象，主述胃疟之症与刺法。善饥不能食、食即胀满，为胃热脾弱、运化不行之象，故取阳明太阴表里两经刺血以泄其实。", []], "21976": ["主病", "温疟脉如平人，谓其脉不显疟之典型弦数，反近常度，故称“如平人”。然症见无寒时热、骨节疼烦、时呕、朝发暮解，是邪伏半表半里，正邪交争有时，脉象未能反映邪势之盛，故以白虎加桂心汤清热透邪。脉平而病疟，提示病机在气分热盛，非脉虚也。", ["平"]], "21977": ["治法", "本条言灸尺泽七壮，穴在肘中约纹动脉处。动脉指脉动应手之处，为取穴标志，非论病脉。尺泽属肺经，灸之可宣肺气、调水道，此处以动脉定位，说明灸法取穴依据，非以动脉主病。", ["动"]], "21978": ["病机", "霍乱由阴阳清浊相干、脾胃虚弱、水谷不化所致。脉来代者，脏气衰微、脉气不续；脉代而绝者，胃气将败；脉大可疗，正气尚能抗邪；脉微迟则阳气虚衰。原文列此数脉，示霍乱吐痢后脉象顺逆，代绝者危，大者可疗，微迟者虚寒。", ["代", "大", "微", "迟"]], "21979": ["主病", "霍乱吐痢后汗出、小便复利、下利清谷、里外无热，脉微欲绝，是阳气衰微、阴寒内盛之候。脉微欲绝主阳亡，故见恶寒、四肢拘急、手足厥逆，治以四逆加猪胆汤回阳救逆，兼益阴液。", ["微"]], "21980": ["主病", "霍乱卒吐下不禁，津液暴脱，脉暴数者，是虚阳外越、气阴两伤之象。暴数非实热，乃吐下后阴液骤亏、阳气浮越所致，故用人参汤益气生津固脱。脉暴数提示病势急骤，正气欲脱。", ["数"]], "21981": ["预后", "霍乱后脉绝手足冷，是吐下后阳气衰绝、不能温煦四末之危候。脉绝示心阳不振、脉道不充，手足冷为阳衰不达。原文以“脉绝手足冷”并称，示阴阳离决之势，属霍乱后危重转归，故专列方治以图挽救。", []], "21982": ["病机", "霍乱大吐下后肠胃俱虚，汗出而脉欲绝，手足皆冷，名为四逆。脉欲绝是阳气衰微、脉道失充，阴阳卒厥绝之象。吐下伤中，汗出伤阳，阳亡阴竭，故四肢逆冷，病机为阴阳气不相顺接。", ["绝"]], "21983": ["主病", "既吐且痢而大汗出、小便复利、下利消谷，里寒外热，脉微欲绝，是阳衰阴盛、虚阳浮越之候。脉微欲绝主阳气将脱，故见发热恶寒、四肢拘急、手足厥逆，治以四逆汤回阳救逆。", ["微"]], "21984": ["主病", "原文“吐已下断，汗出厥冷，四肢拘急不解，脉微欲绝”，吐下虽止而阳气未复，汗出亡阳，厥冷拘急为阴寒内盛、筋脉失温，脉微欲绝乃阳气衰微、鼓动无力之象，故主少阴寒化、阳亡液竭之危候，用通脉四逆汤回阳救逆。", ["微"]], "21985": ["治法", "本段为通脉四逆汤方后加减及服法，言“其脉即出愈”“利止脉不出者，去桔梗加人参”，以脉出与否判断阳气来复，脉不出属利止而阳未复、气阴两伤，故加人参益气生脉；又述吐利止身痛不休者消息和解其外，属霍乱后表邪未解之兼症处理。", []], "21986": ["主病", "原文“主多寒，手足厥冷，脉绝”，多寒、厥冷为阴寒内盛、阳气不能外达，脉绝非全无脉，乃阳气衰微、脉道不通、鼓动无力之极，故主寒厥亡阳之证，用千金四逆汤温阳散寒、回阳救逆。", ["绝"]], "21987": ["主病", "原文“毒冷霍乱吐痢，烦呕转筋，虚冷汗出，手足指浮肿，气息垂死绝语音声不出，百方不效，脉不通者”，吐痢交作致阴阳俱虚、冷毒内盛，虚汗出、声不出为阳气欲脱，脉不通乃气血虚极、脉道不利，主霍乱危候，用人参汤益气回阳。", []], "21988": ["病机", "原文“霍乱大吐下之后，阴阳俱虚，血气虚极，则手足逆冷而营卫不理，冷搏于筋，则筋为之转”，指出转筋由吐下后血气不足、阴阳俱虚，风冷邪气乘虚搏筋，随冷所入之筋而转动，故本段主论霍乱转筋之病机，非脉象主病。", []], "21989": ["主病", "原文“吐下不禁，两手三阴三阳脉俱疾数者”，吐下不禁则津液暴脱、阴伤及阳，脉俱疾数非单纯热象，乃阴液枯竭、阳气浮越、虚热内扰之候，疾数并见示病情急迫，主吐下过度、阴阳两伤之危重病机。", ["疾", "数"]], "21990": ["其他", "本段述灸慈宫穴部位，按语引甲乙针经“横骨两端约中动脉是”，动脉指体表可触之搏动处，用以定位穴位，非论病之脉象，故属针灸取穴之其他类，不主病机。", ["动"]], "21991": ["其他", "本段仅存“三焦脉病论二首”标题，无具体脉象与病机文字，无法据以分析脉象所主，仅可判为三焦脉病论述之篇目，内容缺佚，故归其他类，不作病机推断。", []], "21992": ["病机", "此段论三焦有名无形，主五脏六腑往还神道，贯体通水道，营出中焦、卫出上焦，上焦如雾。原文未出脉象，故脉素为空。所论重在三焦气化与营卫出入之机，非以脉候病，属三焦生理及病机总纲，提示三焦失和则水道气机不利。", []], "21993": ["主病", "原文言邪在三焦，视其结脉与厥阴小络结而血者。结脉主气血结滞、络脉不通，故见少腹坚满、不得小便、溢则为水、留则为胀。三焦气化不利，水液不行，络血瘀结，脉气因而结涩不畅，与腹胀、溺窘、水肿相应。", ["结"]], "21994": ["病机", "此段述上焦实热，饮食下胃其气未定，汗出面背身中皆热，名曰漏气。原文未出脉象，故脉素为空。所论为胃气未定而热迫上焦，腠理开泄致汗，属上焦实热、气机失守之病机，非以脉候，故归病机。", []], "21995": ["其他", "此段为方药组成，厚朴、吴茱萸、人参、茯苓等，其中橘皮去赤脉乃炮制去络，非脉象。原文无脉候内容，故脉素为空。全段属方药记载，不涉脉诊病机，归其他。", []], "21996": ["病机", "此段论中焦如沤，受气泌糟粕、蒸津液、化精微上注肺脉而为血，主足阳明。原文未出脉象，故脉素为空。所论为中焦营气化生及脾胃虚实病机：实则生热闭塞，虚则生寒洞泄霍乱，强调血与气异形同类、夺血无汗夺汗无血。", []], "21997": ["其他", "此段为方药组成，人参、橘皮去赤脉、茯苓、乌梅皮、麦门冬等，橘皮去赤脉为炮制去络，非脉象。原文无脉候，故脉素为空。全段属方药记载，不涉脉诊病机，归其他。", []], "21998": ["主病", "原文言右手关上脉沉而虚者，病善哕也。关候脾胃，沉虚主脾胃俱虚，受风邪而新谷不能传化，谷气与胃气相干，胃逆脾胀，气逆遇冷则哕。脉沉为病在里，虚为正气不足，故与善哕相应。", ["沉", "虚"]], "21999": ["预后", "原文言呕脉弱，小便复利，身有微热，见厥者难疗。呕而脉弱为胃气虚弱，小便复利则津液下夺，身微热而见厥为阴阳气不相顺接，正虚阳衰，故属难疗之候，四逆汤主之。脉弱在此提示胃气虚败、阳气欲脱之预后。", ["弱"]], "22000": ["病机", "原文未出脉象，论心痛由风冷邪气乘心。伤正经为真心痛，朝发夕死；伤支别络脉则乍间乍甚，成疹不死。说明病位深浅决定预后，络脉受邪病情较轻，正经受伤则危殆。", []], "22001": ["主病", "心脉急者，为心痛引背、食不下。急脉主寒主痛，心脉拘急，寒邪内侵，牵引背部，胃气受阻故食不下。此以脉急定心痛之诊。", ["急"]], "22002": ["主病", "寸口脉沉紧，苦心下有寒时痛。沉主里，紧主寒主痛，寒邪客于胸下，阳气被遏，故心下时痛。脉沉紧为里寒疼痛之征。", ["沉", "紧"]], "22003": ["主病", "关上脉紧，心下苦痛。关候中焦，紧脉主寒主痛，寒凝气滞于中焦，故心下苦痛。此以关部脉紧定位中焦寒痛。", ["紧"]], "22004": ["病机", "左手寸口脉沉则为阴，阴绝者无心脉也，苦心下毒痛。沉脉属阴，阴寒内盛，心阳衰绝，故心下毒痛。此以脉沉辨阴寒内盛、心脉不通之病机。", ["沉"]], "22005": ["治法", "暴冷心腹刺痛，面目青，肉冷汗出，欲霍乱吐下，脉沉细者，为寒邪内盛、阳气衰微之候。沉细主里虚寒，故以温中当归汤调诸冷痛，方证相应。", ["沉", "细"]], "22006": ["病机", "腹痛由腑脏虚、寒冷客于肠胃募原，正气与邪交争。寸口脉沉紧、尺脉紧、脉沉迟、阴弦皆主寒主痛，里寒内盛。若脉细反浮大，病与脉相反，故当愈者不即愈必死。", ["沉", "紧", "迟", "弦"]], "22007": ["预后", "心腹痛由腑脏虚弱、风寒客于其间，邪正相击，上下相攻。脉沉细小者生，大坚疾者死；沉细小为正气尚存、邪气不盛，大坚疾为邪气亢盛、正气衰败，故主死。", ["沉", "细", "大", "坚"]], "22008": ["病机", "原文诊心腹胀满之脉为「迟而滑」。迟主脏虚寒、阳气不运，滑主邪气与正气相搏、积聚在内。脾肾二经脏虚，邪客与正气相搏，气并于脾而胀，故脉见迟滑，主心腹烦满、气急而胀之候，属虚实夹杂之胀满病机。", ["迟", "滑"]], "22009": ["治法", "此段仅载「灸小指第四指间交脉上，七壮」，未识别出脉名，亦无脉象描述，故脉象要素为空。文意属灸法取穴治疗，非论脉主病，故归治法类，不涉病机推断。", []], "22010": ["病机", "原文诊寸口脉「弦而滑」，并自释「弦则为痛，滑则为实，痛则为急，实则为跃」。肝胆肾支脉虚而寒气乘之，邪正相击，故脉弦滑相搏，主胸胁相引急痛、抢息而痛，是寒邪伤经、邪实作痛之病机。", ["弦", "滑"]], "22011": ["病机", "此段言手少阳络脉虚，风邪所乘，邪迫心络，心气不得宣畅，故烦满而胸胁痛；久则搏脏成积、搏腑成聚。原文未出具体脉象，仅言络脉虚，故脉象要素为空，主旨仍在阐发烦满胸胁痛之病机及传变。", []], "22012": ["治法", "原文「其脉紧弦，此寒也，当以温药下之」。紧主寒、弦主痛，紧弦并见为寒实内结、胁下偏痛发热之候，故以大黄附子汤温下。脉象直接指示寒实病机，并据以立法处方，属脉证合参之治法。", ["紧", "弦"]], "22013": ["病机", "原文「其脉喜沉弦细迟」，沉主里、弦主饮主痛、细主虚、迟主寒。胃气弱而受冷，痰水冷气停于胸膈心腹，故心下汪洋、嘈烦多唾、胁肋急胀。四脉合见，正合虚寒痰饮内停之病机，故悉以半夏茯苓汤主之。", ["沉", "弦", "细", "迟"]], "22014": ["病机", "寒疝绕脐苦痛，发则白汗出、手足厥寒，而「脉沉弦」。沉主里、主寒，弦主痛、主寒凝，沉弦并见为阴寒内盛、寒凝气结之象，故主寒疝剧痛、厥逆之候，以二物大乌头煎温散寒邪。", ["沉", "弦"]], "22015": ["其他", "此段列举尸疝、石疝、寒疝、盘疝、血疝、脉疝七疝之名及证候，主以七疝丸，原文未识别出脉名，亦无脉象描述，故脉象要素为空。内容属疝病证候分类与方治，非专论脉，归其他类。", []], "22016": ["病机", "原文言积聚由寒气在内、血气虚弱、风邪搏于腑脏所致，气涩则生积聚。脉𫘝而紧，紧主寒，𫘝为数之变，示寒邪搏结、气机壅滞；浮而牢，浮为阳聚无根，牢主坚积。牢强急者生，因正气尚能抗邪；虚弱急者死，乃气血衰败、邪气独盛之候。", ["𫘝", "紧", "浮", "牢"]], "22017": ["主病", "原文谓痰饮由气脉闭塞、津液不通、水饮停于胸腑结而成痰，症见胸胁胀满、水走肠间漉漉有声、身体重、短气好眠、咳逆倚息不得卧、其形如肿。脉偏弦为饮，因水饮偏聚一处，脉气偏颇而弦；浮而滑为饮，浮主饮邪在表，滑主痰湿内盛，皆水饮停聚之象。", ["弦", "浮", "滑"]], "22018": ["病机", "此段辨四饮之证，痰饮水走肠间沥沥有声，悬饮咳唾引痛，溢饮身体疼重，支饮咳逆倚息不得卧。脉双弦者，饮邪偏盛；脉偏弦者，饮聚一处；脉平者，饮邪未甚；脉微者，阳气不足；脉沉滑者，水饮内停；脉沉细、脉虚者为微劳，示饮病日久，正气渐伤，虚实夹杂。", ["弦", "微", "沉", "滑"]], "22019": ["误治", "原文述服麻黄类方后汗出多者亡阳，逆虚恶风、烦躁不得眠，脉微弱、汗出恶风者不可服，服之则厥逆、筋惕肉𥆧，此为逆也。脉微弱主阳气虚衰，汗出已伤卫阳，若再发汗则阳愈虚，故见厥逆、筋惕肉𥆧等亡阳之候，明示虚人禁汗之理。", ["微", "弱"]], "22020": ["病机", "原文言酒客咳者必致吐血，因极饮过多所致；其脉虚者必冒，缘其人本有支饮在胸中。脉虚主正气不足，饮邪上冒清阳，故冒。支饮胸满者，厚朴大黄汤主之，示饮热结于胸膈，虽脉虚而实证仍在，当以攻饮为急，此虚中夹实之候。", ["虚"]], "22021": ["主病", "原文述膈间支饮，喘满、心下痞坚、面黧黑，脉沉紧，得之数十日，医吐下之不愈。脉沉主饮邪内伏，紧主寒饮凝结，沉紧相合，示水饮坚结于膈间，非一般吐下可解，故用木防己汤行水散结，此支饮重证之脉。", ["沉", "紧"]], "22022": ["病机", "原文言病者脉伏，其人欲自痢，痢者反快，虽利心下续坚满，此为留饮欲去故也。脉伏主饮邪深伏、阳气被遏，欲自痢乃正气驱饮外出之象，利后反快，然心下续坚满，示留饮未尽，故用甘遂半夏汤因势利导，攻逐留饮。", ["伏"]], "22023": ["病机", "原文言营卫俱虚，血气不足，停水积饮在于胃管则脏冷，脾不磨则宿谷不化，气逆而成胃反，朝食暮吐、暮食朝吐，心下牢大如杯。脉紧而弦，紧则为寒，弦则为虚，虚寒相搏，故食已则吐，名为反胃，此虚寒胃反之脉证。", ["紧", "弦"]], "22024": ["病机", "尺脉浮滑速疾，浮主虚阳外浮，滑主痰食内壅，数疾主热与积滞相搏。原文谓“脾胃二气俱虚弱，故不能食”，又言“食不消，脾不磨也”，是脾虚不运、胃纳不腐，宿食停滞化热，故脉见浮滑数疾。此脉主脾虚食积，与不能食、食不消症相应。", ["浮", "滑", "数", "疾"]], "22025": ["主病", "右手关上脉阳实，阳实即浮取坚实有力，主足阳明胃经实热。原文列头痛、汗不出、如温疟、唇口干、善哕、乳痈、缺盆腋下肿，皆胃热壅盛、经气不利之症。脉实为邪气盛，坚为热结，故主胃实热。", ["实", "坚"]], "22026": ["主病", "右手关上脉阳虚，即浮取无力，主足阳明胃经虚冷。原文见胫寒不得卧、恶风寒、洒洒自急、腹中痛、耳虚鸣、时寒时热、唇口干、面浮肿，皆胃阳不足、寒从中生、营卫不和之症。脉虚为阳气衰，故主胃虚冷。", ["虚"]], "22027": ["病机", "原文引经云“阳脉结谓之膈”，结脉主气机郁结不通。五膈之病，忧恚寒热气结胸膈，饮食不下、噎塞不通、心下积结，皆气结使然。脉结为阳郁不伸，故主膈病气结之机。", ["结"]], "22028": ["预后", "此段论咳嗽脉象预后。脉浮大者生，浮直者生，为邪在表、正气未败；脉弦弦欲绝者死，小硬急者死，大硬者死，大者死，为真脏脉见、胃气已绝。原文“脉反迟”亦见于咳病，迟为寒饮内伏。诸脉以胃气存亡判生死。", ["浮", "大", "弦", "小"]], "22029": ["其他", "此段为紫菀贝母茯苓杏仁等药方组成，未识别出脉名，纯属方药内容，无脉象可析。原文“橘皮（一两去脉）”之“脉”指橘络，非脉诊之脉，故脉象要素为空。", []], "22030": ["主病", "原文论十咳之证，支咳“心下坚满，咳则支痛，其脉反迟”，迟为寒饮内结、阳气不布；肝咳“咳引胁下痛”，其脉弦，弦主饮主痛。脉迟主寒饮支结，脉弦主水饮停聚，故列十咳脉证以辨病位。", ["迟", "弦"]], "22031": ["病机", "原文“咳家，其人脉弦为有水”，弦脉主饮主痛，咳家见弦，是水饮内停、上逆犯肺。水饮渍肺则咳，饮邪支撑则不能卧坐。脉弦为水气太过之象，故可与十枣汤下其水饮。", ["弦"]], "22032": ["预后", "酒客久饮致咳吐血，脉沉者示饮邪内伏、阳气不布，故不可发汗；久咳数岁脉弱为正虚邪衰可疗，实大数则邪盛正败主死；脉虚者阳虚饮泛上冒，因本有支饮在胸中，治属饮家。原文以脉之虚实判汗禁与死生，紧扣'其脉沉者不可发汗''实大数者死'。", ["沉", "弱", "虚", "实"]], "22033": ["病机", "服青龙汤后多唾口燥，寸脉沉而尺脉微，沉主饮停上焦、微主下焦阳衰，故手足厥逆、气从少腹上冲胸咽、手足痹、面翕热如醉，皆冲气挟饮上逆之象；下流阴股、小便难、时复冒，为饮邪随冲气上下。脉沉微正合阳虚饮逆、气冲之机，故以茯苓桂心甘草五味子汤治其气冲。", ["沉", "微"]], "22034": ["病机", "原文未出脉名，专论咳嗽脓血之由：肺主气、心主血，肺感于寒微则成咳，伤于阴脉则有血，咳极伤血动气，气血俱乘于肺，津液相搏蕴结成脓，故咳而脓血。其病机为损肺伤心、气血俱伤而蕴热成脓，与脉象无涉，故脉象要素从缺。", []], "22035": ["病机", "寸口脉数而咳、反有浊唾涎沫，为热在上焦、津液重亡之肺痿；发汗后阳脉早索、阴脉不涩，三焦踟蹰，津伤而内烦多唾唇燥，甚则脉浮弱。数主热，涩主津亏，浮弱主气阴两虚，故肺痿吐涎沫而不咳、遗溺小便数，皆上虚不能制下之候。", ["数", "涩", "浮", "弱"]], "22036": ["病机", "原文以右手寸口气口以前脉阴实为断，未出具体脉名。阴实者，手太阴肺经邪实也，故病苦肺胀、汗出若露、上气喘逆、咽中塞如欲呕，名肺热实。其机为肺经实热壅盛、气逆不降，实邪内结则肺胀喘逆，热迫津泄则汗出如露，与脉阴实相应。", []], "22037": ["病机", "原文以右手寸口气口以前脉阴虚为断，未出具体脉名。阴虚者手太阴肺经虚寒，故病苦少气不足以息、嗌干不津液，病名肺虚寒。其机为肺气虚寒、津液不布，气虚则息微，津不上承则咽干无液，与脉阴虚之候相合，属虚寒之肺病。", []], "22038": ["病机", "肺胀咳而上气、烦躁而喘，脉浮者，浮主表亦主水气在上，原文断为心下有水，水饮上迫于肺则咳喘烦躁。脉浮与心下有水相应，水气泛溢、肺失肃降，故宜小青龙汤加石膏，外散水寒、内清郁热。紧扣'脉浮者，以心下有水'一句。", ["浮"]], "22039": ["病机", "肺胀病人喘、目如脱状，脉浮大。浮主邪在表在上，大主邪气壅盛，水饮与热互结、肺气胀满上逆，故喘促而目睛外突如脱。脉浮大正合肺胀邪实气壅之机，故以越婢加半夏汤宣肺泄热、降逆化饮。紧扣'脉浮大也'与'目如脱状'。", ["浮", "大"]], "22040": ["病机", "脉浮为水气上逆、肺气不降之象。原文“咳而上气，肺胀，其脉浮，心下有水气”，说明水饮停于心下，上迫于肺，致肺胀咳逆。浮脉主表亦主水气，此处水气泛溢，肺失宣降，故脉浮。若见实象则躁扰倚伏，为水饮内结、气机壅滞之征。", ["浮"]], "22041": ["病机", "脉浮主水气在表，亦主肺气上逆。原文“肺胀，咳嗽上气，咽燥脉浮，心下有水”，水饮停聚心下，上逆犯肺，肺气胀满，故咳喘上气；水气不化，津不上承则咽燥。浮脉反映水气偏表、肺失宣肃之病机。", ["浮"]], "22042": ["病机", "原文以脉数辨肺痈肺痿：数实属肺痈，数虚属肺痿；脉反滑数，为热盛血凝、蓄结痈脓；寸口脉微而数，微为风，数为热，风伤皮毛、热伤血脉，风舍于肺则咳，热灼营血则凝滞成痈。脉紧数亦主热结。诸脉象共示风热壅肺、血滞成痈之病机。", ["数", "滑", "微", "紧"]], "22043": ["主病", "脉数主热，热壅肺络，血为凝滞，蓄结痈脓。原文“咳，胸中满而振寒，脉数，咽干不渴，时出浊唾腥臭，久久吐脓如粳米粥”，正是热毒蕴肺、腐肉成脓之肺痈典型症候。数脉在此反映肺中热毒炽盛、痈脓已成之病机。", ["数"]], "22044": ["主病", "脉数主肺中热毒。原文“胸中满而振寒，脉数，咽燥而不渴，时时出浊唾腥臭，久久吐脓如粳米粥”，热毒壅肺，气血凝滞，腐败成痈，故吐腥臭脓痰；热伤津液则咽燥，然有脓浊内蕴故不渴。数脉为热毒炽盛、痈脓内结之征。", ["数"]], "22045": ["平脉", "原文“定血脉和利精神”指大肠腑功能正常则血脉和利、精神安定，属平脉生理之论。大肠为传泻之腑，与肺相合，肺气宣降有序，则血脉通利、精神爽慧。此段论脏腑相合与平人常度，非病脉主病。", []], "22046": ["主病", "右手寸口气口以前脉阳实，为手阳明大肠经实热之候。原文“肠满，善喘咳，面赤身热，喉咽中如核状”，实热壅滞大肠，腑气不通则肠满；热邪上熏于肺则喘咳；阳明热盛则面赤身热；热结咽喉则咽中如核。实脉主邪气盛实、热壅大肠之病机。", ["实"]], "22047": ["病机", "肺脉厥逆大于寸口，为肺气上逆、热壅于肺之象。原文“主大肠热咳上气，喘鸣心烦”，肺与大肠相表里，肺热下移大肠，腑热上攻于肺，致咳喘上气、喘鸣心烦。厥逆脉大于寸口，示气逆于上、热邪壅盛之病机。", ["厥", "大"]], "22048": ["主病", "原文言“右手寸口气口以前脉阳虚者，手阳明经也”，脉虚主阳气不足，手阳明大肠经气虚寒，故见胸中喘、肠鸣、虚渴唇干、目急善惊、泄白等症，总属大肠虚寒之病机。", ["虚"]], "22049": ["主病", "脉浮主表，亦主气逆上浮。原文“上气，脉浮咳逆，咽喉中水鸡鸣，喘息不通”，为风寒束表、痰饮上逆之证，脉浮反映邪在表或气机上浮，故用麻黄汤宣肺解表、降逆平喘。", ["浮"]], "22050": ["其他", "本段为制药服法，未涉及脉象与病机，故脉象要素为空。文中“去子、皮、筋脉”指去除药物筋脉，非诊脉之脉，主旨属其他。", []], "22051": ["其他", "本段为方药服法及病案记述，未直接论脉。病案述“腹胀坚如石，气息不利……变哕至掣动百脉”，此“百脉”指全身经脉掣动，非脉诊，故脉象要素为空，主旨属其他。", []], "22052": ["预后", "原文论消渴“脉数大者生，细小浮者死，又沉小者生，实牢大者死”。脉数大示热盛而正气尚存，故生；细小浮为阴伤阳浮，故死；沉小者阴液虽伤而胃气未绝，故生；实牢大者邪实正衰，故死。", ["数", "大", "细", "沉"]], "22053": ["主病", "原文“消渴阴脉绝，胃反吐食方”，阴脉绝指阴液枯竭、脉道不利，非具体脉象，故脉象要素为空。此脉主消渴日久阴伤及胃，胃气上逆而反吐食之病机。", []], "22054": ["病机", "脉涩主血行不畅。原文“渴利虚经脉涩成痈脓”，消渴日久，津亏血少，经脉涩滞，营血壅遏，热毒聚而不散，腐肉成脓，故脉涩为痈脓形成之病机。", ["涩"]], "22055": ["预后", "原文“利时脉沉细微弱，服枸杞汤即效”，内消病小便大利，津液大伤，脉沉细微弱为气阴两虚之象，然服枸杞汤即效，说明胃气尚存，故预后可治；若脉转实大则危。", ["沉", "细", "微", "弱"]], "22056": ["主病", "脉细弱为气血两虚之象。久虚热、小便利多、汗出当风取冷、脚气、消渴肾消等症，皆因虚热耗伤气阴，津液外泄，故脉道不充而细弱。细弱脉主正虚，与方中阿胶滋阴养血、补虚清热相应，服之即减，说明病本在虚。", ["细", "弱"]], "22057": ["病机", "心脉滑甚为善渴，滑主热盛、津液壅聚。原文谓“腑脏因虚实而生热者，热气在内，则津液竭少，故渴也”，热盛则脉滑，津伤则渴。久病变发痈疽或水病，亦由热毒壅滞、水液代谢失常所致，滑脉反映热与津液搏结之病机。", ["滑"]], "22058": ["兼症", "脉如连珠为滑数流利之象，主热盛。面黄、咽干、手足俱黄、短气，乃湿热郁蒸、津液耗伤之候。脉如连珠提示热邪内盛，故用地黄丸除热止渴利、补养阴血，以针对热盛伤津、湿热发黄之兼症。", []], "22059": ["主病", "脉紧实者癖结也。紧主寒凝、实主邪结，饮水停聚不散，复与饮食相搏，结积胁下，故脉见紧实。原文“有时弦旦起，或胀痛，或喘息短气”，皆由癖结阻滞气机所致，紧实脉正反映寒饮与食积搏结之实邪内聚。", ["紧", "实"]], "22060": ["主病", "脉弦而大者寒癖也。弦主饮癖、主痛，大主邪实，寒饮停积胁下，遇寒即痛，故脉弦大。原文“饮水停积胁下痃强”“因遇寒即痛”，说明寒癖为寒饮结聚、气机不通之病，弦大脉应之，反映寒实内结之病机。", ["弦", "大"]], "22061": ["治法", "原文未识脉名，“脉筑筑然”指手下有搏动应指之感，非正式脉象。此段述癖根所在，以手循按寻找“筑筑头”作为施灸定位，属外治取穴之法。所主病机为癖积有根、结聚于背膊，故以灸法温通消散，非凭脉断病。", []], "22062": ["病机", "原文列多种积聚脉象：𫘝而紧、浮而牢、小沉实、细䎡附骨等，皆主积邪内结。贲豚为肾积，发于少腹上至心下，若豚奔走，由寒邪留结、脏气传变所致。脉紧牢主寒实，浮主邪在表，小沉实主里实，细䎡附骨主积深着骨，诸脉皆反映积聚寒实、气机逆乱之病机。", ["𫘝", "紧", "浮", "牢"]], "22063": ["预后", "积为阴气五脏所生，聚为阳气六腑所成，皆寒气搏于脏腑所致。寸口脉细沉滑主积聚在胁下，紧而牢主横积结痛而泄痢，脉微细者生，浮者死。微细为正气尚存、脉证相应，故生；浮为正气外越、阴阳离决，故死，此段重在凭脉判断积聚之预后。", ["细", "沉", "滑", "紧"]], "22064": ["病机", "原文言积聚宿食由\"腑脏为寒气所乘，脾胃虚冷\"，谷不化而留积。脉来实，非正气之强，乃寒积内结、气机壅滞之象，实因虚冷生积，积成反见实脉。故主心腹积聚、饮食不消、胃中冷，脉实与虚冷积滞之候相应，提示本虚标实之病机。", ["实"]], "22065": ["治法", "此段为气痞丸方证，述寒气痞积、聚结不通、绕脐切痛、腹中胀满、胸逼满，兼风入脏、忧恚所积、筋脉伤而羸瘦不能食。原文未出脉象，故脉素取空。其病机为寒凝气滞、积结于内兼情志所伤，方药令人强嗜食益气力，属治法类，示温通气机、扶正消积之意。", []], "22066": ["预后", "原文论症由寒温失节、腑脏气虚、食饮不消，聚结渐长成\"块段盘牢不移动\"。脉弦而伏，弦主积结气滞，伏主邪深牢着、阳气不行，正合症块盘牢之形。若积引岁月，人柴瘦腹转大，脉症相应而\"其症不转动者必死\"，故本段主旨为预后判断，脉伏示生机内闭。", ["弦", "伏"]], "22067": ["主病", "原文谓寒气客于五脏六腑，因虚而发，上冲胸间则胸痹，见胸中愊愊如满、噎塞、咳唾引痛、烦闷白汗出等。脉浮而微，浮示寒邪上冲于胸，微示阳气虚衰、胸阳不振，正合\"责其极虚\"之义。故脉浮微主胸痹本虚寒客之病机，并明言\"不治数日杀人\"，示其危重。", ["浮", "微"]], "22068": ["病机", "原文以\"阳微阴弦\"论胸痹而痛，责其极虚，阳虚在上焦，阴弦为寒饮内动，故胸痹心痛。又述喘息咳唾、胸背痛、短气，脉沉而迟、关上小紧数，沉迟主阳虚寒凝，小紧数主寒饮搏结、阳气被遏。诸脉共示上焦阳虚、阴寒痰饮痹阻之病机，为栝蒌汤证之所本。", ["弦", "沉", "迟", "紧"]], "22069": ["主病", "此段承仲景胸痹之病，喘息咳唾、胸背痛、短气，寸脉沉而起，关脉小紧数。寸沉示胸阳不振、饮邪内停；关小紧数示中焦寒饮搏结、气机紧束而迫。脉症合参，主胸痹病，属阳微阴弦、痰饮痹阻胸中之候，故以栝蒌薤白白酒汤通阳散结、豁痰下气主之。", ["沉", "小", "紧", "数"]], "22070": ["病机", "原文论贲豚为肾之积气，起于惊恐忧思，神志伤动，气积于肾而上下游走如豚之贲。肾脉微急沉厥，微示肾气不足，急示气逆躁动，沉示病在里、气郁于下，厥示阳气不达而手足厥逆。脉症相合，主惊恐忧思伤肾、气逆上冲之病机，兼足不收、不得前后。", ["微", "急", "沉"]], "22071": ["其他", "此段为灸中府穴之法，言穴在云门下一寸、乳上三肋间动脉处，灸百壮或百五十壮。动脉乃指体表可触之搏动处，用以定穴，非论病之脉象。故本段主旨属针灸取穴之其他类，动脉仅作定位标志，不反映特定病机，亦不主病。", ["动"]], "22072": ["病机", "脉蒸根在心，脉数主心火亢盛。原文载“日增烦闷，掷手出足，翕翕思水，口唾白沫，卧即浪言，或惊恐不定”，皆心火扰神、津液被灼之象。数脉为热，热盛则蒸，故脉数对应心蒸之病机，甚则变为疳而脐下闷或暴痢。", ["数"]], "22073": ["病机", "脉蒸其根在心，“其脉又数”重申数脉主心热。原文“日增烦闷，掷手出足，翕翕思水，口唾白沫，卧便浪语，或惊恐不安”均属心火内炽、神明被扰。数脉应热，热郁则蒸，盛则变疳旁脐时闷或痢不止，脉数正是心蒸热盛之征。", ["数"]], "22074": ["主病", "“两脊脉常急”指脊膂两侧脉紧急，主骨蒸传尸之病。原文先乍寒乍热、唇颊赤、痢血多唾、咳盗汗、黄瘦，皆阴虚火旺、瘀虫蚀肺之候。急脉示邪伏脊膂、气血壅迫，故按捻脊膂四边肉可察气满急，膂肉尽则著床难灸。", ["急"]], "22075": ["治法", "原文未识脉名，仅言“胸前有青脉出者，以针刺看血色”，此青脉指体表络脉，非脉象要素。全段主在服药与针刺治法：丸药无毒，粥饮送服，青脉刺血辨色，未变黑者七日必瘥。故归治法，不取脉象。", []], "22076": ["其他", "本段论骨蒸将息调养，未及具体脉象。原文“热甚则血脉拥塞，头眩目疼”乃热邪致血脉壅塞之病机描述，非脉诊。主旨为寒温得所、饮食软少、先热而脱先寒而著等将养之法，属调护禁忌，故归其他。", []], "22077": ["主病", "原文未识脉名，仅述飞尸“又名恶脉”及“发时急头痛，不在一处，针灸则移”等症。恶脉指病邪在皮中络脉，非脉象。全段主飞尸病候与附著散方治，故归主病，不取脉象要素。", []], "22078": ["病机", "原文未识脉名，论遁尸“停遁在人肌肉血脉之间”，卒犯则心腹胀满刺痛、气息喘急、旁攻两胁、上冲心胸，瘥后复发。此述病邪潜伏血脉、随触而动之机，非脉象。故归病机，脉象要素为空。", []], "22079": ["病机", "原文未识脉名，“人有三百六十脉，走入皮中”指疰病邪入皮中络脉，非脉诊。症见寒热、喉咽如鲠、胸中痛、绕脐痛、面黄青白黑，随月盛衰，至死注易。此述疰病传注之机，故归病机，不取脉象。", []], "22080": ["病机", "原文谓白虎病由风寒暑湿之毒因虚所致，将摄失理而受风邪，致“经脉结滞，血气不行”，蓄于骨节四肢。脉结滞正应经脉气血壅阻不通之机，故其病昼静夜发、彻髓酸疼，如虎啮之状，肉色不变，皆气血痹阻骨节之候。", ["结", "滞"]], "22081": ["其他", "此段为犀角、当归、芍药、牛膝、沉香、青木香、虎头骨、麝香、槲叶脉等组成的疗白虎方药，属方治内容，未言脉象主病。原文“槲叶脉”为药名而非脉诊，故脉象要素为空，主旨归为其他，不涉病机推断。", []], "22082": ["主病", "原文论盗汗因阳虚所致，久不已则羸瘠枯瘦、心气不足、亡津液。诊男子平人脉“虚弱细微”，虚微为阳气不足，细弱为阴津亏耗，正合阳虚不固、津液外泄之机，故以此脉为盗汗之脉，与眠睡汗出、消瘦枯槁相应。", ["虚", "弱", "细", "微"]], "22083": ["病机", "此段论风中五脏，各随脏腑生病，心中风偃卧不得倾侧、唇色变化主心坏为水，肝中风踞坐不得低头、面青黑主肝伤，皆示脏气已败。脉虚弱者，正气不足，风邪乘虚中脏，故见脏真外露、预后凶险之候，与原文“因虚”受风之旨相合。", ["虚", "弱"]], "22084": ["预后", "原文疗中风发于春，谓“脉浮短者多凶，大而长可疗”。春时风木用事，中风而脉浮短，浮为邪在表，短为气不足、脉道不利，示正虚邪盛、气血难续，故预后多凶；大而长则气血尚充，故可疗。此以脉之长短判吉凶。", ["浮", "短"]], "22085": ["兼症", "原文疗中风发于夏，脉沉紧，症见恶寒不汗而烦。夏当阳盛，脉反沉紧，沉主里、紧主寒，示寒邪闭郁于里，阳气不得外达，故恶寒无汗；阳郁化热则烦。脉症相合，为外寒内郁、表闭阳郁之候，故用三阳汤。", ["沉", "紧"]], "22086": ["病机", "原文疗中风发于秋，脉浮大而洪长。秋令收敛，脉反浮大洪长，浮大为邪盛于外，洪长为阳热有余、气血涌盛，示风邪夹阳热亢盛、不得收敛之机。脉与秋令相违，故以扶金汤调之，寓抑木扶金、制其亢盛之意。", ["浮", "大", "洪", "长"]], "22087": ["病机", "原文疗中风发于冬，脉浮大者用温脾汤。冬令闭藏，脉宜沉潜，反见浮大，浮为阳气外浮不藏，大为邪气有余，示脾阳不足、不能镇摄，虚阳浮越于外。故以温脾汤温运中阳，使阳气内守，脉症相应，属阳虚浮越之候。", ["浮", "大"]], "22088": ["主病", "脉浮为风邪在表，数为发热之征。原文言“中风发热，头痛面赤，吸吸苦热，恶风烦闷”，正是风邪袭表、卫阳奋起抗邪之象。浮脉主表，数脉主热，风热相搏于肌腠，故见恶风烦闷、身中悁悁而疼。此脉浮数，说明病位在表、病性属热，与防风汤所疗之中风发热证相应。", ["浮", "数"]], "22089": ["主病", "脉动不安，指脉象躁动不宁、应指无定。原文述“毒风贼风”内侵，致身体不能自收、不知痛处、咽中卒不得语、拘急腰痛、反张脊不著席，皆风邪深入、筋脉拘急之候。脉动不安反映风毒扰攘、气血逆乱，神不守舍，故兼恍惚恐惧欲啼、上气呕逆面肿。此脉主风毒内盛、脏腑气机失和之病机。", ["动"]], "22090": ["预后", "原文论诸阳经筋皆络于头面颔颊，风寒客之则筋急，故口噤不开。诊其脉迟者生，迟为脉来从容和缓、胃气尚存之象，说明正气未败、阳气犹能运行。口噤属筋急之实证，若脉见迟和，则示邪未深陷、生机尚在，故断为可生。此以脉迟判断口噤之预后，强调胃气与阳气存亡。", ["迟"]], "22091": ["预后", "原文言风邪入足阳明、手太阳之经，遇寒则筋急引颊，致口㖞僻、言语不正、目不能平视。脉浮而迟者可疗：浮为风邪在经、病位尚浅，迟为寒凝筋脉、气血运行不畅。浮迟并见，说明风邪未深入脏腑，阳气虽受寒遏而未尽衰，故属可疗之候。此以脉象判断口㖞之预后，强调邪浅正未大伤。", ["浮", "迟"]], "22092": ["治法", "本段为灸法操作记载，未识别出脉名，亦无脉象描述。原文述“灸手交脉三壮，左灸右，右灸左”，并详述艾炷燃烧如鼠屎形、横安两头放火之法，属外治灸疗口㖞的具体施术。因无脉象内容，不能据脉论病机，仅记治法操作，故归入治法类，脉象要素为空。", []], "22093": ["主病", "原文“厥逆无脉手足拘急”，无脉指脉伏不见、按之难寻，属阳气衰微、不能鼓动血脉之危候。卒中风不能言，为风邪中脏、窍闭神匿；厥逆无脉，示阳衰气陷；手足拘急，为筋脉失温养而挛急。三者并见，说明中风之候已至阳气欲脱、经脉凝滞之重证，四逆汤回阳救逆正对此病机。脉象要素因“无脉”而空。", []], "22094": ["病机", "原文论风寒之气客于中，滞不能发，故喑不言、喉疼失声。尸蹶如死而“脉动如故”，说明虽形似死状，然脉气仍动，生机未绝。阳脉下坠、阴脉上争，气闭不通，故致昏厥失音。脉动如故是判断尸蹶与真死之关键，反映气机一时闭阻而非脉气断绝，故主气闭昏厥之病机。", ["动"]], "22095": ["病机", "本段未识别出脉名，无脉象描述。原文从经络立论：脾脉络胃夹咽、连舌本、散舌下，心之别脉系舌本，今心脾二脏受风邪，故舌强不得语。其病机为风邪中于心脾之络，气血痹阻，舌本失养而强急。全段以经络脏腑解释舌强不语之因，未涉脉诊，故脉象要素为空，主旨归病机。", []], "22096": ["主病", "原文诊脾脉缓为风痿，四肢不用。因脾气弱则肌肉虚，风邪伤脾胃经络，搏于阳经，气行迟而关机缓纵，故脉缓。缓为脾土本脉，病则缓纵无力，主肌肉不用、手足不随，与风邪乘虚、四肢失禀相应。", ["缓"]], "22097": ["主病", "寸口沉细，名阳中之阴。脾胃气弱，血气偏虚，风邪乘之，致半身不随。沉细为气血不足、阳气不布之象，故见悲伤不乐、恶闻人声、少气汗出、臂偏不举，与血气偏虚、风邪中经相应。", ["沉", "细"]], "22098": ["病机", "原文未出脉名，述风猥退由皮肉薄弱不胜虚风，邪侵分肉、流于血脉，致四肢不收、身体疼痛、肌肉虚满、骨节懈怠、腰脚缓弱。病机在虚风入分肉血脉，久则变风水，非以脉断，故脉象要素从缺。", []], "22099": ["病机", "原文言脉虚则筋肉懈惰。胃气衰损，其气不实，气不实则经脉虚，经脉虚则筋肉懈惰，风邪搏筋而亸曳。虚脉主胃气衰、经脉失养，故肢体弛缓不收摄，与胃虚风搏之机相应。", ["虚"]], "22100": ["主病", "脉动而弱为惊悸。体虚心气不足，风邪搏心，惊不自安则悸动不定。动为惊，弱为悸：动者气乱于中，弱者心气不足，故见目睛不转、不能呼，与心虚风乘、惊悸不宁相应。", ["动", "弱"]], "22101": ["兼症", "大竹沥汤证见百脉掣动，属大虚风气入腹，拘急心痛、恍惚惊悸、历节疼痛，或缓或不摄，产妇体虚受风，并疗风痉口噤背强反折。掣动言脉体拘急跳动，主虚风内动、筋脉失柔，与诸症相应。", ["掣", "动"]], "22102": ["其他", "本条为深师续命汤方证，未出脉名。述大风风邪入心，心痛彻背、去来上下惊恐、小腹胀满微痛、乍寒乍热、心中闷、面青白黄，虚劳邪气入百脉。病机在虚劳风邪入百脉，百病皆疗，非以脉断，故脉象从缺。", []], "22103": ["主病", "原文列五癫诊脉：心脉微涩为癫疾，脾脉紧而疾者癫脉。微涩主心气不足、血涩不荣；紧疾主风邪急搏。又肾急甚为骨癫，洪大长、浮大附阴、牢疾皆癫，紧急可疗，虚可疗，沉细小者死，脉搏大滑生，沉小急疾不可疗，示脉象关乎预后。", ["微", "涩", "紧", "疾"]], "22104": ["病机", "原文未出具体脉名，仅言「寸口阴阳表里互相乘」，指寸口脉阴阳表里相互乘袭、脉位交错，反映体虚阳经脉为风所乘。诸阳经脉上走头面，腠理开而受风，故头面多汗恶风、甚则头痛；风久入脑则变头眩。脉象互乘正是风邪乘虚入经、表里失和之征。", []], "22105": ["病机", "原文言「诊其脉洪大而长者，风眩」，又「得阳维浮者，暂起目眩」。洪大而长为血气上涌、风邪入脑之象，血气虚而风邪乘之，引目系急故眩；阳维浮主表邪暂起，故目眩暂作。脉洪大长示风阳上盛，久不瘥则变为癫。", ["洪", "大", "长", "浮"]], "22106": ["病机", "原文明言「脉浮而大，浮为风虚，大为气强，风气相搏，即成瘾疹，身体为痒」。浮主风邪客于皮肤，大主气强，风气相搏于肌腠，故发风搔瘾疹；赤疹因凉湿搏热，白疹因风热相搏，皆由此风气相搏之机而致身痒。", ["浮", "大"]], "22107": ["病机", "原文述风热发时「头项脉掣动急强」，指头项部脉络掣动、紧急强直。风热之邪上攻头项，脉络受灼而拘急，故脉掣动急强，兼热毒疹痒。此非寸口常脉，乃风热壅盛、筋脉失柔之病机外现。", ["急", "强"]], "22108": ["其他", "此段言灸当容穴定位法，以手按之「有上下行脉则是」，指按取穴处可触到上下走行的脉络，用以确定客主人穴所在。所述「脉」为体表络脉，非诊病之脉象，故不属主病病机，仅为取穴标志，列于其他。", []], "22109": ["其他", "此段为栀子竹茹汤方药组成，其中「去脉」指橘皮去其脉络（橘络），属炮制去杂之语，非脉象描述。全段为方剂配伍，不涉诊脉主病，故脉象要素为空，归入其他。", []], "22110": ["病机", "原文言「脉不营则筋急」，指脉气不能营润筋脉则筋脉拘急。肝应筋，肝虚风则筋虚善悲、转筋；肝实风则善怒嗌干、胁下痛。脉不营为筋失濡养之机，故见筋急、转筋、十指爪痛等症，虚实皆可致筋病。", ["急"]], "22111": ["其他", "此段仅存「脉极论一首」标题，无具体脉象与病机正文，无法据以分析所主病证。脉极当指脉气耗极之论，然原文未展开，故脉象要素为空，暂归其他，不作臆测。", []], "22112": ["病机", "原文以“脉空虚”言心脉痹阻、气血不荣之虚象，又分“脉气实则热”“脉气虚则寒”，阐明心风虚实两候：实则热伤心，令人好怒、口赤、言语不快；虚则寒，咳而心痛、喉中介介如哽。脉虚为气血衰少，脉实为邪热内盛，故治疗“脉实宜泻，气虚宜补”，紧扣脉与心合、病从脉起之旨。", ["虚", "实"]], "22113": ["其他", "此段仅为“脉热极方三首”之标题，未载具体脉象描述与病机条文，故脉象要素为空。从标题可知其主旨为脉热极之证治方药，属治法类内容，但原文无脉象与症候细节可析，不能强解病机。", []], "22114": ["病机", "原文直言“脉实热极，血气伤心”，脉实为邪热炽盛之象，热极则血气燔灼，伤心之神明，故“使心好生赫怒”，口色变赤、言语不快。此脉实主热极伤心、血气逆乱之病机，治以茯苓汤消热、止血气、调脉理中，体现脉实宜泻、热者清之之法。", ["实"]], "22115": ["病机", "此段未明写脉象，然标题“脉极热”已示热极之机。原文述“伤风损脉为心风”，心风状多汗无滋润，乃风热伤脉、心液外泄所致；热极消虚，故见汗多而燥。其病机为风热损脉、心气耗散，治以麻黄汤止汗消虚热，属脉极热之证治。", []], "22116": ["病机", "原文“脉热极，遇风为痹，痹感心”点明热极遇风、痹阻心脉之机，而“脉空虚”正是气血不荣、痹阻日久之外候。脉虚故颜脱色白不泽，热郁则口唇色赤干燥。此脉空虚主心痹虚热夹杂、营血不荣之病机，治以升麻润色消痹止热极汤，寓补虚清热、宣痹润色之意。", ["虚"]], "22117": ["其他", "此段仅为“脉寒极方四首”之标题，未载脉象描述与具体症候，故脉象要素为空。从标题可知其主旨为脉寒极之证治方药，属治法类内容，原文无脉症细节可析，不能凭空推断病机。", []], "22118": ["病机", "原文“脉极虚寒则咳”明言脉虚主寒，虚寒内盛则肺气上逆而咳；咳甚则心痛，乃寒邪循脉上逆、心脉挛急所致；“喉中介介如哽，甚则咽肿喉痹”为寒郁咽喉、气机不利之象。此脉虚寒主心肺阳虚、寒饮上逆之病机，治以半夏消痛止极益气汤，温阳益气、消痛止极。", ["虚"]], "22119": ["病机", "原文“脉极虚寒，鬓发堕落”指出脉虚为气血虚寒、不能上荣之候。发为血之余，虚寒则血不荣发，故鬓发脱落。此脉虚寒主阳气衰少、血不荣发之病机，治以桑白皮沐头方外治，安发润生，体现内虚外治、养血润发之法。", ["虚"]], "22120": ["病机", "原文论肉极主脾，脾病则肉变色，肌痹不已复感于邪内舍于脾，见体淫淫如鼠走、津液脱、腠理开、汗大泄、鼻上色黄。此段未出脉名，以症候言病机：脾主肌肉，脾虚则肉无所养，卫外不固故津脱汗泄；里虚外实、阳动伤热则唇口坏、皮肤色变，皆脾肉之极，非脉象所主。", []], "22121": ["病机", "原文论气极主肺，肺病先发气上冲胸、常欲自恚，阴伤则寒而虚、气逆咳短气暮甚，阳伤则热而实、气喘息上胸臆甚则唾血。段中未出脉名，以阴阳表里衰旺言病机：肺主气，寒湿客于六腑则气逆，热实则气壅，故知以阳调阴、以阴调阳，为气极虚实之辨。", []], "22122": ["病机", "原文论骨极主肾，肾病则骨极牙齿苦痛、手足酸疼、不能久立、屈伸不利、身痹脑髓酸。气阴则虚寒，面肿垢黑、腰脊痛、发堕齿槁；气阳则实热，面色炲、膀胱不通、耳鸣色黑。段中未出脉名，以阴阳清浊言病机：肾主骨，虚寒则骨失温养，实热则髓枯骨痛，须精别阴阳、审其清浊。", []], "22123": ["病机", "原文论精极通主五脏六腑病候，五脏六腑衰则形体皆极，目视无明、齿焦发落、耳聋行步不正。阳邪害五脏则高而实热，腹中满、历节痛宜泻于内；阴邪损六腑则下而虚寒，体重、肾水生。段中未出脉名，以阴阳升降言病机：精不足者补之以味，形不足者温之以气，先疗肌肤筋脉次及六腑五脏。", []], "22124": ["主病", "原文言肾气虚损不能藏精故精漏失，症见少腹弦急、阴头寒、目眶痛、发落。诊得脉数而散者，为失精之脉：数因虚阳浮动，散因精血耗散不敛；脉芤动微紧，芤动主精血虚而阳扰，微紧主虚寒内结，故男子失精。脉象与肾虚不藏、精液漏失之病机相应。", ["数", "散", "芤", "动"]], "22125": ["兼症", "原文为小品龙骨汤疗梦失精，症见心悸少急、隐处寒、目眶疼、头发脱，而诸脉浮动。浮为阳虚外越，动为精虚阳扰、心神不宁，故梦遗失精而兼心悸；隐处寒、目眶疼、发脱皆肾精亏虚、阳失温煦之兼症。脉浮动与梦失精之虚阳不藏病机相应，故用龙骨汤镇摄。", ["浮", "动"]], "22126": ["治法", "原文为灸法取穴：灸足内踝上一寸，一名三阴交，二七壮，两脚皆灸，内踝大脉并四指是。此处大脉指踝间明显可触之脉，用以定穴位分部，非言病机。三阴交为足三阴交会，灸之可温补脾肾肝，主虚损失精诸疾，属治法取穴之文，脉字仅作定位标识。", ["大"]], "22127": ["病机", "原文借黄帝问高阳负，言素女明知经脉脏腑虚盈，男子五劳七伤、妇人阴阳隔闭、漏下赤白、绝产无子，并列七伤：阴汗、阴衰、精清、精少、阴下湿痒、小便数少、阴痿行事不遂。段中未出具体脉名，以经脉脏腑虚盈为纲，说明七伤皆由元本虚损而起，治随病形、冷热风药加减小便。", []], "22128": ["病机", "原文以“脉大为劳”“脉浮大”“脉浮而迟”“脉涩无阳是肾气少”“脉浮微缓皆为虚”“脉微濡相薄为五劳”论六极七伤。大、浮为劳伤气浮于外而内虚；迟为阳气不足；涩为肾气少、精血不充。诸脉皆指向五脏虚损、正气少而邪气多，故见羸瘦、少气、发毛落、喜忘等虚劳之候。", ["大", "浮", "迟", "涩"]], "22129": ["病机", "本段为淮南王枕中丸方证，未出脉象。原文言“胃气不和，发于五脏虚劳”，小便或难或数，多思，脾气不和，宿食热所为，流入百脉，食饮不进，沉滞著中隔。其病机为胃气失和、宿食郁热流注百脉，致五脏虚劳，故以丸药调中和胃、消食化滞。", []], "22130": ["治法", "本段为古今录验薯蓣丸方证，未出脉象。原文列头痛目眩、手足逆冷、烦热有时、冷痹骨疼、食多不生肌肉、少食胀满、体涩无光泽、阳气衰绝、阴气不行等，皆五劳七伤阴阳俱损之候。方药能补十二经脉、起发阴阳、通内制外、安魂定魄，属补虚通滞之治法。", []], "22131": ["主病", "原文诊腰痛：“尺脉沉主腰背痛，寸口脉弱腰背痛，尺寸俱浮直下，此为督脉腰强痛。”尺沉为肾经虚损、风冷乘之；寸弱为阳气不足、腰背失养；尺寸俱浮直下则病属督脉，腰强痛。诸脉皆围绕肾虚风冷、督脉不利之腰痛病机，并列少阴、风痹、肾虚、坠堕、湿地五类腰痛。", ["沉", "弱", "浮"]], "22132": ["治法", "本段为备急陶氏肾气丸方证，未出脉象。原文主“短气、腰痛身重”，调中补筋脉不足。短气为肾不纳气，腰痛身重为肾虚水湿不化、筋脉失养。方以肾气丸温补肾气、调中补虚，属补益肾气、强筋脉之治法，与前述肾虚腰痛病机相承。", []], "22133": ["治法", "本段为范汪大行谐散方证，未出脉象。原文主“强中益气，补力不足，长养肌肉，通和百脉，调利机关，轻身润泽，安定五脏，强识不忘”。其旨在于补气强中、通和百脉、调利机关，属补虚强壮、安养五脏之治法，针对虚劳力不足、肌肉不长、百脉不和之证。", []], "22134": ["治法", "本段为甘草丸方证，未出脉象。原文主“安养五脏，长肌肉，调经脉，下气，补脾胃，益精神，令人能食，强健倍力”。其病机为五脏失养、脾胃虚弱、经脉不调，故以丸药安养五脏、补脾胃、调经脉、下气益精，属补虚健脾、调脉安脏之治法。", []], "22135": ["病机", "原文论虚劳伤冲脉：“上部之脉微细”“寸口脉阳弦下急，阴弦里急”“寸微关实尺弦紧”。微细为虚劳内损、气血不足；弦急为冲脉拘急、胃气虚；尺弦紧为少腹腰背拘急痛。诸脉共示虚劳肾气不足、冲脉失养而腹里拘急，兼胃气虚、食难用饱之候。", ["微", "细", "弦", "紧"]], "22136": ["病机", "原文论不眠病源，谓邪客五脏六腑，卫气独营于外，行于阳不得入于阴，阳气盛而阴气虚，故目不得眠。虽未言脉，然卫气“悍剽疾利”之行失常，脉当应其阳盛阴弱之机，此段重在阐明营卫阴阳失调之病机。", []], "22137": ["病机", "原文以“瞥瞥如羹上肥”喻阳气微，“连连如蜘蛛丝”喻阴气衰，阴阳衰微而风邪入肾经，故阴不起或引少腹痛。此段借脉象描述阐发肾虚阴痿之病机，脉虽未明言，然微细欲绝之象已寓其中。", []], "22138": ["治法", "虚劳服散，虚热盛又当风取冷，患脚气发动兼小便利，脉细弱示气血虚少、阴阳俱损。细弱之脉主虚劳不足，故以阿胶汤滋阴养血、温阳化气，服后利减，乃脉证相应之治法。", ["细", "弱"]], "22139": ["预后", "脚气病气上入腹，胸胁逆满，气喘肩息，白汗数出，乍寒乍热，脉促短而数，呕吐不止，皆死候。促短而数乃邪毒攻心、正气欲脱之象，脉证不符，故断为死。", ["促", "短", "数"]], "22140": ["其他", "此段仅为“论脉候法”标题，无具体脉象与病机论述，故脉象要素为空，主旨归为其他，不涉主病、病机等具体内容。", []], "22141": ["预后", "论脚气诊候，强调三部之脉须不违四时者为吉，逆四时者勿治。又言黑瘦者易治，肥大肉厚赤白者难愈，因肉软则受疾至深。此段以脉应四时及体质判断预后，未出具体脉名。", []], "22142": ["病机", "脚气病由感风毒所致，初起症状繁多。脉得浮大而缓为常，若转快而紧、微而弱、浮大而紧快、沉细而快，或与浮大而紧同，皆为恶脉，示风毒内攻、正气衰败之病机，故列诸恶候。", ["浮", "大", "缓", "紧"]], "22143": ["预后", "脚气本因肾虚，肥溢肌肤者易患。晋宋前名缓风，后因肿满从脚起故名脚气。脉沉紧者多死，沉紧主毒气内攻、阴寒凝滞，故预后不良；缓脉则示病情较缓，然亦须防毒气上攻。", ["缓", "沉", "紧"]], "22144": ["主病", "脚气复发见恶寒壮热、头痛手足冷，似疟似伤寒，而脉甚洪急。洪为热盛，急为毒气壅迫，说明冷毒与热邪交争、壅滞经脉。脉洪急而非浮缓，故知非单纯外感，乃脚气毒气暴发之候，七日壮热退后脚气本状方显，冷毒盛胀、热盛胀皆由此洪急之脉可辨。", ["洪", "急"]], "22145": ["病机", "风毒入体脉分三品：浮大而缓为风邪在表、证较轻，宜续命汤；浮大而紧转快为风盛邪急，宜竹沥汤；脉微而弱则因虚而得，宜风引汤。浮大而紧快为三品中最恶，沉细而快与之同属恶脉，浮大者病在外、沉细者病在内，皆示风毒深入、正气将败，故数日气上便终。", ["浮", "大", "缓", "紧"]], "22146": ["预后", "风毒初得似天行毒病，而脉浮缓终不变快，是邪毒内陷而脉不应病、正气不能鼓邪外出之象。脉当转快而不转，说明毒气滞留营分，故或数日死、或十日死，见不识人、发黄、发斑、目赤、下部穿烂等危候。此最急，须续命汤接续服之，不可半日缺汤。", ["浮", "缓"]], "22147": ["病机", "脉沉细驶，沉主病在里，细为血少，驶即数急，示风邪入内、痹阻经脉而血气不足。前文屡言浮大为病在外，此则沉细为风在内，故用竹沥汤清内风、通经络。脚弱先服竹沥汤未觉增损，作此方后觉得力，正合沉细驶、风在内之病机。", ["沉", "细"]], "22148": ["预后", "毒气攻心，手足脉绝，是邪毒内陷心包、阳气不能达于四末之危候。脉绝非寻常虚损，乃毒盛气闭、血脉不通所致，故云此亦难济。不得已作茱萸汤温通降逆，十愈七八，说明虽属险证，尚可借温阳下气之法挽回，然预后仍凶。", []], "22149": ["其他", "此段为漏芦、葳蕤、乌蛇脯、苦参、防己等药之方剂组成，未载脉象与证候。苦参“捣去筋脉取粉”乃炮制之语，非诊脉之脉。全段属方药记录，无从据脉论病机，故脉象要素为空，主旨归入其他。", []], "22150": ["主病", "风偏枯由血气偏虚、风湿客于分腠，血气凝涩不能润养而成。诊胃脉沉大、心脉小牢急，皆为偏枯之应：沉大示邪滞于里，小牢急示血脉拘急不通。男子废左、女子废右，若不喑舌转者可疗，年未满二十者三岁死，尺中神门以后脉虚则病恶风偏枯，由愁思忧思所致。", ["沉", "大", "小", "牢"]], "22151": ["病机", "体虚腠理开，风邪客于筋，春遇痹为筋痹，邪客关机则筋挛。脉急细如弦者，急为筋脉拘急，细为血虚，弦为肝风，肝主诸筋，故主筋急足挛、四肢拘挛不得屈伸。若筋屈不已又遇邪，则移变入肝，见夜卧则惊、小便数，说明筋痹日久内传于肝。", ["急", "细", "弦"]], "22152": ["病机", "原文述导引动作后云'去膊内风，两膊并内冷血，两腋筋脉挛急'，脉挛急指腋下筋脉拘急之象，非寸口脉象。其病机为风冷客于膊内、血行不畅，筋脉失养而拘挛，故以导引极势来去换易以散风冷、通血脉，属外风冷血致筋脉挛急之候。", ["急"]], "22153": ["预后", "原文'诊其寸口脉缓，则皮肤不仁'，缓主荣气虚、卫气实，风寒入肌肉使血气不宣流，故搔之如隔衣。又'不仁脉虚数者生，牢急疾者死'，虚数示荣气虽虚而胃气尚存，牢急疾则邪实正败，故以脉之虚实判生死，属风不仁之预后。", ["缓", "虚", "数", "牢"]], "22154": ["病机", "原文未出脉名，述风湿由风气与湿气共伤人，腠理开而受之，症见懈惰、精神昏愦，久则四肢缓纵不随，入脏则喑痖口舌不收，或脚痹弱变为脚气。其病机为风湿外袭、气血壅滞、经络不利，久则内传入脏，属风湿致痿痹脚气之病机。", []], "22155": ["主病", "原文'疗风湿脉浮身重，汗出恶风方'，脉浮为风湿在表、卫气不固，身重为湿邪留着肌肉，汗出恶风示表虚风袭。浮脉主表，与身重、汗出、恶风相应，正合风湿袭表、营卫不和之病机，故以方治之，属风湿主病之脉。", ["浮"]], "22156": ["其他", "本段罗列阳陵泉、绝骨、风市、昆仑、阳辅、上廉、条口、下廉、太冲等穴定位及异说，未及脉象与病机，属针灸取穴之考订。文中辨风市出处、绝骨与阳辅异同，皆为腧穴定位之辨，与脉诊病机无涉，故列其他。", []], "22157": ["病机", "原文'心下有脉洪大跳，其数向下，分入两髀股内，令人心急忪悸'，洪大跳动示气逆上冲、心气不宁，其数向下分入髀股为气散不敛、下注之象。故灸少腹傍脉动处及三里以引气下行，属气逆冲心、悸动不安之病机。", ["洪", "大", "数", "动"]], "22158": ["病机", "原文述大指或小指傍侧疼闷，'觉内有脉如流水，上入髀腹'，此非寸口脉，乃指局部脉络跳动如流水上逆。其病机为经气循指傍上逆入髀腹，气血壅滞而疼闷，故随指傍灸三炷以通经散滞，属经络气逆之病机。", []], "22159": ["治法", "原文论四肢灸法不宜过多，须依经数，惟脚气风毒灸之务欲多；又辨八木之火不可用，松柏橘桑枣竹枳榆各有伤皮肉筋骨之害，主张用阳燧、䃈石、槐木之火。全段言灸治火法之宜忌，属治法范畴，未涉脉象病机。", []], "22160": ["主病", "原文论水病由胃虚不能传化水气，水气溢于皮肤而肿，症见目里上微肿、颈脉动时咳、股间冷。脉沉者，水气内停，沉为水病之应；脉洪大者，水气壅盛于外，洪大为邪实可疗之象。若见唇黑、缺盆平等五伤，则脏气败绝，脉虽洪大亦不可疗，故以脉之沉与洪大辨水病之可疗与不可疗。", ["沉", "洪", "大"]], "22161": ["病机", "原文辨水与肤胀、鼓胀、肠覃、石瘕之别。水病始起目里上微肿、颈脉动时咳、阴股间寒、足胫肿，脉自浮或沉迟，浮为水溢皮肤，沉迟为水寒内结；肤胀脉亦浮，为寒气客于皮肤；肠覃脉沉迟，为寒气客于肠外、癖而内著。诸脉随病位浅深而异，浮主表浅，沉迟主里寒，以脉之浮沉迟别水病与肠覃等证。", ["浮", "沉", "迟"]], "22162": ["误治", "原文论水病难疗，瘥后须慎口味，病水人多嗜食不廉。医者不本性命，劝令食羊头蹄肉，羊头蹄极补，而水病百脉之中气水俱实，疗之皆令泻之使虚，补之则水气愈壅，故未见一愈者。又蛊胀但腹满不肿，水胀四肢面目俱肿，医者不善诊候，疗蛊以水药、疗水以蛊药，皆属误治，仲景所谓医杀之。", []], "22163": ["病机", "原文述卒大腹水病初起，先两目上肿起如老蚕色，侠颈脉动，股里冷，胫中满，按之没指，腹内转侧有声。侠颈脉动为水气上逆、经脉壅塞之征；此病从虚损大病、下痢后或妇人产后饮水不即消，三焦决漏，小便不利，水气渐聚流于经络而成。脉动在此示水气搏击经脉，病已成犹可疗。", ["动"]], "22164": ["兼症", "原文述大腹水病身体肿、上气、小便涩赤、脐深，颈上有两大脉动，唾稠不得眠睡。颈上两大脉动为水气上壅、脉道不利之候，与上气、唾稠并见，示水邪犯肺、气逆不降。肿先随脚肿或头面肿，大便涩者服此药佳；若先患大便利、脐凸腹大胀、手掌平满，则脾肾已败，不可服此药。", ["动"]], "22165": ["主病", "原文论风水由肾脾气虚弱，肾劳汗出逢风，风气内入客肾，脾虚不能制水，水散溢皮肤，又与风湿相搏。症见身浮肿如里水之状、颈脉动时咳、按肿上凹而不起、骨节疼痛恶风。脉浮大者名风水，浮为风邪在表，大为水气外溢，浮大并见示风与水合、病位偏表，故以脉浮大定风水之名。", ["浮", "大"]], "22166": ["病机", "原文疗大风水脉浮，浮为在表，其人或头汗出，表无他病，但下重，故知从腰以上为和，腰以下当肿及阴，难以屈伸。脉浮示水气与风邪偏于表分，头汗出为风阳上蒸，下重、腰以下肿及阴为水湿下注。浮脉在此说明病位在表在上，故治以木防己汤宣散水湿。", ["浮"]], "22167": ["主病", "原文疗风水恶风，举身悉肿，脉浮不渴，欲自有汗而无大热。脉浮为风邪袭表、水气泛溢；不渴示里无热邪，欲自有汗而无大热示表气尚和、热势不盛。举身悉肿与恶风并见，为风水相搏、肺失宣降之候，故以越婢汤发越水气、兼清郁热。脉浮在此主风水在表之病机。", ["浮"]], "22168": ["病机", "原文谓肾虚则水妄行、流溢皮肤，身体面目悉肿、按之没指而无汗、四肢重，此水在皮腠之候。脉浮者，水气与风相搏，病位偏表偏上，故以浮脉定名皮水，与风水相类而别于里水之沉，浮脉在此标示水溢皮肤、病势向外之机。", ["浮"]], "22169": ["病机", "原文谓肾虚水气妄行、不依经络、停聚结在脐间，少腹肿大鞭如石，引胁下胀痛而不喘。脉沉者水结于里、病位深在脐腹，故名曰石水；脉微大亦曰石水，微为阳气不足、大乃水势壅盛，正虚邪实并见，故肿起脐下上至胃管则死不疗。", ["沉", "微", "大"]], "22170": ["病机", "原文述寒热当风、饮多暴肿身如吹，乃风邪外袭、饮邪内动、风水相激之候。脉浮主邪在表、水溢肌肤，数主热与邪争，浮数并见说明表有风热而水饮暴发，故用泽漆汤逐水清热，脉浮数正是可攻之凭据。", ["浮", "数"]], "22171": ["其他", "此段为眼热眦赤、生赤脉息肉、急痛难开如芒在眼之证，并出大枣煎方，原文未及脉象，故脉象要素为空。所论重在邪热攻目、血脉蕴结之候与治法方药，属眼病证治范畴，不能据以推断脉机。", []], "22172": ["其他", "此段仅列防风、细辛、芎䓖、白藓皮、独活、甘草、橘皮、大枣、甘竹叶、蜜等药味及分量，属方药组成，原文无脉象描述，故脉象要素为空。其主旨为眼病之方治，非论脉候病机，归入其他。", []], "22173": ["病机", "原文谓息肉淫肤由邪热在脏、气冲于目、热气攻于血脉、蕴积不散而结生息肉，在于白睛肤睑之间。全段论目病之因，以邪热蕴结血脉立说，未涉脉象，故脉象要素为空；其主旨明病机而非主脉，归病机。", []], "22174": ["其他", "此段述肝热不止、冲眼为眦赤脉、息肉闭痛不开、热势彭彭不歇及目睛黄，并出洗肝干蓝饮方，原文未载脉象，故脉象要素为空。所论为肝热上冲之眼候与方治，属证治范畴，归其他。", []], "22175": ["其他", "此段详述煎服之法、食后服药、敷药抽热毒风，及以冷肝肉贴疼痛脉上、候肝肉暖熟以验热毒之候，并及斋忌无肉以大豆代之。原文无脉象描述，脉象要素为空；主旨为眼病外治与服药调护，归其他。", []], "22176": ["误治", "原文述天行病后犯食毒、房室，致“鬓边脉掣，微似憎寒”，愚医妄针灸补药而失明。脉掣指鬓边脉络拘急引痛，非脉象本身，乃风毒热邪上攻头目、络脉壅滞之征。此段主旨在于告诫误治之害，故归为误治。", []], "22177": ["治法", "原文“眼疼，脉掣连耳热疼不可堪者”，脉掣指脉络拘急牵引，连及耳部热痛，为风热邪毒壅滞少阳经脉之候。段中给出鼢鼠土膏外疗方，属外治法，故主旨为治法。", []], "22178": ["病机", "原文“手少阳之脉动而气厥逆而耳聋者”，脉动指手少阳经脉搏动异常，因厥气上逆搏入耳脉而聋，候见耳内辉辉焞焞。此段论耳聋病机，强调经脉厥逆、气搏耳脉，故归病机。", ["动"]], "22179": ["病机", "原文“其经脉虚，风邪乘之，风入于耳之脉，使经气否塞不宣，故为风聋”，脉虚指足少阴经脉气虚，风邪乘虚入耳，经气壅塞而聋，时头痛。此段阐明风聋由经脉虚而风邪外袭所致，属病机。", ["虚"]], "22180": ["病机", "原文“劳伤于肾，宗脉虚损，血气不足，为风邪所乘，故成耳聋”，脉虚损指宗脉血气亏虚，风邪停滞不去，久聋乃成。此段论劳伤致虚、风邪久滞之病机，故归病机。", ["虚"]], "22181": ["病机", "原文“宗脉则虚，风邪乘虚随脉入耳，与气相击，故为耳鸣”，又诊寸口“浮则为阳”“阴阳俱虚者，此为血气虚损，宗脉不足”。脉虚浮示血气亏虚而风邪外乘，肺与大肠俱虚，故耳鸣嘈嘈、眼妄见花。属病机。", ["虚", "浮"]], "22182": ["病机", "原文“劳伤血气，热乘虚而入于其经，邪随血气至耳，热气聚则生脓汁，故谓之聤耳”，未出脉名，然劳伤血气、热乘虚入经是聤耳病机核心，热聚耳窍化腐成脓。此段主论聤耳成因，故归病机。", []], "22183": ["病机", "原文“耳中策策痛者，皆是风入于肾之经也”，风邪入肾经上攻耳内，与气相击故痛；邪流入肾则脊强背直成痉。段中未出脉象，而论风邪入经、肾候腰脊之病机传变，故归病机。", []], "22184": ["病机", "原文以“脉脏调和”为顺，肺气通鼻，脉和则鼻气通利而知香臭；若风冷伤脏腑、邪乘太阴经，气蕴积于鼻，津液壅塞、鼻气不宣调，则不知香臭而为鼻齆。此段从脉之调和与否推演肺经气机通塞，脉和主无病，脉失和则主风冷蕴鼻之病机。", []], "22185": ["其他", "本段未出脉名，主述手阳明支脉入齿、风冷客经络伤骨髓而致齿痛，及虫食齿根有孔之痛，并载针灸敷药与叩齿导引诸法。所论重在齿痛病因与治法，非以脉断病，故脉象要素为空，归入其他。", []], "22186": ["治法", "原文仅载“灸外踝下高骨前交脉三壮”，属针灸取穴治法，未言脉象及病机。所灸部位在足外踝前交脉处，为治齿痛等症之施灸法，故脉象要素为空，主旨归为治法。", []], "22187": ["病机", "原文言齿为骨之所终、髓之所养，手阳明支脉入齿。若髓气不足、阳明脉虚，不能荣养牙齿，风冷乘虚所伤，故牙齿相引而痛。脉虚正应髓气不足、阳明经气亏虚，不能荣齿，风冷得以客之，主牙齿疼痛之病机。", ["虚"]], "22188": ["病机", "本段未出脉名，言手阳明支脉入齿、足太阳脉入颊遍齿，其经虚则风气客之，络搏齿间与血气相乘，断肿热气、脓汁出而臭，侵食齿断，谓之龋齿。所论以经虚受风、血气相乘成肿腐为病机，故脉象要素为空。", []], "22189": ["病机", "原文言头面有风，阳明之脉虚，风乘虚随风流入于齿，则令齿有风微肿而根浮。脉虚正合阳明经气不足，风邪乘虚而入，客于齿根，故齿微肿而浮动。此脉主经虚受风之齿病病机，与齿根浮肿相应。", ["虚"]], "22190": ["预后", "本段未出脉名，述齿龈虚软无脓血及口䘌、口疳、口瘘、齿疳诸症，特别指出唇口吻变白或青紫黑色者为急疳之状，死不过旬日，宜急疗。所论重在辨症候轻重与死生预后，故脉象要素为空，主旨归为预后。", []], "22191": ["病机", "原文言手阳明支脉入齿，头面有风而阳明脉虚，风挟热乘虚入齿龈，搏于血，故血出。脉虚说明阳明经气不足，风热乘虚搏血于齿龈，血溢而出。此脉主经虚受风热之齿衄病机，与齿龈出血症候相应。", ["虚"]], "22192": ["病机", "原文未出脉名，专论紧唇病源。脾胃有热，气发于唇则生疮；疮又被风邪寒湿之气搏结，故微肿湿烂、或冷或热、乍瘥乍发。其病机为脾胃积热为本、风寒湿外搏为标，属本虚标实、寒热错杂之候，久则积月累年难愈。", []], "22193": ["病机", "原文未出脉名，论燕口疮病源。足太阴脾、足阳明胃、手阳明大肠三经并夹于口，脏腑虚则风邪湿热乘虚而入，气发于脉与津液相搏，故生疮湿烂有汁。病机关键在“腑脏虚”而“风邪湿热所乘”，属正虚邪客、湿热蕴蒸之候。", []], "22194": ["病机", "原文未出脉名，论舌为心与小肠之候及五味偏嗜伤脏。多食咸则舌脉凝而变色，多食辛则舌筋急而枯干，示五味太过可致舌脉凝涩、筋急枯干。又言脏热则生疮唇揭赤色，腑寒则舌本缩、口噤唇青，明舌病有寒热虚实之别，治宜寒补热泻。", []], "22195": ["病机", "原文未出脉名，论瘿病由忧恚气结或饮沙水所致。恚气结成瘿者垂核捶捶然无脉，饮沙水成瘿者有核㿔㿔然无根、浮动在皮中。其“无脉”“浮动”正说明气结与沙水随气入脉、搏结颈下，属气滞痰凝、脉络壅阻之病机。", []], "22196": ["治法", "原文未出脉名，属瘿病外治掐法。平旦手挽瘿令离项，掐其下根使脉断则愈，一日一度，易愈者七日、难瘥者三七日。其“脉断愈”指掐断瘿核下连之脉络，使气血不复贯注，属以通为治、断其病根的外治思路，非论脉象主病。", []], "22197": ["治法", "原文出“动脉”二字，指耳后发际阴骨骨间小穴处有动脉应手，可准前法施灸而大效。此处动脉为取穴定位之标志，非以脉候病机，故其主旨属灸法取穴之治法，动脉仅示穴位所在、气血所过之处。", ["动"]], "22198": ["病机", "原文论喉痹，风毒客于喉间、气结蕴积生热，故喉肿塞痹痛、水浆不入。脉沉者为阴、浮者为阳，以辨邪之浅深；右手关上脉阴阳俱实，是喉痹之候，实象示风毒蕴热结聚于上，故令人壮热恶寒，七八日不治则死，兼含预后之意。", ["沉", "浮", "实"]], "22199": ["预后", "原文未出脉名，论寒热瘰疬即鼠瘘，寒热之气稽留于脉而不去，本在脏而末上出于颈腋。其决生死之法在望目：赤脉从上下贯瞳子者，见一脉一岁死，递增至三脉三岁死；赤脉不下贯瞳子者可疗。以赤脉贯瞳之多少判预后吉凶。", []], "22200": ["治法", "原文为五香连翘汤方治恶肉恶脉、恶核瘰疬、风结肿气痛，未出脉象。所主病机为风毒结聚、气血壅滞，致恶肉恶脉、结核瘰疬肿痛。方以五香行气散结、连翘解毒消肿，故本条属治法方药，非脉诊主病，脉象要素无从取。", []], "22201": ["治法", "丹参膏主恶肉结核瘰疬、脉肿气痛，原文未载脉象。其病机为瘀毒结聚、脉络壅阻，故见结核瘰疬及脉肿气痛。丹参活血消癥、通脉散结，制成膏剂外敷内服，属治法类条文，无脉象可辨。", []], "22202": ["主病", "原文言「结脉寒热，如瘰疬痛不可近」，结脉主气血痰毒结聚、脉道不利。毒气壅于肌肉，气血结滞不行，故肌肉中肿痛、结脉而寒热，状如瘰疬痛不可近。急者数日杀人，示毒结深重、传变迅速，当急与大五香汤解毒散结，并以滓敷肿脉上。", ["结"]], "22203": ["主病", "转脉瘘发于颈，如大豆浮在脉中，濯濯脉转，苦惊惕、身如振寒热。原文「浮在脉中」「脉转」为描述瘘核随脉转动之状，非独立脉名。其根在小肠，得于惊卧失枕，病机为惊气内动、痰毒结于脉络，故以斑蝥攻毒散结、白芷为佐。", []], "22204": ["其他", "本条列举狼瘘、鼠瘘、蝼蛄瘘、蜂瘘、蚍蜉瘘、蛴螬瘘、浮沮瘘、瘰疬瘘、转脉瘘九种，属瘘病分类名目，未涉脉象与具体病机分析。转脉瘘之名源于瘘核转动于脉中，然本条仅列名，故归其他，脉象要素为空。", []], "22205": ["主病", "本条与转脉瘘条同文，言瘘发于颈如大豆浮在脉中、濯濯脉转，苦惊惕、身如振寒热，得于惊卧失枕，根在小肠。「浮在脉中」「脉转」为瘘核形态描述，非脉象要素。病机为惊则气乱、痰毒结于颈部脉络，斑蝥主之、白芷为佐以攻毒散结。", []], "22206": ["病机", "原文论瘘病有鼠蛇蜂蛙蚓之类，皆从饮食中得其精气，入人肌体变化成形，疮既穿溃则浸淫诸经脉，故亦能杀人。其病机为饮食秽毒内侵、化生瘘虫，溃后毒邪浸淫经脉，耗伤气血。鼠蚁最多，因近人易染，全条未出脉象。", []], "22207": ["病机", "本条辨痈疽之别：荣卫稽留经脉，血泣不行，卫气从之不通，壅遏化热，热胜肉腐为脓，然不陷肌肤骨髓、五脏不伤，故为痈；疽则热气纯盛，下陷肌肤筋髓骨肉，内连五脏，血气竭尽，筋骨良肉无余。以皮之坚薄泽夭辨候，未出脉象，主在病机。", []], "22208": ["其他", "原文仅列“五为胡脉，六为五脏俞，七为五脏系”，属脉诊部位与脏腑配属的框架性论述，未描述具体脉象形态，故无从推求病机。其意在建立脉与五脏俞、系之对应，为后续凭脉定位脏腑提供依据，非主病、主症之文。", []], "22209": ["病机", "原文述䐔病“赤脉起如编绳，急痛壮热”，由“四肢劳热气盛，为凉湿所折，风结筋中”而成。赤脉如编绳即热盛血壅、风结筋脉之象，非脉诊之脉。热盛为凉湿所折，气不散则变䐔，甚则消溃去脓、筋挛缩，点明热壅血瘀、风湿相搏之病机。", []], "22210": ["治法", "原文“针写上结脉处”指以锋针泻去血络结聚之处，此“结脉”指体表赤脉结聚，非脉诊之结脉。全段讲漏芦汤内服令下、锋针泻血、敷小豆薄外消，属痈肿丹毒之治法，故归治法类，不涉凭脉断病。", ["结"]], "22211": ["主病", "“脉洪粗难疗，脉微涩者易疗”，洪粗为热毒壅盛、邪实正充，故难疗；微涩为气血已伤、毒势渐衰，故易疗。“诸浮数之脉，应当发热而反恶寒者，痈也”，浮数主热，热盛当发热，反恶寒乃毒邪深伏、附骨成脓，营卫被遏之征，故以脉症相参断痈。", ["洪", "粗", "微", "涩"]], "22212": ["预后", "原文述夭疽“大而赤黑”，不急疗则“热气下入渊腋，前伤任脉，内熏肝肺，十余日死”。赤黑为热毒炽盛、血瘀肉腐之象，热毒循经内陷，伤任脉、熏肝肺，故预后凶险。全段重在判断转归死期，非脉象主病之论。", []], "22213": ["预后", "原文“待筋脉平复，乃可任意耳”，指痈疽溃后新肉初生，须待筋脉气血平复方可纵欲劳烦；否则“新肉易伤，伤则重溃发”。此处“脉平复”言脉气平和、正气来复，为疮口向愈之兆，故归预后，强调慎风冷劳烦、断绝房室以保平复。", ["平"]], "22214": ["病机", "“疗痈疽溃漏，血脉空竭方”，言痈疽久溃成漏，脓血外泄，血脉空虚竭乏，故以内塞散补塞内虚。空竭指脉中气血耗损、正虚不能托毒，属溃漏日久、气血两伤之病机，非寻常脉象描述，而为立方之依据。", ["空", "竭"]], "22215": ["预后", "原文以“急入暗中，以手掩左眼，竟视右眼见光者”辨胸中结痈，不见光则瘭疽内发；又述齿间臭热血出“是瘭疽也，七日死”，毒“逐脉上，入脏杀人”。臭血、黯疱、瘆痛入心皆热毒炽盛、内攻脏腑之候，故断死期，归预后。", []], "22216": ["其他", "原文未识别脉名，仅述瘭疽症状与治法。文中“毒散逐脉，入脏杀人”强调毒邪沿脉内陷，非论脉象。所述“根不浮肿”“根深至肌”描述局部病灶，与脉诊无关。故本条主旨为病证描述与外治、内服疗法，不涉及脉象主病机。", []], "22217": ["预后", "水谷痢由体虚风邪客于肌肉，脾胃大肠虚弱而致。原文以脉判预后：“脉小”为血气尚弱之应；“脉大手足温”示胃气未绝；“脉沉则生”因沉主里，邪未外散；“脉不悬绝滑大者生”见胃气尚存；“脉缓时小结者生”缓为脾脉，小结示邪衰。诸脉皆以胃气存亡、邪正盛衰定生死。", ["小", "大", "沉", "缓"]], "22218": ["预后", "冷痢由肠胃虚弱受寒，痢色青白黑为冷。诊脉“沉则生，浮则死”：沉主里，寒邪在里，脉应沉，为脉证相符，故生；浮为阳气外越，里虚寒盛而脉反浮，是胃气败绝之兆，故死。此以脉之沉浮辨里寒之存亡，非主病机。", ["沉"]], "22219": ["主病", "血痢由热毒乘血，血渗大肠。原文“关上脉芤大，便去血，暴下血数升”：芤为血虚，大为热盛，关候中焦，热毒迫血妄行，故暴下血。脉芤大与“身热者死，身寒者生”相参，示热毒炽盛、血脱之候。", ["芤", "大"]], "22220": ["病机", "原文未识别脉名，论湿毒挟热与血相搏成血痢。文中“毒气侵食于脏腑，如病蛊注之状”述病机深重，“痢血杂脓瘀黑，有片如鸡肝”为症候。全段无脉象描述，故脉象要素为空，主旨为病机阐发。", []], "22221": ["预后", "脓血痢由春伤风、夏热乘之，血渗肠间化脓。原文以脉判预后：“脾脉微涩者为内溃”微涩示脾虚血腐，故多下脓血；“脉微小者生”邪衰正未竭；“脉沉细虚迟者生”沉细虚迟为里虚寒，脉证相符。反“实急”“数疾大而有热”则邪盛正衰，故死。", ["微", "涩", "沉", "细"]], "22222": ["病机", "原文未识别脉名，论赤白痢病机。文中“荣卫不足，肠胃虚弱，冷热之气乘虚而入”为总因；“热乘于血，血渗肠内则赤”“冷气入肠搏于肠间，津液凝滞则白”分述赤白；“冷热相交，故赤白相杂”释鱼脑痢。全段无脉象，故脉象要素为空。", []], "22223": ["主病", "原文“其脉如涩方”述肠滑下痢脓血、日数十行、腹中绞痛、身热头痛之候。涩脉主血少津伤，又主气滞血瘀。下痢日久，阴血耗伤，脉道不充，故脉涩；身热如火、头痛如破为热毒上攻，涩脉示正虚邪恋、血络瘀滞之病机。", ["涩"]], "22224": ["其他", "本段为五痔分类及主治方药，未涉及脉象。文中按气痔、牡痔、牝痔、肠痔、脉痔分述证候与用药，如'生肉如鼠乳在孔中颇见外''更衣挺出，久乃缩''更衣出清血'等，皆据症辨痔，非凭脉断病，故无脉象要素可析，主旨属方药证治而非脉学病机。", []], "22225": ["病机", "原文谓蛔虫腹痛'其脉法当沉弱弦'，沉弱弦为虫动脏虚、气机郁滞之常脉；今反见'洪而大'，洪大为热盛气逆，与虫扰气聚、去来上下之痛相应，故脉变洪大即提示蛔虫为患。此以常脉反脉对举，说明脉证不符时当从实际脉象辨虫。", ["沉", "弱", "弦", "洪"]], "22226": ["兼症", "此段为方药加减法，言妇人房劳、肾中有热、小便难利、腹满痛而'脉沉细者'，加猪肾。沉细主肾虚阴伤、热郁于内，与房劳伤肾、肾热膀胱不利之小便难、腹满痛相应，故于原方加猪肾以补肾利水，属据脉施治的兼症处理。", ["沉", "细"]], "22227": ["病机", "原文论气淋由'肾虚膀胱热气胀'所致，热气流入胞，令胞内气胀、少腹满、尿涩余沥。诊'少阴脉数者，男子则气淋'，数脉主热，少阴候肾与膀胱，热蕴下焦故脉数，正合膀胱热气胀之病机，说明数脉在此标示下焦热实成淋。", ["数"]], "22228": ["病机", "原文论大便难由五脏不调、冷热虚实结于肠胃，又邪在肾则津液枯燥、肠胃干涩。诊左手寸口人迎以前手少阴脉，'脉沉为阴，阴实者，病苦闭闷，大便不利，腹满，四肢重，身热'；沉主阴，实主邪结，阴实则气机闭阻，故见闭闷、便难、腹满身热，脉象直指冷热结聚之病机。", ["沉", "实", "紧", "滑"]], "22229": ["病机", "原文论关格由阴阳气不和、营卫不通，阴阳俱盛不得相营，气痞结腹内胀满，大小便不通。诊'脉来浮牢且滑直者，不得大小便也'，浮牢主邪气坚结于外，滑直主气机壅实，脉象反映阴阳痞结、三焦约闭之实象，故主关格二便不通。", ["浮", "牢", "滑"]], "22230": ["病机", "原文论小便不通由膀胱与肾俱有热，热入于胞，热气大盛，结涩令小便不通，少腹胀，甚则水气上逆、心急腹满。诊'脉紧而滑直者，不得小便也'，紧主热结收引，滑直主热实气壅，脉象与肾膀胱热结、水道闭涩之病机相应，故主小便不通。", ["紧", "滑"]], "22231": ["治法", "本段言足大趾奇间有青脉，以针挑血出、灸三壮取愈，属外治刺灸之法，未述脉象。青脉显露为络脉瘀滞之征，挑刺出血以通络，灸以温散，主旨为治法操作，非脉诊病机，故无脉象要素可录。", []], "22232": ["病机", "原文言小便难由肾与膀胱热、水气涩所致，热势微故但难。诊尺脉浮、濡、缓皆主小便难。浮为热在表，濡为水湿不化，缓为热微而水行迟涩，故脉见缓而小便难且有余涩。三脉均反映肾与膀胱气化不利、水热互结之病机。", ["浮", "濡", "缓"]], "22233": ["病机", "遗尿由膀胱虚冷、不能约水。肝脉微滑亦遗尿，微为阳虚，滑为水液不摄；左手关上脉沉为阴绝，尺脉实主少腹牢痛、小便不禁，尺中虚亦不禁。肾病小便不禁脉当沉滑而反浮大，为土克水之逆。诸脉皆示肾与膀胱虚冷、阳气衰微、水失约束之机。", ["微", "滑", "沉", "实"]], "22234": ["其他", "原文述忍小便致胞转、大小便不得、困笃欲死无脉，服方得瘥。无脉因水气闭阻、气机骤塞，非阴阳竭绝，故服药可瘥。此段重在记录治法效验，脉象缺如，病机为胞转气闭、水道不通。", []], "22235": ["病机", "小便数由膀胱与肾俱虚、客热乘之。虚不能制水故数，热则水行涩而小便不快，故数起。趺阳脉数主胃中有热，消谷引食、大便硬、小便数。数脉在此示客热内乘、水液偏渗之机，非单纯实热。", ["数"]], "22236": ["预后", "中恶因精神衰弱、鬼邪猝中，症见心腹刺痛、闷乱欲死。脉紧大而浮者死，紧细而微者生；吐血数升脉沉数细者死，浮焱如疾者生。紧大浮为邪盛正溃、气浮无根，故死；紧细而微为邪退正虽弱犹存，故生。脉示预后吉凶。", ["紧", "大", "浮", "细"]], "22237": ["病机", "猝死无脉、无他形候，原文断为阴阳俱竭。无脉因阴阳气血一时竭绝，脉道不充，非必有形症可察。此段以无脉为据，说明猝死之阴阳离决病机，属危候。", []], "22238": ["病机", "猝死而有脉形候，原文谓阴气先尽、阳气后竭。有脉形候而猝死，示阴先竭而阳未全绝，故脉尚存形候。此与无脉之阴阳俱竭相对，说明猝死有阴阳先后竭绝之异，脉形可辨。", []], "22239": ["病机", "尸厥由阳脉猝下坠、阴脉猝上升，阴阳离居、营卫不通。症如死而脉尚动、形无知。寸口脉沉大而滑，沉为实、滑为气，实气相搏，入腑身温汗出可自愈，入脏唇青身冷即死。脉动示真气未绝，沉大滑示实气搏结。", ["沉", "大", "滑", "动"]], "22240": ["病机", "原文谓尸厥“脉动而无气”，脉虽动而气息闭绝，是气机闭塞不通、阴阳不相接续所致。脉动为生机尚存之象，无气则气闭于内，故外见静卧如死。此段以脉动与无气并见，说明尸厥病机在气闭不通，非脉绝，故可治。", ["动"]], "22241": ["病机", "原文言尸厥“脉动如故”，并释为“阳脉下坠，阴脉上争，气闭故也”。风寒客于脏间，滞而不发，致喑不能言、喉痹失声。脉动如故说明脉气未绝，病机关键在于阴阳升降失常、气闭不通，故形如死而脉仍动。", ["动"]], "22242": ["病机", "崔氏论尸厥“脉动而形，无所知”，又言“阳脉下坠，阴脉上争，营卫不通”。脉动说明生机未息，形无所知、息不常则因营卫不通、阴阳相争、气闭于内。此段以脉动与神昏息微并见，阐明尸厥气闭营卫不通之病机。", ["动"]], "22243": ["主病", "原文论蛊毒，蛇蛊“其脉洪壮”，蜴蜥蛊“其脉浮滑而短”。洪壮为热毒壅盛之象，故腹内热闷、舌本胀强、唇口干燥；浮滑而短主毒邪偏表而兼痰湿壅滞，故腰背微满。脉象随蛊毒种类而异，说明蛊毒害人势甚，脉以毒邪壅盛为主。", ["洪", "浮", "滑", "短"]], "22244": ["预后", "此段论金疮禁忌与死候，未及脉名。原文列“破脑出血而不能言语，戴眼直视，咽中沸声，口急唾出，两手妄举”皆死候，又言伤天窗、眉角、脑户及五脏六腑输等“皆是死处”。所述以症候判断预后，强调金疮出血、脏气受损则危，非以脉断。", []], "22245": ["误治", "此段论灸不依明堂脉穴、触犯时忌及灸后房室等，致“灸疮洪肿，发作疼痛”，反增火毒，甚则“火毒伤脏即死”。原文未出脉名，主旨在于灸法失当、火毒伤脏之误治后果，故归误治，强调取穴合宜、避忌有时。", []], "22246": ["病机", "崔氏论代指，谓“五脏之气使然，流注于十二源经脉，热冲手指不还，即代指也”。原文未及脉象，专述代指成因：五脏之气流注经脉，热邪冲指不去，聚而成病。其病机在热壅经脉、气血不还，故指端肿痛，属病机论述。", []], "22247": ["治法", "此段详述制药蒸煎之法及敷药疗瘤，未出脉名。原文强调血瘤及“左右胡脉及上下悬雍舌本诸险处”不可令消，消则血出不止杀人。主旨为外敷消瘤之治法与禁忌，故归治法，示人辨瘤施药、避险处。", []], "22248": ["治法", "本段为外涂瘢痕的食疗与涂敷法，未涉脉象。取白鸡以油脂水煮小麦饲之，再空饲清水七日，取猪脂去脉膜切啖，粪凝白，暖水取涂瘢上，粗葛布揩微赤后涂。'去脉膜'指剔除猪脂中筋膜，非诊脉之脉，故脉象要素为空，主旨属外治涂瘢之法。", []], "22249": ["病机", "本段论癞病由恶风及犯触忌害而得，初觉皮肤不仁、淫淫苦痒如虫行、目见物如垂丝、瘾疹赤黑，为疾始起。风邪初入皮肤不能自觉，流通四肢、潜于经脉，致毛腠理壅塞难通、气血精髓乖离，久则顽痹、汗不流泄、手足酸疼。全段言风毒入经之病机，未出脉象。", []], "22250": ["病机", "本段论禀形须摄养，将息失度则百病萌生。四时代谢、阴阳递兴，暴气每月必有，猝遇大风大雾大寒大热，入人四体、顿折皮肤、流注经脉，使腠理壅隔、营卫结滞，阴阳之气不得宣泻，变成痈疽疔毒恶疮诸肿。主旨为外邪入经、营卫结滞之病机，原文未及脉象。", []], "22251": ["病机", "本段言肿著口边颊中舌上，赤黑如珠子、疼痛应心，为寒毒久结所变。'流入诸脉数道如箭入身'，数道指多条脉路，非脉数之数；然其毒邪流注诸脉、捉人不得动摇，反映寒毒结聚、脉道壅遏之病机，故取'数'以标脉道受邪之象，主寒毒久结、毒流诸脉之恶候。", ["数"]], "22252": ["治法", "本段为牛蒡根煮粥食疗方：取牛蒡根二茎净洗煮烂，盆中研细，去筋脉取汁下米煮粥，咸淡任性服一碗。'去筋脉'指去除牛蒡根中纤维筋络，非诊脉。全段属饮食调治之法，未涉脉象与病机推断，故脉象要素为空。", []], "22253": ["其他", "本段仅列'肃州（肉苁蓉百脉根）'，为药物产地及品种记载，'百脉根'系药名，非脉象描述。原文无病机、主病或症候内容，属本草出处条目，故脉象要素为空，主旨归入其他，不作病机分析。", []], "22254": ["其他", "本段论古医自解采取、阴干曝干如法、用药依土地，故疗十得九；今医但知诊脉处方，不知采药时节、出处土地、新陈虚实，故疗十得愈五六。'诊脉处方'为泛论医事，非具体脉象。主旨批评不谙药性产地之弊，属医论，脉象要素为空。", []], "22255": ["治法", "本段为丸药服法及主治：蜜丸梧子大，酒服二十丸渐加至五十丸，病在下空腹、病在上食后，以宣利为度。主治风气结聚、宿食不消、积年腰膝疼痛寒冷如冰石、脚气冲心、筋脉掣痛、眠寝不安等。'筋脉掣痛'言症非脉，全段属治法服饵，脉象要素为空。", []], "22256": ["治法", "原文为广济神明膏方，主诸风顽痹、筋脉不利及癣疮痒，未出脉象。其病机为风邪痹阻筋脉、肌肤失养，故以膏摩外治祛风通痹、润肤止痒。脉象未载，不能据方推脉，只就“顽痹”“筋脉不利”言风邪久稽、气血不畅之机。", []], "22257": ["治法", "钟乳酒疗虚损、通顺血脉、补益下气，原文未言脉。其病机属虚损不足、血脉不畅、气逆不降，故以酒剂温补通脉、降气益下。虽“通顺血脉”提示血行不畅，但无脉象可凭，不能补入弦涩等字，只明虚损兼血脉不利之治。", []], "22258": ["其他", "此段详述药饼制作、炮制、煮服及“除风”之用，未及脉象。主旨属制药用法，非脉诊病机。文中“除风”示所治与风邪有关，但无脉可辨，故脉象要素为空，不能以炮制文字推断浮弦等脉。", []], "22259": ["病机", "原文言饮酒房劳虚受热、积日不食、四体中虚热、饮酒不已入百脉、心气虚而错谬失常，未出脉象。其病机为酒热入脉、房劳伤虚、心气不足，虚热扰神致失常。虽“入百脉”关涉血脉，但无脉象写法，故不列脉，只述虚热扰心之机。", []], "22260": ["其他", "此段为面膏制作过程，先浸膏髓、易水、合煎、绞滓、研凝，述用法及成色，未言脉象。主旨属外治面膏调制，非脉诊病机。文中“去脉”指去除筋膜，非脉象，不能误作脉名，故脉象为空。", []], "22261": ["其他", "此段列蔓菁油、甘松香、零陵香等面膏药味及炮制，羊髓“以水浸去赤脉炼之”之“赤脉”指筋膜血络，非诊脉脉象。全段属外治方药组成，未涉病机脉候，故脉象要素为空，不作主病分析。", []], "22262": ["主病", "原文直言“脉极虚寒”，主发堕落。脉极虚为气血亏耗、脉道不充，寒则阳气衰微、不能温养毛发，故发失濡养而脱落。虚寒并见，说明病本在阳气精血俱损，非单纯外风，故以安发润方温养补虚为治。", ["虚", "寒"]], "22263": ["其他", "此段述猪膏去膜及赤脉、捣筛绞掠、贮器，先以桑灰汁洗发后摩药，属外治用法，未出脉象。“赤脉”指脂膜血络，非脉诊。主旨为制药摩发之操作，不能据以言病机脉候，故脉象为空。", []], "22264": ["妇人", "此段总论妇人之病与男子不同，因血气不调、胎妊生产崩伤之异，故“比之男子十倍难疗”。原文言妇人“众阴所集常与湿居”，阴气浮溢、瘀血停凝、中道断绝，致气脉损竭、五脏虚实交错，故妇人别立方；唯四时节气虚实冷热之病与丈夫同，怀胎挟病则避毒药。全段无脉象，旨在明妇人病机特点与治法大要。", []], "22265": ["妇人", "妊娠一月，足厥阴肝脉养胎，肝主筋及血，故不可针灸其经。原文谓“血行痞涩不为力事”，言此时血气运行尚涩滞，当寝必安静、无令恐畏，以护肝血、安胎元。此段论妊娠按月分经养胎及调护禁忌，无脉象可辨，属妇人胎养之法。", []], "22266": ["妇人", "妊娠二月，足少阳胆脉养胎，胆主精，原文谓“儿精成于胞里”，故不可针灸其经，当慎护惊动。此段承前论妊娠分经养胎，二月重在胆精成胎，惊动则伤精动胎，故以慎护为要。全段无脉象，属妇人胎养调护之论。", []], "22267": ["妇人", "妊娠三月，手心主心包脉养胎，心主神明，故不可针灸其经，戒“无悲哀无思虑惊动”。原文以情志扰动伤心包而碍胎养为病机，强调静心宁神以安胎。此段论妊娠三月养胎禁忌，无脉象，属妇人胎养之法。", []], "22268": ["妇人", "妊娠三月胎形已定，原文分寒热言症：有寒则大便青，有热则小便难、不赤即黄；又猝惊恐忧愁嗔恚或顿仆，动于经脉，致腹满绕脐苦痛、腰背痛、猝有所下，此皆动胎之候，故用雄鸡汤方。全段论妊娠三月因寒热情志跌仆伤动经脉之病机与证治，无脉象。", []], "22269": ["妇人", "妊娠四月，原文谓“始受水精以成血脉”，宜食稻粳羹鱼雁，以成血气、通耳目而行经络。此段论四月胎养重在成血脉，饮食调养以助血气流通、耳目聪明、经络畅行，属妇人逐月养胎食治之法，无脉象可辨。", []], "22270": ["妇人", "妊娠四月，手少阳三焦脉养胎，原文谓“儿六腑顺成”，故不可针灸其经，当静形体、和心志、节饮食。三焦内输，主通调水道、运行气血，形体静、心志和、饮食节则三焦安而胎元固。此段论四月养胎调护，无脉象，属妇人胎养之论。", []], "22271": ["妇人", "妊娠五月，足太阴脾脉养胎，原文谓“儿四肢成”，脾主四肢、主运化，故不可针灸其经，戒大饥甚饱、食干燥炙热及大劳倦，以护脾气、养胎元。此段论五月养胎重在健脾，饮食劳倦皆当有节，无脉象，属妇人逐月养胎调护之法。", []], "22272": ["妇人", "本段讲妊娠六月足阳明脉养胎，足阳明属胃主口目，六月儿口目皆成，故调五味、食甘美而戒大饱。原文未出脉名，主旨为妊娠按月养胎的调护禁忌，非论脉象主病，故脉象要素为空，归入妇人门。", []], "22273": ["妇人", "本段述妊娠七月手太阴脉养胎，手太阴属肺主皮毛，七月儿皮毛已成，故戒大言号哭、薄衣洗浴寒饮，以防伤肺。原文无脉名，属妊娠逐月养胎的调摄法，非脉诊内容，脉象要素从空，类别归妇人。", []], "22274": ["妇人", "本段言妊娠七月忽受惊恐摇动，腹痛猝有所下、手足厥冷，又见烦热腹满短气、颈项腰背强，原文以“脉若伤寒”状其外候，非具体脉名。病机为惊恐动胎、气血失和兼外邪，故以葱白汤通阳安胎，属妇人妊娠病证治。", []], "22275": ["妇人", "本段论妊娠八月手阳明脉养胎，手阳明属大肠主九窍，八月儿九窍皆成，故戒食燥物、辄失食、忍大起，以护大肠与九窍之成。原文未出脉名，为按月养胎的饮食起居禁忌，脉象要素为空，类别属妇人。", []], "22276": ["妇人", "本段述妊娠九月足少阴脉养胎，足少阴属肾主续缕，九月儿脉续缕皆成，故戒处湿冷、著炙衣，以护肾与胎脉。原文无脉名，属妊娠逐月养胎的调护内容，非脉象主病，脉象要素从空，归妇人门。", []], "22277": ["治法", "本段论始妒乳之治，急灸两手鱼际各二七壮以“断痈脉”，令小儿吮助使乳汁出如脓状，内服连翘汤、外涂小豆散。原文“断痈脉”指阻断痈肿发展之势，非脉象描述，故脉象要素为空，主旨为外灸内服外涂的治法。", []], "22278": ["病机", "本段论产后久不识人、时复发者，因产时血气暴虚，风邪乘虚行于脉中，去血多者尤易增此疾，故急与竹沥汁频服。原文“风行脉中”言风邪入血脉之病机，非脉象写法，脉象要素为空，主旨阐发产后血虚风中之理。", []], "22279": ["病机", "本段言产妇劳虚，或本虚寒，或产后血脉虚竭，致四肢羸弱、饮食减少、经水断绝、血脉不通，虚实交错。脉虚竭正示血气耗损、脉道不充，虚为本而瘀滞为标，故以泽兰补虚丸补虚行滞，属病机分析。", ["虚", "竭"]], "22280": ["病机", "原文言妇人营卫经络断绝不通，邪气往来入合子脏，或产后恶露未已即合阴阳，致“经脉挛急”。挛急指经脉拘急不畅，因邪入子脏、气血壅阻，冲任失和，故月水失常、生子之道受阻。此段以经脉挛急说明妇人胞门子户病机，非单论脉形。", ["急"]], "22281": ["病机", "燥瘕由月水未尽、虚惫劳作、恚怒致“经脉挛急，内结不舒”，气上达膈背，少腹壅急，月水与气俱不通。脉挛急反映气血郁结、经脉拘急，热与恶血相结而生瘕聚，故见胁腹痛、烦满、盗汗、月水闭塞等症。", ["急"]], "22282": ["病机", "脂瘕因月水新下或产后未复即合阴阳，致“络脉分，胞门伤，子户失禁，关节散”，百脉关枢四解，子精与血气相遇犯禁而成瘕。原文未出脉名，以络脉分、关节散说明血脉失敛、胞门损伤之病机，故见支满裹急痛、月水乍来乍去、大小便血等症。", []], "22283": ["病机", "狐瘕因月水数来而悲哀惊恐，逢暴风疾雨，湿倦少气，致“脉气绝，精神游亡”，邪入阴里不去，食人子脏。脉气绝指气血一时阻绝、神气浮游，非真脏死脉，故月水闭不通、少腹瘀滞、阴中肿、小便难，甚则终身无子。", ["绝"]], "22284": ["误治", "原文言新生儿慎不可逆灸，灸之忍痛则“动其五脉”，因惊而喜成痫。此段主旨为误治，逆灸扰动小儿五脏血脉，使气血逆乱、神气不宁，故发痫。田舍小儿任其自然反无夭折，正说明妄灸动脉之害。", []], "22285": ["病机", "儿初生骨肉未敛，肌肉犹血，若血阻败不成肌肉，则见面目鼻口悉黄、啼闭目、聚口撮面、口中干燥、四肢不能伸缩，皆“血脉不敛”所致。原文未出脉名，以血脉不敛说明新生儿营血凝涩、肌肉失养之病机，预后喜不育。", []], "22286": ["其他", "此段论新生儿衣着调护，不可过厚热，以免伤皮肤、害血脉、发杂疮而黄；暖衣太过则筋骨缓弱。宜时见风日，使“血凝气刚，肌肉牢密”，耐风寒而不病。原文未涉脉象，主旨属小儿调护法，故归其他。", []], "22287": ["小儿", "崔氏论小儿初受气至十月而生，生后六十日至三百六十日，目瞳子、百脉、尻骨、掌骨、髌骨、膝骨依次而成，此为定法。若发育不依期，则“必有不平之处”，提示脏腑血脉筋骨生长失常。原文未出脉名，主旨论小儿生长发育常度及异常。", []], "22288": ["小儿", "原文述小儿变蒸之候，谓“身热脉乱汗出”，脉乱乃气血荣养血脉、改易五脏之际，脉气未定之象，非病脉。变蒸为小儿生长发育过程，故见身热、汗出、目睛不明、微似欲惊、不乳哺、上唇白泡、耳冷尻冷等症，皆变蒸特有之诊，脉乱正应此生理变动。", ["乱"]], "22289": ["主病", "原文以鱼际脉色辨痫之寒热：“鱼际脉赤者热，脉青大者寒，青细者为平也。”脉青大主寒，因青为寒凝之色，大为邪盛之象，寒邪内侵，气血凝滞，故脉见青大。此与痫病之寒候相应，提示痫发有寒热之别，青大者当从寒治。", ["青", "大"]], "22290": ["治法", "原文列痫病初候多条，其中“耳后完骨上有青络盛卧不静是痫候脉青大刺之令血出”，脉青大主寒邪壅盛，青络盛亦寒凝血滞之征。故以刺法令血出，泄其寒邪壅滞。此条以脉青大为痫候之征，并示刺血治法，与诸痫候并列，强调早期干预。", ["青", "大"]], "22291": ["误治", "原文论痫病初候与剧候之辨，并诫“小儿惊啼，眠中四肢掣动，变蒸未解，慎不可针灸瓜之。动其百脉，仍因惊成痫也”。此段无脉象，主旨为误治警示：变蒸未解时妄施针灸瓜法，扰动百脉，反因惊成痫。强调须辨变蒸与痫候，不可妄攻。", []], "22292": ["治法", "原文述肾痫之病：“面黑，目正直视不摇如尸状”，并载灸法“灸肘下动脉各二壮”。动脉为脉气搏动之处，灸之可温通肾经气血。肾痫面黑、直视如尸，乃肾经气逆、阴阳不相接续之候，灸动脉以通阳救逆，属痫病灸治之一法。", ["动"]], "22293": ["治法", "原文详列痫病灸法部位，其中“灸客主人穴在眉后际动脉是也”，动脉为经气所过之处，灸之可通调经脉。此段主旨为痫病灸治取穴，强调随手动者、动脉应手处为要穴，以灸法通阳止痫，兼以针刺耳后青脉出血，属外治之法。", ["动"]], "22294": ["其他", "原文论病家杂疗无次序、后师不察前证虚实而妄疗之弊，强调“要应精问察之”，须续前师之法以疗，否则“不依次前师疗则毙也”。此段无脉象，主旨为诊疗次序与接续治疗之要，属医论范畴，警示不究前证、更医乱治之害。", []], "22295": ["小儿", "原文载丸药服法及《神农本草经》小儿惊痫百二十种之说，谓“初出胎，血脉不敛，五脏未成，稍将养失宜，即为病也”，又言变蒸之后余证并宽，唯中风最暴卒。此段无脉象，主论小儿惊痫之因与调养，强调初生血脉未敛、五脏未成，将养失宜则病。", []], "22296": ["小儿", "此段论小儿养惊与灸惊脉的时机，非论脉象。原文强调小儿微惊可长血脉，但大惊则需灸惊脉；五六十日灸者惊复重甚，百日后灸乃善。说明小儿惊气与血脉生长相关，灸治须待气血渐充，过早施灸反致惊重，体现小儿调护重时机、慎妄攻的思想。", []], "22297": ["主病", "原文言客忤之病，症见吐下青黄白色、水谷解离、腹痛夭纠、面色变易，其候似痫但眼不上插，脉急数。急数主热盛邪实，客忤之气内扰，脾胃升降失司故吐下，气血壅迫故腹痛面变。脉急数正是邪热内盛之征，故宜龙胆汤下之，以泻实热。", ["急", "数"]], "22298": ["治法", "此段述龙胆汤主治婴儿出腹血脉盛实热、温壮惊掣、发热大吐、中食不消、变蒸不解及中客忤魃气诸惊痫。方以龙胆为主，随儿日龄加人参当归，示小儿用药须量年龄增减。全段重在治法与方剂运用，非论脉象，体现小儿实热惊痫以清热镇惊为治。", []], "22299": ["主病", "原文疗少小中风，脉浮发热自汗出，项强鼻鸣干呕。浮脉主表，风邪袭表故脉浮；卫气抗邪则发热，表虚不固则自汗；风邪上扰，经气不利故项强鼻鸣；干呕为风邪犯胃。此脉浮与发热自汗项强鼻鸣并见，正是小儿中风表虚之候，脉症相应。", ["浮"]], "22300": ["病机", "此段论服乳石之宜忌，言年少筋力满盛、血气自强，服石得力速而无病患；年岁迟暮、气候衰竭、食饮失宜，则石气胜人而发动。脉微有滞处，微主气力衰，滞示石气壅遏，正说明气血衰而石气强、壅滞为患之病机，与文中气力衰石气强发动相合。", ["微"]], "22301": ["其他", "此段详述白石英的炮制与服食方法，包括敲碎、砂盘挼洗、蒿叶熟挼、晒干、盛袋含咽等步骤，并言服后饮食无忌。全段属服石操作与禁忌的记载，未涉及脉象与病机判断，故归其他，体现古代服石养生之具体法度。", []], "22302": ["其他", "薛侍郎言服石后一二百日内须吃精细饮食羹粥酒等，使血脉通利。此段讲服石后的饮食调护，以羹粥酒通利血脉，防止石气壅滞。虽言血脉通利，但未及脉象，主旨属服石调养之法，故归其他，反映古人服石后重视饮食以助血脉流通。", []], "22303": ["其他", "此段述鲜鲫鱼鲙的制法，剥鳞去肠血，新布净拭令血脉断，名曰上鲙，佐蒜齑瓜姜等酱，言益人下食并疗气痢赤痢。全段为食疗方与制作法，未论脉象，主旨属饮食疗病，故归其他，体现古代以鲙鱼佐蒜齑调养下食、疗痢的食疗经验。", []], "22304": ["病机", "原文述饮热歇后石势虚损，饮食入口自觉诸脉中如冷水入者，乃酒石俱退、经络空虚所致。脉象未明，然‘诸脉中如冷水入’喻脉络空虚失温，故宜积日调冷食、服猪蹄羹以通养诸脉，使经络渐充自瘥。", []], "22305": ["病机", "鸡心酸枣汤证因饮后阳多、肾虚发热，积日不食致胃中虚热，饮食不已则气入百脉，心脏虚甚令人失常。原文未出脉象，然‘气入百脉’‘心脏虚甚’点明虚热扰脉、心失所养之机，故以酸枣汤养心清热。", []], "22306": ["病机", "寒栗头掉不自支持，因食少药气溢于肌肤，五脏失守而百脉摇动，与正气相竞。脉摇动即脉动不宁，主正虚邪扰、脏气不守。故宜强饮热酒和脉、强食冷食定脏、强行调关节、强洗宣壅滞。", ["动"]], "22307": ["预后", "脉洪实主癖，细数弦𫘝主热多，断绝不足似死脉主急痛，皆寒食药热率常如此，自无所苦非死。然大便稠数为久失节度将死之候，难疗，可与大黄黄芩栀子芒硝汤下之，傥十有一生，不可不利致死。", ["洪", "实", "细", "数"]], "22308": ["死脉", "人已困而脉不绝，非生气也，乃药气盛行于百脉，真气已尽而药气自行故不绝。死后体温如生人肌、腹中雷鸣、颜色不变，一两宿乃作死人。此脉绝而药气独存，属死候，非真脉也。", []], "22309": ["病机", "周体患肿不能回转，因久坐不行又不饮酒，药气滞在皮肤之内，血脉不通故也。原文未出脉象，然‘血脉不通’点明气滞血壅之机，故宜饮酒、冷水洗、自劳，或遣人扶持强行使肢节调畅。", []], "22310": ["病机", "肌肤坚如石不可屈伸，因热食温卧作癖，五脏隔闭，血脉不通故也。原文未出脉象，然‘五脏隔闭’‘血脉不通’明示癖阻气机、血行壅塞，故急服三黄汤下之，食冷食、饮热酒、自劳即瘥。", []], "22311": ["病机", "痈疽脉皆有状，浮为阳虚，滑为阳实，数为阳燥，涩为阴寒，弱为阴虚，沉为阴坚，此三阳三阴之脉。原文以脉之浮滑数涩弱沉分阴阳虚实，说明痈疽由腑脏拥热、血脉不流、毒气凑于俞穴而发。", ["浮", "滑", "数", "涩"]], "22312": ["病机", "原文以乳石之性立论，谓其“在阳即能发其炎”，阳盛则“炎上腑之受邪”，表热气隔而“至阴之伏”，故脉见“阳浮而数，阴伏而沉”。浮数为阳热亢于表，沉为阴伏于里，一浮一沉示表里寒热错杂、阳亢阴伏之病机，非单纯外感。文中“热不已者”点明热势持续，与浮数相应；治当理经通泰，不可妄灸抑石性。", ["浮", "数", "沉"]], "22313": ["病机", "脉急数为热盛邪实之象。石发者，服石后热毒内发，热盛充实，故脉来急而数；急主邪势急迫，数主热，热壅三焦则四体烦满，热灼津液则大小便赤涩。此脉此症相应，皆属实热内盛，故用升麻汤清解热毒。脉不急不数，则热未盛实，非此方所宜。", ["急", "数"]], "22314": ["病机", "本段未出脉名，而论服石之人阴虚摄温过度，致“经脉凑溢”，即脉道充盈急迫之象。其病机为客主两阳并蒸肺肝，阳热耗津故渴；肺金畏火，告子肾水，水虽暂寒而潜流于下，反成“滂沱”水气，渴未除更增肾冷。脉之凑溢正反映阳热壅盛、经脉气血奔迫，主上焦燥热、下焦寒水之错杂证候。", []], "22315": ["主病", "原文仅言“主眼生赤脉，息内碜痛不开”，未出具体脉名，故脉象要素为空。此段主旨为眼目赤脉、碜涩疼痛、胞睑难开之症，属目病主病条文；其病机当为邪热郁滞眼络、气血壅阻，然原文未及脉形，不可臆补脉象，只就所述症候归入主病。", []], "22316": ["其他", "本段为食疗方，述取鲫鱼治如食法、断血脉、切作鲙、以蒜虀食之、夜以白粥量事吃之，属饮食调养之法，非论脉象。原文未出现任何脉象描述，故脉象要素为空；主旨为食疗服食法度，与主病、病机、平脉、死脉等脉学范畴无涉，归入其他。", []], "22317": ["病机", "脉象所主病机为脾虚失藏、阳气腾越而三阴坚塞。原文“脾虚不能含藏，则地气渐泄，阳上腾则三阴坚塞，足便冷也”，指出脾为中州、含藏阳气，虚则阳气不能温煦三阴，故足冷。若兼“踵缓急不仁”，则因“肾肝之气不足，使少阴厥阴之阙”，足失载运跷捷之力，是“阴搏其阳”，由“脏虚所生，阳气伤狂，而阴不能独理”。若见“发热口噤，及腋下热不可近”，则为“三阳伤盛之所致”，属阳分热证，与阴搏阳搏之脏虚足冷相应而病位有别。", []], "22318": ["其他", "本段未言具体脉象，旨在强调明堂甲乙之经与图不可偏废。原文谓“有经而无图，则不能明脉俞之会合，有图而无经，则不能论百疾之要”，说明脉俞会合须借图象方明，非论某脉主某病。其核心在医经传承与孔穴图谱并重，属医籍整理之论，故不归主病、病机诸类。", []], "22319": ["病机", "本段未出脉名，专论邪气由皮毛、孙络、经脉内连五脏的传变次第。原文强调“留而不去”致“闭塞不通”，邪不得入经而“溢于大络，而生奇病”，说明病机为邪客浅表、络脉壅滞、气血不通。此非脉象所主，故脉象要素为空；主旨属病机传变，与主病、兼症无直接脉症对应。", []], "22320": ["病机", "原文言五脏六腑精灵之气“顺脉而出，附经而入”，环转无端；若气行“越其数”即偏离常度，则“伤脉而损经”，脉经受损而变为异病。此段无具体脉名，主旨说明脉为脏腑精气出入之道路，气机失序越常则损脉伤经，属脉病机总论，非主某脉某病。", []], "22321": ["治法", "原文分手足内外脉应五脏六腑，强调灸壮须“依经数”，手足外阳脉“不得过于二壮”，腹中水谷风寒所结“灸之务欲多”，脊为太阳所合亦宜多。若顿多则“血脉绝于火下”，火气随脉远去。全段论灸法壮数及补泻，非诊脉主病，故脉象要素为空。", []], "22322": ["治法", "原文论灸火取材，忌松柏桑枣竹柿枫榆八木，谓其“害人肌肉筋脉骨髓”，宜阳燧火珠映日取火，或钻槐木、䃈石蒸艾。又言灸后须令痛根疮发，“得发则病愈”。全段讲灸法用火与发灸疮以去疾，涉及筋脉骨髓受火之害，非脉象主病，故无脉象要素。", []], "22323": ["其他", "此段罗列头维、下关、承光、脑户、气冲、脊中、伏兔、乳中、地五会、风府等穴名，并注“女子”“甲乙经”等，属针灸腧穴目录，未言脉象、病机或主病。既非平脉死脉，亦非治法论述，仅穴名汇编，故归其他，脉象要素为空。", []], "22324": ["治法", "黄帝问大风大雨大阴大寒可否施灸，岐伯答：大风灸则“阴阳交错”，大雨灸则“诸经络脉不行”，大阴灸“令人气逆”，大寒灸“血脉蓄滞”，此时施灸“更动其病，令人短寿”。全段论灸法禁忌与时令，强调外邪盛时灸之反致血脉滞逆，非脉诊主病。", []], "22325": ["病机", "原文仅列“筋血（脉）肉皮毛（气）骨（精）”，以筋配血、脉、肉、皮毛配气、骨配精，示五体与血气精相合之层次。未出现具体脉象描述，亦未言主病，主旨在于说明形体与气血精的对应关系，属病机框架性文字，故脉象要素为空。", []], "22326": ["其他", "原文仅“五脏脉”三字，为篇目或标题性文字，未展开任何脉象形态、主病或病机论述。既无浮沉迟数等脉象要素可取，也无法据以分析所主病机，仅标示讨论范围，故归其他，脉象要素为空。", []], "22327": ["其他", "原文言肺脉“出于少商”，少商在手大指端内侧去爪甲如韭叶，为手太阴脉所出，并注“冬月宜灸”。此段讲肺经井穴少商的位置与灸宜，属经络腧穴内容，未描述脉象形态及主病，故脉象要素为空，归其他。", []], "22328": ["病机", "原文言鱼际为手太阴脉所流，属荣，其位在散脉中，故取散脉。散者脉气涣散流布，非病脉之散，乃言脉气于此散布流注。鱼际属火，夏月宜灸，示手太阴经气由井荥输经合流注，此段重在明经气流注与四时灸宜，非主病之脉。", ["散"]], "22329": ["病机", "原文未出脉名，仅言太渊为手太阴脉所注，属输，位在掌后陷中，夏月宜灸。此段承上文述经气流注至太渊，以输穴应土，示脉气汇聚灌注之处。无脉象描述，故脉素从缺，主旨为经气流注与灸法宜忌，非论病脉。", []], "22330": ["病机", "原文未出脉名，言行于经渠，经渠属金为经，在寸口陷中，特标禁灸。此段述手太阴脉气流经之处，以经穴应金，示脉气运行之道。因无脉象描写，脉素从缺；主旨为经气流注及禁灸之戒，属针灸宜忌，非主病脉。", []], "22331": ["病机", "原文言尺泽为手太阴脉所入，属合，位在肘中约纹上动脉处，秋月宜灸。取动脉者，以该处脉动可察，非病脉之动。此段述脉气入合于尺泽，应水应秋，示经气归藏之所，重在流注与灸宜，非主病之脉。", ["动"]], "22332": ["兼症", "原文述少商穴主治，载腮颔肿大、喉中闭塞、水粒不下、疟寒热、烦心善哕、咳喘上气、臂痛呕吐等症，末言此脉脾肺之候不宜灸。无脉象描写，脉素从缺；所列症候多属肺经热壅及脾肺同病，故归兼症，示穴主诸症而非脉诊病机。", []], "22333": ["兼症", "原文言穴在手大指本节后内侧散脉中，取散脉以明其位。所列主症繁多，如虚极洒洒毛起恶风寒、舌上黄身热、咳喘不得息、唾血时寒时热、肺心痛等，末言皆虚也。此段以穴主诸症为主，散脉仅指穴位所在，非病脉，故归兼症。", ["散"]], "22334": ["兼症", "原文言穴在肘中约纹上动脉，取动脉以定穴处。所列主症有阴痹上气、舌干胁痛、咳逆上气、腹胀喘振栗、疝瘕积与阴相引痛、喉痹哽塞，并分热实肩背热痛四肢暴肿、虚则臂背寒短气。动脉指穴处脉动，非病脉，主旨为穴主虚实诸症，故归兼症。", ["动"]], "22335": ["兼症", "原文言穴在天府下五寸动脉处，为手太阴之别，灸五壮，主心痛咳干呕烦满。取动脉以明穴位所在，非论病脉。此段以络穴主治心痛、咳、干呕、烦满等症为主，症属肺经及心胸气机失调，故归兼症，动脉仅为定位之辞。", ["动"]], "22336": ["主病", "原文点明臂臑内廉为“手太阴脉气所发”，其处有动脉，禁灸，灸则“使人逆气”。脉动见于该处，说明手太阴肺气所聚、经气搏动于局部；其所主咳上气喘不得息、暴痹内逆、肝肺相搏口鼻出血、身胀不得卧等，皆肺气上逆、肝肺气争之候，风汗身肿喘喝、恍惚善忘嗜卧亦属肺气不利、清阳不升。", ["动"]], "22337": ["其他", "本段为手阳明大肠经井穴定位，言“手大指次指内侧去爪角如韭叶”，为“手阳明脉之所出为井”，并载冬三月宜灸。原文未及脉象形态与主病，仅述经气流注之始及施灸时令，故不涉病机分析，属针灸腧穴内容。", []], "22338": ["其他", "本段述手阳明大肠经荥穴间谷位置，在“手大指次指本节前内侧陷者中”，为“手阳明脉之所留也为荥”，春三月宜灸。全段只言经气留止之处与灸法时宜，未描述脉象，也未论主病，故不能据以推断病机，归入其他。", []], "22339": ["其他", "本段记手阳明大肠经输穴定位，在“手大指本节后内侧陷者中”，称“手阳明脉之所注也为输”，夏三月宜灸。原文仅述经气所注与施灸季节，无脉象描述及病候，故不涉脉诊病机，属腧穴灸法内容。", []], "22340": ["其他", "本段言手阳明大肠经原穴虎口位置，在“手大指岐骨间”，为“手阳明脉之所过也为原”。原文只载经脉所过之处，未提脉象形态、主病或症候，无从分析病机，故列其他。", []], "22341": ["其他", "本段述手阳明大肠经经穴中魁，在“腕中上侧两筋间陷者中”，为“手阳明脉之所出也为经”。全段仅明经穴定位与经气所行，未及脉象与病候，不能推求病机，归入其他。", []], "22342": ["其他", "本段记手阳明大肠经合穴位置，在“肘外辅骨屈肘曲骨之中”，为“手阳明脉之所入也为合”，秋三月宜灸。原文只述经气所入与灸法时令，无脉象描述及主病文字，故不涉病机，属腧穴内容。", []], "22343": ["主病", "原文谓穴在“肘上三寸行向里大脉中央”，此“大脉”指局部粗大之脉，灸之可主风劳惊恐、久吐血、肘不欲举、风痫嗜卧、四肢不欲动摇、身黄寒热、颈疬咳嗽、少气痎疟、心下胀满痛上气等。大脉见于肘上，说明气血壅盛于经隧，风劳痰瘀互结，故见惊痫、咳逆、胀满、寒热诸候。", ["大"]], "22344": ["其他", "此段为肩髃穴定位与主治，非脉诊内容。原文述其位于肩端两骨间宛宛中，举臂取之，为手阳明与跷脉之会，灸三壮，主肩中热、指臂痛。病机为手阳明经气壅滞、跷脉失和，故肩臂局部热痛，与脉象无关，故脉象要素为空。", []], "22345": ["其他", "此段述肩髃穴（肩尖端上行两叉骨陷中）灸三壮，主肩膊痛、胸中有瘀血、肩臂不得屈伸而痛。病机属手阳明经气血瘀阻，瘀血内停胸中，经气不通则肩臂痛而屈伸不利。原文未及脉象，纯为穴位主治，故脉象要素为空。", []], "22346": ["其他", "此段述水穴（人迎后一寸五分）为手阳明脉气所发，灸三壮，主咳逆上气、咽喉鸣喝、喘息暴喑、气哽。病机为手阳明经气上逆，痰气交阻于咽喉，肺失宣降，故咳喘、喉鸣、暴喑。原文为穴位主治，未涉脉象，脉象要素为空。", []], "22347": ["其他", "此段述颈缺盆直扶突气舍后一寸半穴，为手阳明脉气所发，灸三壮，主暴喑气哽、喉痹咽肿、不得息、饮食不下。病机为阳明经气郁滞，热结咽喉，气机闭塞，故咽肿喉痹、暴喑、饮食难下。原文为穴位主治，未言脉象，脉象要素为空。", []], "22348": ["其他", "此段述鼻孔下侠水沟傍五分穴，为手阳明脉气所发，主鼻窒、口僻、清涕不止、鼽衄有痈、口噤不开。病机为阳明经气不利，风寒或热邪客于鼻口，故鼻塞流涕、口眼㖞僻、口噤。原文为穴位主治，未及脉象，脉象要素为空。", []], "22349": ["其他", "此段述人中穴为督脉与手阳明之会，灸三壮，主寒热头痛、癫疾互引、水肿、振寒、鼻鼽不能息、不知香臭、衄不止、口噤㖞僻等。原文特言「人中尽满唇反者死」，为危候预后。病机属督脉与阳明经气逆乱，涉及神志、水气、鼻口诸症。原文为穴位主治，未涉脉象，脉象要素为空。", []], "22350": ["其他", "此段述唇上端穴为手阳明脉气所发，灸三壮，主寒热鼓颔、口噤、癫疾吐沫、寒热痓互引、唇吻强、上齿龋、涩渴嗜饮、目瞑身汗出、衄血不止。病机为阳明经热与风痰交争，故寒热、口噤、痓病、齿龋、衄血。原文为穴位主治，未言脉象，脉象要素为空。", []], "22351": ["其他", "此段述足大趾端去爪甲如韭叶及三毛中穴，为足厥阴脉之所出，属井穴，冬三月宜灸之。原文仅言穴位属性与灸法时机，未载主治症候，亦未涉脉象。病机为足厥阴经气所出之处，冬月宜灸以助经气，属针灸取穴内容，故脉象要素为空。", []], "22352": ["其他", "原文定位“足大趾间动脉应手陷者中”，为足厥阴肝经荣穴所在，春三月宜灸。此处“动脉”仅指体表可触之搏动处，非病脉；所述内容属腧穴定位与灸法，未言主病，故病机分析从略。", ["动"]], "22353": ["其他", "原文述足厥阴肝经输穴位置“足大趾本节后二寸或一寸半陷者中”，夏三月宜灸。未提脉象，亦未言主病，属腧穴定位与灸法内容，无病机可析。", []], "22354": ["其他", "原文述足厥阴肝经经穴“足内踝前一寸”取穴法，仰足取之陷者中，伸足乃得。未涉及脉象与主病，属腧穴定位内容，无病机可析。", []], "22355": ["其他", "原文述足厥阴肝经合穴“膝内辅骨下大筋上小筋下陷者中”，屈膝而得，秋三月宜灸。未言脉象与主病，属腧穴定位及灸法，无病机可析。", []], "22356": ["主病", "原文列大敦穴主病，涵盖卒心痛汗出、寒疝、遗溺、小儿痫瘛等，末言“凡厥死不知人脉动如故痓”。厥死不知人而脉动如故，说明脉气未绝，与痓病相关；此“动脉”指脉仍搏动，非病脉要素，故主病机为厥证脉未绝。", ["动"]], "22357": ["主病", "原文述足大趾间动脉处（肝经荣穴）主病，包括咳逆上气、疝、癃、心痛、月事不利等。此处“动脉”为取穴标志，非病脉；所列症候多属肝经气逆、寒凝、热郁，病机为肝脉失调、经气逆乱。", ["动"]], "22358": ["主病", "原文述犊鼻下二寸陷者中（足厥阴脉气所发）灸五壮，主“膝内廉痛引膑不可屈伸，连腹引喉咽痛”。未提脉象，病机为肝经经脉痹阻，气血不通，故痛引膝膑、腹及咽喉。", []], "22359": ["主病", "原文述阴廉下二寸、去气冲三寸“阴股中动脉”处灸二壮，主“少腹中满热闭不得溺”。此处“动脉”为体表搏动处，非病脉；病机为肝经热郁、气化不利，故少腹满而闭癃。", ["动"]], "22360": ["妇人", "原文指出羊矢下、去气冲二寸处有动脉，主妇人绝产；若未曾产者灸三壮。此处以“动脉”为定位标志，而非诊脉所得之动脉脉象，说明该处脉动与妇人胞宫、冲任相关，脉动异常可反映绝产之病机，属妇人病范畴。", ["动"]], "22361": ["其他", "原文述足小趾次趾端为足少阳脉所出之井穴，冬三月宜灸。此段未涉及具体脉象描述，仅言经脉所出部位与灸法时令，属经络腧穴内容，非脉诊病机分析，故脉象要素为空。", []], "22362": ["其他", "原文述足小趾次趾岐骨间本节前陷中为足少阳脉所留之荥穴，春三月宜灸。全段为经脉腧穴定位与灸法时令，未出现脉象描述，不涉及脉诊病机，故脉象要素为空。", []], "22363": ["其他", "原文述足小趾次趾间本节后陷中，去侠谿一寸半，为足少阳脉所注之输穴，夏三月宜灸。内容属经络腧穴与灸法时令，无脉象描述，不涉及脉诊病机，故脉象要素为空。", []], "22364": ["其他", "原文述足外廉踝下前陷中，去临泣三寸，为足少阳脉所过之原穴。全段为经脉腧穴定位，未言脉象，不涉及脉诊病机分析，故脉象要素为空。", []], "22365": ["其他", "原文述足外踝上四寸辅骨前绝骨端，去丘墟七寸，为足少阳脉所行之经穴。内容属经络腧穴定位，无脉象描述，不涉及脉诊病机，故脉象要素为空。", []], "22366": ["其他", "原文述膝下一寸外廉陷中为足少阳脉所入之合穴，秋三月宜灸。全段为经脉腧穴定位与灸法时令，未出现脉象描述，不涉及脉诊病机，故脉象要素为空。", []], "22367": ["主病", "原文言足三阳大络在外踝上三寸动者中，按之阳明脉绝乃取之，灸五壮，主肠满、胃中有热、不嗜食、小儿腹满不能食饮。此处“动者”指络脉搏动处，按之阳明脉绝说明阳明经气阻绝，故主胃肠胀满、胃热不嗜食等症，属主病范畴。", ["动"]], "22368": ["主病", "本段为足少阳脉气所发腧穴的主治条文，未出脉象。所列太息、口苦、咽中介介、数唾、胁下支满、呕吐逆，皆少阳胆腑气郁化火、循经上逆之候；髌痹引膝股痛不仁筋急，为少阳经气痹阻于下肢；心澹澹如人将捕之，是胆虚气怯、神魂不宁。诸症合观，主胆胀及少阳经气郁逆之病机。", []], "22369": ["主病", "本段未言脉，专述足少阳脉气所发穴主「寒气在分肉间，痛攻上下，筋痹不仁」。寒邪客于分肉之间，少阳经气不得宣通，故痛势上下攻走；营卫涩滞，筋脉失养，故痹而不仁。其病机为寒凝分肉、少阳经气痹阻，属筋痹范畴，与脉象无涉。", []], "22370": ["主病", "本段无脉象，述足少阳脉气所发穴主「枢中痛不可举，腰胁相引急痛，痹筋瘛，胫痛不可屈伸，痹不仁」。髀枢为少阳经气转枢之处，经气痹阻则枢痛不可举；腰胁相引、筋瘛胫痛，是少阳经筋失养、拘急不仁。病机属少阳经气痹阻、筋脉挛急，主髀枢痹痛之证。", []], "22371": ["主病", "本段未出脉，述耳后足少阳脉气所发穴主「身热头重，胁痛不可反侧，小儿痫，喘不得息，耳鸣」。身热头重、胁痛不可反侧，为少阳经气壅遏、热郁于经；小儿痫、喘不得息，是少阳火逆、痰热扰神犯肺；耳鸣则少阳经气上壅于耳。病机主少阳经热壅逆、痰火内扰。", []], "22372": ["主病", "本段无脉象，述曲角颞颥上廉足少阳脉气所发穴主「热病头痛，引目外眦而急，烦满汗不出，引颔齿，面赤皮痛」。少阳经脉起于目外眦、下颔颊，热邪郁于少阳经，循经上攻，故头痛引目眦急、引颔齿而面赤皮痛；热郁气壅，故烦满汗不出。病机为少阳经热郁蒸、循经上逆。", []], "22373": ["主病", "本段未言脉，述眉后足少阳脉气所发穴「不可灸」，误灸则目小及盲；主眩头痛互引、目中赤、脐风目上插、痓反目、憎风、癫疾狂、烦满。少阳经气通于目，火攻伤络则目损；风热痰火循经上扰，则眩痛目赤、痓反目、癫狂烦满。病机为少阳风热痰火逆乱、上扰神明目窍，兼示误灸之害。", []], "22374": ["病机", "本段未出脉，述脾之大络「布胸胁中」，主「腹有大气不得息，息即胸胁中痛，实则身尽寒，虚则百节皆纵」。大络布于胸胁，络气壅滞则大气不得息而胸胁痛；实则经气闭阻、阳不外达故身尽寒，虚则络脉失养、百节弛纵。病机为脾之大络气血壅滞或空虚，主大络虚实之证。", []], "22375": ["主病", "本段无脉象，述腋下足少阳脉气所发穴主「胸中暴满，不得卧，喘息」。少阳经气壅塞于胸胁，气机暴阻，故胸中暴满；气逆迫肺，则喘息不得卧。病机为少阳经气暴郁、气逆犯肺，属胸满喘逆之实证，与脉象描述无关。", []], "22376": ["其他", "此段为腧穴定位与主治条文，言天会穴为手心主、足少阳脉之会，灸三壮，主寒热、胸满、颈痛、四肢不举、腋下肿、上气、胸中有声、喉中鸣。所主诸症系手足少阳与心包经气失调、水气上逆所致，原文未及脉象，故不能以脉论病机，只属针灸主治范围。", []], "22377": ["其他", "此段仅标「带脉」二字，为奇经八脉之一，非脉象描述，亦无病机症候可析。带脉环腰约束诸经，原文过简，未言其病候与诊法，故不能推断所主病机，只可视为经脉名义条目，列于其他类。", []], "22378": ["其他", "此段述带脉穴定位与灸法，主男子阴疝、两丸上下入腹痛，妇人下赤白、里急、瘛疭。诸症属带脉失约、下焦寒湿与肝风内动，原文未载脉象，故不能以脉推病机，只就穴位主治言其病候所属。", []], "22379": ["其他", "此段述外枢穴为足少阳、带脉之会，灸三壮，主咳逆不止、三焦有水气、不能食。病机在少阳枢机不利、三焦水道壅滞，水气上逆则咳逆，中焦不运则不能食。原文未出脉象，故不能以脉论，只属腧穴主治。", []], "22380": ["其他", "此段述足太阴脉井穴定位，在足大趾端内侧去爪甲角如韭叶，为足太阴脉所出，冬三月宜灸。原文只言经脉所出与灸时，未及脉象与病候，故不能推断病机，只属经络腧穴内容，列于其他。", []], "22381": ["其他", "此段述足太阴脉荥穴定位，在足大趾本节后陷者中，为足太阴脉所留，春三月宜灸。原文仅言荥穴位置与施灸季节，未载脉象症候，故无从论其病机，只属经络腧穴与灸法宜忌。", []], "22382": ["其他", "此段述足太阴脉输穴定位，在足内侧核骨下陷者中，为足太阴脉所注，夏三月宜灸。原文只明输穴部位与灸时，未言脉象及主病，故不能以脉析机，只属经络腧穴内容。", []], "22383": ["其他", "此段述足太阴脉经穴定位，在足内踝上微前陷者中，为足太阴脉所行。原文仅言经穴部位与经脉所行，未及脉象、症候与灸法，故不能推断所主病机，只属经络腧穴条目。", []], "22384": ["其他", "本段为腧穴定位与灸法条文，述足太阴脉所入为合，秋三月宜灸，未及脉象与病机。原文仅言\"伸足乃得之\"\"足太阴脉之所入\"，属经脉流注与灸治宜忌，非论脉主病，故无从据脉析病机，只可视为针灸取穴资料。", []], "22385": ["兼症", "原文列腹中寒气、气喘、衄血、烦心、腹胀、呕吐、尸厥不知人等症，末言\"脉动如故\"。脉动如故指脉仍搏动未绝，说明尸厥虽昏不知人而脉气未败，故主病在气机暴逆、阳气闭阻，非脉绝之死候；饮渴、身体痛、多唾则示寒饮内停、气不化津之兼症。", ["动"]], "22386": ["妇人", "本段言足太阴脉气所发穴灸五壮，主妇人漏下恶血、月闭不通、逆气腹胀。未出脉象，然病机在脾统血失职、冲任失调：漏下恶血与月闭并见，属瘀阻胞宫、脾气不运，逆气腹胀为脾虚气滞之应，故列妇人门。", []], "22387": ["主病", "原文\"动应手\"指该处动脉搏动可触，为足太阴脉气所发。主淋、遗溺、鼠鼷痛、小便难，病机在脾失运化、水湿下注膀胱，气化不利。动脉应手说明经气所聚之处，灸之可通调水道，故所主皆水液代谢失常之症。", ["动"]], "22388": ["主病", "原文\"约中动脉\"\"足太阴阴维之会\"，动脉应手为经气交会之征。主寒气腹满、癃、淫泺、身热、腹中积痛、阴疝、乳难、子上冲心，病机为寒凝太阴、阴维失维，气机壅滞于腹，故见腹满积痛、癃闭与冲逆诸症。", ["动"]], "22389": ["病机", "原文\"动脉应手\"示经气所发，末言\"脉代不至寸口，四逆脉鼓不通\"。脉代不至寸口为脉气断续、阳衰不达四末，故见四逆；脉鼓不通为邪闭脉道、气血壅遏。合喉痹、暴逆、咳喘不得卧、疝积上冲心等症，病机属肺气壅闭、阳气不布、脉道阻绝。", ["动", "代", "鼓"]], "22390": ["主病", "原文\"动脉应手\"为手太阴之会，经气所聚。主肺系急、胸中痛、恶清、胸满、呕逆、多浊唾、不得息、肩背风汗出、肺胀等，病机在肺气不利、寒饮停聚、卫表不固。动脉应手说明病位在肺之募俞，灸之可宣肺降逆、通调气机。", ["动"]], "22391": ["主病", "本段为腧穴定位，言足太阴脉气所发，灸五壮，主胸胁支满、不得俯仰、饮食不下、咳唾陈脓。未出脉象，病机在脾失健运、痰浊壅肺：胸胁支满、饮食不下属脾不运化，咳唾陈脓为痰热久蕴于肺，脾肺同病，故取太阴经穴灸治。", []], "22392": ["其他", "本段为腧穴定位与主治条文，未载脉象。所述“胸胁支满却引背痛、卧不得转侧”属足太阴脉气所发之穴主治，病机为脾脉失和、经气壅滞于胸胁，故取该穴灸五壮以通经调气，非凭脉断病。", []], "22393": ["其他", "本段记腧穴部位及灸法主治，无脉象可辨。“胸中满痛、乳肿贲膺、咳逆上气、喉鸣有声”系足太阴经气不利、痰气上逆所致，取该穴灸之以宣通脾经气机，属针灸主治范畴，不涉脉诊。", []], "22394": ["其他", "本段述腧穴定位与主治，未出脉象。“胸胁支满、膈间雷鸣滀漉常有小声”为脾经气滞、水饮内停之候，取足太阴脉气所发之穴灸五壮，以运脾化饮、通调胸膈，属针灸治法条文。", []], "22395": ["其他", "本段言足阳明井穴部位及灸时，未载脉象。“冬三月宜灸之”体现因时施灸之法，井穴主心下满，与脉诊病机无直接关联，故不作脉象分析。", []], "22396": ["其他", "本段记足阳明荥穴定位及“春三月宜灸之”，无脉象描述。荥穴主身热，春季灸之顺应生发之气，属针灸取穴与时令宜忌内容，不涉及脉象主病。", []], "22397": ["其他", "本段述足阳明输穴部位及“夏三月宜灸之”，未识别脉名。输穴主体重节痛，夏季灸之应长养之气，为针灸按时取穴之法，无脉象可析，故列其他。", []], "22398": ["其他", "原文仅以“骨间动脉”描述冲阳穴所在，此“动脉”指体表可触之搏动处，非脉诊之动脉脉象。全段主旨为足阳明原穴定位，虽见“动脉”二字，实属解剖标志，不构成病机判断，故归其他。", ["动"]], "22399": ["其他", "本段记足阳明经穴定位，未载脉象。“腕上陷者中”为取穴标志，“阳明脉之所行也为经”说明经穴属性，全段属针灸腧穴内容，无脉象主病可言，故列其他。", []], "22400": ["其他", "本段为足阳明胃经合穴定位及灸法宜忌，未载脉象。原文'在膝下三寸胻外廉足阳明脉之所入也为合秋三月宜灸之'，说明合穴属土应秋，秋时阳气收敛，宜灸以温通阳明经气。无脉象可辨，故不涉病机，仅属针灸取穴与施灸时令之论。", []], "22401": ["兼症", "原文'脉动如故'指尸厥口噤气绝而脉仍搏动，说明形无知而脉未绝，气血尚存，非真死候。所列疟、腹寒胀满、热病汗不出、鼽衄眩仆、面浮肿、足胫寒、恶人与木音、喉痹龋齿、恶风鼻不闻、多卧善惊，皆阳明经气逆乱、经腑失和之兼症，脉动为辨证关键。", ["动"]], "22402": ["兼症", "原文'足跗上五寸骨间动脉'为冲阳穴处，脉动可候胃气。所列皮先寒、热病汗不出、口热痛、胃管痛、时寒热、齿龋痛、腹大不嗜食、振寒而欠、狂妄登高弃衣而走、足下缓失履、风水面胕肿，皆胃经实热或经气逆乱之兼症，动脉为胃气外应之征。", ["动"]], "22403": ["病机", "原文'若脉陷寒热身痛'，脉陷指局部脉动沉陷不起，主阳气内陷、经气不足。故见寒热身痛、唇干不得汗、毛发焦脱肉少气，为阳明经气亏虚、卫外不固；内有热不欲动摇、泄脓血、腰引少腹痛、暴惊狂言，为热郁于内、经气逆乱。脉陷为虚实夹杂之机。", ["陷"]], "22404": ["兼症", "本段述足阳明脉所发穴位主胫寒不得卧、胫疼足缓失履、湿痹足下热、不能久立，皆阳明经气痹阻、寒湿下注或虚热内生之兼症。原文未载脉象，故脉素为空，病机从症状推求，属经输主治范围。", []], "22405": ["预后", "原文'其赤坚勿攻，攻者死'，赤坚指犊鼻肿处色赤而坚硬，为热毒凝聚、气血壅结之象，不可妄攻，攻则伤正致败。又'诸肿节溃者死，不溃可疗'，以溃与不溃判预后吉凶。脉素取'坚'，示邪结坚牢，与赤坚之症相应，属预后判断。", ["坚"]], "22406": ["主病", "本段述阴鼎穴不可灸，主寒疝下至腹腠、膝腰痛如清水、大腹诸疝、按之下膝上伏兔中寒痛、腹胀满、痿厥少气。皆寒邪内结、阳明经气不行之病，原文未载脉象，故脉素为空，主病以寒疝、痿厥为核心。", []], "22407": ["其他", "本段仅载穴位定位'在膝上六寸起内，足阳明脉气所发，禁不宜灸'，属针灸禁灸之论，未涉脉象与病机。原文明言禁灸，示该处经气所发而不可火攻，故脉素为空，归类为其他。", []], "22408": ["其他", "此段为腧穴定位与灸禁主治，非论脉。述目下七分跷脉任脉足阳明之会，禁灸，误灸则眼下肿如拳、息肉长桃许大，乃至百日不见物。所列目不明、泪出、目眩、瞳子痒、远视䀮䀮、目𥆧动、口僻不能言，皆目系与阳明经气失养之候，与脉象无关，故脉象要素为空。", []], "22409": ["其他", "此段言目下一寸足阳明脉气所发之穴，灸七壮，主目痛、口僻、泪出、目不明。所主皆阳明经筋与目系病候，因穴在目下、脉气所发，故能治目痛及口面僻侧。原文未及脉象，纯为腧穴主治，故脉象要素为空，归其他类。", []], "22410": ["其他", "此段述侠鼻傍八分直瞳子、跷脉足阳明之会穴，主面目恶风寒、䪼肿痈痛、招摇视瞻、瘛疭、口僻、青盲、远视䀮䀮、目中淫肤白膜覆瞳子。病机为阳明与跷脉经气不利，风寒客于面目，目系失养。原文无脉象描述，脉象要素为空。", []], "22411": ["其他", "此段言侠口傍四分、跷脉手足阳明之会穴，灸三壮，主口缓不收、不能言语、手足痿躄不能行。病机在阳明经气不用，跷脉失约，故口缓、言语不能、四肢痿躄。原文为腧穴主治，未载脉象，脉象要素为空，归其他类。", []], "22412": ["其他", "此段述颐前下唇之下、足阳明任脉之会穴，主寒热凄厥鼓颔、癫疾呕沫、痓、口干、小便赤黄或不禁、消渴嗜饮、目瞑汗出、衄血不止、上齿龋。病机为阳明任脉失调，寒热错杂，气逆津伤。原文无脉象，脉象要素为空。", []], "22413": ["其他", "此段言耳下曲颊端陷者中、足阳明脉气所发穴，灸三壮，主颊肿、口急、颊车骨痛、齿不可用嚼。病机为阳明经气壅滞于颊车，故颊肿口急、骨痛碍嚼。原文纯属腧穴主治，未及脉象，脉象要素为空，归其他类。", []], "22414": ["其他", "此段述曲颔前一寸二分骨陷中动脉处，足阳明脉气所发，灸三壮。原文以「动脉」言穴处脉动应手，非诊脉之脉象；所主寒热、颈瘰疬、癫疾、口㖞、喘、痓、悸、口噤、厥、口僻、失欠、下牙痛、颊肿、恶寒、口不收、舌不能言、不得嚼，皆阳明经气逆乱之候。脉象要素取「动」。", ["动"]], "22415": ["其他", "此段言客主人下、耳前动脉下空下廉穴，灸三壮，主失欠、下齿龋、下牙痛、䪼肿、耳聋鸣、痓、口僻、耳中干底聤耳有脓。原文「耳前动脉」指穴旁脉动之处，非论病脉；所主为阳明少阳经气不利、耳窍壅滞之候。脉象要素取「动」，归其他类。", ["动"]], "22416": ["主病", "此段述人迎穴（天五会）位于颈大脉动应手处，为足阳明脉气所发，禁灸。原文以“阳逆霍乱”“阳逆头痛”“胸满不得息”“呼吸喘暍”为主病，皆因阳明经气上逆、气机壅塞所致。人迎为候五脏之气要穴，阳明多气多血，逆则胸满喘促，故列禁灸以防火上加火、气逆更甚。", []], "22417": ["主病", "此段述水突穴（水门）在颈大筋前、人迎下气舍上，属足阳明脉气所发。主“咳逆上气”“咽喉痈肿”“呼吸短气”“喘息不通”，皆阳明经气壅滞、痰热结于咽喉胸膈之候。穴近咽喉气道，故灸之可通阳明郁滞，使气降咽利而喘咳自平。", []], "22418": ["主病", "此段述气舍穴在颈直人迎侠天突陷中，足阳明脉气所发。主“咳逆上气”“瘤瘿气”“咽肿”“肩肿不得顾”“喉痹”，均属阳明经气郁结于颈项咽喉。瘤瘿、喉痹为气结痰凝，肩肿不得顾乃经气不利，灸此穴可疏阳明壅滞、散结利咽。", []], "22419": ["主病", "此段述俞府旁足阳明穴在巨骨下、俞府两旁各二寸陷中。主“胸胁支满”“喘逆上气”“呼吸肩息”“不知食味”，为阳明气逆、胸膈壅塞之候。肩息示喘甚抬肩，不知食味乃胃气不降、脾运受困，灸此可降逆宽胸、复阳明和降之职。", []], "22420": ["主病", "此段述气户下足阳明穴在气户下一寸六分陷中。主“胸胁支满”“咳逆上气”“呼吸多唾浊沫脓血”，乃阳明痰热壅肺、气逆络伤之候。浊沫脓血示热灼肺络、痰浊内蕴，胸胁支满为气机壅滞，灸此穴可宣通阳明、降气化痰排脓。", []], "22421": ["主病", "此段述库房下足阳明穴在库房下一寸六分陷中。主“胸胁支满”“咳逆上气”“多唾浊沫脓血”，兼“身体重”“皮肤不可近衣”“淫泺瘛疭不仁”，为阳明痰热壅肺兼经络气血痹阻之候。身体重、不仁、瘛疭示经气不畅、肌肤失养，灸此可通阳明、化痰通络。", []], "22422": ["主病", "此段述乳下足阳明穴在乳下一寸六分陷中。主“胸下满痛”“膺肿”“乳痈”“凄索寒痛不可按搔”，为阳明经气壅滞于胸膺乳房、气血结聚成痈之候。乳痈、膺肿示热毒壅结，寒痛不可按搔乃气血痹阻，灸此穴可疏阳明郁滞、消肿散结止痛。", []], "22423": ["主病", "此段述幽门旁足阳明穴在幽门傍各一寸半、去任脉二寸直四肋端。主“呕血”“肩息”“胁下痛”“口干”“心痛与背相引”“不可咳引肾痛”，为阳明气逆、血随气上兼经气牵引之候。呕血示胃络损伤，心痛彻背、咳引肾痛示经气贯膈牵涉，灸此可降逆和络。", []], "22424": ["主病", "原文未出脉名，仅言足阳明脉气所发，灸五壮主肠鸣相逐、不可倾侧、肩息唾血。阳明经气通于肠胃，经气失调则肠鸣相逐；不可倾侧、肩息为气逆不降、胸中壅塞之象；唾血则阳明热伤血络。此段以经穴主病为纲，非以脉象言病机，故脉象要素从缺。", []], "22425": ["主病", "原文未出脉名，言足阳明脉气所发，灸五壮主胁下积气结痛。阳明经气所过，若经气壅滞，则积气结于胁下而痛。此段以穴位所属经脉说明主治，非凭脉断病，故脉象要素为空。其病机在阳明经气不舒、气结胁下，与积气结痛相应。", []], "22426": ["主病", "原文未出脉名，言足阳明脉气所发，灸五壮主遗溺、腹胀善满、积气身肿。阳明经气主通降，经气失约则遗溺；气机壅滞则腹胀善满、积气；气不行水则身肿。此段以经穴主病言病机，未及脉象，故脉象要素从缺，主旨归主病。", []], "22427": ["主病", "原文未出脉名，言足阳明脉气所发，灸五壮主狂癫疾、吐舌。阳明经气上通于头面，经气逆乱、痰火扰神则发狂癫；吐舌为心神失守、舌络不收之象。此段以经穴主治说明病机，未出脉象，故脉象要素为空，主旨属主病。", []], "22428": ["主病", "原文未出脉名，言足阳明脉气所发，灸五壮主狂癫疾、吐舌。与上段同属阳明经穴主治，阳明经气逆乱、神机失用则狂癫吐舌。此段亦以经穴言主治，未及脉象，故脉象要素从缺，主旨归主病，病机在阳明气逆、神扰舌纵。", []], "22429": ["主病", "原文未出脉名，详列脐疝绕脐痛、时上冲心、胞络中痛、月水不以时休止、腹胀肠鸣、气上冲胸、冬月重感于寒则泄、疟振寒热盛狂言、脾胀四肢重等。此为足阳明经穴广主诸病，核心在阳明经气失调、寒凝气滞、冲逆上下，故脉象要素从缺，主旨归主病。", []], "22430": ["主病", "原文未出脉名，言足阳明脉气所发，灸五壮主腹中尽痛。阳明经气循腹而行，经气凝滞不通则腹中尽痛。此段以经穴主治言病机，未出脉象，故脉象要素为空，主旨属主病，病机为阳明经气痹阻、不通则痛。", []], "22431": ["主病", "原文未出脉名，言足阳明脉气所发，灸五壮主腹满痛、善烦、𤻊疝、偏枯、四肢不用、善惊。阳明经气失调，气滞则腹满痛；经气不达四肢则偏枯不用；神气不宁则善烦善惊；𤻊疝亦属经气下陷。此段以经穴主病言病机，未出脉象，故脉象要素从缺，主旨归主病。", []], "22432": ["主病", "原文未出脉名，仅言足阳明脉气所发之穴灸五壮，主少腹胀满痛引阴中、腰背中痛、腹中瘕、子门有寒、小便不通。此为阳明经气失调、寒凝下焦之病机，故取该穴灸之以温通经脉、散寒行气，属针灸主病条文，非脉诊内容。", []], "22433": ["主病", "原文未识脉名，述归来下穴动应手足阳明脉气，灸三壮，主肠中大热不安、腹有逆气、女子月水不利或闭塞、暴腹胀满、癃、身热、腹中绞痛、𤻊疝阴肿、乳难、子上抢心、胞不出、腰痛控睪等。此为阳明与冲任气血逆乱、寒热错杂之病机，取穴灸治以调气通经。", []], "22434": ["其他", "原文未出脉象，仅述手少阴脉所出之井穴位置，去爪甲如韭叶，冬三月宜灸之。此属经脉腧穴归经与灸法时宜的记述，说明井穴为经气所出之处，冬令宜灸以应闭藏之气，非论病机脉象，故归其他。", []], "22435": ["其他", "原文未识脉名，述手少阴脉所留之荥穴在手小指本节后陷中，直劳宫，春三月宜灸之。此为经脉腧穴归经与灸法时宜条文，说明荥穴为经气所留之处，春令宜灸以应生发之气，非脉诊病机内容，故归其他。", []], "22436": ["其他", "原文未出脉象，述手少阴脉所注之输穴在掌后兑骨之端陷中，一名兑冲、中都，夏三月宜灸之。此属经脉腧穴归经与灸法时宜记述，说明输穴为经气所注之处，夏令宜灸以应长养之气，非论病机脉象，故归其他。", []], "22437": ["其他", "原文未识脉名，仅述手少阴脉所行之经穴在掌后一寸半或一寸。此为经脉腧穴归经条文，说明经穴为经气所行之处，未涉及病机、主病或症候，亦无脉象描述，故归其他。", []], "22438": ["其他", "原文未出脉象，述手少阴脉所入之合穴在肘内廉节后，一名曲节，秋三月宜灸之。此属经脉腧穴归经与灸法时宜记述，说明合穴为经气所入之处，秋令宜灸以应收敛之气，非论病机脉象，故归其他。", []], "22439": ["主病", "原文未识脉名，述掌后脉中去腕半寸穴灸三壮，主十二痫、失喑不能言、凄凄寒咳、吐血、气惊、心痛。此为心经及心包经气逆乱、痰瘀闭阻神明之病机，故取掌后脉动处灸之以通心气、宁神定惊，属针灸主病条文。", []], "22440": ["主病", "原文以腋下筋间动脉为手少阴脉气所发，灸之主治心腹痛、干呕哕；其动病则嗌干心痛、渴而欲饮、臂厥，所生病则目黄胁痛、臑臂内后廉痛、掌中热痛。动脉在此标示心脉气血搏动之处，故主心与心包络之病，症候皆循手少阴经所过而发。", ["动"]], "22441": ["病机", "此段论手少阴心脉为五脏六腑之大主、精神之舍，其脏坚固，邪不能害，害之则心伤神去而死；诸邪在心者皆在心包络。原文未及具体脉象，而阐明心不受邪、病在外经脉而脏不病之机理，故取掌后兑骨之端以治外经之病。", []], "22442": ["其他", "原文定位手小指端去爪甲一分为手太阳脉所出之井穴，冬三月宜灸。全段言井穴部位与灸时，未涉脉象形态，故脉象要素为空；其主旨属经穴灸法，非主病、病机之论，列于其他。", []], "22443": ["其他", "原文指手小指外侧本节前陷中为手太阳脉所留之荥穴，春三月宜灸。段中只述荥穴位置与施灸季节，无脉象描述，故脉象要素为空；主旨为经穴灸法，不归主病或病机。", []], "22444": ["其他", "原文言手小指外侧本节后陷中为手太阳脉所注之输穴，夏三月宜灸。全段为输穴定位与灸时，未提脉象，故脉象要素为空；内容属经穴灸法，列于其他。", []], "22445": ["其他", "原文定位手外侧腕前起骨下陷中为手太阳脉所过之原穴。段中仅述原穴部位，无脉象形态描述，故脉象要素为空；主旨为经穴部位，不涉主病、病机，归入其他。", []], "22446": ["其他", "原文指手外侧腕中兑骨下陷中为手太阳脉所行之经穴。全段只言经穴位置，未及脉象，故脉象要素为空；属经穴定位内容，非脉诊主病之论，列于其他。", []], "22447": ["其他", "原文述肘内大骨外去肘端五分陷中、屈肘乃得为手太阳脉所入之合穴，秋三月宜灸。段中无脉象描述，故脉象要素为空；主旨为合穴定位与灸时，归入其他。", []], "22448": ["主病", "本段为腧穴主治条文，非脉诊论述。文中\"动应手\"指该穴处有脉气搏动应指，属手太阳脉气所发，非病脉。所主为耳聋无闻、颊痛肿、喉痛喑不能言、肩痛引项、汗出、偏耳鸣等症，皆手太阳小肠经循行部位及脉气失调所致，与脉象病机无直接关联。", []], "22449": ["主病", "本段述手太阳脉气所发腧穴主治，\"陷者中\"言取穴部位，非脉象。所主胸胁支满、抢心咳逆、肩重肘臂痛不可举，为手太阳经气不利、上逆犯胸胁所致。原文未及脉象，故脉象要素为空，主旨归主病，不可强解为某脉主某病。", []], "22450": ["主病", "本段为手足太阳阳维跷脉之会穴主治，\"举臂取之\"言取穴姿势，非脉诊。所主寒热、肩肿引胛中臂酸、颈历适、肩痛不可举臂，属阳维与太阳经气失调、寒热错杂之候。原文无脉象描述，脉象要素从缺，主旨归主病。", []], "22451": ["其他", "本段属心包经穴数考订，言心包为心脉之旁，两傍一十六穴，并通按本经原九穴、少天池一穴入胆、左右共十八穴。全段为经络腧穴数目之校勘说明，未涉脉象与病机，故脉象要素为空，主旨归其他，不可附会为脉诊内容。", []], "22452": ["其他", "本段述手中指端中冲穴为手心主脉所出之井穴，\"冬三月宜灸之\"言灸法时宜，非脉象。原文未及脉象与病机，仅明井穴位置、脉气所出及施灸季节，故脉象要素为空，主旨归其他，属针灸取穴治法类条文。", []], "22453": ["其他", "本段述掌中央劳宫穴为手心主脉所留之荥穴，\"动脉\"指该处有脉搏动应手，属取穴标志，非病脉。\"春三月宜灸之\"言灸法时宜。原文虽见\"动脉\"字样，然系言穴位处脉气搏动，非诊病脉象，故仅取\"动\"字，主旨归其他。", ["动"]], "22454": ["其他", "本段述掌后两筋间大陵穴为手心主脉所注之输穴，\"陷者中\"言取穴凹陷处，\"夏三月宜灸之\"言灸法时宜。原文未及脉象与病机，仅明输穴位置、脉气所注及施灸季节，故脉象要素为空，主旨归其他，属针灸腧穴类条文。", []], "22455": ["其他", "本段述掌后三寸两筋间间使穴为手心主脉所行之经穴，\"陷者中\"言取穴部位，非脉象。原文未及脉象与病机，仅明经穴位置及脉气所行，故脉象要素为空，主旨归其他，属针灸经络腧穴类条文，不可强解为脉诊病机。", []], "22456": ["其他", "本段为腧穴定位与灸法宜忌，述肘内廉陷者中屈肘得之，为手厥阴心包经之合穴，秋三月宜灸。原文未出脉名脉象，故无从论脉所主病机；其“脉之所入”指经气流注，非诊脉之脉，不可据以推断病机，仅属针灸取穴内容。", []], "22457": ["主病", "本段述大陵穴在掌中动脉处，灸三壮，主热病发热满而欲呕哕、怵惕胸胁痛、咳满溺赤、衄血呕吐、嗌中痛、掌中热、善怒善悲善笑不休、少腹积聚、小儿口中腥臭、黄瘅目黄等。掌中动脉为手厥阴所过，故其主病多归心包与胸胁、神志、血热之候，非以脉象推断病机。", ["动"]], "22458": ["其他", "本段述足心陷者中屈足卷趾宛宛处为足少阴井穴，冬三月宜灸。原文未载脉名脉象，只言“足少阴脉之所出”，指经气所出之井穴，非脉诊之象，故不能据此论病机，属腧穴灸法内容。", []], "22459": ["其他", "本段述足内踝前起大骨下陷中为足少阴荥穴，春三月宜灸。原文未识别脉名，仅言“足少阴脉之所留”，指经气留止之处，非脉象描述，故无脉可辨，亦不能推演所主病机，属针灸取穴与灸时宜忌。", []], "22460": ["其他", "本段述足内踝后跟骨上动脉陷中为足少阴输穴，夏三月宜灸。文中“动脉”指可触知之搏动处，用以定穴，非论脉象主病；虽见动脉字样，仍属腧穴定位，不能据以推断病机，故列其他。", ["动"]], "22461": ["其他", "本段述足内踝上二寸陷中，一名伏白、一名昌阳，为足少阴经穴。原文未出脉名脉象，只言“足少阴脉之所行”，指经气所行之处，非诊脉之象，故无从论其所主病机，属腧穴定位内容。", []], "22462": ["其他", "本段述膝内辅骨之后、大筋之下、小筋之上，按之应手、屈膝而得，为足少阴合穴，秋三月宜灸。原文未载脉名脉象，“按之应手”是取穴手法，非脉象，故不能据此论病机，属针灸腧穴内容。", []], "22463": ["主病", "本段述足内侧踝前大骨下陷中灸三壮，主不嗜食、心如悬、善怒、恐如人将捕、少气不足以息、心痛如刺、厥心痛、胸中寒脉代时不至、上重下轻、少腹胀、咳唾有血、喉痹、癃疝、石水、女子不字、阴暴出、淋漏、精溢、胫酸、寒热消渴、黄瘅、小儿脐风、癫疾洞泄等。其中“脉代时不至”点出胸中寒致脉气不能接续，故见代脉，主心阳不振、气血虚寒之候。", ["代"]], "22464": ["主病", "本段以足内踝后动脉陷中为施灸部位，动脉搏动处即脉气所发之所。原文列久疟咳逆、心闷不得卧、呕甚热多寒少、欲闭户而处、寒厥足热、肾胀、消瘅善噫、心痛如锥刺等症，皆属少阴肾脉经气逆乱、阴阳不相顺接所致。动脉应手说明经气尚存、病在经脉气机失调，故灸之以通阳调气，非言某脉主某病之常法。", ["动"]], "22465": ["主病", "本段取足内踝下阴跷脉所生处及大趾上动脉，动脉为脉气发动之象。原文所主热痛、足寒清多汗、目痛引脊、少腹偏痛、呕瘛疭、视昏嗜卧、卒疝、女子不下月水、阴挺出等，涉及阴阳跷脉失调、少阴经气逆乱。动脉应手表明经气未绝，灸补然谷、太谿以调跷脉，故列诸症以明其主治范围。", ["动"]], "22466": ["主病", "本段未识脉名，原文仅言足少阴脉气所发之处，灸五壮主咳逆上气、喘不得息、呕吐胸满、不得饮食。此为少阴肾脉经气上逆，影响肺胃所致。取穴于巨骨下璇玑旁，属肾脉气所发，说明病机在少阴经气不降、冲逆犯肺犯胃，故以灸法温通经气、降逆平喘，非凭脉象断病。", []], "22467": ["主病", "本段未识脉名，原文指出足少阴脉气所发，灸五壮主咳逆上气、涎出多唾、呼吸喘悸、坐不得安。此为少阴肾气上逆，水饮随经上泛，肺失肃降，故咳喘多唾、悸而不得安坐。取穴于输府下，属肾脉气发之处，灸以温肾降逆、化饮平喘，说明病机重在少阴经气上逆而非脉象本身。", []], "22468": ["主病", "本段未识脉名，原文言足少阴脉气所发，灸五壮主胸满咳逆、喘不得息、呕吐烦满、不得饮食。此为少阴肾脉经气上逆，犯于胸膈，肺胃失降，故胸满咳喘、呕烦不食。取穴于或中下，属肾脉气发之所，灸之温通少阴经气以平冲逆，说明病机为少阴经气上逆、肺胃不降，非据脉象断病。", []], "22469": ["主病", "本段未识脉名，原文称足少阴脉气所发，灸五壮主胸胁支满、痛引膺、不得息、闷乱烦满、不得饮食。此为少阴肾脉经气逆于胸胁，气机壅滞，肺失宣降，故支满引痛、闷乱不食。取穴于神藏下，属肾脉气发之处，灸以通经降逆、宽胸利膈，说明病机在少阴经气壅逆胸胁，非凭脉象。", []], "22470": ["主病", "本段未识脉名，原文言足少阴脉气所发，灸三壮主胸胁支满、膈逆不通、呼吸少气、喘息不得举臂。此为少阴肾脉经气上逆，膈间气机不通，肺失肃降，故胸胁支满、呼吸少气、喘而臂不能举。取穴于神封下，属肾脉气发之所，灸以温通少阴、降逆宽膈，说明病机为少阴经气逆于膈上。", []], "22471": ["主病", "本段未识脉名，原文称冲脉足少阴之会，灸五壮主胸胁背相引痛、心下溷溷、呕吐多唾、饮食不下、善哕支满、数咳善忘、泄有脓血、呕沫吐涎、少腹坚、女子心痛逆气吐食不下。此为冲脉与少阴经气逆乱，上冲胸胁、下扰少腹，脾胃升降失司，故见诸症。取穴于巨阙旁，灸以调冲降逆，说明病机在冲脉少阴之气逆乱，非凭脉象。", []], "22472": ["主病", "此段为腧穴主治，非脉诊原文，未载脉象。所述失欠、口㖞僻不端、食饮善呕、不得言、舌下肿、舌纵㖞戾，皆属足少阴与冲脉会穴所主，病机在肾经与冲脉经气失调、舌本不利、胃气上逆，故见口舌与饮食诸症。", []], "22473": ["主病", "原文为腧穴主治，无脉象可辨。身寒热痎疟、心满气逆，说明冲脉足少阴之会穴可调寒热往来与胸膈气逆，病机涉及疟邪客于少阳、冲脉气机上逆、心下满闷，故取该穴灸治以通调经气。", []], "22474": ["主病", "此段未载脉象，属腧穴主治。痓脊强、口不可开、多唾、大便难，为冲脉足少阴经气不利、筋脉失养、津液输布失常所致；妇人胞中恶血内逆满痛，则示冲脉为血海、与胞宫相通，瘀血内阻而气逆作痛。", []], "22475": ["主病", "原文为腧穴主治，无脉象。腹中积聚时切痛，说明冲脉足少阴之会穴主治积聚类病，病机为寒凝气滞、瘀血内结、冲脉气血运行不畅，故积聚时作切痛，灸该穴以温通冲脉、散结止痛。", []], "22476": ["主病", "此段未言脉象，为腧穴主治。心大坚、大肠寒中、大便干、腹中切痛，提示寒邪内中大肠、传导失司而便干，冲脉与少阴经气不通则腹中切痛；心大坚或指心下痞硬，属寒凝气滞、腑气不通之候。", []], "22477": ["主病", "原文为腧穴主治，未载脉象。少腹有热、大便难，说明该冲脉足少阴会穴可清少腹之热、通调大便，病机为热结少腹、津液受灼、肠道失润，故取此穴灸治以调冲脉、泄少腹郁热。", []], "22478": ["主病", "此段无脉象，属腧穴主治。脐下积聚、疝瘕、胞中有血、肠澼泄切痛、振寒、大腹石水、肾痛，皆示冲脉足少阴经气凝滞、水寒内结、瘀血停胞，故见积聚疝瘕、泄利切痛、振寒及石水等症，灸此穴以温通散结。", []], "22479": ["妇人", "原文为腧穴主治，未载脉象。月水不通、奔气上下引腰脊痛，明示该穴（又名胞门、子户）主妇人经闭与冲气上逆，病机为冲脉气血瘀阻、胞门不通、气逆循腰脊而痛，故灸此冲脉足少阴之会以通经降逆。", []], "22480": ["其他", "本段为腧穴条目，述阴维、阴关穴位于气穴下一寸，为冲脉与足少阴之会，灸五壮，主女子赤淫、男子精溢、阴上缩。原文未出脉象，所主之病从冲脉、少阴经气失调理解：冲任不固则女子赤淫，少阴失藏则男子精溢、阴器上缩。属针灸主治范围，非脉诊病机之论。", []], "22481": ["其他", "本段述下极穴在大赫下一寸，冲脉足少阴之会，灸五壮，主少腹满、小便难、阴下纵、卵中痛。原文无脉象，病机从冲脉与少阴经气不利着眼：冲脉失调则少腹满，少阴气化不行则小便难，阴器失约则下纵、卵中痛。属腧穴主治，非脉象主病之文。", []], "22482": ["其他", "本段述尾翳（𩩲骭）在蔽骨下五分，为任脉之别，不可灸刺，一云灸五壮，主心中寒胀满、不得息、唾血、胸中痛、心痛不可按、善哕、心疝、面赤、喘息、咳呕等。原文无脉象，诸症从任脉之别与心胸阳气痹阻理解，甄权谓宜针不宜灸，属腧穴主治与治法宜忌。", []], "22483": ["其他", "本段述鸠尾下一寸穴，任脉气所发，灸五壮，主心痛不可按、烦心、热病、腹满暴痛、恍惚不知人、瘛疭、心疝、唾血、霍乱、发狂妄言、狐疝、惊悸少气等。原文无脉象，病机从任脉气发与心神被扰、气机逆乱理解，症候繁杂，属腧穴主治条目，非脉象主病。", []], "22484": ["病机", "本段述巨阙下一寸五分穴，为足阳明、手太阳、任脉之会，灸五壮，主寒中伤饱、食饮不化、䐜胀、心腹胸胁支满。原文特出「脉虚则生百病」，以脉虚统括诸症，说明中焦脾胃气虚、运化失职，故食饮不化、胀满由生；虚则百病丛生，是本段以脉虚言病机的关键。", ["虚"]], "22485": ["其他", "本段述太仓（中脘）在上管下一寸，为手太阳、少阳、足阳明所生，任脉之会，灸七壮，主腹胀不通、心大坚、胃胀、霍乱、溢饮、寒中伤饱、食饮不化、目黄、贲豚、积聚、蛔咬等。原文无脉象，诸症从胃腑气机壅滞、水饮积聚、寒热错杂理解，属腧穴主治，非脉诊之论。", []], "22486": ["其他", "本段述建里下一寸穴，为太阴、任脉之会，灸五壮，主饮食不化、入腹还出、六腑谷气不转；甄权云主小便赤、腹坚硬，孕妇不可灸。原文无脉象，病机从太阴脾运失职、六腑传化不行理解：谷气不转则食入还出，水湿停蓄则腹坚硬、小便赤。属腧穴主治与灸禁。", []], "22487": ["其他", "本段述下管下一寸、脐上一寸穴，任脉气所发，灸三壮，主痓、脊强、里急、腹中拘急痛；甄权云主水病腹肿，孕妇不可灸。原文无脉象，病机从任脉与督脉经气拘急、水气内停理解：经气不利则脊强里急腹痛，水气不化则腹肿。属腧穴主治与灸禁，非脉象主病。", []], "22488": ["主病", "本段为任脉冲脉会穴（少关/横户）灸法主治，非脉象论述。原文列“水胀水气行皮中”“惊不得眠”“阴疝引睪”“月水不下”“绝子阴痒”“贲豚上䐜”等，皆属任冲失调、水气内停、下焦寒凝之病机，故以主病归类，脉象要素无从取。", []], "22489": ["主病", "本段记脐下一寸半穴（脖胦/下肓）灸法，主“少腹疝卧善惊”“下热小便赤气痛状如刀搅”。少腹疝痛属任脉下焦气机凝滞，热郁则小便赤、痛如刀搅，惊则神气不宁。原文未涉脉象，故脉象要素为空，主旨归主病。", []], "22490": ["主病", "本段述脐下二寸丹田/命门穴灸法主治，涵盖“脐疝绕脐痛”“三焦胀水腹大”“气癃小便黄”“虚则遗溺”“贲豚上䐜”“恶露不止”等。丹田为任脉要穴，主下焦元气与三焦水道，虚则遗溺、实则胀满癃闭，皆本穴所主病候，原文无脉象描述。", []], "22491": ["主病", "本段记脐下三寸关元（次门）灸法，主“寒热石水痛引胁下胀”“气癃尿黄”“转胞不得尿”“贲豚寒热”“溺血”“暴疝痛”“女子绝子衃血在内不下”。关元为任脉足三阴之会，主下焦寒热、水气、血结诸病，原文未及脉象，故脉象要素空。", []], "22492": ["主病", "本段述横骨上中极下一寸毛际穴灸法，主“膀胱小便难”“脚屈转胞不得尿”“妇人赤白淫阴中干痛”“水胀满尿涩”“癫疾不呕沫”。穴当任脉足厥阴之会，主膀胱气化不利与肝经湿浊下注，原文无脉象，脉象要素从缺。", []], "22493": ["主病", "本段记会阴（屏翳）穴灸法，主“痹小便难窍中热”“实则腹皮痛虚则痒搔”“痔与阴相通者死”“女子血不通”“男子阴端寒上冲心中”。会阴为任脉别络冲督之会，主前后二阴及冲任气血病，原文未述脉象，故脉象要素为空。", []], "22494": ["主病", "本段述颔下结喉上舌本下穴（本池）灸法，主“舌下肿难以言舌纵涎出”“咳逆少气喘息呕沫”“噤龂上气胸满”。穴属阴维任脉之会，主舌本与胸肺气逆之病，原文无脉象描述，脉象要素从缺，主旨归主病。", []], "22495": ["主病", "本段记颈结喉下五寸穴（玉户）灸法，主“咳上气喘暴喑不能言”“舌下侠青缝脉颈有大气喉痹咽中干急不能息”“寒热颈肿肩痛胸满”“衄气鲠心痛瘾疹”。穴为阴维任脉之会，主咽喉颈胸气逆与寒热诸候，原文未及脉象，脉象要素空。", []], "22496": ["主病", "本段为任脉腧穴定位与灸法主治，未言脉象。天突居胸骨上窝，任脉气所发，灸五壮主治胸满痛、喉痹咽痈、水浆不下，病机在任脉气机壅滞、咽喉胸膈不利，故取局部腧穴以通调任脉、宣散壅结。", []], "22497": ["主病", "本段述璇玑穴定位灸法及主治，无脉象可辨。穴在璇玑下一寸陷中，属任脉气所发，主胸胁支满痛引胸中、咳逆上气、喘不能言，乃任脉与胸中气机郁滞、肺失宣降所致，灸之可温通任脉、宽胸降逆。", []], "22498": ["主病", "本段为华盖穴定位灸法主治，未涉脉象。穴在华盖下一寸六分陷中，任脉气所发，主胸胁支满、痹痛骨疼、饮食不下、呕逆上气、烦心，病机属任脉气滞、胸膈不利、胃气上逆，灸五壮以通任脉、调畅胸膈。", []], "22499": ["主病", "本段述玉英（玉堂）穴定位灸法主治，无脉象。穴在紫宫下一寸六分陷中，任脉气所发，主胸中满不得息、胁痛骨疼、喘逆上气、呕吐烦心，为任脉气机壅塞、肺胃气逆之候，灸之通调任脉、降逆宽胸。", []]});